\section{Introduction}
\subsection{Model problem}

For any positive constant $b$ and $x'=(x_1,\dots,x_{N-1}) \in \BR^{N-1}$ ($N\geq 2$), let us set
\begin{equation}\label{dfn:Omega}
\begin{aligned}
  	\Omega_+ &=\{x=(x',x_N)\in\BR^N:  x_N>0\}, \\
	\Omega_- &=\{x=(x',x_N)\in \BR^N: -b<x_N<0\},\\
 	\Gamma & =\{x=(x',x_N)\in\BR^N: x_N= 0\},\\
  	S & =\{x=(x',x_N)\in\BR^N: x_N= -b\}.
\end{aligned}
\end{equation}
Let $\BR_+=(0,\infty)$ and $\bn=(0,\cdots,0,1)^\top \in \BR^N.$
This paper concerns the following model problem arising from the study of the sharp interface problem of the gas-liquid two-phase flows in unbounded domains (see  Figure \ref{Fig:Omega2}):
 \begin{equation}\label{eql:1}
	\left\{ \begin{aligned}
		&\pd_t\rho_+ + \gamma_{1+}\, \dv \bv_+=f_+
		&&\quad&\text{in} &\quad \Omega_+ \times \BR_+, \\
		&\gamma_{1+}\pd_t\bv_+ - \DV\bT_+(\bv_+,\gamma_{2+}\rho_+)  = \bg_+
		&&\quad&\text{in}& \quad \Omega_+ \times \BR_+, \\
		&\gamma_{1-}\pd_t\bv_-  - \Di\bT_-(\bv_{-},\fp_-) = \bg_-
		&&\quad&\text{in}& \quad \Omega_- \times \BR_+, \\
		& \di \bv_- = g_d=\di \fg_d
		&&\quad&\text{in}& \quad \Omega_- \times \BR_+, \\
		&\big(\bT_+(\bv_+,\gamma_{2+}\rho_+)- \bT_-(\bv_-,\fp_-)\big)\bn
		= \bh
		&&\quad&\text{on}& \quad \Gamma \times \BR_+,\\
		&\bv_{+}=\bv_{-}
		&&\quad&\text{on}& \quad \Gamma \times \BR_+,  \\
		& \bv_-=0
		&&\quad&\text{on}& \quad   S \times \BR_+, \\
		&(\rho_+, \bv_+)|_{t=0} = (\rho_{+,0}, \bv_{+,0})
		&&\quad&\text{in}& \quad \Omega_+, \\
		&\bv_-\big|_{t=0}=\bv_{-,0}
		&&\quad&\text{in}& \quad \Omega_-.
	\end{aligned}
	\right.
\end{equation}

In \eqref{eql:1}, the constant parameters $\gamma_{1\pm},$ $\gamma_{2+},$ $\mu_{\pm},\nu_+>0,$ and the stress tensors in \eqref{eql:1} are given by
\begin{align*}
\bT_{\pm}(\bv_{\pm},\pi_{\pm}) &=\bS_{\pm}(\bv_{\pm})  -\pi_{\pm}\bI,\\
	\bS_+(\bv_+) &= \mu_+ \bD(\bv_+)  + (\nu_+ - \mu_+)\di\bv_+\bI ,\\
	\bS_-(\bv_-) &= \mu_- \bD(\bv_-),\quad  \bD(\bv_\pm) = \nabla\bv_\pm + (\nabla\bv_\pm)^\top.
\end{align*}
In addition, $\dv \bv = \sum_{j=1}^N \pd_{x_j}v_j$ for $\pd_{x_j}=\pd/\pd x_j,$
the $(i,j)$th entry of the matrix $\nabla \bu$ is $\pd_{x_i} u_j,$ 
$\bI$ is the $N\times N$ identity matrix, 
$\bM^\top$ is the transposed matrix of $\bM=[M_{ij}],$
$\DV \bM$ denotes an $N$-vector of functions 
whose $i$-th component is $\sum_{j=1}^N \pd_{x_j} M_{ij}.$

Furthermore, the system \eqref{eql:1} can be regarded as the linearized model of the free boundary value problem of the compressible-incompressible Navier-Stokes equations in unbounded domains in view of the \emph{Lagrangian} coordinates (see Appendix \ref{app:non}).


