\subsection{Brief review of the sharp interface problem}
The sharp interface problem is one of fundamental models describing the interfacial phenomena.
For the motion of the viscous fluids, there are a lot of literature on the mathematical theory of one-phase or two-phase flows. To our knowledge, the first breakthrough on the mathematical theory of the sharp interface problem of viscous fluids is due to Solonnikov \cite{Sol1977}
where the author used Lagrangian coordinates and proved the local well-posedness of the one-phase incompressible Navier-Stokes equations in bounded domains within H\"older continuity (see \cite{Sol1987} for the framework of Sobolev spaces).

Another well-known problem on the one-phase incompressible flows is so-called the \emph{viscous surface wave} problem which could trace back to the works \cite{Beale1981, Beale1983} by Beale. The viscous surface wave problem has been revisited by Guo and Tice in a series of works \cite{GT2013b,GT2013a,GT2013c} where the authors developed new high-order energy method (also see the recent results \cite{Gui2021,Wang2020} in this direction).

Based on the $\mathcal{R}$-boundedness theory in Weis' work \cite{Weis2001}, Shibata and Shimizu \cite{shibata2007,ShiShi2008} established a more general approach to handling the solutions of the one-phase incompressible Navier-Stokes in the class of the maximal $L_p$-$L_q$ regularity provided with the indices $p,q\in (1,\infty).$ Very recently, the maximal $L_1$ regularity for the free boundary value problem has been investigated in \cite{DHMT2020,OS2024,SW2024}.

All the aforementioned methods on the incompressible viscous flows can be applied to study the one-phase compressible Navier-Stokes equations with free boundary value conditions. However, due to the more complicated structure of the compressible Navier-Stokes equations, it is not immediate to solve the global well-posedness issue just in view of the results on the incompressible flows. For the interface problem of the compressible Navier-Stokes equations, we refer to the works \cite{DT2023, HL2021,SZ2023,Zaja1993,Zaja1994} and the references therein.
\medskip

For the mathematical study of viscous two-phase problem, the incompressible-incompressible Navier-Stokes problem has attracts significant attention. Assuming the domains are smooth and bounded, the first attempt is due to Tanaka \cite{Tanaka1993} on the global solvability of the model describing the motion of two immiscible inhomogeneous viscous liquids in $L_2$ type Sobolev–Slobodetskii spaces with the capillarity taken into account (also see \cite{Denisova2014}). The extension to the $L_p$ framework, we refer to more recent works on the bounded domains \cite{Pruss2011,PruS2016,SSZ2020}. Furthermore, the progress in the case of unbounded domains is much more involved. In this direction, we refer to the recent works \cite{Saito2024,WTK2014}. Besides, we refer to the works \cite{Deni1997,JTW2016a,KSS2016,Tani1984} for the gas-gas two-phase problem.
\medskip

Compared with the liquid-liquid two-phase problem, there are only a few of works on the gas-liquid two-phase problem. 
Denisova \cite{Denisova14} firstly obtained the local solvability in Sobolev-Slobodetskii space whenever two-phase flows occupy the bounded and exterior domains respectively. Then the more general $L_p$ theory has been developed by Shibata et al. in \cite{Kubo2021, KSS2014,Shibata17} where the key step is to study the resolvent problem of the linearized gas-liquid two-phase model in $\BR^N_+ \cup \BR^N_-$ for $N\geq 2$. 
In this paper, we study the problem \eqref{eql:1} in the unbounded reference domain $\Omega_{+} \cup \Omega_-$ with the fixed bottom $S,$ which reflects the feature of the compressible flow and the viscous surface wave problem.   

\subsection{Main result}



The main goal of this paper is to find the solution $(\rho_{+}, \bv_{\pm},\fp_{-})$ of \eqref{eql:1} in the class of the so-called \emph{maximal $L_p$-$L_q$ regularities} provided with suitable initial data $(\rho_{+,0}, \bv_{\pm,0})$ and source terms $(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh).$ To this end, we introduce the following functional spaces
\footnote{See Subsection \ref{subsec:fs} for the definitions of the standard functional spaces and the operator $\Lambda^{1/2}_{\gamma}$ in this paper.}.
\begin{dfn} \label{def:FD}
Let $1<p,q<\infty$ and $\gamma>0.$
For $\Omega_\pm$ in \eqref{dfn:Omega}, we denote $\dOm=\Omega_+ \cup \Omega_-.$ 
\begin{itemize}

\item We write 
$(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \in \CF_{p,q,\gamma}(\dot \Omega)$
if $g_d=\di \fg_d$ and the following regularity assumptions hold 
\begin{gather*}
f_+ \in L_{p,\gamma}\big(\BR; H^1_q(\Omega_{+})\big), \,\,\,
\Bg_\pm \in L_{p,\gamma}\big(\BR; L_q(\Omega_{\pm})^N\big), \\
g_d\in  L_{p,\gamma}\big(\BR; H^1_q(\Omega_-)\big) 
\cap H^{1\slash 2}_{p,\gamma}\big( \BR; L_q(\Omega_-)\big), \,\,\,
\fg_d \in H^1_{p,\gamma}\big(\BR; L_q(\Omega_-)^N\big),\\ 
\bh \in  L_{p,\gamma}\big(\BR; H^1_q(\dOm)^N\big) 
\cap H^{1\slash 2}_{p,\gamma}\big( \BR; L_q(\dOm)^N\big).
\end{gather*}
Moreover, we set 
\begin{equation*}
\begin{aligned}
&\|(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \|_{\CF_{p,q,\gamma}(\dot \Omega)}\\
=& \| e^{-\gamma t} f_+\|_{L_p(\BR; H^1_q(\Omega_+))}   
+\| e^{-\gamma t}\bg_+ \|_{L_p(\BR; L_q(\Omega_{+}))}
+\| e^{-\gamma t}\bg_- \|_{L_p(\BR; L_q(\Omega_{-}))}\\
&+\| e^{-\gamma t} g_d\|_{L_p(\BR; H^1_q(\Omega_-))} 
+\| e^{-\gamma t} \Lambda_{\gamma}^{1\slash 2}  g_d\|_{L_p(\BR; L_q(\Omega_-))} 
+ \| e^{-\gamma t} \pd_t \fg_d\|_{L_p(\BR; L_q(\Omega_-))}\\
 &+\| e^{-\gamma t} \bh\|_{L_p(\BR; H^1_q(\dOm))}
+\| e^{-\gamma t} \Lambda_{\gamma}^{1\slash 2} \bh\|_{L_p(\BR; L_q(\dOm))}.
\end{aligned}
\end{equation*}

\item For any given $(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh)$ in $\CF_{p,q,\gamma}(\dot \Omega),$
we say $(\rho_{+,0}, \bv_{+,0},\bv_{-,0}) \in \CD_{p,q}(\dOm)$ if 
\begin{equation*}
    \rho_{+,0} \in H^1_q(\Omega_+), \,\,\,\bv_{+,0} \in B^{2-2/p}_{q,p}(\Omega_+)^N 
    \,\,\,\text{and}\,\,\,\bv_{-,0} \in B^{2-2/p}_{q,p}(\Omega_-)^N
\end{equation*}
satisfying the following compatibility conditions:
\begin{equation}\label{eq:1.4}
\begin{aligned}
& \dv \bv_{-,0}=g_d|_{t=0}\,\,\,\text{in}\,\,\,\Omega_-,
\quad (\bv_{-,0},\nabla \varphi)_{\Omega_-} =(\fg_{d}|_{t=0},\nabla \varphi)_{\Omega_-},
\,\,\,\forall \,\,\varphi \in  H^1_{q',\Gamma}(\Omega_-),\\
&\CT_{\bn} \Big( \big(\mu_+ \bD(\bv_{+,0})-\mu_- \bD(\bv_{-,0}) \big)\bn \Big) \Big|_{\Gamma} =\CT_{\bn} (\bh|_{t=0})|_{\Gamma},\quad
(\bv_{+,0}-\bv_{-,0})\big|_{\Gamma}=0,\quad
\bv_{-,0}|_{S}=0,  
\end{aligned}
\end{equation}
where 
\begin{equation}\label{def:proj}
    \CT_{\bn} \fh = \fh-(\fh \cdot \bn) \bn
\end{equation}
denotes the projection into the tangent space orthogonal to the normal vector $\bn.$ In addition, we also write 
\begin{equation*}
\|(\rho_{+,0}, \bv_{+,0},\bv_{-,0})\|_{\CD_{p,q}(\dOm)} 
= \|\rho_{+,0}\|_{H^1_q(\Omega_+)} 
+\sum_{\fs \in \{+,-\}}\|\bv_{\fs}\|_{B^{2-2/p}_{q,p}(\Omega_\fs)}.
\end{equation*}
\end{itemize}
\end{dfn}

With the notations in Definition \ref{def:FD}, we state the following main result of this paper.
\begin{thm}[Maximal $L_p$-$L_q$ regularity]\label{thm:mr}
Let $N\geq 2$ and $1<p,q<\infty$ with $2/p+N/q\not=1$ or $2.$ Then there exist positive constants $\gamma_0$ and $C$ such that the following assertions hold true.
\begin{itemize}
\item (Existence) 
Let $(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \in \CF_{p,q,\gamma_0}(\dot \Omega)$
and $(\rho_{+,0}, \bv_{+,0},\bv_{-,0}) \in \CD_{p,q}(\dOm).$ Then there exists a solution $(\rho_+, \bv_{+}, \bv_{-}, \fp_-)$ of the system \eqref{eql:1} satisfying 
\begin{equation}\label{ss:thm1}
\begin{aligned}
\rho_+ \in H^1_{p,\gamma_0} \big(\BR_+; H^1_q(\Omega_+)\big),\quad
\fp_- \in L_{p,\gamma_0} \big(\BR_+; \wh H^1_q(\Omega_{-})\big),\\ 
\bv_\pm \in L_{p,\gamma_0} \big(\BR_+; H^2_q(\Omega_{\pm})^N\big)
\cap H^1_{p,\gamma_0} \big(\BR_+; L_q(\Omega_\pm)^N\big).
\end{aligned}
\end{equation}
Moreover, there holds
\begin{equation*}
\CN_{p,q,\gamma_0}(\rho_+,\bv_{+}, \bv_{-}, \fp_-) \leq 
C\big(  \|(\rho_{+,0}, \bv_{+,0},\bv_{-,0})\|_{\CD_{p,q}(\dOm)}
+\|(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \|_{\CF_{p,q,\gamma_0}(\dot \Omega)} \big)
\end{equation*}
with 
\begin{equation*}
\begin{aligned}
\CN_{p,q,\gamma_0}(\rho_+,\bv_{+}, \bv_{-}, \fp_-)
=& \big\|e^{-\gamma_0 t} (\pd_t \rho_+, \gamma_0 \rho_+)\big\|_{L_p(\BR_+; H^1_q(\Omega_+))} 
+\big\|e^{-\gamma_0 t} \nabla \fp_-\big\|_{L_p(\BR_+; L_q(\Omega_-))}\\
&+\sum_{\fs \in \{+,-\}}
\big\|e^{-\gamma_0 t} (\pd_t \bv_{\fs}, \gamma_0 \bv_{\fs}, \Lambda_{\gamma_0}^{1/2} \nabla \bv_{\fs},\nabla^2 \bv_{\fs})\big\|_{L_p(\BR_+; L_q(\Omega_\fs))}.
\end{aligned}
\end{equation*}

\item (Uniqueness) Suppose that the solution $(\rho_+, \bv_{+}, \bv_{-}, \fp_-)$ of the system \eqref{eql:1} satisfies \eqref{ss:thm1} for  
\begin{equation*}
(\rho_{+,0}, \bv_{+,0},\bv_{-,0})=0
\quad \text{and}\quad
(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) =0.
\end{equation*}
Then we have $(\rho_+, \bv_{+}, \bv_{-},\fp_-)=0.$
\end{itemize}
\end{thm}

\begin{rmk}
Let us give some comments on Theorem \ref{thm:mr}.
\begin{itemize}
\item In this paper, we mainly focus on the case where the mass density of the gases has the \emph{constant} equilibrium state $\gamma_{1+}$ and the bottom $S$ is \emph{flat}. The advantage of such reduction is to derive the resolvent estimates in very precise manner (see Section \ref{sec:sf}), which sheds light on the challenging global-in-time theory of the gas-liquid two-phase problem. 
On the other hand, Theorem \ref{thm:mr} can help us find the local-in-time solutions of the nonlinear problem \eqref{eq:NS3} with the mass density of gases near $\gamma_{1+}$ by using similar arguments in one-phase problems (see \cite{EvBS2014,Kubo2021,shibata2007} for instance) and thus we omit it here. 


\item  Based on the Weis' theory \cite{Weis2001}, the key step to prove Theorem \ref{thm:mr} is to establish the $\CR$-solver of the 
 resolvent problem of \eqref{eql:1}: 
\begin{equation}\label{eq:res_full}
	\left\{ \begin{aligned}
		&\lambda\rho_++\gamma_{1+}\di \bv_+=f_+
		&&\quad&\text{in}& \quad \Omega_+, \\
		&\gamma_{1+}\lambda\bv_+-\Di\bT_+(\bv_+,\gamma_{2+}\rho_+)=\bg_+
		&&\quad&\text{in}& \quad  \Omega_+, \\
		&\gamma_{1-}\lambda\bv_--\Di \bT_-(\bv_-,\fp_-)=\bg_-
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
  		& \di\bv_-=g_d=\di\fg_d
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
		&\bT_+(\bv_+,\gamma_{2+}\rho_+)\bn
		-\bT_-(\bv_-,\fp_-)\bn =\bh
		&&\quad&\text{on}& \quad \Gamma,\\
		& \bv_+-\bv_-=\bk
		&&\quad&\text{on}& \quad \Gamma,	\\
		&\bv_-= 0
		&&\quad&\text{on}& \quad S.   
	\end{aligned}
	\right.
\end{equation}
Here $\lambda$ is some complex number. For the result on the system \eqref{eq:res_full}, we refer to Theorem \ref{thm:main2} in Section \ref{sec:resolvent} for more details.
\end{itemize}
\end{rmk}

To conclude this subsection, we outline the structure of this paper. In Section \ref{sec:sf}, we consider some reduced resolvent problem (see \eqref{eq:2.3}) which eliminates the unknown $\rho_+$ from \eqref{eq:res_full}. By applying the partial Fourier transform with respect to the horizontal variable $x'$ to the reduced resolvent problem, we can explicitly solve the resulting ordinary differential equations of the vertical variable $x_N.$ Moreover, we shall analyze the Lopatinski determinant $\det \bL$ appearing in the solution formula of the reduced resolvent problem in Section \ref{sec:det} which is one of most difficult parts in this paper. In particular, from the derivation of the lower bound of  $\det \bL$ in Subsection \ref{subsec:lemma_3.1}, one may find the effect from both the compressible flows and the viscous surface wave problem. 
Using the result on $\det \bL$ in Section \ref{sec:det}, we construct the $\CR$-solver of the problem \eqref{eq:2.3} in Section \ref{sec:SO} and then return to the problem \eqref{eq:res_full} in Section \ref{sec:resolvent}. 
Let us emphasize that the standard technical results on the $\CR$-boundedness theory in the previous one-phase problems are not sufficient in our analysis of the two-phase problems. 
In this regard, we give some new technical results concerning the multiplier operators in Section \ref{sec:SO} but their proofs are postponed in Appendix \ref{proof}. At last, we apply the results on the resolvent problem \eqref{eq:res_full} to obtain the maximal $L_p$-$L_q$ regularity estimates of the system \eqref{eql:1} in Section \ref{sec:mr}. 



\subsection{Notations}
\label{subsec:fs}

%\subsection*{Notations}
Let $\BC$ and $\BN$ denote the set of complex numbers and  natural numbers respectively. For any domain $D\subset\BR^N$, we write $L_q(D)$, $H_q^k(D)$ and $B^s_{q,p}(D)$ for the standard Lebesgue spaces, Sobolev spaces and Besov spaces with $k\in\BN$, $s\in \BR$ and $1\leq p,q\leq \infty$ respectively. In addition, let us set 
\begin{equation*}
   \begin{aligned}
   \wh H^1_q(D)&=\{\theta\in L_{q,\loc}(D):
\nabla\theta\in L_q(D)^N\},  \\
H^1_{q,\Gamma}(\Omega_-)&=\{\theta\in H^1_q(\Omega_-):\,\theta|_\Gamma=0\}
   \end{aligned}
\end{equation*}
with $\Omega_-$ defined in \eqref{dfn:Omega}. 
Moreover, for $\gamma>0,$ $\ell\in\BN$ and some Banach space $X,$ we write 
\begin{align*}
	L_{p,\gamma}(\BR; X)&=\{\theta\in L_{p,\loc}(\BR;X):
    e^{-\gamma t}\theta\in L_p(\BR; X)\},\\
	H^\ell_{p,\gamma}(\BR; X)&=\{\theta\in H^\ell_{p,\loc}(\BR;X):
    e^{-\gamma t}\pd_t^k\theta\in L_p(\BR; X),\,k=0,\dots,\ell\}.
\end{align*}


For $\lambda=\gamma+i\tau\in\BC$, we denote the Laplace transform and its inverse by
\begin{equation}\label{eq:Laplace}
	\begin{aligned}
		\CF_{L} [f] (\lambda)&=\int_{\BR} e^{-\lambda t} f(t) \,dt=\CF[e^{-\gamma t}f](\tau), \\
		\CF_{L}^{-1} [g] (t) &=\frac{1}{2\pi}\int_{\BR}  e^{\lambda t} g(\tau)\,d\tau =e^{\gamma t} \CF^{-1}[g] (t),
	\end{aligned}
\end{equation}
where $\CF$ denote the standard Fourier transform in $\BR.$ 
Then, for $\gamma>0$, let us set
\begin{equation}\label{eq:half}
\Lambda_{\gamma}^{1/2}f(t,x)
=\CF_{L}^{-1}\big[\lambda^{1/2}\CF_{L}[f(t,x)](\tau)\big](t)
=e^{\gamma t} \CF\big[\lambda^{1/2} \CF[e^{-\gamma t}f]\big].    
\end{equation}
The Bessel potential space of order $1/2$ is given by 
\begin{align*}
	H^{1/2}_{p,\gamma}(\BR;L_q(\Omega))&=\big\{f\in L_{p,\gamma}(\BR;L_q(\Omega)):e^{-\gamma t}\Lambda^{1/2}_\gamma f\in L_p(\BR;L_q(\Omega))\big\}
\end{align*}
with its norm 
$$\|f\|_{H^{1/2}_{p,\gamma}(\BR;L_q(\Omega))}=\|e^{-\gamma t}\Lambda_{\gamma}^{1/2}f\|_{L_p(\BR;L_q(\Omega))}.$$

For Banach spaces $X$ and $Y,$ $\CL(X; Y)$ denotes the set of bounded linear transformations from $X$ to $Y.$ 
Besides, $\Hol(\Lambda;X)$ denotes the set of $X$-valued functions defined on domain $\Lambda\subset \BC$.

In addition, $A \lesssim B$ stands for $A\leq C B$ whenever $C$ is a harmless constant.


