\section{Solution formula for some reduced resolvent problem} \label{sec:sf}
In this section,  we consider the following reduced problem:
	\begin{equation}\label{eq:2.3}
		\left\{ \begin{aligned}
			&\gamma_{1+}\lambda\bv_+-\mu_+\Delta\bv_+-(\nu_++\delta)\nabla\di\bv_+=0
			&&\quad&\text{in}& \quad \Omega_+, \\
			&\gamma_{1-}\lambda\bv_--\mu_-\Delta\bv_-+\nabla \fp_-=0,\quad \di\bv_-=0
			&&\quad&\text{in}& \quad \Omega_-, \\ 
			&\bS_{\delta+}(\bv_+)\bn-\bT_-(\bv_-,\fp_-)\bn=\bh
			&&\quad&\text{on}& \quad \Gamma,\\
			& \bv_+-\bv_-=\bk
			&&\quad&\text{on}& \quad \Gamma ,	\\
			&\bv_-= 0
			&&\quad&\text{on}& \quad S.   
		\end{aligned}
		\right.
	\end{equation}	
where $\Omega_{\pm}, \Gamma, S$ are given in \eqref{dfn:Omega} for some $b>0$ and 
\begin{equation}\label{eq:S_delta}
  \bS_{\delta+}(\bv_+)
	=\mu_+\bD(\bv_+)+(\nu_+-\mu_++\delta)\di\bv_+\bI.  
\end{equation}
In fact, we can obtain the system \eqref{eq:2.3} by the eliminating $\rho_+$ from \eqref{eq:res_full} and neglecting the source terms in the equations of $\bv_{\pm}$.
In addition, let us set 
\begin{equation}\label{eq:KSigma}
\begin{aligned}
	K_{\ep}&=\{\lambda \in \BC: (\Re \lambda +\gamma_{1+}\gamma_{2+} \nu_+^{-1} +\ep)^2 + (\Im \lambda)^2 \geq (\gamma_{1+}\gamma_{2+} \nu_+^{-1} +\ep)^2\}, \\
	\Sigma_{\ep}&= \big\{\lambda \in \BC\backslash \{0\} :
	|\arg \lambda |\leq \pi -\ep \big\},\quad 
	\Sigma_{\ep, \lambda_0} =\{\lambda \in \Sigma_{\ep} : |\lambda| \geq \lambda_0\}
\end{aligned}
\end{equation}
for any $\lambda_0>0$ and $0<\varepsilon<\pi/2$.


\begin{ass}\label{ass:dl}
Let $\delta_0$ be some positive constant.
In \eqref{eq:2.3}, $\lambda,\delta\in \BC$  are some parameters satisfying the following assumption:
\begin{enumerate}[label=$(C\arabic*)$]	
\item $\lambda \in  \Sigma_{\ep, \lambda_0}  \cap K_{\ep},$ 
$\delta=\gamma_{1+}\gamma_{2+}\lambda^{-1};$

\item $\delta \in \Sigma_{\ep}$ 
with $\Re \delta<0$ and $|\delta| \leq \delta_0,$ 
$|\lambda|\geq \lambda_0,$
$\Re \lambda \geq |\Re \delta / \Im \delta| \, |\Im \lambda| ;$

\item $\delta \in \Sigma_{\ep}$ 
with $\Re \delta \geq 0$ and $|\delta| \leq \delta_0,$  
$|\lambda|\geq \lambda_0,$
$\Re \lambda \geq \lambda_0 \, |\Im \lambda|.$
\end{enumerate}

For simplicity, we also write
\begin{equation}\label{def:Gamma}
\Gamma_{\ep,\lambda_0}=
\begin{cases}
\Sigma_{\ep, \lambda_0}  \cap K_{\ep} & 
\text{in case of}\,\,\,\, (C1);\\
\big\{ \lambda\in \BC: |\lambda|\geq \lambda_0,
\Re \lambda \geq |\Re \delta / \Im \delta| \, |\Im \lambda|\big\}
& \text{in case of}\,\,\,\, (C2);\\
\big\{ \lambda\in \BC: |\lambda|\geq \lambda_0,
\Re \lambda \geq \lambda_0 \, |\Im \lambda|\big\}
& \text{in case of}\,\,\,\, (C3).
\end{cases}
\end{equation}
\end{ass}




As the the boundaries of $\Omega_\pm$ are flat, we introduce the (partial) Fourier transform with respect to the tangential variable $x^\prime:$
	$$\wh{\bv}(\xi^\prime,x_N)=\mathcal{F}_{x^\prime}[\bv(\cdot,x_N)](\xi^\prime)=\int_{\mathbb{R}^{N-1}}e^{-ix^\prime\cdot\xi^\prime}\bv(x^\prime,x_N)dx^\prime.$$ 
	Then taking the partial Fourier transform to \eqref{eq:2.3}  yields  
	\begin{equation}\label{eq:2.4}
	\left\{ 
		\begin{aligned}
		&(\gamma_{1+}\lambda+\mu_+|\xi^\prime|^2)\widehat{v}_{+j}
		-\mu_+\pd_N^2\widehat{v}_{+j}-(\nu_++\delta)i\xi_j
		(i\xi^\prime\cdot\widehat{\bv}^\prime_++\pd_N\widehat{v}_{+N})=0 
		& (x_N>0),\\
		&(\gamma_{1+}\lambda+\mu_+|\xi^\prime|^2)\widehat{v}_{+N}
		-\mu_+\pd_N^2\widehat{v}_{+N}-(\nu_++\delta)\pd_N
		(i\xi^\prime\cdot\widehat{\bv}^\prime_++\pd_N\widehat{v}_{+N})=0 
		& (x_N>0),\\	
		&(\gamma_{1-}\lambda+\mu_-|\xi^\prime|^2)\widehat{v}_{-j}
		-\mu_-\pd_N^2\widehat{v}_{-j}+i\xi_j\widehat{\fp}_-=0
		&(-b<x_N<0),\\
		&(\gamma_{1-}\lambda+\mu_-|\xi^\prime|^2)\widehat{v}_{-N}
		-\mu_-\pd_N^2\widehat{v}_{-N}+\pd_N\widehat{\fp}_-=0
		&(-b<x_N<0),\\
		&i\xi^\prime\cdot\widehat{\bv}^\prime_-+\pd_N\widehat{v}_{-N}=0
		&(-b<x_N<0)
	\end{aligned}
		\right.
	\end{equation}
	subject to the conditions
	\begin{equation}\label{eq:2.5}
		\left\{ 
		\begin{aligned}
		&\mu_+(\pd_N\widehat{v}_{+j}+i\xi_j\widehat{v}_{+N})
		-\mu_-(\pd_N\widehat{v}_{-j}+i\xi_j\widehat{v}_{-N})=\widehat{h}_j
		&(x_N=0),\\
		&2\mu_+\pd_N\widehat{v}_{+N}
		+(\nu_+-\mu_++\delta)(i\xi^\prime\cdot\widehat{\bv}_{+}^\prime
		+\pd_N\widehat{v}_{+N})
		-(2\mu_-\pd_N\widehat{v}_{-N}-\widehat{\fp}_-)=\widehat{h}_{N} 
		&(x_N=0),\\
		&\widehat{v}_{+J}-\widehat{v}_{-J}=\widehat{k}_J 
		&(x_N=0),\\
		&\widehat{v}_{-J}=0 &(x_N=-b)
	\end{aligned}
		\right.
	\end{equation}
	for $j=1,\cdots,N-1,$ $J=1,\cdots,N$ and $\pd_N=\pd_{x_N}.$ 
	Moreover, we have also used the equalities
	\begin{equation*}
		i\xi^\prime\cdot\widehat{\bv}_{\pm}^\prime=\sum_{j=1}^{N-1}i\xi_j\widehat{v}_j
	\end{equation*}
	for $\bv_\pm=(\bv_{\pm}',v_{\pm N})^{\top} =(v_{\pm 1},\cdots,v_{\pm (N-1)},v_{\pm N})^{\top}.$
	\medskip

Now, let us derive the solution formula from \eqref{eq:2.4} and \eqref{eq:2.5}.
As the discussion of the problem in the whole space in \cite{KSS2014}, we introduce the characteristic roots:
	\begin{equation}\label{eq:2.7}
		\begin{aligned}
			A_+& =\sqrt{\gamma_{1+}(\mu_++\nu_++\delta)^{-1}\lambda+A^2}, & 
			B_{+}& =\sqrt{\gamma_{1+}(\mu_+)^{-1}\lambda+A^2},\\ 
			A_-& =A=|\xi^\prime|, & 
			B_-& =\sqrt{\gamma_{1-}(\mu_-)^{-1}\lambda+A^2}.
		\end{aligned}
	\end{equation}
Suppose that the solution $(\widehat{\bv}_{\pm},\widehat{\fp}_-)$ to the problem \eqref{eq:2.4}-\eqref{eq:2.5} is of the forms 
	\begin{equation}\label{eq:2.8}
		\begin{aligned}
			\widehat{v}_{+J}=&\alpha_{+J}(e^{-B_+x_N}-e^{-A_+x_N})+\beta_{+J}e^{-B_+x_N},\\
			\widehat{v}_{-J}=&\alpha_{-J}^0(e^{B_-x_N}-e^{Ax_N})+\beta_{-J}^0e^{B_-x_N}\\
			&+\alpha_{-J}^{b}(e^{-B_-(x_N+b)}-e^{-A(x_N+b)})+\beta_{-J}^{b}e^{-B_-(x_N+b)},\\
			\widehat{\fp}_-=&\gamma_-^0e^{Ax_N} +\gamma_-^be^{-A(x_N+b)} .
		\end{aligned}
	\end{equation}
Then inserting \eqref{eq:2.8} into \eqref{eq:2.4} and equating the coefficients of the terms $e^{\mp A_{\pm}x_N},$ $e^{\mp B_{\pm}x_N}$, $e^{-A_-(x_N+b)}$ and $e^{-B_-(x_N+b)}$ imply that 
\begin{equation}\label{eq:2.9}
	\left\{ 
\begin{aligned}
		&\mu_+(A^2_+-B^2_+)\alpha_{+j}+(\nu_++\delta)i\xi_j(i\xi^\prime\cdot\alpha^\prime_+-A_+\alpha_{+N})=0,\\
		&\mu_+(A^2_+-B^2_+)\alpha_{+N}-(\nu_++\delta)A_+(i\xi^\prime\cdot\alpha^\prime_+-A_+\alpha_{+N})=0,\\
		&i\xi^\prime\cdot\alpha^\prime_+-B_+\alpha_{+N}
		+i\xi^\prime\cdot\beta^\prime_+-B_+\beta_{+N}=0,\\
				&\mu_-(A^2-B^2_-)\alpha_{-j}^0+i\xi_j\gamma_-^0=0,\quad \mu_-(A^2-B^2_-)\alpha_{-j}^b+i\xi_j\gamma_-^b=0,\\
		&\mu_-(A^2-B^2_-)\alpha_{-N}^0+A\gamma_-^0=0,\quad \mu_-(A^2-B^2_-)\alpha_{-N}^b-A\gamma_-^b=0,\\
			&i\xi^\prime\cdot(\alpha_-^{0})'+B_-\alpha_{-N}^0
	+i\xi^\prime\cdot(\beta_-^{0})'+B_-\beta_{-N}^0=0,\\
	&i\xi^\prime\cdot(\alpha_-^{b})'-B_-\alpha_{-N}^b
	+i\xi^\prime\cdot(\beta_-^{b})'-B_-\beta_{-N}^b=0,
	\\&i\xi^\prime\cdot(\alpha_-^{0})'+A\alpha_{-N}^0=0,\quad i\xi^\prime\cdot(\alpha_-^{b})'-A\alpha_{-N}^b=0.
\end{aligned}
\right.
\end{equation}
From the equalities in \eqref{eq:2.9}, it is not hard to see that
\begin{equation}\label{eq:2.10}
\left\{ 
\begin{aligned}
	i\xi^\prime\cdot\alpha_+^\prime
	&=\frac{A^2}{A_+B_+-A^2}(i\xi^\prime\cdot\beta_+^\prime-B_+\beta_{+N}), \\
	\alpha_{+N} &=\frac{A_+}{A_+B_+-A^2}
	(i\xi^\prime\cdot\beta_+^\prime-B_+\beta_{+N}),\\
i\xi^\prime\cdot(\alpha_-^{0})'
&=\frac{A}{B_--A} 
\big(i\xi^\prime\cdot(\beta_-^{0})'+B_-\beta_{-N}^{0} \big),\\
\alpha_{-N}^0&=-\frac{1}{B_--A} 
\big(i\xi^\prime\cdot(\beta_-^{0})'+B_-\beta_{-N}^{0} \big),\\
i\xi^\prime\cdot(\alpha_-^{b})' &=\frac{A}{B_--A}
\big( i\xi^\prime\cdot(\beta_-^{b})'-B_-\beta_{-N}^{b} \big),\\
\alpha_{-N}^b &=\frac{1}{B_--A}
\big( i\xi^\prime\cdot(\beta_-^{b})'-B_-\beta_{-N}^{b}\big),\\
\gamma_-^0&=-\frac{\mu_-(A+B_-)}{A}
\big( i\xi^\prime\cdot(\beta_-^{0})'+B_-\beta_{-N}^0 \big),\\
\gamma_-^b&=-\frac{\mu_-(A+B_-)}{A}
\big( i\xi^\prime\cdot(\beta_-^{b})'-B_-\beta_{-N}^b \big).
\end{aligned}
\right.
\end{equation}


On the other hand,  we use \eqref{eq:2.8} to get
\begin{equation}\label{2.11-1}
\left\{ 
	\begin{aligned}
		\widehat{v}_{+ J}(0)& =\beta_{+ J},\\
		\pd_N\widehat{v}_{+ J}(0)&=(A_+-B_+)\alpha_{+J}-B_+\beta_{+J},\\
		\widehat{v}_{- J}(0)&=\beta_{-J}^0+(e^{-B_-b}-e^{-Ab})\alpha_{-J}^b
		+e^{-B_-b}\beta_{-J}^b,\\
		\pd_N\widehat{v}_{- J}(0)&=(B_--A)\alpha_{-J}^0+B_-\beta_{-J}^0\\
		&\quad +(-B_-e^{-B_-b}+Ae^{-Ab})\alpha_{-J}^b-B_-e^{-B_-b}\beta_{-J}^b, \\
	\widehat{p}_{-}(0)&=\gamma_-^0+e^{-Ab}\gamma_-^b,\\
	\widehat{v}_{-J}(-b) &=(e^{-B_-b}-e^{-Ab})\alpha_{-J}^0
	+e^{-B_-b}\beta_{-J}^0+\beta_{-J}^{b}.
	\end{aligned}
	\right.
\end{equation}
Substituting \eqref{2.11-1} into \eqref{eq:2.5}, we have
\begin{equation}\label{eq:2.12}
\begin{aligned}
\widehat{h}_j(0)=&\mu_+\big((A_+-B_+)\alpha_{+j}-B_+\beta_{+j}+i\xi_j\beta_{+N}\big)\\
&-\mu_-\big[ (B_--A)\alpha_{-j}^0+B_-\beta_{-j}^0
+(-B_-e^{-B_-b}+Ae^{-Ab})\alpha_{-j}^b
\\& \hspace{1.5cm} -B_-e^{-B_-b}\beta_{-j}^b
+i\xi_j \big( \beta_{-N}^0+(e^{-B_-b}-e^{-Ab})\alpha_{-N}^b
+ e^{-B_-b} \beta_{-N}^b\big) \big] ,\\
\widehat{h}_N(0)=&-2\mu_+\big((B_+-A_+)\alpha_{+N}+B_+\beta_{+N}\big) \\
		&-(\nu_+-\mu_++\delta)\big(-i\xi^\prime\cdot\beta_+^\prime+(B_+-A_+)\alpha_{+N}+B_+\beta_{+N}\big)\\
		&-2\mu_-\big[ (B_--A)\alpha_{-N}^0+B_-\beta_{-N}^0+(-B_-e^{-B_-b}+Ae^{-Ab})\alpha_{-N}^b-B_-e^{-B_-b}\beta_{-N}^b\big]\\
		&+\gamma_-^0+e^{-Ab}\gamma_-^b,\\
\widehat{k}_J(0)=&\beta_{+J}-\beta_{-J}^0
-(e^{-B_-b}-e^{-Ab})\alpha_{-J}^b-e^{-B_-b}\beta_{-J}^b,\\
0=&(e^{-B_-b}-e^{-Ab})\alpha_{-J}^0+e^{-B_-b}\beta_{-J}^0+\beta_{-J}^b.
	\end{aligned}
\end{equation}
\medskip

Let $M_{\pm}(x_N)$ denote the Stokes kernels 
\begin{equation}\label{eq:2.13}
	M_+(y_N)=\frac{e^{-B_+y_N}-e^{-A_+y_N}}{B_+-A_+} \,\,\,(y_N>0),\qquad 
	M_-(z_N)=\frac{e^{B_-z_N}-e^{Az_N}}{B_--A} \,\,\,(z_N<0).
\end{equation}
Using \eqref{eq:2.10} and \eqref{eq:2.12}, we get that
\begin{equation}\label{eq:2.14}
\begin{aligned}
i\xi'\cdot \widehat{h}'(0)=&\mu_+\Big( \frac{(A_+-B_+)A^2}{A_+B_+-A^2}(i\xi'\cdot\beta_+'-B_+\beta_{+N})-B_+i\xi'\cdot\beta_+'-A^2\beta_{+N} \Big)\\
	&-\mu_-\Big\{A\big( i\xi'\cdot(\beta_-^{0})'+B_-\beta_{-N}^0 \big)
	+B_-i\xi' \cdot (\beta_-^{0})' \\
	&\qquad -A\big( B_-M_-(-b)+e^{-Ab} \big) 
	\big( i\xi'\cdot(\beta_-^{b})'-B_-\beta_{-N}^b\big)
	- B_-e^{-B_-b}\,i\xi'\cdot(\beta_-^{b})'\\
	&\qquad -A^2\big[ \beta_{-N}^0+M_-(-b)
	\big( i\xi'\cdot(\beta_-^{b})'-B_-\beta_{-N}^b\big)
	+e^{-B_-b}\beta_{-N}^b \big]\Big\},\\
\widehat{h}_N(0)=&-2\mu_+\Big( \frac{A_+(B_+-A_+)}{A_+B_+-A^2}
(i\xi'\cdot\beta_+'-B_+\beta_{+N})+B_+\beta_{+N} \Big)\\
&-(\nu_+-\mu_++\delta)\Big(-i\xi'\cdot\beta_+'+\frac{A_+(B_+-A_+)}{A_+B_+-A^2}(i\xi'\cdot\beta_+'-B_+\beta_{+N})+B_+\beta_{+N}  \Big)\\
	&-2\mu_-\Big\{-\big( i\xi'\cdot(\beta_-^{0})'+B_-\beta_{-N}^0 \big)+B_-\beta_{-N}^0\\
	&\qquad -\big( B_-M_-(-b)+e^{-Ab} \big) 
	\big( i\xi'\cdot(\beta_-^{b})'-B_-\beta_{-N}^b \big)
	-B_-e^{-B_-b}\beta_{-N}^b \Big\} \\
	&-\frac{\mu_-(A+B_-)}{A}
\big( i\xi^\prime\cdot(\beta_-^{0})'+B_-\beta_{-N}^0 \big)
-\frac{\mu_-(A+B_-)}{A}e^{-Ab}
\big( i\xi^\prime\cdot(\beta_-^{b})'-B_-\beta_{-N}^b \big),\\
i\xi'\cdot\widehat{k}'(0)=&i\xi'\cdot\beta_+'-i\xi'\cdot(\beta_-^{0})'
-AM_-(-b) \big( i\xi'\cdot(\beta_-^{b})'-B_-\beta_{-N}^b \big)
-e^{-B_-b}i\xi'\cdot(\beta_-^{b})',\\
\widehat{k}_N(0)=&\beta_{+N}-\beta_{-N}^0-M_-(-b)
\big( i\xi'\cdot(\beta_-^{b})'-B_-\beta_{-N}^b \big)-e^{-B_-b}\beta_{-N}^b,\\
0=&AM_-(-b)\big(i\xi^\prime\cdot(\beta_-^{0})'+B_-\beta_{-N}^{0} \big)
+e^{-B_-b}i\xi^\prime\cdot(\beta_-^{0})'+
i\xi^\prime\cdot(\beta_-^{b})',\\
	0=&-M_-(-b)\big(i\xi^\prime\cdot(\beta_-^{0})'+B_-\beta_{-N}^{0} \big)
	+e^{-B_-b}\beta_{-N}^0+\beta_{-N}^b.\\
\end{aligned}
\end{equation}
It then follows that
\begin{equation}\label{eq:2.14-2}
\begin{aligned}
	i\xi'\cdot\widehat{h}'&=L_{11}^+ i\xi'\cdot\beta_+'
	+L_{11}^{0-} i\xi'\cdot(\beta_-^{0})' 
	+L_{11}^{b-} i\xi'\cdot(\beta_-^{b})'
	+L_{12}^+\beta_{+N}+L_{12}^{0-}\beta_{-N}^0+L_{12}^{b-}\beta_{-N}^b,\\
	A\widehat{h}_N&=L_{21}^+ i\xi'\cdot\beta_+'
	+L_{21}^{0-} i\xi'\cdot(\beta_-^{0})'
	+L_{21}^{b-} i\xi'\cdot(\beta_-^{b})'
	+L_{22}^+\beta_{+N}+L_{22}^{0-}\beta_{-N}^0+L_{22}^{b-}\beta_{-N}^b
\end{aligned}
\end{equation}
with
\begin{equation}\label{eq:2.15}
	\begin{aligned}
		&L_{11}^+=-\mu_+\frac{A_+(B_+^2-A^2)}{A_+B_+-A^2},
		\qquad L_{11}^{0-}=-\mu_-(A+B_-),\\
		&L_{11}^{b-}=\mu_-\big((A+B_-)e^{-B_-b}+2A^2M_-(-b)\big),\qquad
		L_{12}^+=-\mu_+\frac{A^2(2A_+B_+-A^2-B_+^2)}{A_+B_+-A^2},\\
		& L_{12}^{0-}=-\mu_-(B_--A)A,\qquad 
		 L_{12}^{b-}=-\mu_-\big(2A^2B_-M_-(-b)+(B_--A)Ae^{-B_-b}\big),\\
		&L_{21}^+=-A\Big( 2\mu_+\frac{A_+(B_+-A_+)}{A_+B_+-A^2}-(\nu_+-\mu_++\delta)\frac{A_+^2-A^2}{A_+B_+-A^2}\Big), \\
		& L_{21}^{0-}=-\mu_-(B_--A),\qquad
		L_{21}^{b-}=2\mu_- AB_-M_-(-b)
		-\mu_-(B_--A)e^{-Ab},\\
		&L_{22}^+=-(\mu_++\nu_++\delta)\frac{AB_+(A^2_+-A^2)}{A_+B_+-A^2},
		\qquad L_{22}^{0-}=-\mu_-(A+B_-)B_-,\\
		&L_{22}^{b-}=-2\mu_-A^2B_-M_-(-b)
		+\mu_-(B_-+A)B_-e^{-Ab}.
	\end{aligned}
\end{equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Using the equations $\eqref{eq:2.14}_3$ and $\eqref{eq:2.14}_4$, we have
\begin{equation}\label{eq:2.15-2}
\left\{ 
\begin{aligned}
i\xi'\cdot\beta_+'=
&i\xi'\cdot\widehat{k}'(0)-A(A+B_-)M_-^2(-b) 
\big( i\xi'\cdot(\beta_-^{0})'+B_-\beta_{-N}^0\big)\\
&+\big(1-e^{-2B_-b} -2e^{-B_-b}AM_-(-b)\big) i\xi'\cdot(\beta_-^{0})' ,\\
\beta_{+N} =& \widehat{k}_N(0)-(A+B_-)M_-^2(-b)
\big( i\xi'\cdot(\beta_-^{0})'+B_-\beta_{-N}^0\big)\\
&+ \big( 1-e^{-2B_-b}+2e^{-B_-b}B_-M_-(-b) \big)\beta_{-N}^0,\\
i\xi^\prime\cdot(\beta_-^{b})' =& 
-e^{-B_-b} i\xi'\cdot(\beta_-^{0})'
-AM_-(-b)\big( i\xi'\cdot(\beta_-^{0})'+B_-\beta_{-N}^0\big),\\
\beta_{-N}^b =& M_-(-b) \big( i\xi'\cdot(\beta_-^{0})'+B_-\beta_{-N}^0\big)
-e^{-B_-b}\,\beta_{-N}^0.
\end{aligned}\right.
\end{equation}

Now let us set 
\begin{equation*}
\begin{aligned}
\widehat{H}_h=&i\xi'\cdot\widehat{h}'
-L_{11}^+i\xi'\cdot\widehat{k}'-L_{12}^+\widehat{k}_N,\\
\widehat{H}_N=&A\widehat{h}_N-L_{21}^+
i\xi'\cdot\widehat{k}'-L_{22}^+\widehat{k}_N,\\
\fL_1=&-(AL_{11}^++L_{12}^+) (A+B_-)M_-^2(-b)
-L_{11}^{b-}A M_-(-b)+ L_{12}^{b-}M_-(-b),\\
\fL_2=&-(AL_{21}^++L_{22}^+ ) (A+B_-)M_-^2(-b)
-L_{21}^{b-}A M_-(-b)+ L_{22}^{b-}M_-(-b).
\end{aligned}
\end{equation*}
Inserting \eqref{eq:2.15-2} into \eqref{eq:2.14-2} yields  
\begin{equation*}
	\bL\begin{pmatrix}
		i\xi'\cdot(\beta_-^{0})'\\\beta_{-N}^0
	\end{pmatrix}=\begin{pmatrix}
		\widehat{H}_h(0)\\\widehat{H}_N(0)
	\end{pmatrix}
\end{equation*}
where the entries $L_{k\ell}$ of the matrix $\bL$ are given by 
\begin{equation}\label{eq:Lij}
\begin{aligned}
L_{k1}=&L_{k1}^+\big(1-e^{-2B_-b}-2e^{-B_-b}AM_-(-b)\big)
+L_{k1}^{0-}-L_{k1}^{b-}e^{-B_-b}+\fL_k,\\
L_{k2}=&L_{k2}^+\big(1-e^{-2B_-b}+2e^{-B_-b}B_-M_-(-b)\big)
+L_{k2}^{0-}-L_{k2}^{b-}e^{-B_-b}+B_-\fL_k
\end{aligned}
\end{equation}
for $k=1,2.$ 
\medskip

Suppose that
\footnote{See Lemma \ref{lem:3.1} for more details. } 
$\det \bL=L_{11}L_{22}-L_{12}L_{21}\not=0.$ Then the inverse matrix of $\bL$ is written as
\begin{equation*}
	\bL^{-1}=\frac{1}{\det \bL}\begin{pmatrix}
		L_{22}&-L_{12}\\
		-L_{21}&L_{11}
	\end{pmatrix}.
\end{equation*}
Thus we have
\begin{equation}\label{eq:2.16}
\begin{aligned}
i\xi'\cdot(\beta_-^{0})'
=&\frac{1}{\det \bL}\Big(L_{22}i\xi'\cdot\widehat{h}'(0)
		-AL_{12}\widehat{h}_N(0) \\
&\hspace{1.5cm}-(L_{22}L_{11}^+-L_{12}L_{21}^+)i\xi'\cdot\widehat{k}'(0)
		-(L_{22}L_{12}^+-L_{12}L_{22}^+)\widehat{k}_N(0)\Big),\\
\beta_{-N}^{0}
=&\frac{1}{\det \bL}\Big(-L_{21}i\xi'\cdot\widehat{h}'(0)
		+AL_{11}\widehat{h}_N(0)\\
&\hspace{1.5cm}+(L_{21}L_{11}^+-L_{11}L_{21}^+)i\xi'\cdot\widehat{k}'(0)
		+(L_{21}L_{12}^+-L_{11}L_{22}^+)\widehat{k}_N(0)\Big).
	\end{aligned}
\end{equation}
By \eqref{eq:2.15-2} and \eqref{eq:2.16}, we arrive 
\begin{equation}\label{eq:2.16-2}
\begin{aligned}
i\xi'\cdot(\beta_-^{0})'+B_-\beta_{-N}^0
&=\sum_{J=1}^{N}\big(P_{J,0}^{0}\widehat{h}_J(0)
+P_{J,1}^{0}\widehat{k}_{J}(0)\big),\\
i\xi'\cdot(\beta_-^{b})'-B_-\beta_{-N}^b
&=\sum_{J=1}^{N}\big(P_{J,0}^{b}\widehat{h}_J(0)
+P_{J,1}^{b}\widehat{k}_{J}(0)\big),\\
i\xi'\cdot\beta_+^{'}-B_+\beta_{+N}
&=\sum_{J=1}^{N}\big(P_{J,0}^{+}\widehat{h}_J(0)
+P_{J,1}^{+}\widehat{k}_{J}(0)\big).
	\end{aligned}
\end{equation}
Here, we have defined 
\begin{equation*}
\begin{aligned}
P_{j,0}^{0}=&\frac{(L_{22}-B_-L_{21})i\xi_j}{\det\bL},\\ 
P_{N,0}^{0}=&\frac{-AL_{12}+AB_-L_{11}}{\det\bL},\\
P_{j,1}^{0}=&\frac{\big(L_{12}L_{21}^+-L_{22}L_{11}^++B_-(L_{21}L_{11}^+-L_{11}L_{21}^+)\big)i\xi_j}{\det\bL},\\
P_{N,1}^{0}=&\frac{L_{12}L_{22}^+-L_{22}L_{12}^+
+B_-(L_{21}L_{12}^+-L_{11}L_{22}^+)}{\det\bL},\\
P_{j,0}^{b}=&-\frac{\big((A+B_-)M_-(-b)+e^{-B_-b}\big)L_{22}i\xi_j}{\det\bL}\\
&+\frac{\big((A+B_-)M_-(-b)-e^{-B_-b}\big)B_-L_{21}i\xi_j}{\det\bL},\\ 
P_{N,0}^{b}=&\frac{\big((A+B_-)M_-(-b)+e^{-B_-b}\big)AL_{12}}{\det\bL}\\
&-\frac{\big((A+B_-)M_-(-b)-e^{-B_-b}\big)AB_-L_{11}}{\det\bL},\\
P_{j,1}^{b}=&\frac{(L_{22}L_{11}^+-L_{12}L_{21}^+)
\big((A+B_-)M_-(-b)+e^{-B_-b}\big)i\xi_j}{\det\bL}\\
&-\frac{(L_{21}L_{11}^+-L_{11}L_{21}^+)
\big((A+B_-)M_-(-b)-e^{-B_-b}\big)B_-i\xi_j}{\det\bL},\\
P_{N,1}^{b}=&\frac{(L_{22}L_{12}^+-L_{12}L_{22}^+)
\big((A+B_-)M_-(-b)+e^{-B_-b}\big)}{\det\bL}\\
&-\frac{(L_{21}L_{12}^+-L_{11}L_{22}^+)
\big((A+B_-)M_-(-b)-e^{-B_-b}\big)B_-}{\det\bL},\\
	P_{j,0}^+=& N^{+}_{0} P_{j,0}^0+N^+_1 \frac{L_{21}}{\det\bL} i\xi_j,\\
	P_{N,0}^+=&N^{+}_{0} P_{N,0}^0-N^{+}_1\frac{AL_{11}}{\det\bL},  \\
    P_{j,1}^+=& i\xi_j + N^{+}_{0}  P_{j,1}^0
    +N^{+}_1\frac{L_{11}L_{21}^+-L_{21}L_{11}^+}{\det\bL} i\xi_j,\\
	 P_{N,1}^+=&-B_++N^{+}_{0} P_{N,1}^0
		+N^{+}_1 \frac{L_{11}L_{22}^+-L_{21}L_{12}^+}{\det\bL}
	\end{aligned}
\end{equation*}
with
\begin{equation*}
\begin{aligned}
N^{+}_0 &=(B_+-A)(A+B_-)M_-^2(-b)
	+1-e^{-2B_-b}-2e^{-B_-b}AM_-(-b),\\
N^{+}_1 &= (B_++B_-)(1-e^{-2B_-b}) +2B_-(B_+-A)M_-(-b)e^{-B_-b}.
\end{aligned}
\end{equation*}
In particular, the formula of $\widehat{\fp}_-$ reads as
\begin{equation}\label{eq:pressure}
	\widehat{\fp}_-(x_N)=e^{Ax_N}\sum_{J=1}^N
	\big( p_{J,0}^{0}\widehat{h}_J(0)+p_{J,1}^{0}\widehat{k}_J(0)\big)
	+e^{-A(x_N+b)}\sum_{J=1}^N\big(p_{J,0}^{b}\widehat{h}_J(0)
	+p_{J,1}^{b}\widehat{k}_J (0)\big)
\end{equation}
with
\begin{align*}
	p_{J,0}^{0}&=-\frac{\mu_-(A+B_-)}{A}P_{J,0}^{0}, &
	 p_{J,1}^{0}=-\frac{\mu_-(A+B_-)}{A}P_{J,1}^{0},\\
	p_{J,0}^{b}&=-\frac{\mu_-(A+B_-)}{A}P_{J,0}^{b},&
	p_{J,1}^{b}=-\frac{\mu_-(A+B_-)}{A}P_{J,1}^{b}.
\end{align*}
\medskip



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Now,  it suffices to derive the formulas of $\wh \bv_{\pm}.$ 
Using \eqref{eq:2.10} and \eqref{eq:2.16-2}, we obtain
\begin{equation}\label{eq:cof_1}
\left\{ 
\begin{aligned}
\alpha_{+N} &=\frac{A_+}{A_+B_+-A^2}
\sum_{J=1}^{N}\big(P_{J,0}^{+}\widehat{h}_J(0)
+P_{J,1}^{+}\widehat{k}_{J}(0)\big),\\
\alpha_{-N}^0&=- \frac{1}{B_--A}\sum_{J=1}^{N}
\big(P_{J,0}^{0}\widehat{h}_J(0)+P_{J,1}^{0}\widehat{k}_{J}(0)\big),\\
\alpha_{-N}^b &=\frac{1}{B_--A}\sum_{J=1}^{N}
\big(P_{J,0}^{b}\widehat{h}_J(0)+P_{J,1}^{b}\widehat{k}_{J}(0)\big),\\
\gamma_-^0&=-\frac{\mu_-(A+B_-)}{A}
\sum_{J=1}^{N}
\big(P_{J,0}^{0}\widehat{h}_J(0)+P_{J,1}^{0}\widehat{k}_{J}(0)\big),\\
\gamma_-^b&=-\frac{\mu_-(A+B_-)}{A}\sum_{J=1}^{N}
\big(P_{J,0}^{b}\widehat{h}_J(0)+P_{J,1}^{b}\widehat{k}_{J}(0)\big).
\end{aligned}
\right.
\end{equation}
On the other hand,  notice from \eqref{eq:2.10} that 
\begin{equation*}
\begin{aligned}
i\xi^\prime\cdot\alpha_+^\prime-A_+\alpha_{+N}
&=-\frac{A_+^2-A^2}{A_+B_+-A^2}
(i\xi^\prime\cdot\beta_+^\prime-B_+\beta_{+N}) \\
&=-\frac{\mu_+ (B_+^2-A_+^2)}{(\nu_++\delta)(A_+B_+-A^2)}
(i\xi^\prime\cdot\beta_+^\prime-B_+\beta_{+N})
\end{aligned}
\end{equation*}
for $(\nu_++\delta)(A_+^2-A^2)=\mu_+ (B_+^2-A_+^2).$
Then \eqref{eq:2.9} and \eqref{eq:2.16-2} yield 
\begin{equation}\label{eq:cof_2}
\left\{
\begin{aligned}
\alpha_{+j}&=-\frac{i\xi_j}{A_+B_+-A^2}
\sum_{J=1}^{N}\big(P_{J,0}^{+}\widehat{h}_J(0)
+P_{J,1}^{+}\widehat{k}_{J}(0)\big),\\
\alpha_{-j}^0&=\frac{i\xi_j \gamma_-^0}{\mu_-(B_-^2-A^2)}
=-\frac{i\xi_j}{A(B_--A)}
\sum_{J=1}^{N}\big(P_{J,0}^{0}\widehat{h}_J(0)
+P_{J,1}^{0}\widehat{k}_{J}(0)\big),\\ 
\alpha_{-j}^b&=\frac{i\xi_j \gamma_-^b}{\mu_-(B_-^2-A^2)}
=-\frac{i\xi_j}{A(B_--A)}
\sum_{J=1}^{N}\big(P_{J,0}^{b}\widehat{h}_J(0)
+P_{J,1}^{b}\widehat{k}_{J}(0)\big)
	\end{aligned} \right.
\end{equation}
for any $j=1,\dots,N-1.$
\medskip

Next, using \eqref{eq:2.16}, we represent $\beta_{-N}^0$ as follows
\begin{equation}\label{eq:cof_3}
\beta_{-N}^0=\sum_{J=1}^N \big( S_{NJ,-1}^-\widehat{h}_J(0)
+S_{NJ,0}^-\widehat{k}_{J}(0) \big),
\end{equation}
where we have set 
\begin{equation*}
\begin{aligned}
S_{Nj,-1}^-&=-\frac{L_{21} i\xi_j}{\det \bL},
&S_{NN,-1}^-&=\frac{AL_{11}}{\det \bL},\\
S_{Nj,0}^-&=\frac{(L_{21}L_{11}^+-L_{11}L_{21}^+)i\xi_j}{\det \bL},
&S_{NN,0}^-&=\frac{L_{21}L_{12}^+-L_{11}L_{22}^+}{\det \bL}
	\end{aligned}
\end{equation*}
for any $j=1,\dots,N-1.$
Then inserting \eqref{eq:cof_3} into \eqref{eq:2.15-2}, we obtain that
\begin{equation}\label{eq:cof_4}
\begin{aligned}
\beta_{+N}=&\sum_{J=1}^N \big( S_{NJ,-1}^+\widehat{h}_J(0)
+S_{NJ,0}^+\widehat{k}_{J}(0) \big),\\
\beta_{-N}^b=&\sum_{J=1}^N \big( S_{NJ,-1}^b\widehat{h}_J(0)
+S_{NJ,0}^b\widehat{k}_{J}(0) \big)
	\end{aligned}
\end{equation}
with
\begin{equation*}
\begin{aligned}
S_{NJ,-1}^+=&-(A+B_-)M_-^2(-b)P^{0}_{J,0}\\
&+\big( 1-e^{-2B_-b}+2e^{-B_-b}B_-M_-(-b) \big)S_{NJ,-1}^-,\\
S_{NJ,0}^+=&\delta_{JN}-(A+B_-)M_-^2(-b)P^{0}_{J,1}\\
&+\big( 1-e^{-2B_-b}+2e^{-B_-b}B_-M_-(-b) \big)S_{NJ,0}^-,\\ 
S_{NJ,-1}^b=& M_-(-b)P^{0}_{J,0}-e^{-B_-b} S_{NJ,-1}^-, \\
S_{NJ,0}^b =& M_-(-b)P^{0}_{J,1}-e^{-B_-b} S_{NJ,0}^-
\end{aligned}
\end{equation*}
for $J=1,\dots,N.$ 
\medskip


From the last two equations of \eqref{eq:2.12},  we have
\begin{equation}\label{eq:2.17-1}
\begin{aligned}
\beta_{-j}^b=&-e^{-B_-b}\beta_{-j}^0-(B_--A)M_-(-b)\alpha_{-j}^0,\\
\beta_{+j}=&(1-e^{-2B_-b})\beta_{-j}^0+\widehat{k}_j(0)
-e^{-B_-b}(B_--A)M_-(-b)\alpha_{-j}^0\\
&+(B_--A)M_-(-b)\alpha_{-j}^b
	\end{aligned}
\end{equation}
for $j=1,\dots,N-1.$  Then inserting \eqref{eq:2.17-1} into $\eqref{eq:2.12}_1$ implies that 
\begin{equation*}
\begin{aligned}
\beta_{-j}^0=\frac{1}{D(B_{\pm})}\Big(&
-\widehat{h}_j(0)-\mu_+B_+\widehat{k}_j(0)
-\mu_+(B_+-A_+)\alpha_{+j}+\mu_+i\xi_j\beta_{+N}\\
&+\big( (\mu_+B_+-\mu_-B_-)e^{-B_-b}M_-(-b)-\mu_-\big)(B_--A) \alpha_{-j}^0
-\mu_-i\xi_j  \beta_{-N}^0\\
&  +((\mu_{-}B_--\mu_+B_+)M_-(-b)+\mu_{-}e^{-Ab})(B_--A) \alpha_{-j}^b \\
&-\mu_- i\xi_j M_-(-b) (B_--A) \alpha_{-N}^b 
-\mu_-i\xi_j e^{-B_-b} \beta_{-N}^b \Big),
	\end{aligned}
\end{equation*}
where we denote for simplicity 
$$D(B_{\pm})=\mu_+B_+(1-e^{-2B_-b})+\mu_-B_-(1+e^{-2B_-b}).$$
Then \eqref{eq:cof_1}, \eqref{eq:cof_2}, \eqref{eq:cof_3} and \eqref{eq:cof_4} furnish that 
\begin{equation}\label{eq:cof_5}
\beta_{-j}^0=\sum_{\ell=1}^N \big( S_{j\ell,-1}^-\widehat{h}_\ell(0)
+S_{j\ell,0}^-\widehat{k}_{\ell}(0) \big)
\end{equation}
for $j=1,\dots,N-1,$ provided with
\begin{equation*}
\begin{aligned}
S_{j\ell,-1}^- =\frac{1}{D(B_{\pm})}\Big(&
-\delta_{j\ell}
+\mu_+\frac{i\xi_j(B_+-A_+)}{A_+B_+-A^2}P_{\ell,0}^{+}
+\mu_+i\xi_j S_{N\ell,-1}^+\\
&-\big( (\mu_+B_+-\mu_-B_-)e^{-B_-b}M_-(-b)-\mu_-\big)\frac{i\xi_j}{A}
P_{\ell,0}^{0}-\mu_-i\xi_j   S_{N\ell,-1}^-\\
&
 -\big(  (\mu_{-}B_--\mu_+B_+)M_-(-b)+\mu_{-}e^{-Ab}\big) \frac{i\xi_j}{A}P_{\ell,0}^{b}\\
&-\mu_- i\xi_j M_-(-b)P_{\ell,0}^{b} 
-\mu_-i\xi_j e^{-B_-b} S_{N\ell,-1}^b\Big),\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
S_{j\ell,0}^-=\frac{1}{D(B_{\pm})}\Big(&
-\mu_+B_+\delta_{j\ell}
+\mu_+\frac{i\xi_j(B_+-A_+)}{A_+B_+-A^2}P_{\ell,1}^{+}
+\mu_+i\xi_j S_{N\ell,0}^+\\
&-\big( (\mu_+B_+-\mu_-B_-)e^{-B_-b}M_-(-b)-\mu_-\big)\frac{i\xi_j}{A}
P_{\ell,1}^{0}-\mu_-i\xi_j  S_{N\ell,0}^- \\
&
 -\big( (\mu_{-}B_--\mu_+B_+)M_-(-b)+\mu_{-}e^{-Ab}\big) \frac{i\xi_j}{A}
P_{\ell,1}^{b}\\
&-\mu_- i\xi_j M_-(-b)P_{\ell,1}^{b}
-\mu_-i\xi_j e^{-B_-b} S_{N\ell,0}^b\Big).
\end{aligned}
\end{equation*}
Then combining \eqref{eq:2.17-1} and \eqref{eq:cof_5} implies that
\begin{equation}\label{eq:cof_6}
\begin{aligned}
\beta_{-j}^b&=\sum_{\ell=1}^N \big( S_{j\ell,-1}^b\widehat{h}_\ell(0)
+S_{j\ell,0}^b\widehat{k}_{\ell}(0) \big),\\
\beta_{+j}&=\sum_{\ell=1}^N \big( S_{j\ell,-1}^+\widehat{h}_\ell(0)
+S_{j\ell,0}^+\widehat{k}_{\ell}(0) \big)
\end{aligned}
\end{equation}
with 
\begin{equation*}
\begin{aligned}
S_{j\ell,-1}^b=&-e^{-B_-b} S_{j\ell,-1}^-
+M_-(-b)\frac{i\xi_j}{A}
P_{\ell,0}^{0},\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
S_{j\ell,0}^b=&-e^{-B_-b}
S_{j\ell,0}^-
+M_-(-b)\frac{i\xi_j}{A}P_{\ell,1}^{0},\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
S_{j\ell,-1}^+=&(1-e^{-2B_-b}) S_{j\ell,-1}^-
+e^{-B_-b}M_-(-b)\frac{i\xi_j}{A} P_{\ell,0}^{0}
-M_-(-b)\frac{i\xi_j}{A}P_{\ell,0}^{b},\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
S_{j\ell,0}^+=&\delta_{j\ell}
+(1-e^{-2B_-b}) S_{j\ell,0}^-
+e^{-B_-b}M_-(-b)\frac{i\xi_j}{A} P_{\ell,1}^{0}
-M_-(-b)\frac{i\xi_j}{A} P_{\ell,1}^{b}.
\end{aligned}
\end{equation*}
\medskip

At last, let us introduce the symbols
\begin{gather*}
	R_{j\ell,0}^+=\frac{(B_+-A_+)i\xi_j}{A_+B_+-A^2}P_{\ell,0}^+,
	\quad R_{N\ell,0}^+=\frac{(B_+-A_+)A_+}{A_+B_+-A^2}P_{\ell,0}^+,\\
	R_{j\ell,1}^+=\frac{(B_+-A_+)i\xi_j}{A_+B_+-A^2}P_{\ell,1}^+,
	\quad R_{N\ell,1}^+=\frac{(B_+-A_+)A_+}{A_+B_+-A^2}P_{\ell,1}^+,\\
  R_{j\ell,0}^-=-\frac{i\xi_j}{A}P_{\ell,0}^{0},\quad R_{N\ell,0}^-=-P_{\ell,0}^{0},\quad R_{j\ell,1}^-=-\frac{i\xi_j}{A}P_{\ell,1}^{0},\quad R_{N\ell,1}^-=-P_{\ell,1}^{0},\\
T_{j\ell,0}^-=-\frac{i\xi_j}{A}P_{\ell,0}^{b},\quad T_{N\ell,0}^-=P_{\ell,0}^{b},\quad T_{j\ell,1}^-=-\frac{i\xi_j}{A}P_{\ell,1}^{b},\quad T_{N\ell,1}^-=P_{\ell,1}^{b}
\end{gather*}
for $j=1,\dots,N-1$ and $\ell=1,\dots,N.$
Then substituting \eqref{eq:cof_1},  \eqref{eq:cof_2}, \eqref{eq:cof_3},
\eqref{eq:cof_4}, \eqref{eq:cof_5} and \eqref{eq:cof_6} into \eqref{eq:2.8} yields 
\begin{equation}\label{eq:2.27}
\widehat{v}_{+J}=\sum_{k=1}^{2}\widehat{v}_{Jk}^+,\quad \widehat{v}_{-J}=\sum_{k=1}^{4}\widehat{v}_{Jk}^-
\end{equation}
with
\begin{equation}\label{eq:all_symbol}
\begin{aligned}
&\widehat{v}_{J1}^{\pm}=	M_{\pm}(x_N)\sum_{\ell=1}^N\big[R_{J\ell,0}^{\pm}\widehat{h}_\ell(0)+R_{J\ell,1}^{\pm}\widehat{k}_\ell(0)\big],\\
		&\widehat{v}_{J2}^{\pm}=e^{\mp B_{\pm}x_N}\sum_{\ell=1}^N\big[S_{J\ell,-1}^{\pm}\widehat{h}_\ell(0)+S_{J\ell,0}^{\pm}\widehat{k}_\ell(0)\big],\\
		&\widehat{v}_{J3}^-=M_-(-x_N-b)\sum_{\ell=1}^N\big[T_{J\ell,0}^-\widehat{h}_\ell(0)+T_{J\ell,1}^-\widehat{k}_\ell(0)\big],\\
		&\widehat{v}_{J4}^-=e^{-B_-(x_N+b)}\sum_{\ell=1}^N\big[S_{J\ell,-1}^b\widehat{h}_\ell(0)+S_{J\ell,0}^b\widehat{k}_\ell(0)\big].
	\end{aligned}
\end{equation}
Thus the derivation of the solution formula of \eqref{eq:2.4} is complete up to taking the inverse Fourier transformation  with respect to $\xi^\prime$.






