\section{Analysis of the Lopatinski determinant} 
\label{sec:det}
Recall the definition of the matrix 
\begin{equation*}
\bL= \begin{pmatrix}
L_{11} & L_{12} \\
L_{21} & L_{22} 
\end{pmatrix}
\end{equation*}
whose the entries $L_{jk}$ ($j,k=1,2$) are given by \eqref{eq:Lij}.
For simplicity, let us write 
\begin{equation}\label{def:LN}
	L_{jk}=\wt L_{jk} + N_{jk} 
\end{equation}
with
\begin{equation}\label{def:N_jk}
	\begin{aligned}
	\wt L_{jk}=&L_{jk}^++L_{jk}^{0-},\\
		N_{11}=&L_{11}^+\big(-e^{-2B_-b}-2e^{-B_-b}AM_-(-b)\big)
		-L_{11}^{b-}e^{-B_-b}+\fL_1,\\
		N_{12}=&L_{12}^+\big(-e^{-2B_-b}+2e^{-B_-b}B_-M_-(-b)\big)
		-L_{12}^{b-}e^{-B_-b}+B_-\fL_1,\\
		N_{21}=&L_{21}^+\big(-e^{-2B_-b}-2e^{-B_-b}AM_-(-b)\big)
		-L_{21}^{b-}e^{-B_-b}+\fL_2,\\
		N_{22}=&L_{22}^+\big(-e^{-2B_-b}+2e^{-B_-b}B_-M_-(-b)\big)
		-L_{22}^{b-}e^{-B_-b}+B_-\fL_2.
	\end{aligned}
\end{equation}
Then we set $\det \wt \bL=\wt L_{11}\wt L_{22}-\wt L_{12}\wt L_{21}$
for $\wt\bL=[\wt L_{jk}].$
 Moreover, it is not hard to see that
\begin{equation}\label{eq:det_whole}
	\det \bL = \wt L_{11}\wt L_{22}-\wt L_{12}\wt L_{21}+h(A_{\pm},B_{\pm})
\end{equation}
with 
\begin{equation*}
	h(A_{\pm},B_{\pm})= \wt L_{11} N_{22}+ \wt L_{22}N_{11}
	+N_{11}N_{22}-\wt L_{12}N_{21}-\wt L_{21}N_{12}-N_{12}N_{21}.
\end{equation*}
\smallbreak

The main goal of this section is to derive the lower bound of $\det \bL,$
which plays a fundamental role in our analysis. Indeed, we shall prove that
\begin{lem}\label{lem:3.1}
Let $\det \bL$ be given in \eqref{eq:det_whole}. 
Then there exists a positive $C$ depending on 
$\mu_{\pm},$ $\nu_+,$ $\varepsilon,$ 
$\gamma_{1\pm},$ $\gamma_{2+}$,  $\lambda_0$ and $b$ such that
	\begin{equation}\label{eq:3.3}
		|\det\bL|\geq C\big(|\lambda|^{1/2}+A\big)^3
	\end{equation}
	for any $(\lambda,\xi')\in\widetilde{\Gamma}_{\varepsilon,\lambda_0}
    =\Gamma_{\varepsilon,\lambda_0}\times \big(\BR^{N-1}\backslash\{0\}\big)$.
\end{lem}


\subsection{Some results on the multipliers}
In this subsection, we begin with the definition of the classes of symbols (see \cite[p.592]{ShiShi2012} for instance).
\begin{dfn}
	Let $\Lambda\subset \mathbb{C}, s\in \BR $ and $\kappa^\prime\in \BN_0^{N-1}.$
	Let $m(\lambda,\xi^\prime)$ be a smooth function defined on the domain $\widetilde{\Lambda}=\Lambda\times (\BR^{N-1}\backslash\{0\})$.
	\begin{enumerate}[label=(\roman*)]
		\item The symbol $m(\lambda,\xi^\prime)$ is called a multiplier of order $s$ with type $1$ on $\widetilde{\Lambda}$, denoted by $m\in\bM_{s,1}(\widetilde{\Lambda})$, if there exists a constant $C_{\kappa^\prime}$ such that
		$$\big|\pd_{\xi^\prime}^{\kappa^\prime}(\tau\pd_{\tau})^{\ell}
		m(\lambda,\xi^\prime)\big|\leq C_{\kappa^\prime}
		(|\lambda|^{1/2}+|\xi^\prime|)^{s-|\kappa^\prime|}$$
		for any $(\lambda,\xi^\prime)\in\widetilde{\Lambda}$ and $\ell=0,1.$

		\item The symbol $m(\lambda,\xi^\prime)$ is called a multiplier of order $s$ with type $2$ on $\widetilde{\Lambda}$, denoted by $m\in\bM_{s,2}(\widetilde{\Lambda})$, if there exists a constant $C_{\kappa^\prime}$ such that
		$$\big|\pd_{\xi^\prime}^{\kappa^\prime}(\tau\pd_{\tau})^{\ell}
		m(\lambda,\xi^\prime)\big|\leq C_{\kappa^\prime}
		(|\lambda|^{1/2}+|\xi^\prime|)^{s}|\xi^\prime|^{-|\kappa^\prime|}$$
		for any $(\lambda,\xi^\prime)\in\widetilde{\Lambda}$ and $\ell=0,1.$	
	\end{enumerate}
For any $m\in\bM_{s,i}(\widetilde{\Lambda})$, $i=1,2$, we denote $M(m,\Lambda) =\max_{|\kappa'|\leq N}C_{\kappa'}$.
\end{dfn}

\begin{remark}\label{rmk:4.2}
Let $s_1,s_2 \in \BR$ and $i=1,2$. It is easy to see that 
\begin{enumerate}[label=(\roman*)]
\item $m_1m_2\in\bM_{s_1+s_2,1}(\widetilde{\Lambda})$ for $m_i\in\bM_{s_i,1}(\widetilde{\Lambda})$;
\item $m_1m_2\in\bM_{s_1+s_2,2}(\widetilde{\Lambda})$ for $m_i\in\bM_{s_i,2}(\widetilde{\Lambda})$;
\item  $m_1m_2\in\bM_{s_1+s_2,2}$ for $m_1\in\bM_{s_1,1}(\widetilde{\Lambda})$ and $m_2\in\bM_{s_2,2}(\widetilde{\Lambda}).$
\end{enumerate}
\end{remark}

To study the characteristic roots in \eqref{eq:2.7}, we recall the following lemma.
\begin{lem}[{\cite[Lemma 3.1]{GS2014}}]
\label{lem:B_comp}
Let $0<\ep<\pi/2,$ $\lambda_0,$ $\mu_{\pm},$ $\nu_+>0$, $s\geq1$. Then the following assertions hold true.
\begin{enumerate}[label=(\arabic*)]	
\item For any $\lambda\in\Sigma_{\ep},$ $\alpha,\beta>0$, 
we have 
$$|\alpha\lambda+\beta|\geq \sin(\ep/2)(\alpha|\lambda|+\beta).$$

\item There exists a constant $0<\ep^\prime<\pi/2$ such that 
	$$(s\mu_++\nu_++\delta)^{-1}\lambda\in\Sigma_{\ep^\prime},\quad \forall\,\lambda\in\Gamma_{\ep,\lambda_0},$$
where the choice of $\ep^\prime$ depends on 
$s,$ $\mu_+,$ $\nu_+,$ $\gamma_{1+},$ $\gamma_{2+},$ $\lambda_0,$ $\delta_0$ and $\ep.$

\item For any $\lambda\in\Gamma_{\ep,\lambda_0}$, there exist constants $c,C>0$ depending on 
$s,$ $\mu_+,$ $\nu_+,$ $\gamma_{1+},$ $\gamma_{2+},$ $\lambda_0,$ $\delta_0$ and $\ep$ such that
	$$c(|\lambda|+|\xi^\prime|^2)\leq \big|(s\mu_++\nu_++\delta)^{-1}\lambda+|\xi^\prime|^2\big|\leq C(|\lambda|+|\xi^\prime|^2).$$
\end{enumerate}
\end{lem}

\begin{lem}\label{lem:4.3}
Let $0<\varepsilon<\pi/2$ and $\lambda_0,$ $\mu_{\pm},\nu_+>0.$ Then the following assertions hold true.	
\begin{enumerate}[label=(\arabic*)]	
\item Let the letter $M$ belong to $\{A_+,B_{\pm}, A_++B_+, \mu_+B_++\mu_-B_-\}.$
There exist positive constants $c$ and $C$ depending on $\mu_\pm,\nu_+,\gamma_{1\pm}, \gamma_{2+} ,\lambda_0$ and $\varepsilon$ such that
\begin{equation*}
c(|\lambda|^{1/2}+|\xi^\prime|)\leq |M|\leq C (|\lambda|^{1/2}+|\xi^\prime|)
\end{equation*}
for any $(\lambda,\xi^\prime)\in\widetilde{\Gamma}_{\varepsilon,\lambda_0}.$ 
Moreover, $M^s\in \bM_{s,1}(\widetilde{\Gamma}_{\varepsilon,\lambda_0})$ for any $s\in\BR.$

\item Let the multi-index $\alpha'\in\BN_0^{N-1}, \ell=0,1,$ and $a>0.$ 
   \begin{enumerate}
     \item There exist positive constants 
      $C_{\alpha',-}=C_{\alpha',\varepsilon,\mu_{-},\gamma_{1-}}$ and
       $c_{-}=c_{\varepsilon,\mu_{-},\gamma_{1-}}$ such that
      \begin{equation*}
          \begin{aligned}
         \big|\pd_{\xi^\prime}^{\alpha^\prime}(\tau\pd_{\tau})^{\ell}e^{-B_-a}\big|
      &\leq C_{\alpha',-}\big(|\lambda|^{1/2}+A\big)^{-|\alpha'|}e^{-c_-(|\lambda|^{1/2}+A)a}, \\
    \big|\pd_{\xi^\prime}^{\alpha^\prime}e^{-Aa}\big|
    &\leq C_{\alpha'}A^{-|\alpha'|}e^{-(1/2)Aa},\\
      \big|\pd_{\xi^\prime}^{\alpha^\prime}(\tau\pd_{\tau})^{\ell}M_-(-a)\big|
      &\leq C_{\alpha',-} \big(a \,\,\text{or}\,\,|\lambda|^{-1/2}\big) A^{-|\alpha'|}e^{-c_- Aa}
      \end{aligned}
 \end{equation*}
for any $(\lambda,\xi')\in\wt \Sigma_{\ep,\lambda_0}.$ 
 \item There exist positive constants 
 $C_{\alpha',+}=C_{\alpha',\varepsilon,\mu_{+},\nu_+,\gamma_{1+},\gamma_{2+}}$ and $c_+=c_{\varepsilon,\mu_{+},\nu_+,\gamma_{1+},\gamma_{2+}}$ such that 
 \begin{equation*}
            \begin{aligned}
     \big|\pd_{\xi^\prime}^{\alpha^\prime}(\tau\pd_{\tau})^{\ell}(e^{-B_+a})\big|
     &\leq C_{\alpha',+}(|\lambda|^{1/2}+A)^{-|\alpha'|}e^{-c_+ (|\lambda|^{1/2}+A)a},\\
   \big|\pd_{\xi^\prime}^{\alpha^\prime}(\tau\pd_{\tau})^{\ell}M_+(a)\big|
   &\leq C_{\alpha',+} a A^{-|\alpha'|}e^{- c_+(|\lambda|^{1/2}+A)a}
            \end{aligned}
        \end{equation*}
for any $(\lambda,\xi')\in\wt \Gamma_{\ep,\lambda_0}.$ 
    \end{enumerate}


\item Let $i,j=1,2$ and let the letter $k$ belong to $\{+,0-,b-\}.$ Recalling the notations in \eqref{eq:2.15} and \eqref{eq:det_whole}, we have 
\begin{equation*}
   L_{i1}^k\in\bM_{1,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}),\quad 
  L_{i2}^k\in\bM_{2,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0})
  \quad \text{and}\quad 
  \det \bL\in\bM_{3,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}).
\end{equation*}
		 Moreover, $M(L_{ij}^k,\Gamma_{\varepsilon,\lambda_0})$ and $M(\det\bL,\Gamma_{\varepsilon,\lambda_0})$ depend solely on $\varepsilon,\mu_{\pm},\nu_+,\gamma_{1\pm},\gamma_{2+},\lambda_0$.
	\end{enumerate}	
\end{lem}
\begin{proof}
The assertion (1) is standard in view of Lemma \ref{lem:B_comp} above, while the bounds in assertion (2) have been proved by \cite[Lemma 5.3]{ShiShi2012} and \cite[p.468]{ES2013} respectively. Finally, using Remark \ref{rmk:4.2} and the assertions (1)-(2), it is not hard to prove the last assertion and we omit the details.
\end{proof}


\subsection{Proof of Lemma \ref{lem:3.1}}
\label{subsec:lemma_3.1}
The proof of Lemma \ref{lem:3.1} will be divided into four steps. 
\medskip

{\bf Step 1.} We shall verify the bound \eqref{eq:3.3} when $(\lambda,\xi')$ locates in the area
$$\CD_1 = \{(\lambda,\xi')\in
\widetilde{\Gamma}_{\varepsilon,\lambda_0}:
|\xi'|\leq r_{1}\}$$
for some sufficiently small positive constant $r_{1}<1.$ 
\medskip

Firstly, we claim that there exists some (large enough) positive constant
$d_1$ such that 
\begin{equation}\label{eq:c11}
	|\det\bL| \gtrsim (|\lambda|^{1/2}+A)^3  \quad 
	\text{for}\,\,\, 0<|\xi'|\leq 1
	\,\,\,\text{and}\,\,\, |\lambda|\geq d_1.
\end{equation}
To prove \eqref{eq:c11},  we rewrite $\det \bL$ as follows:
\begin{equation}\label{eq:rdet}
	\det\bL =H_1(A_{\pm},B_{\pm})+h_1(A_{\pm},B_{\pm})
\end{equation}
with
\begin{equation}\label{eq:h(A,B)}
	\begin{aligned}
		H_1(A_{\pm},B_{\pm})=&(L_{11}^++L_{11}^{0-})
		\big( L_{22}^{0-}+B_-M_-(-b)L_{22}^{b-} \big),\\
		h_1(A_{\pm},B_{\pm})=
		&L_{11}\Big( L_{22}^+(1-e^{-2B_-b}+2e^{-B_-b}B_-M_-(-b))
		-L_{22}^{b-}e^{-B_-b}\\
		&\quad\quad-(AL_{21}^++L_{22}^+)(A+B_-)B_-M_-^2(-b)
		-L_{21}^{b-}AB_-M_-(-b) \Big)\\
		&+\big(L_{22}^{0-}+B_-M_-(-b)L_{22}^{b-}\big)
		N_{11}-L_{12}L_{21}.
	\end{aligned}
\end{equation}
Above, the formula of $N_{11}$ is given by \eqref{def:N_jk}.
\smallbreak

Notice the fact that
\begin{equation*}
	B_-M_-(-b)=e^{-B_-b}+AM_-(-b)-e^{-Ab}. 
\end{equation*}
Then we use \eqref{eq:2.15} to obtain that
\begin{equation*}
	\begin{aligned}
			L_{11}^++L_{11}^{0-}
		=&-(\mu_{+}B_++\mu_{-}B_-)
		-\mu_{+}\frac{(B_+-A_+)A^2}{A_+B_+-A^2}-\mu_{-}A,\\
		L_{22}^{0-}+B_-M_-(-b)L_{22}^{b-}
		=&\,\, L_{22}^{0-}-e^{-Ab} L_{22}^{b-}
		+ \big( e^{-B_-b}+AM_-(-b) \big)  L_{22}^{b-}\\
		=&-\mu_-(1+e^{-2Ab})B_-^2+R_1(A_\pm,B_\pm),
	\end{aligned}
\end{equation*}
where $R_1(A_\pm,B_\pm)$ is given by
\begin{equation*}
	\begin{aligned}
		R_1(A_\pm,B_\pm)=&-\mu_{-}AB_-+2\mu_-A^2B_-M_-(-b)e^{-Ab}\\
		&-\mu_-AB_-e^{-2Ab}
		+\big( e^{-B_-b}+AM_-(-b) \big)  L_{22}^{b-}.
	\end{aligned}
\end{equation*}
Thus we see that 
\begin{equation}\label{eq:rwdet}
	\begin{aligned}
		H_1(A_{\pm},B_{\pm})
		=&\mu_{-}\big(1+e^{-2Ab}\big)B_-^2
		\big(\mu_{+}B_++\mu_{-}B_-\big)+R_2(A_\pm,B_\pm)
	\end{aligned}
\end{equation}
with
\begin{equation*}
	\begin{aligned}
		R_2(A_\pm,B_\pm)
		=&\Big( \mu_{+}\frac{(B_+-A_+)A^2}{A_+B_+-A^2}+\mu_{-}A \Big)
		\mu_-(1+e^{-2Ab})B_-^2\\
		&+(L_{11}^++L_{11}^{0-}) R_1(A_\pm,B_\pm).
	\end{aligned}
\end{equation*}
Moreover, Lemma \ref{lem:4.3} yields
\begin{equation*}
	\big| \mu_{-}\big(1+e^{-2Ab}\big)B_-^2
	\big(\mu_{+}B_++\mu_{-}B_-\big) \big| \gtrsim (|\lambda|^{1/2}+A)^3.
\end{equation*}
\smallbreak 

To find the upper bound of the remainder term $R_2(A_\pm,B_\pm),$ Lemma \ref{lem:4.3} yields 
\begin{equation}\label{eq:est}
	\begin{aligned}
		&|e^{-aB_-b}| \lesssim  e^{-ca(|\lambda|^{1/2}+A)b}
		\lesssim  e^{-ca|\lambda|^{1/2}b}   \quad (a>0),\\ 
		&|M_-(-b)| \lesssim \frac{1}{|\lambda|^{1/2}}e^{-cAb},\\
		&|A_+M_-(-b)|+|B_\pm M_-(-b)|\lesssim \frac{|\lambda|^{1/2}+A}{|\lambda|^{1/2}}e^{-cAb}.
	\end{aligned}
\end{equation}
for some positive constant $c=c_{\varepsilon,\mu_-,\gamma_{1-}}.$ 
As in \cite[Section 4]{KSS2014}, we rewrite $L^+_{jk}$ in \eqref{eq:2.15} by
\begin{equation}\label{eq:Lkks}
	\begin{aligned}
		&L_{11}^+=-\frac{\mu_{+}(\mu_{+}+\nu_++\delta)}{2\mu_{+}+\nu_++\delta}A_+P,\quad L_{12}^+=-\mu_{+}A^2(2-\frac{\mu_{+}+\nu_++\delta}{2\mu_{+}+\nu_++\delta}P),\\
		&L_{21}^+=-\Big(\frac{2\mu_{+}(\nu_++\delta)}{2\mu_{+}+\nu_++\delta}\frac{A_+}{B_++A_+}-\frac{\mu_{+}(\nu_+-\mu_{+}+\delta)}{2\mu_{+}+\nu_++\delta}\Big)AP,\\
		&L_{22}^+=-\frac{\mu_{+}(\mu_{+}+\nu_++\delta)}{2\mu_{+}+\nu_++\delta}AB_+P
	\end{aligned}
\end{equation}
with $$P(\lambda,\xi')=\frac{A_+B_++A^2}{\gamma_{1+}(2\mu_{+}+\nu_++\delta)\lambda+A^2}\in\bM_{0,1}.$$ 

For $s\in \{\nu_+,\mu_++\nu_+,\nu_+-\mu_{+}\}$, we have
\begin{equation*}
	\Big|\frac{s+\delta}{2\mu_++\nu_++\delta} \Big|\lesssim 1.
\end{equation*}
Then we see from \eqref{eq:2.15}, \eqref{eq:est} and \eqref{eq:Lkks} that
\begin{equation}\label{est:Ljk_1}
	\begin{aligned}
		& |L_{22}^{0-}| + |L_{22}^{b-}|\lesssim  |\lambda|,\\
		& |L_{11}^+|+|L_{22}^+| +|L_{11}^{0-}|  +|L_{12}^{0-}|
		+|L_{21}^{0-}|+ |L_{21}^{b-}|+|\fL_2| \lesssim |\lambda|^{1/2},\\
		& |L_{12}^+| +|L_{21}^+|+|L_{12}^{b-}|+|\fL_1| \lesssim 1,\\
		& |L_{11}^{b-}|   \lesssim |\lambda|^{-1/2}
	\end{aligned}
\end{equation}
for any $0<|\xi'|\leq 1 \leq  |\lambda|,$
which yield
\begin{equation*}
\begin{aligned}
& |L_{11}|+|L_{12}|+|L_{21}|+|R_1(A_\pm,B_\pm)|\lesssim |\lambda|^{1/2}, \\
&   |L_{22}| + |R_2(A_\pm,B_\pm)| \lesssim |\lambda|.
\end{aligned}
\end{equation*}
Furthermore, recall the definition of $h_1(A_{\pm},B_{\pm})$ in \eqref{eq:h(A,B)}, and we use \eqref{eq:est} and \eqref{est:Ljk_1} to obtain that
\begin{equation*}
	|h_1(A_{\pm},B_{\pm})| \lesssim |\lambda|+ |\lambda| |N_{11}| \lesssim  |\lambda|.
\end{equation*}
Thus summing up the estimates above, we can conclude that
\begin{equation}\label{eq:c11-1}
|\det\bL |\geq |H_1(A_{\pm},B_{\pm})|-C_1 |\lambda|\geq C_2^{-1}(|\lambda|^{1/2}+A)^3-C_2 |\lambda|
\end{equation}
for any $0<|\xi'|\leq 1 \leq  |\lambda|.$
Then we easily see \eqref{eq:c11} follows from 
\eqref{eq:c11-1} by choosing the constant $d_1$ large enough. 
\medskip

Now, we fix the constant $d_1$ chosen in \eqref{eq:c11}.
Let us introduce the function 
$$F(A,\lambda)=\det\bL$$ 
for any $\lambda\in \CK=\{z\in\Gamma_{\ep,\lambda_0}:\,|z|\leq d_1\}.$
It is easy to see that 
\begin{gather*}
	\fL_1|_{A=0}=L_{12}|_{A=0}=0, \quad  
	 \fL_2|_{A=0}=(\mu_{-}\gamma_{1-})^{1/2}\lambda^{1/2}(e^{-b\sqrt{\gamma_{1-}(\mu_{-})^{-1}\lambda}}-1),\\
	L_{11}|_{A=0}=-(\mu_+\gamma_{1+})^{1/2} \lambda^{1/2}
		\big( 1-e^{-2b\sqrt{ \gamma_{1-}(\mu_-)^{-1}\lambda}}  \big)
		-(\mu_-  \gamma_{1-})^{1/2} \lambda^{1/2}
		\big(1+e^{-2b\sqrt{ \gamma_{1-}(\mu_-)^{-1}\lambda}}\big),\\
	L_{22}|_{A=0} = -2\gamma_{1-}\lambda.
\end{gather*}
Thus we have 
\begin{equation*}
	\begin{aligned}
		F(0,\lambda)& = (L_{11} L_{22})|_{A=0} \\
		&=2  \gamma_{1-} \lambda^{3/2} \Big( (\mu_+\gamma_{1+})^{1/2} 
		\big( 1-e^{-2b\sqrt{ \gamma_{1-}(\mu_-)^{-1}\lambda}}  \big)
		+(\mu_-  \gamma_{1-})^{1/2} 
		\big(1+e^{-2b\sqrt{ \gamma_{1-}(\mu_-)^{-1}\lambda}} \big) \Big).
	\end{aligned}
\end{equation*}
 As $|\sqrt{\lambda}|\geq \lambda_0^{1/2},$ we have 
\begin{equation*}
\Big| e^{-2b\sqrt{ \gamma_{1-}(\mu_-)^{-1}\lambda}} \Big| 
\leq c' \quad \text{and}\quad
|F(0,\lambda)| \geq 2c''
\end{equation*}
with 
\begin{equation*}
\begin{aligned}
c' &=\exp \Big(  -2b
	\big(\gamma_{1-}(\mu_-)^{-1}\lambda_0\big)^{1/2}\Big),
	\\
c''&=\gamma_{1-} \lambda_0^{3/2}   (1-c') 
	\big( (\mu_+\gamma_{1+})^{1/2}
	+(\mu_-  \gamma_{1-})^{1/2} \big) .	
\end{aligned}
\end{equation*} 
By the continuity of $F(A,\lambda)$ and the compactness of the set $\CK,$
there exists a small positive constant $r_1$ such that 

\begin{equation}\label{es:C1-2}
	|\det \bL| =|F(A,\lambda)|\geq  c''
	\geq c''\big( d_{1}^{1/2}+r_1 \big)^{-3}\big(|\lambda|^{1/2}+A\big)^3
\end{equation}
for any $(\lambda,A) \in [0, r_1]\times \CK.$ 
\smallbreak

Therefore, the bound \eqref{eq:3.3} holds for any $(\lambda,\xi')\in \CD_1$ thanks to \eqref{eq:c11} and \eqref{es:C1-2}.
\medskip

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
{\bf Case 2.}
For the parameter $r_1$ given in Case 1, we introduce the set 
$$\CD_2 = \{(\lambda,\xi')\in
\widetilde{\Gamma}_{\varepsilon,\lambda_0}:
|\xi'|\geq  r_{1},\,\,\, R_2|\xi'|\leq |\lambda|^{1/2}\}.$$
Here, $R_2$ is a fixed very large positive number. 
In this case,  we know from \cite[Section 5]{KSS2014} that
\begin{equation}\label{es:C2-1}
	\begin{aligned}
		&A_+=(\mu_++\nu_++\delta)^{-1/2}(\gamma_{1+}\lambda)^{1/2}\big(1+O(R_2^{-1})\big),\\ 
		&B_{\pm}=(\mu_{\pm})^{-1/2}(\gamma_{1\pm}\lambda)^{1/2}\big(1+O(R_2^{-1})\big),\\
		&L_{11}^+=-(\mu_+\gamma_{1+})^{1/2}\lambda^{1/2}\big(1+O(R_2^{-1})\big),
		\quad     L_{12}^+=-A^2 O(1),\\
		&L_{21}^+=-A\,O(1),\quad 
		L_{22}^+=-\lambda O(R_2^{-1}),\\
		&L_{11}^{0-}=L_{21}^{0-}=-(\mu_{-}\gamma_{1-})^{1/2}\lambda^{1/2}
		\big(1+O(R_2^{-1})\big),\quad   
		L_{12}^{0-}=-\lambda O(R_2^{-1}),\\
		& L_{22}^{0-}=-\gamma_{1-}\lambda\big(1+O(R_2^{-1})\big).
	\end{aligned}
\end{equation}
On the other hand, according to \eqref{eq:est} and \eqref{es:C2-1}, we have
\begin{equation}\label{es:C2-2}
\begin{aligned}
 L_{11}^{b-}&=(\mu_{-}\gamma_{1-}\lambda)^{1/2}e^{-B_-b}\big(1+O(R_2^{-1})\big)
+\lambda^{1/2}e^{-cAb}O(R_2^{-2}), \\
L_{12}^{b-}&=\lambda  O(R_2^{-1}),\\
L_{21}^{b-}&=-(\mu_{-}\gamma_{1-}\lambda)^{1/2}e^{-Ab}
+\lambda^{1/2}e^{-cAb} O(R_2^{-1}),\\
L_{22}^{b-}&=\gamma_{1-}\lambda e^{-Ab}\big(1+O(R_2^{-1})\big)+\lambda e^{-cAb} O(R_2^{-2}).
	\end{aligned}
\end{equation}


Next, we use \eqref{eq:rdet}, \eqref{eq:rwdet} and \eqref{es:C2-1} to obtain 
\begin{equation*}
	\begin{aligned}
		|\lambda|^{-3/2} |\det\bL| & \geq |\lambda|^{-3/2} |H_1(A_{\pm},B_{\pm})|
		- |\lambda|^{-3/2}|h_1(A_{\pm},B_{\pm})| \\
		&\geq 2c-|\lambda|^{-3/2} \big( |h_1(A_{\pm},B_{\pm})| +|R_2(A_{\pm},B_{\pm})|  \big)
	\end{aligned}
\end{equation*}
for some constant $c>0.$
In fact, we can prove that there exists a constant $C_2$ such that
\begin{equation}\label{clm:c2}
	|\lambda|^{-3/2} \big( |h_1(A_{\pm},B_{\pm})| +|R_2(A_{\pm},B_{\pm})|  \big)
	\leq C_2 \big(R_2^{-1}+e^{-C_2^{-1} R_2}\big).
\end{equation}
Then choosing $R_2$ large enough, we see that 
\begin{equation*}
	|\det\bL|  \geq c  |\lambda|^{3/2} 
	\geq c ( 1+R_2^{-1} )^{-3}\big(|\lambda|^{1/2}+A\big)^3 
\end{equation*}
for any $(\lambda,\xi')\in \CD_2.$
\medskip

To prove \eqref{clm:c2},  we first note from 
\eqref{eq:est}, \eqref{es:C2-1} and \eqref{es:C2-2} that
\begin{equation}\label{es:C2-3}
	\begin{aligned}
		&|\lambda|^{-1/2} |\fL_1|+|\lambda|^{-1}|L_{12}|=O(R_2^{-1}), \\
		&|\lambda|^{-1/2} (|\fL_2|+|L_{11}|+|L_{21}|)+|\lambda|^{-1}|L_{22}| =O(1).
	\end{aligned}
\end{equation}
Since $|\lambda|^{1/2} \geq r_1 R_2$ for any $(\lambda,\xi')\in\CD_2,$  we infer from  
\eqref{eq:est}, \eqref{es:C2-1}, \eqref{es:C2-2} and \eqref{es:C2-3} that
\begin{equation*}
	\begin{aligned}
		& |\lambda|^{-1} |R_1(A_{\pm},B_{\pm})|
		+|\lambda|^{-3/2} |R_2(A_{\pm},B_{\pm})|
		\lesssim  R_2^{-1}+e^{-c_2r_1 R_2},\\
				&	 |\lambda|^{-3/2} |h_1(A_{\pm},B_{\pm})|
	\lesssim { R_2^{-1}+e^{-c|\lambda|^{1/2}b} 
		+|\lambda|^{-1/2}|N_{11}| }
	\lesssim R_2^{-1}+e^{-c_2 r_1 R_2}
	\end{aligned}
\end{equation*}
for some constant $c_2>0.$ Then the proof of \eqref{clm:c2} is complete.
\medskip

{\bf Case 3.} For the fixed number $R_2$ given in {\bf Case 2}, let us consider the domain
\begin{equation*}
	\CD_3 = \{(\lambda,\xi')\in\widetilde{\Gamma}_{\varepsilon,\lambda_0}: |\xi'|\geq R_3,\,\,R_2|\xi'|\geq |\lambda|^{1/2} \}
\end{equation*}
where $R_3$ is a sufficiently large positive number.
Moreover, by Lemma \ref{lem:4.3}, there exists a positive constant $c=c_{\varepsilon,\gamma_{1-},\mu_-}$ such that
\begin{equation}\label{es:exp_c3}
	\begin{aligned}
		|A_+|+ |B_\pm|&\lesssim |\lambda|^{1/2} + A \lesssim R_2A,\\
		|e^{-aB_-b}|& \lesssim  e^{-ca(|\lambda|^{1/2}+A)b}
		\lesssim  e^{-caA b},\\
		|M_-(-b)|& \lesssim b e^{-cb A},\\ 
		|AM_-(-b)|&\lesssim  bAe^{-cAb} \lesssim e^{-cb A/2},\\
		|B_-M_-(-b)|&\lesssim  R_2bA e^{-cb A}
		\lesssim  R_2 e^{-cb A/2}
	\end{aligned}
\end{equation}
for any $(\lambda,\xi')\in \CD_3,$ $a>0$ and $R_2 \geq 1.$
\smallbreak 

To derive the lower bound of $|\det \bL|,$ we first notice from \eqref{eq:2.15}, \eqref{def:N_jk} and \eqref{es:exp_c3} that
\begin{equation}\label{es:L_3}
	\begin{aligned}
		& |L_{11}^+| + |L_{11}^{0-}| +|L_{21}^{0-}|
		+ { |\wt L_{11}|}+ |\wt L_{21}|\lesssim R_2 A, \quad
		|L_{12}^+| \lesssim A^2,\quad
		|L_{21}^+| \lesssim A, \\
		& |L_{22}^+| + |L_{12}^{0-}|+|\wt L_{12}|  \lesssim R_2 A^2, \qquad
		|L_{22}^{0-}|+|\wt L_{22}| \lesssim  R_2^2 A^2,\\ 
	 &	|L_{11}^{b-}|+|L_{12}^{b-}| + |L_{21}^{b-}| \lesssim R_2 e^{-d_3 A}, \qquad
		 |L_{22}^{b-}|\lesssim R_2^2 e^{-d_3 A} 
	\end{aligned}
\end{equation}
for some constant $d_3$ satisfying $0<2 d_3<b \min\{1,c\}.$
Then \eqref{def:N_jk}, \eqref{es:exp_c3} and \eqref{es:L_3} yield
\begin{equation}\label{es:N_3}
	\begin{aligned}
		|\fL_1|+|N_{11}|+|N_{12}| \lesssim &  
		\big( |L_{11}^+|+|L_{12}^+|
		+|L_{11}^{b-}|+| L_{12}^{b-} |\big) { R_2^2} e^{-cbA/2} 
		\lesssim  {  R_2^3 }  e^{-cbA/4},\\
		|\fL_2|+|N_{21}|+|N_{22}| \lesssim & 
		\big(|L_{21}^+|+|L_{22}^+ | 
		+|L_{21}^{b-}|+ |L_{22}^{b-}|\big) { R_2^2 } e^{-cbA/2}
		\lesssim  {  R_2^4 }  e^{-cbA/4}.
	\end{aligned}
\end{equation}
Combining the estimates \eqref{es:L_3} and \eqref{es:N_3},  we see that
\begin{equation}\label{es:C3-1}
	|h(A_{\pm},B_{\pm})|\lesssim  { R_2^7 } A^2  e^{-cbA/4}.
\end{equation}
By \cite[Lemma 5.1]{KSS2014}, there exists a constant $c_3>0$ such that
\begin{equation*}
|\wt L_{11}\wt L_{22}-\wt L_{12}\wt L_{21}|
	\geq  2c_3 (|\lambda|^{1/2}+A)^3,
\end{equation*}
which together with \eqref{eq:det_whole} and \eqref{es:C3-1} yields
\begin{equation*}
	|\det \bL|\geq 2c_3 (|\lambda|^{1/2}+A)^3-C R_2^7 A^2  e^{-cbA/4} 
	\geq c_3 (|\lambda|^{1/2}+A)^3
\end{equation*}
for large enough $R_{3}$.
\medskip

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
{\bf Case 4.}
In this step, we shall prove $\det \bL\neq 0$ by the contradiction argument provided with $(\lambda,A)\in \CD_4$ for
\begin{equation*}
	\begin{aligned}
		\CD_4 &= \{(\lambda,\xi')\in\widetilde{\Gamma}_{\varepsilon,\lambda_0}: r_{1}\leq |\xi'|\leq R_3,
		\,\,R_2|\xi'|\geq  |\lambda|^{1/2} \}\\
		&  \,\, \subset \{(\lambda,\xi')\in\widetilde{\Gamma}_{\varepsilon,\lambda_0}:
		r_{1}\leq |\xi'|\leq R_3,
		\,\lambda_0^{1/2}\leq|\lambda|^{1/2}\leq R_2R_3\}.  
	\end{aligned}
\end{equation*}
Here, the constants $R_2$ and $R_3$ are fixed by {\bf Case 2} and {\bf Case 3} respectively.
\smallbreak 

Suppose that $\det\bL=0$ for some $(\lambda_{\star},\xi'_{\star})\in \CD_4$. Thus the problem \eqref{eq:2.4}-\eqref{eq:2.5} admits some non-trivial solution 
$$(\bu_{\pm},\fq)(x_N)=(\widehat{\bv}_{\pm},\widehat{\fp}_-)(\xi',x_N)$$
for $\widehat{h}_J(0)=\widehat{k}_J(0)=0$ ($J=1,\dots,N$). 
For simplicity, we still write $(\lambda,\xi')=(\lambda_{\star},\xi'_{\star})$ in what follows.
Therefore, $(\bu_{\pm},\fq)$ satisfies the equations
\begin{equation}\label{eq:ho}
	\begin{aligned}
		&\gamma_{1+}\lambda u_{+j}-\sum_{\ell=1}^{N-1}\mu_+i\xi_\ell(i\xi_ju_{+\ell}+i\xi_\ell u_{+j})-\mu_+\pd_N(i\xi_ju_{+N}+\pd_Nu_{+j}) \\
		&\quad-(\nu_+-\mu_++\delta)i\xi_j(i\xi'\cdot \bu_+'+\pd_Nu_{+N})=0
		& \text{for}\,\,x_N>0,\\
		&\gamma_{1+}\lambda u_{+N}-\sum_{\ell=1}^{N-1}\mu_+i\xi_\ell(\pd_Nu_{+\ell}+i\xi_\ell u_{+N})-2\mu_+\pd_N^2u_{+N}\\
		&\quad-(\nu_+-\mu_++\delta)\pd_N(i\xi'\cdot \bu_+'+\pd_Nu_{+N})=0
		& \text{for}\,\,x_N>0,\\
		&\gamma_{1-}\lambda u_{-j}-\sum_{\ell=1}^{N-1}\mu_-i\xi_\ell(i\xi_ju_{-\ell}+i\xi_\ell u_{-j})\\
		&\quad-\mu_-\pd_N(i\xi_ju_{-N}+\pd_Nu_{-j})+i\xi_j\fq=0
		&  \text{for}\,\,-b<x_N<0,\\
		&\gamma_{1-}\lambda u_{-N}-\sum_{\ell=1}^{N-1}\mu_{-}i\xi_\ell(\pd_Nu_{-\ell}+i\xi_\ell u_{-N})\\
		&\quad-2\mu_{-}\pd_N^2u_{-N}+\pd_N\fq=0
		&  \text{for}\,\, -b<x_N<0,\\
		&i\xi'\cdot \bu_-'+\pd_Nu_{-N}=0
		&  \text{for}\,\,-b<x_N<0
	\end{aligned}
\end{equation}
with the boundary conditions
\begin{equation}\label{bc:unique}
	\begin{aligned}
		&\mu_+(\pd_Nu_{+j}+i\xi_ju_{+N})\big|_{x_N=0}
		=\mu_{-}(\pd_Nu_{-j}+i\xi_ju_{-N})\big|_{x_N=0},\\
		&2\mu_+\pd_Nu_{+N}+(\nu_+-\mu_++\delta)
		(i\xi'\cdot \bu_+'+\pd_Nu_{+N})\big|_{x_N=0}
		=(2\mu_{-}\pd_Nu_{-N}-\fq)\big|_{x_N=0},\\
		& u_{+J}\big|_{x_N=0}=u_{-J}\big|_{x_N=0},\quad 
		u_{-J}\big|_{x_N=-b}=0.
	\end{aligned}
\end{equation}

Let us set  $\|f_{\pm}\|_{\pm}=(f,f)_\pm^{1/2}$ with
$$(f_{+},g_{+})_{+}=\int_{0}^{\infty} f_+(t)\overline{g_+(t)}\,dt
\quad \text{and}\quad
(f_{-},g_{-})_{-}=\int^{0}_{-b} f_-(t)\overline{g_-(t)}\,dt.$$
Then multiplying the equations in \eqref{eq:ho} by $\overline{u_{\pm J}}$ and using integration by parts and interface conditions in \eqref{bc:unique},  we obtain that

\begin{equation}\label{eq:l2}\allowdisplaybreaks 
	\begin{aligned}
		0=&\lambda\big(\gamma_{1+}\sum_{J=1}^N\|u_{+J}\|_+^2
		+\gamma_{1-}\sum_{J=1}^N\|u_{-J}\|_-^2\big)\\
		&+\mu_+\Big( \sum_{j,\ell=1}^{N-1}\|i\xi_\ell u_{+j}\|_+^2
		+\|i\xi'\cdot \bu_+'\|_+^2+\sum_{j=1}^{N-1}\|\pd_Nu_{+j}\|_+^2
		+\sum_{\ell=1}^{N-1}\|i\xi_{\ell}u_{+N}\|_+^2
		+2\|\pd_Nu_{+N}\|_+^2\\
		&\qquad +\sum_{j=1}^{N-1}(i\xi_ju_{+N},\pd_Nu_{+j})_+		
		+\sum_{\ell=1}^{N-1}(\pd_Nu_{+\ell},i\xi_{\ell}u_{+N})_+\Big)\\
		&+(\nu_+-\mu_++\delta)\Big( \|i\xi'\cdot \bu_+'\|_+^2+\|\pd_Nu_{+N}\|_+^2
		+(\pd_Nu_{+N},i\xi'\cdot \bu_+')_+
		+(i\xi'\cdot \bu_+',\pd_Nu_{+N})_+\Big)\\
		&+\mu_-\Big( \sum_{j,\ell=1}^{N-1}\|i\xi_\ell u_{-j}\|_-^2+\|i\xi'\cdot \bu_-'\|_-^2+\sum_{j=1}^{N-1}\|\pd_Nu_{-j}\|_-^2  
		+\sum_{\ell=1}^{N-1}\|i\xi_{\ell}u_{-N}\|_-^2
		+2\|\pd_N u_{-N}\|_-^2\\
		&\qquad \qquad+\sum_{\ell=1}^{N-1}(\pd_Nu_{-\ell},i\xi_{\ell}u_{-N})_-
		+\sum_{j=1}^{N-1}(i\xi_ju_{-N},\pd_Nu_{-j})_-	\Big).
	\end{aligned}
\end{equation}
Thus it is not hard to find from \eqref{eq:l2} that
\begin{equation}\label{eq:l22}
	\begin{aligned}
		0=&\lambda(\gamma_{1+}\|\bu_+\|_+^2+\gamma_{1-}\|\bu_-\|_-^2)\\
		&+\mu_+\Big(\sum_{j,\ell=1}^{N-1}\|i\xi_\ell u_{+j}\|_+^2+\|i\xi'\cdot \bu_+'\|_+^2
		+\sum_{j=1}^{N-1}\|\pd_Nu_{+j}+i\xi_ju_{+N}\|_+^2+2\|\pd_Nu_{+N}\|_+^2\Big)\\
		&+(\nu_+-\mu_++\delta)\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2\\
		&+\mu_-\Big(\sum_{j,\ell=1}^{N-1}\|i\xi_\ell u_{-j}\|_-^2
		+\|i\xi'\cdot \bu_-'\|_-^2
		+\sum_{j=1}^{N-1}\|\pd_Nu_{-j}+i\xi_ju_{-N}\|_-^2
		+2\|\pd_Nu_{-N}\|_-^2\Big).
	\end{aligned}
\end{equation}

Next, taking the imaginary part of \eqref{eq:l22}, we see that 
\begin{equation}\label{eq:IM}
	\begin{aligned}
	 0=& \Im\lambda(\gamma_{1+}\|\bu_+\|_+^2+\gamma_{1-}\|\bu_-\|_-^2)
		 +\Im \delta 
		 \|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2.
	\end{aligned}
\end{equation}
On the other hand, taking the real part of \eqref{eq:l22} and using the inequality
\begin{equation*}
	\begin{aligned}
		\sum_{j,\ell=1}^{N-1}\|i\xi_ju_{+\ell}\|_+^2
		+\|i\xi'\cdot \bu_+'\|_+^2+2\|\pd_Nu_{+N}\|_+^2 
		&\geq 2(\|i\xi'\cdot \bu_+'\|_+^2+\|\pd_Nu_{+N}\|_+^2)\\
		&\geq \|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2,
	\end{aligned}
\end{equation*}
we get that
\begin{equation*}
	\begin{aligned}
		0\geq &\Re\lambda(\gamma_{1+}\|\bu_+\|_+^2
		+\gamma_{1-}\|\bu_-\|_-^2)
		+\mu_+\sum_{j=1}^{N-1}\|\pd_Nu_{+j}+i\xi_ju_{+N}\|_+^2\\
		&+  ( \nu_++\Re \delta ) 
		\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2\\
		&+\mu_-\Big(\sum_{j,\ell=1}^{N-1}\|i\xi_\ell u_{-j}\|_-^2+\|i\xi'\cdot \bu_-'\|_-^2+\sum_{j=1}^{N-1}\|\pd_Nu_{-j}+i\xi_ju_{-N}\|_-^2+2\|\pd_Nu_{-N}\|_-^2\Big).
	\end{aligned}
\end{equation*}
In particular, we have from the inequality above that
\begin{equation}\label{eq:con}
	\begin{aligned}
		0\geq &\Re\lambda(\gamma_{1+}\|\bu_+\|_+^2
		+\gamma_{1-}\|\bu_-\|_-^2)+ ( \nu_++\Re \delta ) 
		\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2.
	\end{aligned}
\end{equation}


In fact, according to \eqref{eq:IM} and \eqref{eq:con}, we can prove that
\begin{equation}\label{cl:u=0}
\gamma_{1+}\|\bu_+\|_+^2
		+\gamma_{1-}\|\bu_-\|_-^2=0
\end{equation}
which immediately gives $\bu_{\pm}=0.$ Then we have $\fq=0$ from \eqref{eq:ho}.
This is a contradiction to  our choice of $(\bu_{\pm},\fq)$. 
\medskip

The proof of \eqref{cl:u=0} will be divided into three cases thanks to Assumption \ref{ass:dl}.
\begin{enumerate}
\item[(C1).] 
In this situation,  we have $\delta=\gamma_{1+}\gamma_{2+}\lambda^{-1}.$
\begin{itemize}

\item If $\Im \lambda\not=0,$ then by \eqref{eq:IM} we have
\begin{equation}\label{c4:1}
	\gamma_{1+}\|\bu_+\|_+^2+\gamma_{1-}\|\bu_-\|_-^2
	=\gamma_{1+}\gamma_{2+}|\lambda|^{-2}\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2,
\end{equation}
which combined with \eqref{eq:con} furnishes that
\begin{equation*}
	\begin{aligned}
		0\geq& \nu_+|\lambda|^{-2}(2\gamma_{1+}\gamma_{2+}\nu_+^{-1}\Re\lambda+|\lambda|^2)\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2\\
		=&\nu_+|\lambda|^{-2}\big((\Re\lambda+\gamma_{1+}\gamma_{2+}\nu_+^{-1})^2+(\Im\lambda)^2-(\gamma_{1+}\gamma_{2+}\nu_+^{-1})^2\big)
		\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2,
	\end{aligned}
\end{equation*}
as $(\Re\lambda+\gamma_{1+}\gamma_{2+}\nu_+^{-1})^2+(\Im\lambda)^2-(\gamma_{1+}\gamma_{2+}\nu_+^{-1})^2>0$ for $\lambda \in K_\varepsilon.$ 
Then  we have 
\begin{equation*}
0=\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2.
\end{equation*}
Thus \eqref{cl:u=0} holds in view of \eqref{c4:1}.
\item For the case where $\Im \lambda=0$ and $\lambda\in \Sigma_{\ep, \lambda_0}$ , we have $\lambda>0$ and $\delta=\gamma_{1+}\gamma_{2+}\lambda^{-1}>0.$ 
Thus we can conclude \eqref{cl:u=0} from \eqref{eq:con}.  

\end{itemize}




\item[(C2).] Suppose that $\delta\in\Sigma_{\varepsilon}$ with $\Re\delta<0$, $\lambda\in\mathbb{C}$ with $|\lambda|\geq \lambda_0$ and $\Re\lambda\geq|\Re\delta/\Im\delta||\Im\lambda|$. 

\begin{itemize}
\item If $\Im\lambda=0$,  we have $\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2=0$ from \eqref{eq:IM}.
Then \eqref{eq:con} yields
\begin{equation*}
	0\geq \Re\lambda(\gamma_{1+}\|\bu_+\|_+^2+\gamma_{1-}\|\bu_-\|_-^2).
\end{equation*}
As $|\lambda|\geq\lambda_0$, we have $\Re\lambda>0,$ and then \eqref{cl:u=0} holds.


\item If $\Im\lambda\neq 0$ and $\Im\lambda\cdot \Im\delta>0$,
then it is easy to see \eqref{cl:u=0} from \eqref{eq:IM}. 

\item Suppose that $\Im\lambda\neq 0$ and $\Im\lambda\cdot \Im\delta<0.$ 
Inserting the following equality 
\begin{equation*}
	\gamma_{1+}\|\bu_+\|_+^2+\gamma_{1-}\|\bu_-\|_-^2=\Big|\frac{\Im\delta}{\Im\lambda}\Big|\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2
\end{equation*}
into \eqref{eq:con} furnishes that
\begin{equation}\label{c4:2}
	0\geq \Big( \nu_++\Re\delta+\Re\lambda\Big|\frac{\Im\delta}{\Im\lambda}\Big| \Big)
	\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2.
\end{equation}
By the fact that $$\Re\delta+\Re\lambda\Big|\frac{\Im\delta}{\Im\lambda}\Big|\geq 0,$$
 we obtain $\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2=0$ and then the equality \eqref{cl:u=0}.
\end{itemize}

\item[(C3).]
Assume that $\delta\in\Sigma_{\varepsilon}$ with $\Re\delta\geq0$, $\lambda\in\mathbb{C}$ with $|\lambda|\geq \lambda_0$ and $\Re\lambda\geq\lambda_0|\Im\lambda|$. 
\begin{itemize}
\item If $\Im\lambda=0$ and $|\lambda|\geq\lambda_0,$  then $\Re\lambda>0.$
Thus \eqref{cl:u=0} holds true according to \eqref{eq:con} and $\Re\delta\geq0.$

\item For the case where $\Im\lambda\neq 0$ and $\Im\lambda\cdot \Im\delta>0$, 
we can easily obtain \eqref{cl:u=0} from \eqref{eq:IM}. 


\item Suppose that $\Im\lambda\neq 0$ and $\Im\lambda\cdot \Im\delta\leq 0.$ According to \eqref{eq:IM} and \eqref{eq:con}, we also obtain the inequality \eqref{c4:2} as before. 
Since 
$$\Re\delta+\Re\lambda\Big|\frac{\Im\delta}{\Im\lambda}\Big|
\geq \lambda_0|\Im\delta|+\Re\delta\geq 0,$$
we have $\|i\xi'\cdot \bu_+'+\pd_Nu_{+N}\|_+^2=0$ and then \eqref{cl:u=0}.

\end{itemize}



\end{enumerate}





Summing up, we have $\det\bL\neq0$ for any $(\lambda,A)\in \CD_4.$
By the compactness of $\CD_4$, there exists a positive constant $C_5$ such that
$$\inf_{(\lambda,A)\in \CD_4}|\det\bL|\geq C_5 
\geq { \frac{C_5}{R_{3}^3 (1+R_2)^3} 
(|\lambda|^{1/2}+A)^3. }$$
This completes the proof of Lemma \ref{lem:3.1}.
\medskip






