\section{Analysis of the solution operators of \eqref{eq:2.3}}
\label{sec:SO}
In this section, we shall establish the property of the $\CR$-boundedness of the solution operators of \eqref{eq:2.3}. 
To this end, let us recall the definition of $\CR$-boundedness of operator families.
\begin{dfn}\label{def:R}
	Let $X,Y$ be Banach spaces. A family of operators $\tau\subset\CL(X;Y)$ is $\CR$-bounded if for any $N\in\BN, T_j\in\tau, x_j\in X$ and the \emph{Rademacher} functions $r_j(u)={\rm sign }(\sin \,2^j\pi u)$ defined for $u\in [0,1]$, there holds
	$$\Big\|\sum_{j=1}^{N}r_jT_jx_j\Big\|_{L_p([0,1];Y)}\leq C_p\Big\|\sum_{j=1}^{N}r_jx_j\Big\|_{L_p([0,1];X)} \quad \text{for some}\,\,p\in [0,\infty).$$
	The smallest constant $C_p$ above is called the $\CR$-bound of $\tau$, denoted by $\CR_{\CL(X;Y)}(\tau)$.
\end{dfn}
\begin{rmk}\label{rmk:R-bdd}
	Let $X,Y,Z$ be Banach spaces.
	\begin{enumerate}[label=(\roman*)]
		\item If $\CT$ and $\CS$ are two $\CR$-bounded families in $\CL(X;Y)$, then the set
		$$\CT+\CS=\{T+S:T\in\CT,S\in\CS\}$$
		is also $\CR$-bounded and 
		$\CR_{\CL(X;Y)}(\CT+\CS)\leq \CR_{\CL(X;Y)}(\CT)+\CR_{\CL(X;Y)}(\CS).$
		\item If the families $\CT\subset\CL(X;Y)$ and $\CS\subset\CL(X;Z)$ are $\CR$-bounded, then the set $$\CS\CT=\{S\circ T:T\in\CT,S\in\CS\}\subset\CL(X;Z)$$ 
        is also $\CR$-bounded and $\CR_{\CL(X;Z)}(\CS\CT)\leq \CR_{\CL(X;Y)}(\CT)\CR_{\CL(Y;Z)}(\CS).$
	\end{enumerate}
\end{rmk}

For \eqref{eq:2.3}, we can prove the following result. 
\begin{thm}\label{thm:5.1}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{\pm},$ $\nu_+,$ $\gamma_{1\pm},$ $\gamma_{2+}>0.$ Set that
	\begin{equation*}
		Z_q(\dot\Omega)=H^1_q(\dot\Omega)^N \times H^2_q(\dot\Omega)^N,\quad  
		\CZ_q(\dot\Omega)=L_q(\dot\Omega)^N\times H^1_q(\dot\Omega)^{N}
		\times L_q(\dot\Omega)^N \times H^1_q(\dot\Omega)^{N}\times H^2_q(\dot\Omega)^{N}.
	\end{equation*}
	For any $(\bh,\bk)\in Z_q(\dot\Omega),$ there exist constants $\lambda_0, r_b$ and the operator families
	\begin{equation*}
		\begin{aligned}
			\CS_{\pm}(\lambda)&\in \Hol\Big(\Gamma_{\varepsilon,\lambda_0};
			\CL\big( \CZ_q(\dot\Omega);\,H^2_q(\Omega_{\pm})^N\big)\Big),\\
			\CP_-(\lambda)&\in\Hol \Big(\Gamma_{\varepsilon,\lambda_0};
			\CL\big( \CZ_q(\dot\Omega);\,\wh H^1_q(\Omega_{-})\big)\Big)
		\end{aligned}	
	\end{equation*}
	such that 
	$$(\bv_{\pm},\fp_-)=\big(\CS_{\pm}(\lambda),\CP_-(\lambda)\big)
	(\lambda^{1/2}\bh,\bh,\lambda\bk,\lambda^{1/2}\bk,\bk)$$
	solves \eqref{eq:2.3}.  Here the set $\Gamma_{\ep,\lambda_0}$ is defined by \eqref{def:Gamma} for some $\delta_0>0.$
	Moreover, we have
 \begin{equation}\label{res:key_1}
     \begin{aligned}
		\CR_{\CL\big(\CZ_q (\dot\Omega)\,;\,H^{2-j}_q(\Omega_\pm)^N \big)}
		\Big(\Big\{ (\tau\pd_{\tau})^\ell \big( \lambda^{j\slash 2} \CS_{\pm}(\lambda) \big):
		\lambda\in\Gamma_{\varepsilon,\lambda_0} \Big\}\Big) & \leq r_b,\\
		\CR_{\CL\big( \CZ_q (\Omega_-)\,;\, L_q(\Omega_{-})^{N} \big)}
		\Big( \Big\{ (\tau\pd_{\tau})^\ell \nabla\CP_-(\lambda) :
		\lambda\in\Gamma_{\varepsilon,\lambda_0} \Big\}\Big) & \leq r_b
     \end{aligned}
 \end{equation}
	for $\ell =0,1,$ $j=0,1,2,$ and $\tau = \Im \lambda.$ 
	Above the choice of  $r_b$ depends solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1\pm},$ $\gamma_{2+},$ $\mu_{\pm},$ 
	$\nu_+,$  $\lambda_0$, $\delta_0$ and $b.$
\end{thm}

In what follows, we first address some technical results on the boundedness of Fourier multipliers in Subsection \ref{subsec:TL}. 
Then we construct the operator families $\CS_{\pm}(\lambda)$ and $\CP_-(\lambda)$ and derive the bounds in  \eqref{res:key_1} in Subsections \ref{subsec:S+} and \ref{subsec:S-P} respectively.


\subsection{Technical lemmas}
\label{subsec:TL}
To prove Theorem \ref{thm:5.1},  we first recall some technical results used in the one-phase problems \cite{KSS2014, Saito2015}.
\begin{lem}[{\cite[Lemma 3.1]{KSS2014}}]
\label{lem:4.4}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\gamma_{1+},$ $\gamma_{2+},$ $\mu_{+},$ 
	$\nu_+,$  $\lambda_0>0.$ Let the set $\Gamma_{\ep,\lambda_0}$ be defined by \eqref{def:Gamma} for some $\delta_0>0,$ and let the multiplier $m(\lambda,\xi')$ belong to $\bM_{-2,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}).$ For $0<x_N<+\infty$, set that
	\begin{equation*}
		\begin{aligned}
			\big[K^1_{+,+}(\lambda)f\big](x',x_N)=&\int_{0}^\infty\mathcal{F}_{\xi'}^{-1}\Big[
			m(\lambda,\xi')AA_+M_+(x_N+y_N)\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^2_{+,+}(\lambda)f\big](x',x_N)=&\int_{0}^\infty\mathcal{F}_{\xi'}^{-1}\Big[
			m(\lambda,\xi')Ae^{-B_+(x_N+y_N)}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N.
		\end{aligned}
	\end{equation*}
Then there exists a constant $r_b$ depending solely on 
$\varepsilon,$ $q,$ $N,$ $\gamma_{1+},$ $\gamma_{2+},$ $\mu_{+},$ 
	$\nu_+,$  $\lambda_0$, $\delta_0$ and $b$ such that
	$$\mathcal{R}_{\mathcal{L}\big(L_q(\Omega_+),H^{2-j}_q(\Omega_+)\big)}
	\Big(\Big\{(\tau\pd_{\tau})^\ell \lambda^{j/2} K^k_{+,+}(\lambda):
	\lambda\in \Gamma_{\varepsilon,\lambda_0} \Big\}\Big)\leq r_b$$
	for $j=0,1,2,$ $k=1,2,$ and $\ell=0,1.$ 
\end{lem}

For the results in the layer type domains,
let us introduce the cut-off functions $\varphi_{\pm}(x_N)\in C^\infty(\BR)$ satisfying 
\begin{equation*}
	0\leq \varphi_\pm(x_N)\leq 1, \quad 
	\varphi_+(x_N)=
	\begin{cases}
