Then we denote
\begin{equation}\label{def:cut-off-1}
\begin{aligned}
    \varphi_{-b}(x_N)&=\varphi_-(x_N/b), &  \varphi_{-0}(x_N)&=1-\varphi_-(x_N/b),\\
    \varphi_{+0}(x_N)&=\varphi_+(x_N/b), & \varphi_{b}(x_N)&=1-\varphi_+(x_N/b),
