\end{equation}
and 
\begin{equation*}
 \begin{aligned}
 E_k^- (y_N)
=\begin{cases}
		\varphi_{-0}(y_N) & \text{for}\,\,\, k=1,\\
		\varphi'_{-0}(y_N) & \text{for}\,\,\, k=2,	
