	$\nu_+,$  $\lambda_0$, $\delta_0$ and $b$ such that
	$$\mathcal{R}_{\mathcal{L}\big(L_q(\Omega_{-}),H^{2-j}_q(\Omega_{+})\big)}
	\Big(\Big\{(\tau\pd_{\tau})^\ell \lambda^{j/2}K_{-,+}^{i,n}(\lambda):
	\lambda\in \Gamma_{\varepsilon,\lambda_0} \Big\}\Big)\leq r_b$$
	for $\ell=0,1$, $j=0,1,2.$ 
\end{lem}

Let us introduce the strip region for any $b>0:$
\begin{equation*}
    \Omega_{+b}=\{x=(x',x_N)\in \BR^N: 0<x_N<b\}.
\end{equation*}
\begin{lem}\label{lem:+-}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{-},$ $\gamma_{1-}>0.$ Let the set $\Gamma_{\ep,\lambda_0}$ be defined by \eqref{def:Gamma} for some $\delta_0>0,$ and let the multiplier $m(\lambda,\xi')$ belong to $\bM_{-2,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}).$ For $-b<x_N<0$, we define $K_{+,-}^{i,n}\,(i=1,2,3,4,\,n=1,2)$ by
	\begin{equation*}
		\begin{aligned}
			\big[K^{1,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')A^2e^{-Ay_N}M_-(x_N)\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{2,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')Ae^{-Ay_N}e^{B_-x_N}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{3,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')A^2e^{-Ay_N}M_-(-x_N-b)\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{4,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')Ae^{-Ay_N}e^{B_-(-x_N-b)}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N.
		\end{aligned}
	\end{equation*}
	Then there exists a constant $r_b$ depending solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1-},$  $\mu_{-},$ 
	  $\lambda_0$, $\delta_0$ and $b$ such that
	$$\mathcal{R}_{\mathcal{L}\big(L_q(\Omega_{+b}),H^{2-j}_q(\Omega_-)\big)}
	\Big(\Big\{(\tau\pd_{\tau})^\ell \lambda^{j/2} K^{i,n}_{+,-}(\lambda):
	\lambda\in \Gamma_{\varepsilon,\lambda_0} \Big\}\Big)\leq r_b$$
	for $\ell=0,1$, $j=0,1,2$.
\end{lem}

\begin{lem}\label{lem:+-2}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{-},$ $\gamma_{1-}>0.$ Let the set $\Gamma_{\ep,\lambda_0}$ be defined by \eqref{def:Gamma} for some $\delta_0>0,$ and let the multiplier $m(\lambda,\xi')$ belong to $\bM_{0,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}).$ For $-b<x_N<0$, we define $K_{+,-}^{i,n}\,(i=5,6,\,n=1,2)$ by
	\begin{equation*}
		\begin{aligned}
			\big[K^{5,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')e^{-Ay_N}e^{Ax_N}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{6,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')e^{-Ay_N}e^{A(-x_N-b)}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N.
		\end{aligned}
	\end{equation*}
	Then there exists a constant $r_b$ depending solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1-},$ $\mu_{-},$ 
  $\lambda_0$, $\delta_0$ and $b$ such that
	$$\mathcal{R}_{\mathcal{L}\big(L_q(\Omega_{+b}),L_q(\Omega_-)\big)}
	\Big(\Big\{(\tau\pd_{\tau})^\ell  \nabla K^{i,n}_{+,-}(\lambda):
	\lambda\in \Gamma_{\varepsilon,\lambda_0} \Big\}\Big)\leq r_b$$
	for $\ell=0,1$.
\end{lem}



\subsection{Bound of the operator family $\CS_{+}(\lambda)$}
\label{subsec:S+}
In this and next subsection, we shall construct the solution operators in Theorem \ref{thm:5.1} from \eqref{eq:2.27}. Let us take $(\bh,\bk)\in Z_q(\dot\Omega).$ Then there exist $\bh_\pm\in H_q^1(\Omega_{\pm})^N$ and $\bk_\pm\in H_q^2(\Omega_{\pm})^N$ such that
\begin{equation*}
	\bh=\bh_+\mathds{1}_{\Omega_{+}} + \bh_-\mathds{1}_{\Omega_{-}} 
	\quad \text{and}\quad 
	\bk=\bk_+\mathds{1}_{\Omega_{+}} + \bk_-\mathds{1}_{\Omega_{-}},  
\end{equation*}
with $\mathds{1}_{\Omega_{\pm}}$ standing for the indicator functions of $\Omega_{\pm}.$ In particular, taking traces on the interface $\Gamma,$ we have 
\begin{equation*}
	\bh(x',0)=\bh_+(x',0)+\bh_-(x',0)  
	\quad \text{and}\quad 
	\bk(x',0)=\bk_+(x',0)+\bk_-(x',0).
\end{equation*}


\begin{lem}[Volevich's trick]
\label{lem:Vol-1}
For any function $a_+(\xi',x_N)$ vanishing as $x_N\to \infty,$ we have 
\begin{equation}\label{Vol:+1}
\begin{aligned}
a_+(\xi',x_N)\widehat{\bh}_+(\xi',0)
           =  &-\int_{0}^{\infty}(\pd_N a_+)(\xi',x_N+y_N)
    \frac{\gamma_{1+}\lambda^{1/2}}{\mu_{+}B_{+}^2}
    \widehat{\lambda^{1/2}\bh_+}(\xi',y_N) dy_N\\
           &+\sum_{\ell=1}^{N-1}\int_{0}^{\infty}(\pd_N a_+)(\xi',x_N+y_N)
\frac{i\xi_\ell}{B_{+}^2} \widehat{\pd_\ell \bh_+}(\xi',y_N) dy_N\\
    &-\int_{0}^{\infty} a_+(\xi',x_N+y_N)\widehat{\pd_N\bh_+}(\xi',y_N)dy_N,
	\end{aligned}
\end{equation}
and 
\begin{equation}\label{Vol:+2}
	\begin{aligned}
		a_+(\xi',x_N)\widehat{\bk}_+(\xi',0)=
  		&-\int_{0}^{\infty}(\pd_N a_+)(\xi',x_N+y_N)
  \frac{\gamma_{1+}}{\mu_{+}B_{+}^2} \widehat{\lambda \bk_+}(\xi',y_N) dy_N\\
  &-\int_{0}^{\infty}a_+(\xi',x_N+y_N)
  \frac{\gamma_{1+}\lambda^{1/2}}{\mu_{+}B_{+}^2}
  \widehat{\lambda^{1/2}\pd_N\bk_+}(\xi',y_N) dy_N\\
    		&+\int_{0}^{\infty}(\pd_N a_+ )(\xi',x_N+y_N)
    \frac{1}{B_{+}^2}\widehat{\Delta'\bk_+}(\xi',y_N)dy_N\\
    &+\sum_{\ell=1}^{N-1}\int_{0}^{\infty}a_+(\xi',x_N+y_N)
    \frac{i\xi_{\ell}}{B_{+}^2} \widehat{\pd_{\ell}\pd_N\bk_+}(\xi',y_N)dy_N
	\end{aligned}
\end{equation}
for $\Delta'=\sum_{\ell=1}^{N-1} \pd_{\ell}^2.$
\smallbreak 

In addition, let the cut-off function $\varphi_{-0}$ be defined in \eqref{def:cut-off-1}. Then we have 
\begin{equation}\label{Vol:-1}
	\begin{aligned}
		\widehat{\bh}_-(\xi',0)
  =&\int_{-b}^0 \big( \varphi'_{-0}(y_N) +\varphi_{-0}(y_N)A\big)
  e^{Ay_N} \frac{\gamma_{1+}\lambda^{1/2}}{\mu_+ B_+^2} \widehat{\lambda^{1/2}\bh_-}(\xi',y_N)dy_N\\
    &  - \sum_{\ell=1}^{N-1} \int_{-b}^0 \big( \varphi'_{-0}(y_N) +\varphi_{-0}(y_N)A\big)
  e^{Ay_N} \frac{i\xi_{\ell}}{B_+^2} \widehat{\pd_{\ell}\bh_-}(\xi',y_N)dy_N\\
		&+\int_{-b}^0\varphi_{-0}(y_N)e^{Ay_N}\widehat{\pd_N \bh_-}(\xi',y_N)dy_N.
	\end{aligned}
\end{equation}
\begin{equation}\label{Vol:-2}
	\begin{aligned}
		\widehat{\bk}_-(\xi',0)
  =&\int_{-b}^0 \big( \varphi'_{-0}(y_N) +\varphi_{-0}(y_N)A\big)
  e^{Ay_N} \frac{\gamma_{1+}}{\mu_+ B_+^2} \widehat{\lambda\bk_-}(\xi',y_N)dy_N\\
 &+\int_{-b}^0\varphi_{-0}(y_N)e^{Ay_N}\frac{\gamma_{1+}\lambda^{1/2}}{\mu_+ B_+^2}
 \widehat{\lambda^{1/2}\pd_N \bk_-}(\xi',y_N)dy_N\\
  &  - \int_{-b}^0 \big( \varphi'_{-0}(y_N) +\varphi_{-0}(y_N)A\big) e^{Ay_N} 
    \frac{1}{B_+^2} \widehat{\Delta'\bk_-}(\xi',y_N)dy_N\\
		&-\sum_{\ell=1}^{N-1}\int_{-b}^0\varphi_{-0}(y_N)e^{Ay_N}
  \frac{i\xi_{\ell}}{B_+^2} \widehat{\pd_{\ell}\pd_N \bk_-}(\xi',y_N)dy_N.
	\end{aligned}
\end{equation}
\end{lem}

\begin{proof}
For any function $f_+$ defined on $\Omega_+,$ it is not hard to see that 
\begin{equation}\label{eq:vh}
\begin{aligned}
a_+(\xi',x_N)\widehat{f_+}(\xi',0) = & -\int_{0}^{\infty}
	(\pd_N a_+)(\xi^\prime,x_N+y_N)\widehat{f_+}(\xi',y_N) d y_N\\
	& -\int_{0}^{\infty} a_+(\xi^\prime,x_N+y_N)\widehat{\pd_N f_+}(\xi',y_N) d y_N.
\end{aligned}
\end{equation}
Then taking $f_+$ in \eqref{eq:vh} as the components of $(\bh_+,\bk_+)$ and inserting the identity 
\begin{equation}\label{eq:1_+}
    1=\frac{\gamma_{1+}\lambda}{\mu_{+}B_{+}^2}
-\sum_{\ell=1}^{N-1}\frac{(i\xi_{\ell})\cdot (i\xi_{\ell})}{B_{+}^2}
\end{equation}
into \eqref{eq:vh} yield \eqref{Vol:+1} and \eqref{Vol:+2}. 

On the other hand, for any function $f_-$ defined on $\Omega_-,$ we have 
\begin{equation}\label{eq:-}
	\begin{aligned}
		\widehat{f_-}(\xi',0)=&\int_{-b}^{0}\frac{d}{dy_N}\big[\varphi_{-0}(y_N)e^{Ay_N}
  \widehat{f_-}(\xi',y_N)\big]dy_N\\
		=&\int_{-b}^0 \big( \varphi'_{-0}(y_N) +\varphi_{-0}(y_N)A\big)
  e^{Ay_N}\widehat{f_-}(\xi',y_N)dy_N\\
		&+\int_{-b}^0\varphi_{-0}(y_N)e^{Ay_N}\widehat{\pd_N f_-}(\xi',y_N)dy_N.
	\end{aligned}
\end{equation}
Then using \eqref{eq:1_+} and \eqref{eq:-} implies \eqref{Vol:-1} and \eqref{Vol:-2}.
\end{proof}



