    \end{aligned}
\end{equation}
which correspond to the following variables
\begin{equation*}
 \begin{aligned}
   \lambda^{1/2} \bh&=\big(\lambda^{1/2}(h_{\ell+}\mathds{1}_{\Omega_{+}}+h_{\ell-}\mathds{1}_{\Omega_{-}})\,|\,\ell=1,\cdots,N\big),\\  
    \nabla \bh&=(\pd_mh_{\ell+}\mathds{1}_{\Omega_{+}}+\pd_mh_{\ell-}\mathds{1}_{\Omega_{-}}\,|\,m,\ell=1,\cdots,N), \\
    \lambda \bk &=\big(\lambda (k_{\ell+}\mathds{1}_{\Omega_{+}}+k_{\ell-}\mathds{1}_{\Omega_{-}})\,|\,\ell=1,\cdots,N\big),\\
    \lambda^{1/2}\nabla \bk & =\big(\lambda^{1/2} \pd_m(k_{\ell+}\mathds{1}_{\Omega_{+}}+k_{\ell-}\mathds{1}_{\Omega_{-}})\,|\,m,\ell=1,\cdots,N\big),\\ \nabla^2\bk&=\big(\pd_n\pd_m(k_{\ell+}\mathds{1}_{\Omega_{+}}+k_{\ell-}\mathds{1}_{\Omega_{-}})\,|\,n,m,\ell=1,\cdots,N\big).
 \end{aligned}   
\end{equation*}

Now, using \eqref{eq:2.27} and the convention \eqref{conv:f}, we will see that
\begin{equation}\label{eq:S+}
    \CS_{J+}(\lambda^{1/2}\bh, \bh,\lambda \bk,\lambda^{1/2}\bk,\bk)
   =\sum_{i=1}^2\CS_{ Ji+} (\lambda^{1/2}\bh, \bh,\lambda \bk,\lambda^{1/2}\bk,\bk)    =\sum_{i=1}^2\sum_{k=1}^5\CS_{Ji+}^k(\lambda)(f_k)
