However, according to the difference in the topology properties between the domains $\Omega_+$ and $\Omega_-,$
we use the following technical lemma to treat the traces of $(\bh_+,\bk_+).$
\begin{lem}[Volevich's trick]
\label{lem:Vol-2}
Let $\varphi_{+0}$ be defined in \eqref{def:cut-off-1} and $\Delta'=\sum_{\ell=1}^{N-1} \pd_{\ell}^2.$ Then we have 
\begin{equation}\label{Vol:1}
	\begin{aligned}
		\widehat{\bh_+}(\xi',0)
  =&-\int_{0}^b \big( \varphi'_{+0}(y_N) - \varphi_{+0}(y_N)A\big)
  e^{-Ay_N} \frac{\gamma_{1-}\lambda^{1/2}}{\mu_- B_-^2} \widehat{\lambda^{1/2}\bh_+}(\xi',y_N)dy_N\\
    &  + \sum_{\ell=1}^{N-1} \int_{0}^b \big(\varphi'_{+0}(y_N) -\varphi_{+0}(y_N)A\big)
  e^{-Ay_N} \frac{i\xi_{\ell}}{B_-^2} \widehat{\pd_{\ell}\bh_+}(\xi',y_N)dy_N\\
		&-\int_{0}^b\varphi_{+0}(y_N)e^{-Ay_N}\widehat{\pd_N \bh_+}(\xi',y_N)dy_N,
	\end{aligned}
\end{equation}
\begin{equation}\label{Vol:2}
	\begin{aligned}
		\widehat{\bk_+}(\xi',0)
  =&-\int_{0}^b \big( \varphi'_{+0}(y_N) -\varphi_{+0}(y_N)A\big)
  e^{-Ay_N} \frac{\gamma_{1-}}{\mu_- B_-^2} \widehat{\lambda\bk_+}(\xi',y_N)dy_N\\
 &-\int_{0}^b\varphi_{+0}(y_N)e^{-Ay_N}\frac{\gamma_{1-}\lambda^{1/2}}{\mu_- B_-^2}
 \widehat{\lambda^{1/2}\pd_N \bk_+}(\xi',y_N)dy_N\\
  &  +\int_{0}^b \big( \varphi'_{+0}(y_N)-\varphi_{+0}(y_N)A\big) e^{-Ay_N} 
