\section{Resolvent operators of the two-phase problem}
\label{sec:resolvent}
In this section, we consider the resolvent problem \eqref{eq:res_full} and the main result on the problem \eqref{eq:res_full} reads as follows.
\begin{thm}\label{thm:main2}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{\pm},$ $\nu_+,$ $\gamma_{1\pm},$ $\gamma_{2+}>0.$
	Let us introduce the functional spaces for the given terms in \eqref{eq:res_full} as follows 
	\begin{equation*}
		\begin{aligned}
			X_q (\dot \Omega)&=\big\{ (f_1,\Bf_2,\Bf_3,f_4,\Bf_5,\Bf_6,\Bf_7) :
			f_1\in H^1_q(\Omega_+),
			\Bf_2\in L_q(\Omega_+)^N, \Bf_3,\Bf_5\in L_q(\Omega_-)^N,\\
			& \hspace{5.5cm} f_4\in H^1_q(\Omega_-), 
			\Bf_6\in H^1_q(\dot\Omega)^N, \Bf_7\in H^2_q(\dot\Omega)^N, 
			f_4=\dv \Bf_5 \big\}, \\
			\CX_q(\dot\Omega)&=\big\{ (f_1,\Bf_2,\Bf_3,g_4, f_4,\Bf_5,\bg_6,\Bf_6,\bh_7,\bg_7,\Bf_7) :
			(f_1,\Bf_2,\Bf_3,f_4,\Bf_5,\Bf_6,\Bf_7) \in X_q(\dot \Omega),\\
			& \hspace{6cm} g_4\in L_q(\Omega_-), \,\Bg_6\in L_q(\dot\Omega)^N,\,\bg_7\in H^1_q(\dot\Omega)^N,\,\bh_7\in L_q(\dot\Omega)^N\big\}.
		\end{aligned}
	\end{equation*} 
	In addition, we also write for short that 
	\begin{equation*}
		\begin{aligned}
			\bF&=(f_+, \bg_+,\bg_-,g_d, \fg_d,\bh,\bk),\\
			\bF_{\lambda}&=(f_+,\bg_+,\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d, 
			\lambda^{1/2} \bh,\bh,\lambda\bk,\lambda^{1/2}\bk,\bk).
		\end{aligned}
	\end{equation*}
	For any $\bF\in X_q(\dot\Omega),$ there exist constants $\lambda_0, r_b$ and the operator families
	\begin{equation*}
		\begin{aligned}
			\Theta_+(\lambda) &\in \Hol\Big( \Sigma_{\ep, \lambda_0}  \cap K_{\ep} ; 
			\CL\big( \CX_q(\dot \Omega) ; H^1_q(\Omega_+) \big) \Big),\\
			\CA_\pm(\lambda) &\in \Hol\Big( \Sigma_{\ep, \lambda_0}  \cap K_{\ep} ; 
			\CL\big( \CX_q(\dot \Omega) ;H^2_q(\Omega_\pm)^N \big) \Big),\\
			\CB_-(\lambda) &\in \Hol\Big( \Sigma_{\ep, \lambda_0}  \cap K_{\ep}; 
			\CL\big( \CX_q(\dot \Omega) ;\wh H^1_q(\Omega_-) \big) \Big)
		\end{aligned}
	\end{equation*}
	such that $(\rho_+, \bv_+,\bv_-,\fp_-)
	= \big(\Theta_+(\lambda) , \CA_+(\lambda), \CA_-(\lambda),\CB_-(\lambda)\big) \,\bF_{\lambda}$ 
	solves \eqref{eq:res_full} uniquely.  Here the regions $\Sigma_{\ep, \lambda_0}$ and $K_{\ep}$ are defined by \eqref{eq:KSigma}. Moreover, we have 
	\begin{gather*}
		\CR_{\CL\big(\CX_q(\dot \Omega); H^{1}_q(\Omega_+) \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{k}
		\Theta_+(\lambda)\big) : 
		\lambda \in \Sigma_{\ep, \lambda_0} \cap K_{\ep} \Big\}\Big) \leq r_b,\\
		\CR_{\CL\big(\CX_q(\dot\Omega); H^{2-j}_q(\Omega_\pm)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{j\slash 2}
		\CA_\pm(\lambda)\big) : 
		\lambda \in \Sigma_{\ep, \lambda_0} \cap K_{\ep} \Big\}\Big) \leq r_b,\\
		\CR_{\CL\big(\CX_q(\dot\Omega); L_q(\Omega_-)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}   \nabla \CB_-(\lambda) : 
		\lambda \in \Sigma_{\ep, \lambda_0} \cap K_{\ep} \Big\}\Big) \leq r_b
	\end{gather*}
	for $k,\ell =0,1,$ $j=0,1,2,$ and $\tau = \Im \lambda.$ 
	Above the choice of  $r_b$ depends solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1\pm},$ $\gamma_{2+},$ $\mu_{\pm},$ 
	$\nu_+,$  $\lambda_0$, $\delta_0$ and $b.$
\end{thm}




To prove Theorem \ref{thm:main2}, it suffices to study the following reduced problem:
\begin{equation}\label{eq:rr}
	\left\{ \begin{aligned}
		&\gamma_{1+}\lambda\bv_+-\Di\bS_{\delta+}(\bv_+)=\bg_+
		&&\quad&\text{in}& \quad  \Omega_+, \\
		&\gamma_{1-}\lambda\bv_--\Di \bT_-(\bv_-,\fp_-)=\bg_-
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
		&\di\bv_-= g_d=\di \fg_d
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
		&\bS_{\delta+}(\bv_+)\bn
		-\bT_-(\bv_-,\fp_-)\bn =\bh
		&&\quad&\text{on}& \quad \Gamma,\\
		& \bv_+-\bv_-=\bk
		&&\quad&\text{on}& \quad \Gamma ,	\\
		&\bv_-= 0
		&&\quad&\text{on}& \quad S
	\end{aligned}
	\right.
\end{equation}
with $\bS_{\delta+}(\bv_+)$ defined in \eqref{eq:S_delta}.
Concerning the problem \eqref{eq:rr}, it is not hard to prove the following result by using Theorem \ref{thm:5.1}.
\begin{thm}\label{thm:rr}
Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{\pm},$ $\nu_+,$ $\gamma_{1\pm},$ $\gamma_{2+}>0.$
With the spaces $Z_q(\dot\Omega)$ and $\CZ_q(\dot\Omega)$ introduced by Theorem \ref{thm:5.1}, we denote that 
	\begin{equation*}
		\begin{aligned}
			Y_q (\dot \Omega)&=\big\{ (\Bf_1,\Bf_2,f_3,\Bf_4,\Bf_5,\Bf_6) :
			\Bf_1\in L_q(\Omega_+)^N, \Bf_2,\Bf_4\in L_q(\Omega_-)^N,
			f_3\in H^1_q(\Omega_-),\\
			& \hspace{7.5cm} (\Bf_5,\Bf_6)\in Z_q(\dot\Omega), f_3=\dv \Bf_4 \big\}, \\
			\CY_q(\dot\Omega)&=\big\{ (\Bf_1,\Bf_2,g_3, f_3,\Bf_4,\bg_5,\Bf_5,\bh_6,\bg_6,\Bf_6) :
			(\Bf_1,\Bf_2,f_3,\Bf_4,\Bf_5,\Bf_6) \in Y_q(\dot \Omega),\\
			& \hspace{5.5cm}  g_3\in L_q(\Omega_-), \, 
			(\bg_5,\Bf_5,\bh_6,\bg_6,\Bf_6)\in \CZ_q(\dot\Omega)\big\}.
		\end{aligned}
	\end{equation*} 
	In addition, we also write for short that 
	\begin{equation*}
		\begin{aligned}
			\bG&=(\bg_+,\bg_-,g_d, \fg_d,\bh,\bk),\\
			\bG_{\lambda}&=(\bg_+,\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d, 
			\lambda^{1/2} \bh,\bh,\lambda\bk,\lambda^{1/2}\bk,\bk).
		\end{aligned}
	\end{equation*}
	For any $\bG\in Y_q(\dot \Omega),$ there exist constants $\lambda_0, r_b$ and the operator families
	\begin{equation*}
		\begin{aligned}
			\CA_\pm^0(\lambda) &\in \Hol\Big( \Gamma_{\ep,\lambda_0} ; 
			\CL\big( \CY_q(\dot \Omega) ;H^2_q(\Omega_\pm)^N \big) \Big),\\
			\CB_-^0(\lambda) &\in \Hol\Big( \Gamma_{\ep,\lambda_0} ; 
			\CL\big( \CY_q(\dot \Omega) ;\wh H^1_q(\Omega_-) \big) \Big)
		\end{aligned}
	\end{equation*}
	such that $(\bv_+,\bv_-,\fp_-)
	= \big(\CA_+^0(\lambda), \CA_-^0(\lambda),\CB_-^0(\lambda)\big) \,\bG_{\lambda}$
	solves \eqref{eq:rr} uniquely.  Here the set $\Gamma_{\ep,\lambda_0}$ is defined by \eqref{def:Gamma} for some $\delta_0>0.$ Moreover, we have 
	\begin{gather*}
		\CR_{\CL\big(\CY_q(\dot \Omega); H^{2-j}_q(\Omega_\pm)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{j\slash 2}
		\CA_\pm^0(\lambda)\big) : 
		\lambda \in \Gamma_{\ep,\lambda_0} \Big\}\Big) \leq r_b,\\
		\CR_{\CL\big(\CY_q(\dot \Omega); L_q(\Omega_-)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}   \nabla \CB_-^0(\lambda) : 
		\lambda \in \Gamma_{\ep,\lambda_0} \Big\}\Big) \leq r_b
	\end{gather*}
	for $\ell =0,1,$ $j=0,1,2,$ and $\tau = \Im \lambda.$ 
	Above the choice of  $r_b$ depends solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1\pm},$ $\gamma_{2+},$ $\mu_{\pm},$ 
	$\nu_+,$  $\lambda_0$, $\delta_0$ and $b.$
\end{thm}

\begin{rmk}
It is not hard to prove Theorem \ref{thm:main2} by imposing $\delta=\gamma_{1+}\gamma_{2+}\lambda^{-1}$ in \eqref{eq:rr} and taking advantage of Theorem \ref{thm:rr}. In addition, the uniqueness part of \eqref{eq:rr} follows from the existence part as one may consider the dual problem of \eqref{eq:rr} in the functional spaces with respect to the conjugate index $q'=q/(q-1)$.
\end{rmk}

To prove Theorem \ref{thm:rr}, we recall some results on the one-phase flows in \cite{GS2014,Saito2015}.
\begin{prop}[{\cite[Theorem 2.3]{GS2014}}]
\label{prop:v+1}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{+},$ $\nu_+,$ $\gamma_{1+},$ $\gamma_{2+}>0.$
	For any $\bg_+ \in  L_q(\Omega_+)^N,$ there exist constants $\lambda_0, r_b$ and the operator family
	\begin{equation*}
		\CA_+^1(\lambda) \in \Hol\Big( \Gamma_{\ep,\lambda_0} ; 
		\CL\big( L_q(\Omega_+)^N;H^2_q(\Omega_+)^N \big) \Big)
	\end{equation*}
	such that $\Bv_+^1= \CA_+^1(\lambda) \, \bg_+$ solves the following system
	\begin{equation}\label{eq:rr_1}
		\left\{ \begin{aligned}
			&\gamma_{1+}\lambda\bv_+^1-\Di\bS_{\delta+}(\bv_+^1)=\bg_+
			&&\quad&\text{in}& \quad  \Omega_+, \\
			&\bS_{\delta+}(\bv_+^1)\bn_{\Gamma}=0
			&&\quad&\text{on}& \quad \Gamma.
		\end{aligned}
		\right.
	\end{equation} 
	Here the set $\Gamma_{\ep,\lambda_0}$ is defined by \eqref{def:Gamma} for some $\delta_0>0$ and $\bn_{\Gamma}=(0,\cdots,0,-1)^{\top}.$
	Moreover, we have 
	\begin{equation*}
		\CR_{\CL\big(L_q(\Omega_+)^N; H^{2-j}_q(\Omega_+)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{j\slash 2}\CA_+^1(\lambda)\big) : 
		\lambda \in \Gamma_{\ep,\lambda_0} \Big\}\Big) \leq r_b
	\end{equation*}
	for $\ell =0,1,$ $j=0,1,2,$ and $\tau = \Im \lambda.$ 
	Above the choice of  $r_b$ depends solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1+},$ $\gamma_{2+},$ $\mu_{+},$ 
	$\nu_+,$  $\lambda_0$ and $\delta_0.$
\end{prop}

\begin{prop}[{\cite[Theorem 1.5]{Saito2015}}]
\label{prop:6.3}
Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{-},$  $\gamma_{1-}>0.$ Let us set
	\begin{equation*}
		\begin{aligned}
			W_q (\Omega_-)&=\big\{ (\Bf_1,f_2,\Bf_3) \in  L_q(\Omega_-)^N \times 
			H^1_q(\Omega_-)\times L_q(\Omega_-)^N : f_2=\dv \Bf_3 \big\},\\
			\CW_q(\Omega_-)&=\big\{ (\Bf_1,g_2,f_2,\Bf_3) : 
			(\Bf_1,f_2,\Bf_3)  \in  W_q (\Omega_-),\, g_2 \in L_q(\Omega_-)\big\}.
		\end{aligned}
	\end{equation*}
	For any $(\bg_-,g_d,\fg_d) \in  W_q(\Omega_-),$ 
	there exist constants $\lambda_0, r_b$ and the operator families
	\begin{equation*}
		\begin{aligned}
			\CA_-^1(\lambda) &\in \Hol\Big( \Sigma_{\ep,\lambda_0} ; 
			\CL\big( \CW_q(\Omega_-) ;H^2_q(\Omega_-)^N \big) \Big),\\
			\CP_-^1(\lambda) &\in \Hol\Big( \Sigma_{\ep,\lambda_0} ; 
			\CL\big( \CW_q(\Omega_-) ;\wh H^1_q(\Omega_-) \big) \Big)
		\end{aligned}
	\end{equation*}
	such that $(\Bv_-^1,\fp_-^1)= \big(\CA_-^1(\lambda),\CP_-^1(\lambda)\big)  \,
	(\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d)$ solves the following system
	\begin{equation}\label{eq:rr_2}
		\left\{ \begin{aligned}
			&\gamma_{1-}\lambda\bv_-^1-\Di \bT_-(\bv_-^1,\fp_-^1)=\bg_-
			&&\quad&\text{in}& \quad  \Omega_-, \\ 
			&\di\bv_-^1= g_d =\dv \fg_d
			&&\quad&\text{in}& \quad  \Omega_-, \\ 
			&\bT_-(\bv_-^1,\fp_-^1)\bn =0
			&&\quad&\text{on}& \quad \Gamma,\\
			&\bv_-^1=0
			&&\quad&\text{on}& \quad S.
		\end{aligned}
		\right.
	\end{equation}
	Moreover, we have 
	\begin{gather*}
		\CR_{\CL\big(\CX_q(\Omega_-); H^{2-j}_q(\Omega_-)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{j\slash 2}\CA_-^1(\lambda)\big) : 
		\lambda \in \Sigma_{\ep,\lambda_0} \Big\}\Big) \leq r_b,\\
		\CR_{\CL\big(\CX_q(\Omega_-); L_q(\Omega_-)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}   \nabla \CP_-^1(\lambda) : 
		\lambda \in \Sigma_{\ep,\lambda_0} \Big\}\Big) \leq r_b
	\end{gather*}
	for $\ell =0,1,$ $j=0,1,2,$ and $\tau = \Im \lambda.$ 
	Above the choice of  $r_b$ depends solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1-},$ $\mu_{-},$ $\lambda_0$ and $b.$
\end{prop}

Inspired by Propositions \ref{prop:v+1} and \ref{prop:6.3},  we decompose the solution  of \eqref{eq:rr} as 
\begin{equation*}
	\bv_+= \bv_+^1+\bv_+^2,\quad 
	\bv_-=\bv_-^1+\bv_-^2, \quad \fp_-=\fp_-^1 +\fp_-^2
\end{equation*}
with 
$$\Bv_+^1= \CA_+^1(\lambda) \, \bg_+ 
\quad \text{and} \quad 
(\Bv_-^1,\fp_-^1)= \big(\CA_-^1(\lambda),\CP_-^1(\lambda)\big)  
\,(\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d).$$ 
Thus the compensated part $(\bv_+^2,\bv_-^2, \fp_-^2)$ satisfies 
\begin{equation}\label{eq:rr_3}
	\left\{ \begin{aligned}
		&\gamma_{1+}\lambda\bv_+^2-\Di\bS_{\delta+}(\bv_+^2)=0
		&&\quad&\text{in}& \quad  \Omega_+, \\
		&\gamma_{1-}\lambda\bv_-^2-\Di \bT_-(\bv_-^2,\fp_-^2)=0
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
           &\di\bv_-^2=0
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
		&\bS_{\delta+}(\bv_+^2)\bn
		-\bT_-(\bv_-^2,\fp_-^2)\bn=\bh
		&&\quad&\text{on}& \quad \Gamma,\\
		& \bv_+^2-\bv_-^2=\bk-(\bv_+^1-\bv_-^1)
		&&\quad&\text{on}& \quad \Gamma,	\\
		&\bv_-^2= 0
		&&\quad&\text{on}& \quad S.   
	\end{aligned}
	\right.
\end{equation}

Next, for $\bG_{\lambda}=(\bg_+,\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d, 
\lambda^{1/2} \bh,\bh,\lambda\bk,\lambda^{1/2}\bk,\bk)\in \CY_q(\dot \Omega),$ we denote 
\begin{equation*}
	\begin{aligned}
		\bH_{\lambda} &=(\bg_+,\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d, \lambda\bk,\lambda^{1/2}\bk,\bk),\\
		\CK(\lambda) \bH_{\lambda} &= \bk-\CA_+^1(\lambda) \bg_+
		+\CA_-^1(\lambda)\,(\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d),\\
		\CT(\lambda) \bG_{\lambda}&= 
		(\lambda^{1/2} \bh,\bh,\lambda\CK(\lambda) \bH_{\lambda},\lambda^{1/2}\CK(\lambda) \bH_{\lambda},\CK(\lambda) \bH_{\lambda}).
	\end{aligned}
\end{equation*}
Then the operator family $\CT(\lambda) $ can be regarded as the $\CR$-bounded mappings from $\CY_q(\dot \Omega)$ into $\CZ_q(\dot \Omega)$  thanks to Propositions \ref{prop:v+1} and \ref{prop:6.3}.
Thus 
\begin{equation*}
	(\bv_{\pm}^2,\fp_-^2)=\big(\CS_{\pm}(\lambda),\CP_-(\lambda)\big) \circ \CT(\lambda) \bG_{\lambda}
\end{equation*}
solves \eqref{eq:rr_3} clearly. Moreover, Remark \ref{rmk:R-bdd} and Theorem \ref{thm:5.1} yield 
\begin{equation}\label{es:vp-2}
    \begin{aligned}
       	\CR_{\CL\big(\CY_q(\dot \Omega); H^{2-j}_q(\Omega_\pm)^N \big)}
	\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{j/2}
	\CS_{\pm}(\lambda) \circ \CT(\lambda) \big) : 
	\lambda \in \Gamma_{\ep,\lambda_0} \Big\}\Big) \lesssim 1,\\
	\CR_{\CL\big(\CY_q(\dot \Omega); L_q(\Omega_-)^N \big)}
	\Big( \Big\{ (\tau \pa_{\tau})^{\ell}   \nabla \CP_-(\lambda)\circ \CT(\lambda) : 
	\lambda \in \Gamma_{\ep,\lambda_0} \Big\}\Big) \lesssim 1. 
    \end{aligned}
\end{equation}

Finally, we define 
\begin{align*}
	\CA_{+}^0 (\lambda) \bG_{\lambda}&=\CA_+^1(\lambda)\bg_+
	+\CS_{+}(\lambda) \circ \CT(\lambda) \bG_{\lambda},\\
	\CA_{-}^0(\lambda)\bG_{\lambda}
	&=\CA_-^1(\lambda) (\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d)
	+\CS_{-}(\lambda) \circ \CT(\lambda) \bG_{\lambda},\\
	\CB_-^0(\lambda)\bG_{\lambda}&=
	\CP_-^1(\lambda) (\bg_-,\lambda^{1/2} g_d, g_d, \lambda \fg_d)
	+\CP_-(\lambda)\circ \CT(\lambda)\bG_{\lambda}.
\end{align*}
According to Remark \ref{rmk:R-bdd}, \eqref{es:vp-2}, Propositions \ref{prop:v+1} and \ref{prop:6.3}, we have the desired estimates for the operator families $\CA_\pm^0(\lambda)$ and  $\CB_-^0(\lambda).$






