 \section{Linear theory on the maximal $L_p$-$L_q$ regularity property}
\label{sec:mr}

In this section, we shall prove Theorem \ref{thm:mr}.
As we will see later, the main difficulty is the case where source terms $f_+=g_{\pm}=g_d=\fg_d=\bh=0$ in \eqref{eql:1}. This essentially leads to the semigroup theory.
However, the model \eqref{eql:1} contains the incompressible part in the region $\Omega_-$. 
Thus we need to introduce some reduced two-phase gas-liquid operator to overcome the difficulty from the pressure term $\fp_-$ as the one-phase incompressible viscous flow (see for instance \cite{Shibata2020} and the references therein). 
Subsections \ref{subsec:reduced_1} and \ref{subsec:reduced_2} are dedicated to the reduced problem of \eqref{eql:1}. In Subsection \ref{subsec:reduced_3}, we will derive the maximal $L_p$-$L_q$ regularity property in view of Theorem \ref{thm:main2} and the Weis' theory \cite{Weis2001}.

\subsection{Resolvent problem for the reduced two-phase operator} 
\label{subsec:reduced_1}
Let us review some result from the one-phase incompressible problem in the layer $\Omega_-.$ 
According to \cite[p.1493]{Saito2018}, we have the following technical lemma.
\begin{lem}\label{lem:weak}
Let $1<q<\infty$ and $q'=q/(q-1).$
For any $\Bf \in L_q(\Omega_-)^N$ and $g\in W^{1-1/q}_q(\Gamma)$
there exists a solution $\fq \in H^1_{q}(\Omega_-)+H^1_{q,\Gamma}(\Omega_-)$ satisfying 
\begin{equation*}
\left\{ \begin{aligned}
    & (\nabla \fq, \nabla \varphi)_{\Omega_-}=(\Bf,\nabla \varphi)_{\Omega_-}, \,\,\,\forall \,\,\varphi \in H^1_{q',\Gamma}(\Omega_-),\\
    & \fq|_{\Gamma}=g.\\
    \end{aligned} \right.
\end{equation*}
Moreover, there exists a contant $C$ such that 
\begin{equation*}
    \|\fq\|_{H^1_q(\Omega_-)} \leq C \big( \|\Bf\|_{L_q(\Omega_-)} + \|g\|_{W^{1-1/q}_q(\Gamma)} \big).
\end{equation*}
\end{lem}

Let $\rho_+ \in H^1_q(\Omega_+)$ and $\bv_{\pm}\in H^2_q(\Omega_{\pm})^N.$ According to Lemma \ref{lem:weak},  
there exists 
$$\theta=\CK_-(\rho_+,\bv_+,\bv_-) \in H^1_{q}(\Omega_-)+H^1_{q,\Gamma}(\Omega_-)$$ 
solving the following variational problem
\begin{equation}\label{def:K}
\left\{ \begin{aligned}
  &  (\nabla \theta, \nabla \varphi)_{\Omega_-} 
    = \big(\DV  \bS_- (\bv_-) -\nabla \dv \bv_-, \nabla \varphi \big)_{\Omega_-},\,\,\,\forall \,\,\varphi \in H^1_{q',\Gamma}(\Omega_-),\\
  &      \theta|_{\Gamma} =  \bS_-(\bv_-)\bn \cdot \bn -\dv \bv_- 
    -\bS_{+}(\bv_+) \bn \cdot \bn +\gamma_{2+} \rho_+.
        \end{aligned} \right.
\end{equation}
Moreover, we have 
\begin{equation*}
    \|\CK_-(\rho_+,\bv_+,\bv_-)\|_{H^1_{q}(\Omega_-)} \lesssim \|\bv_+\|_{H^2_q(\Omega_+)}+\|\bv_-\|_{H^2_q(\Omega_-)}
    +\|\rho_+\|_{H^{1}_q(\Omega_+)}.
\end{equation*}
%For simplicity, we denote $\CK_{-}(\bv_-)=\CK_{-}(0,0,\bv_-).$


With the operator $\CK_-$ defined by \eqref{def:K} at hand, we consider the following generalized reduced resolvent problem:
\begin{equation}\label{gres:2}
	\left\{ \begin{aligned}
		&\lambda\rho_++\gamma_{1+}\di \bv_+=f_+
		&&\quad&\text{in}& \quad \Omega_+, \\
		&\lambda\bv_+-\gamma_{1+}^{-1}\DV\big(\bS_+(\bv_+)-\gamma_{2+}\rho_+\bI\big)=\bg_+
		&&\quad&\text{in}& \quad  \Omega_+, \\
		&\lambda\bv_--\gamma_{1-}^{-1} \Di\big(\bS_-(\bv_{-})-\CK_-(\rho_+,\bv_+,\bv_-)\bI\big)=\bg_-
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
		&\big(\bS_+(\bv_+)-\gamma_{2+}\rho_+\bI\big)\bn
		=\big(\bS_-(\bv_{-})-\CK_-(\rho_+, \bv_+,\bv_-)\bI\big)\bn
		&&\quad&\text{on}& \quad \Gamma,\\
		& \bv_+-\bv_-=\bk
		&&\quad&\text{on}& \quad \Gamma,	\\
		&\bv_-= 0
		&&\quad&\text{on}& \quad S.   
	\end{aligned}
	\right.
\end{equation}
For \eqref{gres:2}, we have 
\begin{thm}\label{thm:gres-2}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{\pm},$ $\nu_+,$ $\gamma_{1\pm},$ $\gamma_{2+}>0.$
	Let us introduce the functional spaces for source terms in \eqref{gres:2} as follows 
	\begin{equation*}
		\begin{aligned}
			X_q^1 (\dot \Omega)&=\big\{ (f_1,\Bf_2,\Bf_3,\Bf_4) :
			f_1\in H^1_q(\Omega_+),
			\Bf_2\in L_q(\Omega_+)^N, \Bf_3\in J_q(\Omega_-)^N,
		   \Bf_4\in H^{2}_q(\dot \Omega)^N\big\}, \\
			\CX_q^1(\dot\Omega)&=\big\{ (f_1,\Bf_2,\Bf_3,\bh_4,\bg_4,\Bf_4) :
			(f_1,\Bf_2,\Bf_3,\Bf_4) \in X^1_q(\dot \Omega),\,
			\bh_4\in L_q(\dot\Omega)^N,\bg_4\in H^1_q(\dot\Omega)^N\big\}.
		\end{aligned}
	\end{equation*} 
	In addition, we write for short that 
	\begin{equation*}
			\bF^1=(f_+, \bg_+,\bg_-,\bk),\quad
			\bF^1_{\lambda}=(f_+,\bg_+,\bg_-,\lambda\bk, \lambda^{1/2} \bk,\bk).
	\end{equation*}
	For any $\bF^1\in X_q^1(\dot\Omega),$ there exist constants $\lambda_0, r_b$ and the operator families
	\begin{equation*}
		\begin{aligned}
			\Theta^1_+(\lambda) &\in \Hol\Big( \Sigma_{\ep, \lambda_0}  \cap K_{\ep} ; 
			\CL\big( \CX^1_q(\dot \Omega) ; H^1_q(\Omega_+) \big) \Big),\\
			\CA^1_\pm(\lambda) &\in \Hol\Big( \Sigma_{\ep, \lambda_0}  \cap K_{\ep} ; 
			\CL\big( \CX_q^1(\dot \Omega) ;H^2_q(\Omega_\pm)^N \big) \Big)
		\end{aligned}
	\end{equation*}
	such that $(\rho_+, \bv_+,\bv_-)
	= \big(\Theta_+^1(\lambda) , \CA^1_+(\lambda), \CA^1_-(\lambda)\big) \,\bF^1_{\lambda}$
	solves \eqref{gres:2}.  Here the regions $\Sigma_{\ep, \lambda_0}$ and $K_{\ep}$ are defined by \eqref{eq:KSigma}. Moreover, we have 
	\begin{gather*}
		\CR_{\CL\big(\CX^1_q(\dot \Omega); H^{1}_q(\Omega_+) \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{k}
		\Theta^1_+(\lambda)\big) : 
		\lambda \in \Sigma_{\ep, \lambda_0}  \cap K_{\ep} \Big\}\Big) \leq r_b,\\
		\CR_{\CL\big(\CX^1_q(\dot\Omega); H^{2-j}_q(\Omega_\pm)^N \big)}
		\Big( \Big\{ (\tau \pa_{\tau})^{\ell}\big( \lambda^{j\slash 2}
		\CA^1_\pm(\lambda)\big) : 
		\lambda \in \Sigma_{\ep, \lambda_0}  \cap K_{\ep} \Big\}\Big) \leq r_b
	\end{gather*}
	for $k,\ell =0,1,$ $j=0,1,2,$ and $\tau = \Im \lambda.$ 
	Above the choice of  $r_b$ depends solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1\pm},$ $\gamma_{2+},$ $\mu_{\pm},$ 
	$\nu_+,$  $\lambda_0$ and $b.$
\end{thm}


In fact, it is not hard to prove Theorem \ref{thm:gres-2} by Theorem \ref{thm:main2} and the following proposition.
\begin{prop}
Let $1<q<\infty$ and $\lambda \in \Sigma_{\ep,\lambda_0} \cap K_{\ep}.$
Let us introduce
	\begin{equation}\label{def:Jq}
		J_q(\Omega_-)=\big\{\bu_-\in L_q(\Omega_-)^N\,|\,(\bu_-,\nabla\varphi)_{\Omega_-}=0,\quad\forall\,\,\varphi\in H^1_{q',\Gamma}(\Omega_-)\big\}.
	\end{equation}
Suppose that $f_+\in H^1_q(\Omega_+),$ $\bg_{+} \in L_q(\Omega_{+})^N,$ $\bg_{-} \in J_q(\Omega_{-})^N,$ and $\bk\in H^{2}_q(\dot \Omega)^N.$ For simplicity, let us denote 
\begin{equation*}
\begin{aligned}
      E^{1}_q (\dot \Omega)&=H^1_{q}(\Omega_+) \times H^2_{q}(\Omega_+)^N
    \times \big( H^2_{q}(\Omega_-)^N \cap J_q(\Omega_-) \big)\times H^1_q(\Omega_-), \\
          E^{2}_q (\dot \Omega)&=H^1_{q}(\Omega_+) \times H^2_{q}(\Omega_+)^N \times H^2_{q}(\Omega_-)^N.
\end{aligned}
\end{equation*}
Then the following assertions hold true.
\begin{enumerate}[label=(\arabic*)]	
    \item If $(\rho_+,\bv_+,\bv_-,\fp_-) \in E^1_q(\dot \Omega) $ solves the problem
    \begin{equation}\label{gres:1}
	\left\{ \begin{aligned}
		&\lambda\rho_++\gamma_{1+}\di \bv_+=f_+
		&&\quad&\text{in}& \quad \Omega_+, \\
		&\lambda\bv_+-\gamma_{1+}^{-1}\DV\big(\bS_+(\bv_+)-\gamma_{2+}\rho_+\bI\big)=\bg_+
		&&\quad&\text{in}& \quad  \Omega_+, \\
		&\lambda\bv_--\gamma_{1-}^{-1} \Di\big(\bS_-(\bv_{-})-\fp_-\bI\big)=\bg_-
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
  		& \di\bv_-=0
		&&\quad&\text{in}& \quad  \Omega_-, \\ 
		&\big(\bS_+(\bv_+)-\gamma_{2+}\rho_+\bI\big)\bn
		=\big(\bS_-(\bv_{-})-\fp_-\bI\big)\bn
		&&\quad&\text{on}& \quad \Gamma,\\
		& \bv_+-\bv_-=\bk
		&&\quad&\text{on}& \quad \Gamma,	\\
		&\bv_-= 0
		&&\quad&\text{on}& \quad S,  
	\end{aligned}
	\right.
\end{equation} then $(\rho_+,\bv_+,\bv_-)$ satisfies \eqref{gres:2}.
    \item If $(\rho_+,\bv_+,\bv_-) \in E^2_q(\dot \Omega)$ solves \eqref{gres:2}, then $\big(\rho_+,\bv_+,\bv_-, \CK_-(\rho_+, \bv_+,\bv_-)\big)$ is a solution of \eqref{gres:1}.
\end{enumerate}


\end{prop}
\begin{proof}
Suppose that $(\rho_+,\bv_+,\bv_-,\fp_-) \in E^1_q(\dot \Omega)$  satisfies \eqref{gres:1}.
Let us denote $$\theta=\CK_-(\rho_+,\bv_+,\bv_-) \in H^1_q(\Omega_-).$$ 
For any $\varphi \in H^1_{q',\Gamma}(\Omega_-),$ taking the inner product of $\eqref{gres:1}_3$ with $\nabla \varphi$ yields 
\begin{equation*}
\begin{aligned}
 0=(\bg_-,\nabla \varphi)_{\Omega_-} &= (\lambda\bv_-,\nabla \varphi)_{\Omega_-}
   -\big(\gamma_{1-}^{-1}\Di \bS_-(\bv_-),\nabla \varphi\big)_{\Omega_-}  
   +(\gamma_{1-}^{-1}\nabla \fp_-,\nabla \varphi)_{\Omega_-} \\
   &= \gamma_{1-}^{-1}\big(\nabla (\fp_--\theta),\nabla \varphi\big)_{\Omega_-},
\end{aligned}
\end{equation*}
 where we have used the facts 
\begin{equation*}
  \bg_- \in J_q(\Omega_-), \quad  \dv \bv_-=0\quad 
   \hbox{and}\quad  \bv_-|_{S}=0.
\end{equation*}
Moreover, we have 
\begin{equation*}
   (\fp_--\theta)|_{\Gamma}=0.
\end{equation*}
Then the uniqueness of the variational problem (see \cite[Proposition 3.4]{Saito2018} for instance) yields $\fp_-=\theta.$
\medskip

On the other hand, suppose that $(\rho_+,\bv_+,\bv_-) \in E^2_q(\dot \Omega)$ solves \eqref{gres:2}.
It suffices to verify that  $\dv \bv_-$ vanishes in $\Omega_-.$
The definition of the operator $\theta=\CK_-(\rho_+, \bv_+,\bv_-)$ implies that $\dv \bv_-|_{\Gamma}=0.$
Then taking the inner product of $\eqref{gres:2}_3$ with $\nabla \varphi$ and integration by parts yield
\begin{equation*}
\begin{aligned}
 0=-(\bg_-,\nabla \varphi)_{\Omega_-} &= -(\lambda\bv_-,\nabla \varphi)_{\Omega_-}
   +\big(\gamma_{1-}^{-1}\Di \bS_-(\bv_-),\nabla \varphi\big)_{\Omega_-}  
   -(\gamma_{1-}^{-1}\nabla \theta,\nabla \varphi)_{\Omega_-} \\
   &= \lambda (\dv \bv_-,\varphi) + \gamma_{1-}^{-1}\big(\nabla \dv \bv_-,\nabla \varphi\big)_{\Omega_-}.
\end{aligned}
\end{equation*}
Then \cite[Proposition 4.2]{Saito2018} furnishes that $\bv_-$ is divergence-free in $\Omega_-.$
\end{proof}

\subsection{Semigroup generated by the reduced two-phase operator}
\label{subsec:reduced_2}
In this subsection, we consider the following evolution problem:
\begin{equation}\label{ibeq:0}
	\left\{ \begin{aligned}
		&\partial_t \rho_++\gamma_{1+}\di \bv_+=0
		&&\quad&\text{in}& \quad \Omega_+\times \BR_+, \\
		&\pd_t \bv_+-\gamma_{1+}^{-1}\DV\big(\bS_+(\bv_+)-\gamma_{2+}\rho_+\bI\big)=0
		&&\quad&\text{in}& \quad  \Omega_+\times \BR_+, \\
		&\pd_t\bv_--\gamma_{1-}^{-1} \Di\big(\bS_-(\bv_{-})-\CK_-(\rho_+,\bv_+,\bv_-)\bI\big)=0
		&&\quad&\text{in}& \quad  \Omega_-\times \BR_+, \\ 
		&\big(\bS_+(\bv_+)-\gamma_{2+}\rho_+\bI\big)\bn
		=\big(\bS_-(\bv_{-})-\CK_-(\rho_+, \bv_+,\bv_-)\bI\big)\bn
		&&\quad&\text{on}& \quad \Gamma\times \BR_+,\\
		& \bv_+=\bv_-
		&&\quad&\text{on}& \quad \Gamma\times \BR_+,	\\
		&\bv_-= 0
		&&\quad&\text{on}& \quad S\times \BR_+,\\   
        		&(\rho_+,\bv_+)\big|_{t=0}=(\rho_{+,0},\bv_{+,0})
		&&\quad&\text{in}& \quad \Omega_+,\\
		&\bv_-\big|_{t=0}=\bv_{-,0}
		&&\quad&\text{in}& \quad \Omega_-
	\end{aligned}
	\right.
\end{equation}
for $\BR_+=(0,\infty)$ and $\bn=(0,\dots,0,1)^{\top}.$ In fact, the system \eqref{ibeq:0} can be written as some abstract Cauchy problem associated to some reduced two-phase operator.
Let us introduce some notations.
\begin{dfn}\label{def:tp-A}
Let $1<q<\infty$ and $\dot\Omega=\Omega_+ \cup \Omega_-.$ Let us set the underlying space 
\footnote{See \eqref{def:Jq} for the definition of $J_q(\Omega_-)$.}
\begin{equation}\label{def:under}
    \CX_q(\dot\Omega)=H^1_q(\Omega_+) \times L_q(\Omega_+)^N \times J_q(\Omega_-).
\end{equation}
Then, according to \eqref{ibeq:0}, we define the reduced two-phase gas-liquid operator 
\begin{equation*}
    \CA \begin{pmatrix}
        \theta_+\\\bu_+\\\bu_-
    \end{pmatrix}=\begin{pmatrix}
        -\gamma_{1+} \dv \bu_+ \\
        \gamma_{1+}^{-1}\DV\big(\bS_+(\bu_+)-\gamma_{2+}\theta_+\bI\big)\\
        \gamma_{1-}^{-1} \Di\big(\bS_-(\bu_{-})-\CK_-(\theta_+,\bu_+,\bu_-)\bI\big)
    \end{pmatrix}
\end{equation*}
whenever $(\theta_+,\bu_+,\bu_-)$ lies in the space
    \begin{equation}\label{cdt:intial0}
    \begin{aligned}
\CD_q(\CA)=\Big\{(\theta_+,\bu_+,\bu_-)\in \CX_q(\dot \Omega):\, &
        \bu_\pm \in H^2_q(\Omega_\pm)^N, \, \bu_+|_{\Gamma}=\bu_-|_{\Gamma},\, \bu_-|_{S}=0,\\
       & \quad \text{and}\,\,\, \CT_{\bn} \big(\mu_+\bD(\bu_{+})\bn\big)|_{\Gamma}
         =\CT_{\bn} \big(\mu_-\bD(\bu_{-})\bn \big) |_{\Gamma} \Big\}.
    \end{aligned}
    \end{equation}
Here the projection $\CT_{\bn}$ is defined in \eqref{def:proj}.
\end{dfn}


Now, writing $V=(\rho_{+},\bv_{+},\bv_{-})$ and $V_0=(\rho_{+,0},\bv_{+,0},\bv_{-,0}),$ we may regard \eqref{ibeq:0} as the following abstract Cauchy problem 
\begin{equation*}
    \pd_t \bV -\CA \bV =0, \quad \bV|_{t=0}=\bV_0.
\end{equation*}
According to Theorem \ref{thm:gres-2}, there exists a $\lambda_0>0$ such that 
$\Sigma_{\ep,\lambda_0}\cap K_\varepsilon$ belongs to the resolvent set $\rho(\CA)$ of $\CA.$
Thus the standard semigroup theory allows us to establish the following result:
\begin{thm}\label{thm:sg}
Let $1<q<\infty.$ Then the reduced two-phase gas-liquid operator $\CA$ in Definition \ref{def:tp-A}  generates a $C^0$-semigroup $\{T(t)\}_{t\geq 0}$ on $\CX_q(\dot \Omega)$ in \eqref{def:under},  which is also analytic.
\end{thm}
Moreover, Theorem \ref{thm:sg} and the interpolation argument (see \cite[Theorem 3.9]{ShiShi2008} for instance) imply that the solution $(\rho_+,\bv_{+}, \bv_{-}, \fp_-)$ of \eqref{ibeq:0} satisfies
\begin{equation}\label{es:sg}
\CN_{p,q,\gamma_0}(\rho_+,\bv_{+}, \bv_{-}, \fp_-) \leq 
C \|(\rho_{+,0}, \bv_{+,0},\bv_{-,0})\|_{\CD_{p,q}(\dOm)} 
\end{equation}
with $\fp_-=\CK_-(\rho_+,\bv_+,\bv_-),$ where the notations $\CD_{p,q}(\dOm)$ and $\CN_{p,q,\gamma_0}$ have been defined in Definition \ref{def:FD} and Theorem \ref{thm:mr} respectively.


\subsection{Proof of Theorem \ref{thm:mr}}
\label{subsec:reduced_3}
In this subsection, we begin with the following problem 
\begin{equation}\label{eq:MR_1}
	\left\{ \begin{aligned}
		&\pd_t\rho_+^1 + \gamma_{1+}\, \dv \bv_+^1=f_+
		&&\quad&\text{in} &\quad \Omega_+ \times \BR, \\
		&\gamma_{1+}\pd_t\bv_+^1 - \DV\bT_+(\bv_+^1,\gamma_{2+}\rho_+^1)  = \bg_+
		&&\quad&\text{in}& \quad \Omega_+ \times \BR, \\
		&\gamma_{1-}\pd_t\bv_-^1  - \Di\bT_-(\bv_{-}^1,\fp_-^1) = \bg_-
		&&\quad&\text{in}& \quad \Omega_- \times \BR, \\
		& \di \bv_-^1 = g_d=\di \fg_d
		&&\quad&\text{in}& \quad \Omega_- \times \BR, \\
		&\big(\bT_+(\bv_+^1,\gamma_{2+}\rho_+^1)- \bT_-(\bv_-^1,\fp_-^1)\big)\bn
		= \bh
		&&\quad&\text{on}& \quad \Gamma \times \BR,\\
		&\bv_{+}^1=\bv_{-}^1
		&&\quad&\text{on}& \quad \Gamma \times \BR,  \\
		& \bv_-^1=0
		&&\quad&\text{on}& \quad   S \times \BR.
	\end{aligned}
	\right.
\end{equation}
Then applying the Laplace transform \eqref{eq:Laplace}  to \eqref{eq:MR_1} implies that 
\begin{equation*}
	\left\{ \begin{aligned}
		&\lambda \wh{\rho_+^1} + \gamma_{1+}\, \dv \wh{\bv_+^1}=\wh{f_+}
		&&\quad&\text{in} &\quad \Omega_+, \\
		&\gamma_{1+}\lambda \wh{\bv_+^1} - \DV\bT_+(\wh{\bv_+^1},\gamma_{2+}\wh{\rho_+^1})  = \wh{\bg_+}
		&&\quad&\text{in}& \quad \Omega_+, \\
		&\gamma_{1-}\lambda \wh{\bv_-^1}  - \Di\bT_-(\wh{\bv_{-}^1},\wh{\fp_-^1}) = \wh{\bg_-}
		&&\quad&\text{in}& \quad \Omega_- , \\
		& \di \wh{\bv_-^1} = \wh{g_d}=\di \wh{\fg_d}
		&&\quad&\text{in}& \quad \Omega_- , \\
		&\big(\bT_+(\wh{\bv_+^1},\gamma_{2+}\wh{\rho_+^1})- \bT_-(\wh{\bv_-^1},\wh{\fp_-^1})\big)\bn
		= \wh{\bh}
		&&\quad&\text{on}& \quad \Gamma,\\
		&\wh{\bv_{+}^1}=\wh{\bv_{-}^1}
		&&\quad&\text{on}& \quad \Gamma ,  \\
		&\wh{\bv_-^1}=0
		&&\quad&\text{on}& \quad   S.
	\end{aligned}
	\right.
\end{equation*}
Here $\widehat{f}=\CF_{L} [f]$ denotes the Laplace transform of $f$. In view of \eqref{eq:half} and Theorem \ref{thm:main2}, the system \eqref{eq:MR_1} admits a solution given by
\begin{equation*}
\begin{aligned}
(\rho_+^1, \bv_+^1,\bv_-^1,\fp_-^1)
	&=e^{\gamma t} \CF\Big[ \big(\Theta_+(\lambda) , \CA_+(\lambda), \CA_-(\lambda),\CB_-(\lambda)\big) \,\bG_{\lambda}\Big]  \\
    &=e^{\gamma t} \CF\Big[ \big(\Theta_+(\lambda) , \CA_+(\lambda), \CA_-(\lambda),\CB_-(\lambda)\big)
    \,\CF[e^{-\gamma t}\bF_{\gamma}]\Big] 
\end{aligned}
\end{equation*}
for 
\begin{equation*}
\begin{aligned}
\bG_{\lambda}&=(\wh{f_+},\wh{\bg_+},\wh{\bg_-},\lambda^{1/2} \wh{g_d}, \wh{g_d}, \lambda \wh{\fg_d}, 
			\lambda^{1/2} \wh{\bh},\wh{\bh}),\\
 \bF_{\gamma}&=(f_+,\bg_+,\bg_-,\Lambda^{1/2}_{\gamma} g_d, g_d,  \partial_t \fg_d, 
			\Lambda^{1/2}_{\gamma} \bh,\bh).
\end{aligned}
\end{equation*}
Thus keeping $\CF_{p,q,\gamma_0}(\dot \Omega)$ in Definition \ref{def:FD} in mind,
Weis' theory \cite{Weis2001} yields 
 \begin{equation}\label{es:v1}
\CN_{p,q,\gamma_0}(\rho_+^1,\bv_{+}^1, \bv_{-}^1, \fp_-^1) 
\lesssim \|(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \|_{\CF_{p,q,\gamma_0}(\dot \Omega)}
\end{equation}
for some $\gamma_0>0$.
Moreover, by the trace method and \eqref{es:v1}, we have 
\begin{equation}\label{es:v10}
    \begin{aligned}
        \|\rho_+^1|_{t=0}\|_{H^1_q(\Omega_+)} &\lesssim \|e^{-\gamma t}\rho_+^1\|_{H^1_p(\BR_+;H^1_q(\Omega_+))} 
        \lesssim \|(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \|_{\CF_{p,q,\gamma_0}(\dot \Omega)},\\
        \|\bv_{\pm}^1|_{t=0}\|_{B^{2-2/p}_{q,p}(\Omega_{\pm})}& \lesssim 
\|e^{-\gamma t}\partial_t \bv_{\pm}^1\|_{L_p(\BR_+;L_q(\Omega_{\pm}))} 
+\|e^{-\gamma t}\bv_{\pm}^1\|_{L_p(\BR_+;H^2_q(\Omega_{\pm}))} \\
& \lesssim \|(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \|_{\CF_{p,q,\gamma_0}(\dot \Omega)}.
    \end{aligned}
\end{equation}

Now, suppose that the solution of \eqref{eql:1} can be decomposed as follows
\begin{equation*}
  (\rho_+, \bv_+,\bv_-,\fp_-)
  = (\rho_+^1, \bv_+^1,\bv_-^1,\fp_-^1)|_{t\in \BR_+}+(\rho_+^2, \bv_+^2,\bv_-^2,\fp_-^2).
\end{equation*}
with 
\begin{equation*}
(\rho_{+,0}^2, \bv_{+,0}^2,\bv_{-,0}^2)=
(\rho_{+,0}, \bv_{+,0},\bv_{-,0})-(\rho_{+}^1, \bv_{+}^1,\bv_{-}^1)|_{t=0}.    
\end{equation*}
According to \eqref{eq:1.4}, \eqref{eq:MR_1} and \eqref{es:v10},  it is not hard to find that  $(\rho_{+,0}^2, \bv_{+,0}^2,\bv_{-,0}^2)\in \CD_q(\CA)$ (see \eqref{cdt:intial0}).
Thus $(\rho_+^2, \bv_+^2,\bv_-^2,\fp_-^2)= T(t) (\rho_{+,0}^2, \bv_{+,0}^2,\bv_{-,0}^2)$ satisfies 
\begin{equation}\label{es:rhovp_2}
\CN_{p,q,\gamma_0}(\rho_+^2,\bv_{+}^2, \bv_{-}^2, \fp_-^2) \lesssim  
\|(\rho_{+,0}, \bv_{+,0},\bv_{-,0})\|_{\CD_{p,q}(\dOm)} 
+\|(f_+, \bg_+, \bg_-, g_d,\fg_d,\bh) \|_{\CF_{p,q,\gamma_0}(\dot \Omega)}
\end{equation}
for $\fp_-^2=\CK_-(\rho_+^2,\bv_+^2,\bv_-^2)$ thanks to \eqref{es:sg} and \eqref{es:v10}. 
Then combining the estimates \eqref{es:v1} and \eqref{es:rhovp_2} implies the desired bound of $  (\rho_+, \bv_+,\bv_-,\fp_-)$.
\smallbreak 

At last, the uniqueness part of Theorem \ref{thm:mr} also holds true by applying \eqref{es:sg} to some dual problem (see \cite[Subsection 4.5]{EvBS2014} for instance). This completes the proof of Theorem \ref{thm:mr}.


