\section{Nonlinear gas-liquid two-phase problem} 
\label{app:non}
As we mentioned in the introduction, the system \eqref{eql:1} comes from some liquid-gas two-phase flow problem in some unbounded domain
$\Omega_{t,-} \cup \Omega_{t,-} \subset \mathbb{R}^N$ for $N\geq 2$ (see Figure \ref{Fig:Omega2}). More precisely, the motion of the viscous gases in $\Omega_{t,+}$ and the viscous liquid in $\Omega_{t,-}$ is separated by a moving sharp interface $\Gamma_t$ with the fixed bottom $S$. 
Furthermore, the viscous fluids obey the Compressible-Incompressible Navier-Stokes equations in view of the \emph{Eulerian} coordinates as follows:
\begin{equation}\label{eq:NS}
	\left\{ \begin{aligned}
		& \pd_t\rho_++\di(\rho_+\bu_+)=0
		&&\quad&\text{in}& \quad  \bigcup_{0<t<T}\Omega_{t,+}\times \{t\}, \\
		&\rho_+(\pd_t\bu_++\bu_+\cdot\nabla\bu_+)
		-\Di \bT_+\big(\bu_+,P(\rho_+)\big)=0
		&&\quad&\text{in}& \quad \bigcup_{0<t<T} \Omega_{t,+}\times \{t\}, \\
		&\rho_-(\pd_t\bu_- +\bu_- \cdot\nabla\bu_-)-\Di \bT_-(\bu_-,\pi_-)=0,
		\quad \di\bu_-=0
		&&\quad&\text{in}& \quad \bigcup_{0<t<T} \Omega_{t,-}\times \{t\}, \\
		&\bT_+\big(\bu_+,P(\rho_+)\big)\bn_t- \bT_-(\bu_-,\pi_-)\bn_t=0
		&&\quad&\text{on}& \quad \bigcup_{0<t<T} \Gamma_t\times \{t\}, \\
		& \bu_+-\bu_-=0,\quad V_{\Gamma_t}=\bu_-\cdot\bn_t
		&&\quad&\text{on} & \quad \bigcup_{0<t<T} \Gamma_t\times \{t\} , \\
		& \bu_-=0
		&&\quad&\text{on}& \quad   S \times (0,T), \\
		&(\rho_+,\bu_+)\big|_{t=0}=(\rho_{+,0},\bu_{+,0})
		&&\quad&\text{in}& \quad \Omega_+,\\
		&\bu_-\big|_{t=0}=\bu_{-,0}
		&&\quad&\text{in}& \quad \Omega_-.
	\end{aligned}
	\right.
\end{equation} 
In \eqref{eq:NS}, the given positive constant $\rho_-$ denotes the mass density of the liquid,
and the unknowns $\bu_{\pm}$, $\rho_+$ and $\pi_-$ are velocity fields of the fluids, the mass density of the gas and the scalar pressure. Besides, $P(\cdot)$ is a smooth function on $[0,\infty)$, $\bn_t$ is the unit normal from $\Omega_{t,-}$ to $\Omega_{t,+}$, $V_{\Gamma_t}$ denotes the normal velocity of the moving surface $\Gamma_t,$
and $\rho_{+,0},\bu_{\pm,0}$ are given initial data.
For simplicity, we assume that the initial state of the unbounded domain $\Omega_{t,-} \cup \Omega_{t,-}$ coincides with the reference domain $\Omega_+ \cup \Omega_-$ in \eqref{dfn:Omega}. 



\subsection{Lagrangian transformation}
\label{ss:Lag}

For the application of the mathematical analysis, we usually transfer the free boundary value problem \eqref{eq:NS} to some system defined in the fixed domain. Without taking surface tension into account, it is standard to write down \eqref{eq:NS} in the Lagrangian coordinates, which allows us to pull back \eqref{eq:NS} to the initial domain along the trajectory of fluid particles (See Figure \ref{fig:LT}). 

\begin{center}
	\begin{figure}[h]
		\centering
		\begin{tikzpicture}[>=stealth]

			% 绘制波浪曲线
			\draw[ domain=-pi:pi, samples=200] plot (\x, {sin(2*\x r)/4}) node[right] {$\Gamma_t$};

			% 绘制y=-b的直线
			\draw (-pi,-2) -- (pi,-2) node[right] {$S$};

			% 标记不同区域
			\node at (1,1) {$\Omega_{t,+}$};
			\node at (1,-1) {$\Omega_{t,-}$};

			% 绘制波浪曲线
			\draw (2.2*pi,0) -- (4*pi,0) node[right] {$\Gamma$};

			% 绘制y=-b的直线
			\draw (2.2*pi,-2) -- (4*pi,-2) node[right] {$S$};

			% 标记不同区域
			\node at (10,1) {$\Omega_{+}$};
			\node at (10,-1) {$\Omega_{-}$};

			%	\draw[->] (3*pi/2,-0.5) -- (pi*2,-0.5);

		\end{tikzpicture}
		\caption{Role of the Lagrangian transform}
  \label{fig:LT}
	\end{figure}
\end{center}

Now, let us introduce the so-called \emph{Lagrangian transformations} for the two-phase problem \eqref{eq:NS}:
\begin{equation}\label{def:LT}
	X_{\bv_\pm}(y,t)= y + \int^t_0 \bv_\pm(y, s)\,ds,
 \quad \forall \,\,y\in \Omega= \Omega_{+} \cup \Gamma \cup \Omega_- 
 \,\,\,\text{and}\,\,\,0<t<T,
\end{equation}
where \emph{Lagrangian velocities} $\bv_\pm=\bv_\pm(y,t).$ 
Moreover, we suppose that 
\begin{equation*}
\begin{aligned}
   \Omega_{t,\pm} &= \{x =X_{\bv_\pm}(y,t): y \in \Omega_{\pm}\}, \\
	\Gamma_t &= \{x =X_{\bv_+}(y,t){ = X_{\bv_-}(y,t)} : y \in \Gamma\}.
\end{aligned}
\end{equation*}
To use the inverse mappings $X_{\bv_{\pm}}^{-1}(x, t)$ of the transformations in \eqref{def:LT}, we assume that 
\begin{equation}\label{asmp:small_1}
	\int^T_0\|\bv_\pm(\cdot, s)\|_{H^1_\infty(\Omega_\pm)}\,ds \leq \delta <1.
\end{equation}



In what follows, we will derive the nonlinear system in the Lagrangian coordinates.
Let us denote the positive constant $\gamma_{1+}$ for the equilibrium state of the density, namely, 
\begin{equation*}
  \rho_{+,0}=\gamma_{1+}+\eta_{+,0}  
\end{equation*}
for some function $\eta_{+,0.}$
Then we set the new unknowns:
\begin{gather*}
\rho_+(x, t) =  \gamma_{1+} +\eta_+ \big(X^{-1}_{\bv_+}(x, t), t\big), \quad
\bu_{\pm}(x, t) = \bv_{\pm}\big(X^{-1}_{\bv_\pm}(x, t), t\big),\quad 
\fp_-(x,t)=\pi_-\big(X^{-1}_{\bv_-}(x,t), t\big).
\end{gather*}
Then the kinematic condition $V_{\Gamma_t}=\bu_-\cdot\bn_t$ is automatically satisfied under
\eqref{def:LT}. 
\smallbreak 
Note that
$$\nabla_y X_{\bv_\pm}= \bI + \int^t_0\nabla_y\bv_\pm(y, s)\,ds.$$
Then, by the assumption \eqref{asmp:small_1}, the inverses of $\nabla_y X_{\bv_\pm}$ are given by 
\begin{equation}\label{eq:Vk}
\big(\nabla_y X_{\bv_\pm}\big)^{-1}
= \bI + \bV_0(\bk_\pm) ,    
\end{equation}
where $\bV_0(\bk_\pm)$ are matrix-valued functions defined by 
$$\bV_0(\bk_\pm)= \sum_{j=1}^{\infty} (-\bk_\pm)^j
\quad \text{for}\quad  
\bk_\pm =\int^t_0\nabla_y\bv_\pm(y, s)\,ds.$$
In particular, $\bV_0(0) = 0.$
Furthermore, let us set the Jacobians $J_{\bv_{\pm}}=\det (\nabla_y X_{\bv_{\pm}}).$ 
In fact, $J_{\bv_{-}}=1$ due to the divergence free condition of $\bu_-$.




In view of the chain rule, we introduce the gradient, divergence and stress tensor operators with respect to \eqref{def:LT},
\begin{equation}\label{eq:1.5}
	\begin{aligned}
		\nabla_{\bv_{\pm}}\bv_{\pm} &= \big(\bI + \bV_0(\bk_{\pm}) \big)\nabla_y\bv_{\pm},\\
		\dv_{\bv_{\pm}} \bv_{\pm} &= \big(\bI+\bV_0(\bk_{\pm})\big):\nabla_y \bv_{\pm}, \\
  		\DV_{\bv_+} \bA &= J_{\bv_+}^{-1} \DV_{y} \Big(J_{\bv_+}\bA \big(\bI + \bV_0(\bk_+) \big) \Big),\\
 \DV_{\bv_-} \bA& =  \DV_{y} \Big(\bA \big(\bI + \bV_0(\bk_-) \big) \Big),\\
   \bT_{\bv_{\pm}}(\bv_{\pm},\pi_{\pm})&=\bS_{\bv_{\pm}}(\bv_{\pm})-\pi_{\pm}\bI\\
  \bS_{\bv_+}(\bv_+)&=\mu_+\bD_{\bv_+} (\bv_+)
		+(\nu_+-\mu_+) (\dv_{\bv_+} \bv_+) \bI,\\ 
  \bS_{\bv_-}(\bv_-)&=\mu_{-}\bD_{\bv_-}(\bv_-),\\
  \bD_{\bv_{\pm}} (\bv_{\pm}) &=\big(\bI + \bV_0(\bk_{\pm}) \big)\nabla \bv_{\pm}
		+(\nabla \bv_{\pm})^{\top}\big(\bI + \bV_0(\bk_{\pm}) \big)^{\top}.
	\end{aligned}
\end{equation}
In addition, $\DV_{\bv_\pm} \bA$ can be also written via
\begin{equation*}
	\DV_{\bv_\pm} \bA= \DV_y \bA+\big(\bV_0(\bk_\pm) \nabla \,|\, \bA\big)
\end{equation*}
with the $i$th component 
$(\bB \nabla | \bA)_{i}= \sum_{j,k=1}^3 B_{jk}\pd_k A_{ij}$ for $\bB=[B_{ij}]_{3\times 3},$ $i=1,2,3.$
Therefore, like the standard operator $\DV,$ $\DV_{\bv} \bA=0$ if $\bA$ is a constant matrix.
\smallbreak 

According to \eqref{eq:NS} and \eqref{eq:1.5}, the knew unknowns $\eta_+,\bv_\pm$ and $\fp_-$ satisfy the following system:
\begin{equation}\label{eq:LL_CNS_1}
	\left\{ \begin{aligned}
		&\pd_t\eta_+ + (\gamma_{1+}+\eta_+)\, \dv_{\bv_+} \bv_+=0
		&&\quad&\text{in} &\quad \Omega_+ \times (0,T), \\
		&(\gamma_{1+}+\eta_+)\pd_t\bv_+-\DV_{\bv_+}\bT_{\bv_+}\big(\bv_+,P(\gamma_{1+}+\eta_+)\big)  = 0 
		&&\quad&\text{in}& \quad \Omega_+ \times (0,T), \\
		&\rho_-\pd_t\bv_-  - \Di_{\bv_-}\bT_{\bv_-}(\bv_{-},\fp_-) = 0,\quad \di_{\bv_-} \bv_- = 0,
		&&\quad&\text{in}& \quad \Omega_- \times (0,T), \\
		&\Big(\bT_{\bv_+}\big(\bv_+,P(\gamma_{1+}+\eta_+)\big) - \bT_{\bv_-}(\bv_-,\fp_-)\Big)\bn_{\bv}
		= 0
		&&\quad&\text{on}& \quad \Gamma \times (0,T),\\
		&\bv_{+}-\bv_{-}
		= 0
		&&\quad&\text{on}& \quad \Gamma \times (0,T),  \\
		& \bv_-=0
		&&\quad&\text{on}& \quad   S \times (0,T), \\
		&(\eta_+, \bv_+)|_{t=0} = (\eta_{+,0}, \bu_{+,0})
		&&\quad&\text{in}& \quad \Omega_+, \\
		&\bv_-\big|_{t=0}=\bu_{-,0}
		&&\quad&\text{in}& \quad \Omega_-,
	\end{aligned}
	\right.
\end{equation}
where the $\bn_\bv$ is defined by
\begin{equation}\label{eq:nv}
  \bn_{\bv} = { \frac{\big(\bI + \bV_0(\bk_+)\big)\bn }{\big|\big(\bI + \bV_0(\bk_+)\big)\bn \big|} }
= { \frac{\big(\bI + \bV_0(\bk_-)\big)\bn }{\big|\big(\bI + \bV_0(\bk_-)\big)\bn \big|} }
\end{equation}
for $\bn=(0,\dots,0,1)^{\top}.$  In fact, the second equality in \eqref{eq:nv} is due to the following lemma.
\begin{lem}
Let us denote
    \begin{equation*}
        \bn_{\bv_+} =  \frac{\big(\bI + \bV_0(\bk_+)\big)\bn }{\big|\big(\bI + \bV_0(\bk_+)\big)\bn \big|} 
        \quad \text{and}\quad 
        \bn_{\bv_-}=\frac{\big(\bI + \bV_0(\bk_-)\big)\bn }{\big|\big(\bI + \bV_0(\bk_-)\big)\bn \big|} \cdot
    \end{equation*}
    Then we have $\bn_{\bv_+}=\bn_{\bv_-}$ if  $\delta$ in \eqref{asmp:small_1} is small enough.
\end{lem}
\begin{proof}
Let $\mathcal{A}_{\bv_\pm}$ stand for the co-factor matrices of $\nabla_y X_{\bv_\pm}.$ 
Then by \eqref{eq:Vk} we get
\begin{equation*}
       \CA_{\bv_+}= J_{\bv+} \big( \bI+\bV_0(\bk_+) \big),\quad 
       \CA_{\bv_-}= \bI+\bV_0(\bk_-)
\end{equation*}
due to $J_{\bv_-}=0.$ Assuming $\delta$ in \eqref{asmp:small_1} small enough, we have $J_{\bv+}>0.$ 
Thus it suffices to prove 
    \begin{equation}\label{bn2}
        \CA_{\bv_+}\bn=\CA_{\bv_-}\bn \,\,\, \text{on}\,\,\, \Gamma.
    \end{equation}

    Note that the tangential derivatives of $X_{\bv_\pm}$ are continuous across the boundary $\Gamma$ since $\bv_{+}=\bv_{-}$ on $\Gamma,$ namely, 
    \begin{equation*}
        \nabla_{y'} X_{\bv_+} = \nabla_{y'} X_{\bv_-} \,\,\,  \text{on}\,\,\, \Gamma
    \end{equation*}
for $y'=(y_1,\dots,y_{N-1}).$ Then we see 
    \begin{equation*}
        \begin{aligned}
           &\text{the i-th component of}\,\,\, \CA_{\bv_+}\bn\\
           =&\, (-1)^{N+i} \det ( \nabla_{y'} X_{\bv_+,1} \wedge  \nabla_{y'} X_{\bv_+,2} 
           \wedge \cdots\wedge\nabla_{y'} X_{\bv_+,i-1} \wedge \nabla_{y'} X_{\bv_+,i+1} 
           \wedge\cdots\wedge \nabla_{y'} X_{\bv_+,N} )\\
          =& \,(-1)^{N+i} \det ( \nabla_{y'} X_{\bv_-,1} \wedge  \nabla_{y'} X_{\bv_-,2} 
           \wedge \cdots\wedge\nabla_{y'} X_{\bv_-,i-1} \wedge \nabla_{y'} X_{\bv_-,i+1} 
           \wedge\cdots\wedge \nabla_{y'} X_{\bv_-,N} )\\
           =&\, \text{the i-th component of}\,\,\, \CA_{\bv_-}\bn.
        \end{aligned}
    \end{equation*}
    Here $(\ba_1' \wedge \cdots \wedge \ba_{N-1}')$ denotes $(N-1)\times (N-1)$ matrix spanned by the column vectors $\ba_{j}'\in \mathbb{R}^{N-1}$ for $j=1,\dots,N-1$. This proves the claim \eqref{bn2}. 
\end{proof}

\subsection{Linearization of \eqref{eq:LL_CNS_1}}
\label{section7.1}
In this subsection, we shall rewrite \eqref{eq:LL_CNS_1} into the form of \eqref{eql:1}. 
To this end, suppose that 
\begin{equation*}
    \rho_{+,0} = \gamma_{1+} + \theta_{+,0}, \quad 
    \gamma_{1-}=\rho_- \quad \text{and}\quad 
    \gamma_{2+}=P'(\gamma_{1+}).
\end{equation*}
Then, by Taylor's theorem, we arrive
\begin{equation*}
	P(\gamma_{1+}+\eta_+)-P(\gamma_{1+})=\gamma_{2+} \eta_++Q(\eta_+)
\end{equation*}
with 
$$Q(\eta_+)=\eta_+^2\int_{0}^{1}P''(\gamma_{1+}+\theta\eta_+)(1-\theta)d\theta.$$
For simplicity, let us introduce 
\begin{equation*}
    \begin{aligned}
    \fq_{-}&=\fp_{-}-P(\gamma_{1+}),\\
        \CD_{\bD_\pm}(\bv_\pm)&=\bD_{\bv_\pm}(\bv_\pm)-\bD(\bv_\pm)=\bV_0(\bk_\pm)\nabla{\bv_\pm}+(\bV_0(\bk_\pm)\nabla{\bv_\pm})^{\top},\\
          \CS_{\bD_+} (\bv_+) & = \mu_+\CD_{\bD_+} (\bv_+) +(\nu_+-\mu_+) \big(\bV_{0}(\bk_+):\nabla\bv_{+}\big) \bI.
    \end{aligned}
\end{equation*}
Then we see from \eqref{eq:LL_CNS_1} that
\begin{equation}\label{eq:NS3}
	\left\{ \begin{aligned}
		&\pd_t\eta_+ + \gamma_{1+}\, \dv \bv_+=f_+(\eta_+,\bv_{+})
		&&\quad&\text{in} &\quad \Omega_+ \times (0,T), \\
		&\gamma_{1+}\pd_t\bv_+-\DV\bT_+(\bv_+,\gamma_{2+}\eta_+)  = \bg_+(\eta_+,\bv_{+})
		&&\quad&\text{in}& \quad \Omega_+ \times (0,T), \\
		&\gamma_{1-}\pd_t\bv_-  - \Di\bT_-(\bv_{-},\fq_-) = \bg_-(\bv_{-},\fq_-)
		&&\quad&\text{in}& \quad \Omega_- \times (0,T), \\
  		& \di \bv_- = g_d (\bv_{-})=\dv \fg_d (\bv_{-})
		&&\quad&\text{in}& \quad \Omega_- \times (0,T), \\
		&\big(\bT_+(\bv_+,\gamma_{2+}\eta_+) - \bT_-(\bv_-,\fq_-)\big)\bn
		= \bh(\eta_+,\bv_{\pm},\fq_-)
		&&\quad&\text{on}& \quad \Gamma \times (0,T),\\
		&\bv_{+}-\bv_{-}
		= 0
		&&\quad&\text{on}& \quad \Gamma \times (0,T),  \\
		& \bv_-=0
		&&\quad&\text{on}& \quad   S \times (0,T), \\
		&(\eta_+, \bv_+)|_{t=0} = (\theta_{+,0}, \bu_{+,0})
		&&\quad&\text{in}& \quad \Omega_+, \\
		&\bv_-\big|_{t=0}=\bu_{-,0}
		&&\quad&\text{in}& \quad \Omega_-,
	\end{aligned}
	\right.
\end{equation}
where we have defined that 
\begin{equation}\label{eq:22}
	\begin{split}
		f_+(\eta_+,\bv_+)&=-\eta_{+}\di\bv_{+}-(\gamma_{1+}+\eta_+) \bV_0(\bk_+):\nabla\bv_{+},\\
		\bg_+(\eta_+,\bv_+)&=-\eta_+\pd_t\bv_{+}+\Di\big(\CS_{\bD_+} (\bv_+)-Q(\eta_+)\,\bI\big)
		 \\&\quad +\Big(\bV_{0}(\bk_+)\nabla \,\big|\, \bS_{\bv_+}(\bv_{+})-\gamma_{2+}\eta_+\bI-Q(\eta_+)\bI\Big),\\
		\bg_-(\bv_-,\fq_-)&=\Di\big(\mu_-\CD_{\bD_-}(\bv_-)\big)+\big(\bV_0(\bk_-)\nabla\,\big|\,\mu_-\bD_{\bv_-}(\bv_-)-\fq_-\bI\big),\\
		g_d (\bv_-)&=-\bV_0(\bk_-):\nabla\bv_-,\qquad  
  \fg_d (\bv_{-}) = -\bV_0(\bk_-)^{\top} \bv_-,
		\\\bh(\eta_+,\bv_\pm, \fq_-)&=\bT_+(\bv_+,\gamma_{2+}\eta_+)\bn-\bT_{\bv_+}(\bv_+,\gamma_{2+}\eta_++Q(\eta_+))\Big(\frac{\big(\bI + \bV_0(\bk_+)\big)\bn }{\big|\big(\bI + \bV_0(\bk_+)\big)\bn \big|}-\bI \Big)\\
  &\quad -\bT_{\bv_+}(\bv_+,\gamma_{2+}\eta_++Q(\eta_+))\bn-\bT_-(\bv_-,\fq_-)\bn\\
  &\quad 
        +\bT_{\bv_-}(\bv_-,\fq_-)\Big(\frac{\big(\bI + \bV_0(\bk_-)\big)\bn }{\big|\big(\bI + \bV_0(\bk_-)\big)\bn \big|}-\bI \Big)+\bT_{\bv_-}(\bv_-,\fq_-)\bn.
	\end{split}
\end{equation}


\section{Some technical results on the multipliers}
\label{proof}
Lemmas \ref{lem:-+}, \ref{lem:+-} and \ref{lem:+-2} can be proved by the following three lemmas respectively. For simplicity, we will provide the detailed proof of Lemma \ref{lem:-+2} and Lemmas \ref{lem:+-1} and \ref{lem:B3} follow analogously.
\begin{lem}
\label{lem:-+2}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants 
    $\mu_{+},$ $\nu_+,$ $\gamma_{1+},$ $\gamma_{2+}>0.$ Let the set $\Gamma_{\ep,\lambda_0}$ be defined by \eqref{def:Gamma} for some $\delta_0>0,$ and let the multiplier $m(\lambda,\xi')$ belong to $\bM_{0,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}).$ For $0<x_N<+\infty$, we define $K_{-,+}^{j,n}\,(j,n=1,2)$ by
	\begin{equation*}
		\begin{aligned}
			\big[K_{-,+}^{1,n}(\lambda)f\big](x',x_N)=&\int_{-b}^0\CF_{\xi'}^{-1}\Big[
			E_n^-(y_N)m(\lambda,\xi')Ae^{-B_+x_N}e^{Ay_N}\widehat{f}(\xi',y_N)\Big](x')dy_N,\\
			\big[K_{-,+}^{2,n}(\lambda)f\big](x',x_N)=&\int_{-b}^0\CF_{\xi'}^{-1}\Big[
			E_n^-(y_N)m(\lambda,\xi')A^2M_+(x_N)e^{Ay_N}\widehat{f}(\xi',y_N)\Big](x')dy_N.
		\end{aligned}
	\end{equation*}
	Then there exists a constant $r_b$ depending solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1+},$ $\gamma_{2+},$ $\mu_{+},$ 
	$\nu_+,$  $\lambda_0$, $\delta_0$ and $b$ such that
    \begin{equation}\label{Rbdd:K_-+}
        \mathcal{R}_{\mathcal{L}\big(L_q(\Omega_{-}),L_q(\Omega_{+})\big)}
	\Big(\Big\{(\tau\pd_{\tau})^\ell K_{-,+}^{j,n}(\lambda):
	\lambda\in \Gamma_{\varepsilon,\lambda_0} \Big\}\Big)\leq r_b
    \end{equation}
	for any $\ell=0,1$ and $j,n=1,2.$
\end{lem}

\begin{lem}
\label{lem:+-1}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants 
     $\nu_+,$ $\mu_-,$ $\gamma_{1\pm},$ $\gamma_{2+},$ $\lambda_0,$ $\delta_0$ and $b>0.$ 
     Let the set $\Gamma_{\ep,\lambda_0}$ be defined by \eqref{def:Gamma} and let the multiplier $m(\lambda,\xi')$ belong to $\bM_{0,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}).$ For $-b<x_N<0$, we define $K_{+,-}^{j,n}\,(j=1,2,3,4,\,n=1,2)$ by
	\begin{equation*}
		\begin{aligned}
			\big[K^{1,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')A^2e^{-Ay_N}M_-(x_N)\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{2,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')Ae^{-Ay_N}e^{B_-x_N}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{3,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')A^2e^{-Ay_N}M_-(-x_N-b)\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{4,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')Ae^{-Ay_N}e^{B_-(-x_N-b)}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N.
		\end{aligned}
	\end{equation*}
	Then there exists a constant $r_b$ depending solely on 
	$\varepsilon,$ $q,$ $N,$  $\nu_+,$ $\mu_-,$ $\gamma_{1\pm},$ $\gamma_{2+},$ $\lambda_0,$ $\delta_0$ and $b$ 
	  such that
     \begin{equation}\label{eq:R2}
         \mathcal{R}_{\mathcal{L}\big(L_q(\Omega_{+b}); L_q(\Omega_-)\big)}
	\Big(\Big\{(\tau\pd_{\tau})^\ell  K^{j,n}_{+,-}(\lambda):
	\lambda\in \Gamma_{\varepsilon,\lambda_0} \Big\}\Big)\leq r_b
     \end{equation}
	for $\ell=0,1$ and $j=1,2,3,4$, $n=1,2$.
\end{lem}
\begin{lem}\label{lem:B3}
	Assume that $0<\varepsilon<\pi/2$, $1<q<\infty$ and the constants $\mu_{-},$ $\gamma_{1-}>0.$ Let the set $\Gamma_{\ep,\lambda_0}$ be defined by \eqref{def:Gamma} for some $\delta_0>0,$ and let the multiplier $m(\lambda,\xi')$ belong to $\bM_{1,2}(\widetilde{\Gamma}_{\varepsilon,\lambda_0}).$ For $-b<x_N<0$, we define $K_{+,-}^{j,n}\,(j=5,6,\,n=1,2)$ by
	\begin{equation*}
		\begin{aligned}
			\big[K^{5,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')e^{-Ay_N}e^{Ax_N}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N,\\
			\big[K^{6,n}_{+,-}(\lambda)f\big](x',x_N)=&\int_{0}^b\mathcal{F}_{\xi'}^{-1}\Big[
			E_n^+(y_N)m(\lambda,\xi')e^{-Ay_N}e^{A(-x_N-b)}\mathcal{F}_{y'}[f](\xi',y_N)\Big](x')dy_N.
		\end{aligned}
	\end{equation*}
	Then there exists a constant $r_b$ depending solely on 
	$\varepsilon,$ $q,$ $N,$ $\gamma_{1-},$ $\mu_{-},$ 
  $\lambda_0$, $\delta_0$ and $b$ such that
	$$\mathcal{R}_{\mathcal{L}\big(L_q(\Omega_{+b}),L_q(\Omega_-)\big)}
	\Big(\Big\{(\tau\pd_{\tau})^\ell  K^{j,n}_{+,-}(\lambda):
	\lambda\in \Gamma_{\varepsilon,\lambda_0} \Big\}\Big)\leq r_b$$
	for $\ell=0,1$.
\end{lem}

\begin{proof}[Proof of Lemma \ref{lem:-+2}]
For any $\lambda\in\Gamma_{\ep, \lambda_0},$ 
$x=(x',x_N) \in \Omega_+,$ $y=(y',y_N) \in \Omega_-$ and $j,n=1,2,$ let us write 
\begin{equation*}
\big[K_{-,+}^{j,n}(\lambda)f\big](x',x_N)
=\int_{\Omega_-}E_n^{-}(y_N) k_{-,+}^{j}(\lambda,x',y';x_N,y_N)f(y)dy
\end{equation*}
with 
\begin{equation*}
\begin{aligned}
k_{-,+}^{1}(\lambda, x',y';x_N,y_N)&=\CF_{\xi'}^{-1}\big[m(\lambda,\xi')Ae^{-B_+x_N}e^{Ay_N}\big](x'-y'),\\
k_{-,+}^{2}(\lambda,x',y';x_N,y_N)&=\CF_{\xi'}^{-1}\big[m(\lambda,\xi')A^2M_+(x_N)e^{Ay_N}\big](x'-y').
\end{aligned}
\end{equation*}

{\bf Step 1.} 
We first prove that there exists some positive constant $C_1$ depending on $N,\varepsilon,\lambda_0,\mu_{+},\nu_+$ such that
\begin{equation}\label{eq:est:k1}
\big|(\tau\pd_{\tau})^{\ell}k_{-,+}^{j,n}(\lambda,x',y';x_N,y_N)\big|
\leq C_1 \big(|x'-y'|+x_N-y_N\big)^{-N}
\end{equation}
for any $\lambda\in\Gamma_{\ep, \lambda_0}$, $\ell=0,1,$ $j,n=1,2,$ and $0<x_N<\infty$.
\smallbreak 

In fact, by the assumption on $m(\lambda,\xi'),$ Leibniz's rule and Lemma \ref{lem:4.3},  there exist positive constants 
$C=C_{\alpha',\varepsilon,\lambda_0,\mu_{+},\gamma_{1+}}$ and $d=d_{\varepsilon,\mu_{+},\nu_+,\gamma_{1+}}$ such that 
\begin{equation}\label{eq:42}
\begin{aligned}
\big|\pd^{\alpha'}_{\xi'}(\tau\pd_{\tau})^{\ell} \big(m(\lambda,\xi')Ae^{-B_+x_N}e^{Ay_N}\big)\big|
&\leq  CA^{1-|\alpha'|}
e^{-d(|\lambda|+A)x_N}
e^{A y_N/2}\\
& \leq C A^{1-|\alpha'|} e^{-c A(x_N-y_N)},\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\big|\pd^{\alpha'}_{\xi'}(\tau\pd_{\tau})^{\ell} \big(m(\lambda,\xi')A^2M_+(x_N)e^{Ay_N}\big)\big|
&\leq  C A^{2-|\alpha'|}
x_N e^{-d A x_N}
e^{A y_N/2}\\
& \leq  C A^{1-|\alpha'|}
e^{-c A(x_N-y_N)}
\end{aligned}
\end{equation}
for $c=\min \{d,1\}/2$ and for any multi-index $\alpha'\in\BN_0^{N-1}.$
Then we apply \cite[Theorem 2.3]{shishi2001} 
\footnote{One may take the parameters $n=N-1$ and $\alpha=\sigma=1$ in \cite[Theorem 2.3]{shishi2001}.}
to obtain
\begin{equation}\label{eq:43}
	\big|(\tau\pd_{\tau})^{\ell}k_{-,+}^{j,n}(\lambda,x',y';x_N,y_N)\big|
    \lesssim |x'-y'|^{-N}.
\end{equation}



On the other hand, using \eqref{eq:42} with $\alpha'=0$ and the change of variables $\eta'=c(x_N-y_N)\xi'$ we have
\begin{equation*}
	\begin{aligned}
		\big|(\tau\pd_{\tau})^{\ell}k_{-,+}^{j,n}(\lambda,x',y';x_N,y_N)\big|
        &\lesssim \int_{\mathbb{R}^{N-1}}Ae^{-cA(x_N-y_N)}d\xi'\\
		&\lesssim  \big(c (x_N-y_N)\big)^{-N}\int_{\mathbb{R}^{N-1}}|\eta'|e^{-|\eta'|}d\eta'\\
		& \lesssim (x_N-y_N)^{-N},
	\end{aligned}
\end{equation*}
which combined with \eqref{eq:43} implies \eqref{eq:est:k1}. 
\medskip




{\bf Step 2.} 
In views of the property \eqref{eq:est:k1}, we introduce the operator
\begin{equation*}
	[K_0^nf](x',x_N)=\int_{\Omega_-} \big| E_n^{-}(y_N)\big| \,k_0(x'-y',x_N-y_N)\,|f(y)|\,dy.
\end{equation*}
with $k_0(x)=C_{1}|x|^{-N}.$ In what follows, we prove $K_0^n\in \CL\big(L_q(\Omega_{-});L_q(\Omega_{+})\big)$ for $n=1,2$. 
\smallbreak

By Young's inequality, we have
\begin{equation}\label{es:K_0}
	\begin{aligned}
		\|[K_0^nf](\cdot,x_N)\|_{L_q(\BR^{N-1})}
        &\leq \int_{-b}^0\big|E_n^{-}(y_N)\big|\,\|k_0(\cdot,x_N-y_N)\|_{L_1(\BR^{N-1})}
        \|f(\cdot,y_N)\|_{L_q(\BR^{N-1})}dy_N\\
		&\lesssim  \int_{-b}^0 \big|E_n^{-}(y_N)\big|\,\frac{\|f(\cdot,y_N)\|_{L_q(\BR^{N-1})}}{x_N-y_N}dy_N.
	\end{aligned}
\end{equation}

\begin{itemize}
    \item Case $n=1$. Using the change of variable $y_N=-x_Nt$, we get from \eqref{es:K_0} that
\begin{equation}\label{eq:45}
	\begin{aligned}
		\|[K_0^1f](\cdot,x_N)\|_{L_q(\BR^{N-1})}
		&\lesssim \int_{0}^{b/x_N}\varphi_{-0}(-x_Nt)\frac{\|f(\cdot,-x_Nt)\|_{L_q(\BR^{N-1})}}{1+t}dt,
	\end{aligned}
\end{equation}
which combined with Minkowski's inequality implies that 
\begin{equation*}
	\begin{aligned}
		\|K_0^1f\|_{L_q(\Omega_+)}
        &\lesssim\int_{0}^\infty\frac{1}{1+t}
        \Big[\int_{0}^{b/t}\big(\varphi_{-0}(-x_Nt)
        \|f(\cdot,-x_Nt)\|_{L_q(\BR^{N-1})}\big)^qdx_N\Big]^{1/q}dt\\
		&\lesssim\int_{0}^\infty\frac{1}{1+t} \Big[\int_{-b}^0
        \big(\varphi_{-0}(y_N)\|f(\cdot,y_N)\|_{L_q(\BR^{N-1})}\big)^q\frac{dy_N}{t}\Big]^{1/q}dt\\
		&\lesssim \|f\|_{L_q(\Omega_{-})}\int_{0}^\infty\frac{1}{(1+t)t^{1/q}}dt\\
        &\lesssim \|f\|_{L_q(\Omega_{-})}.
	\end{aligned}
\end{equation*}


\item Case $n=2.$ Analogous to the \eqref{eq:45}, we obtain from the change of variable $y_N=-x_Nt$ and \eqref{es:K_0} that
\begin{equation}\label{eq:46}
	\begin{aligned}
		\|[K_0^2f](\cdot,x_N)\|_{L_q(\BR^{N-1})}
        &\lesssim \int_{-2b/3}^{-b/3}\big| \varphi'_{-0}(y_N)\big| \frac{\|f(\cdot,y_N)\|_{L_q(\BR^{N-1})}}{x_N-y_N}dy_N\\
		&\lesssim \int_{b/(3x_N)}^{2b/(3x_N)}
        \big| \varphi'_{-0}(-x_Nt)\big|\frac{\|f(\cdot,-x_Nt)\|_{L_q(\BR^{N-1})}}{1+t}dt,
	\end{aligned}
\end{equation}
which yields 
\begin{equation*}
	\begin{aligned}
		\|K_0^2f\|_{L_q(\Omega_+)}
        &\lesssim \int_{0}^\infty\frac{1}{1+t}\Big[\int_{b/(3t)}^{2b/(3t)}
        \big( \big| \varphi'_{-0}(-x_Nt) \big| \,\|f(\cdot,-x_Nt)\|_{L_q(\BR^{N-1})}\big)^q \,dx_N\Big]^{1/q}dt\\
		&\lesssim \int_{0}^\infty\frac{1}{1+t}\Big[\int_{-2b/3}^{-b/3} \big(\big| \varphi'_{-0}(y_N)\big|\, 
        \|f(\cdot,y_N)\|_{L_q(\BR^{N-1})}\big)^q\frac{dy_N}{t}\Big]^{1/q}dt\\
		&\lesssim \|\varphi'_{-0}\|_{L_\infty(\BR)}\|f\|_{L_q(\Omega_{-})}\int_{0}^\infty\frac{1}{(1+t)t^{1/q}}dt\\
         &\lesssim \|f\|_{L_q(\Omega_{-})}.
	\end{aligned}
\end{equation*}
\end{itemize}
\medskip




{\bf Step 3.} Now, we prove \eqref{Rbdd:K_-+} by verifying Definition \ref{def:R}. 
Assume that  $M\in\BN, \lambda_k\in\Gamma_{\ep,\lambda_0}, f_k\in L_q(\Omega_{-}),$ $r_j(u)$ be the Rademacher functions  and $k=1,\dots,M.$
By Khintchine inequality (see \cite[(3.4)]{Denk2003} for instance), we obtain
\begin{equation*}
	\begin{aligned}
	&\Big(\int_0^1 \Big\|\sum_{k=1}^M r_k(u)(\tau\pd_{\tau})^{\ell} K_{-,+}^{j,n}(\lambda_k)f_k\Big\|_{L_q(\Omega_{+})} \Big)^{1/q}\\
    \lesssim  & \Big\|\Big(\sum_{k=1}^M |(\tau\pd_{\tau})^{\ell} 
    K_{-,+}^{j,n}(\lambda_k)f_k|^2\Big)^{1/2} \Big\|_{L_q(\Omega_{+})}\\
    \lesssim & \Big\|\big(\sum_{k=1}^M (K_0^{n} f_k )^2\big)^{1/2} \Big\|_{L_q(\Omega_{+})}\\
    \lesssim & \Big\| K_0^n \Big(\sum_{k=1}^M |f_k|^2\Big)^{1/2}\Big\|_{L_q(\Omega_{+})}\\
\lesssim  &\|K_0^n\|_{\CL\big(L_q(\Omega_{-}); L_q(\Omega_{+})\big)}
\Big\|\Big(\sum_{k=1}^M |f_k|^2\Big)^{1/2}\Big\|_{L_q(\Omega_{-})}\\
\lesssim & \|K_0^n\|_{\CL\big(L_q(\Omega_{-}),L_q(\Omega_{+})\big)}
\Big(\int_0^1 \Big\|\sum_{k=1}^M r_k(u)f_k\Big\|_{L_q(\Omega_{-})}^q \,du \Big)^{1/q}.
	\end{aligned}
\end{equation*}
This gives the bound \eqref{Rbdd:K_-+}. 
\end{proof}



