\section{Methodology}\label{Sec_Method}

\noindent Suppose $\mathcal{D} = \{(y_i, \mathbf{x}_i) \mid i = 1, 2, \cdots, n\}$ is the observed dataset, where $y_i$ follows a Generalised Pareto Distribution (GPD), i.e.,
\[
y_i \sim \text{GPD}(\mu, \sigma_i, \xi), \quad i = 1, 2, \cdots, n,
\]
with probability density function:
\[
f(y_i \mid \sigma_i, \xi) = \frac{1}{\sigma_i} \left(1 + \xi \frac{y_i - \mu}{\sigma_i} \right)^{-1/\xi - 1},
\]
and $\mathbf{x}_i = \{x_{i1}, x_{i2}, \cdots, x_{ip}\}$ are the covariates associated with the $i^{\text{th}}$ observation. The threshold $\mu$ is assumed known; the shape parameter $\xi$ is same across observations, and the scale parameter $\sigma_i$ is modelled as a log-linear function of covariates:
\[
\log(\sigma_i) = \mathbf{x}_i^\top \boldsymbol{\beta}.
\]
The support of $Y_i$ is $(\mu, \infty)$ if $\xi < 0$, and $(\mu, \mu + \sigma_i / \xi)$ if $\xi > 0$. The special case $\xi = 0$ corresponds to the exponential distribution with mean $\sigma_i$, interpreted as the limit as $\xi \to 0$.
The survival function of the GPD regression model is:
\begin{eqnarray*}
\mathbb{P}(Y > y_0 \mid Y > \mu) &=& \left( 1 - \frac{\xi(y_0 - \mu)}{\exp(\mathbf{x}_i^\top \boldsymbol{\beta})} \right)^{1/\xi} \\
&=& \left(1 + \frac{\xi(y_i - \mu)}{\exp(\mathbf{x}_i^\top \boldsymbol{\beta})} \right)^{-1/\xi}.
\end{eqnarray*}
In financial applications, if $Y$ represents the daily negative return (in percentage), and a market crash is defined as a daily drop exceeding $y_0 = 5\%$, then this survival function quantifies the conditional probability of a crash, given that a drop of, say, $\mu = 2\%$ has already occurred.
The conditional expectation of $Y_i$ given the covariates is:
\[
\mathbb{E}(Y_i\mid Y_i \geq \mu) = 
\begin{cases}
\infty, & \xi \geq 1, \\
\mu + \dfrac{\exp(\mathbf{x}_i^\top \boldsymbol{\beta})}{1 - \xi}, & \xi < 1.
\end{cases}
\]
The variance exists only when $\xi < 0.5$ and is given by:
\[
\mathbb{V}ar(Y_i\mid Y_i \geq \mu) = \dfrac{\exp(2\mathbf{x}_i^\top \boldsymbol{\beta})}{(1 - \xi)^2(1 - 2\xi)}.
\]
This characterisation highlights the influence of covariates on the first two moments of the tail distribution and emphasises the model's ability to capture heavy-tailed behaviour.

\subsection{Log-Likelihood Function}

\noindent The log-likelihood function of the GPD regression model is:
\[
\log L(\xi, \boldsymbol{\beta}) = -\sum_{i=1}^n \mathbf{x}_i^\top \boldsymbol{\beta} + \left(\frac{1}{\xi} - 1\right) \sum_{i=1}^n \log \left[1 + \xi \frac{y_i - \mu}{\exp(\mathbf{x}_i^\top \boldsymbol{\beta})} \right].
\]
This formulation treats the exceedances $y_i > \mu$ as GPD-distributed with covariate-dependent scale. The shape parameter $\xi$ governs the heaviness of the tail, while the covariates modulate the scale of exceedance. In particular, the conditional mean:
\[
\mathbb{E}(Y_i \mid Y_i \geq \mu) = \mu + \frac{\exp(\mathbf{x}_i^\top \boldsymbol{\beta})}{1 - \xi}
\]
exists only for $\xi < 1$, and the variance exists only if $\xi < 0.5$. This structure provides a coherent framework for modelling the magnitude of extreme outcomes while adjusting for covariate information. As shown in \citet{smith1985mle}, the maximum likelihood estimator (MLE) exists asymptotically when $\xi < 1$ and is consistent, asymptotically normal, and efficient provided $\xi < 0.5$.

\subsection{Truncated Cauchy Prior on $\xi$}

\noindent The \texttt{truncated Cauchy(0,1)} prior truncated from above at 1, i.e., the support is $\xi < 1$. The \emph{probability density function} of the standard Cauchy distribution is:
$$
p(\xi) = \frac{1}{\pi(1 + \xi^2)}, \quad \xi \in (-\infty, \infty).
$$
We define the \emph{truncated density}:
$$
p_{\text{trunc}}(\xi) = \frac{1}{Z} \cdot \frac{1}{\pi(1 + \xi^2)}, \quad \text{for } \xi < 1
$$
where $Z$ is the normalising constant, i.e. the total probability over the truncated domain:
\begin{eqnarray}
Z &=& \int_{-\infty}^{1} \frac{1}{\pi(1 + \xi^2)} \, d\xi = \frac{1}{\pi} \cdot \left[ \tan^{-1}(\xi) \right]_{-\infty}^{1}
= \frac{1}{\pi} \cdot \left( \tan^{-1}(1) - \tan^{-1}(-\infty) \right) \nonumber \\
&=&\frac{1}{\pi} \left( \frac{\pi}{4} - (-\frac{\pi}{2}) \right) = \frac{1}{\pi} \cdot \frac{3\pi}{4} = \frac{3}{4}
\end{eqnarray}
Now plug in $Z = \frac{3}{4}$:
$$
p_{\text{trunc}}(x) = \frac{4}{3\pi(1 + \xi^2)}, \quad \xi < 1.
$$
The pdf of \texttt{truncated Cauchy(0,1)} prior density, with upper truncation at $\xi = 1$.
$$
p(\xi) = \frac{4}{3\pi(1 + \xi^2)}, \quad \text{for } \xi < 1
$$
