\section{Introduction}
%two parts： Background； Contributions
% References test~\cite{chen2020spatial,EM-DAT2025,Flood_hazard_review_traditional_2021,FloodIncreaseTellman2021,han2023survey,Karim2023HydrodynamicML_review,Notarangelo2025STURM,Poterek2025INFLOS,Seleem2023CNN_RF_Compare}
