\section{The framework}
\label{sec:introduce_BQRRP}

As stated in \cref{subsec:contribution}, the intended format for a \code{BQRRP} algorithm is to be in line with that of standard LAPACK QRCP, \code{GEQP3}.
\cref{alg:BQRRP} gives pseudocode toward this end.
% For simplicity of presentation, the pseudocode is not concerned with performing computations in-place.
For simplicity of presentation, it uses a \textit{simplified} representation of orthogonal factors from
QR factorizations, stating that such factors represent a \textit{square} matrix using some number of elementary reflectors (implicit economical storage format).
The pseudocode is valid in a setting where variables are passed by value rather than by reference, and where functions can return nontrivial datastructures.
Details on how a \code{BQRRP} algorithm can be properly implemented in-place and when working with raw pointers are deferred to \cref{sec:bqrrp_practical}.
% Finally, the pseudocode pre-allocates storage for $\mtx{Q}$ and $\mtx{R}$ at step \ref{bqrrp:alloc}, which is only done to enhance the clarity of the algorithm's details and would naturally be avoided in an implementation of \code{BQRRP}.


The pseudocode in \cref{alg:BQRRP} has two required inputs: the matrix $\mtx{M}$ and an integer block size $b$. 
It relies on five essential
helper functions inside its main loop.
These helper functions are applied to various submatrices whose bounds are computed at 
step \ref{bqrrp:block_partitions}.

\begin{itemize}

\item \code{qrcp\_wide} in step \ref{bqrrp:qrcp} represents
a column-pivoted QR factorization method, suitable for wide matrices.

\item \code{tri\_rank} in
step \ref{bqrrp:rank_est} computes some notion of numerical rank of an input triangular matrix.

\item \code{col\_perm} in
steps \ref{bqrrp:permute_r}, \ref{bqrrp:permute_m}, \ref{bqrrp:update_j}
is responsible for permuting the columns of a given matrix in accordance with the indices stored in a given vector.

\item \code{qr\_tall} in step \ref{bqrrp:qr_tall} performs a tall unpivoted QR factorization.

\item \code{apply\_trans\_q} in steps \ref{bqrrp:apply_q_1} and \ref{bqrrp:apply_q_2} applies the transpose $\mtx{Q}$-factor output by \code{qr\_tall} to a given matrix.
\end{itemize}

\noindent \crefrange{subsec:qrcp_wide}{subsec:col_perm} describe possibilities of how each of these functions might be implemented. 
We recommend specific implementations targeting the CPU architectures from \cref{table:cpu_config}.
% In practice, selecting suitable candidates for these functions is a crucial step in defining an effective \code{BQRRP} algorithm.
% The details on how each of these five functions is implemented in practice are presented in \crefrange{subsec:qrcp_wide}{subsec:col_perm}.

\begin{algorithm}[htb!]
\small \caption{Blocked QR with Randomization and Pivoting}
\label{alg:BQRRP}
\begin{algorithmic}[1]

\vspace{0.15em}
\Statex \textbf{Required input:} An $m$-by-$n$ matrix $\mtx{M}$; and an integer block size parameter $b$.

\vspace{0.45em}

\Statex \textbf{Optional input:} A scalar $\gamma$ that sets the size of the sketch relative to $b$ ($\gamma \geq 1$).

\vspace{0.45em}

\Statex \textbf{Output:} Numerical rank $\ell$, orthonormal $m \times m$ matrix $\mtx{Q}$ based on $\ell$ elementary reflectors, upper-trapezoidal $\ell \times n$ matrix $\mtx{R}$, and a column permutation vector $\vct{J}$ of length $n$.

\vspace{0.35em}

\setstretch{1.25}
\Function{bqrrp}{$\mtx{M}, b, \gamma$} \label{bqrrp:input}
\label{bqrrp:input}
    \State Set $d = \lceil \gamma \cdot b \rceil$ and sample a
    $d$-by-$n$ sketching operator $\mtx{S}$ from a Gaussian distribution\label{bqrrp:sample}
%\vspace{-4pt}
    \State Allocate empty $\mtx{Q}$, $\mtx{R}$; $\vct{J} = 1:(n+1)$ \label{bqrrp:alloc}
    \State Sketch $\sk{\mtx{M}} = \mtx{S}\mtx{M}$\label{bqrrp:sketching}
    \For{$i = 0:\lceil n/b \rceil$} \label{bqrrp:loop}
        \State $\sblock = i \cdot b$ is the start of the current row/col block;
        \Statex\hspace{2.6em} $\ecolblock = \min\{n, (i+1)b\}$ is the (exclusive) end
            %\Statex ~~~~~~~~\,
            column of the column block;
        \Statex \hspace{2.6em} $\erowblock = \min\{m, (i+1)b\}$ is the (exclusive) end row of the row block; \label{bqrrp:block_partitions}
        %\Statex \hspace{2.6em} $b = \min\{b, (n-\sblock), (m-\sblock)\}$\label{bqrrp:block_partitions}

        \State Decompose $[\sim, \sk{\mtx{R}}, \sk{\vct{J}}] = \code{qrcp\_wide}(\sk{\mtx{M}}(:, \tslice{s}))$\label{bqrrp:qrcp}
        \Statex ~~~~~~~\, \codecomment{$\sk{\vct{J}}$ is a permutation vector of length $n-s$}
        \State Determine $k = \code{tri\_rank}(\sk{\mtx{R}})$ \label{bqrrp:rank_est}
         \Statex \hspace{2.5em} \codecomment{ $k \leq \min\{b, n-\sblock, m-\sblock\}$}
        %\Statex ~~~~~~~\, \codecomment{{} Performed by finding the last nonzero element in the diagonal of $\sk{\mtx{R}}$}
        \State Permute $\mtx{R}(\lslice{\sblock}, \tslice{\sblock}) = \code{col\_perm}(\mtx{R}(\lslice{\sblock}, \tslice{\sblock}), \sk{\vct{J}})$ \label{bqrrp:permute_r}
        \Statex ~~~~~~~\, \codecomment{ The rectangular portion of the \textbf{computed} rows is permuted
        (no-op at $i = 0$)}
        \State Permute $\mtx{M}(\tslice{\sblock}, \tslice{\sblock}) = \code{col\_perm}(\mtx{M}(\tslice{\sblock}, \tslice{\sblock}), \sk{\vct{J}})$ \label{bqrrp:permute_m}
        \State Update $\vct{J} = \code{col\_perm}(\vct{J}(\tslice{\sblock}), \sk{\vct{J}})$  \label{bqrrp:update_j}
        \State Decompose $[\mtx{Q}^{\mathrm{curr}}, \mtx{R}_{11}] = \texttt{qr\_tall}(\mtx{M}(\tslice{\sblock}, \tslice{\sblock}\ecolblock), k)$\label{bqrrp:qr_tall}
        \Statex ~~~~~~~\, \codecomment{ $\mtx{Q}^{\mathrm{curr}}$ uses $k$ reflectors, implicitly represents $m - \sblock$ columns and $\mtx{R}_{11}$ is $k$-by-$b$}

        \State Update $\mtx{R}(\tslice{\sblock}(\sblock + k), \tslice{\sblock}\ecolblock) = \mtx{R}_{11}$ \label{bqrrp:update_R11}
        \If{$k \neq \min\{b, (n-\sblock), (m-\sblock)\}$} \label{bqrrp:iter_check}
            \State Perform $[\sim, \mtx{R}_{12}] = \code{apply\_trans\_q}(\mtx{Q}^{\mathrm{curr}}, \mtx{M}(\tslice{\sblock}k, \tslice{\ecolblock}))$ \label{bqrrp:apply_q_1}
            \Statex ~~~~~~~~~~~~\, \codecomment{ Output  $\mtx{R}_{12}$ is $k \times (n - \ecolblock)$}
        \Else
            \State Perform $[\mtx{M}^{\mathrm{to\_update}}, \mtx{R}_{12}] = \code{apply\_trans\_q}(\mtx{Q}^{\mathrm{curr}}, \mtx{M}(\tslice{\sblock}, \tslice{\ecolblock}))$ \label{bqrrp:apply_q_2}
            \Statex ~~~~~~~~~~~~\, \codecomment{Output $\mtx{M}^{\mathrm{to\_update}}$ is $(m - \erowblock)$-by-$(n - \ecolblock)$, $\mtx{R}_{12}$ is $b$-by-$(n - \ecolblock)$}
            \State Update $\mtx{M}(\tslice{\erowblock}, \tslice{\ecolblock}) = \mtx{M}^{\mathrm{to\_update}}$ \label{bqrrp:update_M}
        \EndIf
        \State Update $\mtx{R}(\tslice{\sblock}(\sblock+k), \tslice{\ecolblock}) = \mtx{R}_{12}$ \label{bqrrp:update_r12}
        \State Update $\mtx{Q}(\tslice{\sblock}\erowblock, \tslice{\sblock}(\sblock+k)) = \mtx{Q}^{\mathrm{curr}}$ \label{bqrrp:update_q}
        \If{$i = n/b$ or $k \neq \min\{b, (n-\sblock), (m-\sblock)\}$}
        \label{bqrrp:termination}
            \State $\ell = \sblock + k$ \label{bqrrp:update_rank}
            \State \textbf{break}
        \EndIf
        \State Update $\sk{\mtx{M}}(\fslice{}, \tslice{\ecolblock}) = \begin{bmatrix} \sk{\mtx{R}}_{12} - \sk{\mtx{R}}_{11}(\mtx{R}_{11})^{-1}\mtx{R}_{12} \\ \ \sk{\mtx{R}}_{22} \end{bmatrix}$ \label{bqrrp:update_sample}
    \EndFor
    \State \textbf{return} $\ell$, $\mtx{Q}$, $\mtx{R}$, $\vct{J}$ \label{bqrrp:output}
    \EndFunction
\end{algorithmic}
\end{algorithm}

%\FloatBarrier

While \code{BQRRP} is a randomized algorithm, it uses randomness only once.
Before entering the main loop, it generates a matrix whose entries are independent mean-zero variance-one Gaussian random variables.\footnote{The unit-variance requirement is not essential, so long as all entries are sampled from the same mean-zero Gaussian distribution.}
This matrix is applied $\mtx{M}$ to obtain a smaller matrix called the \textit{sketch}.
The number of rows in the sketch is $d = \lceil \gamma b \rceil$, where $\gamma$ is called the \textit{sampling factor}.
The natural default value of $\gamma$ depends on the implementation of \code{qcrp\_wide} (in our recommended implementation, the only reasonable value is $\gamma = 1$).
As \code{BQRRP} iterates, the sketch is updated deterministically with a method proposed by Duersch and Gu~\cite[Section 4]{DG:2017:QR}.

\begin{remark}
    In our prior work for QRCP of tall matrices, \cite{MBM2024}, we used a fast sparse operator to prevent sketching from becoming a computational bottleneck.
    In the context of \code{BQRRP}, Gaussian sketching has no risk of being a bottleneck operation.
    This is because \code{BQRRP} sketches in the \textit{sampling regime} rather than the \textit{embedding regime}, to borrow terms from  \cite[Section 2.2]{RandLAPACK_Book}.
\end{remark}

% \cref{alg:BQRRP} only uses randomness to construct a \textit{sketching operator} $\mtx{S}$, sampled from a \textit{skecthing distribution} at step \ref{bqrrp:sketching}; the sketching operator is constructed only once, at the beginning of the algorithm. 
% The image of a given matrix under a sketching operator is called a \textit{sketch}.
% Since step \ref{bqrrp:sketching} performs sketching in a \textit{sampling} regime (meaning that the operator $\mtx{S}$ has fewer rows than columns in $\mtx{M}$), sampling the operator from a \textit{Gaussian} distribution is safe for the algorithm's performance.
% This is in contrast to Algorithm 2 in our prior work~\cite{MBM2024},
% where a fast sparse operator was required to prevent sketching from becoming a computational bottleneck.
% The deterministic \textit{sample update} (step \ref{bqrrp:update_sample}) formula in \cref{alg:BQRRP} is based on work by Duersch and Gu~\cite[Section 4]{DG:2017:QR}, and it is responsible for updating the sketch at every iteration of the main loop.
%As \cite[Algorithm 6]{DG:2017:QR} describes, one can avoid performing the trailing matrix $\mtx{M}$ update when the original input data is low-rank. 

