\begin{algorithm}[htb]
\small \setstretch{1.2}
\caption{ : Kahan matrix generator}
\label{alg:kahan_generator}
\begin{algorithmic}[1]
\Statex \textbf{Input:} Numbers of rows and columns, $m$ and $n$, perturbation real number parameter $p$, parameter $\theta$ such that $0 < \theta < \pi$
