    \State $\mtx{P} = p \epsilon_{\mathrm{mach}} \code{diag}(k, (k-1), \dots, 1)$
    \State $\mtx{S} = \code{diag}(1, s, s^2, \dots, s^{(k - 1)})$
    \State $\mtx{C} = \code{triu}(\code{ones}(k, k))$
    \State $\mtx{C}(\code{triu}(\code{true}(\code{size}(\mtx{C})), 1)) = -c$
    \Statex ~~~~~~~\, \codecomment{{} $\mtx{C}$ is upper-triangular with $1$'s on its main diagonal and $-c$ above it}
    \State $\mtx{M} = \mtx{S}\mtx{C}+\mtx{P}$
    \If{$m > n$}
        \State $\mtx{M} = [\mtx{M};~\code{zeros}(m - n, n)]$
    \ElsIf{$n > m$}
        \State $\mtx{M} = [\mtx{M},~\mtx{M}(:, m) \cdot \code{ones}(1, n - m)]$
    \EndIf
    \Statex ~~~~~~~\, \codecomment{{} Append zero rows or replicate the last column if $\mtx{M}$ is rectangular}
    \State \textbf{return} $\mtx{M}$
\EndIndent    
\end{algorithmic}
