\end{definition}



Motivated by work of Barr, Borceaux-Rosick\'y~\cite{MR2280436} defined what it means for a locally finitely presentable category to satisfy ``effective unions of $\mathcal{M}$-subobjects" for a class $\mathcal{M}$ of monomorphisms.  This was a sufficient, but not necessary, condition for $\mathcal{M}$ to be cellularly generated.  It is not necessary because, for example, the class of pure monomorphisms is cofibrantly generated in the category \textbf{Ab} of abelian groups, but does not have effective unions of subobjects in \textbf{Ab} (\cite{MR4121092}).  We realized that if one weakens their condition to merely hold ``almost everywhere", then this exactly characterizes cellular generation.  


\begin{definition}\label{def_EffectiveSubobj}
Suppose $S$ be a monoid, $\mathcal{K}$ is either Act-$S$, $\overline{\text{Act}}$-$S$, or Act$_0$-$S$, and $\mathcal{M}$ a class of monomorphisms in $\mathcal{K}$ that is cellularly closed (i.e., closed under pushouts and transfinite compositions).  For a regular cardinal $\kappa > |S|$, we say that \textbf{$\boldsymbol{\mathcal{M}}$ is $\boldsymbol{\kappa}$-almost-everywhere (a.e.) effective} if the following holds for some natural number $n$:\footnote{This definition is really a definition \emph{scheme} indexed by natural numbers.}
\begin{align*}
\left( \exists p  \  \forall \mathfrak{N} \right) & \Big( \textbf{if } S \cup \{S,p \} \subset \mathfrak{N}\prec_{\Sigma_n} (V,\in) \text{ and } \mathfrak{N} \cap \kappa \text{ is transitive,} \\
& \textbf{then } (\forall f \in \mathfrak{N} \cap \mathcal{M})( f \restriction \mathfrak{N} \text{ and } r^{f,\mathfrak{N}} \text{ are both in } \mathcal{M} )\Big),
\end{align*}
where $r^{f,\mathfrak{N}}$ denotes the map from Definition \ref{def_MainDiag}.  We say \textbf{$\boldsymbol{\mathcal{M}}$ is a.e.-effective} if it is $\kappa$-a.e.\ effective for some regular $\kappa$ (equivalently, a tail end of regular $\kappa$, see below).   
\end{definition}
\noindent The ``almost everywhere" terminology is chosen because one may rephrase the displayed statement using a slightly nonstandard interpretation of Shelah's ``almost all" quantifier:
\[
\left( \text{aa}^*_\kappa \mathfrak{N} \right) \left( \forall f \in \mathfrak{N} \cap \mathcal{M} \right)\left(  f \restriction \mathfrak{N} \in \mathcal{M} \text{ and } r^{f,\mathfrak{N}} \in \mathcal{M}\right).
\]
Intuitively, the ``almost" in ``almost all" is because of the presence of the constraint that $\mathfrak{N}$ has to include the parameter $p$ and the parameters in $S \cup \{ S \}$, and be sufficiently elementary in $(V,\in)$.  The $p$ will very often be empty or trivial.  One could also make sense of ``restriction to $\mathfrak{N}$" for many other categories (e.g., any finitely accessible category), but we stick with monoid acts for simplicity.  

If $\kappa_0 < \kappa_1$ are regular cardinals and $\mathfrak{N}\cap \kappa_1$ is transitive, then $\mathfrak{N} \cap \kappa_0$ is transitive.  It follows easily that if $\mathcal{M}$ is $\kappa_0$-a.e.\ effective then it is $\kappa_1$-a.e.\ effective.  This justifies the parenthetical comment in the definition.



Before proving our key Theorem \ref{thm_NewChar} we need the next lemma.

\begin{lemma}\label{lem_restrictColimit}
Suppose $S$ is a monoid and $\mathcal{K}$ is one of $\overline{\text{Act}}$-$S$, Act-$S$, or Act$_0$-$S$.  Suppose 
% https://q.uiver.app/#q=WzAsNCxbMCwwLCJBIl0sWzIsMCwiQyJdLFswLDIsIkIiXSxbMiwyLCJQIl0sWzAsMSwiZiJdLFswLDIsImciLDJdLFsyLDMsImYnIiwyXSxbMSwzLCJnJyJdLFszLDAsIiIsMSx7InN0eWxlIjp7Im5hbWUiOiJjb3JuZXItaW52ZXJzZSJ9fV1d
\[\begin{tikzcd}
	A && C \\
	\\
	B && P
	\arrow["f", from=1-1, to=1-3]
	\arrow["g"', from=1-1, to=3-1]
	\arrow["{g'}", from=1-3, to=3-3]
	\arrow["{f'}"', from=3-1, to=3-3]
	\arrow["\ulcorner"{anchor=center, pos=0.125, rotate=180}, draw=none, from=3-3, to=1-1]
\end{tikzcd}\]
is a pushout square in $\mathcal{K}$.  If $S \cup \{ S,f,g,f',g' \} \subset \mathfrak{N} \prec_* (V,\in)$, then the square's restriction to $\mathfrak{N}$
% https://q.uiver.app/#
\[\begin{tikzcd}
	{\mathfrak{N} \cap A} && {\mathfrak{N} \cap C} \\
	\\
	{\mathfrak{N} \cap B} && {\mathfrak{N} \cap P}
	\arrow["{f \restriction \mathfrak{N}}", from=1-1, to=1-3]
	\arrow["{g \restriction \mathfrak{N}}"', from=1-1, to=3-1]
	\arrow["{g' \restriction \mathfrak{N}}", from=1-3, to=3-3]
	\arrow["{f' \restriction \mathfrak{N}}"', from=3-1, to=3-3]
\end{tikzcd}\]
is also a pushout square.\footnote{This is an instance of a more general fact:  if $\mathcal{D}$ is a diagram in a locally finitely presentable category $\mathcal{K}$, $\mathcal{D} \in \mathfrak{N} \prec_* (V,\in)$, and (a representative set of) the finitely presentable objects of $\mathcal{K}$ is contained in $\mathfrak{N}$, then it is possible to make sense of ``restriction to $\mathfrak{N}$", and one can show $\text{colim} \left( \mathcal{D} \restriction \mathfrak{N} \right) = \left( \text{colim} \mathcal{D} \right) \restriction \mathfrak{N}$.}
\end{lemma}

\begin{proof}
The pushout $P$ can be explicitly described as 
\[
P = \frac{B \sqcup C}{\overline{R_{f,g}}}
\]  
where $\overline{R_{f,g}}$ is the equivalence relation generated by the binary relation
\[
R_{f,g}:=\{ (g(a),f(a))  \ : \ a \in A \}
\]
on $B \sqcup C$.  And $f'$ and $g'$ are the respective compositions of $f$ and $g$ with the factor map $B \sqcup C \to P$.  

By Lemma \ref{lem_HomThm}
\[
\mathfrak{N} \cap P = \mathfrak{N} \cap \frac{B \sqcup C}{\overline{R_{f,g}}} \simeq \frac{\mathfrak{N} \cap (B \sqcup C)}{\mathfrak{N} \cap \overline{R_{f,g}}} 
\]
Now $\mathfrak{N} \cap (B \sqcup C) = (\mathfrak{N} \cap B) \sqcup (\mathfrak{N} \cap C)$, and elementarity of $\mathfrak{N}$ (and the fact that $f,g \in \mathfrak{N}$) imply that $\overline{R_{f,g}}$ is the same as the equivalence relation generated by the relation
\[
R_{f \restriction \mathfrak{N}, g \restriction \mathfrak{N}} = \{ (g(a),f(a)) \ : \ a \in \mathfrak{N} \cap A  \}.
\]
Then
\[
\frac{\mathfrak{N} \cap (B \sqcup C)}{\mathfrak{N} \cap \overline{R_{f,g}}}  = \frac{(\mathfrak{N} \cap B) \sqcup (\mathfrak{N} \cap C)}{\overline{R_{f \restriction{N}, g \restriction \mathfrak{N}}}}
\]
which is the pushout of the span created by $f \restriction \mathfrak{N}$ and $g \restriction \mathfrak{N}$.
\end{proof}




\begin{theorem}\label{thm_NewChar}
Suppose $S$ is a monoid and $\mathcal{K}$ is one of $\overline{\text{Act}}$-$S$, Act-$S$, or Act$_0$-$S$.  Suppose $\mathcal{M}$ a cellularly-closed class of monomorphisms in $\mathcal{K}$.  The following are equivalent:

\begin{enumerate}[label=(\Roman*)]
 \item\label{item_AE} $\mathcal{M}$ is almost-everywhere effective.
 \item\label{item_CellGen} $\mathcal{M}$ is cellularly generated.
\end{enumerate}

\end{theorem}  




\begin{remark}
Theorem \ref{thm_NewChar} holds in more general settings (e.g., locally finitely presentable categories) but the proof is simpler for monoid acts, which is all we need for our main applications here.  \end{remark}




\begin{proof}
We prove the theorem for the category $\overline{\text{Act}}$-$S$; the proofs for Act-$S$ and Act$_0$-$S$ are basically identical, since pushouts in those categories agree with pushouts from the ambient category $\overline{\text{Act}}$-$S$.

\ref{item_AE} $\implies$ \ref{item_CellGen}:  Let $\kappa > |S|$ witness that $\mathcal{M}$ is a.e.\ effective.  We prove by induction on cardinals $\lambda$, that if $f \in \mathcal{M}$ and $|\text{cod}(f)| \le \lambda$, then $f \in \text{cell} \big(\mathcal{M}^{<\kappa}\big)$, where $\mathcal{M}^{<\kappa}$ denotes a representative set of members of $\mathcal{M}$ whose codomains have cardinality $<\kappa$.

This trivially holds for $\lambda <\kappa$.  Assume that $\lambda \ge \kappa$ is a cardinal, and that the claim holds for all members of $\mathcal{M}$ with codomains of size $<\lambda$.  Consider an arbitrary $f: A \to B$ in $\mathcal{M}$ with $|B|=\lambda$; since $\mathcal{M} \subset \text{Mono}$ we can without loss of generality assume $f$ as an inclusion.  By a basic application of Fact \ref{fact_LS_class} (see, e.g., Fact 2.2 of \cite{Cox_MaxDecon}), there is a sequence $\langle \mathfrak{N}_\alpha \ : \ \alpha \le \text{cf}(\lambda) \rangle$\footnote{$\text{cf}(\lambda)$ denotes the cofinality of $\lambda$, i.e., the least cardinal $\mu$ such that there is an increasing and cofinal function $\mu \to \lambda$.} of sufficiently elementary submodels of $(V,\in)$\footnote{I.e., a fixed sufficiently large $n$ such that $\mathfrak{N}_\alpha \prec_n (V,\in)$ for each $\alpha$.} such that 
\begin{enumerate}
 \item $\mathfrak{N}_\alpha$ is both an element and subset of $\mathfrak{N}_{\alpha+1}$ for each $\alpha < \text{cf}(\lambda)$;
 \item each $\mathfrak{N}_\alpha$ has transitive intersection with $\kappa$; 
 \item if $\alpha < \text{cf}(\lambda)$ then $|\mathfrak{N}_\alpha|<\lambda$;
 \item $S \cup \{ S,A,B\} \subset \mathfrak{N}_0$;

 \item (continuity) for all limit ordinals $\alpha \le \text{cf}(\lambda)$, $\mathfrak{N}_\alpha = \bigcup_{\zeta < \alpha} \mathfrak{N}_\zeta$; and

 \item $B \subset \mathfrak{N}_{\text{cf}(\lambda)}$.
\end{enumerate}
By assumption \ref{item_AE},

\begin{equation}\label{eq_all_alpha_h_nice}
\forall \alpha \le \text{cf}(\lambda) \ \forall h \in \mathcal{M} \cap \mathfrak{N}_\alpha: \text{ both } h \restriction \mathfrak{N}_\alpha \text{ and } r^{h,\mathfrak{N}_\alpha} \text{ are members of } \mathcal{M}. \tag{*}
\end{equation} 
Note the ``diagonal" nature of \eqref{eq_all_alpha_h_nice}; it quantifies over \emph{all} members $h$ of $\mathcal{M} \cap \mathfrak{N}_\alpha$, not just the inclusion $f: A \subset B$.  It follows immediately (since $f \in \mathfrak{N}_0 \subseteq \mathfrak{N}_\alpha$ for all $\alpha$) that 

\begin{equation}\label{eq_rest_in_M}
\forall \alpha \ \ f \restriction \mathfrak{N}_\alpha \in \mathcal{M} \text{ and } r^{f,\mathfrak{N}_\alpha} \in \mathcal{M}.
\end{equation}

Moreover, if $\alpha < \text{cf}(\lambda)$, then since $\mathfrak{N}_\alpha$ is an \emph{element} of $\mathfrak{N}_{\alpha+1}$, the diagram $\mathcal{D}^{f,\mathfrak{N}_\alpha}$ and in particular the function $r^{f,\mathfrak{N}_\alpha}$ is an \emph{element} of $\mathfrak{N}_{\alpha+1}$, since $\mathfrak{N} \prec_* (V,\in)$. So it makes sense to restrict $r^{f,\mathfrak{N}_\alpha}$ to $\mathfrak{N}_{\alpha+1}$.  Then we apply \eqref{eq_all_alpha_h_nice} again (with $h=r^{f,\mathfrak{N}_\alpha} \in \mathfrak{N}_{\alpha+1}$) to conclude that

\begin{equation}\label{eq_quot_in_M}
\forall \alpha < \text{cf}(\lambda)  \ \  r^{f,\mathfrak{N}_\alpha} \restriction \mathfrak{N}_{\alpha+1} \text{ is a member of } \mathcal{M}.
\end{equation}

We will use these facts to write $f$ as a transfinite composition of maps from $\mathcal{M}$ that each have codomain of size $<\lambda$, and then use the induction hypothesis on those pieces to conclude that $f$ is in $\text{cell}(\mathcal{M}^{<\kappa})$.



For each $\alpha$ consider the diagram $\mathcal{D}^{f,\mathfrak{N}_\alpha}$.  Since $A \cap (\mathfrak{N}_\alpha \cap B) = \mathfrak{N}_\alpha \cap A$, the pushout of the span $A \leftarrow \mathfrak{N}_\alpha \cap A \rightarrow \mathfrak{N}_\alpha \cap B$ is exactly $A \cup (\mathfrak{N}_\alpha \cap B)$, and the diagram $\mathcal{D}^{f,\mathfrak{N}_\alpha}$ has this form, with all arrows inclusions (recall our assumption that $f$ itself was an inclusion):
% https://q.uiver.app/#
\[\begin{tikzcd}
	A &&&&& B \\
	\\
	&& \begin{array}{c} P_\alpha:= \\ A \cup (\mathfrak{N}_\alpha \cap B) \end{array} \\
	\\
	{\mathfrak{N}_\alpha \cap A} &&&&& {\mathfrak{N}_\alpha \cap B}
	\arrow["f", from=1-1, to=1-6]
	\arrow["{\widetilde{f \restriction \mathfrak{N}_\alpha}}"', curve={height=18pt}, from=1-1, to=3-3]
	\arrow["{r^{f,\mathfrak{N}_\alpha}}"', from=3-3, to=1-6]
	\arrow["\ulcorner"{anchor=center, pos=0.125, rotate=-90}, draw=none, from=3-3, to=5-1]
	\arrow[from=5-1, to=1-1]
	\arrow["{f \restriction \mathfrak{N}_\alpha}"', from=5-1, to=5-6]
	\arrow[from=5-6, to=1-6]
	\arrow[curve={height=-18pt}, from=5-6, to=3-3]
\end{tikzcd}\]


%By assumptions of the theorem, since each $\mathfrak{N}_\alpha \cap \kappa$ is transitive, both $f \restriction \mathfrak{N}_\alpha$ and $r^{f,\mathfrak{N}_\alpha}$ are members of $\mathcal{M}$.  And since $\mathcal{M}$ is closed under pushouts, $\widetilde{f \restriction \mathfrak{N}_\alpha}$ is an element of $\mathcal{M}$. In summary:
%\begin{equation}
%\forall \alpha \le \text{cf}(\lambda) \  \ \widetilde{f \restriction \mathfrak{N}_\alpha} \text{ and } r^{f,\mathfrak{N}_\alpha} \text{ are members of } \mathcal{M}.
%\end{equation}


We noted above that if $\alpha < \lambda$ then since $f$ and $\mathfrak{N}_\alpha$ are both elements of $\mathfrak{N}_{\alpha+1}$, it makes sense to form the diagram $\mathcal{D}^{r^{f,\mathfrak{N}_\alpha}, \mathfrak{N}_{\alpha+1}}$.  This diagram is displayed below, with 
\[
\tau^{\alpha+1}:=r^{r^{f,\mathfrak{N}_\alpha}, \mathfrak{N}_{\alpha+1}} \text{ and } 
\varphi^{\alpha,\alpha+1}:= \widetilde{r^{f,\mathfrak{N}_\alpha} \restriction \mathfrak{N}_{\alpha+1}},
\]
and all arrows are inclusions:



% https://q.uiver.app/#
\[\begin{tikzcd}
	{P_\alpha} &&&&& B \\
	\\
	&&& \begin{array}{c} P_\alpha \cup (\mathfrak{N}_{\alpha+1} \cap B) \\ = A \cup (\mathfrak{N}_\alpha \cap B) \\ \cup (\mathfrak{N}_{\alpha+1} \cap B) \\=A \cup (\mathfrak{N}_{\alpha+1} \cap B) \\=P_{\alpha+1} \end{array} \\
