\begin{equation}\label{33-9-24-55}
	\alpha_{11}(\mathbf{f})=\pi\int_{\mathbb{R}^2}\mathrm{d}^2x\,
	\Big(A_0(x)G^{1,\mathbf{f}}(x)\Big)\Big(x^\mu\partial_{x^\mu}G^{1,\mathbf{f}}(x)\Big)=-\frac{1}{4}.
\end{equation}
Note that the latter functionals depend only on the regularizing function $\mathbf{f}(\cdot)$. At the same time, they do not depend on the regularizing and auxiliary parameters $\Lambda$ and $\sigma$. Secondly, we define a set of auxiliary vertices
\begin{equation}\label{33-d-28-11}
\mathrm{R}_1[\phi]=\int_{\mathbb{R}^2}\mathrm{d}^2x\,\phi^e(x)B_\mu^{eh}(x)B_\mu^{ha}(x)\phi^a(x),
\end{equation}
\begin{equation}\label{33-d-29-1}
\mathrm{R}_2[\phi]=\int_{\mathbb{R}^2}\mathrm{d}^2x\,
	\Big(f^{abc}\phi^b(x)\phi^d(x)f^{cde}\Big)B_\mu^{eh}(x)B_\mu^{ha}(x),
\end{equation}
\begin{equation}\label{33-w-5-1}
\mathrm{R}_3[\phi]=\int_{\mathbb{R}^2}\mathrm{d}^2x\,
	\Big(f^{a_1ga_2}f^{a_1bc}\phi^b(x)\phi^d(x)f^{cde_1}f^{e_2ge_1}\Big)B_\mu^{e_2h}(x)B_\mu^{ha_2}(x),
\end{equation}
\begin{equation}\label{33-d-28-1-1}
\mathrm{R}_4[\phi]=\int_{\mathbb{R}^2}\mathrm{d}^2x\,\phi^e(x)B_\mu^{ea}(x)\partial_{x_\mu}\phi^a(x),
\end{equation}
\begin{equation}\label{33-z-11}
	\hat{\Gamma}_3[\phi]=\int_{\mathbb{R}^2}\mathrm{d}^2x\,f^{abc}\phi^b(x)f^{ced}\phi^e(x)\Big(\partial_{x_\mu}B^{dg}_{\mu}(x)\Big)f^{gha}\phi^h(x),
\end{equation}
\begin{equation}\label{33-d-28-1-2}
	\widetilde{\Gamma}_4[\phi]=\int_{\mathbb{R}^2}\mathrm{d}^2x\,
	f^{a_1b_1a_2}\phi^{b_1}(x)f^{a_2b_2a_3}\phi^{b_2}(x)
	f^{a_3b_3a_4}\phi^{b_3}(x)f^{a_4b_4a_1}\phi^{b_4}(x).
\end{equation}

\begin{theorem}\label{33-t}
Let all the conditions stated above be fulfilled. Then it is possible to exclude nonlocal (disproportionate to the classical action) singular contributions from the three-loop correction \eqref{33-p-31} using the following choice of auxiliary renormalization vertices
\begin{equation*}
\Gamma_{r,3}=-\frac{L_1}{3\pi}\hat{\Gamma}_3,
\end{equation*}
\begin{equation*}
\Gamma_{r,4}=\Lambda^2\bigg(\frac{\alpha_1}{2\pi}-\frac{5\alpha_6}{2}\bigg)
\widetilde{\Gamma}_4
-\frac{15\Lambda^2c_2^2}{2\pi}\mathrm{R}_0\tau_5-
\frac{5L_1}{32\pi^2}\Big(c_2^2\mathrm{R}_1\tau_1+c_2\mathrm{R}_2\tau_2+\mathrm{R}_3\tau_3+c_2^2\mathrm{R}_4\tau_4\Big),
\end{equation*}
where auxiliary finite numbers are defined by the equalities
\begin{align*}
\tau_1=&\,4\theta_3-10\theta_2-2\theta_1+26\alpha_{11},\\
\tau_2=&\,2\alpha_8+34\theta_3-154\theta_2/5+8\theta_1+14\alpha_{11},\\
\tau_3=&\, 8\alpha_8-4\theta_3-164\theta_2/5+8\theta_1-6\alpha_{11},\\
\tau_4=&\,10\alpha_8-60\theta_2+52\theta_1+44\alpha_{11},\\
\tau_5=&-\mathbf{f}(0)/2+\alpha_7-4\alpha_{10}.
\end{align*}
They depend only on the deforming function $\mathbf{f}(\cdot)$. Singular terms proportional to the classical action $S[B]$ or independent of the background field at all can be reduced by a suitable choice of the coefficients $a_2$ and $\hat{\varkappa}_2$. In this case, the structure of the value $a_2$ has the following form
\begin{equation}\label{33-i-7}
a_2=\frac{a_0a_1}{2}-\frac{c_2^3L_1^2}{16(4!)^2\pi^3}\big(2\tau_1-2\tau_2+2\tau_3+\tau_4\Big)+L_1t,
\end{equation}
where $t\in\mathbb{R}$ and it depends only on the regularizing function. $\mathbf{f}(\cdot)$.
\end{theorem}

\begin{theorem}\label{33-tt} Let the assumptions of Theorem \ref{33-t} be fulfilled. Let $\{\mathrm{K}_i(\cdot)\}_{i=1}^4$ be a set of continuous functions such that the relations hold
	\begin{equation*}
		\mathrm{supp}(\mathrm{K}_i)\subset\mathrm{B}_1,\,\,\,
		\int_{\mathbb{R}^2}\mathrm{d}^2x\,\mathrm{K}_i(x)=\tau_i,
	\end{equation*}
	for all index values $i$. Next, using the functionals from Section \ref{33:sec:kva}, we define four vertices
	\begin{equation*}
		\hat{\mathrm{V}}_i[\phi]=\mathrm{V}_i[\mathrm{K}_i,\phi],
	\end{equation*}
	where $i\in\{1,\ldots,4\}$. Then, as an auxiliary vertex $\Gamma_{r,4}$ from Theorem \ref{33-t}, we can choose a functional of the form
	\begin{multline}\label{33-i-2}
		\Lambda^2\bigg(\frac{\alpha_1}{2\pi}-\frac{5\alpha_6}{2}\bigg)
		\widetilde{\Gamma}_4
		-\frac{15\Lambda^2c_2^2}{2\pi}\mathrm{R}_0\tau_5-
		\frac{5L_1}{32\pi^2}\Big(c_2^2\mathrm{R}_1\tau_1\upsilon_1+c_2\mathrm{R}_2\tau_2\upsilon_2+\mathrm{R}_3\tau_3\upsilon_3+c_2^2\mathrm{R}_4\tau_4\upsilon_4\Big)-\\-\frac{5}{32\pi}
		\Big(c_2\hat{\mathrm{V}}_1\vartheta_1+c_2\hat{\mathrm{V}}_2\vartheta_2+\hat{\mathrm{V}}_3\vartheta_3+c_2\hat{\mathrm{V}}_4\vartheta_4\Big),
	\end{multline}
	in which the coefficients $\{\upsilon_i\}_{i=1}^4$ and $\{\vartheta\}_{i=1}^4$ are subject to the following conditions
	\begin{align*}
		\upsilon_1-\vartheta_1+\vartheta_2-\vartheta_3=&\,1,\\
		\upsilon_2-\vartheta_2+\vartheta_4/2=&\,1,\\
		\upsilon_3-\vartheta_3=&\,1,\\
		\upsilon_4+\vartheta_4=&\,1.
	\end{align*}
	In this case, the third coefficient $a_2$ of the renormalization constant becomes equal to
	\begin{equation}\label{33-i-6}
		a_2\to a_2=\frac{a_0a_1}{2}-\frac{c_2^3L_1^2}{16(4!)^2\pi^3}\big(2\tau_1\upsilon_1-2\tau_2\upsilon_2+2\tau_3\upsilon_3+\tau_4\upsilon_4\Big)+L_1t_1,
	\end{equation}
	where the number $t_1\in\mathbb{R}$ depends on the regularizing function $\mathbf{f}(\cdot)$, the set of coefficients $\{\vartheta_i\}_{i=1}^4$, and the set of kernels $\{\mathrm{K}_i(\cdot)\}_{i=1}^4$, and it does not depend on $\{\upsilon_i\}_{i=1}^4$. In particular, fixing the values as follows $\upsilon_1=\upsilon_2=\upsilon_3=\upsilon_4=0$, we obtain coefficients for quasi-local vertices in the form
	\begin{equation*}
		\vartheta_1=-1/2,\,\,\,
		\vartheta_2=-1/2,\,\,\,
		\vartheta_3=-1,\,\,\,
		\vartheta_4=1.
	\end{equation*}
	In this case, the coefficient for the renormalization constant takes the form
	\begin{equation}\label{33-i-1}
		a_2\to a_2=\frac{a_0a_1}{2}+L_1t_2,
	\end{equation}
	where $t_2\in\mathbb{R}$ depends on the regularizing function $\mathbf{f}(\cdot)$ and the set of kernels $\{\mathrm{K}_i(\cdot)\}_{i=1}^4$.
\end{theorem}


\noindent\textbf{Additional comments on Theorem \ref{33-t}.}
\begin{enumerate}
	\item The three-loop coefficient $a_2$ for the coupling constant in the main order is proportional to the logarithm squared, which is completely consistent with the general theory.
	\item The coefficient $a_2$ does not contain power-law singularities.
	\item In addition to the functionals $\theta_i$ containing the differences of deformed Green's functions, the answer also contains integrals of the special form $\alpha_8$ and $\alpha_{11}$. It can be noted that $\alpha_{11}$ is equal to $-1/4$ and does not depend on the regularizing function. At the same time, $\alpha_8$ is the result of deformation and is somewhat artificial in nature. It would be zero in the absence of regularization. Indeed, we have
	 \begin{equation*}
	 \pi\int_{\mathbb{R}^2}\mathrm{d}^2x\,
	 \Big(A_0(x)G^{1,\mathbf{f}}(x)\Big)^2|x|^2\longrightarrow
	 \pi\int_{\mathbb{R}^2}\mathrm{d}^2x\,
	 \Big(A_0(x)\frac{\ln(|x|\sigma)}{2\pi}\Big)^2|x|^2=
	 \pi\int_{\mathbb{R}^2}\mathrm{d}^2x\,
	 \Big(|x|\delta(x)\Big)^2=0.
	 \end{equation*} 
 \item Auxiliary (counter) vertices do not contain a singularity of the form $\Lambda^2L$.
 \item The triple vertex $\hat{\Gamma}_3$ is an intermediate (auxiliary) object. It can be noted that it is proportional to $\partial_{x_\mu}B^a_\mu(x)$, and thus is involved in solving the classical equation of motion. It is assumed that in subsequent renormalization orders, additional terms will arise, which in total will lead to a functional equal to zero on the set of solutions of the quantum equation of motion. Thus, this amount will be zero due to the choice of the background field.
 \item The part of the coefficient $a_2$ from \eqref{33-i-7}, proportional to $L_1^2$, consists of two parts. The first one is standard and appears in every renormalization scheme. It can be called a "reaction" of the renormalization process on the first two loops. The second term is a regularization feature and a consequence of the requirement for locality of auxiliary vertices $\mathrm{R}_i[\,\cdot\,]$. It depends on the regularizing function $\mathbf{f}(\cdot)$. Note that in dimensional regularization, such a term is zero.
\end{enumerate}

\noindent\textbf{Additional comments on Theorem \ref{33-tt}.}
\begin{enumerate}
	\item The abandonment of the locality of auxiliary vertices and the transition to quasi-local functionals helped solve the problem of the presence of a second term in \eqref{33-i-7}.
	\item The introduced nonlocal vertices $\mathrm{\hat{V}}_i[\,\cdot\,]$ are not the only option. In particular, they depend on the kernels of $\mathrm{K}_i$. Moreover, we can enter vertices that differ significantly from the existing ones, see Section \ref{33:sec:zak}.
	\item After adjusting the coefficient $a_2$, the renormalized coupling constant can be used to calculate the $\beta$-function. Indeed, we can rewrite formula \eqref{33-p-32} as
	\begin{equation*}
\gamma_0^2=\gamma^2+a_0^{\phantom{1}}\gamma^4+(a_0^2+a_1^{\phantom{1}})\gamma^6+(a_0^3+2a_0^{\phantom{1}}a_1^{\phantom{1}}+a_2^{\phantom{1}})\gamma^8+\ldots,
	\end{equation*}
	then for the equation
	\begin{equation*}
\Lambda\frac{\mathrm{d}\gamma^2_0}{\mathrm{d}\Lambda}=\beta_1^{\phantom{1}}\gamma^4_0+\beta_2^{\phantom{1}}\gamma^6_0+\beta_3^{\phantom{1}}\gamma^8_0+\ldots
	\end{equation*}
	we obtain the following coefficients
	\begin{equation*}
		\beta_1=-\frac{c_2}{4\pi}
		,\,\,\,
		\beta_2=-\frac{c_2^2}{3(4\pi)^2}(3\theta_1+2\theta_2)
		,\,\,\,
		\beta_3=t_2
		.
	\end{equation*}
	\item The problem of calculating $t_2$ for the proposed deformation remains open.
\end{enumerate}


\subsection{Proofs}
\noindent\textbf{Proof of Theorem \ref{33-t}.}
Let us consider formula \eqref{33-p-31} for the functional $W_2[B,\Lambda]$ and substitute into it explicit asymptotic expansions with respect to the regularizing parameter $\Lambda$ for each individual term. Calculations of such decompositions are carried out in Section \ref{33:sec:cl}, therefore we provide only references to the corresponding decompositions:
\begin{align*}
\mathbb{H}_0^{\mathrm{sc}}(\Gamma_3\Gamma_5)&\longrightarrow
\mbox{see Lemma \ref{33-lem-3} in Section \ref{33:sec:cl:2}},
\\
\mathbb{H}_0^{\mathrm{sc}}\big(\Gamma_3^4\big)&\longrightarrow
\mbox{see Lemma \ref{33-lem-1} in Section \ref{33:sec:cl:3}},
\\
\mathbb{H}_0^{\mathrm{sc}}(\Gamma_3^2\Gamma_4^{\phantom{1}})&\longrightarrow
\mbox{see Lemma \ref{33-lem-13} in Section \ref{33:sec:sum1}},
\\
\mathbb{H}_0^{\mathrm{sc}}(\Gamma_4^2)&\longrightarrow
\mbox{see Lemma \ref{33-lem-14} in Section \ref{33:sec:sum2}},
\\
\mathbb{H}_0^{\mathrm{sc}}(\Gamma_6)&\longrightarrow
\mbox{see Lemma \ref{33-lem-10} in Section \ref{33:sec:cl:6}}.
\end{align*}
Since the statements are proved for the more general case, the free parameters $\sigma_1$--$\sigma_5$ should be chosen such that equalities hold $\ln(\Lambda/\sigma_i)=L_1$ for all $i\in\{1,\ldots,5\}$.
Additionally, we use the decomposition for the two-loop diagram:
\begin{equation}\label{33-m-6}
\mathbb{H}_0^{\mathrm{sc}}\big(\Gamma_4\big)\longrightarrow
\mbox{see Lemma \ref{33-lem-15} in Section \ref{33:sec:sum2}}.
\end{equation}
It has been studied in the works \cite{Ivanov-Akac,Iv-244}. Note that the finite parts were preserved in the last relation, since the diagram is included in $W_1[B,\Lambda]$ and, thus, multiplied by the renormalization coefficient $a_0$. Further, after additional summation, we come to the relation
\begin{align}\nonumber
W_2[B,\Lambda]\stackrel{\mathrm{s.p.}}{=}&\,
	\bigg(\frac{\Lambda^2\alpha_1}{4(6!)\pi}-\frac{\Lambda^2\alpha_6}{4!4!}\bigg)\mathbb{H}_0^{\mathrm{sc}}(\widetilde{\Gamma}_4)-\frac{c_2^2}{96\pi}\Lambda^2J_5[B]\tau_5-\frac{L_1}{12(3!5!)\pi}\mathbb{H}_0^{\mathrm{sc}}(\Gamma_3\hat{\Gamma}_3)
	\\\label{33-i-4}&-
	\frac{L}{8(4!)^2\pi^2}\Big(c_2^2J_1[B]\tau_1+c_2J_2[B]\tau_2+J_3[B]\tau_3+c_2^2J_4[B]\tau_4\Big)
	\\\nonumber
	&-\frac{\mathbb{H}_0^{\mathrm{sc}}(\Gamma_3\Gamma_{r,3})}{4(3!5!)}
	-\frac{\mathbb{H}_0^{\mathrm{sc}}(\Gamma_{r,4})}{2(6!)}+\hat{\upsilon}_1S[B]+\hat{\upsilon}_2,
\end{align}
where $\hat{\upsilon}_1$ and $\hat{\upsilon}_2$ are singular coefficients with respect to the regularizing parameter $\Lambda$. They are independent of the background field.
Next, we note that the $J$-functionals, the definitions for which are in Section \ref{33:sec:dia}, can be replaced via auxiliary vertices as follows
\begin{equation}\label{33-i-3}
J_5[B]\longrightarrow\frac{1}{2}\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_0),\,\,\,
J_i[B]\longrightarrow\frac{1}{2}\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_i),
\end{equation}
where $i=1,2,3,4$. However, such a substitution can only lead to a shift in the coefficients $\hat{\upsilon}_1$ and $\hat{\upsilon}_2$. Therefore, by choosing the vertices $\Gamma_{r,3}$ and $\Gamma_{r,4}$ as suggested in the statement, all singular nonlocal components are reduced. It is clear that the part proportional to the classical action $S[B]$ can be removed by a suitable choice of the coefficient $a_2$ from \eqref{33-p-32}, see also \eqref{33-p-31}. Let us clarify the structure of the value $a_2$.

Note that during the calculation of the asymptotics in Section \ref{33:sec:cl}, it was shown that all logarithmic singularities are constructed using monomials $L_1^k$, where $k>0$. Thus, the main logarithmic contribution can be calculated by differentiating by the auxiliary parameter $\sigma$. Indeed, we calculate the derivative in equation \eqref{33-p-31}, and then use equation \eqref{33-p-33} for $i=1$, the absence of dependence of the vertices and the deformed Green's function on the parameter $\sigma$, as well as the fact that such differentiation does not lead to towards new singularities. Note that only the last five terms in \eqref{33-p-31} can make a non-zero contribution. For convenience, the operator $-\sigma\partial_{\sigma}$ we notate by a dot. Then we get the equality
\begin{align}\label{33-i-5}
-\sigma\frac{\mathrm{d}}{\mathrm{d}\sigma}&W_2[B,\Lambda]=-\sigma\frac{\mathrm{d}}{\mathrm{d}\sigma}
\bigg(-\frac{\mathbb{H}_0^{\mathrm{sc}}(\Gamma_3\Gamma_{r,3})}{4(3!5!)}
-\frac{\mathbb{H}_0^{\mathrm{sc}}(\Gamma_{r,4})}{2(6!)}+a_0W_1[B,\Lambda]-\frac{a_2-a_0a_1}{4}S[B]+\hat{\varkappa}_2\bigg)\\\nonumber&
=-\frac{\mathbb{H}_0^{\mathrm{sc}}(\Gamma_3\hat{\Gamma}_3)}{12(3!5!)\pi}+
\frac{1}{16(4!)^2\pi^2}\mathbb{H}_0^{\mathrm{sc}}\big(c_2^2\mathrm{R}_1\tau_1+c_2\mathrm{R}_2\tau_2+\mathrm{R}_3\tau_3+c_2^2\mathrm{R}_4\tau_4\Big)
-\frac{\dot{a}_2-\dot{a}_0a_1}{4}S[B]+\dot{\hat{\varkappa}}_2.
\end{align}
Next, note that the diagram $\mathbb{H}_0^{\mathrm{sc}}(\Gamma_3\hat{\Gamma}_3)$ is finite, while the remaining diagrams can be calculated explicitly
\begin{equation*}
\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_1)\stackrel{\mathrm{s.p.}}{=}-\frac{L_1c_2}{\pi}S[B]
,\,\,\,
\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_2)\stackrel{\mathrm{s.p.}}{=}\frac{L_1c_2^2}{\pi}S[B]
,\,\,\,
\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_3)\stackrel{\mathrm{s.p.}}{=}-\frac{L_1c_2^3}{\pi}S[B]
,\,\,\,
\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_4)\stackrel{\mathrm{s.p.}}{=}-\frac{L_1c_2}{2\pi}S[B].
\end{equation*}
Therefore, the requirement $\dot{W}_2[B,\Lambda]\stackrel{\mathrm{s.p.}}{=}0$ leads to a first-order differential equation
\begin{equation*}
\dot{a}_2\stackrel{\mathrm{s.p.}}{=}-\frac{c_2^3L_1}{8(4!)^2\pi^3}\big(2\tau_1-2\tau_2+2\tau_3+\tau_4\Big)
+a_0\dot{a}_1,
\end{equation*}
which can be integrated explicitly and leads to the answer stated in the theorem. The proof is finished.\\


\noindent\textbf{Proof of Theorem \ref{33-tt}.} Let us again consider the representation from \eqref{33-i-4} for the singular part of the third loop correction $W_2[B,\Lambda]$. However, instead of replacing \eqref{33-i-3}, let us use the calculations obtained in Section \ref{33:sec:kva} and perform the substitutions taking into account the fairness of the following transitions
\begin{align*}
	c_2^2\tau_1\upsilon_1\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_1)
	+c_2\pi L_1^{-1}\vartheta_1\mathbb{H}_0^{\mathrm{sc}}(\mathrm{\hat{V}}_1)\longrightarrow&\,
	\tau_1\Big(2c_2^2\tau_1\upsilon_1J_1-2c_2^2\vartheta_1J_1\Big),
	\\
	c_2\tau_2\upsilon_2\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_2)
	+c_2\pi L_1^{-1}\vartheta_2\mathbb{H}_0^{\mathrm{sc}}(\mathrm{\hat{V}}_2)\longrightarrow&\,
	\tau_2\Big(2c_2\tau_2\upsilon_2J_2+2c_2\vartheta_2(c_2J_1-J_2)\Big),
	\\
	\tau_3\upsilon_3\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_3)
	+\pi L_1^{-1}\vartheta_3\mathbb{H}_0^{\mathrm{sc}}(\mathrm{\hat{V}}_3)\longrightarrow&\,
	\tau_3\Big(2\tau_3\upsilon_3J_3+2\vartheta_3(-c_2^2J_1-J_3)\Big),
	\\
	c_2^2\tau_4\upsilon_4\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_4)
	+c_2\pi L_1^{-1}\vartheta_4\mathbb{H}_0^{\mathrm{sc}}(\mathrm{\hat{V}}_4)\longrightarrow&\,
	\tau_4\Big(2c_2^2\tau_4\upsilon_4J_4+c_2\vartheta_4(2c_2J_4-J_2)\Big),
\end{align*}
in which the terms proportional to the classical action are omitted.
In this case, the auxiliary coefficients must obey the conditions from Theorem \ref{33-tt}, which is easy to verify after adding up all the relations and comparing the linear combinations from \eqref{33-i-2} and \eqref{33-i-4}. Thus, the possibility of using a vertex of the form \eqref{33-i-2} has been proved.

Turning to obtaining the renormalization coefficient, we use the differentiation by the parameter $\sigma$ and the corresponding formula from \eqref{33-i-5}. Note that the auxiliary quasi-local vertices are independent of the parameter $\sigma$. Therefore, after differentiation, we get the second line from \eqref{33-i-5} with the replacement $\tau_i\to\tau_i\upsilon_i$. Therefore, the third coefficient $a_2$ is obtained by using the same substitution. Next, it is easy to make sure that the diagrams $L_1\mathbb{H}_0^{\mathrm{sc}}(\mathrm{R}_i)$ for $i\in\{1,2,3,4\}$ does not lead to terms proportional to the classical action and the first degree of the logarithm $L_1$, which implies the absence of dependence on the set $\{\upsilon_i\}_{i=1}^4$. The theorem has been proved.

\subsection{Special cases}
\label{33:sec:spec}
Let us look at some explicit examples. To do this, let us pay attention to the constants $\tau_i$ from Theorem \ref{33-t}. They are linear combinations of functionals depending on the deformed free Green's function, and in particular contain $\theta$-functionals. Let us study them in more detail and start with $\theta_1$, see \eqref{33-p-38},
\begin{equation}\label{33-p-38-11}
	\frac{\theta_1}{2\pi}=
	\int_{\mathbb{R}^{2}}\mathrm{d}^2x\,
	\Big(A_0(x)G^{1,\mathbf{f}}(x)\Big)
	\Big(G^{1,\mathbf{f}}(x)-
	G^{1,\mathbf{f}}(0)\bigg).
\end{equation}
Next, we note that the regularization from Section \ref{33:sec:ps} leads to the deformation of the Green's function, which in the momentum representation is reduced to multiplying the function $|k|^{-2}$ by the regularizing factor $\rho(|k|/\Lambda)$. The explicit form of such a factor is not important yet, we only assume that the function $\rho(|k|/\Lambda)/|k|^2$ is bounded and integrable in the exterior of a ball of any radius centered at the origin, and also has the properties
\begin{equation*}
\rho(0)=1,\,\,\,0\leqslant\rho(s)\leqslant1\,\,\,\mbox{for almost all}\,\,\,s>0.
\end{equation*}
Let us switch to \eqref{33-p-38-11} in the momentum representation. Despite the fact that $1/|k|^2$ is a nonintegrable function in two-dimensional space, the difference is well defined
\begin{equation*}
\theta_1=\frac{1}{2\pi}
\int_{\mathbb{R}^{2}}\mathrm{d}^2k\,|k|^{-2}
\Big(\rho^2(|k|/\Lambda)-\rho(|k|/\Lambda)\Big).
\end{equation*}
It instantly follows from the properties of the function $\rho(\cdot)$ that $\theta_1\leqslant0$. In this case, the equality\footnote{This property will be useful later when discussing the standard cutoff in the momentum representation. Thus, the relation is true for a wider class of deformations.} $\theta_1=0$ can be fulfilled if and only if the mapping $\rho(|\cdot|)$ takes values from $\{0,1\}$ almost everywhere. The same reasoning holds for all $\theta_k$, $k>0$.
\begin{lemma}\label{33-ll-1}
Taking into account the type of regularization, the relations $\theta_k\leqslant0$ are correct for $k>0$. The constraint $a_1\geqslant0$ for the two-loop renormalization coefficient is also valid.
\end{lemma}

Note that the deformation of the Green's function, introduced in Section \ref{33:sec:ps}, in the main decomposition order near the diagonal was reduced to the deformation of the free fundamental solution in some neighborhood of zero (in a ball of radius $1/\Lambda$). This was important for using the averaging operator in the formulation of regularization. In particular, this led to the fact that the support of the function $A_0(x)G^{\Lambda,\mathbf{f}}(x)$ was contained in the ball $\mathrm{B}_{1/\Lambda}$. However, technically, this restriction was not applied in all functionals (diagrams).

Let us try to compare the deformation used with the standard cutoff in the momentum representation. In other words, let us proceed formally to the limiting case. Namely, choose \footnote{In the general case, we can consider a broader class of sets of finite measure. In particular, we can choose $|k|<a\in\mathbb{R}_+$, which eventually reduces to scaling the regularizing parameter.} $\rho(|k|)=\chi(|k|<1)$, where $\chi(\cdot)$ is the characteristic function of the specified set in $\mathbb{R}^2$. Note that in this situation, the function
\begin{equation*}
P(x-y)=\frac{1}{4\pi^2}\int_{\mathbb{R}^2}\mathrm{d}^2k\,e^{ik_\mu(x-y)^{\mu}}\chi(|k|<1)
\end{equation*}
is the kernel of an integral representation for a projector. Thus, the relation is correct
\begin{equation*}
\int_{\mathbb{R}^2}\mathrm{d}^2z\,P(x-z)P(z-y)=P(x-y),
\end{equation*}
which should be understood in the sense of generalized functions, see \cite{Gelfand-1964,Vladimirov-2002}. Therefore, as a deformed combination of $A_0(x)G_{\mathrm{def}}^\Lambda(x)$, we can choose the function $P(x)$, that is
\begin{equation*}
A_0(x)G_{\mathrm{def}}(x)=P(x)=\frac{1}{4\pi^2}\int_{\mathbb{R}^2}\mathrm{d}^2k\,e^{ik_\mu x^{\mu}}\chi(|k|<\Lambda)=\frac{\Lambda J_1(|x|\Lambda)}{2\pi|x|},
\end{equation*}
where in the last equation the definition for the Bessel function was used. This choice instantly leads to the equality $\theta_k=0$ for all $k>0$. And this fact is a positive feature of the standard cutoff in the momentum representation. It minimizes the value of $-\theta_i$. 

However, when trying to calculate, for example, the functional from \eqref{33-9-24-52}, a significant problem appears. Indeed, direct substitution leads to a divergent integral
\begin{equation*}
\alpha_8\Big|_{G^{\Lambda,\mathbf{f}}\to G_{\mathrm{def}}^\Lambda}=\lim_{N\to+\infty}\pi\int_{\mathrm{B}_N}\mathrm{d}^2x\,
\Big(A_0(x)G_{\mathrm{def}}^\Lambda(x)\Big)^2|x|^2=\lim_{N\to+\infty}\frac{1}{2}\int_0^N\mathrm{d}s\,sJ_1^2(s)=+\infty.
\end{equation*}
To understand what the number $\alpha_8$ should be equal to and which singularity it corresponds to, it is necessary to return to the process of obtaining it. When calculating, the functional was determined from the equality
\begin{equation*}
\frac{L\alpha_8}{2\pi}\stackrel{\mathrm{s.p.}}{=}\pi\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2x\,
\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)^2G^{\Lambda,\mathbf{f}}(x)|x|^2\equiv\mathrm{Y}(G^{\Lambda,\mathbf{f}}),
\end{equation*}
as a coefficient about the logarithmic singularity. Thus, consider $\mathrm{Y}(G_{\mathrm{def}}^\Lambda)$.
For these purposes, we calculate the explicit form of the function $G_{\mathrm{def}}^\Lambda(x)$. Representing the Laplace operator in polar coordinates, we obtain
\begin{equation*}
G_{\mathrm{def}}^\Lambda(x)=\int_{1/\sigma}^{|x|}\mathrm{d}s\,\frac{J_{0}(s\Lambda)-1}{2\pi s}+\mathcal{O}\big(1/\Lambda\big),
\end{equation*}
where the integration used the fact that removing the regularization $\Lambda\to+\infty$ should result in the function $-\ln(|x|\sigma)/2\pi$. The correction term does not depend on the variable $x$. Therefore, after scaling, we have
\begin{equation*}
\mathrm{Y}(G_{\mathrm{def}}^\Lambda)=\int_{0}^{\Lambda/\sigma}\mathrm{d}t\,t
J_1^2(t)\int^{\Lambda/\sigma}_{t}\mathrm{d}s\,\frac{1-J_{0}(s)}{4\pi s}\\
=
\int^{\Lambda/\sigma}_{0}\mathrm{d}s\,\frac{1-J_{0}(s)}{4\pi s}
\int_{0}^{s}\mathrm{d}t\,t
J_1^2(t).
\end{equation*}
Let us differentiate and consider the asymptotic expansion for large $\Lambda$
\begin{align*}
\frac{\mathrm{d}}{\mathrm{d}\Lambda}\mathrm{Y}(G_{\mathrm{def}}^\Lambda)=&\,
\frac{1-J_{0}(\Lambda/\sigma)}{4\pi\Lambda}
\int_{0}^{\Lambda/\sigma}\mathrm{d}t\,t
J_1^2(t)\\=&\,\frac{1}{4\pi^2\sigma}
+\frac{\cos(2\Lambda/\sigma)}{8\pi^2\Lambda}
+\mathcal{O}\big(\Lambda^{-3/2}\big).
\end{align*}
Thus, the function $\mathrm{Y}(G_{\mathrm{def}}^\Lambda)$ has a power-law behavior at high momentum and, therefore, leads to significant differences between the two types of cutoffs. Of course, singular power contributions should not depend on the auxiliary parameter $\sigma$, and therefore such terms should cancel each other out with similar contributions from other functionals. However, further study of the cutoff in the momentum representation is beyond the scope of this work.


