\subsection{Proof of Lemma \ref{33-lem-7}}
\label{33:sec:appl:2}
Relation \eqref{33-r-25} follows from the explicit calculation. Let us do it. From \eqref{33-r-23} we get
\begin{equation}\label{33-r-23-1}
	G_{2}^{\nu\mu}(0)=-\frac{\delta_{\mu\nu}}{2}
	\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2z\,
	G^{\Lambda,\mathbf{f}}(y)
	G^{\Lambda,\mathbf{f}}(y-z)
	A_0(z)G^{\Lambda,\mathbf{f}}(z)+\frac{\delta_{\mu\nu}}{16\pi\sigma^2}.
\end{equation}
Let us write the middle deformed function as  $G^{\Lambda,\mathbf{f}}=G^{\Lambda,\mathbf{f}}\pm G$, then the first part of the integral is
\begin{align*}
	\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2z\,
	G^{\Lambda,\mathbf{f}}(y)&
	\Big(G^{\Lambda,\mathbf{f}}(y-z)-G(y-z)\Big)
	A_0(z)G^{\Lambda,\mathbf{f}}(z)\\&=\frac{L}{2\pi\Lambda^2}
	\int_{\mathbb{R}^2}\mathrm{d}^2y\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
	\Big(G^{1,\mathbf{f}}(y-z)-G(y-z)\Big)
	A_0(z)G^{1,\mathbf{f}}(z)+\mathcal{O}(1/\Lambda^2)
	\\&=\frac{L}{2\pi\Lambda^2}
	\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
	\Big(G^{1,\mathbf{f}}(y)-G(y)\Big)+\mathcal{O}(1/\Lambda^2)
	\\&=\frac{L}{8\pi\Lambda^2}\bigg(
	\int_0^1\mathrm{d}^2s\,\mathbf{f}(s)-1\Bigg)+\mathcal{O}(1/\Lambda^2).
\end{align*}
In turn, the following chain of relations is true for the second part
\begin{align*}
	\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2z\,
	G^{\Lambda,\mathbf{f}}(y)&G(y-z)
	A_0(z)G^{\Lambda,\mathbf{f}}(z)\\&=\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2z\,
	G^{\Lambda,\mathbf{f}}(y)G^{1/|y|,\mathbf{0}}(z)
	A_0(z)G^{\Lambda,\mathbf{f}}(z)
	\\&=\frac{1}{8\pi\sigma^2}-\frac{L}{4\pi\Lambda^2}+\frac{L}{8\pi\Lambda^2}\int_0^1\mathrm{d}s\,\mathbf{f}(s)\\&+\frac{L}{8\pi\Lambda^2}
	\int_{\mathrm{B}_{1}}\mathrm{d}^2y\,A_0(y)G^{1,\mathbf{f}}(y)\big(1-|y|^2\big)
	+\mathcal{O}(1/\Lambda^2).
\end{align*}
Finally, by describing the last integral and substituting all the parts in \eqref{33-r-23-1}, taking into account Definition \eqref{33-r-24-4}, we obtain the declared equality \eqref{33-r-25}.



\subsection{Auxiliary lemmas}
\label{33:sec:appl:1}
\begin{lemma}\label{33-lem-2} Let $v_1(\cdot)$ and $v_2(\cdot)$ be continuous functions on $\mathbb{R}^2$ with the Hölder exponent\footnote{Note that the introduction of the Hölder exponent is related to the fact that the functions in the work are not smooth and may have logarithmic behavior. In the statements below, the Hölder index is introduced for the same reasons.} $\alpha>0$, see \cite{He-1}, decreasing well enough at infinity (such that the integrals below converge). Then, taking into account the explicit form of regularization \eqref{33-o-55}, the following asymptotic expansions are valid for large values of the regularizing parameter $\Lambda$
	\begin{equation*}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1(x)v_2(y)\Big(\partial_{x^{\nu}}G^{\Lambda,\mathbf{f}}(x-y)\Big)\Big(\partial_{y^{\mu}}G^{\Lambda,\mathbf{f}}(x-y)\Big)\stackrel{\mathrm{s.p.}}{=} -\frac{L}{4\pi}\int_{\mathbb{R}^{2}}\mathrm{d}^2x\,v_1(x)v_2(x)\delta_{\nu\mu}+\mathcal{O}(1),
	\end{equation*}
	\begin{equation*}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1(x)v_2(y)\Big(\partial_{x^{\nu}}\partial_{y^{\mu}}G^{\Lambda,\mathbf{f}}(x-y)\Big)G^{\Lambda,\mathbf{f}}(x-y) \stackrel{\mathrm{s.p.}}{=} \frac{L}{4\pi}\int_{\mathbb{R}^{2}}\mathrm{d}^2x\,v_1(x)v_2(x)\delta_{\nu\mu}+\mathcal{O}(1).
	\end{equation*}
\end{lemma}
\begin{proof} Note that the integration domain $\mathbb{R}^2\times\mathbb{R}^2$ can be replaced by $\mathrm{B}_{1/\sigma}(y)\times\mathbb{R}^2$, where $\sigma$ is the mentioned above parameter. It is a finite fixed value, which, neglecting the finite integral, does not contain singularities with respect to the regularizing parameter $\Lambda$. In the remaining integral, we decompose one more time, then replace $v_1(x)\to v_1(y)$, again discarding the final parts, and also use a chain of relations
	\begin{equation}\label{33-r-5}
		\int_{\mathrm{B}_{1/\sigma}(y)}\mathrm{d}^2y\,\Big(\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x-y)\Big)
		\Big(\partial_{y^\mu}G^{\Lambda,\mathbf{f}}(x-y)\Big)\stackrel{\mathrm{s.p.}}{=}
		\frac{-1}{4\pi^2}\int_{1/\Lambda\leqslant|x|\leqslant1/\sigma}
		\mathrm{d}^2x\,\frac{x^\nu x^\mu}{|x|^4}\stackrel{\mathrm{s.p.}}{=}-
		\frac{L}{4\pi}\delta_{\mu\nu},
	\end{equation}
	where the replacement of the variable $x\to x+y$ was additionally used. This leads to the stated result. The second integral is analyzed similarly.
\end{proof}

\begin{lemma}\label{33-lem-4} Let $v_1^{ab}(\cdot)$ and $v_2^{ab}(\cdot)$ be matrix-valued continuously differentiable functions on $\mathbb{R}^2$, decreasing well enough at infinity (such that the integrals below converge). Additionally, we require that the first partial derivatives have the Hölder exponent $\alpha>0$, see \cite{He-1}. Then, taking into account the explicit form of regularization \eqref{33-o-55}, the following asymptotic expansions are valid for large values of the regularizing parameter $\Lambda$
	\begin{multline}\label{33-r-8}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(x)
		\Big(\partial_{y^\mu}G_\Lambda^{bc}(x,y)\Big)
		\Big(\partial_{x_\nu}D_\nu^{ad}(x)G_\Lambda^{de}(x,y)\Big)
		v_2^{ec}(y)
		\stackrel{\mathrm{s.p.}}{=}\\\stackrel{\mathrm{s.p.}}{=} \frac{L}{\pi}
		\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(y)B_\mu^{bc}(y)v_2^{ac}(y)+\mathcal{O}(1),
	\end{multline}
	\begin{multline}\label{33-r-9}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(x)
		\Big(G_\Lambda^{bg}(x,y)B_\mu^{gc}(y)\Big)
		\Big(\partial_{x_\nu}D_\nu^{ad}(x)G_\Lambda^{de}(x,y)\Big)
		v_2^{ec}(y)
		\stackrel{\mathrm{s.p.}}{=}\\\stackrel{\mathrm{s.p.}}{=} -\frac{2L}{\pi}
		\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(y)B_\mu^{bc}(y)v_2^{ac}(y)+\mathcal{O}(1),
	\end{multline}
	\begin{multline}\label{33-r-10}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(x)
		\Big(G_\Lambda^{bg}(x,y)\overleftarrow{D}_\mu^{gc}(y)\Big)
		\Big(\partial_{x_\nu}D_\nu^{ad}(x)G_\Lambda^{de}(x,y)\Big)
		v_2^{ec}(y)
		\stackrel{\mathrm{s.p.}}{=}\\\stackrel{\mathrm{s.p.}}{=} -\frac{L}{\pi}
		\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(y)B_\mu^{bc}(y)v_2^{ac}(y)+\mathcal{O}(1).
	\end{multline}
	In this case, the operator $\partial_{x_\nu}D_\nu^{ad}(x)$ in the left parts can be replaced by aither $D_\nu^{ad}(x)\partial_{x_\nu}$ or $-2A^{ad}(x)$.
\end{lemma}
\begin{proof} Consider the left hand side of the first relation. Taking into account the expansions near the diagonal \eqref{33-o-5} and \eqref{33-r-1}, only the following three terms can have a singular contribution
	\begin{equation*}
		4\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(x)
		\Big(\partial_{y^\mu}G^{\Lambda,\mathbf{f}}(x-y)\Big)
		\Big(\partial_{x_\nu}\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x-y)\Big)
		v_2^{ab}(y),
	\end{equation*}
	\begin{equation*}
		4\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(x)
		\Big(\partial_{y^\mu}G^{\Lambda,\mathbf{f}}(x-y)\Big)
		\Big(\partial_{x_\nu}\partial_{x^\nu}\eta_1^{ae}(x,y)-\partial_{x_\nu}B_\nu^{ae}(x)G^{\Lambda,\mathbf{f}}(x-y)\Big)
		v_2^{eb}(y),
	\end{equation*}
	\begin{equation}\label{33-r-7}
		4\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(x)
		\Big(\partial_{y^\mu}\eta_1^{bc}(x,y)\Big)
		\Big(\partial_{x_\nu}\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x-y)\Big)
		v_2^{ac}(y).
	\end{equation}
	The first two are convergent integrals when regularization is removed and do not contain a singular component, since the following relations are fulfilled
	\begin{equation*}
		\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2x\,
		\Big(\partial_{x^\mu}G^{\Lambda,\mathbf{f}}(x)\Big)
		\Big(\partial_{x_\nu}\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x)\Big)=0,
	\end{equation*}
	\begin{equation}\label{33-r-6}
		\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2x\,
		\Big(\partial_{x^\mu}G^{\Lambda,\mathbf{f}}(x)\Big)
		\bigg(-\partial_{x_\nu}\partial_{x^\nu}
		\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2z\,
		G^{\Lambda,\mathbf{f}}(x-z)\partial_{z^\rho}G^{\Lambda,\mathbf{f}}(z)
		-\partial_{x^\rho}G^{\Lambda,\mathbf{f}}(x)\bigg)\stackrel{\mathrm{s.p.}}{=}0.
	\end{equation}
	Note that the latter equality is proved by integration by parts. Indeed, using spherical averaging and the fact that the support of the function $\partial_{x_\nu}\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x)$ is located in the ball $\mathrm{B}_{1/\Lambda}$, we get
	\begin{align*}
		\eqref{33-r-6}&\stackrel{\mathrm{s.p.}}{=}\frac{\delta_{\mu\rho}}{2}
		\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,
		\Big(\partial_{x_\eta}\partial_{x^\eta}G^{\Lambda,\mathbf{f}}(x)\Big)
		\bigg(\partial_{x_\nu}\partial_{x^\nu}
		\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2z\,
		G^{\Lambda,\mathbf{f}}(x-z)G^{\Lambda,\mathbf{f}}(z)
		+G^{\Lambda,\mathbf{f}}(x)\bigg)\\&\stackrel{\mathrm{s.p.}}{=}
		\frac{\delta_{\mu\rho}}{2}
		\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,
		\Big(\partial_{x_\eta}\partial_{x^\eta}G^{\Lambda,\mathbf{f}}(x)\Big)
		\bigg(
		\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2z\,
		\Big(\partial_{z_\eta}\partial_{z^\eta}G^{\Lambda,\mathbf{f}}(z)\Big)G^{\Lambda,\mathbf{f}}(x-z)
		+\frac{\ln(\Lambda/\sigma)}{2\pi}\bigg)\\&\stackrel{\mathrm{s.p.}}{=}
		\frac{\delta_{\mu\rho}}{2}\frac{\ln(\Lambda/\sigma)}{2\pi}
		\int_{\mathrm{B}_{1}}\mathrm{d}^2x\,
		\Big(\partial_{x_\eta}\partial_{x^\eta}G^{1,\mathbf{f}}(x)\Big)
		\bigg(
		\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
		\Big(\partial_{z_\eta}\partial_{z^\eta}G^{1,\mathbf{f}}(z)\Big)
		+1\bigg)=0
		.
	\end{align*}
	Thus, only the third part of \eqref{33-r-7} is of interest. Let us rewrite it in more explicit equivalent terms, taking into account factorization after shifting the variable $x\to x+y$
	\begin{equation*}
		4\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2x\,
		\big(\partial_{x^\mu}\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2z\,
		G^{\Lambda,\mathbf{f}}(x-z)\partial_{z_\rho}G^{\Lambda,\mathbf{f}}(z)\bigg)
		\Big(\partial_{x_\nu}\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x)\Big)
		\bigg(\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(y)B_\rho^{bc}(y)v_2^{ac}(y)\bigg).
	\end{equation*}
	Next, integrating by parts, using spherical averaging, and again taking into account the size of the function support $\partial_{x_\nu}\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x)$, we obtain
	\begin{equation*}
		2\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,
		\bigg(\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2z\,
		G^{\Lambda,\mathbf{f}}(x-z)\partial_{z_\rho}\partial_{z^\rho}G^{\Lambda,\mathbf{f}}(z)\bigg)
		\Big(\partial_{x_\nu}\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x)\Big)
		\bigg(\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(y)B_\mu^{bc}(y)v_2^{ac}(y)\bigg).
	\end{equation*}
	Then, by scaling $x\to x/\Lambda$ and $z\to z/\Lambda$ and using the representation from \eqref{33-o-55}, we arrive at the formula
	\begin{equation*}
		\frac{\ln(\Lambda/\sigma)}{\pi}
		\bigg(\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,\partial_{z_\rho}\partial_{z^\rho}G^{1,\mathbf{f}}(z)\bigg)^2
		\bigg(\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(y)B_\mu^{bc}(y)v_2^{ac}(y)\bigg),
	\end{equation*}
hence the stated statement. Similarly, the validity of the second relation \eqref{33-r-9} can be shown. The equality \eqref{33-r-10} is the sum of the previous two. To conclude the proof, we add that in the left hand sides the operator $\partial_{x_\nu}D_\nu^{ad}(x)$ can be replaced by $-2A^{ad}(x)$ from \eqref{33-o-3} or by $D_\nu^{ad}(x)\partial_{x_\nu}$ by adding a term proportional to $-\partial_{x^\nu}B_\nu^{ad}(x)$. Such addition does not lead to additional singularities, since the auxiliary integral is convergent.
\end{proof}

\begin{lemma}\label{33-lem-5} Let $v_1^{ab}(\cdot)$ and $v_2^{ab}(\cdot)$ be matrix-valued doubly continuously differentiable functions on $\mathbb{R}^2$, decreasing well enough at infinity (such that the integrals below converge). Additionally, we require that the second partial derivatives have the Hölder exponent $\alpha>0$, see \cite{He-1}. Then, taking into account the explicit form of regularization \eqref{33-o-55}, the following asymptotic expansions are valid for large values of the regularizing parameter $\Lambda$
	\begin{multline}\label{33-r-11}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(x)
		\Big(A^{cg}(y)G_\Lambda^{bg}(x,y)\Big)
		\Big(A^{ad}(x)G_\Lambda^{de}(x,y)\Big)
		v_2^{ec}(y)
		\stackrel{\mathrm{s.p.}}{=}\\\stackrel{\mathrm{s.p.}}{=}\Lambda^2
		\bigg(\int_{\mathbb{R}^2}\mathrm{d}^2x\Big(A_0(x)G^{1,\mathbf{f}}(x)\Big)^2\bigg)
		\int_{\mathbb{R}^2}\mathrm{d}^2y\,
		v_1^{ab}(y)
		v_2^{ab}(y)+\mathcal{O}(1).
	\end{multline}
\end{lemma}
\begin{proof} Let us introduce a convenient representation\footnote{It follows from formula \eqref{33-o-5}. It is possible to check by substitution.} for the Green's function of the form
	\begin{equation*}
		G_\Lambda^{de}(x,y)=2G^{\Lambda,\mathbf{f}}(x-y)\delta^{de}-
		\int_{\mathbb{R}^2}\mathrm{d}^2z\,\rho_1(x-z)V^{df}(z)G_\Lambda^{fe}(z,y)+
		\int_{\mathbb{R}^2}\mathrm{d}^2z\,\frac{\ln(|x-z|\sigma)}{2\pi}V^{df}(z)G_\Lambda^{fe}(z,y),
	\end{equation*}
	where
	\begin{equation*}
		\rho_1(x)=G^{\Lambda,\mathbf{f}}(x)+\frac{\ln(|x|\sigma)}{2\pi}.
	\end{equation*}
	Note that the support of $\rho_1(x)$ is located in the ball $\mathrm{B}_{1/\Lambda}$, and the function itself has a continuous first derivative in $\mathbb{R}^2\setminus\{0\}$. Next, we apply the operator $A^{ad}(x)=A_0(x)\delta^{ad}/2+V^{ad}(x)/2$ to the new representation, then we get
	\begin{equation*}
		A^{ad}(x)G_\Lambda^{de}(x,y)=A_0(x)G^{\Lambda,\mathbf{f}}(x-y)\delta^{ae}+\rho_2^{ae}(x,y).
	\end{equation*}
	where
	\begin{equation*}
		\rho_2^{ae}(x,y)=-\frac{1}{2}
		\int_{\mathbb{R}^2}\mathrm{d}^2z\,\Big(A_0(x)\rho_1(x-z)\Big)V^{af}(z)G_\Lambda^{fe}(z,y).
	\end{equation*}
	Let us show that the combinations
	\begin{equation}\label{33-r-12}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(x)
		\Big(\rho_2^{cb}(y,x)\Big)
		\Big(\rho_2^{ae}(x,y)\Big)
		v_2^{ec}(y),
	\end{equation}
	\begin{equation}\label{33-r-13}
		\int_{\mathbb{R}^2}\mathrm{d}^2x\int_{\mathbb{R}^2}\mathrm{d}^2y\,v_1^{ab}(x)
		\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x-y)\Big)
		\Big(\rho_2^{ae}(x,y)\Big)v_2^{eb}(y),
	\end{equation}
	do not contain singular contributions. To prove this fact, it is easiest to use the perturbative decomposition again and consider the most singular contribution. In the first case, there is only one. After shifting the variable and factoring, the interesting part of the integral can be represented as
	\begin{equation*}
		\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2x
		\bigg(\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2z\,A_0(x)\rho_1(x-z)\partial_{z^\mu}G^{\Lambda,\mathbf{f}}(z)\bigg)
		\bigg(\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2y\,A_0(x)\rho_1(x-y)\partial_{y^\nu}G^{\Lambda,\mathbf{f}}(y)\bigg).
	\end{equation*}
	After integration by parts, as well as using spherical symmetry and constraints on the support, we obtain 
	\begin{equation*}
		\frac{\delta_{\mu\nu}}{2}\int_{\mathrm{B}_{2/\Lambda}}\mathrm{d}^2x
		\bigg(\int_{\mathrm{B}_{3/\Lambda}}\mathrm{d}^2z\,A_0(x)\rho_1(x-z)G^{\Lambda,\mathbf{f}}(z)\bigg)
		\bigg(\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2y\,A_0(x)\rho_1(x-y)A(y)G^{\Lambda,\mathbf{f}}(y)\bigg).
	\end{equation*}
	It is clear that the possible singular contribution is obtained after scaling the variables by substitution $G^{\Lambda,\mathbf{f}}(z)\to\ln(\Lambda/\sigma)/(2\pi)$ and is equal to
	\begin{equation*}
		\frac{\delta_{\mu\nu}\ln(\Lambda/\sigma)}{4\pi}\int_{\mathrm{B}_{2/\Lambda}}\mathrm{d}^2x
		\bigg(\int_{\mathrm{B}_{3/\Lambda}}\mathrm{d}^2z\,A_0(x)\rho_1(x-z)\bigg)
		\bigg(\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2y\,A_0(x)\rho_1(x-y)A(y)G^{\Lambda,\mathbf{f}}(y)\bigg).
	\end{equation*}
	The last integral is zero, since
	\begin{equation*}
		\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2z\,A_0(z)\rho_1(z)=0.
	\end{equation*}
	Thus, \eqref{33-r-12} does not contain singular contributions. Similar arguments are valid for the integral from \eqref{33-r-13}. Therefore, the main part of the asymptotic decomposition of the left side of \eqref{33-r-11} can be obtained by replacing $A^{ad}(x)G_\Lambda^{de}(x,y)$ and $A^{cg}(y)G_\Lambda^{bg}(x,y)$ by $A_0(x)G^{\Lambda,\mathbf{f}}(x-y)\delta^{ae}$ and $A_0(x)G^{\Lambda,\mathbf{f}}(x-y)\delta^{cg}$. This is what the stated statement follows from.
\end{proof}

\subsection{Integral estimates}
\label{33:sec:appl:3}
\noindent\textbf{The first integral.} Consider a value of the form
\begin{equation*}
	\mathrm{Q}_1=\int_{\mathrm{B}_1}\mathrm{d}^2x\int_{\mathrm{B}_1}\mathrm{d}^2y\int_{\mathrm{B}_1}\mathrm{d}^{2}z\,\Big(\partial_{x^{\mu}}\ln{|x-y|}\Big)\ln{|x-z|}\Big(\partial_{z^{\sigma}}\ln{|y-z|}\Big)\Big(\partial_{x^{\rho}}\ln{|x|}\Big)\ln{|z|}\Big(\partial_{y^{\nu}}\ln{|y|}\Big).
\end{equation*}
Let us define the auxiliary number
\begin{equation*}
	M_1=\max_{x,y\in\mathrm{B}_1}\bigg(
	\int_{\mathrm{B}_1}\mathrm{d}^{2}z\,\Big|\ln{|x-z|}\Big(\partial_{z^{\sigma}}\ln{|y-z|}\Big)\ln{|z|}\Big|\bigg)<+\infty.
\end{equation*}
Further, given the fact that $\big|\partial_{y^{\nu}}\ln{|y|}\big|\leqslant1/|y|$, the integral can be estimated from above by
\begin{equation*}
	\big|\mathrm{Q}_1\big|\leqslant M_1\int_{\mathrm{B}_1}\mathrm{d}^2x\int_{\mathrm{B}_1}\mathrm{d}^2y\,
	\frac{1}{|x|\cdot|x-y|\cdot|y|},
\end{equation*}
from which the finitness follows.\\

\noindent\textbf{The second integral.} Next, consider the value
\begin{equation*}
	\mathrm{Q}_2=\int_{\mathrm{B}_1}\mathrm{d}^2x\int_{\mathrm{B}_1}\mathrm{d}^2y\int_{\mathrm{B}_1}\mathrm{d}^{2}z\,\Big(\partial_{x^{\mu}}\ln{|x-y|}\Big)\ln{|x-z|}\Big(\partial_{z^{\sigma}}\ln{|y-z|}\Big)\Big(\partial_{x^{\rho}}\ln{|x|}\Big)\Big(\partial_{z^{\nu}}\ln{|z|}\Big)\ln{|y|}.
\end{equation*}
It is clear that its absolute value can be estimated by the integral
\begin{equation*}
|Q_2|\leqslant
\int_{\mathrm{B}_{1}}\mathrm{d}^2z\int_{\mathrm{B}_{1}}\mathrm{d}^2x\int_{\mathrm{B}_{1}}\mathrm{d}^2y\,\frac{|\ln|x-z||\cdot|\ln|y||}{|x|\cdot|z|\cdot|x-y|\cdot|y-z|}
\equiv Q_3.
\end{equation*}
Note that the integral function is invariant with respect to the replacement $x\longleftrightarrow z$, therefore, dividing the integration domain for the variable $x$
\begin{equation*}
\mathrm{B}_1=\mathrm{B}_{|z|}\cup\big(\mathrm{B}_1\setminus\mathrm{B}_{|z|}),
\end{equation*}
changing the order of integration in one of the terms
\begin{equation*}
\int_{\mathrm{B}_{1}}\mathrm{d}^2z\int_{\mathrm{B}_1\setminus\mathrm{B}_{|z|}}\mathrm{d}^2x
\longrightarrow
\int_{\mathrm{B}_{1}}\mathrm{d}^2x\int_{\mathrm{B}_{|x|}}\mathrm{d}^2z,
\end{equation*}
and in it, reassigning the variables $x\longleftrightarrow z$, we get the equality
\begin{equation*}
Q_3=2\int_{\mathrm{B}_{1}}\mathrm{d}^2z\int_{\mathrm{B}_{|z|}}\mathrm{d}^2x\int_{\mathrm{B}_{1}}\mathrm{d}^2y\,\frac{|\ln|x-z||\cdot|\ln|y||}{|x|\cdot|z|\cdot|x-y|\cdot|y-z|}.
\end{equation*}
Consider an auxiliary function of the form 
\begin{equation*}
\mathrm{I}(x,z)=\int_{\mathrm{B}_{1}}\mathrm{d}^2y\,\frac{|\ln|y||}{|x-y|\cdot|y-z|}.
\end{equation*}
Let $z\in\mathrm{B}_{1}$ and $x\in\mathrm{B}_{|z|}$, $M>1$, as well as $r(M,x)=|x|/M$. Then we can write out the relations 
\begin{align*}
\mathrm{I}(x,z)=& \int_{\mathrm{B}_{1}\setminus\mathrm{B}_{r(M,x)}}\mathrm{d}^2y\,(\ldots)
+\int_{\mathrm{B}_{r(M,x)}}\mathrm{d}^2y\,(\ldots)\\
\leqslant&
|\ln(r(M,x))|\int_{\mathrm{B}_{1}}\mathrm{d}^2y\,
\frac{1}{|x-y||y-z|}+\left(\frac{M}{M-1}\right)^{2}\frac{1}{|x|^{2}}\int_{\mathrm{B}_{r(M,x)}}\mathrm{d}^2y\,|\ln|y||.
\end{align*}
For the first integral in the expression above, an estimate can be obtained using Theorem 3 from paragraph $115$ (chapter IV) of the monograph \cite{smir}, while the second one is calculated explicitly. Thus, we come to an estimate of the form
\begin{equation*}
\mathrm{I}(x,z)\leqslant
A_1|\ln(r(M,x))|(1+|\ln|x-z||)+\frac{A_2}{(M-1)^{2}}(2|\ln(r(M,x))|+1),
\end{equation*}
where $A_1$ and $A_2$ are numbers independent of $M$. Finally, writing out the auxiliary integral in the form
\begin{equation*}
Q_3=2\int_{\mathrm{B}_{1}}\mathrm{d}^2z\int_{\mathrm{B}_{|z|}}\mathrm{d}^2x\,\frac{|\ln|x-z||}{|x|\cdot|z|}\,\mathrm{I}(x,z),
\end{equation*}
note that due to the logarithmic behavior of the function $\mathrm{I}(x,z)$, all integrals are convergent. Thus, the convergence of $Q_2$ is shown.

\subsection{Special relations}
\label{33:sec:sp}
\noindent\textbf{Property 1.} Let $G^{1,\mathbf{f}}(x)$ be a deformation of the free fundamental solution from \eqref{33-o-55-1}, as well as $x\in\mathrm{B}_1$, then the relation holds
\begin{equation}\label{33-sp-1}
z_1(x)=
\int_{\mathrm{B}_2}\mathrm{d}^2y\,\Big(G^{1,\mathbf{f}}(x+y)-G^{1,\mathbf{f}}(y)\Big)=-
\frac{|x|^2}{4}.
\end{equation}
Let us use addition and subtraction, then we can rewrite
\begin{equation}\label{33-sp-2}
z_1(x)=
\int_{\mathrm{B}_2}\mathrm{d}^2y\,\Big(G^{1,\mathbf{f}}(x+y)-G(x+y)+G(x+y)-G^{1,\mathbf{f}}(y)\Big),
\end{equation}
where $G(x)=-\ln(|x|\sigma)/(2\pi)$. Next, note that the sum of the first two functions is constant at $x\in\mathrm{B}_1$. Indeed, the support of the difference $G^{1,\mathbf{f}}(\cdot)-G(\cdot)$ is contained in the ball $\mathrm{B}_1$, hence
\begin{equation}\label{33-sp-3}
\partial_{x_\mu}\int_{\mathrm{B}_2}\mathrm{d}^2y\,\Big(G^{1,\mathbf{f}}(x+y)-G(x+y)\Big)=
\int_{\partial\mathrm{B}_2}\mathrm{d}\sigma(y)\,\mathbf{n}^\mu(y)\Big(G^{1,\mathbf{f}}(x+y)-G(x+y)\Big)
=0,
\end{equation}
where $\mathrm{d}\sigma(y)$ is a standard measure on a sphere, and $\mathbf{n}^\mu(y)$ is the external normal to the boundary. Thus, choosing $x=0$ in the first two terms, we get
\begin{equation}\label{33-sp-4}
z_1(x)=
\int_{\mathrm{B}_2}\mathrm{d}^2y\,\Big(G(x+y)-G(y)\Big)=-\frac{1}{4}|x|^2,
\end{equation}
where the relation was used in the calculation, see \cite{Ivanov-2022}, 
\begin{equation}\label{33-sp-5}
\int_{\partial\mathrm{B}_1}\mathrm{d}\sigma(\hat{y})\,G(x+|y|\hat{y})=-\frac{1}{2\pi}
\begin{cases}
\ln(|y|\sigma),&|y|\geqslant|x|;\\
\ln(|x|\sigma),&|y|<|x|,
\end{cases}
=G^{1/|y|,\mathbf{0}}(x).
\end{equation}

\noindent\textbf{Property 2.} Let the function $G_1^\mu(\cdot)$ be defined by equality \eqref{33-r-21}, and the relation $x\in\mathrm{B}_1$ is also fulfilled, then the equality is true 
\begin{equation}\label{33-sp-6}
\Lambda G_1^\mu(x/\Lambda)=\frac{x^\mu \ln(\sigma\Lambda/\hat{\sigma})}{4\pi}-
\partial_{x_{\mu}}
\int_{\mathrm{B}_{2}}\mathrm{d}^2y\,
G^{1,\mathbf{f}}(x-y)
G^{1,\mathbf{f}}(y),
\end{equation}
where the second term is a correction to the first in the sense of expansion by the regularizing parameter $\Lambda$. To prove this, we use the definition, scaling of the variable, and integration by parts, then we get
\begin{align*}
\Lambda G_1^\mu(x/\Lambda)=&-
\Lambda\int_{\mathrm{B}_{1/\hat{\sigma}}}\mathrm{d}^2y\,
G^{\Lambda,\mathbf{f}}(x/\Lambda-y)
\partial_{y_{\mu}}G^{\Lambda,\mathbf{f}}(y)\\&-\partial_{x_{\mu}}
\int_{\mathrm{B}_{\Lambda/\hat{\sigma}}}\mathrm{d}^2y\,
\bigg(G^{1,\mathbf{f}}(x-y)+\frac{\ln(\Lambda)}{2\pi}\bigg)
\bigg(G^{1,\mathbf{f}}(y)+\frac{\ln(\sigma\Lambda/\hat{\sigma})}{2\pi}\bigg).
\end{align*}
Next, note that $\ln(\Lambda)/(2\pi)$ can be removed from the first multiplier, since in this case the differentiation of the constant will result. It is also important to note that the function
\begin{equation}\label{33-sp-8}
\partial_{x_{\mu}}
\int_{\mathrm{B}_{\Lambda/\hat{\sigma}}}\mathrm{d}^2y\,
G^{1,\mathbf{f}}(x-y)
G^{1,\mathbf{f}}(y)=
\partial_{x_{\mu}}
\int_{\mathrm{B}_{2}}\mathrm{d}^2y\,
G^{1,\mathbf{f}}(x-y)
G^{1,\mathbf{f}}(y)
\end{equation}
is finite due to the support of the averaged logarithm and, thus, falls into the correction term. The remaining part is instantly calculated using the first property from this section. Additionally, we note several auxiliary integrals in which only the main part of the asymptotics is used:
\begin{equation*}\label{33-sp-9}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)^2x_\nu 
G_1^\nu(x)=\frac{L\alpha_8(\mathbf{f})}{4\pi^2}+\mathcal{O}(1),
\end{equation*}
\begin{equation*}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)
G_1^\nu(x)\partial_{x^\nu}
\bigg(G^{\Lambda,\mathbf{f}}(x)-
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2y\,G^{\Lambda,\mathbf{f}}(x-y)A_0(y)G^{\Lambda,\mathbf{f}}(y)\bigg)
=\frac{L\alpha_9(\mathbf{f})}{4\pi^2}+\mathcal{O}(1),
\end{equation*}
\begin{equation*}
\int_{\mathrm{B}_{1/\sigma}}\mathrm{d}^2x\,\Big(\partial^\mu G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_\mu G_1^\nu(x)\Big)
\partial_{x^\nu}
\bigg(G^{\Lambda,\mathbf{f}}(x)-
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2y\,G^{\Lambda,\mathbf{f}}(x-y)A_0(y)G^{\Lambda,\mathbf{f}}(y)\bigg)
=-\frac{L\theta_2}{8\pi^2}+\mathcal{O}(1),
\end{equation*}
\begin{equation*}\label{33-sp-11}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(x_\nu\partial_{x_\mu}G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x^\mu}G_1^\nu(x)\Big)
=\frac{L\alpha_{11}(\mathbf{f})}{4\pi^2}+\mathcal{O}(1),
\end{equation*}
\begin{equation*}\label{33-sp-12}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x_\mu}G^{\Lambda,\mathbf{f}}(x)\Big)
G_1^\mu(x)
=\frac{L\alpha_{11}(\mathbf{f})}{4\pi^2}+\mathcal{O}(1).
\end{equation*}
As well as two integrals that use the correction term:
\begin{equation*}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x_\mu}G_1^\nu(x)\Big)\Big(\partial_{x^\mu}G_1^\nu(x)\Big)
=\frac{L_1^2+2L\theta_2}{8\pi^2}+\mathcal{O}(1),
\end{equation*}
\begin{equation*}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x_\mu}G_1^\mu(x)\Big)G^{\Lambda,\mathbf{f}}(x)
=\frac{L_1^2+L(\theta_2+\theta_1)}{4\pi^2}+\mathcal{O}(1).
\end{equation*}

\noindent\textbf{Property 3.} Let the function $G_2^{\nu\mu}(\cdot)$ be defined according to formula \eqref{33-r-23}. Let also $x\in\mathrm{B}_1$, then the relation is true
\begin{equation}\label{33-sp-13}
\Lambda^2G_2^{\mu\mu}(x/\Lambda)-\Lambda^2G_2^{\mu\mu}(0)=\frac{|x|^2L}{8\pi}+\mathcal{O}(1).
\end{equation}
To prove this, we use the definition and scaling of the integration variables, then we get
\begin{multline*}
\int_{\mathrm{B}_{\Lambda/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
\bigg(G^{1,\mathbf{f}}(y)+\frac{\ln(\Lambda)}{2\pi}\bigg)
\bigg(G^{1,\mathbf{f}}(y-z)+\frac{\ln(\Lambda)}{2\pi}\bigg)
A_0(z)G^{1,\mathbf{f}}(z)-\\
-\int_{\mathrm{B}_{\Lambda/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
\bigg(G^{1,\mathbf{f}}(x-y)+\frac{\ln(\Lambda)}{2\pi}\bigg)
\bigg(G^{1,\mathbf{f}}(y-z)+\frac{\ln(\Lambda)}{2\pi}\bigg)
A_0(z)G^{1,\mathbf{f}}(z).
\end{multline*}
It is clear that the terms with $\ln(\Lambda)/(2\pi)$, which follow from the first multiplier, are reduced. Then, using information about the behavior of the averaged logarithm, we can conclude that the integral
\begin{equation*}
\int_{\mathrm{B}_{\Lambda/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
G^{1,\mathbf{f}}(y)
G^{1,\mathbf{f}}(y-z)
A_0(z)G^{1,\mathbf{f}}(z)
-\int_{\mathrm{B}_{\Lambda/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
G^{1,\mathbf{f}}(x-y)
G^{1,\mathbf{f}}(y-z)
A_0(z)G^{1,\mathbf{f}}(z)
\end{equation*}
is a finite function and therefore falls into the correction $\mathcal{O}(1)$. The remaining part, taking into account the first property, leads to the stated answer
\begin{equation*}
\frac{L}{2\pi}\bigg(\int_{\mathrm{B}_{\Lambda/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
G^{1,\mathbf{f}}(y)
	A_0(z)G^{1,\mathbf{f}}(z)
	-\int_{\mathrm{B}_{\Lambda/\sigma}}\mathrm{d}^2y\int_{\mathrm{B}_{1}}\mathrm{d}^2z\,
G^{1,\mathbf{f}}(x-y)
	A_0(z)G^{1,\mathbf{f}}(z)\bigg)=\frac{|x|^2L}{8\pi}.
\end{equation*}
Here are two examples of applying properties that appear in calculations:
\begin{equation*}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)^2G_2^{\mu\mu}(x)=
L\bigg(
2\alpha_5(\mathbf{f})\alpha_6(\mathbf{f})+\frac{\alpha_8(\mathbf{f})}{8\pi^2}
\bigg)+\mathcal{O}(1),
\end{equation*}
\begin{equation*}
\int_{\mathrm{B}_{1/\Lambda}}\mathrm{d}^2x\,\Big(A_0(x)G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x_\nu}G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x^\nu}G_2^{\mu\mu}(x)\Big)=
\frac{L\alpha_{11}(\mathbf{f})}{4\pi^2}+\mathcal{O}(1).
\end{equation*}
\noindent\textbf{Property 4.} Taking into account the definitions from \eqref{33-9-24-53} and \eqref{33-9-24-55} for two functionals, the following equalities are true
\begin{equation*}
\alpha_9(\mathbf{f})=0,\,\,\,\alpha_{11}(\mathbf{f})=-\frac{1}{4}.
\end{equation*}
To prove this, let us first consider the second integral
\begin{equation*}
\alpha_{11}(\mathbf{f})=\pi\int_{\mathbb{R}^2}\mathrm{d}^2x\,\Big(A_0(x)G^{1,\mathbf{f}}(x)\Big)
x^\nu\partial_{x^\nu}G^{1,\mathbf{f}}(x).
\end{equation*}
Note that the functions depend on the absolute value of the argument. Therefore, the operators can be rewritten in the polar coordinates
\begin{equation*}
A_0(x)=-r^{-1}\partial_rr\partial_r,\,\,\,x^\nu\partial_{x^\nu}=r\partial_r,
\end{equation*}
where $r=|x|$. Then, substituting and integrating by parts, we obtain the following chain of equalities
\begin{equation*}
\alpha_{11}(\mathbf{f})=-2\pi^2\int_{0}^{+\infty}\mathrm{d}r\,\Big(\partial_rr\partial_rG^{1,\mathbf{f}}(x)\Big)
r\partial_rG^{1,\mathbf{f}}(x)=-\pi^2\Big(r\partial_rG^{1,\mathbf{f}}(x)\Big)^2\Big|_{r\to+\infty}
=-\frac{1}{4}.
\end{equation*}
Next, note that the functional $\alpha_{11}(\mathbf{f})$ is part of $\alpha_{9}(\mathbf{f})$, so it is enough to calculate only the second part
\begin{equation*}
\alpha_{9}(\mathbf{f})-\alpha_{11}(\mathbf{f})=
-\pi\int_{\mathbb{R}^2}\mathrm{d}^2x\,\Big(A_0(x)G^{1,\mathbf{f}}(x)\Big)
x^\nu\partial_{x^\nu}z_2(x),
\end{equation*}
where the auxiliary function has the form
\begin{equation*}
z_2(x)=\int_{\mathrm{B}_1}\mathrm{d}^2y\,G^{1,\mathbf{f}}(x-y)\Big(A_0(y)G^{1,\mathbf{f}}(y)\Big).
\end{equation*}
First of all, we note that the function $z_2(x)$ depends on the absolute value of $|x|$, therefore, the differential operators can be rewritten in polar coordinates without the angular part. Next, we integrate it again by parts, then we get
\begin{equation*}
\alpha_{9}(\mathbf{f})-\alpha_{11}(\mathbf{f})=\pi^2\Big(r\partial_rG^{1,\mathbf{f}}(x)\Big)\Big(r\partial_rz_2(x)\Big)\Big|_{r\to+\infty}=\frac{1}{4},
\end{equation*}
where the relations were used
\begin{equation*}
z_2(x)=\int_{\mathrm{B}_1}\mathrm{d}^2y\,G^{1,\mathbf{f}}(x-y)\Big(A_0(y)G^{1,\mathbf{f}}(y)\Big)=
-\frac{\ln(|x|\sigma)}{2\pi}\int_{\mathrm{B}_1}\mathrm{d}^2y\,A_0(y)G^{1,\mathbf{f}}(y)=G^{1,\mathbf{f}}(x)
\end{equation*}
for $|x|>2$, as well as
\begin{equation*}
-2\pi^2\int_{0}^{+\infty}\mathrm{d}r\,\Big(r\partial_rG^{1,\mathbf{f}}(x)\Big)
\partial_rr\partial_rz_2(x)=
\pi\int_{\mathbb{R}^2}\mathrm{d}^2x\,\Big(x^\nu\partial_{x^\nu}G^{1,\mathbf{f}}(x)\Big)
A_0(x)z_2(x)=-\alpha_{9}(\mathbf{f})+\alpha_{11}(\mathbf{f}).
\end{equation*}
Finally, from the equality $\alpha_{9}(\mathbf{f})-\alpha_{11}(\mathbf{f})=1/4$ we obtain $\alpha_{9}(\mathbf{f})=0$.\\

\noindent\textbf{Property 5.} In addition, we consider another auxiliary integral, the asymptotics of which must be calculated using a less trivial method. It has the form
\begin{equation*}
\int_{\mathrm{B}_{1/\sigma_1}}\mathrm{d}^2x\,
\Big(\partial_{x_\nu}G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x)\Big)
\partial_{x^\mu}G_1^\mu(x)=
\frac{L_1^2}{8\pi^2}+\mathcal{O}(1).
\end{equation*}
Let us show its calculation. We make a few comments. First, the singular part of the asymptotics does not depend on which final value of $\sigma_1>0$ will be fixed. For further information, it is convenient to choose $1/\sigma_1=1/\hat{\sigma}-1/\Lambda$. Secondly, the application of the second property for the function $\partial_{x^\mu}G_1^\mu(x)$ is impossible, since it was derived with a variable restriction. Therefore, we need to use the definition from \eqref{33-r-21} followed by integration by parts. Then, after scaling the variables, the integral takes the form
\begin{equation*}
\int_{\mathrm{B}_{\Lambda/\hat{\sigma}-1}}\mathrm{d}^2x\,
\Big(\partial_{x_\nu}G^{1,\mathbf{f}}(x)\Big)
\Big(\partial_{x^\nu}G^{1,\mathbf{f}}(x)\Big)
\bigg(
\frac{\ln(\sigma\Lambda/\hat{\sigma})}{2\pi}+
\int_{x+\mathrm{B}_1}\mathrm{d}^2y\,
A_0(x)G^{1,\mathbf{f}}(x-y)
G^{1,\mathbf{f}}(y)
\bigg).
\end{equation*}
The convenient choice of $\sigma_1$ led to the possibility of making a shift of $y\to y+x$ by centering the multiplier with the Laplace operator. Breaking it down into terms, we get
\begin{multline*}
\frac{\ln(\sigma\Lambda/\hat{\sigma})}{2\pi}
\bigg(\int_{\mathrm{B}_{1}}\mathrm{d}^2x\,
\Big(\partial_{x_\nu}G^{1,\mathbf{f}}(x)\Big)
\Big(\partial_{x^\nu}G^{1,\mathbf{f}}(x)\Big)
+\frac{\ln(\Lambda/\hat{\sigma}-1)}{2\pi}\bigg)
+\\+
\int_{\mathrm{B}_{\Lambda/\hat{\sigma}-1}}\mathrm{d}^2x\,
\Big(\partial_{x_\nu}G^{\Lambda,\mathbf{f}}(x)\Big)
\Big(\partial_{x^\nu}G^{\Lambda,\mathbf{f}}(x)\Big)
\int_{\mathrm{B}_1}\mathrm{d}^2y\,
G^{1,\mathbf{f}}(x-y)
A_0(y)G^{1,\mathbf{f}}(y).
\end{multline*}
Next, we note that it is possible to make a substitution in the last integral
\begin{equation*}
\int_{\mathrm{B}_1}\mathrm{d}^2y\,
G^{1,\mathbf{f}}(x-y)
A_0(y)G^{1,\mathbf{f}}(y)\longrightarrow G^{1,\mathbf{f}}(x),
\end{equation*}
since the support of their difference is contained in $\mathrm{B}_2$. In addition, the integral in the first term can be calculated explicitly
\begin{equation*}
\int_{\mathrm{B}_{1}}\mathrm{d}^2x\,
\Big(\partial_{x_\nu}G^{1,\mathbf{f}}(x)\Big)
\Big(\partial_{x^\nu}G^{1,\mathbf{f}}(x)\Big)=
\int_{\mathrm{B}_{1}}\mathrm{d}^2x\,
\Big(A_0(x)G^{1,\mathbf{f}}(x)\Big)G^{1,\mathbf{f}}(x)\big|_{\sigma=1}=\frac{\theta_1+\mathbf{f}(0)/2}{2\pi}.
\end{equation*}
Then the original integral, after removing some finite parts, is rewritten as
\begin{equation*}
\frac{\ln(\sigma\Lambda/\hat{\sigma})}{4\pi^2}
\big(\theta_1+\mathbf{f}(0)/2+\ln(\Lambda/\hat{\sigma})\big)
+\frac{1}{4}\bigg(\mathrm{I}_1(\Lambda,\hat{\sigma})-\frac{\ln(\sigma\Lambda/\hat{\sigma})}{\pi^2}\big(\theta_1+\mathbf{f}(0)/2+\ln(\Lambda/\hat{\sigma})\big)\bigg),
\end{equation*}
where the definition from \eqref{33-w-7} was used. Remembering that $\theta_1=-\ln(\sigma/\hat{\sigma})$, we obtain
\begin{equation*}
\frac{(L_1+\ln(\sigma/\hat{\sigma}))^2+2L\theta_1}{8\pi^2},
\end{equation*}
from which final answer follows.











