We now define an optimal pricing rule $p^{\star}$ for general distributions conditioning on different realizations of $c$. When $c \in C_1$, let $p^\star$ be defined in \eqref{eq:p-star}. When $c \in C_2$, since $F_{c,l}(c) \geq \Delta_c(v^\star_c)$, there exists a unique value $\eta_c^l \leq c$ such that $F_{c,l}(c)-F_{c,l}(\eta_c^l)=\Delta_c(v^\star_c)$. Let $\eta_c^h:=F_{c,h}^{-1}(F_{c,l}(\eta_c^l))$. The pricing rule $p^{\star}$, when $c \in C_2$, is defined as follows:
\begin{align*}
p^{\star}(v,c,l,r)&:=\begin{cases}
c,&\mbox{if } v < \eta_c^l\\
\overline{\Delta}_c^{-1}(\Delta_c(v^\star_c)+F_{c,l}(\eta_c^l)-F_{c,l}(v)),&\mbox{if }v \in [\eta_c^l,c)  \\
v,&\mbox{if } v \geq c
\end{cases}\\
p^\star(v,c,h,r)&:=\begin{cases}
c,&\mbox{if } v<\eta_h\\
\underline{\Delta}_c^{-1}(F_{c,h}(v)-F_{c,h}(\eta_c^h)+\Delta_c(c)),&\mbox{if } v \in [\eta_c^h,c)\\
v,&\mbox{if } v \geq c
\end{cases}
\end{align*}
\bref{figure2} depicts the optimal pricing rule $p^{\star}$ when $c \in C_2$. 




When $c \in C_3$, the pricing rule $p^\star$ is defined as follows: 
\begin{align*}
p^\star(v,c,l,r)&:=\begin{cases}
c,&\mbox{if } v<F_{c,l}^{-1}(F_{c,h}(c))\\
\ub{\Delta}_c^{-1}(\Delta_c(c)+F_{c,h}(c)-F_{c,l}(v)),&\mbox{if } v \in [F_{c,l}^{-1}(F_{c,h}(c)),c)\\
v,&\mbox{if } v \geq c
\end{cases}\\
p^\star(v,c,h,r)&:= \max\{v,c\}
\end{align*}
\bref{figure3} depicts the optimal pricing rule $p^\star$ when $c \in C_3$. 




\bref{thm2} below establishes that $p^\star$ is an optimal non-discriminatory pricing rule. 

\begin{theorem}[Optimal Pricing for General Distributions]\label{thm2}$ $
\begin{compactenum}[(i)]
\item $p^\star$ is a profit-maximizing non-discriminatory pricing rule, that is, $p^\star$ solves \eqref{eq:optimal-pricing}. 
\item Every undominated profit-maximizing non-discriminatory pricing rule induces the same average surplus $CS(\theta,c;p^\star)$ for consumer of each protected characteristic $\theta$ and cost $c$.
\end{compactenum}
\end{theorem}








We note that \bref{thm2} immediately implies \bref{thm1}, since $c \in C_1$ almost surely under \bref{ass:no-full-surplus-extraction}. As another immediate consequence of \bref{thm2}, under the optimal pricing rule $p^\star$, the seller is able to fully extract all gains from trade whenever $c \in C_2\cup C_3$. 

\begin{corollary}\label{cor:full-surplus-extraction}
For all $\tilde{c} \in C_2 \cup C_3$, 
\[
\EE[(p^\star-c)\mathbf{1}\{v \geq p^\star\}\mid c=\tilde{c}]=\EE[(v-c)^+\mid c=\tilde{c}]\,.
\]
As a result, 
\[
CS(c,\theta;p^\star)=WL(c,\theta;p^\star)=0\,,
\]
for all $c \in C_2\cup C_3$ and $\theta \in \{l,h\}$.
\end{corollary}

According to \bref{cor:full-surplus-extraction}, the restrictions on the value distributions imposed by \bref{ass:no-full-surplus-extraction} are in fact equivalent to restricting attention to distributions where the seller cannot fully extract all gains from trade. 


\section{A Proof Sketch for Theorem \ref{thm1} and Theorem \ref{thm2}}\label{sec:4.3}

In this section, we outline the main steps of the proof for \bref{thm1} and \bref{thm2}. Details of the proof can be found in the appendix. From \bref{prop:opt-transport}, optimal pricing rules can be identified by solving the optimal transport problem  
\begin{equation}\label{eq:transport-point}
\pi^\star(c):=\max_{\rho \in \mathcal{R}_c} \int_{V^2} \pi_c(v_l,v_h) \diff \rho_c\,,
\end{equation}
for each cost $c \in C$. We solve \eqref{eq:transport-point} by a duality argument. The dual problem corresponding to \eqref{eq:transport-point} is given by 
\begin{align}\label{eq:dual}
\pi_\star(c):=\inf_{\phi_c,\psi_c} &\left[\int_V \phi_c(v_l)  F_{c,l}(\diff v_l)+\int_V \psi_c(v_h) F_{c,h}(\diff v_h)\right] \notag\\
\mbox{s.t. }& \phi_c(v_l)+\psi_c(v_h) \geq \pi_c(v_l,v_h)\,,
\end{align}
where the infimum is taken over all measurable functions $\phi_c,\psi_c:V \to \RR$. Since $\pi_c$ is continuous, the Kantorovich duality theorem holds \citep[see, e.g.,][Theorem 5.10]{V09}.

\begin{lemma}[Kantorovich Duality]\label{lem:dual}
$\pi_\star(c)=\pi^\star(c)$ for all $c \in C$. Moreover, for any $c \in C$, for any measurable $\phi_c,\psi_c$ such that $\phi_c(v_l)+\psi_c(v_h) \geq \pi_c(v_l,v_h)$ for all $(v_l,v_h) \in V \times V$, and for any $\rho_c \in \mathcal{R}_c$, $\rho_c$ is a solution of \eqref{eq:transport-point} and $\phi_c,\psi_c$ is a solution of \eqref{eq:dual} if and only if 
\begin{equation}\label{eq:cs}
\phi_c(v_l)+\psi_c(v_h)=\pi_c(v_l,v_h)
\end{equation}
for all $(v_l,v_h) \in \supp(\rho_c)$. 
\end{lemma}

Therefore, to solve \eqref{eq:transport-point}, it suffices to find, for each $c \in C$, a joint distribution $\rho_c^\star \in \mathcal{R}_c$ and a pair of functions $\phi_c^\star$ and $\psi_c^\star$ such that $(\phi_c^\star,\psi_c^\star)$ is feasible in the dual problem \eqref{eq:dual} and that the complementary slackness condition holds: $\psi_c^\star(v_l)+\psi_c^\star(v_h)=\pi_c(v_l,v_h)$ for all $(v_l,v_h) \in \supp(\rho_c^\star)$. In the appendix, we construct explicitly the optimal dual variables $(\phi^\star_c,\psi^\star_c)$. \bref{fig:dual} illustrates the functions $\phi_c^\star$ and $\psi_c^\star$ when $\alpha_c=\nicefrac{1}{2}$ and $c=0$. 

