\subsection{Proof of Main Results}
\begin{proof}[Proof of \bref{lem:lem1}]
Consider any non-discriminatory pricing rule $p$. By definition, $p$ is independent of $\theta$ conditional on $c$. Therefore, for any $\tilde{c} \in C$ and for any $z \subseteq V$, 
\begin{align*}
\rho_{\tilde{c}}([0,z] \times V)=&\EE[\PP[v \in [0,z] \mid p, c=\tilde{c},\theta=l] \times \PP[v \in V\mid p,\theta=h,c=\tilde{c}]\mid c=\tilde{c}]\\
=& \EE[\PP[v \in [0,z]\mid p,c=\tilde{c},\theta=l]\mid c=\tilde{c}]\\
=& \EE[\PP[v \in [0,z]\mid c=\tilde{c},\theta=l]]\\
=&F_{\tilde{c},l}(z)\,.
\end{align*}
Likewise, 
\begin{align*}
\rho_{\tilde{c}}(V \times [0,z])=&\EE[\PP[v \in V \mid p, c=\tilde{c},\theta=l] \times \PP[v \in [0,z]\mid p,\theta=h,c=\tilde{c}]\mid c=\tilde{c}]\\
=& \EE[\PP[v \in [0,z]\mid p,c=\tilde{c},\theta=h]\mid c=\tilde{c}]\\
=& \EE[\PP[v \in [0,z]\mid c=\tilde{c},\theta=h]]\\
=&F_{\tilde{c},h}(z)\,.
\end{align*}
Therefore, the marginals of $\rho_c$ equals $F_{c,l}$ and $F_{c,h}$ for all $c \in C$, as desired. 
\end{proof}




\begin{proof}[Proof of \bref{prop:opt-transport}]
Consider any non-discriminatory pricing rule $p$, for each $c \in C$, let $\rho_c$ be defined by \eqref{eq:match}. We first claim that 
\[
\Pi(p) \leq \int_C \left(\int_{V^2} \pi_c(v_l,v_h) \rho_c(\diff v_l,\diff v_h)\right) G(\diff c)\,.
\]
Indeed, note that, for all $\hat{c} \in C$, by the definition of $\pi_{\hat{c}}$,
\[
    \int_{V^2} \pi_{\hat{c}} (v_l,v_h) \rho_{\hat{c}}(\diff v_l,v_h) = \int_{V^2} \max_{\tilde{p}} (\tilde{p}-\hat{c})\left[ (1-\alpha_{\hat{c}}) \mathbf{1}\{v_l \geq \tilde{p}\} + \alpha_{\hat{c}} \mathbf{1}\{v_h \geq \tilde{p}\} \right]  \rho_{\hat{c}}(\diff v_l,\diff v_h)\,.
\]
By the definition of $\rho_{\hat{c}}$, for all $\hat{c} \in C$, we have
\begin{equation}\label{eq:upperbound}
\begin{aligned}
    &\int_{V^2} \max_{\tilde{p}} (\tilde{p}-\hat{c})\left[ (1-\alpha_{\hat{c}}) \mathbf{1}\{v_l \geq \tilde{p}\} + \alpha_{\hat{c}} \mathbf{1}\{v_h \geq \tilde{p}\} \right]  \rho_{\hat{c}}(\diff v_l,\diff v_h)\\
    =&\E{ \max_{\tilde{p}} \E{(\tilde{p}-c) (1-\alpha_c) \mathbf{1}\{v \geq \tilde{p}\} }{ p, \theta=l, c = \hat{c} } \times \E{(\tilde{p}-c) \alpha_c \mathbf{1}\{v \geq \tilde{p}\}}{p, \theta= h,  c = \hat{c} } }{c = \hat{c}}\\
    =&\E{ \max_{\tilde{p}} \E{(\tilde{p}-c) \mathbf{1}\{v \geq \tilde{p}\} }{ p, c = \hat{c} } }{c = \hat{c}}\\
    \geq& \E{ \E{({p}-c) \mathbf{1}\{v \geq {p}\} }{ p, c = \tilde{c} } }{c = \hat{c}} \\
    =& \E{ ({p}-c) \mathbf{1}\{v \geq {p}\}  }{c = \hat{c}}\,.
\end{aligned}
\end{equation}
Therefore, 
\[
\Pi(p)=\EE[(p-c)\mathbf{1}\{v \geq p\}] \leq \int_{C}\left(\int_{V^2} \pi_c(v_l,v_h) \rho_c(\diff v_l,\diff v_h)\right)G(\diff c)\,,
\]
as desired. 

Next, we show that 
\[
\sup_{p \in \mathcal{D}} \Pi(p) \geq \int_C\left(\int_{V^2}\max_{\rho_c \in \mathcal{R}_c} \pi_c(v_l,v_h) \rho_c(\diff v_l,\diff v_h)\right)G(\diff c)\,.
\]
To this end, we show that any $\{\rho_c\}_{c\in C}$ such that $\rho_c \in \mathcal{R}_c$ for all $c \in C$, we can construct a non-discriminatory pricing rule $p$ such that 
\[
\Pi(p)=\int_C \left(\int_{V^2} \pi_c(v_l,v_h) \rho_c(\diff v_l,\diff v_h)\right)G(\diff c)\,.
\]
Indeed, consider any $\{\rho_c\}_{c \in C}$ such that $\rho_c \in \mathcal{R}_c$ for all $c \in C$. Since $V \subseteq \RR_+$ is a standard Borel space, by the disintegration theorem \citep[see, e.g.,][Theorem 2.17, pp. 151]{cinlarprobability2010}, for each $c \in C$, there exists transition probabilities $\gamma_{c,l}:V \to \Delta(V)$ and $\gamma_{c,h}:V \to \Delta(V)$ such that for all measurable $V_l,V_h \subseteq V$
\begin{equation}\label{eq:kernel}
\int_{V_h} \gamma_{c,l}(V_l\mid v_h) F_{c,h}(\diff v_h)=\rho_c(V_l \times V_h)=\int_{V_l} \gamma_{c,h}(V_h\mid v_l)F_{c,l}(\diff v_l)\,.
\end{equation}
Let $\Gamma_{c,\theta}(\cdot\mid v)$ be the CDF associated with $\gamma_{c,\theta}(\cdot\mid v)$, for all $v \in V$, $c \in C$ and $\theta \in \{l,h\}$. 
In the meantime, let $\xi_c:V^2 \to \RR_+$ be a measurable selection of 
\[
\argmax_{\tilde{p} \geq 0} (\tilde{p}-c)(\alpha_c \mathbf{1}\{v_h \geq \tilde{p}\}+(1-\alpha_c) \mathbf{1}\{v_l \geq \tilde{p}\})\,.
\]
Then, let 
\begin{equation}\label{eq:price}
p(v,c,\theta,r):=\begin{cases}
\xi_c(v,\Gamma^{-1}_{c,h}(r\mid v)),&\mbox{if } \theta=l\\
\xi_c(\Gamma^{-1}_{c,l}(r\mid v),v),&\mbox{if } \theta=h
\end{cases}\,,
\end{equation}
for all $(v,c,\theta,r) \in \Omega$. By construction, 
\begin{equation}\label{eq:lowerbound}
\begin{aligned}
\Pi(p)=&\EE[(p-c)\mathbf{1}\{v \geq p\}]\\
=&\EE[\EE[\EE[(p-c)\mathbf{1}\{v \geq p\}\mid c,\theta]\mid c]]\\
=&\int_C \bigg(\alpha_c \int_{V \times [0,1]} (\xi_c(\Gamma_{c,l}^{-1}(r\mid v_h),v_h)-c)\mathbf{1}\{ v_h\geq \xi_c(\Gamma_{c,l}^{-1}(r\mid v_h),v_h)\}\diff rF_{c,h}(\diff v_h)\\
&+(1-\alpha_c) \int_{V \times [0,1]} (\xi_c(v_l,\Gamma_{c,h}^{-1}(r\mid v_l))-c)\mathbf{1}\{v_l \geq \xi_c(v,\Gamma_{c,h}^{-1}(r\mid v_l))\}\diff rF_{c,l}(\diff v_l) \bigg)G(\diff c)\\
=& \int_C \bigg(\alpha_c \int_{V^2} (\xi_c(v_l,v_h)-c)\mathbf{1}\{v_h \geq \xi_c(v_l,v_h)\}\Gamma_{c,l}(\diff v_l\mid v_h)F_{c,h}(\diff v_h)\\
&+(1-\alpha_c)\int_{V^2}(\xi_c(v_l,v_h)-c)\mathbf{1}\{v_l \geq \xi_c(v_l,v_h)\}\Gamma_{c,h}(\diff v_h\mid v_l)F_{c,l}(\diff v_l)\bigg)G(\diff c)\\
=&\int_C \left(\int_{V^2} (\xi_c(v_l,v_h)-c)(\alpha_c\mathbf{1}\{v_h \geq \xi_c(v_l,v_h)+(1-\alpha_c)\mathbf{1}\{v_l \geq \xi_c(v_l,v_h)\})\rho_c(\diff v_l,\diff v_h)\right)G(\diff c)\\
=&\int_C\left(\int_{V^2}\pi_c(v_l,v_h)\rho_c(\diff v_l,\diff v_h)\right)G(\diff c)\,,
\end{aligned}
\end{equation}
where the second equality follows from the law of iterated expectation, the fourth equality follows from changing variables of the integration, the fifth equality follows from \eqref{eq:kernel}, and the last equality follows from the definition of $\xi_c$. 

Moreover, for any $c \in C$ and for any measurable $M \subseteq V$, 
\begin{align*}
\PP[p \in M\mid c,\theta=l]=&\PP[\xi_c(v,\Gamma_{c,h}^{-1}(r\mid v)) \in M\mid c, \theta=l]\\
=&\int_{V \times [0,1]} \mathbf{1}\{\xi_c(v_l,\Gamma_{c,h}^{-1}(r\mid v_l))\in M\}\diff r \diff F_{c,l}(\diff v_l)\\
=&\int_{V^2} \mathbf{1}\{\xi_c(v_l,v_h) \in M\} \Gamma_{c,h}(\diff v_h\mid v_l)F_{c,l}(\diff v_l)\\
=&\int_{V^2} \mathbf{1}\{\xi_c(v_l,v_h) \in M\} \rho_c(\diff v_l,\diff v_h)\,,
\end{align*}
where the third equality again follows from changing variables of the integration, and the last equality follows from \eqref{eq:kernel}. Likewise, 
\begin{align*}
\PP[p \in M\mid c,\theta=h]=&\PP[\xi_c(\Gamma_{c,l}^{-1}(r\mid v),v) \in M\mid c, \theta=h]\\
=&\int_{V \times [0,1]} \mathbf{1}\{\xi_c(\Gamma_{c,l}^{-1}(r\mid v_h),v_h)\in M\}\diff r \diff F_{c,h}(\diff v_h)\\
=&\int_{V^2} \mathbf{1}\{\xi_c(v_l,v_h) \in M\} \Gamma_{c,l}(\diff v_l\mid v_h)F_{c,h}(\diff v_h)\\
=&\int_{V^2} \mathbf{1}\{\xi_c(v_l,v_h) \in M\} \rho_c(\diff v_l,\diff v_h)\,.
\end{align*}
As a result, for all $c \in C$, and for all measurable $M \subseteq [0,1]$,
\[
\PP[p \in M\mid c,\theta=l]=\int_{V^2} \mathbf{1}\{\xi_c(v_l,v_h) \in M\}\rho_c(\diff v_l, \diff v_h) =\PP[p \in M\mid c,\theta=h]\,,
\]
and thus $p$ is indeed non-discriminatory. 

Together, we have 
\begin{equation}\label{eq:prop1}
\sup_{p \in \mathcal{D}}\Pi(p)=\int_C\left(\max_{\rho_c \in \mathcal{R}_c}\int_{V^2} \pi_c(v_l,v_h)\rho_c(\diff v_l,\diff v_h)\right)\,.
\end{equation}
Furthermore, for any profit-maximizing non-discriminatory pricing rule $p$, let $\rho_c$ be defined by \eqref{eq:match}, \eqref{eq:upperbound} and \eqref{eq:prop1} then implies that $\{\rho_c\}_{c \in C}$ solves \eqref{eq:transport}. Conversely, for any $\{\rho_c\}_{c \in C}$ that solves \eqref{eq:transport}, let $p$ be defined by \eqref{eq:price}. Then $p$ solves \eqref{eq:optimal-pricing} by \eqref{eq:lowerbound} and \eqref{eq:prop1}. This completes the proof. 
\end{proof}

\begin{proof}[Proof of \bref{lem:system}]
Since $\Delta_c$ is continuous and quasi-concave, it has a unique maximizer. Let $v^\star_c$ be the unique maximizer of $\Delta_c$ for all $c \in C$. Since $F_{c,l}$ and $F_{c,h}$ are CDFs on $\RR_+$ that are absolutely continuous, $\Delta_c(0)=0$ and $\lim_{v \to\infty } \Delta_c(v)=0$, and 
\[
\|F_{c,l}-F_{c,h}\|=\max_{A \subseteq \RR_+} \bigg|\int_A [f_{c,l}(v)-f_{c,h}(v)] \diff v\bigg|=\max_v \Delta_c(v)=\Delta_c(v^\star_c)\,.
\]
Moreover, since $\Delta_c$ is continuous and quasi-concave, for any $v \geq v_c^\star$, there exists a unique $g_c(v) \in [\lb{v}_c, v_c^\star]$ such that $\Delta_c(v)=\Delta_c(g_c(v))$. Moreover, the function $g_c:[v_c^\star,\infty) \to [\lb{v}_c,v_c^\star]$ is continuous and decreasing in $v$, with $g_c(v_c^\star)=v_c^\star$ and $\lim_{v \to \infty } g_c(v)=\lb{v}_c$. For any $v \geq v_c^\star$, let 
\[
h_c(v):=v-g_c(v)\,.
\]
Note that $h_c$ is increasing on $[v_c^\star,\ub{v}_c]$ and $h_c(v_c^\star)=0$, $\lim_{v \to \infty} h_c(v)=\infty$. In particular, since $F_{c,l}(c)<\|F_{c,l}-F_{c,h}\|=\Delta_c(v^\star_c)$, and thus $c<v^\star_c$, there exists a unique $\tilde{v}_c>v^\star_c$ such that  $\alpha_c h_c(\tilde{v}_c) =(1-\alpha_c)(v_c^\star-c)$. Meanwhile let $\hat{v}_c:=\inf\{v \geq v^\star_c: \alpha_ch_c(v) \geq (1-\alpha_c)(\lb{v}_c-c)\}$. Since $h_c$ is nondecreasing, it must be that $\hat{v}_c \in[v^\star_c, \tilde{v}_c]$. 

Note that, if $\hat{v}_c=v^\star_c$, then it must be that 
\[
\Delta_c\left(\frac{\alpha_c}{1-\alpha_c}h_c(\hat{v}_c)+c\right)+F_{c,h}(\alpha_c h_c(\hat{v}_c)+c)=F_{c,l}(c)<\|F_{c,l}-F_{c,h}\|=\Delta_c(v^\star_c)=\Delta_c(\hat{v}_c)\,;
\]
If $\hat{v}_c \in (v^\star_c,\ub{v}_c)$, then it must be that $0\leq \alpha_ch_c(\hat{v}_c)=(1-\alpha_c)(\lb{v}_c-c)$, and thus $\alpha_ch_c(\hat{v}_c)+c=(1-\alpha_c)\lb{v}_c+\alpha_c c \leq \lb{v}_c$. Therefore, 
\[
\Delta_c\left(\frac{\alpha_c}{1-\alpha_c}h_c(\hat{v}_c)+c\right)+F_{c,h}(\alpha_c h_c(\hat{v}_c)+c)=0<\Delta_c(\hat{v}_c)\,.
\]
If $\hat{v}_c \geq \ub{v}_c$, then 
\[
\Delta_c\left(\frac{\alpha_c}{1-\alpha_c}h_c(\hat{v}_c)+c\right)+F_{c,h}(\alpha_c h_c(\hat{v}_c)+c)=0=\Delta_c(\hat{v}_c)\,.
\]
Since $\Delta_c$ is quasi-concave, and hence is decreasing on $[v^\star_c,\ub{v}_c]$ while $\Delta_c(v)=0$ for all $v \geq \ub{v}_c$. In the meantime, since $\alpha_ch_c(v)/(1-\alpha_c)+c \leq v^\star_c$ for all $v \in [v^\star_c,\tilde{v}_c]$ and since $h_c$ is increasing in $v$, the function 
\[
v \mapsto \Delta_c\left(\frac{\alpha_c}{1-\alpha_c}h_c(v)+c\right)+F_{c,h}(\alpha_c h_c(v)+c)
\]
is increasing on $[v_c^\star,\tilde{v}_c]$. Together, there exists a unique $\kappa_c^5 \in [\hat{v}_c,\tilde{v}_c]$ such that 
\begin{equation}\label{eq:fixedpoint}
\Delta_c(\kappa^5_c)=\Delta_c\left(\frac{\alpha_c}{1-\alpha_c} h_c(\kappa^5_c)+c\right)+F_{c,h}(\alpha_c h_c(\kappa^5_c)+c)\,,
\end{equation}
and that 
\[
\frac{\alpha_c}{1-\alpha_c} h_c(\kappa^5_c)\leq \frac{\alpha_c}{1-\alpha_c} h_c(\tilde{v}_c)=v_c^\star-c\,.
\]
Let $\kappa^4_c:=g_c(\kappa^5_c)$ and $\kappa^1_c:=\alpha_c h_c(\kappa^5_c)+c$, $\kappa^3_c:=\alpha_c h_c(\kappa_c^5)/(1-\alpha_c)+c$, and $\kappa_c^2:=F_{c,l}^{-1}(\Delta_c(\kappa^5_c))$. By construction, $\kappa_c^5 \geq \hat{v}_c \geq v^\star_c>\kappa_c^4$, with at least one of the first two inequalities being strict, and $\kappa_c^3 \geq \kappa_c^1$. Moreover, since $\kappa_c^3=\alpha_ch_c(\kappa_c^5)/(1-\alpha_c)+c \leq v^\star_c$ and since $\Delta_c(\kappa_c^3) \leq \Delta_c(\kappa_c^4)<\Delta_c(v^\star_c)$, $\kappa_c^3 \leq \kappa_c^4$. In the meantime, since $F_{c,l}(\kappa_c^2)=\Delta_c(\kappa_c^3)+F_{c,h}(\kappa_c^1)$, 
\[
F_{c,l}(\kappa_c^3)-F_{c,l}(\kappa_c^2)=F_{c,h}(\kappa_c^3)-F_{c,h}(\kappa_c^1) \geq 0\,,
\]
and hence $\kappa_c^2 \leq \kappa_c^3$. Lastly, since $\kappa_c^1 \leq \kappa_c^3 \leq v^\star_c$, it must be that $\Delta_c(\kappa_c^1)\leq \Delta_c(\kappa_c^3)$. Therefore, 
\[
F_{c,l}(\kappa_c^2)-F_{c,h}(\kappa_c^1)=\Delta_c(\kappa_c^3) \geq \Delta_c(\kappa_c^1)=F_{c,l}(\kappa_c^1)-F_{c,h}(\kappa_c^1)\,,
\]
 and hence $F_{c,l}(\kappa_c^2) \geq F_{c,l}(\kappa_c^1)$, which in turn implies $\kappa_c^2 \geq \kappa_c^1$. 

Together, it then follows that $\kappa^1_c\leq \kappa_c^2 \leq \kappa^3_c\leq \kappa^4_c<v^\star_c < \kappa^5_c$. Moreover, for any $\tilde{\kappa}_c \in \RR^5$ that solves \eqref{eq:system} such that $\tilde{\kappa}_c^4<v^\star_c<\tilde{\kappa}_c^5$, it must be that $\tilde{\kappa}_c^4 \geq \tilde{\kappa}_c^2 \geq \lb{v}_c$. Since $\kappa_c^5$ is the unique solution of \eqref{eq:fixedpoint} among $v \in [\hat{v}_c,\tilde{v}_c]$, for which $g_c(v) \geq \lb{v}_c$, it must be that $\tilde{\kappa}_c^5=\kappa_c^5$. Meanwhile, since $\tilde{\kappa}_c$ solves \eqref{eq:system}, it must be that $\tilde{\kappa}_c=\kappa_c$. Thus, $\kappa_c$ is the unique increasing vector in $\RR^5$ with $\kappa_c^4<v^\star_c<\kappa_c^5$ that solves \eqref{eq:system}. 
\end{proof}

\begin{proof}[Proof of \bref{thm2}]
Note that \bref{thm2} immediately implies \bref{thm1}, and therefore we prove \bref{thm2} directly. For any $c \in C$, if $F_{c,l}(c) \geq \|F_{c,l}-F_{c,h}\|$, let 
\[
\phi^\star_c(v_l):=(1-\alpha_c)\cdot (v_l-c)^+ \quad \mbox{ and } \quad \psi^\star_c(v_h):=\alpha_c \cdot (v_h-c)^+\,,
\]
for all $(v_l,v_h) \in V \times V$. Meanwhile, if $F_{c,l}(c)<\|F_{c,l}-F_{c,h}\|$, let 
\[
\phi_c^\star(v_l):=\begin{cases}
\kappa_c^1-c,& \mbox{if } v_l \leq \kappa_c^3\\
(1-\alpha_c)\cdot(v_l-c),&\mbox{if } v_l \in \left(\kappa_c^3,\kappa_c^4\right]\\
v_l-c-\alpha_c\cdot(\kappa_c^4-c),&\mbox{if } v_l \in (\kappa_c^4,\kappa_c^5]\\
(1-\alpha_c)(v_l-c)+\kappa_c^1-c, &\mbox{if } v_l>\kappa_c^5
\end{cases}\,,
\]
and let 
\[
\psi_c^\star(v_h):=\begin{cases}
0,& \mbox{if } v_h \leq \kappa_c^1\\
v_h-\kappa_c^1,&\mbox{if } v_h \in \left(\kappa_c^1,\kappa_c^3\right]\\
\alpha_c\cdot (v_h-c),&\mbox{if } v_h \in \left(\kappa_c^3,\kappa_c^4\right]\\
\alpha_c\cdot (\kappa_c^4-c),&\mbox{if } v_h \in (\kappa_c^4,\kappa_c^5]\\
\alpha_c(v_h-c)-(\kappa_c^1-c), &\mbox{if } v_h>\kappa_c^5
\end{cases}\,.
\]


\begin{taggedlemma}{A.1}\label{lem:feasible}
For any $(v_l,v_h) \in V \times V$ and for any $c \in C$, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h) \geq \pi_c(v_l,v_h)\,.
\]
\end{taggedlemma}
The proof of \bref{lem:feasible} is by inspection, using the system of equation \eqref{eq:system} that defines $\kappa_c$. Details of the proof can be found in \bref{sec:a.3}. Next, we define a joint distribution $\rho_c^\star \in \Delta(V^2)$. When $F_{c,l}<\|F_{c,l}-F_{c,h}\|$, define a transition probability $\gamma_c^\star:V \to \Delta(V)$ as follows: 
\begin{align*}
&\gamma^\star_c(v_l \leq x \mid v_h):=\\
&\begin{cases}
\mathbf{1}\{\lb{\Delta}_c^{-1}(F_{c,h}(v_h+\Delta_c(\kappa_c^3)) \leq x\},& \mbox{if } v_h \leq \kappa_c^1\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3)) \leq x\},&\mbox{if } v_h \in (\kappa_c^1,\kappa^3_c]\\
\mathbf{1}\{v_h \leq x\},& \mbox{if } v_h \in (\kappa_c^3,\kappa_c^4]\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^4)) \leq x\}, &\mbox{if } v_h \in (\kappa_c^4,\kappa_c^5]\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\cdot \mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \cdot \mathbf{1}\{F_{c,l}^{-1}(\Delta_c(\kappa_c^5)-\Delta_c(v_h)) \leq x\},&\mbox{if } v_h > \kappa_c^5,
\end{cases}\,,
\end{align*}
for all $x \in V$ and for all $v_h \in V$. Meanwhile, when $F_{c,l} \geq \|F_{c,l}-F_{c,h}\|$ and $c<v^\star_c$, define a transition probability $\gamma^\star_c:V \to \Delta(V)$ as: 
\begin{align*}
&\gamma_c^\star(v_l \leq x \mid v_h):=\\
&\begin{cases}
\mathbf{1}\left\{F_{c,l}^{-1}(F_{c,h}(v_h)) \leq x\right\},&\mbox{if } v_h \leq \eta_c^h\\
\mathbf{1}\left\{\lb{\Delta}_c^{-1}(F_{c,h}(v_h)-F_{c,h}(\eta_c^h)+\Delta_c(c)) \leq x\right\},&\mbox{if }  v_h \in (\eta_c^h,c]\\
\mathbf{1}\{v_h \leq x\},&\mbox{if } v_h \in (c,v^\star_c]\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \mathbf{1}\{F_{c,l}^{-1}(\Delta_c(v^\star_c)-\Delta_c(v_h)+F_{c,l}(\eta_c^l)) \leq x\}, &\mbox{if } v_h >v_c^\star
\end{cases}\,,
\end{align*}
for all $x \in V$ and for all $v_h \in V$. When $F_{c,l} \geq \|F_{c,l}-F_{c,h}\|$ and $c \geq v^\star_c$, define $\gamma^\star_c$ as: 
\begin{align*}
&\gamma^\star_c(v_l \leq x\mid v_h):=\\
&\begin{cases}
\mathbf{1}\left\{F_{c,l}^{-1}(F_{c,h}(v_h)) \leq x\right\},&\mbox{if } v_h \leq c\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \mathbf{1}\{F_{c,l}^{-1}(F_{c,l}(c)-\Delta_c(v_h)) \leq x\}, &\mbox{if } v_h >c
\end{cases}\,,
\end{align*}
for all $x \in V$ and for all $v_h \in V$.

Then, for all $c \in C$, let $\rho_c^\star \in \Delta(V \times V)$ be defined as 
\begin{equation}\label{eq:sol2}
\rho_c^\star(v_l \in A, v_h \in B):=\int_B \gamma_c^\star(A\mid v_h) F_{c,h}(\diff v_h)\,,
\end{equation}
for all measurable sets $A,B \subseteq V$. By construction, the marginals of $\rho_c^\star$ are exactly $F_{c,l}$ and $F_{c,h}$. That is,

\begin{taggedlemma}{A.2}\label{lem:rfeas}
$\rho_c^\star \in \mathcal{R}_c$ for all $c \in C$. 
\end{taggedlemma}


Combining \bref{lem:dual}, \bref{lem:feasible} and \bref{lem:rfeas} with   \bref{lem:complementary_slackness} below, it then follows that $\rho_c^\star$ is a solution of \eqref{eq:transport-point}. 

\begin{taggedlemma}{A.3}\label{lem:complementary_slackness}
For any $c \in C$, $\phi_c^\star(v_l)+\psi_c^\star(v_h)=\pi_c(v_l,v_h)$ for all $(v_l,v_h) \in \mathrm{supp}(\rho_c^\star)$.
\end{taggedlemma}

Since $\rho_c^\star$ is a solution of \eqref{eq:transport-point} for all $c$, \bref{prop:opt-transport} implies that one can construct an optimal non-discriminatory pricing rule from $\{\rho^\star_c\}_{c \in C}$. To this end, for any $c \in C$, let $\beta_c^\star: V \to \Delta(V)$ be the conditional distribution of $v_h$ given $v_l$ implied by $\rho_c^\star$. That is, $\beta_c^\star$ is a version of the regular conditional probability defined by 
\begin{equation}\label{eq:beta}
\rho_c^\star(v_l \in A,v_h \in B)=\int_B \beta_c^\star(v_l \in A\mid v_h ) F_{c,h}(\diff v_h)\,,
\end{equation}
for all measurable $A,B \subseteq V$. Next, let $\gamma_c^{-1}$ and $\beta_c^{-1}$ be the quantile function defined by $\gamma_c^\star$ and $\beta_c^\star$, respectively. That is, 
\[
\gamma_c^{-1}(r\mid v_h):=\inf\{v_l \in V: \gamma_c^\star([0,v_l]\mid v_h ) \geq r\} \mbox{ and } \beta_c^{-1}(r \mid v_l):=\inf\{v_h \in V: \beta_c^\star([0,v_h]\mid v_l) \geq r\}
\]
for all $r \in [0,1]$ and for all $(v_l,v_h) \in V^2$. Meanwhile, for any $(v_l,v_h) \in V^2$, let $\ub{p}_c(v_l,v_h)$ be the minimum element of 
\[
\argmax_{\tilde{p} \geq 0} (\tilde{p}-c)(\alpha_c \mathbf{1}\{v_h \geq \tilde{p}\}+(1-\alpha_c)\mathbf{1}\{v_l \geq \tilde{p}\})\,.
\]
It then follows that $p^\star$ can be written as 
\[
p^\star(v,l,c,r)=\ub{p}_c(v,\beta_c^{-1}(r\mid v)) \mbox{ and } p^\star (v,h,c,r)=\ub{p}_c(\gamma_c^{-1}(r\mid v),v)
\]
for all $v \in V$, $c \in C$ and $r \in [0,1]$. By construction, 
\begin{align*}
\PP[p^\star \in M\mid c,\theta=l]=&\PP[\ub{p}_c(v,\beta_{c}^{-1}(r\mid v)) \in M\mid \theta=l,c]\\
=&\int_{V \times [0,1]} \mathbf{1}\{\ub{p}_c(v_l,\beta_{c}^{-1}(r\mid v_l))\in M\}\diff r \diff F_{c,l}(\diff v_l)\\
=&\int_{V^2} \mathbf{1}\{\ub{p}_c(v_l,v_h) \in M\} \beta^\star_{c}(\diff v_h\mid v_l)F_{c,l}(\diff v_l)\\
=&\int_{V^2} \mathbf{1}\{\ub{p}_c(v_l,v_h) \in M\} \rho^\star_c(\diff v_l,\diff v_h)\,,
\end{align*}
where the third equality again follows from changing variables of the integration, and the last equality follows from \eqref{eq:sol2} and \eqref{eq:beta}. Likewise, 
\begin{align*}
\PP[p^\star \in M\mid c,\theta=h]=&\PP[\ub{p}_c(\gamma_{c}^{-1}(r\mid v),v) \in M\mid \theta=h,c]\\
=&\int_{V \times [0,1]} \mathbf{1}\{\ub{p}_c(\gamma_{c}^{-1}(r\mid v_h),v_h)\in M\}\diff r \diff F_{c,h}(\diff v_h)\\
=&\int_{V^2} \mathbf{1}\{\ub{p}_c(v_l,v_h) \in M\} \gamma^\star_{c}(\diff v_l\mid v_h)F_{c,h}(\diff v_h)\\
=&\int_{V^2} \mathbf{1}\{\ub{p}_c(v_l,v_h) \in M\} \rho^\star_c(\diff v_l,\diff v_h)\,.
\end{align*}
As a result, for all $c \in C$, and for all measurable $M \subseteq [0,1]$,
\[
\PP[p^\star \in M\mid c,\theta=l]=\int_{V^2} \mathbf{1}\{\ub{p}_c(v_l,v_h) \in M\}\rho^\star_c(\diff v_l \diff v_h) =\PP[p^\star \in M\mid c,\theta=h]\,,
\]
and thus $p^\star$ is indeed non-discriminatory. Moreover, 
\begin{align*}
\Pi(p^\star)=&\EE[(p^\star-c)\mathbf{1}\{v \geq p^\star\}]\\
=&\EE[\EE[\EE[(p^\star-c)\mathbf{1}\{v \geq p^\star\}\mid c,\theta]\mid c]]\\
=&\int_C \bigg(\alpha_c \int_{V \times [0,1]} (\ub{p}_c(\gamma_{c}^{-1}(r\mid v_h),v_h)-c)\mathbf{1}\{ v_h\geq \ub{p}_c(\gamma_{c}^{-1}(r\mid v_h),v_h)\}\diff rF_{c,h}(\diff v_h)\\
&+(1-\alpha_c) \int_{V \times [0,1]} (\ub{p}_c(v_l,\beta_{c}^{-1}(r\mid v_l))-c)\mathbf{1}\{v_l \geq \ub{p}_c(v,\beta_{c}^{-1}(r\mid v_l))\}\diff rF_{c,l}(\diff v_l) \bigg)G(\diff c)\\
=& \int_C \bigg(\alpha_c \int_{V^2} (\ub{p}_c(v_l,v_h)-c)\mathbf{1}\{v_h \geq \ub{p}_c(v_l,v_h)\}\gamma^\star_{c}(\diff v_l\mid v_h)F_{c,h}(\diff v_h)\\
&+(1-\alpha_c)\int_{V^2}(\ub{p}_c(v_l,v_h)-c)\mathbf{1}\{v_l \geq \ub{p}_c(v_l,v_h)\}\beta_{c}^\star(\diff v_h\mid v_l)F_{c,l}(\diff v_l)\bigg)G(\diff c)\\
=&\int_C \left(\int_{V^2} (\ub{p}_c(v_l,v_h)-c)(\alpha_c\mathbf{1}\{v_h \geq \ub{p}_c(v_l,v_h)\}+(1-\alpha_c)\mathbf{1}\{v \geq \ub{p}_c(v_l,v_h)\})\rho^\star_c(\diff v_l,\diff v_h)\right)G(\diff c)\\
=&\int_C\left(\int_{V^2}\pi_c(v_l,v_h)\rho^\star_c(\diff v_l,\diff v_h)\right)G(\diff c)\,,
\end{align*}
where the second equality follows from the law of iterated expectation, the fourth equality follows from changing variables of the integration, the fifth equality follows from \eqref{eq:sol2} and \eqref{eq:beta}, and the last equality follows from the definition of $\ub{p}_c$. Thus, by \bref{prop:opt-transport}, $p^\star$ is indeed an optimal non-discriminatory pricing rule. This completes the proof of $(i)$. Part $(ii)$ then immediately follows from \bref{prop:welfare}. 
\end{proof}



\begin{proof}[Proof of \bref{prop:surplus}]
For $(i)$, by \bref{thm1}, to show that $CS(c,h;p^\star)>0$, it suffices to show $F_{c,h}(\kappa_c^5)>F_{c,h}(\kappa_c^4)$ and that $F_{c,h}(\kappa_c^1)>0$. To see this, since $\kappa_c^4<v^\star_c<\kappa_c^5$ and since $v_c^\star \in (\lb{v}_c, \ub{v}_c)$, it must be that $F_{c,h}(\kappa_c^5)>F_{c,h}(\kappa_c^4)$, as desired. In the meantime, to show that $WL(c,h;p^\star)$, it suffices to show $F_{c,h}(\kappa_c^1)>0$ by \bref{thm1}. According to \eqref{eq:system}, $\kappa_c^1>c$ for all $c$. Therefore, whenever $\lb{v}_c \leq c$, $F_{c,h}(\kappa_c^1)>F_{c,h}(c) \geq F_{c,h}(\lb{v}_c)=0$, as desired. 

For $(ii)$, suppose that $\alpha_c \ub{v}_c>\lb{v}_c-(1-\alpha_c)c$. By \bref{thm1}, it suffices to show that $F_{c,l}(\kappa_c^3)>F_{c,l}(\kappa_c^2)>0$. We first claim that $\Delta_c(\kappa_c^4)>0$. To see this, suppose the contrary. $\Delta_c(\kappa_c^4)=0$. Then it must be that $\kappa_c^4 \leq \lb{v}_c$ and $\kappa_c^5 \geq \ub{v}_c$. Moreover, $\kappa_c^2=F_{c,l}^{-1}(\Delta_c(\kappa_c^4))=F_{c,l}^{-1}(0)=\lb{v}_c$, and $\Delta_c(\kappa_c^3)=F_{c,h}(\kappa_c^1)=0$. Since $\kappa_c$ is increasing, it must be that $\kappa_c^3 \leq \kappa_c^4 \leq \lb{v}_c$. Together, 
\[
\lb{v}_c=\kappa_c^3 \leq \kappa_c^3 \leq \kappa_c^4 \leq \lb{v}_c\,,
\]
Therefore, $\kappa_c^3=\kappa_c^4=\lb{v}_c$. Thus, 
\[
(1-\alpha_c)(\kappa_c^3-c)=(1-\alpha_c)(\lb{v}_c-c)=\alpha_c(\kappa_c^5-\kappa_c^4) \geq \alpha_c(\ub{v}_c-\lb{v}_c)\,,
\]
and hence 
\[
\alpha_c \ub{v}_c \leq \lb{v}_c-(1-\alpha_c)c\,,
\]
a contradiction. As a result, $\Delta_c(\kappa_c^4)>0$. This implies that $F_{c,l}(\kappa_c^2)>0$. Together, we have that $CS(c,l;p^\star)>0$ and $WL(c,h;p^\star)>0$.

Conversely, suppose that $\alpha_c(\overline{v}_c-c) \leq \underline{v}_c-c$. Then, it must be that $\kappa_c^1 \leq \underline{v}_c$, since otherwise, as $\kappa_c^3 \leq \kappa_c^4<v^\star_c<\ub{v}_c$, 
\[
\alpha_c(\kappa_c^3-c) \leq \alpha_c(\ub{v}_c) \leq \lb{v}_c-c < \kappa_c^1-c\,,
\]
contradicting to \eqref{eq:system}. Since $\kappa_c^1 \leq \lb{v}_c$, \eqref{eq:system} then implies that  $0=\Delta_c(\kappa_c^3)=\Delta_c(\kappa_c^4)$, and hence $\kappa_c^3=\kappa_c^4=\lb{v}_c$, which in turn implies that $\kappa_c^2=\lb{v}_c$ and $\kappa_c^5=\ub{v}_c$. Thus, by \bref{thm1}, $CS(c,l;p^\star)=WL(c,l;p^\star)=0$, as desired. 

\end{proof}

\begin{proof}[Proof of \bref{prop:profit-bound}]
Recall that the assortative pricing rule $p^{ass}$, defined by \eqref{eq:assortative-matching} gives a profit of $\E{(v-c)^+}{c=\tilde{c},\theta=l}$ for all $\tilde{c} \in C$. Since $p^{ass}$ is non-discriminatory, and since 
\[
\E{(v-c)^+}{c=\tilde{c}}=\alpha_{\tilde{c}}\E{(v-c)^+}{c=\tilde{c},\theta=h}+(1-\alpha_{\tilde{c}})\E{(v-c)^+}{c=\tilde{c},\theta=l}
\]
we have
    \begin{equation}\label{eq:lb1}
        \frac{\Pi^\star_{\tilde{c}}}{\E{(v-c)^+}{c=\tilde{c}}} \geq \frac{\E{(v-c)^+}{c=\tilde{c},\theta=l}}{\E{(v-c)^+}{c=\tilde{c}}} \geq \frac{1}{\alpha_{\tilde{c}}r_{\tilde{c}} + 1} \,,
    \end{equation}
    for all $\tilde{c} \in C$. In the meantime, since the partly anti-assortative pricing rule $p^{anti}$ defined by \eqref{eq:partly}, with $q_c=1$ for all $c$, gives a profit of $\E{\alpha_c(v-c)^+}{c=\tilde{c},\theta=h}$ conditional on every $\tilde{c} \in C$, and is also non-discriminatory, we have  
    \begin{equation}\label{eq:lb2}
          \frac{\Pi^\star_{\tilde{c}}}{\E{(v-c)^+}{c=\tilde{c}}} \geq \frac{\alpha_{\tilde{c}}\E{(v-c)^+}{c=\tilde{c},\theta=h}}{\E{(v-c)^+}{c=\tilde{c}}} = \frac{\alpha_{\tilde{c}}(r_{\tilde{c}}+1)}{\alpha_{\tilde{c}}r_{\tilde{c}} + 1}\,,
    \end{equation}
 for all $\tilde{c} \in C$. Since the right-hand side of \eqref{eq:lb1} is decreasing in $\alpha_{\tilde{c}}$ and the left-hand side of \eqref{eq:lb2} is increasing in $\alpha_{\tilde{c}}$, the maximum of the two is minimizes at $\alpha_{\tilde{c}}=\nicefrac{1}{(r_{\tilde{c}}+1)}$, we have 
\[
\frac{\Pi^\star_{\tilde{c}}}{\E{(v-c)^+}{c=\tilde{c}}} \geq \max\left\{\frac{1}{\alpha_{\tilde{c}}r_{\tilde{c}} + 1},\frac{\alpha_{\tilde{c}}(r_{\tilde{c}}+1)}{\alpha_{\tilde{c}}r_{\tilde{c}} + 1}\right\} \geq \frac{r_{\tilde{c}}+1}{2\,r_{\tilde{c}} + 1}\,.
\]
as desired. 
\end{proof}



\begin{proof}[Proof of \bref{prop:population-size}]
For $(i)$, consider each $c \in C$, note that since $\tilde{v}_c$ defined in the proof of \bref{lem:system} is decreasing in $\alpha_c$, and since the function 
\[
\alpha_c \mapsto \Delta_c\left(\frac{\alpha_c}{1-\alpha_c} h_c(v)+c\right)+F_{c,h}(\alpha_c h_c(v)+c)
\]
is increasing in $\alpha_c$ for all $v \in [v^\star_c,\tilde{v}_c]$, $\kappa_c^5$ defined in \eqref{eq:fixedpoint} is decreasing in $\alpha_c$, which in turn implies that $\kappa_c^4$ is increasing in $\alpha_c$. Therefore, since 
\[
CS(c,h;p^\star)=\int_{F_{c,h}(\kappa_c^4)}^{F_{c,h}(\kappa_c^5)}(F_{c,h}^{-1}(q)-F_{c,l}^{-1}(q-\Delta_c(\kappa_c^4)))\diff q, 
\]
$CS(c,h;p^\star)$ is decreasing in $\alpha_c$. 

For $(ii)$, note that since $\Delta_c(\kappa_c^5)=\Delta_c(\kappa_c^4)$ is increasing in $\alpha_c$ as established above, and since the function 
\[
v \mapsto \Delta_c\left(\frac{\alpha_c}{1-\alpha_c} h_c(v)+c\right)+F_{c,h}(\alpha_c h_c(v)+c)
\]
is increasing on $[v^\star_c,\tilde{v}_c]$, $\kappa_c^3=\alpha_c h_c(v)/(1-\alpha_c)+c$ is also increasing in $\alpha_c$. Together with $\kappa_c^3 \leq v^\star_c$ for all $\alpha_c \in [0,1]$, it follows that $\Delta_c(\kappa_c^3)$ is increasing in $\alpha_c$ as well. In the meantime, since $F_{c,l}(\kappa_c^4)-F_{c,l}(\kappa_c^2)=F_{c,h}(\kappa_c^4)$, it is also increasing in $\alpha_c$. 

Moreover, note that since $\Delta_c$ is increasing on $[0,v^\star_c]$ and since $\kappa_c^4 \leq v^\star_c$, $F_{c,h}(v) \leq F_{c,l}(v)-\Delta_c(\kappa_c^3)$ for all $v \in [\kappa_c^3,\kappa_c^4]$,
\begin{align*}
CS(c,l;p^\star)=\int_{\kappa_c^2}^{\kappa_c^3} (v-F_{c,h}^{-1}(F_{c,l}(v)-\Delta_c(\kappa_c^3)))F_{c,l}(\diff v)=\int_{\kappa_c^2}^{\kappa_c^4} (v-\tau(v))F_{c,l}(\diff v)\,,
\end{align*}
where 
\[
\tau(v):=\min\{v, F_{c,h}^{-1}(F_{c,l}(v)-\Delta_c(\kappa_c^3))\}
\]
for all $v \in [\kappa_c^2,\kappa_c^4]$. Note that $\tau(v)$ is decreasing in $\alpha_c$ for all $v \in [\kappa_c^2,\kappa_c^4]$ since $\Delta_c(\kappa_c^3)$ is increasing in $\alpha_c$. Together, $CS(c,l;p^\star)$ is increasing in $\alpha_c$. 

For $(iii)$, suppose first that $\alpha_c \to 1$. Since $\kappa_c^5$ is decreasing in $\alpha_c$ and is bounded from below by $v^\star$. Thus, the limit of $\kappa_c^5$ exists. As a result, the limits of $\kappa_c^1,\kappa_c^2, \kappa_c^3$ and $\kappa_c^4$ exist as well. 
Moreover, since $\kappa_c^3 \leq v^\star_c$ for all $\alpha_c \in (0,1)$, $\kappa_c^3$ must converge to a finite value as $\alpha_c \to 1$. Thus, since $\kappa_c^3-c=\nicefrac{\kappa_c^1-c}{(1-\alpha_c)}$, for all $\alpha_c \in (0,1)$, $\kappa_c^1$ must converge to $c$ as $\alpha_c \to 1$. This in turn implies that the limits of $\kappa_c^5$ and $\kappa_c^4$ coincide and equal $v_c^\star$. This implies $CS(c,h,p^\star)=0$. 

Now suppose that $\alpha_c \to 0$. Since $\kappa_c^4$ is decreasing as $\alpha_c \to 0$ and is bounded from below by $0$, the limit of $\kappa_c^4$ exists, and hence the limits of $\kappa_c^1,\kappa_c^2,\kappa_c^3$ and $\kappa_c^5$ exist as well. Moreover, since $\kappa_c^1-c=\alpha_c(\kappa_c^5-\kappa_c^4)$, the limit of $\kappa_c^1$ as $\alpha_c \to 0$ must be $c$, which in turn implies that the limit of $\kappa_c^3$ as $\alpha_c \to 0$ equals $c$ as well. Since $\kappa_c^2 \in [\kappa_c^1,\kappa_c^3]$, it then follows that the limit of $\kappa_c^2$ equals $c$ as well. As a result, $CS(c,l;p^\star)=0$. This completes the proof.
\end{proof}


\begin{proof}[Proof of \bref{prop:compare}]
To prove $(i)$, consider any non-discriminatory pricing rule $p$ that induces non-discriminatory outcomes. For each $c \in C$, define a matching scheme $\rho_c \in \Delta(V^2)$ as 
\[
\rho_c(V_l \times V_h):= \EE\left[\PP[v \in V_l\mid p,c,\theta=l,y] \times \PP[v \in V_h \mid p,c,\theta=h,y]\mid c\right]\,,
\]
for all measurable $V_l,V_h \subseteq V$. Since $p$ induces non-discriminatory outcomes, 
\[
\rho_c([0,z] \times V)=\EE[\PP[v \in [0,z] \mid p,\theta=l,c,y]\mid c]=F_{c,l}(z)\,,
\]
and 
\[
\rho_c(V\times [0,z])=\EE[\PP[v \in [0,z]\mid p,\theta=h,c,y]\mid c]=F_{c,h}(z)\,,
\]
for all $z\geq 0$. Therefore, $\rho_c \in \mathcal{R}_c$. 

For each $c$, given such matching scheme $\rho_c$, since $(p,y)$ is independent of $\theta$ conditional on $c$, each matched pair $(v_l,v_h) \in \mathrm{supp}(\rho_c)$ must face the same price under $p$; and either both purchase or both do not purchase. Therefore, the seller's profit under $p$ must be weakly lower than selling to each matched pair $(v_l,v_h) \in \mathrm{supp}(\rho_c)$ at a price $\min\{v_l,v_h\}$ whenever $\min\{v_l,v_h\} \geq c$, and not selling to the pair otherwise. That is, 
\[
\Pi(p) \leq \EE\left[\int_{V^2} (\min\{v_l,v_h\}-c)^+\diff \rho_c\right]\,.
\]
As a result, for any pricing $p$ that induces non-discriminatory outcomes, 
\[
\Pi(p) \leq \EE\left[\max_{\rho_c \in \mathcal{R}_c} \int_{V^2}(\min\{v_l,v_h\}-c)^+\diff \rho_c \right]=:\ub{\pi}\,.
\]
Note that the objective $(\min\{v_l,v_h\}-c)^+$ of the optimal transport problem 
\[
\max_{\rho_c \in \mathcal{R}_c} \int_{V^2} (\min\{v_l,v_h\}-c)^+\diff \rho_c
\]
if supermodular for all $c \in C$, the assortative matching must be a solution. Therefore, 
\[
\max_{\rho_c \in \mathcal{R}_c} \int_{V^2} (\min\{v_l,v_h\}-c)^+\diff \rho_c=\int_V (v-c)^+ F_{c,l}(\diff v)\,.
\]
Thus, by construction, under the pricing rule $p^{ass}$, 
\[
\Pi(p^{ass})=\EE\left[\int_V (v-c)^+ F_{c,l}(\diff v) \right]=\ub{\pi}\,.
\]
Since $p^{ass}$ also induces non-discriminatory outcomes, $p^{ass}$ is optimal. Furthermore, as $p^{ass}$ is also non-discriminatory, $\Pi(p^\star) \geq \Pi(p^{ass})$. Lastly, since the solution of 
\[
\max_{\rho_c \in \mathcal{R}_c} \int_{V \times V} (\min\{v_l,v_h\}-c)^+\rho_c(\diff v_l, \diff v_h)
\]
must correspond to a pricing rule that is outcome-equivalent to the assortative matching for all $c \in C$, any profit-maximizing pricing rule that induces non-discriminatory outcomes must yield the same surplus to consumers. 

For $(iii)$, since $F_{c,h}$ dominates $F_{c,l}$ in the likelihood ratio order, under $p^{ass}$, each matched pair of consumers who are purchasing consumers must buy at the value of the consumer with $\theta=l$, and hence $0=CS(c,l;p^{ass}) \leq CS(c,h;p^\star)$; while the price distribution faced by purchasing consumers with $\theta=h$ equals $(F_{c,l}(\cdot)-F_{c,l}(c))^+/(1-F_{c,l}(c))$, which in turn is dominated by the price distribution faced by purchasing consumers with $\theta=h$ in the sense of first-order-stochastic dominance under $p^\star$. Therefore, $CS(c,h;p^{ass}) \geq CS(c,h;p^\star)$. Moreover, note that as established in the proof of $(ii)$ of \bref{prop:surplus}, $p^\star \neq p^{ass}$ if and only if $\alpha_c(\overline{v}_c-c)>\underline{v}_c-c$ for a positive measure of $c$. Thus, $CS(c,h;p^{ass}) > CS(c,h;p^\star)$ if and only if $\alpha_c(\overline{v}_c-c)>\underline{v}_c-c$ for a positive measure of $c$.

For $(ii)$, since $p^{ass}$ is non-discriminatory, \bref{thm1} implies that $\Pi(p^\star) \geq \Pi(p^{ass})$. Moreover, by $(iii)$, since $CS(c,h;p^{ass})>CS(c,h;p^\star)$ if and only if $\alpha_c(\ub{v}_c-c)\lb{v}_c-c$, and since every undominated profit-maximizing rule $p$ must yield $CS(c,\theta;p)=CS(c,\theta;p^\star)$ for all $c \in C$ and for all $\theta \in \{l,h\}$ by \bref{thm1}, it must be that $p^{ass}$ is not optimal if and only if $\alpha_c(\ub{v}_c-c)>\lb{v}_c-c$ for a positive measure of $c \in C$. Therefore, $\Pi(p^\star)>\Pi(p^{ass})$ if and only if $\alpha_c(\ub{v}_c-c)>\lb{v}_c-c$. This completes the proof.    
\end{proof}

\subsection{Proofs of Omitted Auxiliary Lemmas}\label{sec:a.3}
\begin{proof}[Proof of \bref{lem:feasible}] 
We show that $\phi_c^\star(v_l)+\psi_c^\star(v_h) \geq \pi_c(v_l,v_h)$ for all $(v_l, v_h)$ by discussing all cases separately. Suppose first that $F_{c,l}(c)<\Delta_c(v^\star_c)=\|F_{c,l}-F_{c,h}\|$.  \\
\mbox{}

\noindent \textbf{Case 1: }$v_l \leq \kappa_c^3$.

\noindent When $v_h \leq \kappa_c^1$, $\pi_c(v_l,v_h)$ either equals $\min\{v_l,v_h\}-c \leq v_h-c \leq \kappa_c^1-c$, or $\alpha_c (v_h-c)^+ \leq \kappa_c^1-c$, or $(1-\alpha_c) (v_l-c)^+ \leq (1-\alpha_c) (\kappa_c^3-c)=\kappa_c^1-c$. Therefore, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=\kappa_c^1-c \geq \pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^1,\kappa_c^3]$, $v_h-c>\kappa_c^1-c=(1-\alpha_c) (\kappa_c^3-c) \geq (1-\alpha_c)(v_l-c)^+$ and hence $\min\{v_h,v_l\}-c \geq (1-\alpha_c)(v_l-c)^+$. Therefore, $\pi_c(v_l,v_h)$ either equals $\min\{v_l,v_h\}-c \leq v_h-c$ or $\alpha_c (v_h-c) \leq v_h-c$. As a result, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_h-c \geq \pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^3,\kappa_c^4]$, $v_h>v_l$, and therefore $\pi_c(v_l,v_h)=\max\{v_l-c,\alpha_c(v_h-c)\}$. Moreover, since $(1-\alpha_c) (\kappa_c^3-c)=\kappa_c^1-c$, we have $v_l-c\leq \kappa_c^3-c = \alpha_c(\kappa_c^3-c)+\kappa_c^1-c \leq \alpha_c (v_h-c)+\kappa_c^1-c$. Thus, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=\alpha_c(v_h-c)+\kappa_c^1-c \geq \max\{v_l-c,\alpha_c(v_h-c)\}=\pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^4,\kappa_c^5]$, $v_h>v_l$, and therefore $\pi_c(v_l,v_h)=\max\{v_l-c,\alpha_c(v_h-c)\}$. As argued above, we have $v_l -c\leq \kappa_c^3-c = \alpha_c (\kappa_c^3-c)+\kappa_c^1-c \leq \alpha_c (\kappa_c^4-c)+(\kappa_c^1-c)$. Furthermore, by \eqref{eq:system},
\[
\alpha_c(\kappa_c^4-c)+\kappa_c^1-c=\alpha_c (\kappa_c^5-c) \geq \alpha_c (v_h-c)\,.
\]
Together, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=\alpha_c(\kappa_c^4-c)+\kappa_c^1-c \geq \max\{v_l-c,\alpha_c(v_h-c)\}=\pi_c(v_l,v_h)\,.
\]
When $v_h>\kappa_c^5$, note that since $\kappa_c^1-c=(1-\alpha_c)(\kappa_c^3-c) \leq (1-\alpha_c)(\kappa_c^4-c)$, and since $\alpha_c(\kappa_c^5-\kappa_c^4)=\kappa_c^1-c$, we have that $\alpha_c (v_h-c) \geq \alpha_c(\kappa_c^5-c)=\alpha_c(\kappa_c^4-c)+(1-\alpha_c)(\kappa_c^3-c)\geq \kappa_c^3-c \geq v_l-c$. Therefore, $\pi_c(v_l,v_h)=\alpha_c(v_h-c)$, and hence 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=\alpha_c (v_h-c) =\pi_c(v_l,v_h)\,.
\]
\mbox{}

\noindent \textbf{Case 2:} $v_l \in (\kappa_c^3,\kappa_c^4]$. 

\noindent When $v_h \leq \kappa_c^1$, $(1-\alpha_c)(v_l-c)>(1-\alpha_c)(\kappa_c^3-c)=\kappa_c^1-c \geq v_h-c$, and hence $\pi_c(v_l,v_h)=(1-\alpha_c) (v_l-c)$. Therefore, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=(1-\alpha_c)(v_l-c) = \pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^1,\kappa_c^3]$, $v_h \leq \kappa_c^3<v_l$ and hence $\min\{v_l,v_h\}-c=v_h-c$. Therefore, $\pi_c(v_l,v_h)=\max\{v_h-c,(1-\alpha_c)(v_l-c)\}$. Since $v_h-\kappa_c^1+(1-\alpha_c)(v_l-c)>v_h-\kappa_c^1+(1-\alpha_c)(\kappa_c^3-c)=v_h-c$, we have 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_h-\kappa_c^1+(1-\alpha_c)(v_l-c) \geq \max\{v_h-c,(1-\alpha_c)(v_l-c)\}\,.
\]
When $v_h \in (\kappa_c^3,\kappa_c^4]$, 
\begin{align*}
\phi_c^\star(v_l)+\psi_c^\star(v_h)=&\alpha_c(v_h-c)+(1-\alpha_c)(v_l-c) \\
\geq& \max\{\min\{v_l,v_h\}-c,(1-\alpha_c)(v_l-c),\alpha_c(v_h-c)\}\,.
\end{align*}
When $v_h \in (\kappa_c^4,\kappa_c^5]$, since $\kappa_c^1-c=\alpha_c(\kappa_c^5-\kappa_c^4)$ and since $(1-\alpha_c)(\kappa_c^3-c)=\kappa_c^1-c$, we have 
\begin{align*}
\alpha_c(v_h-c) \leq \alpha_c(\kappa_c^5-c) =&\alpha_c(\kappa_c^4-c)+\kappa_c^1-c\\
=&\alpha_c(\kappa_c^4-c)+(1-\alpha_c)(\kappa_c^3-c)\\
\leq& \alpha_c(\kappa_c^4-c)+(1-\alpha_c)(v_l-c) \,.
\end{align*}
Together, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=\alpha_c(\kappa_c^4-c) + (1-\alpha_c) (v_l-c) \geq \max\{v_l-c,\alpha_c(v_h-c)\}=\pi_c(v_l,v_h)\,.
\]
When $v_h>\kappa_c^5$, since $\kappa_c^1-c=\alpha_c(\kappa_c^5-\kappa_c^4)$, we have 
\[
\alpha_c(v_h-c)-(\kappa_c^1-c) \geq \alpha_c(\kappa_c^5-c)-(\kappa_c^1-c)=\alpha_c(\kappa_c^4-c) \geq \alpha_c(v_l-c)\,.
\]
Therefore, 
\[
\alpha_c(v_h-c)-(\kappa_c^1-c)+(1-\alpha_c) v_l \geq v_l-c\,.
\]
Meanwhile, since $(1-\alpha_c)(\kappa_c^3-c)=\kappa_c^1-c$, 
\[
(1-\alpha_c)(v_l-c) \geq (1-\alpha_c) (\kappa_c^3-c)=\kappa_c^1-c\,,
\]
and thus
\[
\alpha_c (v_h-c)-(\kappa_c^1-c)+(1-\alpha_c)(v_l-c) \geq \alpha_c (v_h-c)\,.
\]
Together, 
\begin{align*}
\phi_c^\star(v_l)+\psi_c^\star(v_h)=&\alpha_c(v_h-c)-(\kappa_c^1-c)+(1-\alpha_c)(v_l-c)\\ 
\geq& \max\{v_l-c,\alpha_c (v_h-c)\}\\
=&\pi_c(v_l,v_h)\,.
\end{align*}
\mbox{}

\noindent \textbf{Case 3:} $v_l \in (\kappa_c^4,\kappa_c^5]$.

\noindent When $v_h \leq \kappa_c^1$, we have
\[
(1-\alpha_c)(v_l-c) > (1-\alpha_c) (\kappa_c^4-c) \geq  (1-\alpha_c)(\kappa_c^3-c) =\kappa_c^1-c \geq (v_h-c)^+\,.
\]
Therefore, $\pi_c(v_l,v_h)=(1-\alpha_c) (v_l-c)$ and hence 
\begin{align*}
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_l-c-\alpha_c(\kappa_c^4-c)=&\alpha_c(v_l-\kappa_c^4)+(1-\alpha_c)(v_l-c)\\
>&(1-\alpha_c)(v_l-c)\\
=&\pi_c(v_l,v_h)\,.
\end{align*}
When $v_h \in (\kappa_c^1,\kappa_c^3]$, 
\[
v_l-c-\alpha_c(\kappa_c^4-c)+v_h-\kappa_c^1>v_l-c-\alpha_c(\kappa_c^4-c)>(1-\alpha_c)(v_l-c)\,.
\]
Moreover, since $(1-\alpha_c)(\kappa_c^3-c)=\kappa_c^1-c$ and since $\kappa_c^4 \geq \kappa_c^3$, 
\begin{align*}
v_l-c-\alpha_c(\kappa_c^4-c)+v_h-\kappa_c^1=&v_l-c-\alpha_c(\kappa_c^4-c)+v_h-c-(\kappa_c^1-c)\\
> & (1-\alpha_c)(\kappa_c^4-c)+v_h-c-(\kappa_c^1-c)\\
\geq & (1-\alpha_c)(\kappa_c^3-c)+v_h-c-(\kappa_c^1-c)\\
=& v_h-c\,.
\end{align*}
Together, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_l-c-\alpha_c(\kappa_c^4-c)+v_h-\kappa_c^1 \geq \max\{v_h-c,(1-\alpha_c)(v_l-c)\}=\pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^3,\kappa_c^4]$, since $v_l>\kappa_c^4 \geq v_h$,
\[
v_l-c-\alpha_c(\kappa_c^4-c)+\alpha_c(v_h-c) > (1-\alpha_c)(\kappa_c^4-c)+\alpha_c(v_h-c) \geq v_h-c
\]
In the meantime, since $v_h>\kappa_c^3 \geq \kappa_c^1 \geq c$, 
\[
v_l-c-\alpha_c(\kappa_c^4-c)+\alpha_c(v_h-c) \geq v_l-c-\alpha_c(\kappa_c^4-c) > (1-\alpha_c)(v_l-c)\,.
\]
Therefore, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_l-c-\alpha_c(\kappa_c^4-c)+\alpha_c(v_h-c) \geq \max\{v_h-c, (1-\alpha_c)(v_l-c)\}=\pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^4,\kappa_c^5]$, since $\kappa_c^1-c=\alpha_c(\kappa_c^5-\kappa_c^4)$  and since $\kappa_c^4-c \geq \kappa_c^3-c=\nicefrac{(\kappa_c^1-c)}{(1-\alpha_c)}$, we have 
\[
\alpha_c(\kappa_c^5-c)=\alpha_c(\kappa_c^4-c)+\kappa_c^1-c= \alpha_c (\kappa_c^4-c) + (1-\alpha_c)(\kappa_c^3-c) \leq \kappa_c^4-c\,.
\]
Therefore, 
\[
\alpha_c(v_h-c) \leq \alpha_c(\kappa_c^5-c) \leq \kappa_c^4-c \leq v_l-c\,,
\]
and hence $\pi_c(v_l,v_h)=\max\{\min\{v_l,v_h\}-c,(1-\alpha_c)(v_l-c)\}$. Together,
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_l-c \geq \max\{\min\{v_l,v_h\}-c, (1-\alpha_c)(v_l-c)\}=\pi_c(v_l,v_h)\,.
\]
When $v_h>\kappa_c^5$, since $\kappa_c^4-c \geq \kappa_c^3-c=\nicefrac{(\kappa_c^1-c)}{(1-\alpha_c)}$, 
\begin{align*}
&\alpha_c (v_h-c)+v_l-c-\alpha_c(\kappa_c^4-c)-(\kappa_c^1-c)\\
\geq &\alpha_c(v_h-c)+(1-\alpha_c)(\kappa_c^4-c)-(\kappa_c^1-c) \\
\geq& \alpha_c(v_h-c) +(1-\alpha_c)(\kappa_c^3-c)-(\kappa_c^1-c)\\
=&\alpha_c (v_h-c)\,. 
\end{align*}
Moreover, since $\kappa_c^1-c=\alpha_c(\kappa_c^5-\kappa_c^4)$, 
\begin{align*}
&\alpha_c(v_h-c)+v_l-c-(\kappa_c^1-c)-\alpha_c(\kappa_c^4-c) \\
> &\alpha_c(\kappa_c^5-c)+v_l-c-(\kappa_c^1-c)-\alpha_c (\kappa_c^4-c) \\
=&\alpha_c(\kappa_c^5-\kappa_c^4)-(\kappa_c^1-c)+v_l-c\\
=&v_l-c\,.
\end{align*}
Together, 
\begin{align*}
\phi_c^\star(v_l)+\psi_c^\star(v_h)=&\alpha_c( v_h-c)-(\kappa_c^1-c)+v_l-c-\alpha_c(\kappa_c^4-c) \\
\geq& \max\{v_l-c,\alpha_c(v_h-c)\}\\
=&\pi_c(v_l,v_h)\,.
\end{align*}
\mbox{}

\noindent \textbf{Case 4: }$v_l>\kappa_c^5$.

\noindent When $v_h \leq \kappa_c^1$, $(v_h-c)^+ \leq \kappa_c^1-c=(1-\alpha_c)(\kappa_c^3-c) \leq (1-\alpha_c) (v_l-c)$. Thus, $\pi_c(v_l,v_h)=(1-\alpha_c)(v_l-c)$, and hence, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=(1-\alpha_c)(v_l-c)+\kappa_c^1-c\geq (1-\alpha_c)(v_l-c)=\pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^1,\kappa_c^3]$, $v_h \leq \kappa_c^3 \leq \kappa_c^4<v_l$. Thus,
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_h-c+(1-\alpha_c)(v_l-c) \geq \max\{v_h-c,(1-\alpha_c)(v_l-c)\}=\pi_c(v_l,v_h)\,.
\]
When $v_h \in (\kappa_c^3,\kappa_c^4]$, since $\kappa_c^1 \geq c$, 
\begin{align*}
\phi_c^\star(v_l)+\psi_c^\star(v_h)=&\alpha_c(v_h-c)+(1-\alpha_c)(v_l-c)+\kappa_c^1-c \\
\geq&\alpha_c(v_h-c)+(1-\alpha_c)(v_l-c)\\
\geq &\max\{\min\{v_l,v_h\}-c,\alpha_c (v_h-c), (1-\alpha_c)(v_l-c)\}\\
=&\pi_c(v_l,v_h)\,.
\end{align*}
When $v_h \in (\kappa_c^4,\kappa_c^5]$, since $\kappa_c^1-c=\alpha_c(\kappa_c^5-\kappa_c^4)$. 
\begin{align*}
\phi_c^\star(v_l)+\psi_c^\star(v_h)=&\alpha_c(\kappa_c^4-c)+(1-\alpha_c)(v_l-c)+\kappa_c^1-c\\
=&\alpha_c(\kappa_c^5-c)-(\kappa_c^1-c)+(1-\alpha_c)(v_l-c)+\kappa_c^1-c\\
=& \alpha_c(\kappa_c^5-c)+(1-\alpha_c)(v_l-c)\\
\geq& \alpha_c(v_h-c) +(1-\alpha_c)(v_l-c)\\
\geq& \max\{\min\{v_l,v_h\}-c,\alpha_c(v_h-c),(1-\alpha_c)(v_l-c)\}\\
=&\pi_c(v_l,v_h)\,.
\end{align*}
When $v_h>\kappa_c^5$, 
\begin{align*}
\phi_c^\star(v_l)+\psi_c^\star(v_h)
=&\alpha_c(v_h-c)+(1-\alpha_c)(v_l-c) \\
\geq& \max\{\min\{v_l,v_h\}-c,\alpha_c(v_h-c),(1-\alpha_c)(v_l-c)\}\\
=&\pi_c(v_l,v_h)\,.
\end{align*}

Together, it follows that 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h) \geq \pi_c(v_l,v_h)\,,
\]
for all $v_l,v_h \geq 0$, as desired.

Now suppose that $F_{c,l}(c) \geq \Delta_c(v^\star_c)$. Then clearly. 
\begin{align*}
\phi^\star_c(v_l)+\psi_c^\star(v_h)=&(1-\alpha_c) (v_l-c)^++\alpha_c (v_h-c)^+\\ \geq & \max\{(1-\alpha_c) (v_l-c)^+, \alpha_c (v_h-c)^+, \min\{v_l,v_h\}-c\}\\
=&\pi_c(v_l,v_h)\,,
\end{align*}
for all $v_l,v_h \in V$. This completes the proof. 
\end{proof}


\begin{proof}[Proof of \bref{lem:rfeas}]
We first note that for all $c \in C$,  $\gamma_c^\star(\cdot\mid v_h)$ is a probability measure for all $v_h \in V$. Indeed, for all $v_h \in V$ $\lim_{x \to \infty} \gamma^\star_c(v_l \leq x\mid v_h)=1$ and $\gamma^\star_c(v_l \leq 0 \mid v_h)=0$; $x \mapsto \gamma^\star(v_l \leq x\mid v_h)$ is right-continuous. Moreover, for any $c \in C$ and for any measurable set $A \subseteq V$, $\gamma_c^\star(A\mid \cdot)$ is a measurable function. Therefore, $\gamma_c^\star$ is a transition probability for all $c \in C$. 

Next, we show that the marginals of $\rho_c^\star$ equal $F_{c,l}$ and $F_{c,h}$, respectively. By construction, 
\[
\rho^\star_c(v_l \in V, v_h \leq x)=\int_0^x 1 F_{c,h}(\diff v_h)=F_{c,h}(x)\,.
\]
To show that $\rho^\star_c(v_l \leq x, v_h \in V)=F_{c,l}(x)$ for all $c \in C$ and for all $x \in V$, consider first the case when $F_{c,l}(c)<\Delta_c(v^\star_c)$. For all $x \leq \kappa_c^2$, 
\[
\gamma_c^\star(v_l \leq x \mid v_h)=
\begin{cases}
0,&\mbox{if } v_h \leq \kappa_c^5\\
\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \mathbf{1}\{F_{c,l}^{-1}(\Delta_c(\kappa_c^5)-\Delta_c(v_h)) \leq x\},&\mbox{if } v_h>\kappa_c^5
\end{cases}\,.
\]
Note that the derivative of $v \mapsto \Delta_c(\kappa_c^5)-\Delta_c(v)$ equals $f_{c,h}-f_{c,l}$. Therefore,
\begin{align*}
\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h)F_{c,h}(\diff v_h)=& \int_{\kappa_c^5}^\infty \frac{f_{c,h}(v_h)-f_0(v_h)}{f_{c,h}(v_h)} \mathbf{1}\{F_{c,l}^{-1}(\Delta_c(\kappa_c^5)-\Delta_c(v_h)) \leq x\}F_{c,h}(\diff v_h)\\
=& \int_{\kappa_c^5}^\infty (f_{c,h}(v_h)-f_{c,l}(v_h)) \mathbf{1}\{\Delta_c(\kappa_c^5)-\Delta_c(v_h) \leq F_{c,l}(x)\}\diff v_h\\
=& \int_{0}^{\Delta_c(\kappa_c^5)} \mathbf{1}\{z \leq F_{c,l}(x)\}\diff z\\
=& \min\{\Delta_c(\kappa_c^5),F_{c,l}(x)\}\\
=& F_{c,l}(x)\,,
\end{align*}
where the third equality follows from changing variables of integration, and the last inequality follows from $F_{c,l}(x) \leq F_{c,l}(\kappa_c^2)=\Delta_c(\kappa_c^5)$, which in turn follows from \eqref{eq:system}. 

For all $x \in (\kappa_c^2,\kappa_c^3]$, 
\[
\gamma_c^\star(v_l \leq x\mid v_h)=
\begin{cases}
0,&\mbox{if } v_h \in [0,\kappa_c^1] \cup (\kappa_c^3,\kappa_c^5]\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3)) \leq x\},&\mbox{if } v_h \in (\kappa_c^1,\kappa_c^3]\\
\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)},&\mbox{if } v_h >\kappa_c^5
\end{cases}\,.
\]
Therefore, 
\begin{align*}
&\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h)F_{c,h}(\diff v_h)\\=& \int_{\kappa_c^1}^{\kappa_c^3} \mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3)) \leq x\} F_{c,h}(\diff v_h)+\int_{\kappa_c^5}^\infty \frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} F_{c,h}(\diff v_h)\\
=&\int_{\kappa_c^1}^{\kappa_c^3} \mathbf{1}\{F_{c,h}(v_h)\leq F_{c,l}(x)-\Delta_c(\kappa_c^3)\}F_{c,h}(\diff v_h)+F_{c,l}(\kappa_c^5)-F_{c,h}(\kappa_c^5)\\
=& \int_{F_{c,h}(\kappa_c^1)}^{F_{c,h}(\kappa_c^3)} \mathbf{1}\{z \leq F_{c,l}(x)-\Delta_c(\kappa_c^3)\} \diff z+\Delta_c(\kappa_c^5)\\
=& \min \{F_{c,l}(x)-\Delta_c(\kappa_c^3),F_{c,h}(\kappa_c^3)\}-F_{c,h}(\kappa_c^1)+\Delta_c(\kappa_c^5)\\
=&F_{c,l}(x)-\Delta_c(\kappa_c^3)-F_{c,h}(\kappa_c^1)+\Delta_c(\kappa_c^5)\\
=& F_{c,l}(x)\,,
\end{align*}
where the third equality follows from changing variables for integration, the fifth equality follows from $F_{c,l}(x)-\Delta_c(\kappa_c^3) \leq F_{c,l}(\kappa_c^3)-\Delta_c(\kappa_c^3)=F_{c,h}(\kappa_c^3)$, and the last equality also follows from \eqref{eq:system}.

For all $x \in (\kappa_c^3,\kappa_c^4]$,
\[
\gamma_c^\star(v_l \leq x\mid v_h)=
\begin{cases}
\mathbf{1}\{\lb{\Delta}_c^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3)) \leq x\},& \mbox{if } v_h \leq \kappa_c^1\\
1,&\mbox{if } v_h \in (\kappa_c^1,\kappa_c^3]\\
\mathbf{1}\{v_h \leq x\},&\mbox{if } v_h \in (\kappa_c^3,\kappa_c^4]\\
0,&\mbox{if } v_h \in (\kappa_c^4,\kappa_c^5]\\
\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)},&\mbox{if } v_h >\kappa_c^5
\end{cases}\,.
\]
Thus, 
\begin{align*}
&\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h)F_{c,h}(\diff v_h)\\
=&\int_0^{\kappa_c^1}\mathbf{1}\{\lb{\Delta}^{-1}_c(F_{c,h}(v_h)+\Delta_c(\kappa_c^3)) \leq x\}F_{c,h}(\diff v_h)+F_{c,h}(\kappa_c^3)-F_{c,h}(\kappa_c^1)\\
&+\int_{\kappa_c^3}^{\kappa_c^4} \mathbf{1}\{v_h \leq x\}F_{c,h}(\diff v_h)+\int_{\kappa_c^5}^\infty \frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)}F_{c,h}(\diff v_h)\\
=& \int_0^{\kappa_c^1}\mathbf{1}\{F_{c,h}(v_h)+\Delta_c(\kappa_c^3) \leq \Delta_c(x)\}F_{c,h}(\diff v_h)\\
&+F_{c,h}(\kappa_c^3)-F_{c,h}(\kappa_c^1)+F_{c,h}(x)-F_{c,h}(\kappa_c^3)+F_{c,l}(\kappa_c^5)-F_{c,h}(\kappa_c^5)\\
=&\int_{0}^{F_{c,h}(\kappa_c^1)}\mathbf{1}\{z \leq \Delta_c(x)-\Delta_c(\kappa_c^3)\}\diff z+F_{c,h}(x)-F_{c,h}(\kappa_c^1)+\Delta_c(\kappa_c^5)\\
=& \min\{\Delta_c(x)-\Delta_c(\kappa_c^3),F_{c,h}(\kappa_c^1)\}+F_{c,h}(x)-F_{c,h}(\kappa_c^1)+\Delta_c(\kappa_c^5)\\
=& \Delta_c(x)-\Delta_c(\kappa_c^3)+F_{c,h}(x)-F_{c,h}(\kappa_c^1)+\Delta_c(\kappa_c^5)\\
=&F_{c,l}(x)-(\Delta_c(\kappa_c^3)+F_{c,h}(\kappa_c^1))+\Delta_c(\kappa_c^5)\,,
\end{align*}
where the third equality follows from changing variables of the integration, the fifth equality follows from $\Delta_c(x)-\Delta_c(\kappa_c^3) \leq \Delta_c(\kappa_c^4)-\Delta_c(\kappa_c^3) = F_{c,h}(\kappa_c^1)$, which in turn follows from \eqref{eq:system}; whereas the last equality also follows from \eqref{eq:system}. 

For all $x \in (\kappa_c^4,\kappa_c^5]$, 
\[
\gamma_c^\star(v_l \leq x \mid v_h)=
\begin{cases}
1,&\mbox{if } v_h \leq \kappa_c^4\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^4)) \leq x\},&\mbox{if } v_h \in (\kappa_c^4,\kappa_c^5]\\
\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)},&\mbox{if } v_h>\kappa_c^5
\end{cases}\,.
\]
Thus, 
\begin{align*}
&\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h) F_{c,h}(\diff v_h)\\
=& \int_0^{\kappa_c^4} 1 F_{c,h}(\diff v)+\int_{\kappa_c^4}^{\kappa_c^5} \mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^4)) \leq x\}F_{c,h}(\diff v_h)
+\int_{\kappa_c^5}^{\infty} \frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} F_{c,h}(\diff v_h)\\
=&F_{c,h}(\kappa_c^4)+\int_{\kappa_c^4}^{\kappa_c^5}\mathbf{1}\{F_{c,h}(v_h) \leq F_{c,l}(x)-\Delta_c(\kappa_c^4)\}F_{c,h}(\diff v_h)
+\int_{\kappa_c^5}^{\infty} [f_{c,h}(v_h)-f_{c,l}(v_h)] \diff v_h\\
=& F_{c,h}(\kappa_c^4)+\min\{F_{c,l}(x)-\Delta_c(\kappa_c^4),F_{c,h}(\kappa_c^5)\}-F_{c,h}(\kappa_c^4)+\Delta_c(\kappa_c^5)\\
=&F_{c,h}(\kappa_c^4)+F_{c,l}(x)-\Delta_c(\kappa_c^4)-F_{c,h}(\kappa_c^4)+\Delta_c(\kappa_c^5)\\
=&F_{c,l}(x)\,,
\end{align*}
where the third equality follows from changing variables of  the integration, the fourth equality follows from $F_{c,l}(x)-\Delta_c(\kappa_c^4) \leq F_{c,l}(\kappa_c^5)-\Delta_c(\kappa_c^4)=F_{c,l}(\kappa_c^5)-\Delta_c(\kappa_c^5)=F_{c,h}(\kappa_c^5)$, which in turn follows from \eqref{eq:system}; and the last equality follows from \eqref{eq:system}.

For all $x> \kappa_c^5$, 
\[
\begin{cases}
1,&\mbox{if } v_h \leq \kappa_c^5\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)},&\mbox{if } v_h>\kappa_c^5
\end{cases}\,.
\]
Therefore, 
\begin{align*}
&\int_0^\infty \gamma_c^\star (v_l \leq x\mid v_h) F_{c,h}(\diff v_h)\\
=& \int_0^{\kappa_c^5} 1 F_{c,h}(\diff v_h)+\int_{\kappa_c^5}^\infty \left(\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)}\right) F_{c,h}(\diff v_h)\\
=& F_{c,h}(\kappa_c^5)+\int_{\kappa_c^5}^x f_{c,l}(v_h)\diff v_h+\int_{\kappa_c^5}^\infty [f_{c,h}(v_h)-f_{c,l}(v_h)]\diff v_h\\
=& F_{c,h}(\kappa_c^5)+F_{c,l}(x)-F_{c,l}(\kappa_c^5)+F_{c,l}(\kappa_c^5)-F_{c,h}(\kappa_c^5)\\
=& F_{c,l}(x)\,.
\end{align*}
Together, we have that 
\[
\rho_c^\star(v_l \leq x,v_h \in V)=\int_0^\infty \gamma^\star(v_l \leq x\mid v_h)F_1(\diff v_h)=F_{c,l}(x)\,,
\]
for all $x \in V$ and and hence $\rho_c^\star \in \mathcal{R}_c$ for all $c \in C$ such that $F_{l,c}(c)<\|F_{c,l}-F_{c,h}\|$.   


Now consider the case when $F_{c,l}(c) \geq \|F_{c,l}-F_{c,h}\|$ and $c \leq v^\star_c$. If $x \leq \eta_c^l$, then 
\[
\gamma^\star_c(v_l\leq x \mid v_h)=\begin{cases}
0,&\mbox{if } v_h>\eta_c^h\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h))\leq x\},&\mbox{if } v_h \leq \eta_c^h
\end{cases}\,.
\]
Thus, 
\begin{align*}
\int_0^\infty \gamma_c^\star (v_l \leq x \mid v_h)=&\int_0^{\eta_c^h} \mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h))\leq x\}F_{c,h}(\diff v_h)\\
=& \int_{0}^{\eta_c^1} \mathbf{1}\{F_{c,h}(v_h) \leq F_{c,l}(x)\}F_{c,h}(\diff v_h)\\
=& \int_0^{F_{c,h}(\eta_c^h)} \mathbf{1}\{z \leq F_{c,l}(x)\}\diff z\\
=& \min\{F_{c,h}(\eta_c^h), F_{c,l}(x)\}\\
=& F_{c,l}(x)\,,
\end{align*}
where the third equality follows from changing variables of the integration, and the last equality follows from $F_{c,l}(x) \leq F_{c,l}(\eta_c^l)=F_{c,h}(\eta_c^h)$. 

If $x \in (\eta_c^l,c]$, then 
\[
\gamma_c^\star(v_l\leq x\mid v_h)=\begin{cases}
1,&\mbox{if } v_h \leq \hat{v}_c^1\\
\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \mathbf{1}\{F_{c,l}^{-1}(\Delta_c(v^\star_c)-\Delta_c(v_h)+F_{c,l}(\eta_c^l))\leq x\},&\mbox{if } v_h>v^\star_c\\
0,&\mbox{otherwise}
\end{cases}\,.
\]
Thus, 
\begin{align*}
&\int_0^\infty \gamma_c^\star(v_l\leq x\mid v_h)F_{c,h}(\diff v_h)\\
=& F_{c,h}(\eta_c^h) +\int_{v^\star_c}^\infty \frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \mathbf{1}\{F_{c,l}^{-1}(\Delta_c(v^\star_c)-\Delta_c(v_h)+F_{c,l}(\eta_c^l)\leq x\} F_{c,h}(\diff v_h)\\
=& F_{c,h}(\eta_c^h)+\int_{v^\star_c}^\infty (f_{c,h}(v_h)-f_{c,l}(v_h)) \mathbf{1}\{\Delta_c(v^\star_c)-\Delta_c(v_h) \leq F_{c,l}(x)-F_{c,l}(\eta_c^l)\}\diff v_h\\
=& F_{c,h}(\eta_c^h)+\int_{0}^{\Delta_c(v^\star_c)} \mathbf{1}\{z \leq F_{c,l}(x)-F_{c,l}(\eta_c^l)\}\\
=& F_{c,h}(\eta_c^h)+\min\{\Delta_c(v^\star_c),F_{c,l}(x)-F_{c,l}(\eta_c^l)\}\\
=&F_{c,h}(\eta_c^h)+F_{c,l}(x)-F_{c,l}(\eta_c^l)\\
=& F_{c,l}(x)\,,
\end{align*}
where the third equality follows from changing variables of the integration, the fifth equality follows from $F_{c,l}(x)-F_{c,l}(\eta_c^l) \leq F_{c,l}(c)-F_{c,l}(\eta_c^l)=\Delta_c(v^\star_c)$, which in turn follows from the definition of $\eta_c^l$; and the last equality follows from $F_{c,h}(\eta_c^h)=F_{c,l}(\eta_c^l)$. 

If $x \in (c,v^\star_c]$, then 
\[
\gamma^\star_c(v_l \leq x\mid v_h)=\begin{cases}
1,&\mbox{if } v_h \leq \hat{v}_c^1\\
\mathbf{1}\{\lb{\Delta}_c^{-1}(F_{c,h}(v_h)-F_{c,h}(\eta_c^h)+\Delta_c(c))\leq x\},&\mbox{if } v_h \in (\eta_c^h,c]\\
\mathbf{1}\{v_h \leq x\},&\mbox{if } v_h \in (c,v^\star_c]\\
\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)},&\mbox{if } v_h>v^\star_c
\end{cases}\,.
\]
Thus, 
\begin{align*}
&\int_0^\infty \gamma^\star_c(v_l \leq x\mid v_h)F_{c,h}(\diff v_h)\\
=&\int_0^{\eta_c^h}1F_{c,h}(\diff v_h) + \int_{\eta_c^h} \mathbf{1}\{\lb{\Delta}_c^{-1}(F_{c,h}(v_h)-F_{c,h}(\eta_c^h)+\Delta_c(c))\leq x\}F_{c,h}(\diff v_h)\\
&+ \int_c^{v^\star_c} \mathbf{1}\{v_h \leq x\}F_{c,h}(\diff v_h)+\int_{v^\star_c}^\infty \frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} F_{c,h}(\diff v_h)\\
=& F_{c,h}(\eta_c^h) + \int_{\eta_c^h}^c \mathbf{1}\{F_{c,h}(v_h)-F_{c,h}(\eta_c^h) \leq \Delta_c(x)-\Delta_c(c))\}F_{c,h}(\diff v_h)+F_{c,h}(x)-F_{c,h}(c)+ \Delta_c(v^\star_c)\\
=& F_{c,h}(\eta_c^h)+\int_{0}^{F_{c,h}(c)-F_{c,h}(\eta_c^h)} \mathbf{1}\{z \leq \Delta_c(x)-\Delta_c(c)\}\diff z+F_{c,h}(x)-F_{c,h}(c)+\Delta_c(v_c^\star)\\
=& F_{c,h}(\eta_c^h)+\min\{\Delta_c(x)-\Delta_c(c), F_{c,h}(c)-F_{c,h}(\eta_c^h)\}+F_{c,h}(x)-F_{c,h}(c)+\Delta_c(v^\star_c)\\
=& F_{c,h}(\eta_c^h)+ \Delta_c(x)-\Delta_c(c)+F_{c,h}(x)-F_{c,h}(c)+\Delta_c(v^\star_c)\\
=& F_{c,h}(\eta_c^h)+F_{c,l}(x)+\Delta_c(v^\star_c)-F_{c,l}(c)\\
=& F_{c,h}(\eta_c^h)+F_{c,l}(x)-F_{c,l}(\eta_c^l)\\
=&F_{c,l}(x)\,,
\end{align*}
where the third equality follows from changing variables of the integration, the fifth equality follow from $\Delta_c(x)-\Delta_c(c) \leq \Delta_c(v^\star_c)-\Delta_c(c)=F_{c,h}(c)-F_{c,h}(\eta_c^h)$, which in turn follows from the definition of $\eta_c^h$; and the last equality also follows from the definition of $\eta_c^h$ and $\eta_c^l$. 

If $x>v^\star_c$, then 
\[
\gamma_c^\star(v_l \leq x\mid v_h)=\begin{cases}
1,&\mbox{if } v_h \leq v^\star_c\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)},&\mbox{if } v_h>v_c^\star. 
\end{cases}\,.
\]
Thus, 
\begin{align*}
&\int_0^\infty \gamma_c^\star (v_l \leq x\mid v_h) F_{c,h}(\diff v_h)\\
=& \int_0^{v^\star_c} 1 F_{c,h}(\diff v_h)+\int_{v^\star_c}^\infty \left(\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)}\right) F_{c,h}(\diff v_h)\\
=& F_{c,h}(v^\star_c)+\int_{v^\star_c}^x f_{c,l}(v_h)\diff v_h+\int_{v^\star_c}^\infty [f_{c,h}(v_h)-f_{c,l}(v_h)]\diff v_h\\
=& F_{c,h}(v^\star_c)+F_{c,l}(x)-F_{c,l}(v^\star_c)+F_{c,l}(v^\star_c)-F_{c,h}(v^\star_c)\\
=& F_{c,l}(x)\,.
\end{align*}
Together, whenever $F_{c,l}(c) \geq \|F_{c,l}-F_{c,h}\|$ and $c \leq v_c^\star$, 
\[
\rho^\star_c(v_l \leq x, v_h \in V)=\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h)F_{c,h}(\diff v_h)=F_{c,l}(x)\,,
\]
for all $x \in V$ and hence $\rho^\star_c \in \mathcal{R}_c$. 

Lastly, consider the case when $F_{c,l}(c) \geq \|F_{c,l}-F_{c,h}\|$ and $c>v^\star_c$. If $x \leq F_{c,l}^{-1}(F_{c,h}(c))$, then 
\[
\gamma^\star_c(v_l \leq x \mid v_h)=\begin{cases}
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)) \leq x\},&\mbox{if } v_h \leq c\\
0,&\mbox{if } v_h>c
\end{cases}\,.
\]
Thus, 
\begin{align*}
\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h)F_{c,h}(\diff v_h)=& \int_0^c \mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h))\leq x\}F_{c,h}(\diff v_h)\\
=& \int_0^{c} \mathbf{1}\{F_{c,h}(v_h) \leq F_{c,l}(x)\}\diff z\\
=& \int_0^{F_{c,h}(c)} \mathbf{1}\{z \leq F_{c,l}(x)\}\diff z\\
=&\min\{F_{c,h}(c),F_{c,l}(x)\}\\
=& F_{c,l}(x)\,,
\end{align*}
where the third equality follows from changing variables of the integration. 

If $x>F_{c,l}^{-1}(F_{c,h}(c))$, then 
\[
\gamma_c^\star(v_l \leq x \mid v_h)=\begin{cases}
1,&\mbox{if } v_h \leq c\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)},&\mbox{if } v_h > c\\
\end{cases}\,.
\]
Thus, 
\begin{align*}
&\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h) F_{c,h}(\diff v_h)\\
=&\int_0^c F_{c,h}(\diff v_h)+\int_c^\infty \frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\mathbf{1}\{v_h \leq x\}F_{c,h}(\diff v_h)+\int_c^\infty \frac{f_{c,l}(v_h)-f_{c,h}(v_h)}{f_{c,h}(v_h)}F_{c,h}(\diff v_h)\\
=&F_{c,h}(c)+\int_{c}^\infty \mathbf{1}\{v_h \leq x\} f_{c,l}(v_h) \diff v_h+\int_c^\infty (f_{c,h}(v_h)-f_{c,l}(v_l))\diff v_h\\
=&F_{c,h}(c)+F_{c,l}(x)-F_{c,l}(c)+F_{c,l}(c)-F_{c,h}(c)\\
=&F_{c,l}(x)\,.
\end{align*}

Together, whenever $F_{c,l}(c) \geq \|F_{c,l}-F_{c,h}\|$ and $c > v^\star_c$, 
\[
\rho^\star_c(v_l \leq x, v_h \in V)=\int_0^\infty \gamma_c^\star(v_l \leq x\mid v_h)F_{c,h}(\diff v_h)=F_{c,l}(x)\,,
\]
for all $x \in V$, and hence $\rho^\star_c \in \mathcal{R}_c$. This completes the proof. 
\end{proof}



\begin{proof}[Proof of \bref{lem:complementary_slackness}]
Consider first the case when $F_{c,l}(c)<\|F_{c,l}-F_{c,h}\|$. By construction,
\begin{align*}
\supp(\rho_c^\star)\subseteq &[0,\kappa_c^2] \times [\kappa_c^5,\infty) \cup [\kappa_c^3,\kappa_c^4] \times [0,\kappa_c^1] \\
\cup&\{(v_l,v_h): v_l=F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3))\}\\
\cup& \{(v_l,v_h): v_l=v_h\,, v_l,v_h \in [\kappa_c^3,\kappa_c^4] \cup [\kappa_c^5,\infty)\}\\
\cup& \{(v_l,v_h): v_l=F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^4))\,, v_l,v_h \in [\kappa_c^4,\kappa_c^5]\}\,.
\end{align*}
For all $(v_l,v_h) \in \supp(\rho_c^\star) \cap [0,\kappa_c^2] \times [\kappa_c^5,\infty)$, since 
\begin{align*}
\alpha_c(v_h-c) \geq \alpha_c(\kappa_c^5-c) =& \alpha_c (\kappa_c^4-c)+\kappa_c^1-c\\
=& \alpha_c(\kappa_c^4-c)+(1-\alpha_c)(\kappa_c^3-c)\\
\geq& \alpha_c(\kappa_c^3-c)+(1-\alpha_c)(\kappa_c^3-c)\\
=&\kappa_c^3-c \\
\geq& \kappa_c^2-c\\
\geq & v_l-c\,,
\end{align*}
$\Pi_c(v_l,v_h)=\alpha_c(v_h-c)$. Thus, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=\alpha_c (v_h-c)=\Pi_c(v_l,v_h)\,.
\]

For all $(v_l,v_h) \in \supp(\rho^\star_c) \cap [\kappa_c^2,\kappa_c^3] \times [\kappa_c^1,\kappa_c^3]$, it must be that $v_l=F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3))$. Moreover, since $v \mapsto \Delta_c(v)$ is increasing on $[0,v_c^\star]$, $\Delta_c(v) \leq \Delta_c(\kappa_c^3)$. Therefore, 
\[
F_{c,l}(v) \leq F_{c,h}(v)+\Delta_c(\kappa_c^3)\,,
\]
for all $v \in [\kappa_c^1,\kappa_c^3]$, and hence 
\[
v \leq F_{c,l}^{-1}(F_{c,h}(v)+\Delta_c(\kappa_c^3))
\]
for all $v \in [\kappa_c^1,\kappa_c^3]$

Therefore, for all $(v_l,v_h) \in \supp(\rho^\star_c) \cap [\kappa_c^2,\kappa_c^3] \times [\kappa_c^1,\kappa_c^3]$, it must be that 
\[
v_l=F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3)) \geq v_h\,,
\]
Together with the fact that 
\[
(1-\alpha_c) (v_l-c) \leq (1-\alpha_c)(\kappa_c^3-c) = \kappa_c^1 -c  \leq v_h-c\,,
\]
which follows from \eqref{eq:system}, it must be that 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=v_h-c=\Pi_c(v_l,v_h)\,.
\]

For all $(v_l,v_h) \in \supp(\rho^\star) \cap [\kappa_c^3,\kappa_c^4] \times [0,\kappa_c^1]$, 
\[
v_h-c \leq \kappa_c^1-c=(1-\alpha_c)(\kappa_c^3-c) \leq (1-\alpha_c)(v_l-c)\,.
\]
Therefore, $\Pi_c(v_l,v_h)=(1-\alpha_c)(v_l-c)$. As a result, 
\[
\phi_c^\star(v_l)+\psi_c^\star(v_h)=(1-\alpha_c) (v_l-c)=\Pi_c(v_l,v_h)\,.
\]


For all $(v_l,v_h) \in \supp(\rho_c^\star) \cap \{(v_l,v_h): v_l=v_h\,, v_l,v_h \in [\kappa_c^3,\kappa_c^4] \cup [\kappa_c^5,\infty)\}$, we have $\Pi_c(v_l,v_h)=v_l=v_h$. Therefore, 
\[
\phi^\star(v_l)+\psi^\star(v_h)=(1-\alpha_c)(v_l-c)+\alpha_c(v_h-c)=v_h-c=v_l-c=\Pi_c(v_l,v_h)\,. 
\]

For all $(v_l,v_h) \in \supp(\rho_c^\star) \cap \{(v_l,v_h): v_l=F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^4))\,, v_l,v_h \in [\kappa_c^4,\kappa_c^5]\}$, it must be that $v_l \leq v_h$. Indeed, since $\Delta_c$ is quasi-concave, $\Delta_c(v) \geq \Delta_c(\kappa_c^4)=\Delta_c(\kappa_c^5)$ for all $v \in [\kappa_c^4,\kappa_c^5]$. As a result, 
\[
F_{c,h}(v)+\Delta_c(\kappa_c^4) \leq F_{c,l}(v)\,,
\]
and hence 
\[
v_l =F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^4))\leq v_h\,.
\]
Therefore, $\Pi_c(v_l,v_h)=v_l-c$, and hence
\[
\phi^\star(v_l)+\psi^\star(v_h)=v_l-c=\Pi_c(v_l,v_h)\,.
\]

Together, it follows that 
\[
\phi^\star(v_l)+\psi^\star(v_h)=\Pi(v_l,v_h)
\]
for all $(v_l,v_h) \in \supp(\rho^\star)$, as desired. 

Now consider the case when $F_{c,l}(c) \geq \|F_{c,l}-F_{c,h}\|$. Note that for all $(v_l,v_h) \in \supp(\rho_c^\star)$, either $v_l=v_h$ or $\min\{v_l,v_h\}\leq c$. In both cases, we have 
\[
\Pi_c(v_l,v_h)=\alpha_c(v_h-c)^++(1-\alpha_c)(v_l-c)^+=\phi_c^\star(v_l)+\psi_v^\star(v_h)\,,
\]
a desired. 
\end{proof}



\subsection{Proofs for the Extensions}
\begin{proof}[Proof of \bref{prop:extension1}]
Since $c=0$, we slightly abuse the notation  and suppress the subscript $c$. Consider the following pair of functions $\tilde{\phi}$ and $\tilde{\psi}$: 
\[
\tilde{\phi}(v_l):=
\begin{cases}
\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1},&\mbox{if } v_l \leq \tilde{\kappa}^2\\
\frac{\tilde{\kappa}^1\tilde{\kappa}^2}{\tilde{\kappa}^1+\tilde{\kappa}^2} + \int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z,&\mbox{if } v_l \in (\tilde{\kappa}^2,\tilde{\kappa}^3]\\
\frac{v_l}{4},&\mbox{if } v_l \in (\tilde{\kappa}^3,\tilde{\kappa}^4]\\
\frac{\tilde{\kappa}^4}{4}+\int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5}\left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z,&\mbox{if } v_l \in (\tilde{\kappa}^4,\tilde{\kappa}^5]\\
\frac{v_l}{4}
+\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1},&\mbox{if } v_l>\tilde{\kappa}^5
\end{cases}
\]
and 
\[
\tilde{\psi}(v_h):=
\begin{cases}
0,&\mbox{if } v_h \leq \tilde{\kappa}^1\\
\frac{\lb{\beta}^{-1}(v_h)v_h}{v_h+\lb{\beta}^{-1}(v_h)}-\frac{\tilde{\kappa}^2\tilde{\kappa}^3}{\tilde{\kappa}^2+\tilde{\kappa}^1}-\int_{\tilde{\kappa}^1}^{\lb{\beta}^{-1}(v_h)} \left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z,&\mbox{if } v_h \in (\tilde{\kappa}^1,\tilde{\kappa}^3]\\
\frac{v_h}{4},&\mbox{if } v_h \in (\tilde{\kappa}^3,\tilde{\kappa}^4]\\
\frac{v_h\ub{\beta}^{-1}(v_h)}{v_h+\ub{\beta}^{-1}(v_h)}-\frac{\tilde{\kappa}^4}{4}-\int_{\tilde{\kappa}^4}^{\ub{\beta}^{-1}(v_h)}\left(\frac{\ub{\beta}^{-1}(z)}{z+\ub{\beta}^{-1}(z)}\right)^2 \diff z,&\mbox{if } v_h \in [\tilde{\kappa}^4,\tilde{\kappa}^5)\\
\frac{v_h}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1},&\mbox{if } v_h>\tilde{\kappa}^5
\end{cases}\,,
\]
where 
\[
\lb{\beta}(z):=F_h^{-1}(F_l(z)-F_l(\tilde{\kappa}^3)+F_h(\tilde{\kappa}^3)) 
\]
for all $z \in [\tilde{\kappa}^1,\tilde{\kappa}^3]$, and 
\[
\ub{\beta}(z):=F_h^{-1}(F_l(z)-F_l(\tilde{\kappa}^4)+F_h(\tilde{\kappa}^4))
\]
for all $z \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$. We now show that 
\begin{equation}\label{eq:feasible_dual}
\tilde{\phi}_0(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)
\end{equation}
for all $v_l,v_h$. To this end, we first establish three inequalities that follow from \eqref{eq:system2}. First, note that the function 
\[
v \mapsto \frac{\tilde{\kappa}^1v}{\tilde{\kappa}^1+v}+\int_{v}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z
\]
is decreasing in $v$. This implies that 
\begin{equation*}
\frac{\tilde{\kappa}^1\tilde{\kappa}^3}{\tilde{\kappa}^1+\tilde{\kappa}^3} \leq \frac{\tilde{\kappa}^1\tilde{\kappa}^2}{\tilde{\kappa}^1+\tilde{\kappa}^2}+\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z=\frac{\tilde{\kappa}^3}{4}\,.
\end{equation*}
Next, note that since the function 
\[
v \mapsto \frac{v}{4}-\int_{\tilde{\kappa}^2}^v \left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z
\]
is increasing in $v$, it follows that 
\[
\frac{\tilde{\kappa}^1\tilde{\kappa}^2}{\tilde{\kappa}^1+\tilde{\kappa}^2}=\frac{\tilde{\kappa}^3}{4}-\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3} \left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z \geq \frac{\tilde{\kappa}^2}{4}\,. 
\]
Together, the above two inequalities imply 
\begin{equation}\label{eq:fact1}
\tilde{\kappa}^2 \leq 3\tilde{\kappa}^1 \leq \tilde{\kappa}^3\,.
\end{equation}
Lastly, note that since 
\[
\frac{\tilde{\kappa}^5}{4}=\int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5} \left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2+\frac{1}{4}(\tilde{\kappa}^4-\tilde{\kappa}^3)+\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2\diff z \leq \int_{\tilde{\kappa}^2}^{\tilde{\kappa}^5}\left(\frac{\tilde{\kappa}^5}{z+\tilde{\kappa}^5}\right)^2 \diff z=\int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5} \frac{\diff }{\diff z} \left(\frac{\tilde{\kappa}^5z}{\tilde{\kappa}^5+z}\right) \diff z \,,
\]
it follows that 
\begin{equation}\label{eq:fact2}
\frac{\tilde{\kappa}^5}{4}=\frac{\tilde{\kappa}^5}{2}-\frac{\tilde{\kappa}^5}{4} \geq \frac{\tilde{\kappa}^5}{2}-\int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5} \frac{\diff }{\diff z} \left(\frac{\tilde{\kappa}^5z}{\tilde{\kappa}^5+z}\right) \diff z=\frac{\tilde{\kappa}^5\tilde{\kappa}^2}{\tilde{\kappa}^5+\tilde{\kappa}^2} \iff \tilde{\kappa}^5 \geq 3\tilde{\kappa}^2\,.
\end{equation}

Then, we discuss all the cases.

\mbox{}

\noindent \textbf{Case 1: }$v_l \leq \tilde{\kappa}^2$.

\noindent When $v_h \leq \tilde{\kappa}^1$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \frac{v_lv_h}{v_l+v_h}\,.
\]
Meanwhile, $3\tilde{\kappa}^2 \geq \tilde{\kappa}^2 \geq \tilde{\kappa}^1$ implies that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \frac{\tilde{\kappa}^1}{4} \geq \frac{v_h}{4}\,.
\]
Moreover, \eqref{eq:fact1} implies that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \frac{\tilde{\kappa}^2}{4} \geq \frac{v_l}{4}\,.
\]
Together, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4},\frac{v_l}{4}\right\}=\widetilde{\pi}(v_l,v_h)\,,
\]
as desired. 

When $v_h \in (\tilde{\kappa}^1,\tilde{\kappa}^3]$, from \eqref{eq:fact1}, it follows that 
\[
3v_h \geq 3\tilde{\kappa}^1 \geq \tilde{\kappa}^2 \geq v_l\,,
\]
and hence 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,.
\]
Moreover, since 
\[
v_h \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4}
\]
is increasing in $v_h$ for all $v_l \leq \tilde{\kappa}^2$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4} \geq \tilde{\phi}(v_l)+\tilde{\psi}(\tilde{\kappa}^1)-\frac{\tilde{\kappa}^1}{4}=\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1}-\frac{\tilde{\kappa}^1}{4} \geq 0\,,
\]
where the last inequality follows from \eqref{eq:fact1}.  Meanwhile, since the function 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is decreasing in $v_l$ and increasing in $v_h$, it follows that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^2)+\tilde{\psi}(\tilde{\kappa}^1)-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1}=0\,.
\]
Together, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,,
\]
as desired. 

When $v_h \in (\tilde{\kappa}^3,\tilde{\kappa}^4]$, 
\begin{align*}
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=&\frac{\tilde{\kappa}^3}{4}-\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3} \left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z+\frac{v_h}{4}\\
=&\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3} \left[\frac{1}{4}-\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2\right]\diff z+\frac{v_h}{4}+\frac{\tilde{\kappa}^2}{4}\\
\geq & \frac{v_h}{4}+\frac{\tilde{\kappa}^2}{4}\\
\geq & \max \left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4},\frac{v_h}{4}\right\}\,,
\end{align*}
as desired. 

When $v_h \in (\tilde{\kappa}^4,\tilde{\kappa}^5]$, since $v_l \leq v_h$, we have 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,.
\]
Note that the function 
\[
v_h \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4}
\]
is decreasing in $v_h$ for all $v_l \leq \tilde{\kappa}^2$. Therefore, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4} \geq \tilde{\phi}(v_l)+\tilde{\psi}(\tilde{\kappa}^5)-\frac{\tilde{\kappa}^5}{4}=0\,.
\]
Meanwhile, note that the function 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is decreasing in $v_l$ and increasing in $v_h$. Thus,
\begin{align*}
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^2)+\tilde{\psi}(\tilde{\kappa}^4)-\frac{\tilde{\kappa}^2\tilde{\kappa}^4}{\tilde{\kappa}^2+\tilde{\kappa}^4}=&\frac{\tilde{\kappa}^4}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^4}{\tilde{\kappa}^2+\tilde{\kappa}^4}-\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z\\
\geq & \frac{\tilde{\kappa}^4}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^4}{\tilde{\kappa}^2+\tilde{\kappa}^4}-\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\tilde{\kappa}^4}{z+\tilde{\kappa}^4}\right)^2 \diff z\\
=& \frac{\tilde{\kappa}^4}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^4}{\tilde{\kappa}^2+\tilde{\kappa}^4}-\frac{\tilde{\kappa}^3\tilde{\kappa}^4}{\tilde{\kappa}^3+\tilde{\kappa}^4}+\frac{\tilde{\kappa}^2\tilde{\kappa}^4}{\tilde{\kappa}^2+\tilde{\kappa}^4}\\
=&\frac{\tilde{\kappa}^4}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^3\tilde{\kappa}^4}{\tilde{\kappa}^3+\tilde{\kappa}^4}\\
\geq & 0\,.
\end{align*}
Together, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)\,,
\]
as desired. 

Lastly, when $v_h>\tilde{\kappa}^5$, by \eqref{eq:fact2}, $v_h>\tilde{\kappa}^5 \geq \tilde{\kappa}^2 \geq 3v_l$. Thus, $\widetilde{\pi}(v_l,v_h)=\nicefrac{v_h}{4}$, and hence 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{v_h}{4} = \widetilde{\pi}(v_l,v_h)\,,
\]
as desired. 

\mbox{}

\noindent \textbf{Case 2: }$v_l \in (\tilde{\kappa}^2,\tilde{\kappa}^3]$.

\mbox{}

\noindent When $v_h \leq \tilde{\kappa}^1$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4}\right\}\,.
\]
Note that 
\[
v_l \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is increasing in $v_l$ and 
\[
v_l \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_l}{4}
\]
is decreasing in $v_l$. Therefore, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^2)+\tilde{\psi}(v_h)-\frac{\tilde{\kappa}^2v_h}{\tilde{\kappa}^2+v_h}=\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1}-\frac{\tilde{\kappa}^2v_h}{\tilde{\kappa}^2+v_h} \geq 0\,,
\]
and 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_l}{4} \geq \tilde{\phi}(\tilde{\kappa}^3)+\tilde{\psi}(v_h)-\frac{\tilde{\kappa}^3}{4}=0\,,
\]
as desired. 

When $v_h \in (\tilde{\kappa}^1,\tilde{\kappa}^3]$, by \eqref{eq:fact1}, it follows that 
\[
\widetilde{\pi}(v_l,v_h)=\frac{v_lv_h}{v_l+v_h}\,.
\]
In particular, $\widetilde{\pi}$ is supermodular on $(\tilde{\kappa}^2,\tilde{\kappa}^3] \times (\tilde{\kappa}^1,\tilde{\kappa}^3]$. Therefore, since $\lb{\beta}$ is increasing, 
\[
\tilde{\phi}(v_l)=\max_{v_h' \in (\tilde{\kappa}^1,\tilde{\kappa}^3]} \left[\widetilde{\pi}(v_l,v_h')-\tilde{\psi}(v_h')\right] \geq \widetilde{\pi}(v_l,v_h)-\tilde{\psi}(v_h)\,,
\]
as desired. 

When $v_h \in (\tilde{\kappa}^3,\tilde{\kappa}^4]$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,.
\]
Note that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{\tilde{\kappa}^1\tilde{\kappa}^2}{\tilde{\kappa}^1+\tilde{\kappa}^2}+\int_{\tilde{\kappa}^2}^{v_l} \left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z+\frac{v_h}{4} \geq \frac{v_h}{4}\,.
\]
Moreover, since 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is increasing in $v_h$ and decreasing in $v_l$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^3)+\tilde{\psi}(\tilde{\kappa}^3)-\frac{\tilde{\kappa}^3}{2}=0\,.
\]
Together, $\tilde{\phi}(v_l)+\tilde{\psi}(v_h)\geq \widetilde{\pi}(v_l,v_h)$, as desired. 

When $v_h \in (\tilde{\kappa}^4,\tilde{\kappa}^5]$, note that 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4}
\]
is increasing in both $v_l$ and $v_h$. Also, 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is decreasing in $v_l$ and increasing in $v_h$. Therefore,
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4} \geq \tilde{\phi}(\tilde{\kappa}^2)+\tilde{\psi}(\tilde{\kappa}^4)-\frac{\tilde{\kappa}^4}{4}=\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq 0\,,
\]
and 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^3)+\tilde{\psi}(\tilde{\kappa}^4)-\frac{\tilde{\kappa}^3\tilde{\kappa}^4}{\tilde{\kappa}^3+\tilde{\kappa}^4}=\frac{\tilde{\kappa}^3}{4}+\frac{\tilde{\kappa}^4}{4}-\frac{\tilde{\kappa}^3\tilde{\kappa}^4}{\tilde{\kappa}^3+\tilde{\kappa}^4} \geq 0\,,
\]
as desired. 

When $v_h>\tilde{\kappa}^5$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,.
\]
Moreover, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\int_{\tilde{\kappa}^2}^{v_l}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z+\frac{v_h}{4} \geq \frac{v_h}{4}\,.
\]
Meanwhile, since 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is decreasing in $v_l$ and increasing in $v_h$, 
\begin{align*}
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq& \tilde{\phi}(\tilde{\kappa}^3)+\tilde{\psi}(\tilde{\kappa}^5)-\frac{\tilde{\kappa}^3\tilde{\kappa}^5}{\tilde{\kappa}^3+\tilde{\kappa}^5}\\
=& \int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z+\frac{\tilde{\kappa}^5}{4}-\frac{\tilde{\kappa}^3\tilde{\kappa}^5}{\tilde{\kappa}^3+\tilde{\kappa}^5}\\
=& \int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5}\left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z +\frac{\tilde{\kappa}^4}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^3\tilde{\kappa}^5}{\tilde{\kappa}^3+\tilde{\kappa}^5}\\
\geq & \frac{1}{4}(\tilde{\kappa}^5-\tilde{\kappa}^4)+\frac{\tilde{\kappa}^4}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^3\tilde{\kappa}^5}{\tilde{\kappa}^3+\tilde{\kappa}^5}\\
=& \frac{\tilde{\kappa}^5}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^3\tilde{\kappa}^5}{\tilde{\kappa}^3+\tilde{\kappa}^5}\\
\geq & 0\,,
\end{align*}
where the first inequality follows from $\ub{\beta}(z) \geq z$ for all $z \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$, which in turn is because $\tilde{\kappa}^4 \leq v^\star \leq \tilde{\kappa}^5$. 

\mbox{}

\noindent \textbf{Case 3: }$v_l \in (\tilde{\kappa}^3,\tilde{\kappa}^4]$.

\mbox{}

\noindent When $v_h \leq \tilde{\kappa}^1$, by \eqref{eq:fact1}, $v_l \geq \tilde{\kappa}^4 \geq \tilde{\kappa}^3 \geq 3\tilde{\kappa}^1 \geq 3v_h$. Thus, $\widetilde{\pi}(v_l,v_h)=\nicefrac{v_l}{4}$. Moreover, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_l)=\frac{\tilde{\kappa}^4}{4}+\int_{\tilde{\kappa}^4}^{v_l} \left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z \geq \frac{\tilde{\kappa}^4}{4}+\frac{1}{4}(v_l-\tilde{\kappa}^4) \geq \frac{v_l}{4}\,,
\]
where the inequality follows from $\ub{\beta}(z) \geq z$ for all $z \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$, which in turn is because $\tilde{\kappa}^4 \leq v^\star \leq \tilde{\kappa}^5$. 

When $v_h \in (\tilde{\kappa}^1,\tilde{\kappa}^3]$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4}\right\}\,.
\]
Note that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{v_l}{4}+\tilde{\psi}(v_h) \geq \frac{v_l}{4}\,.
\]
Moreover, since 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is increasing in $v_l$ and decreasing in $v_h$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^3)+\tilde{\psi}(\tilde{\kappa}^3)-\frac{\tilde{\kappa}^3}{2}=0\,.
\]
Thus, $\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)$. 

When $v_h \in (\tilde{\kappa}^3,\tilde{\kappa}^4]$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{v_l}{4}+\frac{v_h}{4} \geq \max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4},\frac{v_h}{4}\right\}=\widetilde{\pi}(v_l,v_h)\,.
\]

When $v_h \in (\tilde{\kappa}^4,\tilde{\kappa}^5]$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,.
\]
First note that the function 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4}
\]
is increasing in $v_l$ and decreasing in $v_h$. Thus, 
\begin{align*}
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4} \geq &\tilde{\phi}(\tilde{\kappa}^3)+\tilde{\psi}(\tilde{\kappa}^5)-\frac{\tilde{\kappa}^5}{4}\\
=& \frac{\tilde{\kappa}^3}{4}+\frac{\tilde{\kappa}^5}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1}-\frac{\tilde{\kappa}^5}{4}\\
=&\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^3}{4}+\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z\\\
\geq & 0\,.
\end{align*}
Moreover, 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is decreasing in $v_l$ and increasing in $v_h$. Therefore, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^4)+\tilde{\psi}(\tilde{\kappa}^4)-\frac{\tilde{\kappa}^4}{2}=0\,,
\]
as desired. 

When $v_h>\tilde{\kappa}^5$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,.
\]
First note that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{1}{4}(v_l+v_h)-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} +\frac{v_h}{4} =\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3} \left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z+\frac{v_h}{4} \geq \frac{v_h}{4}\,.
\]
Moreover, since 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is decreasing in $v_l$ and increasing in $v_h$, 
\begin{align*}
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq &\tilde{\phi}(\tilde{\kappa}^4)+\tilde{\psi}(\tilde{\kappa}^5)-\frac{\tilde{\kappa}^4\tilde{\kappa}^5}{\tilde{\kappa}^4+\tilde{\kappa}^5}\\
=&\frac{1}{4}(\tilde{\kappa}^4+\tilde{\kappa}^5)-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1}-\frac{\tilde{\kappa}^4\tilde{\kappa}^5}{\tilde{\kappa}^4+\tilde{\kappa}^5}\\
=& \frac{1}{4}(\tilde{\kappa}^4+\tilde{\kappa}^5)+\frac{1}{4}(\tilde{\kappa}^5-\tilde{\kappa}^4)-\int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5}\left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z-\frac{\tilde{\kappa}^4\tilde{\kappa}^5}{\tilde{\kappa}^4+\tilde{\kappa}^5}\\
=& \frac{\tilde{\kappa}^5}{2}-\frac{\tilde{\kappa}^4\tilde{\kappa}^5}{\tilde{\kappa}^4+\tilde{\kappa}^5}-\int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5} \left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z\\
=& \int_{\tilde{\kappa}^4}^{\tilde{\kappa}^5} \left[\left(\frac{\tilde{\kappa}^5}{z+\tilde{\kappa}^5}\right)^2-\left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2\right]\diff z\\
\geq & 0\,,
\end{align*}
where the last inequality follows from the fact that $\ub{\beta}(z) \leq \tilde{\kappa}^5$ for all $z \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$. Together, $\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)$, as desired. 

\mbox{}

\noindent \textbf{Case 4:} $v_l \in (\tilde{\kappa}^4,\tilde{\kappa}^5]$.

\mbox{}

\noindent When $v_h \leq \tilde{\kappa}^1$, by \eqref{eq:fact1}, $v_l \geq \tilde{\kappa}^4 \geq \tilde{\kappa}^3 \geq 3\tilde{\kappa}^1 \geq 3v_h$, and hence $\widetilde{\pi}(v_l,v_h)=\nicefrac{v_l}{4}$. Thus, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{\tilde{\kappa}^4}{4}+\int_{\tilde{\kappa}^4}^{v_l}\left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z \geq \frac{\tilde{\kappa}^4}{4}+\frac{1}{4}(v_l-\tilde{\kappa}^4)=\frac{v_l}{4}=\widetilde{\pi}(v_l,v_h)\,,
\]
where the inequality follows from the fact that $\ub{\beta}(z) \geq z$ for all $z \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$, which in turn follows from $\tilde{\kappa}^4 \leq v^\star \leq \tilde{\kappa}^5$.  

When $v_h \in (\tilde{\kappa}^1,\tilde{\kappa}^3]$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4}\right\}\,.
\]
Note that, as argued above,
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \tilde{\phi}(v_l)=\frac{\tilde{\kappa}^4}{4}+\int_{\tilde{\kappa}^4}^{v_l}\left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z \geq \frac{v_l}{4}\,.
\]
Moreover, since 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is increasing in $v_l$ and decreasing in $v_h$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^4)+\tilde{\psi}(\tilde{\kappa}^3)-\frac{\tilde{\kappa}^4\tilde{\kappa}^3}{\tilde{\kappa}^4+\tilde{\kappa}^3}=\frac{1}{4}(\tilde{\kappa}^4+\tilde{\kappa}^3)-\frac{\tilde{\kappa}^4\tilde{\kappa}^3}{\tilde{\kappa}^4+\tilde{\kappa}^3} \geq 0\,,
\]
as desired. 

When $v_h \in (\tilde{\kappa}^3,\tilde{\kappa}^4]$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4}\right\}\,.
\]
Again, as argued above,
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \tilde{\phi}(v_l)=\frac{\tilde{\kappa}^4}{4}+\int_{\tilde{\kappa}^4}^{v_l}\left(\frac{\ub{\beta}(z)}{z+\ub{\beta}(z)}\right)^2 \diff z \geq \frac{v_l}{4}\,.
\]
Meanwhile, note that the function 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is increasing in $v_l$ and decreasing in $v_h$. Thus,
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^4)+\tilde{\psi}(\tilde{\kappa}^4)-\frac{\tilde{\kappa}^4}{2}=0\,.
\]
Together, $\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)$, as desired. 

When $v_h \in (\tilde{\kappa}^4,\tilde{\kappa}^5]$, first note that, since 
\[
(v_l,v_h) \mapsto \frac{v_lv_h}{v_l+v_h}
\]
is supermodular and since $\ub{\beta}$ is increasing, by construction, 
\[
\tilde{\phi}(v_l)=\max_{v_h' \in [\tilde{\kappa}^4,\tilde{\kappa}^5]} \left[\frac{v_lv_h'}{v_l+v_h'}-\psi(v_h')\right] \geq \frac{v_lv_h}{v_l+v_h}-\tilde{\psi}(v_h)\,,
\]
and thus 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)\,.
\]
Next, note that since the function 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4}
\]
is increasing in $v_l$ and decreasing in $v_h$,
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_h}{4} \geq \tilde{\phi}(\tilde{\kappa}^4)+\tilde{\psi}(\tilde{\kappa}^5)-\frac{\tilde{\kappa}^5}{4}=\frac{\tilde{\kappa}^4}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1}=\frac{\tilde{\kappa}^4}{4}-\frac{\tilde{\kappa}^3}{4}+\int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z \geq 0\,.
\]
Lastly, note that since the function 
\begin{equation}\label{eq:4.1}
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_l}{4}
\end{equation}
is increasing in both $v_l$ and $v_h$, 
\begin{equation}\label{eq:4.2}
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_l}{4} \geq \tilde{\phi}(\tilde{\kappa}^4)+\tilde{\psi}(\tilde{\kappa}^4)-\frac{\tilde{\kappa}^4}{4}=\frac{\tilde{\kappa}^4}{4} \geq 0\,.
\end{equation}
Together, we have that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)\,,
\]
as desired. 

When $v_h>\tilde{\kappa}^5$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_h}{4}\right\}\,.
\]
Note that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \frac{\tilde{\kappa}^4}{4}+\frac{v_h}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \frac{\tilde{\kappa}^3}{4} +\frac{v_h}{4}-\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1}= \int_{\tilde{\kappa}^2}^{\tilde{\kappa}^3}\left(\frac{\lb{\beta}(z)}{z+\lb{\beta}(z)}\right)^2 \diff z +\frac{v_h}{4} \geq \frac{v_h}{4}\,.
\]
Moreover, since the function 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is decreasing in $v_l$ and is increasing in $v_h$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^5)+\tilde{\psi}(\tilde{\kappa}^5)-\frac{\tilde{\kappa}^5}{2}=0\,.
\]
Together, $\tilde{\psi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)$, as desired. 

\mbox{}

\noindent \textbf{Case 5:} $v_l>\tilde{\kappa}^5$.

\mbox{}

\noindent When $v_h \leq \tilde{\kappa}^1$, by \eqref{eq:fact1}, $v_l \geq \tilde{\kappa}^5 \tilde{\kappa}^3 \geq 3\tilde{\kappa}^1 \geq 3v_h$, and hence $\widetilde{\pi}(v_l,v_h)=\nicefrac{v_l}{4}$. Thus, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_l) = \frac{v_l}{4}+\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \frac{v_l}{4} = \widetilde{\pi}(v_l,v_h)\,,
\]
as desired. 

When $v_h \in (\tilde{\kappa}^1,\tilde{\kappa}^3]$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4}\right\}\,.
\]
Note that 
\[
\tilde{\phi(v_l)}+\tilde{\psi}(v_h)\geq \tilde{\phi(v_l)} \geq \frac{v_l}{4}\,,
\]
as argued above. Moreover, since 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is increasing in $v_l$ and decreasing in $v_h$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^5)+\tilde{\psi}(\tilde{\kappa}^3)-\frac{\tilde{\kappa}^5\tilde{\kappa}^3}{\tilde{\kappa}^5+\tilde{\kappa}^3}
=\frac{\tilde{\kappa}^5}{4}+\frac{\tilde{\kappa}^3}{4}-\frac{\tilde{\kappa}^5\tilde{\kappa}^3}{\tilde{\kappa}^5+\tilde{\kappa}^3}+\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^5} \geq 0\,.
\]
Together, $\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)$, as desired. 

When $v_h \in (\tilde{\kappa}^3,\tilde{\kappa}^4]$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{v_l}{4}+\frac{v_h}{4}+\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \max \left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4},\frac{v_h}{4}\right\}=\widetilde{\pi}(v_l,v_h)\,,
\]
as desired. 

When $v_h \in (\tilde{\kappa}^4,\tilde{\kappa}^5]$, 
\[
\widetilde{\pi}(v_l,v_h)=\max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4}\right\}\,.
\]
Note that 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \tilde{\phi}(v_l)=\frac{v_l}{4}+\frac{\tilde{\kappa}^2\tilde{\kappa}^1}{\tilde{\kappa}^2+\tilde{\kappa}^1} \geq \frac{v_l}{4}\,.
\]
Moreover, since the function 
\[
(v_l,v_h) \mapsto \tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h}
\]
is increasing in $v_l$ and is decreasing in $v_h$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)-\frac{v_lv_h}{v_l+v_h} \geq \tilde{\phi}(\tilde{\kappa}^5)+\tilde{\psi}(\tilde{\kappa}^5)-\frac{\tilde{\kappa}^5}{2}=0\,.
\]
Together, $\tilde{\phi}(v_l)+\tilde{\psi}(v_h) \geq \widetilde{\pi}(v_l,v_h)$, as desired. 

When $v_h>\tilde{\kappa}^5$, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{1}{4}(v_l+v_h) \geq \max\left\{\frac{v_lv_h}{v_l+v_h},\frac{v_l}{4},\frac{v_h}{4}\right\}\,,
\]
as desired. 


Next, let 
\begin{align*}
&\tilde{\gamma}^\star_c(v_l \leq x \mid v_h):=\\
&\begin{cases}
\mathbf{1}\{\lb{\Delta}_c^{-1}(F_{c,h}(v_h+\Delta_c(\tilde{\tilde{\kappa}}_c^3)) \leq x\},& \mbox{if } v_h \leq \tilde{\tilde{\kappa}}_c^1\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\tilde{\tilde{\kappa}}_c^3)) \leq x\},&\mbox{if } v_h \in (\tilde{\tilde{\kappa}}_c^1,\tilde{\tilde{\kappa}}^3_c]\\
\mathbf{1}\{v_h \leq x\},& \mbox{if } v_h \in (\tilde{\tilde{\kappa}}_c^3,\tilde{\tilde{\kappa}}_c^4]\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\tilde{\tilde{\kappa}}_c^4)) \leq x\}, &\mbox{if } v_h \in (\tilde{\tilde{\kappa}}_c^4,\tilde{\tilde{\kappa}}_c^5]\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\cdot \mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \cdot \mathbf{1}\{F_{c,l}^{-1}(\Delta_c(\tilde{\tilde{\kappa}}_c^5)-\Delta_c(v_h)) \leq x\},&\mbox{if } v_h > \tilde{\tilde{\kappa}}_c^5,
\end{cases}\,,
\end{align*}
for all $x \in V$ and for all $v_h \in V$. 

Then, let $\tilde{\rho}_c^\star \in \Delta(V \times V)$ be defined as 
\begin{equation}\label{eq:sol}
\tilde{\rho}_c^\star(v_l \in A, v_h \in B):=\int_B \gamma_c^\star(A\mid v_h) F_{c,h}(\diff v_h)\,,
\end{equation}
for all measurable sets $A,B \subseteq V$. By construction, the marginals of $\rho_c^\star$ are exactly $F_{c,l}$ and $F_{c,h}$. That is, $\tilde{\rho}_c^\star \in \mathcal{R}_c$.

It remains to show that for any $(v_l,v_h) \in \supp(\tilde{\rho})$, $\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\widetilde{\pi}(v_l,v_h)$. To see this, consider any $(v_l,v_h) \in \supp(\tilde{\rho})$. If $v_l \leq \tilde{\kappa}^2$, it must be that $v_h \geq \tilde{\kappa}^5$. By \eqref{eq:fact2}, $\widetilde{\pi}(v_l,v_h)=\nicefrac{v_h}{4}$. Therefore, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{v_h}{4}=\widetilde{\pi}(v_l,v_h)\,,
\]
as desired. If $v_l \in (\tilde{\kappa}^2,\tilde{\kappa}^3]$, then it must be that $v_h=\lb{\beta}(v_l)$. By \eqref{eq:fact1}, it follows that 
\[
\widetilde{\pi}(v_l,v_h)=\frac{v_lv_h}{v_l+v_h}\,.
\]
Therefore, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\tilde{\phi}(v_l)+\tilde{\psi}(\lb{\beta}(v_l))=\frac{v_l\lb{\beta}(v_l)}{v_l+\lb{\beta}(v_l)}=\widetilde{\pi}(v_l,\lb{\beta}(v_l))=\widetilde{\pi}(v_l,v_h)\,,
\]
as desired. If $v_l \in (\tilde{\kappa}^3,\tilde{\kappa}^4]$, then it must be that $v_h=v_l$. Therefore, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{v_l}{2}=\widetilde{\pi}(v_l,v_l)=\widetilde{\pi}(v_l,v_h)\,,
\]
as desired. If $v_l \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$, it must be that $v_h=\ub{\beta}(v_l)$, and thus
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\tilde{\phi}(v_l)+\tilde{\psi}(\ub{\beta}(v_l))=\frac{v_l\ub{\beta}(v_l)}{v_l+\ub{\beta}(v_l)}\,. 
\]
Moreover, by \eqref{eq:4.1}, 
\[
\frac{v_l\ub{\beta}(v_l)}{v_l+\ub{\beta}(v_l)}=\tilde{\phi}(v_l)+\tilde{\psi}(\ub{\beta}(v_l))\geq \frac{\ub{\beta}(v_l)}{4}\,.
\]
Likewise, by \eqref{eq:4.2}, 
\[
\frac{v_l\ub{\beta}(v_l)}{v_l+\ub{\beta}(v_l)}=\tilde{\phi}(v_l)+\tilde{\psi}(\ub{\beta}(v_l))\geq \frac{v_l}{4}\,.
\]
Together, for any $v_l \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$,
\[
\frac{v_l\ub{\beta}(v_l)}{v_l+\ub{\beta}(v_l)} \geq \max\left\{\frac{v_l}{4},\frac{\ub{\beta}(v_l)}{4}\right\}
\]
and thus 
\[
\widetilde{\pi}(v_l,\ub{\beta}(v_l))=\frac{v_l\ub{\beta}(v_l)}{v_l+\ub{\beta}(v_l)}
\]
for all $v_l \in [\tilde{\kappa}^4,\tilde{\kappa}^5]$. As a result,
\begin{align*}
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=&\tilde{\phi}(v_l)+\tilde{\psi}(\ub{\beta}(v_l))\\
=&\frac{v_l\ub{\beta}(v_l)}{v_l+\ub{\beta}(v_l)}\\
=& \widetilde{\pi}(v_l,\ub{\beta}(v_l))\\
=& \widetilde{\pi}(v_l,v_h)\,,
\end{align*}
as desired. Lastly, for any $v_l >\tilde{\kappa}^5$, it must be that $v_h=v_l$. Therefore, 
\[
\tilde{\phi}(v_l)+\tilde{\psi}(v_h)=\frac{v_l}{2}=\widetilde{\pi}(v_l,v_l)=\widetilde{\pi}(v_l,v_h)\,,
\]
as desired. Together, this completes the proof. 
\end{proof}

\begin{proof}[Proof of \bref{prop:welfare}]
By \bref{prop:opt-transport}, any optimal non-discriminatory pricing rule $p$ can be identified by a family $\{\rho_c\}_{c \in C}$ of matching schemes, where $\rho_c \in \mathcal{R}_c$ is a solution of 
\[
\max_{\rho \in \mathcal{R}_c} \int_{V^2} \pi_c(v_l,v_h) \diff \rho,.
\]
Thus, it suffices to consider the solutions of the optimal transport problem \eqref{eq:transport-point} for each $c$.   

When $F_{c,l}(c) \geq \|F_{c,l}-F_{c,h}\|$, since $\pi^\star(c)=\EE[(v-c)^+]$, it must be that $CS(c,h;p)=CS(c,l;p)=0$. Now suppose that $F_{c,l}(c)< \|F_{c,l}-F_{c,h}\|$. Fix any such $c \in C$, consider any solution $\rho_c$ of the optimal transport problem \eqref{eq:transport-point}. By \bref{lem:dual}, for any solution $\rho_c$ of \eqref{eq:transport-point}, it must be that 
\[
\phi^\star_c(v_l)+\psi^\star_c(v_h)=\pi_c(v_l,v_h)\,,
\]
for all $(v_l,v_h) \in \supp (\rho_c)$. Therefore, we have 
\begin{align}\label{eq:supp}
\supp(\rho_c) \subseteq [0,\kappa_c^3] \times [\kappa_c^5,\infty) \cup &\{(v_l,v_h) \in [\kappa_c^1,\kappa_c^3] \times [\kappa_c^1,\kappa_c^3]: v_l \geq v_h\} \notag\\
\cup& [\kappa_c^3,\kappa_c^4] \times [0,\kappa_c^1] \notag\\
\cup& \{(v_l,v_h) \in [\kappa_c^3,\kappa_c^4] \times [\kappa_c^3,\kappa_c^4]: v_l=v_h\}\\
\cup& \{(v_l,v_h) \in [\kappa_c^4,\kappa_c^5] \times [\kappa_c^4,\kappa_c^5]: v_l \leq v_h\} \notag\\
\cup& \{(v_l,v_h) \in [\kappa_c^5,\infty) \times [\kappa_c^5,\infty): v_l=v_h\} \notag
\end{align}

Now consider any optimal non-discriminatory pricing rule $p$. By \bref{prop:opt-transport}, there exists $\{\rho_c\}_{c \in C}$ such that $\rho_c$ is a solution of \eqref{eq:transport-point} for all $c \in C$ and that for almost all $c \in C$ and for almost all matched pair $(v_l,v_h) \in \mathrm{supp}(\rho_c)$, these consumers face a price that equals 
\[
\argmax_{x \in \{v_l,v_h\}} (x-c)[\alpha_c \mathbf{1}\{v_h \geq x\}+(1-\alpha_c)\mathbf{1}\{v_l \geq x\}]\,.
\]

Let $\{\rho_c\}_{c \in C}$ be the family of matching schemes associated with the non-discriminatory pricing rule $p$. Note that for any $(v_l, v_h) \in [\kappa_c^3,\kappa_c^4] \times [0,\kappa_c^1]$, $(1-\alpha_c) (v_l-c) \geq (1-\alpha_c) (\kappa_c^3-c)=\kappa_c^1-c \geq v_h-c$. Therefore, the optimal price for these matched pairs equals $v_h$, and hence $h$-consumers purchase at a price equals their values, whereas $l$-consumers do not purchase. In particular, these consumers retain zero surplus, just as under $p^\star$. Likewise, for any $(v_l,v_h) \in [0,\kappa_c^3] \times [\kappa_c^5,\infty)$, $\alpha_c (v_h-c) \geq \alpha_c (\kappa_c^5-c)=\alpha_c (\kappa_c^4-c)+(1-\alpha_c)(\kappa_c^3-c) \geq \alpha_c \kappa_c^3-c+(1-\alpha_c)(\kappa_c^3-c)=\kappa_c^3-c \geq v_l-c$. Thus, the optimal price for these matched pairs $(v_l,v_h)$ must equal $v_h$, and thus $h$-consumers purchase by paying their values, whereas $l$-consumers do not purchase, just as under $p^\star$. Furthermore, for any $(v_l,v_h) \in [\kappa_c^4,\kappa_c^5] \times [\kappa_c^4,\kappa_c^5]$ such that $v_l \leq v_h$, $\alpha_c (v_h-c) \leq \alpha_c( (\kappa_c^5-c)=\alpha_c (\kappa_c^4-c)+(1-\alpha_c)(\kappa_c^3-c) = \alpha_c (\kappa_c^4-c)+(1-\alpha_c)(\kappa_c^3-c) \leq \kappa_c^4-c \leq v_l-c$. The optimal price for these matched pairs $(v_l,v_h)$ must equals $v_l$, and hence both $\theta_l$ and $\theta_h$ consumers purchase by paying the value of $l$-consumers, just as under $p^\star$. Together, the pricing rule $p$ must lead to the same outcomes as $p^\star$ for matched pairs $(v_l,v_h)$ in $[0,\kappa_c^1] \times [\kappa_c^5,\infty)$, $\{(v_l,v_h) \in [\kappa_c^3,\kappa_c^4] \times [0,\kappa_c^1]: v_l \geq v_h\}$, and $\{(v_l,v_h) \in [\kappa_c^4,\kappa_c^5] \times [\kappa_c^4,\kappa_c^5]: v_l \leq v_h\}$.
In the meantime, for any matched pair $(v_l,v_h) \in [\kappa_c^1,\kappa_c^3] \times [\kappa_c^1,\kappa_c^3]$, since $(1-\alpha_c) (v_l-c) \leq (1-\alpha_c)(\kappa_c^3-c)=\kappa_c^1-c \leq v_h-c$, the optimal price for these matched pairs must be $v_h$.

Together, we have
\[
CS(c,h;p)=CS(c,h;p^\star)=\int_{F_{c,h}(\kappa_c^4)}^{F_{c,h}(\kappa_c^5)}(F_{c,h}^{-1}(q)-F_{c,l}^{-1}(q+F_{c,h}(\kappa_c^4)-F_{c,l}(\kappa_c^4)))\diff q\,;
\]
\[
WL(c,h;p)=WL(c,h;p^\star)=\int_0^{\kappa_c^1} v F_{c,h}(\diff v)\,;
\]
\[
CS(c,l;p)=\int_{[\kappa_c^1,\kappa_c^3]^2} (v_l-v_h) \rho(\diff v_l,\diff v_h)\,;
\]
and 
\[
WL(c,l;p)=\int_0^{\kappa_c^1}v F_{c,l}(\diff v)+ \int_{[\kappa_c^1,\kappa_c^3] \times [\kappa_c^5,\infty)} v_l \rho(\diff v_l,\diff v_h) 
\]
By \eqref{eq:supp}, $\rho_c(v_l \notin [\kappa_c^1,\kappa_c^3],v_h \in [\kappa_c^1,x])=0$ and $\rho_c(v_l \in [\kappa_c^1,\kappa_c^3], v_h \notin [\kappa_c^1,\kappa_c^3])=\rho_c(v_l \in[\kappa_c^1,x], v_h > \kappa_c^5)$, for all $x \in [\kappa_c^1,\kappa_c^3]$. Thus,
\begin{align*}
\rho_c(v_l \in [\kappa_c^1,\kappa_c^3], v_h \in [\kappa_c^1,x])=&\rho(v_l \in V, v_h \in [\kappa_c^1,x])-\rho_c(v_l \notin [\kappa_c^1,\kappa_c^3],v_h \in [\kappa_c^1,x])\\
=& F_{c,h}(x)-F_{c,h}(\kappa_c^1)\,,
\end{align*}
and  
\begin{align*}
\rho_c(v_l \in [\kappa_c^1,x], v_h \in [\kappa_c^1,\kappa_c^3])=& \rho_c(v_l \in [\kappa_c^1,x],v_h \in V)-\rho_c(v_l \in [\kappa_c^1,x], v_h \notin [\kappa_c^1,\kappa_c^3])\\
=& F_{c,l}(x)-F_{c,l}(\kappa_c^1)-\rho(v_l \in [\kappa_c^1,x],v_h>\kappa_c^5)\,, 
\end{align*}
for all $x \in [\kappa_c^1,\kappa_c^3]$. Moreover, by \eqref{eq:supp}, since $\rho_c \in \mathcal{R}_c$, it must be that 
\[
\rho(v_l \in [0,\kappa_c^3],v_h>\kappa_c^5)=\Delta_c(\kappa_c^5)\,.
\]
Together with the fact that $F_{c,l}(\kappa_c^2)=\Delta_c(\kappa_c^5)$, it follows that 
\begin{equation}\label{eq:rhobound}
\min\{F_{c,l}(x),F_{c,l}(\kappa_c^2)\} \geq \rho_c(v_l \in [\kappa_c^1,x], v_h>\kappa_c^5)\,.
\end{equation}
As a result, 
\begin{align*}
CS(c,l;p)=&\int_{[\kappa_c^1,\kappa_c^3]^2} (v_l-v_h) \rho_c(\diff v_l, \diff v_h)\\=& \int_{\kappa_c^1}^{\kappa_c^3} v_l F_{c,l}(\diff v_l)-\int_{\kappa_c^1}^{\kappa_c^3} v_l \rho_c(\diff v_l, v_h>\kappa_c^5)-\int_{\kappa_c^1}^{\kappa_c^3} v_h F_{c,h}(\diff v_h)\\
\leq & \int_{\kappa_c^1}^{\kappa_c^3} v F_{c,l}(\diff v)-\int_{\kappa_c^1}^{\kappa_c^2} v F_{c,l}(\diff v)-\int_{\kappa_c^1}^{\kappa_c^3}v F_{c,h}(\diff v)\\
=& \int_{\kappa_c^2}^{\kappa_c^3} v F_{c,l}(\diff v)-\int_{\kappa_c^1}^{\kappa_c^3} v F_{c,h}(\diff v)\\
=& \int_{F_{c,l}(\kappa_c^2)}^{F_{c,l}(\kappa_c^3)} F_{c,l}^{-1}(q) \diff q -\int_{F_{c,h}(\kappa_c^1)}^{F_1(\kappa_c^3)} F_{c,h}^{-1}(q) \diff q\\
=& \int_{F_{c,l}(\kappa_c^2)}^{F_{c,l}(\kappa_c^3)} (F_{c,l}^{-1}(q)-F_{c,h}^{-1}(q+F_{c,h}(\kappa_c^3)-F_{c,l}(\kappa_c^3)))\diff q\\
=&CS(c,l;p^\star)\,,
\end{align*}
where the inequality follows from \eqref{eq:rhobound} and the last equality follows from \eqref{eq:system}. Likewise, 
\begin{align*}
WL(c,l;p)=& \int_0^{\kappa_c^1} v F_{c,l}(\diff v) +\int_{[\kappa_c^1,\kappa_c^3] \times [\kappa_c^5,\infty)} v_l \rho_c(\diff v_l, \diff v_h) \\
\geq & \int_0^{\kappa_c^1} v F_{c,l}(\diff v)+\int_{\kappa_c^1}^{\kappa_c^2} v F_{c,l}(\diff v)\\
=& \int_0^{\kappa_c^2} v F_{c,l}(\diff v)\,,
\end{align*}
where the inequality follows from \eqref{eq:rhobound}. Together, we have that 
\[
CS(c,h;p)=CS(c,h;p^\star)\,; \mbox{ and } WL(c,h;p)=WL(c,h;p^\star)\,,
\]
while 
\[
0 \leq CS(c,l;p) \leq CS(c,l;p^\star)
\]
for all $c \in C$. Since 
\[
\pi^\star(c)+\sum_{\theta \in \{l,h\}} [CS(c,\theta;p)+WL(c,\theta;p)]\,,
\]
it then follows that 
\[
WL(c,l;p^\star) \leq WL(c,l;p) \leq \int_0^{\kappa_c^1} v_l F_{c,l}(\diff v_l)+\int_{\kappa_c^1}^{\kappa_c^3} v (f_{c,l}(v)-f_{c,h}(v))\diff v\,.
\]

It now remains to show that for any $c$ and for any $\sigma_{c,l}$ 
\[
0 \leq \sigma_{c,l} \leq CS(c,l;p^\star)
\]
there exists $\rho_c \in \mathcal{R}_c$ that solves \eqref{eq:transport-point} such that 
\[
\int_{[\kappa_c^1,\kappa_c^3]}(v_l-v_h) \rho_c(\diff v_l,\diff v_h)=\sigma_{c,l}
\]

To this end, for each $c \in C$, let
\begin{align*}
\tilde{\gamma}_c(v_l \leq x \mid v_h):=
\begin{cases}
\mathbf{1}\{\lb{\Delta}_c^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^3)) \leq x\},& \mbox{if } v_h \leq \kappa_c^1\\
\mathbf{1}\{v_h \leq x\},&\mbox{if } v_h \in (\kappa_c^1,\kappa_c^4]\\
\mathbf{1}\{F_{c,l}^{-1}(F_{c,h}(v_h)+\Delta_c(\kappa_c^4)) \leq x\}, &\mbox{if } v_h \in (\kappa_c^4,\kappa_c^5]\\
\frac{f_{c,l}(v_h)}{f_{c,h}(v_h)}\cdot \mathbf{1}\{v_h \leq x\}+\frac{f_{c,h}(v_h)-f_{c,l}(v_h)}{f_{c,h}(v_h)} \cdot \mathbf{1}\{J_c^{-1}(\Delta_c(\kappa_c^5)-\Delta_c(v_h)) \leq x\},&\mbox{if } v_h > \kappa_c^5,
\end{cases}\,,
\end{align*}
where 
\[
J_c(v):=\begin{cases}
\min\{F_{c,l}(v),\Delta_c(v)+F_{c,h}(\kappa_c^1)\},&\mbox{if } v \leq \kappa_c^3\\
\Delta_c(\kappa_c^3)+F_{c,h}(\kappa_c^3),&\mbox{if } v>\kappa_c^3
\end{cases}
\]
for all $v \in V$. By the same argument as the proof of \bref{lem:rfeas}, $\tilde{\gamma}_c$ is indeed a transition probability. Then, let
\[
\tilde{\rho}_c(v_l \in A, v_h \in B):=\int_{B} \tilde{\gamma}_c(A\mid v_h)F_{c,h}(\diff v_h)\,.
\]
Since $\rho_c^\star \in \mathcal{R}_c$ and since $F_{c,l}(\kappa_c^2)=\Delta_c(\kappa_c^5)$, it follows that $\tilde{\rho}_c \in \mathcal{R}_c$ as well. Moreover, for all $(v_l,v_h) \in \supp(\tilde{\rho}_c)$, $\phi_c^\star(v_l)+\psi_c^\star(v_h)=\pi_c(v_l,v_h)$. Thus, by \bref{lem:dual}, $\tilde{\rho}_c$ solves \eqref{eq:transport-point}. In the meantime, by construction, $v_l=v_h$ for all $(v_l,v_h) \in \supp(\tilde{\rho}_c) \cap [\kappa_c^1,\kappa_c^3] \times [\kappa_c^1,\kappa_c^3]$. Therefore, 
\[
\int_{[\kappa_c^1,\kappa_c^3]^2} (v_l-v_h) \diff \tilde{\rho}_c=0\,.
\]
Therefore, for any $c$ and for any $\sigma_c,l \in [0, CS(c,l;p^\star)]$, 
\[
\rho_c:=\frac{\sigma_{c,l}}{CS(c,l;p^\star)} \rho^\star_c+\left(1-\frac{\sigma_{c,l}}{CS(c,l;p^\star)}\right) \tilde{\rho}_c\,.
\]
Since $\mathcal{R}_c$ is convex and since both $\rho_c^\star$ and $\tilde{\rho}_c$ are solutions of \eqref{eq:transport-point}, $\rho_c$ is in $\mathcal{R}_c$ solves \eqref{eq:transport-point} as well. Moreover,
\begin{align*}
\int_{[\kappa_c^1,\kappa_c^3]^2} (v_l-v_h) \diff \rho_c=&\frac{\sigma_{c,l}}{CS(c,l;p^\star)} \int_{[\kappa_c^1,\kappa_c^3]^2} (v_l-v_h) \diff \rho_c^\star+\left(1-\frac{\sigma_{c,l}}{CS(c,l;p^\star)}\right) \int_{[\kappa_c^1,\kappa_c^3]^2} (v_l-v_h) \tilde{\rho}_c\\
=&CS(c,l;p^\star) \cdot \frac{\sigma_{c,l}}{CS(c,l;p^\star)}+0 \cdot \left(1-\frac{\sigma_{c,l}}{CS(c,l;p^\star)}\right) \\
=&\sigma_{c,l}\,,
\end{align*}
as desired. This completes the proof. 
\end{proof}
\subsection{More on the Partly Anti-Assortative Pricing Rule}
Consider any partly anti-assortative pricing rule $p^{anti}$ with quantiles $\{q_c\}_{c \in C}$. Note that all consumers with $\theta=h$ and $v \geq c$ would purchase and pay their values. For $l$-consumers, if $v < F_{c,l}^{-1}(q_c)$, then since 
\[
F_{c,l}(x) \geq F_{c,h}(x) > F_{c,h}(x)-(1-q_c) 
\]
for all $x$, 
\[
p^{anti}(v,c,l)=F_{c,h}^{-1}(F_{c,l}(v)+(1-q_c)) > v\,,
\]
and thus they would not purchase. In the meantime, if $v \geq F_{c,l}^{-1}(q_c)$, note that 
\[
p^{anti}(v,c,l)=F_{c,h}^{-1}(F_{c,l}(v)-q_c) \leq v
\]
if and only if 
\[
F_{c,l}(v)-F_{c,h}(v)=\Delta_c(v) \leq q_c\,.
\]
Therefore, such a consumer would purchase if and only if $\Delta_c(v) \leq q_c$, and will purchase at a price $F_{c,h}^{-1}(F_{c,l}(v)-q_c)$. As a result, for any $c \in C$, the smallest $q_c$ such that all consumers with $\theta=l$ and $v \geq F_{c,l}^{-1}(q_c)$ would purchase is $q_c=\Delta_c(v^\star_c)$. In this case, the seller's profit is given by 
\[
\E{(p^{anti}-c)\mathbf{1}\{v \geq p^{anti}\}}=\alpha_c \int_V (v-c)^+ F_{c,h}(\diff v)+(1-\alpha_c)\left[\int_0^{F_{c,h}^{-1}(1-q_c)}(v-c)^+F_{c,h}(\diff v)\right]\,.
\]


\subsection{Assumption \ref{ass:no-full-surplus-extraction} under a Scaled Family}
Suppose that there exists $F_h,F_l$ such that $F_{c,h}(x)=F_h(\nicefrac{x}{c})$ and $F_{c,l}(x)=F_{l}(\nicefrac{x}{c})$ for all $c$ and for all $x$. Then 
\begin{align*}
\|F_{c,l}-F_{c,h}\|=&\max_{v} \Delta_c(v)=\max_v [F_{c,l}(v)-F_{c,h}(v)]\\
=&\max_{v} \left[F_{l}\left(\frac{v}{c}\right)-F_{h}\left(\frac{v}{c}\right)\right]\\
=&\max_{\tilde{v}} [F_{l}(\tilde{v})-F_{h}(\tilde{v})] \tag{$\tilde{v}=\frac{v}{c}$}\\
=&\|F_l-F_h\|\,.
\end{align*}
Therefore, \bref{ass:no-full-surplus-extraction} is equivalent to 
\[
F_{c,l}(c)=F_l(1)<\|F_l-F_h\|=\|F_{c,l}-F_{c,h}\|\,.
\]

Furthermore, suppose that $\alpha_c=\alpha$ for all $c \in C$. Let $\kappa_1$ be the solution to \eqref{eq:system} when $c=1$, and let $\kappa_c:=c\cdot \kappa_1$. Then, for all $c \in C$, $F_{c,l}(\kappa_c^j)=F_{1,l}(\kappa_1^j)$ and $F_{c,h}(\kappa_c^j)=F_{1,h}(\kappa_1^j)$ for all $j \in \{1,2,3,4,5\}$, and 
\[
\kappa_c^1-c=c(\kappa_c^1-1)=c\alpha(\kappa_1^3-1)=(1-\alpha)(\kappa_c^3-c)
\]
while 
\[
(1-\alpha)(\kappa_c^3-c)=c(1-\alpha)(\kappa_1^3-1)=c\alpha(\kappa_1^5-\kappa_1^4)=\alpha(\kappa_c^5-\kappa_c^4)\,.
\]
Therefore, $\kappa_c=c\cdot \kappa_1$ must solve \eqref{eq:system}.

Now suppose that $F_{c,l}(v)=1-e^{-v/\lambda_l c}$ and $F_{c,h}(v)=1-e^{-v/\lambda_h c}$ for all $v \geq 0$ and for some $0<\lambda_l<\lambda_h$. Let $\gamma:=\nicefrac{\lambda_h}{\lambda_l}$. Then, $\Delta_c(v)=e^{-v/\lambda_h c}-e^{-v/\lambda_lc}$ for all $v \geq 0$. Moreover, since $v^\star_c$ is the unique maximize of $\Delta_c$, by the first order condition, $\Delta_c'(v^\star_c)=f_{c,l}(v^\star_c)-f_{c,h}(v^\star_c)=0$. Therefore, 
\[
\gamma=\frac{\lambda_h}{\lambda_l}=\exp\left(\frac{-v^\star_c}{\lambda_h c}+\frac{v^\star_c}{\lambda_l c}\right)=\exp\left(-\frac{v^\star_c}{\lambda_h c}(1-\gamma)\right)\,.
\]
Therefore, 
\[
\exp\left(-\frac{v^\star_c}{\lambda_h c}\right)=\gamma^{-\frac{1}{\gamma-1}}
\]
and 
\[
\exp\left(-\frac{v^\star_c}{\lambda_l c}\right)=\left(\exp\left(-\frac{v^\star_c}{\lambda_h c}\right)\right)^{\frac{\lambda_h}{\lambda_l}}=\gamma^{-\frac{\gamma}{\gamma-1}}\,.
\]
As a result, 
\[
\Delta_c(v^\star_c)=\exp\left(-\frac{v^\star_c}{\lambda_h c}\right)-\exp\left(-\frac{v^\star_c}{\lambda_l c}\right)=\gamma^{-\frac{1}{\gamma-1}}-\gamma^{-\frac{\gamma}{\gamma-1}}=\gamma^{-\frac{\gamma}{\gamma-1}}(\gamma-1)\,,
\]
and hence \bref{ass:no-full-surplus-extraction} simplifies to 
\[
F_{c,l}(c)=1-e^{\frac{-1}{\lambda_l}}<\gamma^{-\frac{\gamma}{\gamma-1}}(\gamma-1)=\Delta_c(v^\star_c)\,.
\]
\end{document}

