\section{Introduction }\label{Sec.1}

\noindent Anisotropic differential equations arise in the study of physical and geometric phenomena where properties vary with direction: this type of differential equations capture directional dependencies in media such as crystals, layered materials, or biological tissues for that they are crucial in fields such as image processing, material science, and fluid dynamics. In the existing literature, which is already extensive, various anisotropic parabolic equations have been considered, depending on whether they relate to the porous medium equation or the parabolic $p$-Laplacean equation. So for anisotropic porous medium equations, the most common evolution equations in the literature associated with fluid flow in an anisotropic medium are
\begin{equation*}
u_t = \sum_{i=1}^n \left( u^{m_i-1} \ u_{x_i}\right)_{x_i} \ , \quad m_i>0, \ \ \forall i=1, \cdots, n
\end{equation*}
and
\begin{equation*}
u_t = \mathrm{div} \left( u^{\gamma(x,t)} Du \right), \quad \mbox{where $\gamma$ is a bounded function.}
\end{equation*}
While for anisotropic equations associated (in some sense) with the p-Laplacian,  very likely due to the mathematical interest and range of applications, there are more records of anisotropic equations, among which we highlight:
\begin{equation*}
u_t = \sum_{i=1}^n \left( |u_{x_i}|^{p_i-2} \ u_{x_i}\right)_{x_i} \ , \quad p_i>1, \ \ \forall i=1,\cdots, n \ ;
\end{equation*}
\begin{equation*}
u_t = \mathrm{div} \left( |Du|^{p(x,t)-2} \ Du \right) \ , \quad \mbox{where $p(x,t)$ is a bounded and continuous function}
\end{equation*}
and also the double-phase equation (also known as the $(p,q)$-growth equation)
\begin{equation*}
u_t =\mathrm{div} \left( |Du|^{p-2} \ Du + a(x,t) |Du|^{q-2} \ Du\right) , \quad 1<p<q \quad \mbox{and $a$ a nonnegative continuous function.}
\end{equation*}

\noindent In \cite{Iwonabook}, several results related to the existence of solutions for differential equations in anisotropic Musielak-Orlicz spaces (as well as some applications) can be found. Also, in \cite{AS-book2}, \cite{AS05}, \cite{Songexist01} and \cite{Songuniq01}, one can find results on the existence and uniqueness of solutions. Regarding qualitative (and quantitative) properties of the solutions, in addition to the aforementioned works, we may also consider the (non-exhaustive) list of other contributions \cite{AMS}, \cite{AS2}, \cite{BBLV23}, \cite{Buryachenko}, \cite{Cianchi}, \cite{CG}, \cite{CH25}, \cite{CHS24}, \cite{CHS25}, \cite{CMV}, \cite{CVV}, \cite{Tedeev-CP}, \cite{DMV}, \cite{Vaz2}, \cite{Vaz1}, \cite{EH21}, \cite{EH11}, \cite{EH08}, \cite{HU06}, \cite{Ok20}, \cite{LY}, \cite{Marcellini}, \cite{SongJian06}, \cite{SongJian05}, as well as the references contained therein.

\vspace{.2cm}


\noindent In this paper we are concerned with general doubly nonlinear anisotropic parabolic equations not only for the growing interest on them and their numerous applications but also for their inherent mathematical challenges and properties. The prototype equation related to this double anisotropic setting is given by 
\[ u_t-\sum\limits_{i=1}^N \left( u^{(m_i-1)(p_i-1)} \ |u_{x_i}|^{p_i-2} \  u_{x_i}  \right)_{x_i}=0 , \quad \forall \  m_i>0, \ \ p_i>1\]
and defined over the space-time domain $\Omega_T:=\Omega \times (0, T)$, where  $\Omega$ is a bounded domain in $\mathbb{R}^N$ and $T$ a real positive number. We will study local regularity properties of the non-negative solutions to the equation
\begin{equation}\label{eq1.1}
u_t-\sum\limits_{i=1}^N \left(a_i(x, t, u, D u) \right)_{x_i}=0,\quad (x,t)\in \Omega_T,
\end{equation} 
where the functions $a_i(x, t, u, Du)$, $i=1, ..., N$, satisfy the Caratheodory conditions and the following structure conditions for almost every $(x,t) \in \Omega_T$,
\begin{equation}\label{eq1.2}
\begin{cases}
 \sum\limits_{i=1}^N a_i(x, t, u, D u) \ (u^{m^-})_{x_i}  \geqslant K_1  \sum\limits_{i=1}^N u^{(m_i-m^-)(p_i-1)} |(u^{m^-})_{x_i}|^{p_i}, \quad 
m^{-}:=\min( m_1, ..., m_N)\,,\\[.8em]
|a_i(x, t, u, D u)|\leqslant K_2 \;  u^{\frac{(m_i-m^-)(p_i-1)}{p_i}} \left(\sum\limits_{j=1}^N u^{(m_j-m^-)(p_j-1)}|(u^{m^-})_{x_j}|^{p_j}\right)^{1-\frac{1}{p_i}}\,
\end{cases}
\end{equation}
being $K_1$, $K_2$ fixed positive constants, $Du=(u_{x_1}, \cdots, u_{x_N})$ the weak gradient, and all the (anisotropic) exponents satisfy $p_i >1, m_i >0$.
\vskip0.2cm \noindent 

\noindent The approaches adopted by the above mentioned authors rely on a specific notion of solution and, if not for any other reason but that one, it brings the subject into different lights. In this work we study \eqref{eq1.1}-\eqref{eq1.2} under the following definition of weak solution.
\begin{definition} \label{defweaksol}
We say that a non-negative function $u$ satisfying\footnote{See Section \ref{sec:functional-setting} for more details on the latter space.}
\[ u\in C_{loc}(0,T; L^{1+m^-}_{loc}(\Omega)), \quad  u^{m^-}\in L^{\vec{p}}_{loc}(0, T; W^{1, \vec{p}}_{loc}(\Omega)), \]
 and for $i=1,..., N$,
\[u^{\frac{m_i(p_i-1)+m^{-}}{p_i}}, \left(u^{\frac{m_i(p_i-1)+m^{-}}{p_i}} \right)_{x_i} \in L^{p_i}_{loc}(0,T; L^{p_i}_{loc}(\Omega)),\quad  \]
 is a local weak sub(super)-solution to \eqref{eq1.1} if the following integral inequalities hold
\begin{equation}\label{eq1.3}
\int\limits_{K} u\,\varphi \,dx \Big|^{t_2}_{t_1} +\int\limits^{t_2}_{t_1}\int\limits_{K}\Big[-u\,\varphi_t+\sum\limits_{i=1}^N a_i(x, t, u, Du)\,\varphi_{x_i}\Big]\,dx\,dt\leqslant (\geqslant) \,0,
\end{equation}
for any compact $K\subset \Omega$, any interval $[t_1, t_2]\subset (0, T)$ and any non-negative $\varphi$, such that \[\varphi\in  W^{1,1+m^-}_{loc}(0,T; L^{1+m^-}(K)) \cap L^{\vec{p}}(0,T, W^{1,\vec{p}}_0(K)),\quad \vec{p}=(p_1, ..., p_N). \]
\noindent We say that $u$ is a non-negative, local weak solution to equation \eqref{eq1.1} if $u$ is both a non-negative, local weak sub- and super-solution.
\end{definition}

\noindent Observe that the regularity assumptions on $u$ assure that all the integrals appearing in \eqref{eq1.3} are well defined. In particular these regularity assumptions will allow us to consider test functions $\varphi=(u^{m^-}- k^{m^-})_{\pm} \xi^{p_+}$ and  guarantee that all the integrals appearing in the energy estimates \eqref{eq2.3} are finite as well as the integral evolving space derivatives related to the anisotropic embedding \eqref{embedding}. 

\vspace{.2cm}

\noindent The choice of $m^-:=\min( m_1, ..., m_N)$ allows us not only to recover what was presented in previous works regarding isotropic settings (see for instances \cite{BHSS21}) but also to obtain better estimates in the framework of local boundedness. Note that another possibility was to consider $m^-:=\min(1, m_1, ..., m_N)$, and in such case one recovers, for the isotropic setting, the setting and results presented in \cite{DBGV-mono}.

\vspace{.2cm}

\noindent Above all, the objective of this work is to make a consistent and precise contribution to the study of anisotropic differential equations, particularly with regard to results leading to local continuity.  In section~\ref{Sec.4}, results on the expansion of
positivity of $u$ are proved under the umbrella of an exponential shift (the isotropic siblings can be found in \cite{DBGV-mono} and also in \cite{EH22} for the doubly nonlinear setting). Nonetheless, there is a price to be paid: the exponents $\lambda_i= m_i(p_i-1)$ must be kept close, that is,  $\displaystyle{\max_{i} \lambda_i-\min_{i} \lambda_i \leqslant \epsilon_{\star}}$, for some small positive $\epsilon_{\star}$ (determined along the proofs and) depending only on the data. In section~\ref{Sec.6}, based on the previous results regarding the expansion of positivity and studying an alternative argument considered within an intrinsic geometry dictated by  \eqref{eq1.1}, the reduction of the oscillation of the nonnegative, locally bounded, local weak solutions to \eqref{eq1.1}-\eqref{eq1.2}, for specific ranges of $\lambda_i$ and $p_i$, is derived both for the fast diffusion range and the slow diffusion range.  

\subsection{The Result} For numbers $\{p_i\}_{i=1}^N$ and $\{m_i\}_{i=1}^N$ related to the degeneracy of the equation \eqref{eq1.1}, let us define for $i=1, \cdots, N$ the numbers
\[\lambda_-:=\min\limits_{1\leqslant i\leqslant N}\lambda_i,\quad \lambda_+:=\max\limits_{1\leqslant i\leqslant N}\lambda_i,\quad \lambda_i:=m_i(p_i-1)\, .  \] Number $\lambda_{+}$ discriminates the {\it singular} or {\it degenerate} behavior of the equation\footnote{The case $\lambda_+=1$ is a special one, reminiscent of the Trudinger's equation -since the parabolic and elliptic  energy terms get balanced - and will be treated in a forthcoming work.}, when respectively $\lambda_+ >1$ or $\lambda_+<1$. Our main results, Theorem \ref{th4.1} and Theorem \ref{th5.1}, state that, for non-negative local weak super-solutions to \eqref{eq1.1}-\eqref{eq1.2}, there exists a number $\epsilon^*\in (0,1)$ determined a priori only on the data, such that, if $\lambda_+-\lambda_{-}<\epsilon^*$ and the measure information
\[|\mathcal{B}_r(y)\cap [u(\cdot, s)\geqslant k]|\geqslant \alpha_0 |\mathcal{B}_r(y)|,\qquad \mathrm{for} \ \ \mathrm{some} \ \ \alpha_0 \in (0,1)\]
is available at some time level $s$ within anisotropic sets $\mathcal{B}_r$ whose geometry depends on $k$, for constants $k,r, \alpha_0$, then there exist constants $\epsilon_{*}\in (0,1)$, $C_{*}>1$ and $\delta_1, \delta_2\in (0,1)$, depending only on the data and $\alpha_0$, such that
\[u(x, t)\geqslant \frac{k}{C_{*}},\quad x\in \mathcal{B}_{2r}(y),\]
for all $t$ in a time range $s+ \delta_1 \,r^{p_{+}}\,\,k^{1-\lambda_{+}} \leqslant t\leqslant s+ \delta_2 \,r^{p_{+}}\,\,k^{1-\lambda_{+}}$ that is different from degenerate to singular case. See Sections \ref{Sec.4}-\ref{Sec.5} for the precise statements. The phenomenon of expansion of positivity lies at the heart of several other results towards regularity, such as results on the reduction of the oscillation and any form of Harnack inequality, and therefore, of H\"older estimates. In the last section of this work, we show its application to the control of the local oscillation of solutions.


\subsection{The Method} Our method is reminiscent of the elliptic technique of \cite{DiBe-Remarks} where, roughly speaking, an expansion of positivity is found for competing exponents in an intrinsic geometry whose magnitude is chosen accordingly to the degeneration of the equation. In this work we adapt the aforementioned strategy to the parabolic doubly nonlinear case, through a careful adaptation of the so-called parabolic technique of the exponential-shift, devised in \cite{Acta}. The simple idea underlying this technique is that, when looking at the equation by the magnifying glass provided by an exponential transformation, the degeneracy (fast or slow propagation) caused by a time factor $t^{-\bar{\lambda}}$ gets reduced and the elliptic terms dominate the diffusion, allowing us to perform De Giorgi's level set machinery \cite{DG}. Our approach has the advantage that can be used for operators with full-quasilinear structure (see \eqref{eq1.2}), and therefore it brings to light the structural local behavior of solutions to equations that do not, necessarily, enjoy a comparison principle. On the other hand, the disadvantage of our approach is that the exponential-shift encumbers so much the nonlinear anisotropy, that the control on the gap $p_{\text{max}}-p_{\text{min}}$ allowed for the expansion of positivity is fixed, but only qualitative.



\section{Notation, functional setting and auxiliary results}\label{Sec.2}

\subsection{Notation} 

\noindent Along the text we will be considering several exponents related to the anisotropic ones $m_i$ and $p_i$, for $i=1, \cdots, N$, and some anisotropic domains. More precisely, we will consider 
\begin{itemize}
    \item Exponents 

    \[\lambda_-:=\min\limits_{1\leqslant i\leqslant N}\lambda_i,\quad \lambda_+:=\max\limits_{1\leqslant i\leqslant N}\lambda_i,\quad \lambda_i:=m_i(p_i-1),\quad i=1, \cdots, N \]

    \[ p_{+} = \max\limits_{1\leqslant i\leqslant N} p_i , \quad p_{-} = \min\limits_{1\leqslant i\leqslant N} p_i\]
    \[\frac{1}{p}= \frac{1}{N} \sum_{i=1}^N \frac{1}{p_i} , \quad p <N \qquad \mbox{and} \qquad 
    \alpha= \sum_{i=1}^N \frac{\alpha_i}{N} , \quad \alpha_i>0\,,\]
    \[ p^\star= \frac{Np}{N-p} \qquad \mbox{and} \qquad p^\star_{\alpha}= p^\star \ \alpha\,.\]


\item Cubes and cylinders 
\[ K_{\vec{r}}(x_0):=\{x: |x_i-x_{i,0}|<r_i, \ \ i=1, ...,N\} \]

\[ Q^{+}_{\vec{r}, \eta}(x_0, t_0):=K_{\vec{r}}(x_0)\times (t_0, t_0+\eta),\quad Q^-_{\vec{r}, \eta}(x_0, t_0):=K_{\vec{r}}(x_0)\times(t_0-\eta, t_0), \]
being 
\[Q_{\vec{r}, \eta}(x_0, t_0):=Q^{+}_{\vec{r}, \eta}(x_0, t_0)\cup Q^{-}_{\vec{r}, \eta}(x_0, t_0) \]
and $\vec{r}:=(r_1, ..., r_N)$, for $r_1,\cdots, r_N, \eta$ real positive fixed numbers.

\item {\it Intrinsic} anisotropic cubes

\[ K^k_{r}(y):=\left\{x:|x_i-y_i|<\frac{r^{\frac{p_+}{p_i}}}{k^{\frac{\lambda_+-\lambda_i}{p_i}}},\ \ i=1, ..., N\right\} , \qquad \mbox{for} \ r,k>0 \ . \]

\end{itemize}

\vspace{.3cm}

\noindent We will consider as structural data the parameters $N$, $p_1$, ..., $p_N$, $m_1$, ..., $m_N$, $K_1$, $K_2$, and we will consider constants $\gamma$ (which may change from line to line) that are  quantitatively determined a priory in terms of the above quantities. 

\subsection{Functional anisotropic setting} \label{sec:functional-setting}

\noindent We define the anisotropic spaces of locally integrable functions as
\[W^{1,\vec{p}}_{loc}(\Omega)= \{u \in W^{1,1}_{loc}(\Omega)\, |\, \,  u_{x_i} \in L^{p_i}_{loc}(\Omega) \},\]
\[L^{\vec{p}}_{loc}(0,T; W^{1, \vec{p}}_{loc}(\Omega))= \{u \in L^1_{loc}(0,T; W^{1,1}_{loc}(\Omega)\, |\, \, u_{x_i} \in L_{loc}^{p_i}(0,T; L^{p_i}_{loc} (\Omega))\},\]
and the respective spaces of functions with zero boundary data
\[W^{1,\vec{p}}_{o}(\Omega)= \{u \in W^{1,1}_{o}(\Omega)\, |\, \, u_{x_i} \in L^{p_i}_{loc}(\Omega) \},\]
\[L^{\vec{p}}_{loc}(0,T; W^{1, \vec{p}}_{o}(\Omega))= \{u \in L^1_{loc}(0,T; W^{1,1}_{o}(\Omega)\, |\, \,  u_{x_i} \in L_{loc}^{p_i}(0,T; L^{p_i}_{loc} (\Omega))\}.\]
\noindent It is known (see  \cite{IlinBesovNikolski}, \cite{russian1}) that when $p>N$ the embedding $W^{1,\vec{p}}(\Omega) \hookrightarrow C^{0,\alpha}_{loc}(\Omega)$ for $\Omega$ regular enough. Therefore in this work we will consider $p<N$.

\vspace{.2cm}

\noindent We will use Lemma \ref{embedding} that provides a Sobolev embedding within the setting of anisotropic parabolic PDEs \cite{DMV}
\begin{lemma} \label{embedding} 
Let $\Omega\subseteq \mathbb{R}^N$ be a rectangular domain, $p<N$, $\alpha_i>0$, for all $i=1, \cdots, N$, and $\sigma\in [1, p^{*}_{\alpha}]$. For any number $\theta\in [0,\,  p/  p^{*}]$ define 
\[
\delta=\delta(\theta, {\bf p}, \alpha)=\theta \,  p^{*}_{\alpha}+\sigma\, (1-\theta),
\]
Then there exists a positive constant $c=c(N, {\bf p}, \alpha, \theta, \sigma)>0$ such that
\begin{equation}
\label{PS}
\iint_{\Omega_{T}}|\varphi|^{\delta}\, dx\, dt\leq c\, T^{1-\theta\, \frac{ p^{*}}{ p}}\left(\sup_{t\in (0, T]}\int_{\Omega}|\varphi|^{\sigma}(x, t)\, dx\right)^{1-\theta}\prod_i \left(\iint_{\Omega_{T}}| (\varphi^{\alpha_i})_{x_i}|^{p_{i}}\, dx\, dt\right)^{\frac{\theta\,   p^{*}}{N \, p_{i}}},
\end{equation} 
for any $\varphi\in L^{1}(0, T; W^{1,1}_{o}(\Omega))$, being the inequality trivial when the right-hand side is unbounded.
\end{lemma}

