% (iii)$\Rightarrow$(iv) follows from Theorem \ref{th:SR-Choquet}.

% (iv)$\Rightarrow$(i): We know that $\rho_{\I}$ satisfies [$S$-RA] by Theorem  \ref{th:SR-Choquet}. This implies that $\I$ satisfies [$S$-RA], according to Theorem \ref{th:convert}.
%\end{proof}

Proposition \ref{prop:SR-rating} allows us to construct many Choquet rating criteria $\I$ that satisfy [QC], [$S$-RA], and [$S$-PE], through choosing the $S$-distortion function $g$. 
 The simplest choice is to use the 
additively separable function $g$ given by  
\begin{align}
\label{eq:separable}
    g(x_1,\dots,x_s) = 
    \sum_{j=1}^s a_j h_j(x_j),~~~(x_1,\dots,x_s)\in [0,1]^s, 
\end{align}
 where  for each $j\in [s]$, $a_j\ge 0$ and
$h_j:[0,1]\to \R$ is a distortion function, and $\sum_{j=1}^s a_j  =1$. 
The corresponding $S$-distortion risk measure $\rho_\I$ is, when restricted to $\L_1$,
\begin{equation}\label{eq:decom3}
\rho_\I(X)= \sum_{j=1}^s a_j \int_0^1 h_j(\p_j(X>x))\dd x,~~~~~X\in \L_1. 
\end{equation} 



\begin{proposition} \label{prop_RCconcave}
If  
$h_j$  in \eqref{eq:decom3} is concave for each $j\in [s]$, then the Choquet rating criterion $\I$ satisfies [QC], [$S$-RA], and [$S$-PE].    
\end{proposition}
The proposition directly follows from Proposition \ref{prop:SR-rating}, because   functions of the form \eqref{eq:separable} are submodular.
 In Section \ref{sec:exampleShort}, we give several examples of rating criteria satisfying [$S$-RA] and [$S$-PE], some in the form of \eqref{eq:decom3}.

