\begin{proof}[Proof of Theorem \ref{thm:summarize}]
All arguments below work for both $\I:\L_1\to [n]$ and  $\rho:\L^\infty\to \R$.

\begin{enumerate}[(i)]
\item   {[LI]} $\Rightarrow$ [$S$-LI]: It follows from the fact that $ L_1\laweq L_2$ is a weaker requirement than $ L_1\seq L_2$. 

[RA] $\Rightarrow$ [$S$-RA]: It suffices to show that $X\leq_{S\opName{-icx}}Y$ implies $X\leq_{\rm{icx}}Y$. If $X\leq_{S\opName{-icx}}Y$, i.e., $\mathbb{E}[\phi(X)|S_j] = \E^{\p_j}[\phi(X)] \leq  \E^{\p_j}[\phi(Y)] = \mathbb{E}[\phi(Y)|S_j]$ holds for any increasing convex function $\phi$ and $j\in [s]$, then $$\mathbb{E}[\phi(X)]=\sum_{j=1} ^s 
\mathbb{E}[\phi(X)\id_{S_j}]\leq\sum_{j=1}^s \mathbb{E}[\phi(Y)  \id_{S_j}]= \mathbb{E}[\phi(Y)]$$ holds for any increasing convex function $\phi$. This yields $X\leq_{\rm{icx}}Y$. Therefore, [RA] implies [$S$-RA].

[PE] $\Rightarrow$ [$S$-PE]: It suffices to show that conditionally iid under each scenario implies conditionally iid. Take any sequence $(L_\ell)_{\ell\in\N}$   in $\L_1$ that is conditionally iid on a random vector $Z_j$ under each $\p_j$, $j\in [s]$, and let $Y$ be a random variable that equals $j\in [s]$ under $S_j$. 
It then follows that $(L_\ell)_{\ell\in\N}$   
is conditionally iid on $(Z_Y,Y)$. Therefore, [PE] implies [$S$-PE].

[PE*] $\Rightarrow$ [$S$-PE*]: This follows the same argument in [PE] $\Rightarrow$ [$S$-PE] that conditionally iid under each scenario implies conditionally iid.


With $S=\Omega$, the above implications become equivalences,   following directly from definitions.

%Note that for any $L_1,L_2\in \mathcal{L}$, $L_1\overset{d}{=} L_2$ implies both $L_1\leq_{\rm{icx}} L_2$ and $L_2\leq_{\rm{icx}} L_1$, since $\mathbb{E}\phi(L_1)= \mathbb{E}\phi(L_2)$ holds for any increasing convex function $\phi$. If a rating criteria $I$ satisfies [RA], then $L_1\overset{d}{=} L_2$ implies $I(L_1)\leq I(L_2)$ and $I(L_2)\leq I(L_1)$ by the stop-loss order which yield $I(L_1)= I(L_2)$, so $I$ satisfies [LI].

\item 
Part (ii) is a special case of (iii) when $S=\Omega$.
\item  {[$S$-RA]} $\Rightarrow$ [$S$-LI]: For any $L_1,L_2\in \mathcal{L}$, $L_1\overset{S}{\sim} L_2$ implies both $L_1\leq_{S\opName{-icx}} L_2$ and $L_2\leq_{S\opName{-icx}} L_1$, since $\mathbb{E}^{\p_j}[\phi(L_1)]= \mathbb{E}^{\p_j}[\phi(L_2)]$ holds for any increasing convex function $\phi$ and $j\in[s]$. Therefore, [$S$-RA] implies  that $L_1$ and $L_2$ are assigned the same value, and thus [$S$-LI] holds.

[$S$-RA] $\Rightarrow$ [$S$-PE]: For any  sequence  $(L_\ell)_{\ell\in\N}$   in $\L_1$ that is conditionally iid under each $\p_j$, $j\in [s]$, if $\ell\le \ell'$, and $K\in(0,1)$, by Lemma \ref{lem:RC-pool} applied to each $\p_j$, $j\in[s]$, we have $ (L^{(\ell')}-K)_+ \le_{S\opName{-icx}} (L^{(\ell)}-K)_+$. Therefore, [$S$-RA] implies [$S$-PE]. 

\item We first discuss the argument for $\rho:\L^\infty\to \R$. Take $X,Y$ with $X\le_{\rm cx} Y$. Let $X_1,X_2,\dots$ be distributed as $Y$ such that 
$X^{(n)}:=\sum_{i=1}^n X_i/n \to X$ in $L^\infty$ as $n\to\infty$; for the existence of such a sequence, see e.g.,~\citet[Theorem 3.5 and Remark 3.2]{MW15}.
By [QC], 
$\rho(X^{(n)}) \le \max\{\rho(X_1),\dots,\rho(X_n)\} = \rho(Y)$.
By [LS*], 
$$\rho(X) \le \liminf_{n\to\infty} \rho(X^{(n)}) \le \rho(Y).$$
Therefore, $\rho$ is increasing in the convex order. This then implies [RA] because $\rho$ is monotone. Translate all the above discussions about $\rho$ into $\I$, we similarly obtain that $\I$ satisfies [RA].

\item This follows from the same argument in (iv) by constructing the sequence $X_1,X_2,\dots$ with the corresponding distributions of $X,Y$ under each $\p_j$, $j\in [s]$. 

\item Take a  conditionally iid sequence  $(L_\ell)_{\ell\in\N}$   in $\L_1$ and fix $\ell\in\N$.
For $k\in [\ell]$, let $L^{(\ell)}_{-k} $
be the average of $L_j$ for $j\in [\ell]\setminus\{k\}$. Clearly, 
$L^{(\ell)}$
is the average of 
$
L^{(\ell)}_{-1},\dots,
L^{(\ell)}_{-\ell}.
$
Therefore, [QC] and [LI] imply 
$$
\rho(L^{(\ell)}) \le \max\{\rho(L^{(\ell)}_{-1}),\dots,
\rho(L^{(\ell)}_{-\ell}) \} 
= \rho(L^{(\ell)}_{-\ell}) = \rho(L^{(\ell-1)}),
$$
and hence, [PE*] holds.
\item This follows the same argument in (vii) by taking  a conditionally iid sequence  under each $\p_j$, $j\in [s]$.
\qedhere
\end{enumerate}
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm_uniqueness}]
According to the condition, there exist increasing functions $f_1:[0,1] \rightarrow [n]$ and $f_2:[0,1] \rightarrow [n]$ such that
\begin{equation}
    \label{eq:unique-pf}    \I(L)=f_1(\rho_1(L))=f_2(\rho_2(L)),~~~~ L\in \L_1.
\end{equation} 
Note that a Choquet integral $\rho$ in form \eqref{eq:scpresentation} satisfies $\rho(x)=x$ for $x\in [0,1]$.
We have
$$f_1(x)=f_1(\rho_1(x))=\I(x)=f_2(\rho_2(x))=f_2(x)~~~\mbox{ for all } x\in [0,1].$$
Hence, the functions $f_1,f_2$ coincide, and we denote it by $f$. 

Next we argue $\rho_1=\rho_2$. Otherwise, there exists $\rho_1(L)\neq \rho_2(L)$ for some $L\in \L_1$. We can assume $\rho_1(L)< \rho_2(L)$ without loss of generality.  
Since $f$ is not a constant on $(0,1)$, there exists $c\in (0,1)$ such that $f(x) < f(y)$ for any $0\leq x<c<y\leq 1$. 
Note that any Choquet integral $\rho$ satisfies $\rho(\lambda X+a)=\lambda \rho(X)+a$ for $\lambda>0$, $a\in \R$ and $X\in \L^{\infty}$.
If $\rho_1(L)<c<\rho_2(L)$ then it is a contradiction to \eqref{eq:unique-pf}. 
If $c<\rho_1(L)<\rho_2(L)$,
then we can find $\lambda\in (0,1)$ such that
$ \rho_1(\lambda L)<c<\rho_2(\lambda  L)$, a contradiction to \eqref{eq:unique-pf}. 
If $\rho_1(L)<\rho_2(L)<c$,
then we can find $\lambda\in (0,1)$ such that
$ \rho_1(\lambda L+(1-\lambda))<c<\rho_2(\lambda  L+(1-\lambda))$, a contradiction to \eqref{eq:unique-pf}. 
Therefore, $\rho_1=\rho_2$ holds true. 
% Define a loss variable
% $$L'=c+\varepsilon(2L-\rho_1(L)-\rho_2(L))$$
% where $0<\varepsilon<\min\{c,1-c\}/2$, then it can be verified from
% $$0<c-2\varepsilon\leq L'\leq c+2\varepsilon<1$$
