% $$\rho_1(L')=c+\varepsilon(2\rho_1(L)-\rho_1(L)-\rho_2(L))=c+\varepsilon(\rho_1(L)-\rho_2(L))<c$$
% and
% $$\rho_2(L')=c+\varepsilon(2\rho_2(L)-\rho_1(L)-\rho_2(L))=c+\varepsilon(\rho_2(L)-\rho_1(L))>c.$$
% Since $c$ is a discontinuity point of $f$,
% $$\I(L')=f(\rho_2(L'))\geq f(\rho_1(L'))+1=\I(L')+1$$
% which contradicts. So $\rho_1=\rho_2$, which gives the proof.
\end{proof}

\begin{proof}[Proof of Theorem \ref{th:convert}]
(i) If $\rho_\I$ satisfies one of the above properties, then $\I$ satisfies the same property since $\I$ is an increasing transformation of $\rho_\I$. 
Conversely, we will show that if $\I$ satisfies any one of the above properties, then so does $\rho_{\I}$. Suppose otherwise; that is, one of the following conditions holds:
\begin{enumerate}[(a)]
    \item $\I$ satisfies [LI] and $\rho_{\I}(X)< \rho_{\I}(Y)$ for some $X,Y\in \L_1$ with $X\overset{\d}{=}Y$;
    \item $\I$ satisfies [$S$-LI] and $\rho_{\I}(X)< \rho_{\I}(Y)$ for some $X,Y\in \L_1$ with $X\overset{S}{\sim}Y$;
    \item $\I$ satisfies [RA] and $\rho_{\I}(X)< \rho_{\I}(Y)$ for some $X,Y\in \L_1$ with $Y\le_{\opName{icx}}X$;
    \item $\I$ satisfies [$S$-RA] and $\rho_{\I}(X)< \rho_{\I}(Y)$ for some $X,Y\in \L_1$ with $Y\le_{S\opName{-icx}}X$;
    \item $\I$ satisfies [PE*] and $\rho_{\I}(X)< \rho_{\I}(Y)$, where $X=L^{(\ell)}$ and $Y=L^{(\ell')}$ with $\ell\le \ell'$ and some conditionally iid sequence $L_1,L_2,\dots\in \L_1$;
    \item $\I$ satisfies [$S$-PE*] and $\rho_{\I}(X)< \rho_{\I}(Y)$, where $X=L^{(\ell)}$ and $Y=L^{(\ell')}$ with $\ell\le \ell'$ and some sequence $(L_\ell)_{\ell\in\N}$ in $\L_1$ that is conditionally iid under each $\p_j$, $j\in [s]$;
    \item $\I$ satisfies [QC] and $\rho_{\I}(Z)\le \rho_{\I}(X)< \rho_{\I}(Y)$, where $Y=\lambda X+(1-\lambda) Z$ for some $X,Z\in \L_1$ and $\lambda \in [0,1]$.
\end{enumerate}

Take a discontinuity point $k$ of $f_{\I}$ in $(0,1)$, such that any $L$ with $\rho_{\I}(L)<k$ and any $L'$ with $\rho_{\I}(L')>k$ are rated differently by $\I$. Because $\rho_{\I}(X)< \rho_{\I}(Y)$, there exist $\alpha,\beta  \in[0,1]$ such that $\alpha \rho_{\I}(X)+ \beta  < k < \alpha \rho_{\I}(Y) +\beta $. 
Moreover, by choosing $\beta$ close to $k$, the value $\alpha$ can be made arbitrarily small, in particular smaller than $1-\beta$. This guarantees that $\alpha X+\beta, \alpha Y+\beta \in \mathcal L_1$.
By translation invariance and positive homogeneity of $\rho_{\I}$,  $ \rho_{\I}(\alpha X +\beta ) < k < \rho_{\I}(\alpha Y +\beta )$ holds. Hence, $\alpha X +\beta$ is rated better than $\alpha Y +\beta$, which yields a contradiction if any of the conditions (a)--(d) hold. 
If condition (e) or (f) hold, then contradiction comes by applying [PE*] (resp.~[$S$-PE*]) to the sequence $\alpha L_1+\beta,\alpha L_2+\beta ,\dots$ in $ \mathcal L_1$. If condition (g) holds, then contradiction comes 
from [QC] and $\I(\alpha Z+\beta)\leq \I(\alpha X+\beta)< \I(\alpha Y+\beta)$, where $\alpha Y+\beta = \lambda(\alpha X+\beta)+ (1-\lambda)(\alpha Z+\beta)$.

(ii) If $f_\I$ is left-continuous and $\rho_\I$ satisfies property [LS] (resp.~[LS*]), then $\I$ satisfies the same property by definition \eqref{eq:p2r}. Now suppose that $\I$ satisfies property [LS] (resp.~[LS*]).

Taking random variables $X_{\ell}=\lambda_{\ell}$ and $X=\lambda$ with constants $\lambda,\lambda_1,\lambda_2,\ldots\in [0,1]$ and $\lambda_{\ell}\uparrow \lambda$, we have $X,X_1,X_2,\ldots \in \L_1$ and $X_{\ell}\uparrow X$. According to [LS] (resp.~[LS*]), 
\begin{equation*}\liminf_{\ell\rightarrow\infty}f_{\I}(\lambda_\ell)=\liminf_{\ell\rightarrow\infty}\I(X_{\ell}) \geq \I(X)=f_{\I}(\lambda)
\end{equation*}
yields that $\lim_{\ell\rightarrow\infty}f_{\I}(\lambda_\ell)=f_{\I}(\lambda)$, i.e., $f_{\I}$ is left-continuous.
Then we show that $\rho_\I$ satisfies the same property. Suppose otherwise; that is, $\liminf_{\ell\rightarrow \infty}\rho_\I(X_{\ell})< \rho_\I(X)$ holds for some $(X_\ell)_{\ell\in\N} $ with $X_{\ell} \rightarrow X$ almost surely (resp.~in $\mathcal{L}^{\infty}$).
Consider the same discontinuity point $k$ of $f_{\I}$ as in part (i). Following the same argument presented in (i), there exist constants $\alpha,\beta  \in[0,1]$ satisfying 
$$\alpha \liminf_{\ell\rightarrow \infty}\rho_{\I}(X_\ell)+ \beta  < k < \alpha \rho_{\I}(X) +\beta,$$ 
which simultaneously ensures that $\alpha X_\ell+\beta \in \mathcal L_1$ for all $\ell$ and $\alpha X+\beta \in \mathcal L_1$. 
By translation invariance and positive homogeneity of $\rho_{\I}$, $\liminf_{\ell\rightarrow \infty}\rho_{\I}(\alpha X_{\ell} +\beta ) < k < \rho_{\I}(\alpha  X  +\beta )$ holds.
Consequently, there exist infinitely many $\ell$ such that $\alpha X_{\ell} +\beta$ is rated better than $\alpha X +\beta$, which yields a contradiction by applying [LS] (resp.~[LS*]) to $\alpha X+\beta$ and the sequence $\alpha X_1+\beta,\alpha X_2+\beta ,\dots$ in $ \mathcal L_1$. So $\rho_\I$ satisfies the same property.
\end{proof}


