\begin{proof}[Proof of Proposition \ref{prop:SPE2}]
Take a point $\mathbf{x}=(x_1,\ldots,x_s)\in (0,1)^s$.
Define a sequence $L_1,L_2,\dots \in \mathcal L_1$ that is  conditionally iid on $S$ such that $L_1$ is distributed as Bernoulli($x_j$) under scenario $S_j$. Clearly, 
$$\rho(L_1) = g(\p_1(L_1=1),\dots,\p_s(L_1=1)) = g(x_1,\ldots,x_s).$$
Moreover, for $j\in [s]$, $L^{(\ell)}$ converges $\p_j$-almost surely to $x_j$ as $\ell\to\infty$.  This implies 
$$\p^S(L^{(\ell)}>z)\to (\p_1(x_1>z),\dots,\p_s(x_s>z)) =   (\id_{\{ x_1>z\}},\dots,\id_{\{ x_s>z\}}) $$
   for all $z\in [0,1]$ except on a set $A\subseteq [0,1]$ of Lebesgue measure $0$.
   For  $z \in [0,1]\setminus A$,
   lower semi-continuity of $g$ at points in $\{0,1\}^s$ implies 
$$\lim_{\ell \to\infty} (g\circ \p^S)(L^{(\ell)}>z) \ge  g(\id_{\{ x_1>z\}},\dots,\id_{\{ x_s>z\}}).$$ 
By the dominated convergence theorem,  \begin{align*} 
  \lim_{\ell \to\infty}   \rho(L^{(\ell)}) 
   =\int_0^1 (g\circ \p^S)(L^{(\ell)}>z)  \d z
  &\ge  \int_0^1 g (\id_{\{ x_1>z\}},\dots,\id_{\{ x_s>z\}}) \d z.
\end{align*} 
  From [$S$-PE], we have that $\rho(L_1) \ge \rho(L^{(\ell)})$ and \eqref{eq_specon} holds. \end{proof}


\section{Equivalent conditions of a submodular function}
\label{app:L5}

The following lemma provides   equivalent conditions of a submodular function. 
The proof of the  lemma is similar to Proposition 2.1 of \cite{shaked1990parametric}
and Theorem 2.5 of \cite{mullerScarsini2001}, but the latter two results are formulated for functions on $\R^s$, and hence the results are not the same, which we discuss later.
In what follows, we denote by $\mathbf{e}_i$ the $i$th unit vector in $\mathbb{R}^{s}$  for $i\in [s]$. 


\begin{lemma}\label{lemma:submodular}
	For a function $g:[0,1]^s\rightarrow\mathbb{R}$, the following conditions are equivalent.
	\begin{enumerate}[(i)]
		\item $g$ is componentwise concave and submodular on $[0,1]^s$;
		\item For all $\mathbf{x}_1, \mathbf{x}_2, \mathbf{x}_3, \mathbf{x}_4\in [0,1]^{s}$ such that $\mathbf{x}_1\leq \mathbf{x}_2\leq \mathbf{x}_4$, $\mathbf{x}_1\leq \mathbf{x}_3\leq \mathbf{x}_4$ and $\mathbf{x}_1+\mathbf{x}_4 = \mathbf{x}_2+\mathbf{x}_3$,
        \begin{equation}
            g(\mathbf{x}_1)+g(\mathbf{x}_4) \leq g(\mathbf{x}_2)+g(\mathbf{x}_3);\label{eq:submodular2}
        \end{equation}
		\item For all $\mathbf{x}\in [0,1]^{s}$, $\epsilon, \delta\geq 0$ and $i,j\in [s]$ such that 
		$\mathbf{x}+\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j\in [0,1]^s$,
		\begin{equation}
			g(\mathbf{x}) + g(\mathbf{x}+\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j)\leq g(\mathbf{x}+\varepsilon\mathbf{e}_i)+g(\mathbf{x}+\delta\mathbf{e}_j).\label{eq:submodular3}
		\end{equation}
	\end{enumerate}
     Any of (i)--(iii) implies
    \begin{enumerate}[(iv)]
    \item For all $\mathbf{x}\in [0,1]^s$, $\varepsilon,\delta\geq 0$ and $i,j\in [s]$ such that  $\mathbf{x}-\varepsilon\mathbf{e}_i,\mathbf{x}+\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j\in [0,1]^s$,
        \begin{equation}
        g(\mathbf{x}-\varepsilon\mathbf{e}_i)+g(\mathbf{x}+\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j)
        \leq g(\mathbf{x})+g(\mathbf{x}+\delta\mathbf{e}_j).\label{eq:submodular4}
        \end{equation}
    \end{enumerate} 
    Moreover, if $g$ is upper semi-continuous, then (i)--(iv) are equivalent.
\end{lemma}

 Theorem 2.5 of \cite{mullerScarsini2001} and Theorem 3.12.2 of \cite{muller2002comparison} state that   
(i)--(iv) in Lemma \ref{lemma:submodular}, when formulated for functions on $\R^s$, are equivalent. For functions $g$ on $[0,1]^s$, condition (iv) does not   imply the other three conditions when $g$ is not upper semi-continuous. For a  counterexample, consider the function $g$ given by $g(x_1,x_2)=\id_{\{x_1>0\}}\id_{\{x_2>0\}}$ with  $s=2$, which is not upper semi-continuous. It is straightforward to see that $g$ satisfies \eqref{eq:submodular4}, but $g(0,0)+g(1,1)-g(0,1)-g(1,0)=1>0$, contradicting \eqref{eq:submodular3}. Therefore, we need the upper semi-continuity of  $g$. 



\begin{proof}[Proof of Lemma \ref{lemma:submodular}]
	(i)$\Rightarrow$(ii): Take vectors  $\mathbf{x}_1 = (x_{1,1}, \ldots, x_{1,s})$, $\mathbf{x}_2 = (x_{2,1}, \ldots, x_{2,s})$, and $\mathbf{y} = (y_1, \ldots, y_s) \in [0,1]^s$ satisfying  $\mathbf{x}_1 \leq \mathbf{x}_2$ and $\mathbf x_2+\mathbf y \in [0,1]^s$. For $j\in [s]$, we have 
	\begin{align*}
	 g(\mathbf{x}_2 + y_j \mathbf{e}_j) - g(\mathbf{x}_2) 
		&\leq  g(\mathbf{x}_2 + (x_{1,j}-x_{2,j}+y_j)  \mathbf{e}_j)
		- g(\mathbf{x}_2 + (x_{1,j}-x_{2,j})  \mathbf{e}_j )\\
		& \leq g(\mathbf{x}_1 + y_j \mathbf{e}_j) - g(\mathbf{x}_1),
	\end{align*}
	where the first inequality follows from componentwise concavity, and the second inequality follows from  submodularity. % Thus
	%$$g(\mathbf{x}_2 + y_j \mathbf{e}_j) - g(\mathbf{x}_1 + y_j \mathbf{e}_j) \leq g(\mathbf{x}_2) - g(\mathbf{x}_1).$$
	Applying the above arguments iteratively for all $j \in [s]$, we get $g(\mathbf{x}_2 + \mathbf{y}) - g(\mathbf{x}_1 + \mathbf{y}) \leq g(\mathbf{x}_2) - g(\mathbf{x}_1)$. 
  This implies that \eqref{eq:submodular2} holds by taking $\mathbf{y}=\mathbf{x}_4-\mathbf{x}_1$.

	(ii)$\Rightarrow$(iii): This follows directly by substituting \eqref{eq:submodular3} into \eqref{eq:submodular2}.

	(iii)$\Rightarrow$(i): The componentwise concavity follows by taking $i=j$. Take $\mathbf{x} = (x_{1}, \ldots, x_{s})$, $\mathbf{y} = (y_1, \ldots, y_s)$ and $\mathbf{z} = (z_1, \ldots, z_s)\in [0,1]^s$ satisfying $y_iz_i=0$ for all $i \in [s]$ and $\mathbf x+ \mathbf y + \mathbf z \in [0,1]^s$.
  To establish submodularity on $[0,1]^s$, it suffices to show       $$g(\mathbf{x})+g(\mathbf{x}+\mathbf{y}+\mathbf{z})\leq g(\mathbf{x}+\mathbf{y})+g(\mathbf{x}+\mathbf{z}),$$
  for the any $\mathbf x,\mathbf y,\mathbf z $ above.
    Define a difference operator $\Delta_{\mathbf{y}}g(\mathbf{x}):=g(\mathbf{x}+\mathbf{y})-g(\mathbf{x})$. Then for $i,j$ with $y_i,z_j>0$, we have $\Delta_{z_j\mathbf{e}_j}g(\mathbf{x}+y_i\mathbf{e}_i)\leq \Delta_{z_j\mathbf{e}_j}g(\mathbf{x})$
    by \eqref{eq:submodular3}. Applying the above arguments iteratively for all $j \in [s]$,  we get   $$\Delta_{z_j\mathbf{e}_j}g(\mathbf{x}+\mathbf{y})\leq \cdots\leq \Delta_{z_j\mathbf{e}_j}g(\mathbf{x}+y_i\mathbf{e}_i)\leq \Delta_{z_j\mathbf{e}_j}g(\mathbf{x}),$$
    that is, $\Delta_{\mathbf{y}}g(\mathbf{x}+z_j\mathbf{e}_j)\leq \Delta_{\mathbf{y}}g(\mathbf{x})$. Similarly, repeatedly applying the above procedure for  $j \in [s]$, we get
    $$\Delta_{\mathbf{y}}g(\mathbf{x}+\mathbf{z})\leq \cdots\leq \Delta_{\mathbf{y}}g(\mathbf{x}+z_j\mathbf{e}_j)\leq \Delta_{\mathbf{y}}g(\mathbf{x}).$$
 Therefore, $g$ is submodular on $[0,1]^s$.

We have shown that   statements (i)--(iii) are equivalent. The direction (ii)$\Rightarrow$(iv) follows directly by substituting \eqref{eq:submodular4} into \eqref{eq:submodular2}. Next, we show (iv)$\Rightarrow$(iii) when $g$ is upper semi-continuous. Taking $\delta=0$ in \eqref{eq:submodular4}, we obtain that $g$ is componentwise concave.
Note that any  upper semi-continuous concave function on $[0,1]$ must be continuous. Hence,    $g$ is componentwise continuous. 
For $\mathbf{x},\mathbf{x}+\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j\in [0,1]^s$, fixing some integer $n$, the inequality \eqref{eq:submodular4} implies   
    \begin{equation*}
        g\left(\mathbf{x}+\frac{k+1}{n}\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j\right)
        -g\left(\mathbf{x}+\frac{k}{n}\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j\right)
        \leq g\left(\mathbf{x}+\frac{k}{n}\varepsilon\mathbf{e}_i\right)
        -g\left(\mathbf{x}+\frac{k-1}{n}\varepsilon\mathbf{e}_i\right)
    \end{equation*}
    for all $k=1,\ldots,n-1$. Adding up these inequalities yields 
    \begin{equation*}
        g(\mathbf{x}+\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j)
        -g\left(\mathbf{x}+\frac{1}{n}\varepsilon\mathbf{e}_i+\delta\mathbf{e}_j\right)
        \leq g\left(\mathbf{x}+\frac{n-1}{n}\varepsilon\mathbf{e}_i\right)
        -g(\mathbf{x}).
    \end{equation*}
    Since $g$ is componentwise continuous, we get that \eqref{eq:submodular3} holds by sending  $n\rightarrow\infty$. 
\end{proof}

