\section{Preliminaries}\label{sec:preliminaries}
% \section{Preliminaries}\label{sec:preliminaries}

% In this section, we introduce the framework of time-homogeneous MDPs and review the existing OPE methods. 

% \subsection{Problem Formulation}\label{sec:2.1}

Assume the data follows an MDP defined by a tuple $(\mathcal{S}, \mathcal{A}, p, r, \gamma)$, where $\mathcal{S}$ is the state space, $\mathcal{A}$ is the action space, $p:\mathcal{S}\times\mathcal{A}\rightarrow\mathcal{S}$ is the Markov transition kernel that characterizes the environment dynamics, $r:\mathcal{S}\times\mathcal{A}\rightarrow\mathbb{R}$ is the reward function where larger positive rewards are preferable, and $\gamma\in(0,1)$ is a discount factor that trades off long-term rewards for immediate rewards. In this work, we assume the state space $\mathcal{S}$ is continuous with $d$-dimensional state variables, and the action space $\mathcal{A}=\{1,\dots,m\}$ is discrete with $m$ distinct actions. Consider a trajectory $\{(S_t ,A_t,R_{t+1})\}_{t\geq 0}$ generated from the MDP model, where $(S_t,A_t,R_{t+1})$ denotes the triplet of state, action, and immediate reward. Here, we denote the reward as $R_{t+1}$ instead of $R_t$ to emphasize that the reward $R_{t+1}$ and next state $S_{t+1}$ are jointly determined. 
The following assumptions are commonly imposed in infinite-horizon RL problems.

\begin{assumption}[Time-homogeneous Markov Assumption]\label{ass:MA}
The transition probability satisfies 
$P(S_{t+1} \vert S_{t}
=s, A_{t}=a, \{S_j, A_j,R_{j+1}\}_{0\leq j < t})
=p(S_{t+1} \vert S_{t}=s, A_{t}=a)
=p(S_{1} \vert S_{0}=s, A_{0}=a)$, where $p$ is the transition function.
\end{assumption}
% \begin{remark}
% % The Markov assumption states that the next state only depends on the current state and action, and it is conditionally independent of the history given the current state and action. 
% % This assumption may not hold for some applications such as chronic disease. 
% % If one suspects the trajectory has some higher-order Markovian properties, the state variable $S_{t}$ can be constructed by aggregating the state information over several time steps \citep{shi2020does}.
% \label{remark:1}
% \end{remark}

\begin{assumption}
[Conditional Mean Independence Assumption]
\label{ass:CMIA}
$\mathbb{E}(R_{t+1} \vert S_{t}
=s, A_{t}=a, \{S_j, A_j,R_{j+1}\}_{0\leq j < t})
=\mathbb{E}(R_{t+1} \vert S_{t}=s, A_{t}=a)
:=r(s, a)$, where $r$ is the reward function. 
% In addition, $R_t$ is uniformly bounded, i.e., there exists a constant $c_0$ such that $\max_t \vert R_{i,t}\vert\leq c_0$.
\end{assumption}
% \begin{remark}
% The reward $R_{t+1}$ is usually a function of $(S_{t},A_{t},S_{t+1})$, larger positive values are preferable. This assumption states that given the current state-action pair, the mean of the current reward is conditionally independent of the history. 
% \end{remark}

\iffalse
\begin{remark}\label{rmk:markov_ass}
% We remark that 
In practice, the Markovian assumption may not hold for some applications such as chronic disease. If one suspects that the trajectory has higher-order Markovian properties, the state variable $S_{t}$ can be constructed by aggregating the state information over several time steps \citep{shi2020does}. 
\end{remark}
\fi

Assumptions \ref{ass:MA}-\ref{ass:CMIA} guarantee the existence of an optimal stationary policy \citep{puterman1994markov}. A stationary policy $\pi$ is a mapping from the state space $\mathcal{S}$ to a probability mass function over the action space $\mathcal{A}$. 
For discounted infinite-horizon MDPs, the state value function of policy $\pi$ is defined as 
% $$V^{\pi}(s)=\mathbb{E}_{\pi}\left\{\sum_{t=0}^{\infty}\gamma^{t} R_{t+1}\biggl\vert S_{0}=s\right\},$$
$V^{\pi}(s)=\mathbb{E}_{\pi}\{\sum_{t=0}^{\infty}\gamma^{t} R_{t+1}\vert S_{0}=s\},$
where $\mathbb{E}_{\pi}$ denotes the expectation with respect to the trajectory distribution following policy $\pi$. 
% The state value function represents the expected cumulative discounted reward starting from some initial state. 
The policy value is defined as  $V_{\mathbb{G}}^{\pi}=\mathbb{E}_{s\sim\mathbb{G}}V^{\pi}(s)=\int_{s \in \mathcal{S}} V^\pi(s) \mathbb{G}(d s)$, where $\mathbb{G}$ is some reference state distribution over which the policy is evaluated, a common choice is the initial state distribution. This integrated value $V_{\mathbb{G}}^{\pi}$ quantifies the overall performance of a policy and hence is a key concept in policy evaluation. Similarly, the state-action value function (better known as the Q-function) is defined as 
% $$Q^{\pi}(s,a)=\mathbb{E}_{\pi}\left\{\sum_{t=0}^{\infty} \gamma^{t} R_{t+1} \biggl\vert S_{0}=s, A_{0}=a\right\}.$$ 
$Q^{\pi}(s,a)=\mathbb{E}_{\pi}\{\sum_{t=0}^{\infty} \gamma^{t} R_{t+1} \vert S_{0}=s, A_{0}=a\}.$
Under Assumption \ref{ass:MA} and \ref{ass:CMIA}, $Q^{\pi}$ satisfies the Bellman equation
\begin{equation}\label{eq:bellman}
    \mathbb{E}\Big\{R_{t+1} + \gamma V^{\pi}(S_{t+1})-Q^{\pi}(S_{t},A_t)\mid S_{t},A_t\Big\} = 0,
\end{equation}
where $V^{\pi}(S_{t+1}) = \sum_{a'\in\mathcal{A}}Q^{\pi}(S_{t+1},a')\pi(a'|S_{t+1})$.
%$$Q^{\pi}(s,a)=r(s,a)+\gamma\mathbb{E}_{\pi}\left\{Q^{\pi}(S_1, A_1)\mid S_{0}=s, A_{0}=a\right\}.$$
% \begin{equation*}
% Q^{\pi}(s,a)
% =r(s,a)+\gamma\mathbb{E}_{\pi}\left\{Q^{\pi}(S_1, A_1)\vert S_{0}=s, A_{0}=a\right\},
% \label{eq:bellman}
% \end{equation*}
This equation plays a critical role in estimating the Q-function in many RL algorithms. 




\section{Off-Policy Evaluation with Missing Data}\label{sec:OPE_incomplete}
% \section{Off-policy evaluation with incomplete data}\label{sec:OPE_incomplete}

In this section, we systematically study OPE under missing data. Specifically, we focus on monotone missingness, which is a common pattern in longitudinal data analysis \citep{birmingham2003pattern,zhou2012efficient,linero2015flexible}. Monotone missingness assumes that if an observation is missing at a given time point in a trajectory, it will remain missing at all subsequent time points. This pattern is often seen in multi-stage missing data settings, particularly when subjects drop out before completing the entire follow-up period.
