% We introduce the additional notations associated with missing data in Section \ref{sec:missing_notation}. 
% In Section \ref{sec:missing_mechanism}, we review the two major types of missing data mechanisms and discuss the consistency of the OPE method under different missingness mechanisms. To remove potential bias, we propose a semiparametric IPW value estimator in Section \ref{sec:value_inference_missing}, which is shown to be consistent under nonignorable missingness.
Before proceeding, we introduce some necessary definitions. Let $\mathcal{D}=\{\tau_i\}_{1\leq i \leq n}$ denote the observed data consisting of $n$ independent and identically distributed trajectories. For complete data, each trajectory can be expressed as $\tau_i=\{(S_{i,t}, A_{i, t},R_{i,t+1},S_{i,t+1})\}_{0\leq t< T}$, where $T$ is the termination time. 
Throughout this paper, we assume that the immediate rewards are uniformly bounded. 
% For simplicity, we assume that all trajectories have the same number of observed time steps, i.e., $T_i = T$ for $i = 1,\dots,n$. 
% Our goal is to estimate the value of target policy $\pi$ using the offline data $\mathcal{D}$. 
% Let $\boldsymbol{\eta}=(\eta_0, \eta_1, \eta_2,\dots, \eta_T)^{\top}$ denote the vector of binary response indicators, where $\eta_{i,t}=1$ if subject $i$ is still in the study at time $t$ and we observe $(R_{i,t}, S_{i,t}, A_{i, t})$, otherwise $\eta_{i,t}=0$. 

For incomplete data, define $\boldsymbol{\eta}=(\eta_0, \eta_1, \eta_2,\dots, \eta_T)^{\top}$ as a vector of binary response indicators. $\eta_{i,t}$ is a sample of $\eta_t$ that represents the response status of subject $i$ at time $t$: $\eta_{i,t}=1$ if subject $i$ is still in the study at time $t$ and we observe 
% the corresponding data 
$(R_{i,t}, S_{i,t}, A_{i, t})$, otherwise $\eta_{i,t}=0$. 
Assume the baseline covariates and initial treatment assignment are always observable, i.e., $\eta_{i,0}=1$. We consider a general setting where the reward $R_{t+1}$ depends on $(S_{t}, A_{t}, S_{t+1})$. If $S_{t+1}$ is unobserved, then $R_{t+1}$ is missing as well. Therefore, an observed trajectory can be represented as $\tau_i=\{(\eta_{i,t}S_{i,t}, \eta_{i,t}A_{i,t}, \eta_{i,t+1}R_{i,t+1}, \eta_{i,t+1}S_{i,t+1})\}_{0\leq t<T}$. 
% In this work, we focus on this particular dropout pattern. Nevertheless, the proposed framework and theoretical results apply to more general dropout patterns, please refer to Appendix \ref{sec:general_dropout} for more discussions. 
Under monotone missingness, $\boldsymbol{\eta}_i$ is a decreasing sequence: if $\eta_{i,t}=0$, then $\eta_{i,s}=0$ for all $s>t$. To describe the lengths of observed trajectories, we also define the dropout time $C$: $C=t$ if the subject dropped out {right after} action $A_t$, which corresponds to $(\eta_{t},\eta_{t+1})=(1,0)$.
% $\boldsymbol{\eta}=(\boldsymbol{1}_{t+1}^{\top}, \boldsymbol{0}_{T-t}^{\top})^\top.$ 
If the trajectory is fully observed, $C$ is set to $T$. 
% We use $\mathcal{F}_{t}=\{(S_{j},A_{j},R_{j+1})\}_{0\leq j<t}\cup\{S_{t}, A_{t}\}$ to represent all the information up to time $t$. 

Given the offline data $\mathcal{D}$, our goal is to estimate and conduct statistical inference on the value function under target policy $\pi$. 
Although this work focuses on monotone missingness where dropout occurs after the action is observed, the proposed framework and theoretical results are applicable to more general dropout patterns. A discussion on these broader scenarios, including dropout before action occurs and intermittent missingness, is provided in Appendix \ref{sec:general_dropout}.

\subsection{Missing Data Mechanisms} \label{sec:missing_mechanism}

There are two major types of missing data mechanisms: ignorable and nonignorable missingness. Ignorable missingness refers to the case where the missingness can be fully explained by the observed information, which is also referred to as Missing-At-Random (MAR). An example of MAR would be dropout in a clinical trial due to recorded side effects and lack of efficacy, or other known baseline characteristics. The term ``randomness'' in MAR implies that once one has conditioned on all the available data, any remaining missingness is completely random \citep{graham2009missing}. On the other hand, if the missingness depends on unobserved components, the missing data mechanism is referred to as nonignorable, or Missing-Not-At-Random (MNAR). Dropout in a clinical trial due to the unobserved current health status or other latent variables is an example of an MNAR. 
Formal definitions of the two missing mechanisms are given as follows. 

\begin{definition}[Ignorable Missingness, MAR]\label{def:mar}
The missingness can be fully accounted for by the observed information, i.e., 
$\eta_{t+1}\indep (R_{t+1}, S_{t+1})\mid(S_{t}, A_{t}, \{(S_{j},A_{j},R_{j+1})\}_{0\leq j<t}, {\eta}_t),$
for $t=0,\dots, T-1$. %Here, $\indep$ means independence.
\end{definition}

\begin{definition}[Nonignorable Missingness, MNAR]\label{def:mnar}
The missingness depends on the next state regardless of whether it is observed or not, i.e., 
$\eta_{t+1}\nindep (R_{t+1}, S_{t+1})\mid(S_{t}, A_{t}, \{(S_{j},A_{j},R_{j+1})\}_{0\leq j<t},{\eta}_t),$
for $t=0,\dots, T-1$.
\end{definition}
\begin{remark}
% We remark that 
In the special case where $S_{t+1}$ and $R_{t+1}$ are fully determined by $S_t$ and $A_t$, nonignorable missingness reduces to ignorable missingness. However, in practice, we cannot evaluate whether the missing data mechanism is ignorable or nonignorable solely based on the observed data. Instead, this distinction need to be justified using contextual information and subject-matter knowledge.
\end{remark}

%For nonignorable missingness in longitudinal data, it is common to also assume that is conditionally independent of future observations after time $t+1$
% , that is, $\eta_{t+1}\indep( A_{t+1}, R_{t+2}, \{(S_j,A_j,R_{j+1},S_{j+1})\}_{t+2\leq j < T})~\vert~(S_{t},A_{t},R_{t+1},S_{t+1},{\eta}_t)$ 
%\citep{diggle1994informative}. 
We define the dropout propensity $\lambda(\cdot)$, i.e. the probability of the subject dropping out right after time $t$, as a function of all historical data observed until time $t$ \citep{diggle1994informative}. That is,
$P(C=t~\vert~\{(S_j,A_j,R_{j+1},S_{j+1})\}_{0\leq j < t+1},C\geq t)
=P(\eta_{t+1}=0 ~\vert~ \{(S_j,A_j,R_{j+1},S_{j+1})\}_{0\leq j < t+1}, \eta_{t}=1)$. Similar to the Markov assumptions in MDPs imposed on $R_t$ and $S_{t+1}$ (see Assumptions \ref{ass:MA}-\ref{ass:CMIA}), we assume that $\eta_{t+1}$ exhibits a similar dependency on existing data, as stated below.

\begin{assumption}\label{ass:lambda_indep}
The dropout propensity satisfies $P(\eta_{t+1}=0 \mid \{S_j, A_j,R_{j+1}\}_{0\leq j \leq t},S_{t+1}, \eta_{t}=1)
=P(\eta_{t+1}=0 \mid S_t,A_t,R_{t+1},S_{t+1}, \eta_{t}=1)$, denoted by $\lambda(S_t,A_t,R_{t+1},S_{t+1})$.
\end{assumption}
% \begin{remark}
This assumption states that whether a subject will drop out or not right after receiving $A_t$ depends on the history 
% $\mathcal{F}_t$ 
only through the current data tuple $(S_t,A_t,R_{t+1},S_{t+1})$. %, and the dependency remains stationary over time. 
% This is the case where the state-action pair contains enough information regarding missingness at the next step. 
%The assumption shares some similarities with the Markovian assumption. 
In practical applications, if the missing probability (or $R_{t+1}$ and $S_{t+1}$ as specified in Assumption \ref{ass:MA}-\ref{ass:CMIA}) is suspected to depend on multiple past steps, this assumption can still be satisfied by directly incorporating such information into the current state variable \citep{shi2020does}.

% , as we mentioned in remark \ref{remark:1}.
% \end{remark}



\subsection{Value Estimation and Inference Under Missingness }\label{sec:est_inference}
Given incomplete data, the response indicator $\eta_t$ must be accounted for. One common approach is to estimate using Equation \eqref{eq:bellman} with only the observed data where $\eta_{i,t} = 1$. However, we will demonstrate later in this section that this straightforward solution does not always yield an unbiased estimate under general missing data mechanisms, such as MNAR. In this section, we investigate the scenarios introduced in Section \ref{sec:missing_mechanism}, propose consistent estimators for these cases, and conduct a comprehensive statistical analysis.



Suppose that the base algorithm approximates the Q-function $Q^{\pi}$
% The Q-function $Q^{\pi}$ can be approximated 
with linear sieves \citep{shi2021statistical}, $Q^{\pi}(s, a) \approx \Phi_{L}^{\top}(s) \boldsymbol{\beta}_{\pi, a}$,
% $\forall s \in \mathcal{S}, a \in \mathcal{A}$,
where $\Phi_{L}(\cdot)=\left\{\boldsymbol{\phi}_{L, 1}(\cdot), \cdots, \boldsymbol{\phi}_{L, L}(\cdot)\right\}^{\top}$ denotes a vector of $L$ sieve basis functions. One can use splines \citep{de1976splines} or wavelet basis \citep{huang1998projection},  and the number of basis functions $L$ is allowed to grow with the sample size to reduce the approximation error\footnote{For a brief introduction to the definitions of B-splines and wavelet bases, please refer to Appendix~\ref{appendix:basis_intro}.}. For ease of notation, we first define $\boldsymbol{\beta}_{\pi}=(\boldsymbol{\beta}_{\pi, 1},\dots,\boldsymbol{\beta}_{\pi, m})^{\top}\in\mathbb{R}^{mL}$, $\boldsymbol{\xi}(s, a) 
=\{\Phi_{L}^{\top}(s) \mathbbm{1}(a=1), \cdots, \Phi_{L}^{\top}(s) \mathbbm{1}(a = m)\}^{\top}$, and $\boldsymbol{U}_{\pi}(s) 
=\{\Phi_{L}^{\top}(s) \pi(1 \vert s), \cdots, \Phi_{L}^{\top}(s) \pi(m \vert s)\}^{\top}$. Then, after some calculations, the Q-function can be expressed as $Q^{\pi}(s,a)= \boldsymbol{\xi}(s,a)^{\top}\boldsymbol{\beta}_{\pi}$, and the value function is $V^{\pi}(s)=\mathbb{E}_{a \sim \pi\left(\cdot \vert s\right)}\left[Q^{\pi}\left(s, a\right)\right]=\boldsymbol{U}_{\pi}(s)^{\top}\boldsymbol{\beta}_{\pi}$. 

When there is no missingness, one can follow the standard Bellman equation in \eqref{eq:bellman}, substitute the definitions above, and derive the following estimating equation:
$\mathbb{E}\left\{\boldsymbol{M}_t(\boldsymbol{\beta}_{\pi})\right\}=\boldsymbol{0}$,
where $\boldsymbol{M}_t(\boldsymbol{\beta}_{\pi})=
% \boldsymbol{M}_t(\boldsymbol{\beta}_{\pi})=
\boldsymbol{\xi}_{t}\big\{R_{t+1}+\gamma V^{\pi}(S_{t+1}) -Q^{\pi}(S_{t}, A_{t})\big\}
=\boldsymbol{\xi}_{t}\big\{R_{t+1}-(\boldsymbol{\xi}_{t}-\gamma \boldsymbol{U}_{\pi, t+1})^{\top} \boldsymbol{\beta}_{\pi}\big\}$. The problem of value function estimation thus reduces to a linear regression. The true parameter $\boldsymbol{\beta}_{\pi}^{*}$ can be estimated by solving the estimating equations $\mathbb{E}_{nT}\left\{\boldsymbol{M}_t(\boldsymbol{\beta}_{\pi})\right\}=\boldsymbol{0}$, where $\mathbb{E}_{nT}(\cdot)$ denotes the empirical average over $nT$ transition pairs of $(S_{i,t}, A_{i,t}, R_{i,t+1}, S_{i,t+1})$.
%This solution which is an extension of Least-Square Temporal Difference Q (LSTDQ) \citep{lagoudakis2003least}.


However, when dealing with MNAR, adjustments are necessary to obtain unbiased estimates. We define the propensity score as the probability of observing the data at time $t$, denoted by $1 - \lambda_t(\cdot)$. To ensure consistency in value estimates, an Inverse Probability Weighting (IPW) term, $\frac{\eta_{t+1}}{1 - \lambda_{t+1}(\cdot)}$, is incorporated into the estimating equation. Specifically, we consider the following estimating equation:
\begin{equation}\label{eq:MNAR_est}
{\small\begin{aligned}
\mathbb{E}_{nT}\left\{\frac{\eta_{t+1}}{1-\lambda_{t+1}(\boldsymbol{\psi})}\boldsymbol{M}_t(\boldsymbol{\beta}_{\pi})\right\}=\boldsymbol{0},
\end{aligned}}
\end{equation}
where $\lambda_{t+1}(\boldsymbol{\psi}):=\lambda\left(S_{t},A_t,R_{t+1},S_{t+1}; \boldsymbol{\psi}\right)$ is the dropout propensity model parameterized by $\boldsymbol{\psi}\in\mathbb{R}^q$. As we focus here on presenting the general framework, the estimation of $\boldsymbol{\psi}$, denoted by $\widehat{\boldsymbol{\psi}}_{nT}$, will be detailed in Section \ref{sec:dropout_est}. Based on Equation \eqref{eq:MNAR_est}, an IPW estimator for $\boldsymbol{\beta}_{\pi}$ is obtained as
{\small \begin{equation}
\begin{gathered}
\widehat{\boldsymbol{\beta}}_{\pi,\text{IPW}}=\\
    \Biggl\{\underbrace{\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \frac{\eta_{i,t+1}}{1-\lambda_{i,t+1}(\widehat{\boldsymbol{\psi}}_{nT})}\boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top}}_{\widehat{\boldsymbol{\Sigma}}_{\pi,\text{IPW}}}\Biggr\}^{-1}\\
    \left(\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \frac{\eta_{i,t+1}}{1-\lambda_{i,t+1}(\widehat{\boldsymbol{\psi}}_{nT})} \boldsymbol{\xi}_{i, t} R_{i, t+1}\right).
    \label{eq:beta_est_ipw}
\end{gathered}
\end{equation}}


The estimated Q-function and value function are 
given by 
% It follows that 
$\widehat{Q}^{\pi}_{\text{IPW}}(s,a)=\boldsymbol{\xi}^{\top}(s,a) \widehat{\boldsymbol{\beta}}_{\pi,\text{IPW}}$, $\widehat{V}^{\pi}_{\text{IPW}}(s)=\boldsymbol{U}_{\pi}^{\top}(s) \widehat{\boldsymbol{\beta}}_{\pi,\text{IPW}}$. Given a reference distribution $\mathbb{G}$ on state space $\mathcal{S}$, the integrated value can be estimated as 
$\widehat{V}^{\pi}_{\text{IPW}}(\mathbb{G})
=\int_{s \in \mathcal{S}} \widehat{V}^{\pi}_{\text{IPW}}(s) \mathbb{G}(d s)
=\{\int_{s\in\mathcal{S}} \boldsymbol{U}_{\pi}(s) \mathbb{G}(d s)\}^{\top} \widehat{\boldsymbol{\beta}}_{\pi,\text{IPW}}$. 
In practice, the integration $\int_{s \in \mathcal{S}} \boldsymbol{U}_{\pi}(s) \mathbb{G}(d s)$ can be approximated with sample average of $\boldsymbol{U}_{\pi}(s)$ using the reference distribution $\mathbb{G}$. 

Notice that if we disregard the weighting term $\{1-\lambda_{i,t+1}(\widehat{\boldsymbol{\psi}}_{nT})\}$ in the denominator, the estimating equation simplifies to $\mathbb{E}_{nT}\left\{\eta_{i,t+1}\boldsymbol{M}_t(\boldsymbol{\beta}_{\pi})\right\}=\boldsymbol{0}$, which represents a straightforward adaptation of the classical estimator that only incorporates observed examples into parameter estimation. For simplicity of reference in later sections, we refer to this approach as the Complete Case (CC) estimator. Following the same estimation logic as IPW, we derive
\begin{equation*}
{\small\begin{aligned}
    \widehat{\boldsymbol{\beta}}_{\pi,\text{CC}}
    =&\Biggl\{\underbrace{\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i,t+1} \boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top}}_{\widehat{\boldsymbol{\Sigma}}_{\pi,\text{CC}}}\Biggr\}^{-1}\\
     &\qquad\quad\left(\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i,t+1} \boldsymbol{\xi}_{i, t} R_{i, t+1}\right).
\end{aligned}}
\label{eq:beta_est_cc} 
\end{equation*}
The estimated value function and integrated value can be similarly obtained by $\widehat{V}^{\pi}_{\text{CC}}(s)
=\boldsymbol{U}_{\pi}^{\top}(s) \widehat{\boldsymbol{\beta}}_{\pi,\text{CC}}$, and $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})
=\{\int_{s\in\mathcal{S}} \boldsymbol{U}_{\pi}(s) \mathbb{G}(d s)\}^{\top} \widehat{\boldsymbol{\beta}}_{\pi,\text{CC}}$. 



When there are no missing data, both the IPW and CC estimators reduce to the base algorithm, and the value estimator is shown to be asymptotically normal as either $n\rightarrow\infty$ or $T\rightarrow\infty$ under regularity conditions (see Theorem 1 of \citet{shi2021statistical}). However, when dealing with incomplete data, the solution to $\mathbb{E}_{nT}\left\{\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}\right) \right\}=\boldsymbol{0}$ may differ from the solution to $\mathbb{E}_{nT}\left\{\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}\right)\right\}=\boldsymbol{0}$. 
The following theorem outlines when the complete-case value estimator remains valid and when it may not. 
\begin{theorem}
\label{thm:cc_consistency}
Suppose Assumption \ref{ass:SAVE} holds. $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})$ is a consistent estimator if the missing mechanism is ignorable (MAR). However, if the missing mechanism is nonignorable (MNAR), $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})$ can be biased. 
\end{theorem}
% \begin{proof}
% See Appendix \ref{appendix:cc_consistency_proof}.
% % See Appendix \ref{appendix:proof}, Theorem \ref{thm:cc_consistency_appendix}.
% \end{proof}
Assumption \ref{ass:SAVE} establishes the necessary conditions that ensure the consistency and asymptotic distribution of value estimation when there is no missing data. 
To the best of our knowledge, this is the first result establishing the validity of OPE methods in the presence of missing data. 
As per Theorem \ref{thm:cc_consistency}, the complete-case value estimator remains valid if the missing data mechanism is ignorable.
% , and thus no adjustment is needed. 
However, for nonignorable missingness, further adjustments based on IPW are required to retrieve consistency, as we will show in Theorem \ref{thm:ipw_consistency} and \ref{thm:ipw_asymptotics}. 

%Theorem \ref{thm:ipw_consistency} and \ref{thm:ipw_asymptotics} establish the consistency and asymptotic distribution of the proposed estimator under nonignorable missingness.
\begin{theorem}[Bidirectional Consistency]
\label{thm:ipw_consistency}
Assume conditions \ref{ass:SAVE} and \ref{ass:dropout_propensity} hold. $\widehat{V}_{\text{IPW}}^{\pi}(\mathbb{G})$ is a consistent estimator for value, i.e., $\widehat{V}_{\text{IPW}}^{\pi}(\mathbb{G})\stackrel{p}{\rightarrow}V^{\pi}(\mathbb{G})$ as either $n\rightarrow\infty$ or $T\rightarrow\infty$. 
\end{theorem}
\begin{theorem}[Bidirectional Asymptotics]
\label{thm:ipw_asymptotics}
Assume conditions \ref{ass:SAVE}-\ref{ass:dropout_propensity} hold. As either $n \rightarrow \infty \text { or } T \rightarrow \infty$, we have 
{\begin{equation*}
    \sqrt{n T} \widehat{\sigma}_{\pi,\mathrm{IPW}}^{-1}(\mathbb{G})\{\widehat{V}_{\mathrm{IPW}}^{\pi}(\mathbb{G})-V^{\pi}(\mathbb{G})\} \stackrel{d}{\rightarrow} \mathcal{N}(0,1),
\end{equation*}}
where 
$\widehat{\sigma}_{\pi,\text{IPW}}^{2}(\mathbb{G})$ is given by (\ref{eq:sigma_def_int}) in Appendix \ref{appendix:ipw_asymptotics_proof}. 
\end{theorem}


%Assumption \ref{ass:dropout_propensity} is the boundedness condition imposed on the dropout propensities. %Assumption \ref{ass:semiparametric-ipw} ensures the consistency and asymptotic normality of the dropout propensity estimation. 
The proofs for Theorems \ref{thm:cc_consistency}-\ref{thm:ipw_asymptotics} can be found in Appendix \ref{appendix:cc_consistency_proof}-\ref{appendix:ipw_asymptotics_proof}. Different from the asymptotic result presented in \citet{shi2021statistical}, we now take into account the response indicator $\eta_{t}$ and the uncertainty associated with dropout propensity estimation. Intuitively, observations with higher dropout propensities are assigned higher weights to adjust the data distribution so as to retain the consistency of value function.
As such, a two-sided Confidence Interval (CI) for $V^{\pi}(\mathbb{G})$ with significance level $\alpha$ can be constructed as 
