\section{Additional Experimental Details}\label{appendix:experiments}
% \section{Additional experimental details}\label{appendix:experiments}

In this section, we provide more details on the experiments and our implementation. 

\subsection{Algorithm}\label{appendix:algo}

The outline for the proposed estimator is presented in Algorithm \ref{alg:main}. In Line 5, when employing a semi-parametric model to estimate the dropout propensity function (see Appendix \ref{appendix:semiparam_est}), an approximation of the estimated standard deviation $\widetilde{\sigma}_{\pi,\text{IPW}}(\mathbb{G})$, as given in Equation \eqref{eq:approx_std}, can be used as a substitute for the exact solution $\widehat{\sigma}_{\pi,\text{IPW}}(\mathbb{G})$. Accordingly, the confidence interval can be obtained as $\left[\widehat{V}^{\pi}_{\text{IPW}}(\mathbb{G}) \pm z_{\alpha / 2}(nT)^{-1 / 2} \widetilde{\sigma}_{\pi,\text{IPW}}( \mathbb{G})\right]$.


\begin{algorithm}[ht]
\caption{Off-Policy Evaluation with Nonignorable Monotone Missingness}
\label{alg:main}
\begin{algorithmic}[1]
% \Require $n \geq 0$
% \Ensure $y = x^n$
\STATE {\bfseries Input:} Observed dataset $\mathcal{D}=\{\tau_i\}_{i=1}^{n}$, target policy $\pi$, discount factor $\gamma$, number of basis $L$
\STATE Fit dropout propensity model (\ref{eq:tilting_model_2}) using the semiparametric approach 
\STATE Construct a set of basis $\Phi_{L}(s)$ from state variables and estimate $\widehat{\boldsymbol{\beta}}_{\pi,\text{IPW}}$ by (\ref{eq:beta_est_ipw})
\STATE Estimate value $\widehat{V}^{\pi}_{\text{IPW}}(s)
=\boldsymbol{U}_{\pi}^{\top}(s) \widehat{\boldsymbol{\beta}}^{\pi}_{\pi,\text{IPW}}$,   $\widehat{V}_{\text{IPW}}^{\pi}(\mathbb{G})=\int_{s \in \mathcal{S}} \widehat{V}_{\text{IPW}}^{\pi}(s) \mathbb{G}(d s)$
\STATE Calculate the asymptotic variance $\widehat{\sigma}_{\pi,\text{IPW}}^{2}(\mathbb{G})$ given by Equation \eqref{eq:sigma_def_int} 
\STATE {\bfseries Return:} the CI of $V^{\pi}(\mathbb{G})$: 
$\left[\widehat{V}^{\pi}_{\text{IPW}}(\mathbb{G}) \pm z_{\alpha / 2}(nT)^{-1 / 2} \widehat{\sigma}_{\pi,\text{IPW}}( \mathbb{G})\right]$
\end{algorithmic}
\end{algorithm}


\subsection{Simulation Settings}\label{appendix:simple_sim}

\subsubsection{Data Generation}
The initial states are generated from the standard bivariate normal distribution $\mathcal{N}(\boldsymbol{0}_2, \boldsymbol{I}_2)$. For $t\geq 0$, we slightly modify the original dynamics and consider the following transition: $S_{t+1}^{(1)}=(2A_t-1)S_{t}^{(1)}+\varepsilon_{t}^{(1)}$, $S_{t+1}^{(2)}=(1-2A_t)S_{t}^{(2)}+\varepsilon_{t}^{(2)}$, where $\varepsilon_{t}^{(1)}$ and $\varepsilon_{t}^{(2)}$ are independent $\mathcal{N}(0,0.25)$ random variables. The immediate reward is designed as  $R_{t+1}=2S_{t+1}^{(1)}+S_{t+1}^{(2)}+0.5S_{t}^{(2)}-0.25(2A_t-1)+\varepsilon_t^{(3)}$, where $\varepsilon_t^{(3)}\sim\mathcal{N}(0, 10^{-4})$. The behavior policy follows a Bernoulli distribution with a mean of $0.5$. Throughout the simulation studies, we set the discount factor $\gamma$ to 0.9. 

To generate complete data with $n$ trajectories, we first sample $n$ initial states from the reference distribution $\mathbb{G}$, 
% a bivariate normal distribution $\mathcal{N}(\boldsymbol{0}_2, \boldsymbol{I}_2)$, 
and then generate the action, next state and reward following the generative model described above. This process is repeated until reaching the maximum horizon $T$. To generate incomplete data, we first calculate the dropout probability $\lambda_{i,t}$ at each step using the dropout model $\lambda_j(\cdot)$ defined in Section \ref{sec:synthetic_env}, this corresponds to the probability of subject $i$ dropping out after taking action $A_t$. Given the dropout probability, we sample the response indicator $\eta_{i,t+1}$ from a Bernoulli distribution with mean $(1-\lambda_{i,t})$. 
% The initial states and actions are always observed, so $\eta_{i,0}=1$. 
To control the overall missing rate, we also set a no-dropout period of two steps, i.e., $\eta_{i,0}=\eta_{i,1}=1$. After the second step, the dropout probability is applied and a trajectory will terminate when the response indicator $\eta_{i,t}$ turns $0$. 

\subsubsection{Complete-Case (CC) Estimator}


The OPE step of \citet{shi2021statistical} approximates the Q-function with linear sieves,
$Q^{\pi}(s, a) \approx \Phi_{L}^{\top}(s) \boldsymbol{\beta}_{\pi, a}$,
% $\forall \boldsymbol{s} \in \mathbb{S}, a \in \mathcal{A}$,
where $\Phi_{L}(\cdot)=\left\{\boldsymbol{\phi}_{L, 1}(\cdot), \cdots, \boldsymbol{\phi}_{L, L}(\cdot)\right\}^{\top}$ is a vector consisting of $L$ spline bases. In our implementation, we first scale the state variables onto $[0,1]$ and then construct 6 cubic B-spline bases for each dimension, where the knots are placed at equally-spaced quantiles of the transformed state variables. To avoid
extrapolation of the basis function, three repeated knots are placed on the boundary. The tensor product of the basis for each dimension is used to construct the final basis, hence $L=36$. The number of basis functions $L$ is allowed to grow with the sample size to reduce the approximation error. For a fair comparison, here we fix $L=36$ throughout the experiments despite the sample sizes. The CC estimator of the Q-function parameter $\boldsymbol{\beta}_{\pi}^{*}$ is given in (\ref{eq:beta_est_cc}). The matrix inversion of $\widehat{\boldsymbol{\Sigma}}_{\pi}\in\mathbb{R}^{mL\times mL}$ tends to be unstable when $mL$ is large, so we add a small ridge penalty with weight $10^{-5}$ to improve the stability. Given $\widehat{\boldsymbol{\beta}}_{\pi}$, the value function can be calculated as $\widehat{V}^{\pi}(s)=\boldsymbol{U}_{\pi}^{\top}(s) \widehat{\boldsymbol{\beta}}_{\pi}$. We approximate the integrated value $\widehat{V}^{\pi}(\mathbb{G})
=\int_{\boldsymbol{s} \in \mathcal{S}} \widehat{V}^{\pi}(\boldsymbol{s}) \mathbb{G}(d \boldsymbol{s})$ by sampling 10,000 states from the reference distribution $\mathbb{G}$ and take the average of the estimated value for each state. 
% The corresponding confidence interval is constructed as described in Section \ref{sec:ope_complete}.

\subsubsection{Solving the Estimating Equation \eqref{eq:M_estimation}}  \label{appendix:fit_dropout}

To calculate the IPW estimator, we need to estimate the dropout probability from the data first. For ignorable missingness (MAR), we fit a logistic regression with the correctly specified model to predict the dropout probability. For nonignorable missingness (MNAR), we adopt both parametric \citep{miao2024identification}
and semiparametric methods \citep{shao2016semiparametric} for flexible dropout model estimation. 

In the parametric estimation for the simulation study, we select $\boldsymbol{h}(S_t,A_t,Z_t) = [1, S_t^{(1)}, Z_t]^T$ for simplicity when learning $\psi$. Theoretically, it has been established (see \citet{miao2024identification}) that any function of $(S_t,A_t,Z_t)$ can be chosen as the $\boldsymbol{h}$-function in the estimating equation while maintaining estimation consistency. Furthermore, \citet{miao2024identification} demonstrated, by leveraging doubly robust estimation derived from the efficient influence function of $\boldsymbol{\psi}$, that there exists a specific function $h^{\text{eff}}(S_t,A_t,Z_t)$ capable of minimizing the estimation variance. However, given that the proposed value estimator in this work is based on IPW and to simplify practical implementation, we recommend users choose $h$ to be as simple as possible in real applications. For instance, incorporating an intercept term, using the original form of the non-shadow variables rather than higher-order polynomial transformations, and including the shadow variable in the construction of $h$ to ensure the identifiability of $\boldsymbol{\psi}$ can help reduce estimation variance and potentially improve the overall accuracy of the estimate.



In the semi-parametric estimation  for the simulation study, the shadow variable $S_t^{(2)}$ is discretized into 4 bins based on the quartiles.
The nonparametric part is approximated using Gaussian kernel with bandwidth $h_l=c\cdot\sigma_{l}n_{l}^{-1/3}$, where $\sigma_{l}$'s and $n_l$'s are the estimated standard deviation and the sample size for samples with $S_2=l\in\{1,2,3,4\}$. We pick $c=7.5$ in the bandwidth formula based on an inspection of the objective function curve. The parametric part, i.e. $\boldsymbol{\psi}$, is estimated using Equation \eqref{eq:M_estimation_appendix} by setting $\boldsymbol{h}(S_t,A_t,Z_t) = [\mathbbm{1}(Z_t=1),\dots,\mathbbm{1}(Z_t=3)]^T$. In the minimization step of GMM, we use the limited-memory BFGS algorithm \citep{liu1989limited} for both parametric and semi-parametric estimation with several initial values to avoid local minimum. In the semi-parametric estimation procedure, we recommend users construct the $\boldsymbol{h}$-function using the discretized shadow variable, which has been empirically shown to perform well in our synthetic studies.


\subsubsection{IPW Estimator}

After getting an estimate of the parameter $\widehat{\boldsymbol{\psi}}_{nT}$ for the dropout model, we plug in the estimated probability to calculate $\widehat{\boldsymbol{\beta}}_{\pi,\text{IPW}}$, which is given in (\ref{eq:beta_est_ipw}). To avoid extremely large inverse weight, we bound the missing propensity below at 0.01. After obtaining $\widehat{\boldsymbol{\beta}}_{\pi,\text{IPW}}$, we calculate the integrated value $\widehat{V}_{\text{IPW}}^{\pi}(\mathbb{G})$ in a similar way to the CC estimator. Finally, we can construct the confidence interval for the proposed IPW estimator based on the theoretical form of the asymptotic variance, as provided in Equation \eqref{eq:sigma_def_int}. Note that when using a semi-parametric model for dropout estimation, the asymptotic variance of $\boldsymbol{\psi}$ has a complex form (as discussed in \citet{shao2016semiparametric}), making it difficult to compute due to the non-parametric kernel $g(\mathcal{U}_t)$. To simplify the computation, we suggest using an approximation of $\widehat{\sigma}_{\pi,\text{IPW}}^{2}(\mathbb{G})$ given by (\ref{eq:approx_std}). In all the empirical experiments presented in the main paper and appendices, the confidence intervals based on this approximation are very close to those obtained through bootstrapping and provide stable and satisfactory coverage. Therefore, we use this approximation in our implementation.

\subsection{Real Data Application}\label{appendix:sepsis}

\paragraph{Data description}

The sepsis dataset is extracted from the MIMIC-III v1.4 database \citep{johnson2016mimic}. We follow the data processing procedure described in \citet{komorowski2018artificial} and use a pure-python re-implementation available at \url{https://github.com/microsoft/mimic_sepsis}. Data is included from the diagnosis of sepsis and until 48 hours following the onset of sepsis to capture treatment management at the early phase. We exclude mortality cases within this time window and only focus on early discharged patients. 

\paragraph{Model features} We consider a $14$-dimensional state feature vector to represent important features clinicians would examine when deciding treatment and dosage for patients. The following physiological features are used in our model: 
% to represent the most important parameters clinicians would examine when deciding treatment and dosage for patients. The physiological features used in our model include:  
% \begin{itemize}
\begin{itemize}[leftmargin=2em]
    \item Demographics: Age
    \item Lab values: Arterial pH, Chloride, Hemoglobin, INR-International Normalized Ratio, PT-Prothrombin Time, Arterial Blood Gas, Ionised Calcium, Calcium, Arterial Lactate
    \item Vital signs: SpO2, Temperature, Heart Rate
    \item Other: Sequential Organ Failure Assessment (SOFA) score
\end{itemize}
% demographics (Age), lab values (Arterial pH, Chloride, Hemoglobin, INR-International Normalized Ratio, PT-Prothrombin Time, Arterial Blood Gas, Ionised Calcium, Calcium, Arterial Lactate), vital signs (SpO2, Temperature, Heart Rate) and SOFA score. 
% We also include SOFA (Sequential Organ Failure Assessment) score \citep{vincent1996sofa} because it's a comprehensive score to measure the severity of organ dysfunction in 6 organ systems (respiratory, coagulation, liver, cardiovascular, renal, and neurological). This feature is also used in prior application of RL to sepsis treatment recommendation \citep{raghu2017deep, komorowski2018artificial}.
The features are aggregated over a time resolution of 4 hours, we carry the last value forward if no record is available in the current time window. 

\paragraph{Target policies}

In our experiments, we evaluate a fitted behavior policy and optimal policies learned via Deep Q-Network \citep{mnih2015human}, Dueling Double Deep Q-Network \citep{wang2016dueling} and a discrete version of Batch-Constrained Deep Q-Learning (BCQ) \citep{fujimoto2019offpolicy}. The behavior policy is fitted with a random forest with 250 trees. For the other three types of Q-learning algorithms, we run for $2\times 10^5$ iterations with minibatch size 256 and learning rate $1\times 10^{-3}$. 


\paragraph{More details about implementation} Similar to the simple environment, we first scale the state variables onto $[0,1]$ and construct 4 cubic B-spline basis for each dimension. We do not use tensor product here due to high-dimensionality concern, so there are $L=56$ bases in total. To fit the dropout model, we use the previous GCS score as a shadow variable, it is discretized into 4 bins based on quantiles. We consider the model in (\ref{eq:tilting_model_2}) with 
% $\mathcal{U}_t=\{\mathbbm{1}(X_t^{\text{FiO2}}\leq 0.6), \mathbbm{1}(60 \leq X_t^{\text{HR}}\leq 100), \mathbbm{1}(10 \leq X_t^{\text{RR}}\leq 30)\}$, $Z_{t+1}=\mathbbm{1}(X_{t+1}^{\text{GCS}}\geq 14),$ 
$\mathcal{U}_t=\{\mathbbm{1}(S_t^{\text{FiO2}}\leq 0.6), \mathbbm{1}(60 \leq S_t^{\text{HR}}\leq 100), \mathbbm{1}(10 \leq S_t^{\text{RR}}\leq 30)\}$, $Z_{t+1}=\mathbbm{1}(S_{t+1}^{\text{GCS}}\geq 14),$ 
and a bandwidth of $h_l=10\sigma_{l}n_{l}^{-1/3}$. For large dataset, the kernel estimator used in this semiparametric method can be a bottleneck in computation. To accelerate the algorithm, we apply the downsample technique where we repeatedly sample random subsets from the whole dataset and aggregate the value estimation results by taking average. 


\section{Generalizability of the Proposed Framework}\label{sec:generalizability}
% \section{Generalizability of proposed framework}\label{sec:generalizability}

In the main paper, we focus on the dropout scenario that occurs after the action is observed but before the reward and the next state are observed. Additionally, we use Least-Squares Temporal Difference Learning (LSTDQ) as the base OPE algorithm to investigate the effect of missing data. In this section, we will expand our scope to more general dropout patterns and other OPE methods. 

\subsection{More General Dropout Patterns} \label{sec:general_dropout}

The proposed framework is universally applicable to a broader class of dropout patterns. 
Specifically, the theoretical results for our IPW estimator are valid when dropout occurs after the observed action, regardless of whether the reward is observed or not. This is because the key idea behind the proposed IPW estimator is to assign weights to each transition based on the inverse probability of observing the complete transition quadruple $(S_t,A_t,R_{t+1},S_{t+1})$ given observed $(S_t,A_t)$. 
On the other hand, when dropout occurs after an observed state but before an observed action, the proposed framework also applies. The distinction lies in that MAR and MNAR are now defined with respect to $S_t$ instead of $(S_t,A_t)$. If the missingness of the current action only depends on the current state and not on the action itself, it is considered ignorable. In such cases, the CC estimator remains valid, and no further adjustment is required. This can be seen from the decomposition $\mathbb{E}\left\{\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}^{*}\right)\right\}
% =\mathbb{E}\left\{\mathbb{E}\left(\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}\right)\mid S_t,A_t,\eta_t\right)\right\}
=\mathbb{E}\left\{\mathbb{E}\left(\eta_{t+1}\mid S_t,\eta_t\right) \mathbb{E}\left(\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}^{*}\right)\mid S_t\right)\right\}=\boldsymbol{0}$. Here, $\mathbb{E}\left(\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}^{*}\right)\mid S_t\right)=\boldsymbol{0}$ follows from the law of total probability together with equation $\mathbb{E}\left\{R_{t+1}+\gamma V^{\pi}(S_{t+1}) -Q^{\pi}(S_{t}, A_{t}) \vert S_{t}, A_{t}\right\}=0$. 
In the case of nonignorable missingness where the dropout is dependent on the potential action, the CC estimator can be biased, and the proposed IPW estimator can still be used to mitigate such bias.
% On the other hand, when dropout occurs after an observed state but before an observed action, there are no incomplete trajectories since a new transition is not initiated. In this case, as long as $(S_t,A_t)$ has sufficient coverage, the CC estimator remains valid and no further adjustment is required. 
% Generally speaking, the IPW adjustment becomes necessary when the following conditions are met: (a) dropout occurs after an observed action; (b) some part of $(R_{t+1},S_{t+1})$ are missing due to dropout; and (c) the dropout propensity cannot be fully determined by $(S_t,A_t)$. 

Moreover, the idea of IPW adjustment can potentially be extended to handle intermittent missingness. The key distinction from monotone missingness lies in estimating the dropout propensity, which should be determined on a case-by-case basis and sometimes requires additional assumptions regarding the missing pattern. We leave this for future investigation.

\subsection{More General OPE Methods} \label{sec:general_ope}

In this section, we discuss how the proposed framework can be extended to Marginalized Importance Sampling-based (MIS) methods. We first introduce some additional notations and review the MIS value estimator. 

Given the discount factor $\gamma$ and reference distribution of initial states $\mathbb{G}$, the discounted state-action visitation probability density for policy $\pi$ is defined as 
$d_{\pi}(s, a)=(1-\gamma) \pi(a \mid s) \sum_{t=0}^{\infty} \gamma^t P\left(S_t=s \mid \pi\right)$. 
% , which represents the probability of visiting state-action pair $(s,a)$ following policy $\pi$ with $S_0\sim\mathbb{G}$.
% Similar to the Q-function, the occupancy satisfies the single-step transpose Bellman recurrence 
% \begin{align*}
%     d_{\pi}(s^{\prime}, a^{\prime})
%     =&
%     % (1-\gamma)
%     \mathbb{G}(s^{\prime})\pi(a^{\prime}\vert s^{\prime})+\gamma\cdot \pi(a^{\prime}\vert s^{\prime})\sum_{s\in\mathcal{S}}\sum_{a\in\mathcal{A}} d_{\pi}(s,a)p(s^{\prime}\vert s,a)\\
%     :=&
%     % (1-\gamma)
%     \mathbb{G}(s^{\prime})\pi(a^{\prime}\vert s^{\prime})+\gamma\cdot \mathcal{P}_{*}^{\pi} d_{\pi}(s^{\prime}, a^{\prime}),
% \end{align*}
% where $\mathcal{P}_{*}^{\pi}$ is the transpose policy transition operator. 
% This recursion reflects the conservation of flow of the stationary distribution on a Markov process.
It satisfies the backward Bellman recursion
\begin{align}
    d_{\pi}(s^{\prime}, a^{\prime})
    =&
    (1-\gamma)
    \mathbb{G}(s^{\prime})\pi(a^{\prime}\vert s^{\prime})+\gamma\cdot \pi(a^{\prime}\vert s^{\prime})\int_{s\in\mathcal{S}}\sum_{a\in\mathcal{A}} d_{\pi}(s,a)p(s^{\prime}\vert s,a) ds^{\prime}.
    % :=&
    % % (1-\gamma)
    % \mathbb{G}(s^{\prime})\pi(a^{\prime}\vert s^{\prime})+\gamma\cdot \mathcal{P}_{*}^{\pi} d_{\pi}(s^{\prime}, a^{\prime}),
    \label{eq:backward_bellman}
\end{align}
With the notation of $d_{\pi}(s, a)$, the policy value can also be expressed as 
$$V_{\mathbb{G}}^{\pi}
=\frac{1}{1-\gamma}\mathbb{E}_{(S_t, A_t) \sim d_{\pi}, R_{t+1} \sim r(S_t, A_t)}\left\{R_{t+1}\right\}.$$
In offline settings, the data may be collected from potentially different policies than the target policy $\pi$, denote the state-action visitation probability density under behavior policies as $d_{\mathcal{D}}$. 
% \footnote{Slightly abusing the notation, we will use $d_{\mathcal{D}}$ to denote both the true visitation distribution and the empirical visitation distribution.} 
To estimate the value using off-policy data, define the marginalized density ratio under the target policy $\pi$ as 
% $$\omega_{\pi}(s, a)=\frac{(1-\gamma)d_{\pi}(s, a)}{d_{\mathcal{D}}(s, a)}.$$
$$\omega_{\pi}(s, a):=\frac{d_{\pi}(s, a)}{d_{\mathcal{D}}(s, a)}.$$
Then the policy value can be equivalently expressed as 
\begin{equation*}
    V_{\mathbb{G}}^{\pi}
    =\frac{1}{1-\gamma}\mathbb{E}_{(S_t, A_t) \sim d_{\mathcal{D}}, R_{t+1}\sim r(S_t,A_t)}\left\{\omega_{\pi}(S_t,A_t)\cdot R_{t+1}\right\},
    % \label{eq:value_int_mis}
\end{equation*}
which leads to the MIS value estimator \citep{liu2018breaking,xie2019towards}. Compared with trajectory-based importance sampling methods, such a marginalized density ratio plays a critical role in breaking the curse of horizon. To handle unknown behavior policies, it is preferred to model the density ratio $\omega_{\pi}(s, a)$ directly, 
% Here we focus on the Minimax Weight Learning (MWL) algorithm \citep{uehara2020minimax} as it is a more direct way to estimate $\omega_\pi(s,a)$ than DaulDICE \citep{nachum2019dualdice}. 
and plug in $\widehat{\omega}_{\pi}(s, a)$ to obtain the final value estimate as follows, 
\begin{equation*}
    % \widehat{V}_{\mathbb{G}}^{\pi}=\frac{1}{1-\gamma}\mathbb{E}_{(S, A) \sim d_{\mathcal{D}}, R\sim r(S,A)}\left[\widehat{\omega}_{\pi}(S,A)\cdot R\right].
    \widehat{V}_{\mathbb{G}}^{\pi}=\frac{1}{1-\gamma} \frac{1}{nT}\sum_{i=1}^{n} \sum_{t=0}^{T-1} \widehat{\omega}_{\pi}(S_{i,t},A_{i,t}) R_{i,t+1}.
    % \label{eq:value_int_mis_emp}
\end{equation*}

The key for estimating $\omega_{\pi}(s, a)$ is by noting the following result derived from (\ref{eq:backward_bellman}),   
\begin{gather*}
% \begin{split}
\mathbb{E}_{d_{\mathcal{D}}}\left\{\omega_{\pi}(S_t,A_t) \left(f(S_t,A_t) 
- \gamma\mathbb{E}_{S_{t+1}\sim p(\cdot\vert S_t,A_t), a^\prime\sim\pi(\cdot|S_{t+1})}\left[f(S_{t+1},a^\prime)\right]\right)\right\}\\
=(1-\gamma) \mathbb{E}_{S_0 \sim \mathbb{G},a\sim\pi(\cdot|S_0)}\left[f\left(S_0,a\right)\right].
% \label{eq:mis_eq}
% \end{split}
\end{gather*}
A special case is to replace with $f(s,a)$ with $Q^{\pi}(s,a)$, leading to the following equation 
\begin{equation}
\begin{split}
\begin{gathered}
\mathbb{E}_{d_{\mathcal{D}}}\left\{\omega_{\pi}(S_t,A_t) \left(Q^{\pi}(S_t,A_t) 
- \gamma\mathbb{E}_{S_{t+1}\sim p(\cdot\vert S_t,A_t), a^\prime\sim\pi(\cdot|S_{t+1})}\left[Q^{\pi}(S_{t+1},a^\prime)\right]\right)\right\}\\
=(1-\gamma) \mathbb{E}_{S_0 \sim \mathbb{G},a\sim\pi(\cdot|S_0)}\left[Q^{\pi}\left(S_0,a\right)\right].
\label{eq:mis_eq}
\end{gathered}
\end{split}
\end{equation}
Another way to derive (\ref{eq:mis_eq}) is by noting the equivalence between two expressions of the policy value 
\begin{gather*}
    \mathbb{E}_{d_{\mathcal{D}}}[\omega_{\pi}(S_t, A_t) \cdot r(S_t,A_t)]
    =(1-\gamma) \mathbb{E}_{S_0\sim \mathbb{G},a\sim\pi(\cdot|S_0)}\left[Q^{\pi}\left(S_0, a\right)\right],
\end{gather*}
and then replacing 
