\textbf{Theorem} Suppose Assumption \ref{ass:SAVE} holds. $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})$ is a consistent estimator if the missing mechanism is ignorable (MAR). However, if the missing mechanism is nonignorable (MNAR), $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})$ can be biased. 

\begin{proof}\label{proof:thm1}
We first provide a sketch of the big idea. Assume the true Q-function is $Q^{\pi}(s,a)=\Phi^{\top}_{L}(s)\boldsymbol{\beta}_{\pi}^{*}$ and the true parameter $\boldsymbol{\beta}^{*}$ satisfies $\mathbb{E}\left\{\boldsymbol{M}_t\left(\boldsymbol{\beta}_{\pi}^{*}\right)\right\}=\boldsymbol{0}$, where  $\boldsymbol{M}_t(\boldsymbol{\beta}_{\pi})=\boldsymbol{\xi}_{t}\left\{R_{t+1}-(\boldsymbol{\xi}_{t}-\gamma \boldsymbol{U}_{\pi, t+1})^{\top} \boldsymbol{\beta}_{\pi}\right\}$. Under incomplete data, the equation becomes $\mathbb{E}\left\{\eta_{t+1}\boldsymbol{M}_t\left(\boldsymbol{\beta}_{\pi}\right)\right\}=\boldsymbol{0}$. Using the condition of MAR (Definition \ref{def:mar}), we apply the conditional independence between $\eta_{t+1}$ and $(S_{t+1}, R_{t+1})$
% $\eta_{t+1}\indep (_{t+1}, R_{t+1})\mid (_t, A_t)$ 
to separate the $\eta_{t+1}$ and $\boldsymbol{M}_t$ term as follows 
\begin{equation*}
\begin{aligned}
\mathbb{E}\left\{\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}\right)\right\}
&=\mathbb{E}\left\{\mathbb{E}\left(\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}\right)\mid S_t,A_t,\eta_t\right)\right\}\\
&=\mathbb{E}\left\{\mathbb{E}\left(\eta_{t+1}\mid S_t,A_t,\eta_t\right) \mathbb{E}\left(\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}\right)\mid S_t,A_t\right)\right\}.
\end{aligned}
\end{equation*}
It follows from $\mathbb{E}\{R_{t+1}+\gamma \sum_{a^{\prime} \in \mathcal{A}} Q^{\pi}(S_{t+1}, a^{\prime}) \pi(a^{\prime} \vert S_{t+1}) -Q^{\pi}(S_{t}, A_{t}) \vert S_{t}, A_{t}\}=0$ that $\mathbb{E}\{\boldsymbol{M}_t( \boldsymbol{\beta}_{\pi}^{*})\vert S_t,A_t\}=\boldsymbol{0}$. Therefore, $\mathbb{E}\left\{\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}^{*}\right)\right\}=\boldsymbol{0}$,  then $\boldsymbol{\beta}_{\pi}^{*}$ is still the solution to $\mathbb{E}\left\{\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}\right)\right\}=\boldsymbol{0}$. As a result, the corresponding value estimator is still unbiased under some regularity conditions. However, for nonignorable missingness (MNAR), $\mathbb{E}\left\{\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}_{\pi}^{*}\right)\right\}=\boldsymbol{0}$ no longer holds because $\eta_{t+1}$ and $\boldsymbol{M}_t$ cannot be separated using the conditional independence. Thus the complete-case estimator $\widehat{\boldsymbol{\beta}}_{\pi,\text{CC}}$ will be biased from $\boldsymbol{\beta}_{\pi}^{*}$ unless the probability $P\left(\eta_{t+1}=1\mid S_t, A_t, R_{t+1}, S_{t+1},\eta_t\right)$ is a constant. 

Next, we provide a more rigorous proof that takes into account the approximation error. 

By Condition \ref{ass:SAVE}(a)(b)(e), the number of basis $L$ for the Q-function satisfies $L^{2 p / d} \gg n T\left\{1+\|\int_{s} \Phi_{L}(s) \mathbb{G}(d s)\|_{2}^{-2}\right\}$, it follows from Lemma \ref{lemma:5} that $L^{2 p / d} \gg n T\left\{1+\|\int_{s} \boldsymbol{U}(s) \mathbb{G}(d s)\|_{2}^{-2}\right\}$. By Lemma \ref{lemma:1} and Condition \ref{ass:SAVE}(b), there exist a set of vectors $\{\beta_{a}^{*}\}$ that satisfy
\begin{equation}\label{eq:E.37}
    \sup _{s \in \mathcal{S}, a \in \mathcal{A}}\left\vert Q^{\pi}(s, a)-\Phi_{L}^{\top}(s) \beta_{a}^{*}\right\vert \leq C L^{-p / d}, 
\end{equation}
for some constant $C>0$ \citep{huang1998projection}. Let $\boldsymbol{\beta}^{*}=(\beta_{1}^{* \top}, \ldots, \beta_{m}^{* \top})^{\top}$, define
\begin{equation}
\label{eq:define_r_eps}
\begin{gathered}
    r_{i, t}=\gamma \sum_{a \in \mathcal{A}}\left\{\Phi_{L}^{\top}\left(S_{i, t+1}\right) \beta_{a}^{*}-Q^{\pi}\left(S_{i, t+1}, a\right)\right\} \pi\left(a \vert S_{i, t+1}\right)
    -\left\{\Phi_{L}^{\top}\left(S_{i, t}\right) \beta_{A_{i, t}}^{*}-Q^{\pi}\left(S_{i, t}, A_{i, t}\right)\right\},\\
    \varepsilon_{i,t}=R_{i,t+1}+\gamma \sum_{a \in \mathcal{A}} Q^{\pi}(S_{i,t+1},a) \pi\left(a \vert S_{i,t+1}\right)-Q^{\pi}(S_{i,t},A_{i,t}).
\end{gathered}
\end{equation}
% then the temporal difference error can be expressed as
% \begin{equation*}
%     \widehat{\varepsilon}_{i,t}
%     =R_{i, t+1} + \gamma \sum_{a \in \mathcal{A}} \pi\left(a \mid S_{i, t+1}\right) \Phi_{L}^{\top}\left(S_{i, t+1}\right) \beta_{a}^{*}  - \Phi_{L}^{\top}\left(S_{i, t}\right) \beta_{A_{i, t}}^{*} 
%     =r_{i,t}+\varepsilon_{i,t}.
% \end{equation*}
The condition $P\left(\max _{t}\vert R_{t} \vert \leq c_0\right)=1$ in Assumption \ref{ass:SAVE}(f) implies that $R_{i,t}\leq c_0$, $\forall i,t$, almost surely. By Lemma \ref{lemma:1}, we have $\vert Q^{\pi}(s, a)\vert \leq c^{\prime}$ for any $\pi, s, a$. Therefore, the error term $\varepsilon_{i,t}$ can be bounded as follows 
\begin{equation}\label{eq:E.38}
    \max _{0 \leq t < T,1 \leq i \leq n}\left\vert\varepsilon_{i, t}\right\vert \leq c_{0}+(\gamma+1) c^{\prime} \leq c_{0}+2 c^{\prime}, \text{ almost surely. }
\end{equation}
In addition, it follows from (\ref{eq:E.37}) that 
\begin{equation}\label{eq:E.39}
    \max _{0 \leq t < T,1 \leq i \leq n}\left\vert r_{i, t}\right\vert \leq 2 \sup _{s \in \mathcal{S}, a \in \mathcal{A}}\left\vert Q^{\pi}(s, a)-\Phi_{L}^{\top}(s) \beta_{a}^{*}\right\vert \leq 2 C L^{-p / d}.
\end{equation}

For incomplete data, we can only leverage the observed samples for inference. With the response indicator $\eta_t$ defined in Section \ref{sec:OPE_incomplete}, the estimating equations can be written as   $\mathbb{E}\left\{\boldsymbol{M}_t\left(\boldsymbol{\beta}^{*}\right)\vert \eta_{t+1}=1\right\}=\boldsymbol{0}$, or equivalently, $\mathbb{E}\left\{\eta_{t+1}\boldsymbol{M}_t\left( \boldsymbol{\beta}^{*}\right)\right\}=\boldsymbol{0}$. The estimator for $\boldsymbol{\beta}^{*}$ is given  by 
\begin{equation*}
    \widehat{\boldsymbol{\beta}}_{\text{CC}}=\Biggl\{\underbrace{\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i, t+1}\boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{i, t+1}\right)^{\top}}_{\widehat{\boldsymbol{\Sigma}}_{\text{CC}}}\Biggr\}^{-1}\left(\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i, t+1} \boldsymbol{\xi}_{i, t} R_{i, t+1}\right).
\end{equation*}
Let $\boldsymbol{\Sigma}_{\text{CC}}=\mathbb{E}\widehat{\boldsymbol{\Sigma}}_{\text{CC}}$. By definition, 
\begin{equation*}
    \begin{aligned}
    \widehat{\boldsymbol{\beta}}_{\text{CC}}-\boldsymbol{\beta}^{*}
    &=\widehat{\boldsymbol{\Sigma}}_{\text{CC}}^{-1}\left[\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}
    \eta_{i, t+1}
    \boldsymbol{\xi}_{i, t}\left\{R_{i, t+1}-\left(\boldsymbol{\xi}_{i, t}-\gamma \boldsymbol{U}_{i, t+1}\right)^{\top} \boldsymbol{\beta}^{*}\right\}\right] \\
    &= \widehat{\boldsymbol{\Sigma}}_{\text{CC}}^{-1}\left[\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}
    \eta_{i, t+1}
    \boldsymbol{\xi}_{i, t}\times \right.\\
    &\qquad \left.\left\{R_{i, t+1}-\Phi_{L}^{\top}\left(S_{i, t}\right) \beta_{A_{i, t}}^{*}+\gamma \sum_{a \in \mathcal{A}} \Phi_{L}^{\top}\left(S_{i, t+1}\right) \beta_{a}^{*} \pi\left(a \mid S_{i, t+1}\right)\right\}\right] \\
    &= \widehat{\boldsymbol{\Sigma}}_{\text{CC}}^{-1}\left\{\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}
    \eta_{i, t+1}
    \boldsymbol{\xi}_{i, t}\left(\varepsilon_{i, t}+r_{i, t}\right)\right\}\\
    &=\underbrace{\boldsymbol{\Sigma}_{\text{CC}}^{-1}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}
    \eta_{i, t+1}
    \boldsymbol{\xi}_{i, t} \varepsilon_{i, t}\right)}_{\zeta_{1}} 
    + \underbrace{\left(\widehat{\boldsymbol{\Sigma}}_{\text{CC}}^{-1}-\boldsymbol{\Sigma}_{\text{CC}}^{-1}\right)\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}
    \eta_{i, t+1}
    \boldsymbol{\xi}_{i, t} \varepsilon_{i, t}\right)}_{\zeta_{2}}\\
    & \qquad + \underbrace{\widehat{\boldsymbol{\Sigma}}_{\text{CC}}^{-1}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
    \eta_{i, t+1}
    \boldsymbol{\xi}_{i, t} r_{i, t}\right)}_{\zeta_{3}} .
    \end{aligned}
\end{equation*}
% \textbf{Error bound for $\left\|\zeta_{3}\right\|_{2}$.}
It suffices to derive the error bounds for $\|\zeta_{1}\|_{2}$, $\|\zeta_{2}\|_{2}$, and $\|\zeta_{3}\|_{2}$. 

% We first derive the error bound for $\|\zeta_{3}\|_{2}$. 
\paragraph{Error bound for $\|\zeta_{3}\|_{2}$.} 
For any $\boldsymbol{a}\in\mathbb{R}^{mL}$,
\begin{equation}\label{eq:bound_zeta3}
\begin{gathered}
    \left\vert\boldsymbol{a}^{\top}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
    \eta_{i, t+1} \boldsymbol{\xi}_{i, t} r_{i, t}\right)\right\vert
    \leq \frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\left\vert\boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t}\right\vert\left\vert r_{i, t}\eta_{i, t+1}\right\vert
    \leq \max _{i, t}\vert r_{i, t}\vert\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\left\vert\boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t}\right\vert\right)\\
    \leq 2CL^{-p/d}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\left\vert\boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t}\right\vert\right)
    \leq 2CL^{-p/d}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top} \boldsymbol{a}\right)^{1 / 2}.
\end{gathered}
\end{equation}
The second inequality uses the bound of binary $\eta_{t}$ that $\vert\eta_t\vert\leq 1$, the third inequality follows from (\ref{eq:E.39}), and the fourth inequality applies the Cauchy-Schwarz inequality.
% $\vert\boldsymbol{a}^{\top}(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
%     \eta_{i, t+1} \boldsymbol{\xi}_{i, t} r_{i, t})\vert
%     \leq \frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\vert\boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t}\vert\vert r_{i, t}\eta_{i, t+1}\vert
%     \leq \max _{i, t}\vert r_{i, t}\vert(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\vert\boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t}\vert).$
% It follows from Cauchy-Schwarz inequality and Equation (\ref{eq:E.39}) that 
% \begin{equation*}\label{eq:bound_zeta3}
% \begin{aligned}
%     \left\vert\boldsymbol{a}^{\top}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
%     \eta_{i, t+1}
%     \boldsymbol{\xi}_{i, t} r_{i, t}\right)\right\vert 
%     &\leq 2CL^{-p/d}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\left\vert\boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t}\right\vert\right)\\
%     &\leq 2CL^{-p/d}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top} \boldsymbol{a}\right)^{1 / 2},
% \end{aligned}
% \end{equation*}
Then we obtain 
$$\left\|\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i, t+1} \boldsymbol{\xi}_{i, t} r_{i, t}\right\|_{2}
    \leq 2CL^{-p / d} \lambda_{\max }^{1 / 2}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top}\right).$$
By Lemma \ref{lemma:3} and Lemma \ref{lemma:4}, we have 
\begin{equation}\label{eq:thm1_zeta3_bound}
\left\|\zeta_{3}\right\|_{2}
\leq \left\|\widehat{\boldsymbol{\Sigma}}_{\text{CC}}^{-1}\right\|_{2}\left\|\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i, t+1} \boldsymbol{\xi}_{i, t} r_{i, t}\right\|_{2}
=O_p(1)O_{p}\left(L^{-p / d}\right)=O_{p}\left(L^{-p / d}\right),
% =o_p(1).
\end{equation}
which indicates that $\zeta_{3}$ is driven by the approximation error of the Q-function, and can be controlled by increasing the number of basis functions. 
% hence 
% \begin{equation}
%     \label{eq:thm1_zeta3_bound}
%     \zeta_{3}=O_{p}\left(L^{-p / d}\right).
% \end{equation}

% \paragraph{Error bounds for $\left\|\zeta_{1}\right\|_{2}$ and $\left\|\zeta_{2}\right\|_{2}$.}

The main difference between ignorable missingness (MAR) and nonignorable missingness (MNAR) lies in $(\zeta_1+\zeta_2)$. In the following steps, we will show that the complete-case value estimator $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})$ is still consistent under ignorable missingness (MAR) but becomes biased under nonignorable missingness (MNAR). 

\begin{itemize}
    \item \textbf{MAR}
\end{itemize}

To show $\|\widehat{\boldsymbol{\beta}}_{\text{CC}}-\boldsymbol{\beta}^{*}\|_2=o_p(1)$, we need to derive the error bound for $\left\|\zeta_{1}\right\|_{2}$, $\left\|\zeta_{2}\right\|_{2}$ and show they are $o_p(1)$. 
\paragraph{Error bound for $\left\|\zeta_{2}\right\|_{2}$.} 
% \paragraph{Error bounds for $\left\|\zeta_{1}+\zeta_{2}\right\|_{2}$.} 
We first derive the error bound for $\left\|\zeta_{2}\right\|_{2}$. 
By Markov Assumption, Conditional Mean Independence Assumption and Bellman equation, $\mathbb{E}\left(\varepsilon_{t} \vert \mathcal{F}_{t}\right)=\mathbb{E}\left(\varepsilon_{t} \vert S_{t}, A_{t}\right)=0$, where $\mathcal{F}_{t}=\{(S_{j},A_{j},R_{j+1})\}_{0\leq j<t}\cup\{S_{t}, A_{t}\}$ denotes the past information up to time $t$. Together with the conditional independence of $\eta_{t+1}$ and $\varepsilon_t$ based on the definition of MAR, we have $\mathbb{E}
    \left\{
    \eta_{t+1}
    \boldsymbol{\xi}_{t} \varepsilon_{t}
    \right\}
    =\mathbb{E}
    \left\{\mathbb{E}\left(\eta_{t+1}
    \boldsymbol{\xi}_{t} \varepsilon_{t}\vert \mathcal{F}_{t},\eta_{t}\right)
    \right\}
    =\mathbb{E}
    \left\{\boldsymbol{\xi}_{t} \mathbb{E}\left(\eta_{t+1}
    \vert \mathcal{F}_{t},\eta_t\right)
    \mathbb{E}\left(\varepsilon_{t}
    \vert \mathcal{F}_{t}\right)
    \right\}=\boldsymbol{0}.$
% In the rest of the proof, we will suppress the subscript of the expectation sign. 
Similarly, for any $0\leq t_1<t_2< T$, we obtain 
$\mathbb{E}\{
    \eta_{t_1+1} \eta_{t_2+1}
    \varepsilon_{t_1}\varepsilon_{t_2}
    \boldsymbol{\xi}_{t_1}^{\top}\boldsymbol{\xi}_{t_2}
\}=0.$
% $\mathbb{E}
%     \left\{
%     \eta_{t_1+1} \eta_{t_2+1}
%     \varepsilon_{t_1}\varepsilon_{t_2}
%     \boldsymbol{\xi}_{t_1}^{\top}\boldsymbol{\xi}_{t_2}
%     \right\}    
%     =\mathbb{E}
%     \left\{\eta_{t_1+1}\varepsilon_{t_1} \mathbb{E}(\eta_{t_2+1}\varepsilon_{t_2}\vert \mathcal{F}_{t_2},\overline{\eta}_{t_2})
%     \boldsymbol{\xi}_{t_1}^{\top}\boldsymbol{\xi}_{t_2}
%     \right\}=0.$ 
In addition, by the independence assumption among trajectories, we have 
$\mathbb{E}
    \{\eta_{i_1,t_1+1}\eta_{i_2,t_2+1}
    \varepsilon_{i_1, t_1}\varepsilon_{i_2, t_2}
    \boldsymbol{\xi}_{i_1, t_1}^{\top}\boldsymbol{\xi}_{i_2, t_2}
    \}=0.
$
It follows that $\mathbb{E}\|\sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i,t+1} \boldsymbol{\xi}_{i, t} \varepsilon_{i, t}\|_{2}^{2}
    =\sum_{i=1}^{n} \sum_{t=0}^{T-1} \mathbb{E} \left\{\eta_{i,t+1}^2\varepsilon_{i, t}^{2} \boldsymbol{\xi}_{i, t}^{\top} \boldsymbol{\xi}_{i, t}\right\}
    =n \sum_{t=0}^{T-1} \mathbb{E} \left\{ \eta_{t+1}^2 \varepsilon_{t}^{2} \boldsymbol{\xi}_{t}^{\top} \boldsymbol{\xi}_{t}\right\}.$
% The response indicator $\eta_{t}$ takes binary value, hence $\vert\eta_t\vert\leq 1$. 
Together with (\ref{eq:E.38}) and Lemma \ref{lemma:2}, we obtain
\begin{equation*}
\begin{gathered}
    \mathbb{E}\left\|\sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i,t+1} \boldsymbol{\xi}_{i, t} \varepsilon_{i, t}\right\|_{2}^{2} 
    \leq \left(c_{0}+2 c^{\prime}\right)^{2} n \sum_{t=0}^{T-1} \mathbb{E} \boldsymbol{\xi}_{t}^{\top} \boldsymbol{\xi}_{t}
    \leq \left(c_{0}+2 c^{\prime}\right)^{2} nT \sup _{s \in \mathcal{S}}\left\|\Phi_{L}(s)\right\|_{2}^{2}
    \preceq n T L.
\end{gathered}
\end{equation*}
% Here, we use notation $a_{nT} \preceq b_{nT}$ to indicate that there exists some constant $C>0$ such that $a_{nT} \leq C\cdot b_{nT}$ for any $nT$. The notation $a_{nT} \preceq 1$ means $a_{nT} =O(1)$.

By Markov inequality, 
$$\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\eta_{i, t+1}\boldsymbol{\xi}_{i, t} \varepsilon_{i, t}=O_{p}\{\sqrt{L /(n T)}\}.$$ 
Combine with Lemma \ref{lemma:3} yields 
\begin{equation}
    \label{eq:thm1_zeta2_bound}
    \zeta_{2}=O_{p}\{\sqrt{L / n T} \log (n T)\} O_{p}\{\sqrt{L /(n T)}\}=O_{p}\left\{L(n T)^{-1} \log (n T)\right\}.
\end{equation}
\paragraph{Error bound for $\left\|\zeta_{1}\right\|_{2}$.} 
Using similar arguments as bounding $\left\|\zeta_{2}\right\|_{2}$, we obtain \begin{equation}
    \label{eq:thm1_zeta1_bound}
    \zeta_{1}=O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2}\right\}.
\end{equation}

Combining (\ref{eq:thm1_zeta3_bound}), (\ref{eq:thm1_zeta2_bound}), and (\ref{eq:thm1_zeta1_bound}), we have
\begin{equation*}
\widehat{\boldsymbol{\beta}}_{\text{CC}}-\boldsymbol{\beta}^{*}=O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2}\right\} + O_{p}\left\{L(n T)^{-1} \log (n T)\right\} + O_{p}\left\{L^{-p / d}\right\}.
\end{equation*}
It follows from Condition \ref{ass:SAVE}(e) 
% on the number of basis functions $L$ 
that 
$$\|\widehat{\boldsymbol{\beta}}_{\text{CC}}-\boldsymbol{\beta}^{*}\|_{2}=O_{p}\left(L^{-p / d}\right)+O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2}\right\}=o_p(1).$$
Recall that $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})=\left\{\int_{s} \boldsymbol{U}(s) \mathbb{G}(d s)\right\}^{\top} \widehat{\boldsymbol{\beta}}_{\text{CC}}$, thus, 
\begin{equation}\label{eq:value_error_bound}
    \left\vert\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G}) - V^{\pi}(\mathbb{G})\right\vert
\leq \left\|\int_{s} \boldsymbol{U}(s) \mathbb{G}(d s)\right\|_2 \left\|\widehat{\boldsymbol{\beta}}_{\text{CC}}-\boldsymbol{\beta}^{*}\right\|_2=o_p(1),
\end{equation}
that is, $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})\stackrel{p}{\rightarrow}V^{\pi}(\mathbb{G})$ as $nT\rightarrow\infty$. Therefore, the value estimator $\widehat{V}_{\text{CC}}^{\pi}(\mathbb{G})$ is still consistent when the dropout mechanism is MAR.

\begin{itemize}
    \item \textbf{MNAR}
\end{itemize} 
\paragraph{Error bounds for $\left\|\zeta_{1}+\zeta_{2}\right\|_{2}$.}
Under nonignorable missingness, the conditional independence of $\eta_{t+1}$ and $\varepsilon_{t}$ no longer holds, so
\begin{equation*}
\begin{aligned}
    \mathbb{E}\left\{\eta_{t+1}\boldsymbol{\xi}_{t} \varepsilon_{t}\right\}
    &=\mathbb{E}\left\{\mathbb{E}\left\{\eta_{t+1}\boldsymbol{\xi}_{t} \varepsilon_{t}\mid \mathcal{F}_{t},S_{t+1},R_{t+1},{\eta}_{t}\right\}\right\}
    =\mathbb{E}\left\{\boldsymbol{\xi}_{t} \varepsilon_{t} \mathbb{E}\left\{\eta_{t+1}\mid \mathcal{F}_t,S_{t+1},R_{t+1},{\eta}_{t}\right\}\right\}\\
    &=\mathbb{E}
    \left\{\boldsymbol{\xi}_{t}\varepsilon_{t}\eta_{t}(1-\lambda(S_t,A_t,S_{t+1},R_{t+1}))
    \right\}
    \neq\boldsymbol{0}.
\end{aligned}
\end{equation*}
We cannot bound the term $\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}\eta_{i, t+1}\boldsymbol{\xi}_{i, t} \varepsilon_{i, t}$ as in the MAR case. As a result, $\|\zeta_1+\zeta_2\|=o_p(1)$ may no longer holds. Therefore, $\widehat{V}^{\pi}(\mathbb{G})$ can be biased when the dropout mechanism is MNAR.
\end{proof}

