\subsection{Proof of Theorem \ref{thm:ipw_consistency}}\label{appendix:ipw_consistency_proof}

\textbf{Theorem} Assume conditions \ref{ass:SAVE} and \ref{ass:dropout_propensity} hold. $\widehat{V}_{\text{IPW}}^{\pi}(\mathbb{G})$ is a consistent estimator for value, i.e., $\widehat{V}_{\text{IPW}}^{\pi}(\mathbb{G})\stackrel{p}{\rightarrow}V^{\pi}(\mathbb{G})$ as either $n\rightarrow\infty$ or $T\rightarrow\infty$. 
% \begin{theorem}[Bidirectional Consistency]
% \label{thm:ipw_consistency_appendix}
% Assume conditions \ref{ass:SAVE}-\ref{ass:dropout_propensity}(b) hold. Then $\widehat{V}_{\mathrm{IPW}}^{\pi}(\mathbb{G})$ is a consistent estimator of value, that is, $\widehat{V}_{\mathrm{IPW}}^{\pi}(\mathbb{G})\stackrel{p}{\rightarrow}V^{\pi}(\mathbb{G})$ as either $n\rightarrow\infty$ or $T\rightarrow\infty$. 
% \end{theorem}

\begin{proof}
The steps in this proof will be very similar to the proof of Theorem \ref{thm:cc_consistency}, but now we incorporate the inverse weights. 
For simplicity, we use the notation 
$$\omega_{i,t+1}(\boldsymbol{\psi}):=\eta_{i,t+1}\{1-\lambda(S_{i,t},A_{i,t},R_{i,t+1},S_{i,t+1};\boldsymbol{\psi})\}^{-1}$$ 
to represent the weighting term, where $\boldsymbol{\psi}\in\mathbb{R}^{k}$ is the parameter of the dropout propensity model. Under assumption \ref{ass:dropout_propensity}(a) on the correct specification of the dropout propensity, there exists some $\boldsymbol{\psi}^{*}$ such that $\lambda(S_{t},A_t,R_{t+1},S_{t+1})
=\lambda(S_{t},A_t,R_{t+1},S_{t+1};\boldsymbol{\psi}^{*})$. It follows from the definition of dropout propensity that $\mathbb{E}(\eta_{t+1}\vert \mathcal{F}_{t},R_{t+1},S_{t+1},\eta_t=1)
=1-\lambda(S_{t},A_t,R_{t+1},S_{t+1};\boldsymbol{\psi}^{*})$, therefore, $\mathbb{E}\left\{\omega_{t+1}(\boldsymbol{\psi}^{*})\vert \mathcal{F}_t,R_{t+1},S_{t+1}, \eta_t=1\right\}=1$.

Similar to the previous proof, $\widehat{\boldsymbol{\beta}}_{\text{IPW}}-\boldsymbol{\beta}^{*}$ can be decomposed as 
\begin{equation*}
    \begin{aligned}
    \widehat{\boldsymbol{\beta}}_{\text{IPW}}-\boldsymbol{\beta}^{*}
    =&\underbrace{\boldsymbol{\Sigma}^{-1}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}
    \omega_{i,t+1}(\widehat{\boldsymbol{\psi}})
    \boldsymbol{\xi}_{i, t} \varepsilon_{i, t}\right)}_{\zeta_{1}} \\
     +& \underbrace{\left(\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}-\boldsymbol{\Sigma}^{-1}\right)\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1}
    \omega_{i,t+1}(\widehat{\boldsymbol{\psi}})
    \boldsymbol{\xi}_{i, t} \varepsilon_{i, t}\right)}_{\zeta_{2}}\\
     +& \underbrace{\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
    \omega_{i,t+1}(\widehat{\boldsymbol{\psi}})
    \boldsymbol{\xi}_{i, t} r_{i, t}\right)}_{\zeta_{3}} .
    \end{aligned}
\end{equation*}
To prove its consistency, it suffices to show $\left\|\zeta_{1}\right\|_{2}$, $\left\|\zeta_{2}\right\|_{2}$, and $\left\|\zeta_{3}\right\|_{2}$ are $o_p(1)$. To bound these terms, we first introduce the following lemma. This lemma is similar to Lemma \ref{lemma:3}, but it is with respect to $\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}$ instead of $\widehat{\boldsymbol{\Sigma}}$. 
% This result can be proven using similar arguments in proving Lemma \ref{lemma:3}. 
The proof can be found in Appendix \ref{appendix:lemma3*_proof}.

\begin{lemma}\label{lemma:3_star}
Suppose Assumption \ref{ass:SAVE}-\ref{ass:dropout_propensity} holds. We have $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}-\boldsymbol{\Sigma}\|_{2}=O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\}$, $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}-\boldsymbol{\Sigma}^{-1}\|_{2}=O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\}$ and $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}\|_2 \leq 6 \bar{c}^{-1}$ with probability approaching 1, as either $n\rightarrow\infty$ or $T\rightarrow\infty$.
\end{lemma}

Next, we will use Lemma \ref{lemma:3_star} to derive the error bounds for $\left\|\zeta_{1}\right\|_{2}$, $\left\|\zeta_{2}\right\|_{2}$, and $\left\|\zeta_{3}\right\|_{2}$.

% \begin{itemize}
%     \item \textbf{Error bound for $\left\|\zeta_{3}\right\|_{2}$.}
% \end{itemize}
\paragraph{Error bound for $\left\|\zeta_{3}\right\|_{2}$.}

It follows from condition \ref{ass:dropout_propensity}(b) that $\max_{1\leq i\leq n, 0\leq t<T}\vert \omega_{i,t}(\boldsymbol{\psi})\vert\leq c_{\lambda}^{-1}$. 
Using similar arguments in (\ref{eq:bound_zeta3}), we have
$$\left\vert\boldsymbol{a}^{\top}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
    \omega_{i,t+1}(\widehat{\boldsymbol{\psi}})
    \boldsymbol{\xi}_{i, t} r_{i, t}\right)\right\vert \leq \frac{2CL^{-p / d}}{c_{\lambda}}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \boldsymbol{a}^{\top} \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top} \boldsymbol{a}\right)^{1 / 2}$$ 
for any $\boldsymbol{a}\in\mathbb{R}^{mL}$. Thus, 
\begin{equation*}
    \left\|\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \omega_{i,t+1}(\widehat{\boldsymbol{\psi}}) \boldsymbol{\xi}_{i, t} r_{i, t}\right\|_{2} 
    \leq \frac{2CL^{-p / d}}{c_{\lambda}} \lambda_{\max }^{1 / 2}\left(\frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top}\right)
    =O_p(L^{-p/d}).
\end{equation*}

By Lemma \ref{lemma:3_star}, we obtain 
\begin{equation}
    \label{eq:thm2_zeta3_bound}
    \zeta_{3}=O_{p}\left(L^{-p / d}\right).
\end{equation}

% \begin{itemize}
%     \item \textbf{Error bound for $\left\|\zeta_{1}\right\|_{2}$ and $\left\|\zeta_{2}\right\|_{2}$.}
