\begin{lemma}\label{lemma:4*}
% Suppose Assumption \ref{ass:SAVE}-\ref{ass:semiparametric-ipw} holds. Then there exist $C_{\Omega,1}$ and $C_{\Omega,2}$ such that $C_{\Omega,1} \leq \lambda_{\min}(\boldsymbol{\Omega}_{ \text{IPW}}) \leq \lambda_{\max}(\boldsymbol{\Omega}_{ \text{IPW}})\leq C_{\Omega,2}$.
Suppose Assumption \ref{ass:SAVE}-\ref{ass:dropout_propensity} holds. Then there exist $C_{\Omega,1}$ such that $\lambda_{\min}(\boldsymbol{\Omega}_{ \text{IPW}}) \geq C_{\Omega,1}$ with probability approaching 1. Besides, $\lambda_{\max}(\boldsymbol{\Omega}_{ \text{IPW}})=O_p(1)$.
\end{lemma}

Lemma \ref{lemma:4*} can be shown by noting that 
\begin{gather*}
    \lambda_{\text{min}}\left(\frac{1}{T}\sum_{t=0}^{T-1}\mathbb{E}\left\{ \omega_{i,t+1}^{*2} \varepsilon_{i, t}^2  \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top}\right\}\right)
=\lambda_{\text{min}}\left(\frac{1}{T}\sum_{t=0}^{T-1}\mathbb{E}\left\{ \frac{1}{1-\lambda_{i,t}^{*}} \varepsilon_{i, t}^2  \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top}\right\}\right)\\
\geq \lambda_{\text{min}}\left(\frac{1}{T}\sum_{t=0}^{T-1}\mathbb{E}\left\{ \varepsilon_{i, t}^2  \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top}\right\}\right)
\geq c_0^{-1} \lambda_{\text{min}}\left(\frac{1}{T}\sum_{t=0}^{T-1}\mathbb{E}\left\{ \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top}\right\}\right) 
\geq \frac{\overline{c}}{3 c_0}:=C_{\Omega,1},\\
\lambda_{\text{max}}(\boldsymbol{A})
\leq c_{\lambda}^{-1}(c_0 + 2c^{\prime})^2 \lambda_{\text{max}}\left(\frac{1}{T}\sum_{t=0}^{T-1}\mathbb{E}\left\{ \boldsymbol{\xi}_{i, t} \boldsymbol{\xi}_{i, t}^{\top}\right\}\right)
=O_p(1).
\end{gather*}

By Lemma \ref{lemma:4*}, 
the lower bound of $\sigma_{\pi,\text{IPW}}^{2}(\mathbb{G})$ satisfies 
\begin{equation}\label{eq:E.45}
    \sigma_{ \pi,\text{IPW}}^{2}(\mathbb{G}) \geq C_{\Omega,1}\left\{\int_{s} \boldsymbol{U}(s) \mathbb{G}(d s)\right\}^{\top} \boldsymbol{\Sigma}^{-1}\left(\boldsymbol{\Sigma}^{\top}\right)^{-1}\left\{\int_{s} \boldsymbol{U}(s) \mathbb{G}(d s)\right\}.
\end{equation}
According to Lemma \ref{lemma:3}, we have $\lambda_{\max }(\boldsymbol{\Sigma}^{\top} \boldsymbol{\Sigma})=O(1)$. This implies that $\lambda_{\min }\{\boldsymbol{\Sigma}^{-1}(\boldsymbol{\Sigma}^{\top})^{-1}\} \geq \bar{C}$ for some constant $\bar{C}>0$, hence
\begin{equation}\label{eq:E.46}
    \sigma_{\pi,\text{IPW}}^{2}(\mathbb{G}) \geq C_{\Omega,1} \bar{C}\left\|\int_{s} U(s) \mathbb{G}(d s)\right\|_{2}^{2}
\end{equation}
Combining Equation (\ref{eq:E.46}) together with Equation (\ref{eq:E.44}) yields that 
\begin{equation*}
\begin{gathered}
    \frac{1}{\sigma_{\pi,\text{IPW}}(\mathbb{G})}\left\vert\widehat{V}_{\text{IPW}}^{\pi}(\mathbb{G})-V^{\pi}(\mathbb{G})-\left\{\int_{s} \boldsymbol{U}(s) \mathbb{G}(d s)\right\}^{\top} \zeta_{1}\right\vert\\ 
    \leq \frac{1}{\sqrt{C_{\Omega,1} \bar{C}}}\left\|\widehat{\boldsymbol{\beta}}_{\text{IPW}}-\boldsymbol{\beta}^{*}-\zeta_{1}\right\|_{2} + \frac{ C L^{-p / d}}{\sqrt{C_{\Omega,1} \bar{C}}\left\|\int_{s} \boldsymbol{U}(s) \mathbb{G}(d s)\right\|_{2}} .
\end{gathered}
\end{equation*}
According to the previous proof, we have
\begin{equation*}
    \widehat{\boldsymbol{\beta}}_{\text{IPW}}-\boldsymbol{\beta}^*
    =\zeta_1 + O_p\left\{L(n T)^{-1} \log (n T)\right\} + O_p\left(L^{-p / d}\right)
