- \widehat{\boldsymbol{H}}_2 \widehat{\boldsymbol{m}}^{(g)}
    - {\omega}^{*(g)} {\varepsilon}^{(g)} \boldsymbol{\xi}^{(g)} 
    + {\boldsymbol{H}}_2 {\boldsymbol{m}}^{*(g)}\\
    &=\underbrace{\left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) \boldsymbol{\xi}^{(g)}}_{\boldsymbol{E}_1^{(g)}}
    - \underbrace{(\widehat{\boldsymbol{H}}_2 \widehat{\boldsymbol{m}}^{(g)} - {\boldsymbol{H}}_2 {\boldsymbol{m}}^{*(g)})}_{\boldsymbol{E}_2^{(g)}},
