By the triangle inequality, 
\begin{equation*}
    \begin{aligned}
        \left\|\frac{1}{nT}\sum_{g=1}^{nT} (\widehat{\zeta}^{(g)}-\zeta^{(g)}){\zeta}^{(g)\top}\right\|_2
    &\leq \left\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_3^{(g)\top}\right\|_2 
    + \left\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_4^{(g)\top}\right\|_2 \\
    &+ \left\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_2^{(g)}\boldsymbol{E}_3^{(g)\top}\right\|_2 
    + \left\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_2^{(g)}\boldsymbol{E}_4^{(g)\top}\right\|_2.
