Thus, it suffices to show $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_i^{(g)}\boldsymbol{E}_j^{(g)\top}\|_2=o_p(1)$ for all  $i\in\{1,2\}, j\in\{3,4\}$. 

We first show $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_3^{(g)\top}\|_2=o_p(1)$. 
% To show $\|\frac{1}{nT}\sum_{g=1}^{nT} (\widehat{\zeta}^{(g)}-\zeta^{(g)})\widehat{\zeta}^{(g)\top} \|_2=o_p(1)$ 
It is equivalent to showing 
\begin{equation*}
    \sup_{\boldsymbol{a}\in\mathbb{S}^{mL-1}}\left\vert \frac{1}{nT}\sum_{g=1}^{nT} \boldsymbol{a}^{\top}\boldsymbol{\xi}^{(g)}\boldsymbol{\xi}^{(g)\top} \boldsymbol{a} \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) {\omega}^{*(g)} {\varepsilon}^{(g)} \right\vert = o_p(1),
\end{equation*}
where $\mathbb{S}^{mL-1}$ denotes the unit sphere $\{\boldsymbol{a} \in \mathbb{R}^{m L}:\|\boldsymbol{a}\|_2=1\}$. According to Lemma \ref{lemma:4}, $\sup _{a \in \mathbb{S}^{m L-1}}\frac{1}{nT} \sum_{g=1}^{n T} \boldsymbol{a}^{\top} \boldsymbol{\xi}^{(g)}\boldsymbol{\xi}^{(g)\top}\boldsymbol{a}=O_p(1)$, hence we only need to show $\max_{1\leq g\leq nT}\vert (\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}) \widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} \vert=o_p(1)$. The bound in (\ref{eq:E.38}) indicates that ${\varepsilon}^{(g)}$'s are uniformly bounded, together with the bound for ${\omega}^{*(g)}$ 
% and $\widehat{\omega}^{(g)}$ 
given in condition \ref{ass:dropout_propensity}(b), we obtain $\max_{1\leq g \leq nT}\vert {\omega}^{*(g)} {\varepsilon}^{(g)} \vert=O_p(1)$. Therefore, it remains to show 
$$\max_{1\leq g\leq nT}\left\vert \widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)} \right\vert
=o_p(1).$$
Note that the term can be decomposed as 
$\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}
=(\widehat{\omega}^{(g)} - {\omega}^{*(g)}) \widehat{\varepsilon}^{(g)} + {\omega}^{*(g)} (\widehat{\varepsilon}^{(g)} - {\varepsilon}^{(g)})$. Using similar arguments in showing (E.50) in \citet{shi2021statistical}, we have $\max _{1 \leq g \leq n T}\vert\varepsilon^{(g)}-\widehat{\varepsilon}^{(g)}\vert=o_p(1)$. On the other hand, the consistency of dropout propensity model, $\widehat{\boldsymbol{\psi}}\stackrel{p}{\rightarrow}\boldsymbol{\psi}^{*}$, indicates that $\widehat{\omega}^{(g)}\stackrel{p}{\rightarrow}\omega^{*(g)}$ for any $g$, thus $\max _{1 \leq g \leq n T}\vert\omega^{(g)}-\widehat{\omega}^{(g)}\vert=o_p(1)$. Combine them together yields
\begin{align}\label{eq:bound_omega_epsilon}
\begin{split}
\max_{1\leq g\leq nT}\vert \widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)} \vert
&=\max_{1\leq g\leq nT}\vert (\widehat{\omega}^{(g)} - {\omega}^{*(g)}) \widehat{\varepsilon}^{(g)} + {\omega}^{*(g)} (\widehat{\varepsilon}^{(g)} - {\varepsilon}^{(g)}) \vert\\
&\leq \max_{1\leq g\leq nT}\vert \widehat{\omega}^{(g)} - {\omega}^{*(g)}\vert \vert \widehat{\varepsilon}^{(g)} \vert
+ \max_{1\leq g\leq nT}\vert {\omega}^{*(g)}\vert \vert \widehat{\varepsilon}^{(g)} - {\varepsilon}^{(g)} \vert
=o_p(1).
\end{split}
\end{align}
This completes the proof for $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_3^{(g)\top}\|_2=o_p(1).$ 

Next, we show $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_2^{(g)}\boldsymbol{E}_4^{(g)\top}\|_2=o_p(1)$. Using similar arguments in bounding $\|\widehat{\boldsymbol{\Sigma}}-\boldsymbol{\Sigma}\|_{2}$ in the proof of Lemma \ref{lemma:3}, we obtain $\|\widehat{\boldsymbol{H}}_2 - \boldsymbol{H}_2\|_2=o_p(1)$ as well as 
$\left\| \frac{1}{nT}\sum_{g=1}^{nT} \boldsymbol{m}^{*(g)} (\boldsymbol{m}^{*(g)})^{\top} - \mathbb{E}\left\{\boldsymbol{m}^{*} 
    (\boldsymbol{m}^{*})^{\top}\right\}\right\|_2=o_p(1)$.

% By the assumption 
It follows from $\widehat{\boldsymbol{\psi}}\stackrel{p}{\rightarrow}\boldsymbol{\psi}^{*}$ that
$\frac{1}{nT}\sum_{g=1}^{nT}\left\|\widehat{\boldsymbol{m}}^{(g)} - \boldsymbol{m}^{*(g)}\right\|_2^2\stackrel{p}{\rightarrow}0$.
% and the triangle inequality
Therefore, 
\begin{equation*}
\begin{aligned}
    &\left\| \frac{1}{nT}\sum_{g=1}^{nT} \widehat{\boldsymbol{m}}^{(g)} (\boldsymbol{m}^{*(g)} )^{\top} - \frac{1}{nT}\sum_{g=1}^{nT} (\boldsymbol{m}^{*(g)} )(\boldsymbol{m}^{*(g)} )^{\top}\right\|_2\\
    &\leq \frac{1}{nT}\sum_{g=1}^{nT}  \left\| \widehat{\boldsymbol{m}}^{(g)}  (\boldsymbol{m}^{*(g)} )^{\top} -  \boldsymbol{m}^{*(g)} (\boldsymbol{m}^{*(g)} )^{\top}\right\|_2
    \leq  \frac{1}{nT}\sum_{g=1}^{nT} \left\| \widehat{\boldsymbol{m}}^{(g)}   -  \boldsymbol{m}^{*(g)} \right\|_2 \left\| \boldsymbol{m}^{*(g)} \right\|_2\\
    &\leq \left( \frac{1}{nT}\sum_{g=1}^{nT} \left\| \widehat{\boldsymbol{m}}^{(g)}   -  \boldsymbol{m}^{*(g)} \right\|_2^2 \right) \left( \frac{1}{nT}\sum_{g=1}^{nT} \left\| \boldsymbol{m}^{*(g)}  \right\|_2^2 \right)
    \stackrel{p}{\rightarrow}0,
\end{aligned}
\end{equation*}
where the last step holds since the convergence of the diagonal elements of $\frac{1}{nT}\sum_{g=1}^{nT} \boldsymbol{m}^{*(g)} (\boldsymbol{m}^{*(g)})^{\top}$ 
implies that $\frac{1}{nT}\sum_{g=1}^{nT} \left\| \boldsymbol{m}^{*(g)}  \right\|_2^2$ is bounded in probability. Based on the aforementioned results, we can show
\begin{equation*}
\begin{aligned}
    \left\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_2^{(g)}\boldsymbol{E}_4^{(g)\top}\right\|_2 &=\left\| \frac{1}{nT}\sum_{g=1}^{nT} \left\{ \widehat{\boldsymbol{H}}_2 \widehat{\boldsymbol{m}}^{(g)}  (\boldsymbol{m}^{*(g)})^{\top}\boldsymbol{H}_2^{\top} - {\boldsymbol{H}}_2 {\boldsymbol{m}}^{*(g)} (\boldsymbol{m}^{*(g)})^{\top}\boldsymbol{H}_2^{\top}\right\} \right\|_2\\
    &\leq \left\| (\widehat{\boldsymbol{H}}_2 - \boldsymbol{H}_2) \left\{\frac{1}{nT}\sum_{g=1}^{nT}  \widehat{\boldsymbol{m}}^{(g)}  (\boldsymbol{m}^{*(g)} )^{\top}\right\}\boldsymbol{H}_2^{\top}  \right\|_2\\
    &+ \left\| {\boldsymbol{H}}_2 \left\{\frac{1}{nT}\sum_{g=1}^{nT} \widehat{\boldsymbol{m}}^{(g)}  (\boldsymbol{m}^{*(g)} )^{\top} -\boldsymbol{m}^{*(g)} (\boldsymbol{m}^{*(g)} )^{\top} \right\} \boldsymbol{H}_2^{\top} \right\|_2=o_p(1).
\end{aligned}
\end{equation*}

It remains to show $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_4^{(g)\top}\|_2=o_p(1)$ and $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_2^{(g)}\boldsymbol{E}_3^{(g)\top}\|_2=o_p(1)$. They can be shown in similar ways, here we only prove $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_4^{(g)\top}\|_2=o_p(1)$ for brevity. 
Notice that 
\begin{equation*}
\begin{aligned}
    \left\| \frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_4^{(g)\top} \right\|_2
    &=\left\| \left\{ \frac{1}{nT}\sum_{g=1}^{nT} \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) \boldsymbol{\xi}^{(g)} ({\boldsymbol{m}}^{*(g)})^{\top}\right\} {\boldsymbol{H}}_2^{\top} \right\|_2\\
    &\leq \left\| \frac{1}{nT}\sum_{g=1}^{nT} \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) \boldsymbol{\xi}^{(g)} ({\boldsymbol{m}}^{*(g)})^{\top} \right\|_2  \left\|{\boldsymbol{H}}_2 \right\|_2 \\
    &\leq \frac{1}{nT}\sum_{g=1}^{nT} \left\| \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) \boldsymbol{\xi}^{(g)} 
    \right\|_2 \left\| {\boldsymbol{m}}^{*(g)}\right\|_2 \left\|{\boldsymbol{H}}_2 \right\|_2\\
    &\leq \left( \frac{1}{nT}\sum_{g=1}^{nT} \left\| \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) \boldsymbol{\xi}^{(g)} 
    \right\|_2^2 \right) \left( \frac{1}{nT}\sum_{g=1}^{nT}  \left\| {\boldsymbol{m}}^{*(g)}\right\|_2^2\right) \left\|{\boldsymbol{H}}_2 \right\|_2.
\end{aligned}
\end{equation*}
Since $\frac{1}{nT}\sum_{g=1}^{nT}  \left\| {\boldsymbol{m}}^{*(g)}\right\|_2^2$ and $\left\|{\boldsymbol{H}}_2 \right\|_2$ are bounded in probability, it suffices to show $\frac{1}{nT}\sum_{g=1}^{nT} \left\| \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) \boldsymbol{\xi}^{(g)} 
\right\|_2^2=o_p(1)$. We have already prove $\max_{1\leq g\leq nT}\vert \widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)} \vert=o_p(1)$ in (\ref{eq:bound_omega_epsilon}), hence $\max_{1\leq g\leq nT}( \widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)})^2=o_p(1)$. Meanwhile, by Lemma \ref{lemma:4}, we have $\sup _{a \in \mathbb{S}^{m L-1}}\frac{1}{nT} \sum_{g=1}^{n T} \boldsymbol{a}^{\top} \boldsymbol{\xi}^{(g)}\boldsymbol{\xi}^{(g)\top}\boldsymbol{a}=O_p(1)$. Thus,
\begin{equation*}
    \sup_{\boldsymbol{a}\in\mathbb{S}^{mL-1}}\left\vert \frac{1}{nT}\sum_{g=1}^{nT} \boldsymbol{a}^{\top}\boldsymbol{\xi}^{(g)}\boldsymbol{\xi}^{(g)\top} \boldsymbol{a} \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right)^2 \right\vert = o_p(1),
\end{equation*}
equivalently, $\frac{1}{nT}\sum_{g=1}^{nT} \left\| \left(\widehat{\omega}^{(g)} \widehat{\varepsilon}^{(g)} - {\omega}^{*(g)} {\varepsilon}^{(g)}\right) \boldsymbol{\xi}^{(g)} 
\right\|_2^2=o_p(1)$. This completes the proof for $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_1^{(g)}\boldsymbol{E}_4^{(g)\top}\|_2=o_p(1).$ 
We can also show $\|\frac{1}{nT}\sum_{g=1}^{nT}\boldsymbol{E}_2^{(g)}\boldsymbol{E}_3^{(g)\top}\|_2=o_p(1)$ using similar steps. 

Combine these results together yields  
% $\|\frac{1}{nT}\sum_{g=1}^{nT} (\widehat{\zeta}^{(g)}-\zeta^{(g)})\widehat{\zeta}^{(g)\top} \|_2=o_p(1)$
$\|\frac{1}{nT}\sum_{g=1}^{nT} {\zeta}^{(g)} (\widehat{\zeta}^{(g)}-\zeta^{(g)})^{\top}\|_2=o_p(1)$
. Similarly we can show 
% $\| \frac{1}{nT}\sum_{g=1}^{nT} \zeta^{(g)}(\widehat{\zeta}^{(g)}-\zeta^{(g)})^{\top} \|_2=o_p(1)$
$\|\frac{1}{nT}\sum_{g=1}^{nT} (\widehat{\zeta}^{(g)}-\zeta^{(g)})\widehat{\zeta}^{(g)\top} \|_2=o_p(1)$
. Therefore, $\|\widehat{\boldsymbol{\Omega}}_{\text{IPW}}-
% \frac{1}{nT}\sum_{g=1}^{n T} \omega^{*(g)2}\varepsilon^{(g)2} \boldsymbol{\xi}^{(g)}\boldsymbol{\xi}^{(g)\top}
\frac{1}{nT}\sum_{g=1}^{n T} \zeta^{(g)}\zeta^{(g)\top}
\|_{2}=o_{p}(1)$, and hence (\ref{eq:step4_obj}) is proven.

\end{proof}

