        &+ \frac{1}{1-\gamma} \frac{1}{nT}\sum_{i=1}^{n} \sum_{t=0}^{T-1} \eta_{i,t+1} \widehat{\omega}_{\pi,i,t} \varepsilon_{i,t+1}  \cdots\cdots\text{(II)}
