\subsection{Proof of Lemma \ref{lemma:3_star}}\label{appendix:lemma3*_proof}

\textbf{Lemma}
Suppose Assumption \ref{ass:SAVE}-\ref{ass:dropout_propensity} holds. We have $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}-\boldsymbol{\Sigma}\|_{2}=O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\}$, $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}-\boldsymbol{\Sigma}^{-1}\|_{2}=O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\}$ and $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}\|_2 \leq 6 \bar{c}^{-1}$ with probability approaching 1, as either $n\rightarrow\infty$ or $T\rightarrow\infty$.

\begin{proof}
Recall that 
\begin{gather*}
\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}
=\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \widehat{\omega}_{i,t+1} \boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top}\\
\boldsymbol{\Sigma}
=\mathbb{E}\left\{\omega^{*}_{i,t+1} \boldsymbol{\xi}_{i, t}(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}) \right\}
=\mathbb{E}\left\{\boldsymbol{\xi}_{i, t}(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}) \right\}.
\end{gather*}
It follows that 
\begin{gather*}
\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}-\boldsymbol{\Sigma}
=\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} \widehat{\omega}_{i,t+1} \boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top} - \boldsymbol{\Sigma}\\
=\left(\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} (\widehat{\omega}_{i,t+1}-\omega^{*}_{i,t+1}) \boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top} \right) \\
+ \left(\frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} {\omega}_{i,t+1}^{*} \boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top} - \boldsymbol{\Sigma}\right)
\end{gather*}
Using similar arguments in proving Lemma \ref{lemma:3}, we obtain 
\begin{gather*}
    \left\| \frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} {\omega}_{i,t+1}^{*} \boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top} - \boldsymbol{\Sigma} \right\|_2
    =O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\}.
\end{gather*}
On the other hand, using a similar technique as in (\ref{eq:value_expansion}), we have 
\begin{equation*}
\begin{gathered}
    \frac{1}{\sqrt{n T}} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
    \left(\widehat{\omega}_{i,t+1} - \omega_{i,t+1}^{*}\right) \boldsymbol{\xi}_{i, t} \left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top}
    =\sqrt{nT}\boldsymbol{H}_3(\widehat{\boldsymbol{\psi}}-\boldsymbol{\psi}^{*})
    + o_p(1),
\end{gathered}
\end{equation*}
for some tensor $\boldsymbol{H}_3$. By convergence of $\widehat{\boldsymbol{\psi}}$ given in (\ref{eq:asymptotic_psi}), we have
\begin{equation*}
    \left\| \frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
    \left(\widehat{\omega}_{i,t+1} - \omega_{i,t+1}^{*}\right) \boldsymbol{\xi}_{i, t} \left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top} \right\|_2 
    = O_p\{(nT)^{-1/2}\}.
\end{equation*}
Therefore, 
\begin{gather*}
    \left\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}-\boldsymbol{\Sigma} \right\|_2
    \leq \left\| \frac{1}{nT} \sum_{i=1}^{n} \sum_{t=0}^{T-1} {\omega}_{i,t+1}^{*} \boldsymbol{\xi}_{i, t}\left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top} - \boldsymbol{\Sigma} \right\|_2\\
    + \left\| \frac{1}{n T} \sum_{i=1}^{n} \sum_{t=0}^{T-1} 
    \left(\widehat{\omega}_{i,t+1} - \omega_{i,t+1}^{*}\right) \boldsymbol{\xi}_{i, t} \left(\boldsymbol{\xi}_{i, t}-\gamma\boldsymbol{U}_{\pi, i, t+1}\right)^{\top} \right\|_2 \\
    = O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\} + O_p\{(nT)^{-1/2}\} \\
    = O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\}.
\end{gather*}
% Under the condition that $L=o\{nT/\log(nT)\}$, we have $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}-\boldsymbol{\Sigma} \|_2=o_p(1)$.
Based on this result, we can follow similar steps in the proof for Lemma \ref{lemma:3} to show $\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}\|_2 \leq 6 \bar{c}^{-1}$ and 
$\|\widehat{\boldsymbol{\Sigma}}_{\text{IPW}}^{-1}-\boldsymbol{\Sigma}^{-1}\|_{2}=O_{p}\left\{L^{1 / 2}(n T)^{-1 / 2} \log (n T)\right\}$. The proof is hence completed.

\end{proof}
