\section{Inequalities for the \texorpdfstring{$L_-$}{L-} distances}\label{s:L-}

In this section we give the proof of Theorem \ref{thm:L-charact}, again divided into multiple subsections. We also state an analogous theorem tailored to the $L_+$ distance. Throughout the section, we work with an arbitrary but fixed smooth family of closed Riemannian manifolds parametrized by backwards time $(M^n, g_\tau)_{\tau \in I}$ of dimension $\dim M = n$, defined for some interval $I \subseteq (0,\infty)$, with the notation of Subsection \ref{subsec:t-dep-mflds} still in force.

\subsection{The \texorpdfstring{$\cD$}{D}-condition in dimension \texorpdfstring{$n$}{n} and the \texorpdfstring{$L_-$}{L-} Bochner formula}\label{ss:L-DBoch}

\begin{prop}\label{prop:L-Bochner}
For any $\tau\in I$, any smooth solution $v$ of the heat flow at $\tau$, the following identity holds:
\begin{equation}
-(\ptau + \Delta)\left(|\nabla v|^2 - 2\tau\Delta v - \tau^2 S + \frac{n}{2}\tau\right) = -2\left|\tau\mathcal{S} - \frac{g}{2} + \Hess v\right|^2 -\tau^2\mathcal{D}(\nabla v/\tau)\,.
\end{equation}
In particular, $\cD \geq 0$ iff 

\begin{equation}\label{eq:BochnerL--id-to-ineq}
-(\ptau + \Delta)\left(|\nabla v|^2 - 2\tau\Delta v - \tau^2 S + \frac{n}{2}\tau\right) \leq 0\,, \tag{B\({}_{L_-}\)}
\end{equation}
for any $\tau \in I$, any smooth solution $v$ of the heat flow at $\tau$.
\end{prop}


\begin{proof}
Let us recall the following identities:
\begin{align}
&-(\ptau + \Delta)|\nabla v|^2 = -2|\Hess v|^2+(2\mathcal{S}-2\Ric)(\nabla v,\nabla v), \\ & -(\ptau + \Delta)\Delta v = 2\La \mathcal{S}, \Hess v\Ra + \La 2\div \mathcal{S}-\nabla S,\nabla v \Ra, \\
& -(\ptau + \Delta)S = 2|\mathcal{S}|^2 -(\ptau S+\Delta S+2|\mathcal{S}|^2) 
\end{align}
Note that we have omitted the (zero) terms that involve the heat operator applied to $v$. One may now compute
\begin{align}
-(\ptau + \Delta)\left(|\nabla v|^2 - 2\tau\Delta v - \tau^2 S +\frac{n}{2}\tau \right) &= -2|\Hess v|^2 + 2\Delta v - 4\tau \langle\mathcal{S},\Hess v\rangle + 2\tau S - 2\tau^2 |\mathcal{S}|^2  -\frac{n}{2} \\
& \qquad  + (2\mathcal{S}-2\Ric)(\nabla v,\nabla v) -2\tau \La 2\div \mathcal{S}-\nabla S,\nabla v \Ra \\
&\qquad +\tau^2(\ptau S+\Delta S+2|\mathcal{S}|^2)  \\
&= -2\left( |\Hess v|^2 +\tau^2 |\mathcal{S}|^2 + \frac{n}{4} +2\tau \langle\mathcal{S},\Hess v\rangle - \Delta v -\tau S \right) \\ 
& \qquad -\tau^2 \mathcal{D}(\nabla v/\tau) \\
&= -2\left|\tau\mathcal{S} - \frac{g}{2} +  \Hess v \right|^2 -\tau^2 \mathcal{D}(\nabla v/\tau)\,.
\end{align}

Given this formula, it is clear that $\mathcal{D}\geq 0$ implies \eqref{eq:BochnerL--id-to-ineq}. Vice versa, assume that every smooth solution $v$ to the heat flow at $\tau \in I$ satisfies \eqref{eq:BochnerL--id-to-ineq}. Then one can argue as in the proof of Proposition \ref{prop:DcondiffBochner}, picking initial data $v_{\tau}$ for a heat flow such that $\tau \cS_p - \frac{1}{2}g_p + (\Hess v)_p = 0$ and $(\nabla v)_p/\tau = V$ for arbitrary $V \in T_pM$ to conclude that $\cD_{\tau,p} \geq0$.
\end{proof}

\begin{rmk}
    If we assume, for some $N>0$, that
    \begin{equation}
-(\ptau + \Delta)\left(|\nabla v|^2 - 2\tau\Delta v - \tau^2 S + \frac{N}{2}\tau\right) \leq 0 \,,
\end{equation}
we get
    \begin{align}
        2\left|\tau\mathcal{S} - \frac{g}{2} +  \Hess v \right|^2 +\tau^2 \cD(\nabla v/\tau) + \frac{N-n}{2} \geq0\,,
    \end{align}
    which only yields (choosing $v$ as above)
    \begin{align}
        \tau^2 \cD(X/\tau) + \frac{N-n}{2} \geq0 \qquad \text{for all $(p,X,\tau)\in TM \times I$.}
    \end{align}
    In order to decouple the $\cD$ condition (in particular, its zero-order in $v$ part) and the dimension bound one may consider time-translations, see Section \ref{s:dimL0}.
\end{rmk}

\subsection{\texorpdfstring{$L_-$}{L-} Bochner formula and gradient estimates}\label{ss:L-BochGE}

\begin{prop}\label{prop:L-GradEst}
The Bochner inequality for any $\tau \in I$, any smooth solution $v$ to the heat equation at $\tau$ \noeqref{eq:BochnerL--Bochner-to-GE}
\begin{equation}\label{eq:BochnerL--Bochner-to-GE}\tag{B\({}_{L_-}\)}
-(\partial_\tau + \Delta)\left(|\nabla v|^2_\tau - 2\tau\Delta v - \tau^2 S_\tau + \frac{n}{2}\tau\right) \leq 0\,,
\end{equation}
is equivalent to the gradient estimate
\begin{align}\label{eq:GEL--Bochner-to-GE}
    |\nabla P_{\sigma,\tau}v|^2-2\sigma \Delta P_{\sigma,\tau}v-\sigma^2S_{\sigma} \leq P_{\sigma,\tau}\left(|\nabla v|^2-2\tau\Delta v - \tau^2S_{\tau}\right) + \frac{n}{2}(\tau-\sigma) \tag{GE\({}_{L_-}\)}
\end{align}
for all $[\sigma,\tau]\in I$ and all Lipschitz $v: M \to \R{}$, in which case we define $P_{\sigma,\tau} \Delta_{\tau} v (x) := -\int_M \La \nabla_{y} \rho_{\sigma,\tau}(x,y), \nabla v(y)\Ra_{\tau} \,dV_{\tau}(y)$, where $\rho$ is the heat kernel.
\end{prop}

\begin{rmk}\label{GEL-and-max-princ}
    The estimate with $v=0$, along with the maximum principle yields 
    \begin{align}
        S_{\sigma} \geq \frac{1}{\sigma^2}\left(\tau^2\underline{S}_\tau -\frac{n}{2}(\tau-\sigma)\right) \geq \frac{1}{\sigma^2}\left(\tau^2\underline{S}_\tau -\frac{n}{2}\tau\right)
    \end{align}
    where $\underline{S}_\tau=\inf_MS_\tau$. Therefore, if $\tau^2\underline{S}_\tau -\frac{n}{2}\tau >0$, then $S$ must blow up at time $\sigma=0$. In particular, if  $\underline{S}_\tau>0$, then the flow cannot exist before $\tau-\frac{n}{2\underline{S}_\tau}$, recovering a classical statement for the Ricci flow, see e.g. \cite[Cor.~3.2.4]{topping2006lectures}.
\end{rmk}

The proof of Proposition \ref{prop:L-GradEst} is almost identical to that of Proposition \ref{prop:L0gradestimate} (taking care of the sign changes when passing to reversed time). We therefore omit it. It is also convenient to record the following ``gradient estimate with parameter'', by exploiting the commutator of time-translation and parabolic rescaling. It will be used only later, in Subsection \ref{ss:GEWCdualitydimL0}.

\begin{cor}\label{cor:L_GradEst_param}
Suppose that the Gradient estimate \eqref{eq:GEL--Bochner-to-GE} holds for any shift $(M,g_{\tau - T})_{\tau \in (I + T)\cap (0,\infty)}$ of the flow $(M,g_\tau)_{\tau \in I}$. For a Lipschitz function $w: M \to \R{}$, times $[\sigma, \tau] \in I$, and a parameter $0 < \lambda < \tau/\sigma$, the following gradient estimate holds
\begin{align}
&(|\nabla P_{\sigma,\tau}[w]|^2 - 2\lambda\sigma \Delta P_{\sigma,\tau}[w] - (\lambda\sigma)^2S_{\sigma}) \\
&- (P_{\sigma,\tau}[|\nabla w|^2] - 2\tau P_{\sigma,\tau}[\Delta w] - \tau^2P_{\sigma,\tau}[S_{\tau}
]) \leq \frac{n}{2}\frac{(\tau - \lambda \sigma)^2}{\tau - \sigma}
\end{align}
\end{cor}

\begin{proof}
We begin by writing the quantity from the LHS of \eqref{eq:GEL--Bochner-to-GE} as follows, for some constant $c > 0$ to be determined later:

\begin{align}
&\phantom{=}P_{\sigma,\tau}[|\nabla w|^2] - 2\tau P_{\sigma,\tau}[\Delta w] - \tau^2P_{\sigma,\tau}[S_{\tau}
] \\
&= \frac{1}{c^2}\left[P_{\sigma,\tau}[|\nabla (cw)|^2] - 2c\tau P_{\sigma,\tau}[\Delta (cw)] - (c \tau)^2P_{\sigma,\tau}[S_{\tau}
]\right] \\
&= \frac{1}{c^2}\left[P_{\sigma,\tau}[|\nabla (cw)|^2] - 2\Big(\tau + \tau(c - 1)\Big)P_{\sigma,\tau}[\Delta (cw)] - \Big(\tau + \tau(c - 1)\Big)^2P_{\sigma,\tau}[S_{\tau}
]\right]\,.
\end{align}

We now apply the gradient estimate \eqref{eq:GEL--Bochner-to-GE} but for the shifted flow $(M,g_{\tau - T})_{\tau \in I + T}$ with $T := \tau(c - 1)$, to the bracketed expression on the RHS to obtain

\begin{align}
&\phantom{\geq}P_{\sigma,\tau}[|\nabla w|^2] - 2\tau P_{\sigma,\tau}[\Delta w] - \tau^2 P_{\sigma,\tau}[S_{\tau}
] \\
&\geq \frac{1}{c^2}\left[|\nabla P_{\sigma,\tau}[cw]|^2 - 2\Big(\sigma + \tau(c - 1)\Big)\Delta P_{\sigma,\tau}[cw] - \Big(\sigma + \tau(c - 1)\Big)^2 S_{\sigma}
 -\frac{n}{2}(\tau - \sigma)\right]
\end{align}

It is at this point that we choose $c > 0$, which we do so that $\big(\sigma + \tau(c - 1)\big)/c = \lambda\sigma$--note that this is only possible if $0 < \lambda < \tau/\sigma$ and ensures that $\sigma +T = c\lambda\sigma > 0$. In particular, the above inequality simplifies to

\begin{align}
&\phantom{\geq}P_{\sigma,\tau}[|\nabla w|^2] - 2\tau P_{\sigma,\tau}[\Delta w] - \tau^2P_{\sigma,\tau}[S_{\tau}
] \\
&\geq \left[|\nabla P_{\sigma,\tau}[w]|^2 - 2\lambda\sigma \Delta P_{\sigma,\tau}[w] - (\lambda\sigma)^2S_{\sigma}
\right] - \frac{n}{2}\left(\frac{\tau - \lambda\sigma}{\tau - \sigma}\right)^2(\tau - \sigma)\,.
\end{align}

\end{proof}

\subsection{Duality of \texorpdfstring{$L_-$}{L-} gradient estimates and \texorpdfstring{$L_-$}{L-}-Wasserstein contraction}\label{ss:GEWCdualityL-}

Before proving the equivalence, we fix some notation and perform a couple computations. Let us start by recording the gradient estimate \eqref{eq:GEL--Bochner-to-GE} written in terms of times $(\tau,\alpha\tau)$:
    \begin{align}\label{eq:alphaGE}
        |\nabla P_{\tau,\alpha\tau}v|^2-2\tau\Delta P_{\tau,\alpha\tau}v-\tau^2 S_{\tau} \leq P_{\tau,\alpha\tau}\left(|\nabla v|^2-2\alpha\tau\Delta v - \alpha^2\tau^2S_{\alpha\tau}\right) + \frac{n}{2}(\alpha\tau-\tau)\,.
    \end{align}
In this subsection we will work with the Lagrangians $L_-$, $\tilde L_-$ defined in \ref{df:L-}. We compute the Hamiltonian associated to $\tilde L_-$ given by the Legendre transform
\begin{align}
    \tilde{H}^{\sigma,\tau}(v,p,\eta) &= \left( (\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}\left(\frac{1}{2}|v|^2+\frac{1}{2}S(p,\eta)\right) \right)^* \\
    &= \left( (\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}\frac{1}{2}|v|^2 \right)^* - \left( (\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}\frac{1}{2}S(p,\eta) \right) \\
    &= \frac{1}{(\sqrt{\tau} -\sqrt{\sigma})\sqrt{\eta}}\frac{1}{2}|v|^2 - (\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}\frac{1}{2}S(p,\eta).
\end{align}

Applying now Proposition \ref{prop:HLsemigroup}, for any Lipschitz $\phi: M \to \R{}$ we have that the Hopf-Lax semigroup $Q$ associated to $\tilde L$ satisfies
\begin{align}\label{HLforRescaledL-}
    \partial_\eta Q^{\alpha\sigma,\alpha \eta}\phi 
    &= -\alpha \tilde{H}^{\alpha\sigma,\alpha \eta}(d Q^{\alpha\sigma,\alpha \eta}\phi,\phi,\alpha \eta) \\
    &= -\alpha \left(\frac{1}{(\sqrt{\alpha\tau} -\sqrt{\alpha\sigma})\sqrt{\alpha \eta}}\frac{1}{2}|\nabla Q^{\alpha\sigma,\alpha \eta} \phi|^2 - (\sqrt{\alpha\tau}-\sqrt{\alpha\sigma})\sqrt{\alpha \eta}\frac{1}{2}S_{\alpha \eta} \right) \\
    &= -\frac{1}{(\sqrt{\tau} -\sqrt{\sigma})\sqrt{\eta}}\frac{1}{2}|\nabla Q^{\alpha\sigma,\alpha \eta}\phi|^2 + \alpha^2(\sqrt{\tau} -\sqrt{\sigma}) \sqrt{\eta}\frac{1}{2}S_{\alpha \eta}\,.
\end{align}

We now proceed to the first direction of the equivalence. We give a slightly different proof from the $L_0$ case (and following \cite{kuwadaduality} more closely). In this case we do not pass through the Hamilton-Jacobi preservation (as done in the $L_0$ case, Lemma \ref{lem:heat-flow-preserves-HJ}), which we nevertheless state later for completeness (Proposition \ref{prop:heat-flow-preserves-L_-HJ}). This is purely a presentation choice, and one could exchange the approaches.

\begin{prop}\label{prop:WL-contraction}
Suppose that for a Lipschitz $v: M \to \R{}$ and times $[\sigma,\tau]\subseteq I$, the following gradient estimate holds
\begin{align} \label{eq:GEL--GE-to-WC}
    |\nabla P_{\sigma,\tau}v|_\sigma^2-2\sigma \Delta_\sigma P_{\sigma,\tau}v-\sigma^2S_{\sigma} \leq P_{\sigma,\tau}\left(|\nabla v|_\tau ^2 - 2\tau\Delta_\tau v - \tau ^2S_{\tau}\right) + \frac{n}{2}(\tau-\sigma) \tag{GE\({}_{L_-}\)}\,.
\end{align}
Then for any times $[\sigma,\tau] \in I$ and factor $1 < \alpha < \sup I/\tau$, the following $W_{L_-}$ contraction along the adjoint heat flow for any $\mu,\nu \in \cP(M)$ holds
    \begin{align} \label{eq:WCL--GE-to-WC}
            W_{\tilde L_-^{\alpha\sigma,\alpha\tau}}(\hat P_{\sigma,\alpha\sigma}\mu, \hat P_{\tau,\alpha\tau}\nu) \leq W_{\tilde L_-^{\sigma,\tau}}(\mu,\nu) + (\sqrt{\tau}-\sqrt{\sigma})^2\frac{n}{2}(\alpha-1)\,.\tag{WC\({}_{L_-}\)}  
    \end{align}
\end{prop}

\begin{rmk}\label{rmk:Kuwada-contraction}
This $W_{\tilde L_-}$ contraction recovers the classical Wasserstein contraction at different times on manifolds with nonnegative Ricci curvature, see \cite{kuwadaspace},  which also holds on $\mathsf{RCD}(0,N)$ spaces, \cite{eks}. Indeed, when we are on a static space $(M,g)$, $\tilde L_-((x,\sigma),(y,\tau))=\frac{1}{4}d^2(x,y)$. Moreover the semigroup is time independent: $\hat P_{\sigma,\tau}=\hat P_{\tau-\sigma}$. Denoting by $W_2$ the Wasserstein distance induced by $d_g^2$, and setting $s=\sigma(\alpha-1)$, $t=\tau(\alpha-1)$, \eqref{eq:WCL--GE-to-WC} becomes
    \begin{align}
    W_2( \hat{P}_s\mu, \hat{P}_t\nu) \leq W_2(\mu,\nu) + 2n(\sqrt{t}-\sqrt{s})^2,
\end{align}
which is \cite[Eq.~(1.4)]{kuwadaspace} with $K=0$, see also Remark 2.10 therein. It is interesting to note that the same contraction is derived in duality with two different gradient estimates: in Kuwada it was
\begin{align}\label{eq:staticNGE}
    |\nabla P_t v|^2 \leq P_t|\nabla v|^2 - \frac{2t}{n}(\Delta P_t v)^2\,,
\end{align}
while in our case
\begin{align}
    |\nabla P_{r-s}v|^2-2s \Delta P_{r-s}v \leq P_{r-s}\left(|\nabla v|^2-2r\Delta v \right) + \frac{n}{2}(r-s)\,,
\end{align}
i.e, by commuting the semigroup and the generator, and setting $t=r-s$,
\begin{align}\label{eq:staticNGE2}
    |\nabla P_tv|^2 \leq P_t|\nabla v|^2-2t\Delta P_tv + \frac{nt}{2}\,.
\end{align}
Estimate \eqref{eq:staticNGE} is strictly better than \eqref{eq:staticNGE2} since $\frac{2t}{n}(\Delta P_tv)^2\geq 2t\Delta P_tv -\frac{nt}{2}$ by $\frac{t}{2n}(2\Delta P_t v- n)^2\geq0$. However, one might notice that \eqref{eq:staticNGE2} is not homogeneous in $v$, and up to rescaling one can make (pointwise) $2\Delta P_t v- n=0$ and recover \eqref{eq:staticNGE}. See also Subsection \ref{ss:dimBochnerandL_} for related considerations.
\end{rmk}

\begin{proof}[Proof of Proposition \ref{prop:WL-contraction}]
It is enough to prove the statement for delta measures (see \cite[Lem.~3.3]{kuwadaduality}). Let $\gamma:[\sigma,\tau]\to M$ be a $L_-^{\sigma,\tau}$-geodesic from $x$ to $y$. Then recalling the duality from Remark \ref{rmk:Kantorovich-via-HL}
\begin{align}
    W_{\tilde L_-^{\alpha\sigma,\alpha\tau}}(\hat P_{\sigma,\alpha\sigma}\delta_x, \hat P_{\tau,\alpha\tau}\delta_y) &= \sup_\phi \int Q^{\alpha\sigma,\alpha\tau}\phi d\hat P_{\tau,\alpha\tau} \delta_{\gamma_\tau}- \int \phi d \hat P_{\sigma,\alpha\sigma} \delta_{\gamma_\sigma} \\
    &= \sup_\phi P_{\tau,\alpha\tau}Q^{\alpha\sigma,\alpha\tau}\phi(\gamma_\tau)-P_{\sigma,\alpha\sigma}\phi(\gamma_\sigma) \\
    &=\sup_\phi \int_\sigma ^\tau\partial_\eta P_{\eta,\alpha \eta}Q^{\alpha \sigma,\alpha \eta}\phi(\gamma_\eta) d\eta \\
    &= \sup_\phi \int_\sigma ^\tau -\Delta P_{\eta,\alpha \eta}Q^{\alpha \sigma,\alpha \eta} \phi(\gamma_\eta) + \alpha P_{\eta,\alpha \eta}\Delta Q^{\alpha\sigma,\alpha \eta}\phi(\gamma_\eta) \\
    & \hspace{1cm}+ P_{\eta,\alpha \eta}(\partial_\eta Q^{\alpha\sigma,\alpha \eta}\phi)(\gamma_\eta) + \left\langle \nabla P_{\eta,\alpha \eta}Q^{\alpha\sigma,\alpha \eta}\phi(\gamma_\eta),\dot\gamma_\eta
    \right\rangle_\eta d\eta \\
    %a%
    &\leq \sup_\phi \int_\sigma ^\tau -\Delta P_{\eta,\alpha \eta}Q^{\alpha \sigma,\alpha \eta} \phi(\gamma_\eta) + \alpha P_{\eta,\alpha \eta}\Delta Q^{\alpha\sigma,\alpha \eta}\phi(\gamma_\eta) \\
    & \hspace{1cm}+ P_{\eta,\alpha \eta}\left(-\frac{1}{(\sqrt{\tau} -\sqrt{\sigma})\sqrt{\eta}}\frac{1}{2}|\nabla Q^{\alpha \sigma,\alpha \eta}\phi(\gamma_\eta)|^2 + \alpha^2(\sqrt{\tau} -\sqrt{\sigma}) \sqrt{\eta}\frac{1}{2}S_{\alpha \eta}\right) \\
    & \hspace{1cm} + \frac{1}{2(\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}}|\nabla P_{\eta,\alpha \eta}Q^{\alpha\sigma,\alpha \eta}\phi(\gamma_\eta)|_\eta^2 + \frac{1}{2}(\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}|\dot\gamma_\eta|_\eta^2 d\eta
    \end{align}
    using in the last line \eqref{HLforRescaledL-} and Young's inequality. Exploiting the different homogeneity in $\phi$ of the terms, we set up the gradient estimate \eqref{eq:alphaGE} that will be applied to $\frac{\sqrt{\eta}Q^{\alpha \sigma,\alpha \eta} \phi(\gamma_\eta)}{\sqrt{\tau}-\sqrt{\sigma}}$:

    \begin{align}
    &...=\sup_\phi \int_\sigma ^\tau \frac{\sqrt{\tau}-\sqrt{\sigma}}{\eta^{3/2}}\Bigg[-\eta\Delta P_{\eta,\alpha \eta}\left(\frac{\sqrt{\eta}Q^{\alpha \sigma,\alpha \eta} \phi(\gamma_\eta)}{\sqrt{\tau}-\sqrt{\sigma}}\right) + \alpha \eta P_{\eta,\alpha \eta}\Delta \left(\frac{\sqrt{\eta}Q^{\alpha\sigma,\alpha \eta}\phi(\gamma_\eta)}{\sqrt{\tau}-\sqrt{\sigma}}\right) \\
    & \hspace{1cm}+ P_{\eta,\alpha \eta}\left(-\frac{1}{2}\left|\frac{\nabla \sqrt{\eta}Q^{\alpha \sigma,\alpha \eta}\phi(\gamma_\eta)}{\sqrt{\tau} -\sqrt{\sigma}}\right|^2 + \alpha^2 \eta^2\frac{1}{2}S_{\alpha \eta}\right) \\
    & \hspace{1cm} + \frac{1}{2}\left|\frac{\nabla P_{\eta,\alpha \eta}\sqrt{\eta}Q^{\alpha\sigma,\alpha \eta}\phi(\gamma_\eta)}{\sqrt{\tau}-\sqrt{\sigma}}\right|^2 \Bigg] + \frac{1}{2}(\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}|\dot\gamma_\eta|^2 d\eta \\
    & \overset{\eqref{eq:alphaGE}}{\leq} \sup_\phi \int_\sigma ^\tau  \frac{\sqrt{\tau}-\sqrt{\sigma}}{\eta^{3/2}} \Bigg[ \frac{\eta^2}{2}S_\eta + \frac{n}{4}(\alpha \eta-\eta) \Bigg] + \frac{1}{2}(\sqrt{\tau}-\sqrt{\sigma})\sqrt{\eta}|\dot\gamma_\eta|^2 d\eta \\
    &= (\sqrt{\tau}-\sqrt{\sigma}) \int_\sigma ^\tau \frac{\sqrt{\eta}}{2}|\dot\gamma_\eta|^2 + \frac{\sqrt{\eta}}{2}S_\eta + \frac{\sqrt{\tau}-\sqrt\sigma}{\sqrt{\eta}} \frac{n}{4}(\alpha-1) d\eta  \\
    & = \tilde{L}_-^{\sigma,\tau}(x,y) + (\sqrt{\tau}-\sqrt{\sigma})^2 \frac{n}{2}(\alpha-1)\,.
    \end{align}
\end{proof}

The gradient estimate \eqref{eq:GEL--GE-to-WC} implies the preservation of the $L_-$ Hamilton-Jacobi equation along the heat flow (see Lemma \ref{lem:heat-flow-preserves-HJ} for the $L_0$ analogue and further comments), which was essentially a mid-step in the proof from \eqref{eq:GEL--GE-to-WC} to \eqref{eq:WCL--GE-to-WC}.


\begin{prop} \label{prop:heat-flow-preserves-L_-HJ}
Suppose that \eqref{eq:GEL--GE-to-WC} holds, $f: [\alpha\tau_1,\alpha\tau_2] \times M\to \R{}$, $\alpha> 1$, $[\alpha\tau_1,\alpha\tau_2]\subseteq I$ is Lipschitz and satisfies the Hamilton-Jacobi inequality
\begin{equation}
\partial_\tau f(\tau,x) \leq -\frac{1}{2(\sqrt{\alpha\tau_2}-\sqrt{\alpha\tau_1})\sqrt{ \tau}}|\nabla f(\tau,x)|^2 + (\sqrt{\alpha\tau_2}-\sqrt{\alpha\tau_1}) \frac{\sqrt{\tau}}{2}S_{(\tau,x)}\,,\qquad \text{ a.e. }(\tau,x)\in M\times [\alpha\tau_1,\alpha\tau_2]\,.
\end{equation}

Then the Lipschitz function $P_{\alpha}[f]: [\tau_1, \tau_2] \to \R{}$, defined for $\tau_1\in I$ by $P_{\alpha}[f](\tau,x) := P_{\tau,\alpha\tau}f_{\alpha\tau}(x)$, itself satisfies the Hamilton-Jacobi-type inequality
\begin{align}
\partial_\tau P_{\alpha}[f](\tau,x) \leq -\frac{1}{2(\sqrt{\tau_2}-\sqrt{\tau_1})\sqrt\tau}|\nabla P_{\alpha}[f](\tau,x)|^2 + (\sqrt{\tau_2}-\sqrt{\tau_1}) \frac{\sqrt\tau}{2}S_{(\tau,x)}&+\frac{n}{4}(\alpha-1)\frac{\sqrt{\tau_2}-\sqrt{\tau_1}}{\sqrt\tau} \\ & \text{for a.e. } \tau\in  [\tau_1,\tau_2], \ \text{for all} \ x\in M,
\end{align}

and is therefore dominated by the $\tilde L_-$ distance:
\begin{equation}\label{eq:L--dominated-preserved}
P_{\alpha}[f](\tau,y) - P_{\alpha}[f](\sigma,x)  \leq \tilde L^{\sigma,\tau}_-(x,y) + \frac{n}{4}(\alpha-1)(\sqrt\tau_2-\sqrt\tau_1)(\sqrt{\tau}-\sqrt{\sigma}),\qquad \text{for all} \ x,y \in M,\, \sigma < \tau\in [\tau_1, \tau_2]\,. 
\end{equation}
\end{prop}
\begin{proof}
    The extra regularity is proved just as in Lemma \ref{lem:heat-flow-preserves-HJ}. Using the Hamilton-Jacobi inequality for $f$ and applying \eqref{eq:GEL--GE-to-WC} to $\frac{\sqrt{\alpha\tau}}{(\sqrt{\alpha\tau_2}-\sqrt{\alpha\tau_1})}f_{\alpha \tau}$ we get
    \begin{align}
        \partial_\tau P_{\tau,\alpha\tau}(f_{\alpha\tau}) 
        &\leq -\Delta P_{\tau,\alpha\tau}f_{\alpha\tau} + \alpha P_{\tau,\alpha\tau}\Delta f_{\alpha\tau} + \alpha \Bigg(-\frac{1}{2(\sqrt{\alpha\tau_2}-\sqrt{\alpha\tau_1})\sqrt{\alpha\tau}}P_{\tau,\alpha\tau}|\nabla f_{\alpha\tau}|^2 \\
        & \hspace{7cm}+(\sqrt{\alpha\tau_2}-\sqrt{\alpha\tau_1}) \frac{\sqrt{\alpha\tau}}{2}P_{\tau,\alpha\tau}S_{\alpha\tau}\Bigg) \\
        &\leq \frac{(\sqrt{\alpha\tau_2}-\sqrt{\alpha\tau_1})}{\sqrt{\alpha\tau}}\left[-\frac{1}{2\tau}\left|\nabla P_{\tau,\alpha\tau}f_{\alpha \tau}\frac{\sqrt{\alpha\tau}}{(\sqrt{\alpha\tau_2}-\sqrt{\alpha\tau_1})}\right|^2 + \frac{\tau}{2}S_{\tau} +\frac{n}{4}(\alpha-1) \right] \\
        &= -\frac{1}{2(\sqrt{\tau_2}-\sqrt{\tau_1})\sqrt\tau}|\nabla P_{\tau,\alpha\tau}f_{\alpha\tau}|^2 + (\sqrt{\tau_2}-\sqrt{\tau_1})\frac{\sqrt{\tau}}{2}S_\tau+\frac{n}{4}\frac{\sqrt{\tau_2}-\sqrt{\tau_1}}{\sqrt\tau}(\alpha-1).
    \end{align}
    Equation \eqref{eq:L--dominated-preserved} follows from integrating the Hamilton-Jacobi inequality along a geodesic.
\end{proof}


We now recover \eqref{eq:GEL--GE-to-WC} from \eqref{eq:WCL--GE-to-WC}.
\begin{prop}
    Suppose that for any times $[\sigma,\tau] \subseteq I$, factor $1 < \alpha < \sup I/\tau$, and measures $\mu,\nu \in \cP(M)$, \eqref{eq:WCL--GE-to-WC} holds. Then for all Lipschitz $v:M \to \R{}$, times $\sigma \in I$, and factors $1 < \alpha < \sup I/\sigma$, we also have \noeqref{eq:GEL--WC-to-GE}
    \begin{align}
    &|\nabla P_{\sigma,\alpha\sigma} v|^2_\sigma + 2\sigma\Delta_\sigma P_{\sigma,\alpha\sigma}v - \sigma^2 S_\sigma(x) \\
    &\leq P_{\sigma,\alpha \sigma}|\nabla v|^2_{\alpha \sigma}(x) + 2\alpha\sigma P_{\sigma,\alpha\sigma}\Delta_{\alpha\sigma} v - \alpha^2\sigma^2 P_{\sigma,\alpha \sigma}S_{\alpha \sigma}(x) + \frac{n}{2}\sigma(\alpha-1)\,.\label{eq:GEL--WC-to-GE}\tag{GE\({}_{L_-}\)}
\end{align}
\end{prop}

\begin{proof}
    We can rewrite \eqref{eq:WCL--GE-to-WC} as
\begin{align}\label{eq:WL-minus-monotoncity}
    \sqrt{\alpha}W_{L_-^{\alpha\sigma,\alpha\tau}}(\hat{P}_{\sigma,\alpha\sigma}\mu,\hat{P}_{\tau,\alpha\tau}\nu)\leq W_{L_-^{\sigma,\tau}}(\mu,\nu)+\frac{n}{2}(\sqrt{\tau}-\sqrt{\sigma})(\alpha-1).
\end{align}
Given $x,y\in M$, $[\sigma,\tau]\subseteq I$, $1<\alpha<\sup I/\tau$, consider a smooth curve $\bar\gamma:[\sigma,\tau]\to M$ from $x$ to $y$. For $\varsigma\in[\sigma,\tau]$ we define 
\begin{align}
    \varsigma\mapsto\mu_{\alpha \varsigma} := \hat{P}_{\varsigma,\alpha \varsigma}\delta_{\bar\gamma_{\varsigma}}
\end{align}
which is a curve of probability measures ``living at time $\alpha \varsigma$'' from $\hat{P}_{\sigma,\alpha \sigma}\delta_{\bar\gamma_\sigma}$ to $\hat{P}_{\tau,\alpha \tau}\delta_{\bar\gamma_\tau}$. By Lemma \ref{lem:dynamiclifting}, we find $\eta\in \cP(C([\alpha\sigma,\alpha\tau]\to M))$ with
\begin{align}
    (\dot{\mu}_{\alpha \varsigma})_{L_-^{\alpha \varsigma}} = \int_{C([\alpha\sigma,\alpha\tau]\to M)}\sqrt{\alpha \varsigma}\frac{1}{2}\left(|\dot{\gamma}|_{\alpha \varsigma}^2+S_{\alpha \varsigma}(\gamma_{\alpha \varsigma})\right)d\eta(\gamma).
\end{align}
Now, with the substitution $\vartheta=(\varrho-\varsigma)>0$
\begin{align}
    (\dot{\mu}_{\alpha \varsigma})_{L_-^{\alpha \varsigma}} &:= \lim_{\vartheta\to0}\frac{W_{L_-^{\alpha \varsigma,\alpha \varsigma+\alpha \vartheta}}(\mu_{\alpha \varsigma},\mu_{\alpha \varsigma+\alpha \vartheta})}{\alpha \vartheta} \\
    &=\lim_{\varrho\to \varsigma}\frac{W_{L_-^{\alpha \varsigma,\alpha \varrho}}(\mu_{\alpha \varsigma},\mu_{\alpha \varrho})}{\alpha(\varrho-\varsigma)},
\end{align}
hence \eqref{eq:WL-minus-monotoncity} implies (when $\tau\to\sigma$)
\begin{align}\label{eq:diffWCL-}
    \alpha^{3/2}(\dot\mu_{\alpha \varsigma})_{L_-^{\alpha \varsigma}} \leq (\dot\delta_{\bar\gamma_\varsigma})_{L_-^\varsigma} + \frac{n}{2}(\alpha-1)\frac{1}{2\sqrt{\varsigma}}.
\end{align}

We now have
\begin{align}
    P_{\tau, \alpha\tau} v(y) -P_{\sigma, \alpha\sigma} v(x)
    &=\int v d\hat{P}_{\tau,\alpha\tau}\delta_{\bar\gamma_\tau} - \int vd\hat{P}_{\sigma,\alpha\sigma}\delta_{\bar\gamma_\sigma} \\
    &= \int vd(\mu_{\alpha\tau}-\mu_{\alpha\sigma}) \\
    &= \int_{C([\alpha\sigma,\alpha\tau])\to M}\int_{\alpha\sigma}^{\alpha\tau} \langle dv(\gamma_\varsigma),\dot\gamma_\varsigma\rangle d\varsigma d\eta(\gamma) \\
    &\leq \int_{C([\alpha\sigma,\alpha\tau])\to M}\int_{\alpha\sigma}^{\alpha\tau} \left(\frac{1}{2\lambda}|\nabla v|_{\varsigma}^2(\gamma_\varsigma) + \frac{\lambda}{2}|\dot\gamma_\varsigma|_{\varsigma}^2 \right) d\varsigma d\eta(\gamma)
    \end{align}
    by Young's inequality for any $\lambda>0$. Setting up to recover the $W_{L^-}$ speed and using the (differentiated) Wasserstein contraction \eqref{eq:diffWCL-}
    \begin{align} 
    ...&= \int_{\alpha\sigma}^{\alpha\tau}\int_M\frac{1}{2\lambda} |\nabla v|^2_{\varsigma}d\mu_\varsigma d\varsigma + \int_C\int_{\alpha\sigma}^{\alpha\tau}\frac{\lambda}{2}(|\dot\gamma_\varsigma|^2_{\varsigma} + S_{\varsigma}(\gamma_\varsigma))d\varsigma d\eta(\gamma) - \int_C\int_{\alpha\sigma}^{\alpha\tau}\frac{\lambda}{2}S_{\varsigma}(\gamma_\varsigma)d\varsigma d\eta(\gamma) \\
    &= \int_{\sigma}^{\tau}\int_M\frac{1}{2\lambda} |\nabla v|^2_{\alpha \varsigma}d\mu_{\alpha \varsigma} \alpha d\varsigma + \int_C\int_{\sigma}^{\tau}\frac{\lambda}{2}(|\dot\gamma_{\alpha \varsigma}|^2_{\alpha \varsigma} + S_{\alpha \varsigma}(\gamma_{\alpha \varsigma}))\alpha d\varsigma d\eta(\gamma) - \int_C\int_{\sigma}^{\tau}\frac{\lambda}{2}S_{\alpha \varsigma}(\gamma_{\alpha \varsigma})\alpha d\varsigma d\eta(\gamma) \\
    &= \int_{\sigma}^{\tau}\frac{\alpha}{2\lambda}P_{\varsigma,\alpha \varsigma}|\nabla v|^2_{\alpha \varsigma}(\bar\gamma_\varsigma)d\varsigma + \int_{\sigma}^{\tau}\frac{\lambda\alpha}{\sqrt{\alpha \varsigma}}(\dot\mu_{\alpha \varsigma})_{L_-^{\alpha \varsigma}} d\varsigma - \int_{\sigma}^{\tau}\frac{\lambda\alpha}{2}P_{\varsigma,\alpha \varsigma}S_{\alpha \varsigma}(\bar\gamma_\varsigma)d\varsigma \\
    &\overset {\eqref{eq:diffWCL-}} {\leq} \int_{\sigma}^{\tau}\frac{\alpha}{2\lambda}P_{\varsigma,\alpha \varsigma}|\nabla v|^2_{\alpha \varsigma}(\bar\gamma_\varsigma)d\varsigma - \int_{\sigma}^{\tau}\frac{\lambda\alpha}{2}P_{\varsigma,\alpha \varsigma}S_{\alpha \varsigma}(\bar\gamma_\varsigma)d\varsigma \\
    &\qquad +\int_{\sigma}^{\tau}\left[\frac{\lambda\alpha}{\sqrt{\alpha \varsigma}}\frac{\sqrt{\varsigma}}{\alpha^{3/2}}\frac{1}{2}(|\dot{\bar\gamma}|^2_\varsigma+S_\varsigma(\bar\gamma_\varsigma)) + \frac{\lambda\alpha}{\sqrt{\alpha \varsigma}}\frac{1}{\alpha^{3/2}}\frac{n}{2}(\alpha-1)\frac{1}{2\sqrt{\varsigma}}\right]d\varsigma \label{eq:L--Lisini-application}
\end{align}


Now divide by $(\tau-\sigma)$ and send $\tau\to\sigma$: the first line becomes
\begin{align}
    \lim_{\tau\to\sigma} \frac{P_{\tau,\alpha\tau}v(\bar\gamma_\tau)-P_{\sigma,\alpha\sigma}v(\bar\gamma_\sigma)}{\tau-\sigma} &= -\Delta P_{\sigma,\alpha\sigma}v(x) + \alpha P_{\sigma,\alpha\sigma}\Delta v(x) + \langle dP_{\sigma,\alpha\sigma} v(x),\dot{\bar\gamma}_\sigma\rangle \\
    &= -\Delta P_{\sigma,\alpha\sigma}v(x) + \alpha P_{\sigma,\alpha\sigma}\Delta v(x) + |\nabla P_{\sigma,\alpha\sigma} v(x)|^2
\end{align}
by choosing $\dot{\bar\gamma}_\sigma=\nabla P_{\sigma,\alpha\sigma}v(x)$. The last line instead, with $\lambda=\alpha$, becomes
\begin{align}
    &\frac{1}{2}P_{\sigma,\alpha \sigma}|\nabla v|^2_{\alpha \sigma}(\bar\gamma_\sigma) - \frac{\alpha^2}{2}P_{\sigma,\alpha \sigma}S_{\alpha \sigma}(\bar\gamma_\sigma) +\frac{1}{2}(|\dot{\bar\gamma}_\sigma|^2_\sigma+S_\sigma(\bar\gamma_\sigma)) + \frac{1}{\sigma}\frac{n}{4}(\alpha-1) \\
    &=\frac{1}{2}P_{\sigma,\alpha \sigma}|\nabla v|^2_{\alpha \sigma}(\bar\gamma_\sigma) - \frac{\alpha^2}{2}P_{\sigma,\alpha \sigma}S_{\alpha \sigma}(\bar\gamma_\sigma) +\frac{1}{2}(|\nabla P_{\sigma,\alpha\sigma}v(x)|^2_\sigma+S_\sigma(\bar\gamma_\sigma)) + \frac{1}{\sigma}\frac{n}{4}(\alpha-1)
\end{align}
Altogether,
\begin{align}
    &-\Delta P_{\sigma,\alpha\sigma}v(x) + \alpha P_{\sigma,\alpha\sigma}\Delta v(x) + \frac{1}{2}|\nabla P_{\sigma,\alpha\sigma} v(x)|^2 \\
    &\leq \frac{1}{2}P_{\sigma,\alpha \sigma}|\nabla v|^2_{\alpha \sigma}(x) - \frac{\alpha^2}{2}P_{\sigma,\alpha \sigma}S_{\alpha \sigma}(x) +\frac{1}{2}S_\sigma(x) + \frac{1}{\sigma}\frac{n}{4}(\alpha-1)
\end{align}
i.e. multiplying by $2\sigma^2$
\begin{align}
    &|\nabla P_{\sigma,\alpha\sigma} \sigma v(x)|^2 - 2\sigma\Delta P_{\sigma,\alpha\sigma}\sigma v(x) - \sigma^2 S_\sigma(x) \\
    &\leq P_{\sigma,\alpha \sigma}|\nabla\sigma v|^2_{\alpha \sigma}(x) - 2\alpha\sigma P_{\sigma,\alpha\sigma}\Delta \sigma v(x) - \alpha^2\sigma^2 P_{\sigma,\alpha \sigma}S_{\alpha \sigma}(x) + \frac{n}{2}\sigma(\alpha-1)\,,
\end{align}
which is the desired gradient estimate for the function $\tilde v = -\sigma v$.
\end{proof}

We conclude the subsection with some modifications of the Wasserstein contraction estimates that can be useful in other contexts. The next corollary shows that, under $\cD\geq0$, we can get a Wasserstein estimate for any four times satisfying the compatibility assumption \eqref{eq:compatibilityoftimes}.
\begin{cor}\label{cor:WC-with-time-translations}
    Consider $(M^n,g_\tau)_{\tau \in I}$ a smooth family of closed Riemannian manifolds with $\dim M = n$, but now parametrized by an arbitrary (not necessarily positive) $I \subseteq \R{}$. Suppose that $\mathcal{D}\geq0$ holds, and let $\sigma_1,\sigma_2,\tau_1,\tau_2 \in I$ with $\sigma_1<\sigma_2$, $\tau_1<\tau_2$, $\sigma_1<\tau_1$ (without loss of generality, up to exchanging $\sigma_i$ and $\tau_i$), $\sigma_2 < \tau_2$, and \begin{align}\label{eq:compatibilityoftimes}
        \tau_2-\tau_1 > \sigma_2-\sigma_1.
    \end{align} Then there exists $T_0$ for which $\frac{\sigma_2+T_0}{\sigma_1+T_0}=\frac{\tau_2+T_0}{\tau_1+T_0}=:\alpha$ and $\sigma_1+T_0>0$, and hence
    \begin{align}
    W_{\tilde{L}_{T_0,-}^{\sigma_2,\tau_2}}(\hat{P}_{\sigma_1,\sigma_2}\mu,\hat{P}_{\tau_1,\tau_2}\nu)\leq W_{\tilde{L}_{T_0,-}^{\sigma_1,\tau_1}}(\mu,\nu)+\frac{n}{2}(\sqrt{\tau_2 - \tau_1}-\sqrt{\sigma_2 -\sigma_1})^2\,.
    \end{align}
    Here $\tilde L_{T_0,-}^{\alpha,\beta}$ is the normalized cost $\tilde L_{T_0,-}^{\alpha,\beta} = (\sqrt{\alpha + T_0} - \sqrt{\beta + T_0})L_{T_0,-}^{\alpha,\beta}$, with $L_{T_0,-}^{\alpha,\beta}(x,y)$ induced by the Lagrangian $L_{T_0,-}(v,x,\tau) :=\sqrt{\tau + T_0}(|v|^2_{g_\tau}+S_{\tau})(x)$.
\end{cor}

\begin{proof}
    Equation $\frac{\sigma_1+T_0}{\sigma_2+T_0}=\frac{\tau_1+T_0}{\tau_2+T_0}$ becomes $T_0=\frac{\sigma_2\tau_1-\sigma_1\tau_2}{(\tau_2-\tau_1)-(\sigma_2-\sigma_1)}$. Moreover, we have $\sigma_1+T_0=\frac{(\tau_1-\sigma_1)(\sigma_2-\sigma_1)}{(\tau_2-\tau_1)-(\sigma_2-\sigma_1)}>0$, thanks to \eqref{eq:compatibilityoftimes}. Now we apply the Wasserstein contraction to the shifted flow $(M,g_{\tau -T_0})_{\tau \in I + T_0}$: the translated flow still satisfies $\mathcal{D}\geq0$, as it is translation-invariant.
\end{proof}

The following allows us to compare two conjugate heat flows at any times using the $L_-$ distance, with their initial distribution at time $\tau=0$. Choosing the same measure we get a continuity in time statement for the conjugate heat flow.
\begin{cor}
    Consider $(M^n,g_\tau)_{\tau\in[0,T]}$ a smooth family of Riemannian manifolds with $\dim M = n$ and $\mathcal{D}\geq0$, then we have the estimate for any $\mu,\nu \in \cP(M)$, times $0<\sigma<\tau < T$,
    \begin{align}
        4W_{\tilde{L}_-^{\sigma,\tau}}(\hat{P}_{0,\sigma}\mu,\hat{P}_{0,\tau}\nu)\leq W_{d_0^2}(\mu,\nu)+2n(\sqrt{\tau}-\sqrt{\sigma})^2.
    \end{align}
    In particular, for $\mu=\nu$
    \begin{align}
        W_{\tilde{L}_-^{\sigma,\tau}}(\hat{P}_{0,\sigma}\mu,\hat{P}_{0,\tau}\mu)\leq \frac{n}{2}(\sqrt{\tau}-\sqrt{\sigma})^2.
    \end{align}
\end{cor}

\begin{proof}
    Fix $0<\bar \sigma<\bar\tau$, let $\bar\tau=\lambda\bar\sigma$. Consider a sequence $\sigma_i\to0$ and let $\tau_i=\lambda\sigma_i$, $\alpha_i=\frac{\bar\sigma}{\sigma_i}$. Apply equation \eqref{eq:WCL--GE-to-WC} with $\sigma=\sigma_i$, $\tau=\tau_i$, $\alpha=\alpha_i$, sending $i\to\infty$ we have (using \cite[Thm.~5.20]{Vil09} for the convergence)
    \begin{align}
        W_{\tilde{L}_-^{\bar\sigma,\bar\tau}}(\hat{P}_{0,\bar\sigma}\mu,\hat{P}_{0,\bar\tau}\nu) \leq W_{d_0^2/4}(\mu,\nu)+ \frac{n}{2}(\sqrt{\bar\tau}-\sqrt{\bar\sigma})^2.
    \end{align}
\end{proof}

\subsection{Entropy \texorpdfstring{$\tau^{-1/2}$}{t12}-convexity and \texorpdfstring{$\mathrm{EVI}$}{EVI}}\label{ss:entropyEVIL-}

\subsubsection{From entropy \texorpdfstring{$\tau^{-1/2}$}{t12}-convexity to $W_{L_-}$ contraction}\label{sss1:entropyEVIL-}
This is the analog of Subsection \ref{ss:entropyEVIL0} for the $L_{-}$ distance. Many aspects will be unchanged from the $L_0$ case, and we will omit the details that have already appeared in that setting. We begin with the implication where the formal computations are correct up to an error with a favorable sign. We consider times $\sigma < \tau$, a.c. measures $\mu_{\sigma} = \rho_\sigma\,dV_\sigma,\,\mu_{\tau} = \rho_\tau\,dV_\tau \in \cP(M)$, and Kantorovitch potentials $(\phi_\eta)_{\eta \in [\sigma,\tau]}: M\to \R{}$ provided by Corollary \ref{cor:dynamic-potentials} with respect to the $L_-$ cost. In particular, $\phi_\eta$ is Lipschitz and solves the following Hamilton-Jacobi equation

\begin{equation}\label{eq:L-minus-cvx-implies-contraction-I}
\partial_\eta \phi_\eta(x) = - \frac{1}{2\sqrt{\eta}}|\nabla \phi_\eta|^2_{g_\eta}(x) + \frac{\sqrt{\eta}}{2}S_\eta(x)\,,\qquad \forall \eta \in [\sigma,\tau]\,,\text{ a.e. }x\in M\,.
\end{equation}

One can also estimate the (one-sided) derivatives of entropy along $L_-
$ Wasserstein geodesics using the semi-concavity properties of the potentials as in Lemma \ref{lem:Top-1-sided-est}, or more directly \cite[l.~(3.18),~(3.24-25)]{Top09}

\begin{align}\label{eq:L-minus-cvx-implies-contraction-II}
\sqrt{\sigma}\left.\frac{d}{d\eta}\right|_{\eta = \sigma^+} \cE(\mu_\eta) &\geq \int_M (\La \nabla \ln(\rho_{\sigma}),\nabla \phi_{\sigma}\Ra - \sqrt{\sigma}S_{\sigma})d\mu_{\sigma}\,, \\
\sqrt{\tau}\left.\frac{d}{d\eta}\right|_{\eta = \tau^-} \cE(\mu_\eta) &\leq \int_M (\La \nabla \ln(\rho_{\tau}),\nabla \phi_{\tau}\Ra - \sqrt{\tau}S_{\tau})d\mu_{\tau}\,.
\end{align}

As in Proposition \ref{prop:L0-cvxty-implies-contr/EVI}, this is sufficient to obtain $W_{L_-}$ contraction for multiplicatively related times if we assume an appropriate entropy convexity along $W_{L_-}$ geodesics. These computations are related to those of \cite[Prop.~16]{Lot09}, but with \eqref{eq:L-minus-cvx-implies-contraction-II} in hand there is no need to perform any (further) computations along $L_-$ geodesics.

\begin{prop}\label{prop:L-minus-convexity-implies-contraction}
Pick times $[\sigma,\tau]\subseteq I$ and suppose also that for any measures $\mu_{\sigma},\,\mu_\tau \in \cP(M)$ there exists a $W_{L_-}$-geodesic $(\mu_{\eta})_{\eta \in [\sigma,\tau]}$ between $\mu_{\sigma}, \mu_{\tau}$ such that

\begin{equation}
\cE(\mu_\eta) - \cE(\mu_{\sigma}) + \frac{1}{\sqrt{\eta}}W_{L_-^{\sigma,\eta}}(\mu_{\sigma},\mu_{\eta}) + \frac{n}{2}\ln(\eta/\sigma)\,,\label{eq:ECL--EC-to-WC}\tag{EC\({}_{L_-}\)}
\end{equation}
is convex in the variable $\eta^{-1/2}$. Then for any $\mu_{\sigma}, \mu_{\tau} \in \cP(M)$ and $1 < \alpha \leq \sup I/\tau$, it holds \noeqref{eq:WCL--EC-to-WC}

\begin{align}
(\sqrt{\alpha \tau} - \sqrt{\alpha\sigma})&\cdot W_{L_-^{\alpha\sigma, \alpha\tau}}(\hat{P}_{\sigma,\alpha\sigma}\mu_{\sigma}, \hat{P}_{\tau, \alpha\tau}\mu_{\tau}) - \frac{n}{2}(\sqrt{\alpha\tau} - \sqrt{\alpha\sigma})^2 \\
&\leq (\sqrt{\tau} - \sqrt{\sigma})\cdot W_{L_-^{\sigma,\tau}}(\mu_{\sigma}, \mu_{\tau}) - \frac{n}{2}(\sqrt{\tau} - \sqrt{\sigma})^2\,.\label{eq:WCL--EC-to-WC}\tag{WC\({}_{L_-}\)}
\end{align}
\end{prop}

\begin{proof}
The technical details--in particular the smoothing of the measures by flowing for some small time $\eps > 0$--are identical to those of the proof of Proposition \ref{prop:L0-cvxty-implies-contr/EVI}. We therefore restrict our attention to the formal computations, which all hold rigorously for endpoint measures that are smooth with full support.

Writing $d/d(\eta^{-1/2}) = -2\eta^{3/2}d/d\eta$, by the convexity assumption we have

\begin{equation}
-\frac{n}{2}(\sqrt{\tau} - \sqrt{\sigma}) \leq \left. \eta^{3/2}\frac{d}{d\eta}\left[\cE(\mu_\eta) + \frac{1}{\sqrt{\eta}}W_{L_-^{\sigma,\eta}}(\mu_{\sigma},\mu_\eta)\right]\right|_{\sigma^+}^{\tau^{-}}\,.
\end{equation}

Note that the existence of the one-sided derivatives of the first term of the RHS is provided by \eqref{eq:L-minus-cvx-implies-contraction-II}, while the derivative for the second term is computed using Proposition \ref{prop:Lisini-for-geodesics} applied to the $L_-$ Lagrangian, yielding
\begin{align}
\cdots &\leq \left.\eta\int_M (\La \nabla \ln( \rho_\eta),\nabla \phi_\eta \Ra - \sqrt{\eta}S_\eta)d\mu_\eta -\frac{1}{2}\int_{M}\phi_\eta\,d\mu_{\eta} + \eta\int_M \left(\frac{1}{2\sqrt{\eta}}|\nabla \phi_\eta|^2 + \frac{\sqrt{\eta}}{2}S_\eta\right)\, d\mu_\eta\right|_{\sigma}^{\tau}\\
&= \left.-\eta\int_M \phi_\eta\Delta\rho_\eta \,dV_\eta -\frac{1}{2}\int_{M}\phi_\eta\,d\mu_{\eta} - \eta\int_M \left(-\frac{1}{2\sqrt{\eta}}|\nabla \phi_\eta|^2 + \frac{\sqrt{\eta}}{2}S_\eta\right)\, d\mu_\eta\right|_{\sigma}^{\tau}\,.
\end{align}

Since $\phi_\eta$ (extended past $\tau$ using the Hopf-Lax semigroup) is Lipschitz and \eqref{eq:L-minus-cvx-implies-contraction-I} holds a.e. in $M$ for $\eta = \sigma,\tau$, one computes 

\begin{equation}
\cdots =-\left.\partial_{\alpha}\right|_{\alpha = 1^+} \sqrt{\alpha}\cdot\left[\int_{M} \phi_{\alpha\tau} d\hat{P}_{\tau, \alpha\tau}[\nu_{\tau}] - \int_{M} \phi_{\alpha\sigma} d\hat{P}_{\sigma, \alpha\sigma}[\nu_{\sigma}]\right]\,.
\end{equation}

Now, as in Proposition \ref{prop:L0-cvxty-implies-contr/EVI}, and modulo the technical details therein, this shows that 

\begin{equation}
\left.\partial_\alpha^+\right|_{\alpha = 1^+} \sqrt{\alpha}\cdot W_{L_-^{\alpha\sigma, \alpha\tau}}(\hat{P}_{\sigma,\alpha\sigma}[\nu_{\sigma}], \hat{P}_{\tau,\alpha\tau}[\nu_{\tau}]) \leq \frac{n}{2}(\sqrt{\tau} - \sqrt{\sigma})\,,
\end{equation}
and thus that the quantity $(\sqrt{\alpha \tau} - \sqrt{\alpha\sigma})\cdot W_{L_-^{\alpha\sigma, \alpha\tau}}(\hat{P}_{\sigma, \alpha\sigma}[\nu_{\sigma}], \hat{P}_{\tau,\alpha\tau}[\nu_{\tau}]) - (n/2)(\sqrt{\alpha\tau} - \sqrt{\alpha\sigma})^2$ is non-increasing in $\alpha > 1$.
\end{proof}

\subsubsection{From gradient estimates to entropy \texorpdfstring{$\tau^{-1/2}$}{t12}-convexity (via $\mathrm{EVI}$).}\label{sss2:entropyEVIL-}
We now turn to the other direction: beginning  from \eqref{eq:GEL--GE-to-EVI} we recover \eqref{eq:ECL--EC-to-WC}, passing through \eqref{eq:EVIL--GE-to-EVI}. The general strategy is the same as in the $L_0$ case, but there are a few additional technical challenges.

\begin{lem}\label{lem:L-minus-action-entropy-est}
Let $(\nu_\eta)_{\eta \in [\sigma,\tau]} = (\rho_\eta dV_\eta)_{\eta \in [\sigma,\tau]}$, $\rho \in C^\infty\big([\sigma,\tau]\times M;(0,\infty)\big)$, $[\sigma,\tau] \subseteq I$, a curve of smooth measures with positive densities. For $\sup I/\tau,\tau/\sigma > \alpha > 1$, write $\lambda_I := (\sqrt{\alpha} - 1)/((\sigma/\alpha)^{-1/2} - \tau^{-1/2})$, $\lambda_{II} := (\sqrt{\alpha} - 1)/(\sigma^{-1/2} - (\tau/\alpha)^{-1/2})$. Then if the $L_-$-type gradient estimate \eqref{eq:GEL--GE-to-EVI} holds, we have the action-entropy estimates
\begin{align}
\lambda_I\cE(\hat{P}_{\tau, \alpha\tau}[\nu_{\tau}]) + \frac{1}{\sqrt{\alpha}}W_{L_-^{\sigma,\alpha\tau}}(\nu_{\sigma},\hat{P}_{\tau, \alpha\tau}[\nu_{\tau}]) &\leq \lambda_I\cE(\nu_{\sigma})  +\frac{1 - \lambda_I/\sqrt{\sigma}}{\sqrt{\alpha}}\int_{\sigma}^{\tau}(\dot\nu_{\tilde\eta})_{L_-^{\tilde \eta}}\,d\tilde\eta  \\
&\qquad + \frac{\lambda_I}{2}\int_{\sigma}^{\tau}\frac{1}{\eta^{3/2}}\left(\int_{\sigma}^{\eta}(\dot{\nu}_{\tilde\eta})_{L_-^{\tilde \eta}}\,d\tilde\eta  - W_{L_-^{\sigma,\eta}}(\nu_{\sigma},\nu_{\eta})\right)\,d\eta\\
&\qquad +n (\sqrt{\alpha} - 1)\sqrt{\tau} - \frac{n}{2}\lambda_I \ln(\tau/\sigma) + O((\sqrt{\alpha} - 1)^2)\,, \label{eq:L-minus-preEVI-I}
\end{align}
and
\begin{align}
-\lambda_{II} \cE(\nu_{\tau}) + W_{L_0^{\alpha\sigma,\tau}}(\hat{P}_{\sigma, \alpha\sigma}[\nu_{\sigma}], \nu_{\tau}) &\leq -\lambda_{II} \cE(\hat{P}_{\sigma, \alpha\sigma}[\nu_{\sigma}]) + (1 + \lambda_{II}/\sqrt{\tau})\int_{\sigma}^{\tau}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta \\
& \qquad - \frac{\lambda_{II}}{2}\int_{\sigma}^{\tau}\frac{1}{\eta^{3/2}}\left(\int^{\eta}_{\sigma}(\dot{\nu}_{\tilde\eta})_{L_-^{\tilde \eta}}\,d\tilde\eta  - W_{L_-^{\sigma,\eta}}(\nu_{\sigma},\nu_{\eta})\right)\,d\eta \\
&\qquad -n(\sqrt{\alpha} - 1)\sqrt{\sigma} + \frac{n}{2}\lambda_{II}\ln(\tau/\sigma) + O((\sqrt{\alpha} - 1)^2)\,. \label{eq:L-minus-preEVI-II}\
\end{align}
The constant implicit in the $O((\sqrt\alpha - 1)^2)$ error term depends on quantities that are independent of the curve $(\nu_\eta)_{\eta \in [\sigma,\tau]}$ (namely $\text{diam}_{L_-}((M,g_\eta)_{\eta \in [\sigma,\tau]}) $, $-\inf_{(\eta,x)\in I \times M} \min(0, S_\eta(x))$, $n$, $\tau$, $\sigma$), and on a uniform bound on the actions $\sup_{[\tilde\sigma,\tilde{\tau}]\subseteq [\sigma,\tau]} \left|\int_{\tilde\sigma}^{\tilde\tau}(\dot\nu_{\eta})_{L_-^\eta}\,d\eta\right|$.
\end{lem}

\begin{proof}
We proceed as in the proof of Lemma \ref{lem:L0-action-entropy-est}, but with fewer details when the two proofs align. In this case, we consider the $\sqrt{\cdot}$-linear, bijective map of intervals $\xi_\alpha: [\sigma,\alpha\tau] \to [\sigma,\tau
]$ given by

\begin{equation}\label{eq:L-paramdefn}
\xi_\alpha:\begin{cases}\xi_\alpha(\sigma) = \sigma\,,\,\xi_\alpha(\alpha\tau) = \tau\,,& \\ \sqrt{\xi_\alpha(\eta)} = (1 - \lambda) \cdot\sqrt{\eta} + b&\end{cases}\, \implies \lambda = \frac{\sqrt{\tau}\cdot(\sqrt{\alpha} - 1)}{\sqrt{\alpha\tau} - \sqrt{\sigma}}\,,\qquad b = \frac{\sqrt{\sigma\tau}\cdot(\sqrt{\alpha} - 1)}{\sqrt{\alpha\tau} - \sqrt{\sigma}} \,.
\end{equation}

The two properties of $\xi_\alpha$ that will interest us are its values at the boundary of the interval, along with the ODE $\xi_\alpha'(\eta) = (1 - \lambda)\cdot \sqrt{\xi_\alpha(\eta)/\eta}$ it solves. As in Lemma \ref{lem:L0-action-entropy-est}, we now define the ``diagonal'' curve of measures $\nu_{\eta,\alpha} := \rho_{\eta,\alpha}\,dV_\eta := \hat{P}_{\xi_{\alpha}(\eta),\eta}[\nu_{\xi_\alpha(\eta)}]$ for $\eta \in [\sigma,\alpha\tau]$, along with a family of Kantorovich potentials $(\phi_\eta)_{\eta \in [\sigma,\alpha\tau]}: M \to \R{}$ from $\nu_{\sigma,\alpha}$ to $\nu_{\alpha\tau,\alpha}$ given by Corollary \ref{cor:dynamic-potentials}, which are Lipschitz and solve the Hamilton-Jacobi equation \eqref{eq:L-minus-cvx-implies-contraction-I} for every $\eta \in [\sigma,\alpha\tau]$ and a.e. $x \in M$. It will be convenient to label the (non-constant) quantity $\kappa := 1 - \eta\xi_\alpha'(\eta)/\xi_{\alpha}(\eta) = 1 - \sqrt{\eta/\xi_\alpha(\eta)}(1 - \lambda)$. We compute (using $1=(1-\kappa)(\frac{\kappa}{1-\kappa}+1)$)

\begin{align}
\eta^{2}\partial_\eta \cE(\nu_{\eta,\alpha}) &= (1 - \kappa)\int_M P_{\xi_\alpha(\eta),\eta}\left[\eta\Delta_\eta \big(\eta\ln \rho_{\eta,\alpha}\big) - \frac{\kappa}{1 - \kappa} |\nabla\big(\eta\ln \rho_{\eta,\alpha}\big)|^2\right] \,d\nu_{\xi_\alpha(\eta)} \\
& \qquad - \eta^{2}\int_M S_\eta\,d\nu_{\eta,\alpha} - (1 - \kappa)\int_M \Big(\xi_\alpha(\eta)\Delta_{\xi_\alpha(\eta)}P_{ \xi_\alpha(\eta),\eta}[\eta\ln \rho_{\eta,\alpha}]\Big)\,d\nu_{\xi_\alpha(\eta)}\\
&\qquad + (1 - \lambda)\int_M \sqrt{\eta\xi_\alpha(\eta)} P_{\xi_\alpha(\eta),\eta}[\eta\big(1 + \ln \rho_{\eta,\alpha}\big)]\,\left.\partial_\upsilon\right|_{\upsilon = \xi_\alpha(\eta)}d\nu_\upsilon\,,
\end{align}

and

\begin{align}
&\phantom{=}\eta^{3/2}\partial_\eta \int_M \phi_\eta \,d\nu_{\eta,\alpha} \\
&= (1 - \kappa)\int_M P_{ \xi_\alpha(\eta),\eta}\left[\eta\Delta_\eta (\sqrt{\eta}\phi_\eta) - \frac{\kappa}{1 - \kappa}\La\nabla (\sqrt{\eta}\phi_\eta), \nabla (\eta\ln \rho_{\eta,\alpha})\Ra +\frac{\eta^{2}}{2} S_{\eta} -\frac{1}{2}|\nabla(\sqrt{\eta} \phi_\eta)|^2\right]\,d\nu_{\xi_\alpha(\eta)} \\
& \qquad- (1 - \kappa)\int_M\left(\xi_\alpha(\eta)\Delta_{\xi_\alpha(\eta)} P_{\xi_\alpha(\eta),\eta}[\sqrt{\eta}\phi_\eta] \right)\,d\nu_{\xi_\alpha(\eta)} + \kappa\int_M \frac{\eta^2}{2}S_\eta - \frac{1}{2}|\sqrt{\eta}\nabla \phi_\eta|^2\,d\nu_{\eta,\alpha} \\
&\qquad + (1 - \lambda) \int_M \sqrt{\eta\xi_\alpha(\eta)}P_{\xi_\alpha(\eta),\eta}[\sqrt{\eta}\phi_\eta]\,\left.\partial_\upsilon\right|_{\upsilon = \xi_\alpha(\eta)} d\nu_\upsilon\,.
\end{align}

We now verify the remaining steps from the proof of Lemma \ref{lem:L0-action-entropy-est}. In particular, we consider a linear combination $\eta^{3/2}\partial_\eta \int_M \phi_\eta\,d\nu_{\eta,\alpha} + [\kappa/(1 - \kappa)]\eta^2\partial_\eta\cE(\nu_{\eta,\alpha})$ of the LHS's above and attempt to estimate the terms appearing on the RHS's. It is convenient to define the corresponding auxiliary function $f_\eta: = \phi_\eta + \kappa\sqrt{\eta}\ln(\rho_{\eta,\alpha})/(1 - \kappa)$. 

First, using the computation of \eqref{eq:L--Lisini-application} yields 

\begin{align}
&(1 - \lambda)\int_M \sqrt{\eta\xi_\alpha(\eta)}P_{\xi_\alpha(\eta),\eta}[\sqrt{\eta} f_\eta]\,\left.\partial_\upsilon\right|_{\upsilon = \xi_\alpha(\eta)}d\nu_\upsilon \\
&\leq \frac{1 - \lambda}{2}\int_M \sqrt{\frac{\eta}{\xi_\alpha(\eta)}}\Big(|\nabla P_{\xi_\alpha(\eta),\eta}[\sqrt{\eta} f_\eta]|^2 - \xi_\alpha^2(\eta) S_{\xi_\alpha(\eta)}\Big)\,d\nu_{\xi_\alpha(\eta)} + (1 - \lambda)\sqrt{\eta}\xi_\alpha(\eta)(\dot{\nu}_{\xi_\alpha(\eta)})_{L_-^{\xi_\alpha(\eta)}}\\
&= \frac{1 - \kappa}{2}\int_M \Big(|\nabla P_{\xi_\alpha(\eta),\eta}[\sqrt{\eta} f_\eta]|^2 - \xi_\alpha^2(\eta) S_{\xi_\alpha(\eta)}\Big)\,d\nu_{\xi_\alpha(\eta)} + \eta\sqrt{\xi_\alpha(\eta)}\xi_\alpha'(\eta)(\dot{\nu}_{\xi_\alpha(\eta)})_{L_-^{\xi_\alpha(\eta)}}\,. 
\end{align}

Second, using the assumed gradient estimate \eqref{eq:GEL--GE-to-EVI} with initial data $\sqrt{\eta} f_\eta$ between the times $\xi_\alpha(\eta) < \eta$ yields

\begin{align}
&\phantom{-}(1 - \kappa)\int_M P_{\xi_\alpha(\eta),\eta}[\eta\Delta_\eta (\sqrt{\eta}f_\eta) - \frac{1}{2}|\nabla (\sqrt{\eta}f_\eta)|^2 + \frac{\eta^2}{2}S_\eta]\,d\nu_{\xi_\alpha(\eta)} \\
&\qquad - (1 - \kappa)\int_M\left(\xi_\alpha(\eta)\Delta_{\xi_\alpha(\eta)} P_{\xi_\alpha(\eta),\eta}[\sqrt{\eta}f_\eta] -\frac{1}{2} |\nabla P_{\xi_\alpha(\eta),\eta}[\sqrt{\eta}f_\eta]|^2 + \frac{\xi_\alpha^2(\eta)}{2}S_{\xi_\alpha(\eta)} \right)\,d\nu_{\xi_\alpha(\eta)} \\
&\leq \frac{n}{4}(1 - \kappa)(\eta - \xi_\alpha(\eta))\,.
\end{align}

Assembling these two estimates as in Lemma \ref{lem:L0-action-entropy-est}, and multiplying by $(1 - \kappa)$ we obtain

\begin{align}
(1 - \kappa^2)\eta^{3/2}\partial_\eta\int_M \phi_\eta \,d\nu_{\eta,\alpha} + \kappa\eta^2\partial_\eta\cE(\nu_{\eta,\alpha}) &\leq (1 - \kappa)\eta\sqrt{\xi_\alpha(\eta)}(\dot{\nu}_{\xi_\alpha(\eta)})_{L_-^{\xi_\alpha(\eta)}}\xi_\alpha'(\eta) \\
&\qquad - \kappa^2\eta^2\int_M S_\eta \,d\nu_{\eta,\alpha} +\frac{n}{4}(1 - \kappa)^2(\eta - \xi_\alpha(\eta))\,.
\end{align}

Before integrating in $\eta$, we would like to remove the $\eta$ dependence of the $\cE(\nu_{\eta,\alpha})$ coefficient. We compute:

\begin{equation}\label{eq:L-param-rel}
\kappa = 1 - \sqrt{\frac{\eta}{\xi_\alpha(\eta)}}(1 - \lambda) = \frac{b}{\sqrt{\xi_\alpha(\eta)}}
\end{equation}

We should therefore divide the last inequality through by $\eta^2/\sqrt{\xi_\alpha(\eta)}$. Doing so and integrating in time yields

\begin{align}\label{eq:halfwayL-EVI}
\int_{\sigma}^{\alpha\tau}\left((1 - \kappa^2)\sqrt{\frac{\xi_\alpha(\eta)}{\eta}}\partial_\eta\int_M \phi_\eta \,d\nu_{\eta,\alpha}\right)\,d\eta + b\left.\cE(\nu_{\eta,\alpha})\right|_{\sigma}^{\alpha\tau} &\leq (1 - \lambda)\int_{\sigma}^{\alpha\tau}\left(\sqrt{\frac{\xi_\alpha(\eta)}{\eta}}(\dot{\nu}_{\xi_\alpha(\eta)})_{L_-^{\xi_\alpha(\eta)}}\xi_\alpha'(\eta)\right)\,d\eta \\
&\qquad - \int_{\sigma}^{\alpha\tau}\left(\kappa^2\sqrt{\xi_\alpha(\eta)}\int_M S_\eta \,d\nu_{\eta,\alpha}\right)\,d\eta \\
&\qquad +\frac{n}{4}\int_{\sigma}^{\alpha\tau}\left((1 - \kappa)^2\sqrt{\xi_\alpha(\eta)}\frac{(\eta - \xi_\alpha(\eta))}{\eta^2}\right)\,d\eta\,.
\end{align}

To avoid dragging along higher-order errors, we will begin consolidating terms that are uniformly $O\big((\sqrt{\alpha} - 1)^2\big)$ whenever uniform upper bounds $ -S, \,\tau - \sigma, \,W_{L_-^{\sigma,\tau}}(\nu_{\sigma}, \,\nu_{\tau}) \leq C$ hold. For instance, this will include all monomials of degree $\geq 2$ in $b,\lambda,\kappa$, by \eqref{eq:L-paramdefn}, \eqref{eq:L-param-rel}. This leaves us with three integrals to compute. Integrating by parts:

\begin{align}
\int_{\sigma}^{\alpha\tau}\left((1 - \kappa^2)\sqrt{\frac{\xi_\alpha(\eta)}{\eta}}\partial_\eta\int_M \phi_\eta \,d\nu_{\eta,\alpha}\right)\,d\eta &= \left. \sqrt{\frac{\xi_\alpha(\eta)}{\eta}}\left(\int_M \phi_\eta\,d\nu_{\eta_\alpha} - \int_M \phi_{\sigma}\,d\nu_{\sigma,\alpha}\right)\right|_{\eta = \sigma}^{\alpha\tau} + O((\sqrt{\alpha} - 1)^2)\\
&\qquad -\int_{\sigma}^{\alpha\tau}\partial_\eta\left((1 - \lambda) + \frac{b}{\sqrt{\eta}}\right)\left(\int_M \phi_\eta\,d\nu_{\eta_\alpha} - \int_M \phi_{\sigma}\,d\nu_{\sigma,\alpha}\right)\,d\eta  \\
&= \frac{1}{\sqrt{\alpha}}W_{L_-^{\sigma,\alpha\tau}}(\nu_{\sigma,\alpha},\nu_{\alpha\tau,\alpha}) +\frac{b}{2}\int_{\sigma}^{\alpha\tau}\frac{1}{\eta^{3/2}}W_{L_-^{\sigma,\eta}}(\nu_{\sigma,\alpha},\nu_{\eta,\alpha})\,d\eta \\
&\qquad +O((\sqrt{\alpha} - 1)^2)\,,
\end{align}
and by substitution, denoting by $\xi_\alpha^{\circ - 1}:[\sigma,\tau]\to[\sigma,\alpha\tau]$ the inverse of $\xi_\alpha$,
\begin{align}
(1 - \lambda)\int_{\sigma}^{\alpha\tau}\left(\sqrt{\frac{\xi_\alpha(\eta)}{\eta}}(\dot{\nu}_{\xi_\alpha(\eta)})_{L_-^{\xi_\alpha(\eta)}}\xi_\alpha'(\eta)\right)\,d\eta &= (1 - \lambda)\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\alpha\tau)}\sqrt{\frac{\bar\eta}{\xi_\alpha^{\circ - 1}(\bar\eta)}}(\dot{\nu}_{\bar\eta})_{L_-^{\bar \eta}}\,d\bar \eta \\
&=(1 - \lambda)\left.\sqrt{\frac{\bar\eta}{\xi_\alpha^{\circ - 1}(\bar\eta)}}\int_{\xi_\alpha(\sigma)}^{\bar\eta}(\dot{\nu}_{\tilde\eta})_{L_-^{\tilde \eta}}\,d\tilde\eta\right|_{\bar\eta = \xi_\alpha(\sigma)}^{\xi_\alpha(\alpha\tau)} \\
&\qquad - (1 - \lambda)\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\alpha\tau)}\partial_{\bar\eta} \left(\sqrt{\frac{\bar\eta}{\xi_\alpha^{\circ - 1}(\bar\eta)}}\right)\int_{\xi_\alpha(\sigma)}^{\bar\eta}(\dot{\nu}_{\tilde\eta})_{L_-^{\tilde \eta}}\,d\tilde\eta d\bar\eta \\
&= \frac{1 - \lambda}{\sqrt{\alpha}}\int_{\sigma}^{\tau}(\dot\nu_{\tilde\eta})_{L_-^{\tilde \eta}}\,d\tilde\eta + \frac{b(1-\lambda)}{2}\int_{\sigma}^{\alpha\tau}\frac{1}{\eta^{3/2}}\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\eta)}(\dot{\nu}_{\tilde\eta})_{L_-^{\tilde \eta}}\,d\tilde\eta d\eta\,.
\end{align}
Note that to simplify the last integral we used $\partial_{\bar\eta} \left(\sqrt{\frac{\bar\eta}{\xi_\alpha^{\circ - 1}(\bar\eta)}}\right) = -\frac{b}{2}\frac{1}{\eta^{3/2}\xi_\alpha'(\eta)}$ for $\eta=\xi_\alpha^{\circ - 1}(\bar\eta)$.

The expressions appearing in the RHS's of the two computations above are, up to $O((\sqrt{\alpha} - 1)^2)$ error with allowable implicit constant dependence, the $W_{L_-}$ distance and action terms that appear in \eqref{eq:L-minus-preEVI-I}. We finally turn to the last term in \eqref{eq:halfwayL-EVI}, which is of order $O(\sqrt{\alpha} - 1)$, and compute its coefficient
\begin{align}
\lim_{\alpha \to 1^+}\frac{1}{\sqrt{\alpha} - 1}\int_{\sigma}^{\alpha\tau}\frac{n}{4}\left((1 - \kappa)^2\sqrt{\xi_\alpha(\eta)}\frac{(\eta - \xi_\alpha(\eta))}{\eta^2}\right)\,d\eta &= \lim_{\alpha \to 1^+}\frac{n(1 - \lambda)^2}{4}\int_{\sigma}^{\alpha\tau}\frac{(\eta - \xi_\alpha(\eta))}{(\alpha - 1)}\frac{\sqrt{\alpha} + 1}{\sqrt{\xi_\alpha(\eta)}\eta}\,d\eta \\
&= \frac{n}{2}\int_{\sigma}^{\tau}\frac{-\left.\partial_\alpha\right|_{\alpha = 1^+}\xi_\alpha(\eta)}{\eta^{3/2}}\,d\eta \\
&= n \sqrt{\tau} - \frac{n}{2}\frac{\sqrt{\tau\sigma}}{\sqrt{\tau} - \sqrt{\sigma}}\ln(\tau/\sigma)\,,
\end{align}
where we used 
\begin{align}
\left.\partial_\alpha\right|_{\alpha = 1^+}\xi_\alpha(\eta) &= \left.\partial_\alpha\right|_{\alpha = 1^+}\left(\frac{\sqrt{\tau} - \sqrt{\sigma}}{\sqrt{\alpha\tau} - \sqrt{\sigma}}\sqrt{\eta} + \frac{\sqrt{\tau\sigma}\cdot(\sqrt{\alpha} - 1)}{\sqrt{\alpha\tau} - \sqrt{\sigma}}\right)^2 \\
&= -\frac{\sqrt{\tau}}{\sqrt{\tau} - \sqrt{\sigma}}\eta + \frac{\sqrt{\tau\sigma}}{\sqrt{\tau} - \sqrt{\sigma}}\sqrt{\eta}\,.
\end{align}
Gathering $O((\sqrt{\alpha} - 1)^{2})$ errors and unpacking notation gives the desired final expression.

The second inequality follows from running the same argument with $\nu_\eta^\alpha := \hat{P}_{\tilde{\xi}_\alpha(\eta),\eta}[\nu_{\tilde{\xi}_\alpha(\eta)}]$ for the range of times $[\alpha\sigma,\tau]$, where $\tilde{\xi}_\alpha: [\alpha\sigma,\tau] \to [\sigma,\tau]$ solves

\begin{equation}
\tilde{\xi}_\alpha(\eta): \begin{cases}\tilde{\xi}_\alpha(\alpha\sigma) = \sigma\,,\,\tilde{\xi}_\alpha(\tau) = \tau\,,&\\
\sqrt{\tilde{\xi}_\alpha(\eta)} = (1 + \tilde{\lambda})\cdot \sqrt{\eta} + \tilde{b}\end{cases}\,\implies \tilde{\lambda} = \frac{\sqrt{\sigma}(\sqrt{\alpha} - 1)}{\sqrt{\tau} - \sqrt{\alpha\sigma}}\,,\qquad \tilde{b} = -\frac{\sqrt{\tau\sigma}(\sqrt{\alpha} - 1)}{\sqrt{\tau} - \sqrt{\alpha\sigma}}\,.
\end{equation}
\end{proof}

As in the $L_0$ case, these action-entropy estimates can be used to obtain the respective \eqref{eq:EVIL--GE-to-EVI}s.

\begin{prop}\label{prop:L-GE-to-EVI}
Assume that for any Lipschitz $v$ and times $[\sigma,\tau] \subseteq I$, the gradient estimate
\begin{equation}
 |\nabla P_{\sigma,\tau}v|_\sigma^2-2\sigma \Delta_\sigma P_{\sigma,\tau}v-\sigma^2S_{\sigma} \leq P_{\sigma,\tau}\left(|\nabla v|_\tau ^2 - 2\tau\Delta_\tau v - \tau ^2S_{\tau}\right) + \frac{n}{2}(\tau-\sigma)\label{eq:GEL--GE-to-EVI}\tag{GE\({}_{L_-}\)}
\end{equation}
holds. Then, for any Borel probability measures $\mu,\nu \in \cP(M)$ and times $[\sigma,\tau] \subseteq I$, the backward heat flow $\hat P$ satisfies the following $\mathrm{EVI}$s
\begin{align}
\eta\cdot\partial_{\eta^+}^+ W_{L_-^{\eta,\tau}}(\hat{P}_{\sigma,\eta}[\nu], \mu) &\leq \frac{1}{2(\eta^{-1/2} - \tau^{-1/2})} \left[\cE(\mu) -\cE(\hat{P}_{\sigma,\eta}[\nu]) + \frac{W_{L_-^{\eta,\tau}}(\hat{P}_{\sigma,\eta}[\nu], \mu)}{\sqrt{\tau}} \right] \\
&\qquad +\frac{n\ln(\tau/\eta)}{4(\eta^{-1/2} - \tau^{-1/2})} - \frac{n\sqrt{\eta}}{2}\,, \qquad \forall\eta \in [\sigma,\tau)\,, \\
\varsigma\cdot\partial_{\varsigma^+}^+ W_{L_-^{\sigma,\varsigma}}(\nu,\hat{P}_{\tau,\varsigma}[\mu]) &\leq \frac{1}{2(\sigma^{-1/2} - \varsigma^{-1/2})} \left[\cE(\nu) - \cE(\hat{P}_{\tau,\varsigma}[\mu])  - \frac{W_{L_-^{\sigma,\varsigma}}(\nu,\hat{P}_{\tau,\varsigma}[\mu])}{\sqrt{\sigma}}\right]\\
&\qquad + \frac{n\ln(\sigma/\varsigma)}{4(\sigma^{-1/2} - \varsigma^{-1/2})} + \frac{n\sqrt{\varsigma}}{2}\,, \qquad \forall \varsigma \in [\tau,\sup I)\,. \label{eq:EVIL--GE-to-EVI}\tag{EVI\({}_{L_-}\)}
\end{align}
\end{prop}

\begin{proof}
The argument follows the same lines as the proof of the corresponding $L_0$ case Proposition \ref{prop:L0GE-to-EVI}, and we therefore omit the details. In a few words, one selects a $W_{L_-}$ geodesic connecting the measures appearing in the $\mathrm{EVI}$s, uses Lemma \ref{lem:wass-geodesic-smoothing} to smooth this geodesic so that \ref{lem:L-minus-action-entropy-est} can be applied, and then takes the limit in the smoothing parameter $\eps \to 0^+$ followed by the limit $\alpha\to 1^+$. It is perhaps worth noting that the action-$W_{L_-}$ difference integrands in the second lines of \eqref{eq:L-minus-preEVI-I}, \eqref{eq:L-minus-preEVI-II} vanish for $W_{L_-}$ geodesics, and both the action and $W_{L_-}$ distance between any two points along the smoothed curves are uniformly bounded and converge as $\eps \to 0^+$ by Lemma \ref{lem:wass-geodesic-smoothing} and \cite[Thm.~5.20]{Vil09}.
\end{proof}

\begin{prop}\label{prop:L-minus-entropy-cvx}
Assume that for any Borel probability measures $\mu,\nu \in \cP(M)$ and times $[\sigma,\tau] \subseteq I$, the backward heat flow $\hat P$ satisfies the $\mathrm{EVI}$s \eqref{eq:EVIL--GE-to-EVI}. Then for times $\sigma \leq \bar\eta \leq \tau$ with $[\sigma,\tau] \subseteq I$ and a $W_{L_-}$ geodesic $(\mu_{\eta})_{\eta \in [\sigma,\tau]}\subseteq \cP(M)$, the following entropy convexity statement holds:
\begin{align}\label{eq:L-minus-entropy-convexity}
&\phantom{-}\frac{\bar\eta^{-1/2} - \tau^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}(\cE(\mu_{\sigma}) + (n/2)\ln\sigma) + \frac{ \sigma^{-1/2} - \bar\eta^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}(\cE(\mu_{\tau}) + (n/2)\ln\tau) - (\cE(\mu_{\bar\eta }) + (n/2)\ln\bar\eta) \\
&- \frac{\bar\eta^{-1/2} - \tau^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}\Big(\sigma^{-1/2}W_{L_-^{\sigma,\bar\eta}}(\mu_{\sigma}, \mu_{\bar\eta})\Big) + \frac{ \sigma^{-1/2} - \bar\eta^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}\Big(\tau^{-1/2}W_{L_-^{\bar\eta,\tau}}(\mu_{\bar\eta}, \mu_{\tau})\Big) \geq 0\,.
\end{align}
\end{prop}

\begin{rmk}
As in Remark \ref{rmk:L0-entropy-alt-form}, the second line of \eqref{eq:L-minus-entropy-convexity} can be rewritten so that the inequality reads as an $(\eta^{-1/2})$-convexity statement for a single quantity. Indeed, if one writes $(\phi_\eta)_{\eta \in [\sigma,\tau]}$ the Kantorovich potentials for the pair of measures $(\mu_{\sigma},\mu_{\tau})$ given by Corollary \ref{cor:dynamic-potentials}, then

\begin{equation}
W_{L_-^{\bar{\sigma},\bar{\tau}}}(\mu_{\bar{\sigma}},\mu_{\bar{\tau}}) = \int_{M}\phi_{\bar{\tau}}d\mu_{\bar{\tau}} - \int_M\phi_{\bar{\sigma}}d\mu_{\bar{\sigma}}\,,\qquad \sigma \leq \bar{\sigma} \leq \bar{\tau} \leq \tau\,,
\end{equation}
and plugging in the above identity and regrouping terms gives

\begin{align}
&- \frac{\bar\eta^{-1/2} - \tau^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}\Big(\sigma^{-1/2}W_{L_-^{\sigma,\bar\eta}}^2(\mu_{\sigma}, \mu_{\bar\eta})\Big) + \frac{ \sigma^{-1/2} - \bar\eta^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}\Big(\tau^{-1/2}W_{L_-^{\bar\eta,\tau}}^2(\mu_{\bar\eta}, \mu_{\tau})\Big) \\
&= \frac{\bar\eta^{-1/2} - \tau^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}\sigma^{-1/2}\int_M \phi_{\sigma}\,d\mu_{\sigma} + \frac{ \sigma^{-1/2} - \bar\eta^{-1/2}}{\sigma^{-1/2} - \tau^{-1/2}}\tau^{-1/2}\int_M \phi_{\tau}\,d\mu_{\tau} - \bar\eta^{-1/2}\int_M \phi_{\bar\eta} \,d\mu_{\bar\eta}\,.
\end{align}
\end{rmk}

\begin{proof}
As in the proof of the $L_0$ version (Proposition \ref{prop:L0-entropy-cvx}), the argument consists of taking the normalized sum of the \eqref{eq:EVIL--GE-to-EVI}s applied respectively to the curves of measures $\left.(\mu_{\eta})_\eta\right|_{[\bar\eta,\tau]}$ resp. $\left.(\mu_{\eta})_\eta\right|_{[\sigma,\bar\eta]}$, then using the $W_{L_-}$ triangle inequality on the sum of Dini derivatives to obtain a lower bound of $0$. To avoid senseless redundancy we omit the details, but we do point out the cancellation of the $\sqrt{\bar\eta}$-dimensional terms with opposite signs in the respective \eqref{eq:EVIL--GE-to-EVI}s.
\end{proof}

\subsection{Characterizations for the \texorpdfstring{$L_+$}{L+} distance}\label{ss:L+}

There is a collection of equivalent conditions that is parallel to those of Theorem \ref{thm:L-charact}, but adapted to the $L_+$ distance--see Definition \ref{df:L+}. We do not include as many details as for the corresponding $L_-$ statements. This is for reasons of redundancy--the arguments are the same as for $L_-$ but with a handful of symbol and sign changes--and of external interest--$L_-$ is more useful in the study of partial regularity for the Ricci flow since it is adapted to blowing up on singularities that appear as one advances in (forward) time, and therefore receives much more attention in the literature. Nevertheless, let $t = T - \tau \in T - I =: \tilde I$ be a choice of forward time variable, then

\begin{thm}\label{thm:L+charact}
     Given $(M^n, g_t)_{t \in \tilde I}$ a smooth time-dependent Riemannian manifold of dimension $M = n$ and $\tilde I \subseteq (0,\infty)$, the following are equivalent:
    \begin{enumerate}
        \item $\mathcal{D}\geq 0$ ;
        \item Bochner formula: for every $v: M \to \R{}$ smooth and times $[s , t] \subseteq \tilde I$
        \begin{align}\label{eq:BochnerL+}
            (\partial_t-\Delta)\left( |\nabla P_{t,s}v|_t^2-2t\Delta_t P_{t,s}v - t^2S_t -\frac{n}{2}t \right) &\leq 0\,;\tag{B\({}_{L_+}\)}
        \end{align}
        \item Gradient estimate: for every $v$ smooth and times $[s , t] \subseteq \tilde I$
        \begin{align}\label{eq:GEL+}
            |\nabla P_{t,s}v|^2_t -2t\Delta P_{t,s}v - t^2S_t \leq P_{t,s}\left(|\nabla v|^2_s-2s\Delta v-s^2 S_s\right) + \frac{n}{2}(t-s)\,;\tag{GE\({}_{L_+}\)}
        \end{align}
        \item Wasserstein contraction: for every probability measures $\mu,\nu \in \cP(M)$, times $[s , t] \subseteq \tilde I$, and factor $1 < a <\sup \tilde I/t$,
        \begin{align}\label{eq:WCL+}
            W_{\Tilde{L}_+^{s,t}}(\hat P_{a s,s}\mu,\hat P_{a t,t}\nu) \leq W_{\Tilde{L}_+^{as,at}}(\mu,\nu) + \frac{n}{2}(a-1)(\sqrt{t}-\sqrt{s})^2\,;\tag{WC\({}_{L_+}\)}
        \end{align}
        \item Entropy convexity: for every $\nu_s,\nu_t \in \cP(M)$ and times $[s,t] \subseteq \tilde I$, there is a $W_{L_{+}^{s,t}}$-geodesic $(\nu_r)_{r \in [s,t]}$ (equivalently, for all such curves) such that
        \begin{align}
            r\mapsto \cE_r(\nu_r) - \cE_s(\nu_s) - \frac{1}{\sqrt{r}}W_{L_{+}^{s,r}}(\mu_{s},\mu_{r}) + \frac{n}{2}\ln(r/s)\ \ \text{is convex in the variable $r^{-1/2}$;}\tag{EC\({}_{L_+}\)}\label{eq:ECL+}
        \end{align}
        \item $\mathrm{EVI}$ characterization: for every $\mu,\nu \in \cP(M)$ and times $[s,t]\subseteq \tilde I$, the heat flow $\hat P_{t,s}\mu$ satisfies the $\mathrm{EVI}$s
        \begin{align}
            -a\cdot\partial_{a^-}^- W_{L_+^{a,t}}(\hat{P}_{s,a}\nu, \mu) &\leq \frac{1}{2(a^{-1/2} - t^{-1/2})} \left[\cE_t(\mu) -\cE_a(\hat{P}_{s,a}\nu) - \frac{W_{L_{+}^{a,t}}(\hat{P}_{s,a}\nu, \mu)}{\sqrt{t}} \right] \\
            &+\frac{n\ln(t/a)}{4(a^{-1/2} - t^{-1/2})} - \frac{n\sqrt{a}}{2}\,, \qquad \forall a \in (\inf \tilde I,s]\,.\\
            -b\cdot\partial_{b^-}^- W_{L_+^{s,b}}(\nu,\hat{P}_{t,b}\mu) &\leq \frac{1}{2(s^{-1/2} - b^{-1/2})} \left[\cE_s(\nu) - \cE_b(\hat{P}_{t,b})  + \frac{W_{L_+^{s,b}}(\nu,\hat{P}_{t,b}\mu)}{\sqrt{s}}\right]\\
            &+ \frac{n\ln(s/b)}{4(s^{-1/2} - b^{-1/2})} + \frac{n\sqrt{b}}{2}\,, \qquad \forall b \in (s,t]\,.\label{eq:EVIL+}\,\tag{EVI\({}_{L_+}\)}\\
    \end{align}
    \end{enumerate}
\end{thm}

\begin{rmk}
The entropy convexity statement \eqref{eq:ECL+} was introduced in \cite[Prop.~20]{Lot09} in the context of Ricci flows, where it was used to obtain a version of reduced volume monotonicity adapted to $L_+$. 
\end{rmk}

\section{Monotonicity of \texorpdfstring{$\cF$}{F} and \texorpdfstring{$\cW$}{W}}\label{s:FandW}

As a palate cleanser for the reader, we now provide a short application for the gradient estimates \eqref{eq:GEL0} and \eqref{eq:GEL-}. We first recall the $\cF$ functional and its scale-invariant sibling $\cW$ defined on a manifold $M$, given a smooth metric $g$ and function $S$ on $M$, a smooth measure $\mu = \rho \,dV$, and a (backwards) time $\tau$:

\begin{equation}
\cF(\mu,g,S) := \int_M (|\nabla f|^2 + S)\,d\mu \,,\qquad \cW(\mu,g,S,\tau) := \int_M [\tau(|\nabla f|^2 + S) + f - n]\,d\mu\,,
\end{equation}
where $f$ is defined via the reverse Gaussian formula $\rho = (4\pi\tau)^{-n/2}e^{-f}$. Recall that $\cF$, known as Fisher information in the static setting, is (up to sign) the derivative of the Boltzmann entropy along the adjoint heat flow. We will mainly be interested in the case when $g = g_\tau$ is time dependent, $S = \partial_\tau dV_g/dV_g$, and $\mu = \hat{P}_{\tau_1,\tau}[\mu_{\tau_1}]$. The main result is the following:

\begin{thm}\label{thm:F-W-monotonicity}
Suppose that $(M,g_\tau)_{\tau \in I}$ is a smooth family of Riemannian manifolds, $\tau_1 \in I$ is any time, and $\mu_{\tau_1} =\rho_{\tau_1\,dV_{\tau_1}} \in \cP(M)$ with $\rho_{\tau_1} \in C^\infty(M;(0,\infty))$ an initial measure with smooth positive density.

\begin{enumerate}
\item If $g$ satisfies the $L_0$ gradient estimate \eqref{eq:GEL0}, then 
\begin{equation}
[\tau_1,\infty)\cap I\ni\tau\qquad\mapsto \qquad\cF(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau, S_\tau)\,\qquad \text{is non-increasing. }
\end{equation}
\item If $g$ satisfies the $L_{-}$ gradient estimate \eqref{eq:GEL-} and $I\subseteq (0,\infty)$, then 
\begin{equation}
[\tau_1,\infty) \cap I\ni\tau \qquad\mapsto \qquad \cW(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau,S_\tau,\tau) \,\qquad \text{is non-increasing. }
\end{equation}
\end{enumerate}
\end{thm}

\begin{rmk}
One may view this argument as a version of \cite[Sec.~1.2]{Top09}, but without needing to pass through the intermediate \eqref{eq:WCL0}, \eqref{eq:WCL-} statements.
\end{rmk}

\begin{rmk}
We observe that $S$ need not be equal to $\partial_\tau\ln dV_\tau$ for the first conclusion to hold. It is enough to assume that \eqref{eq:GEL0} holds for the particular choice of function $S : I\times M \to \R{}$. Meanwhile the second conclusion uses $S \geq \partial_\tau dV_\tau/dV_\tau$ to ensure that $\tau \partial_\tau \cW \leq \partial_\tau (\tau^2 \cF - \tau n/2)$.)
\end{rmk}

\begin{proof}
\begin{enumerate}
\item Let us write the smooth measures $\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}] =: \rho_\tau \,dV_\tau$. We then compute by using integration by parts and duality of the forward and adjoint heat propagators
\begin{align}
\cF(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau, S_\tau) &= \int_M \left(|\nabla \ln\rho_\tau|^2 + S_\tau\right)\,d\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}] \\
&= \int_M \left(-|\nabla \ln\rho_\tau|^2 + S_\tau\right)\,d\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}] + \int_M 2|\nabla \ln\rho_\tau|^2\,\rho_\tau dV_\tau\\
&= \int_M \left(-|\nabla \ln\rho_\tau|^2 + S_\tau\right)\,d\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}] + \int_M 2\La\nabla \ln\rho_\tau,\nabla \rho_\tau\Ra\,dV_\tau\\
&= \int_M P_{\tau_1,\tau}\left[-2\Delta\ln\rho_\tau-|\nabla \ln\rho_\tau|^2 + S_\tau\right]\,d\mu_{\tau_1} \\
\end{align}
Using now \eqref{eq:GEL0}, again integration by parts, and then Young's inequality, we can continue with 
\begin{align}
\cdots&\leq \int_M \left[-2\Delta P_{\tau_1,\tau}[\ln \rho_\tau] - |\nabla P_{\tau_1,\tau}[\ln \rho_\tau]|^2 + S_{\tau_1}\right]\,d\mu_{\tau_1} \\
&=\int_M \left[ - |\nabla P_{\tau_1,\tau}[\ln \rho_\tau]|^2 + S_{\tau_1}\right]\,d\mu_{\tau_1} + 2\int_M \La \nabla P_{\tau_1,\tau}[\ln \rho_{\tau}], \nabla \rho_{\tau_1}\Ra\,dV_{\tau_1} \\
&= \int_M \left[ - |\nabla P_{\tau_1,\tau}[\ln \rho_\tau]|^2 + S_{\tau_1}\right]\,d\mu_{\tau_1} + 2\int_M \La \nabla P_{\tau_1,\tau}[\ln \rho_{\tau}], \nabla \ln\rho_{\tau_1}\Ra\,d\mu_{\tau_1} \\
&\leq \int_M \left[  |\nabla \ln \rho_{\tau_1}|^2 + S_{\tau_1}\right]\,d\mu_{\tau_1} = \cF(\mu_{\tau_1},g_{\tau_1}, S_{\tau_1})\,. \\
\end{align}
\item The second item proceeds similarly, so we do not highlight every step:
\begin{equation}
\tau^2\cF(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau, S_\tau) - \frac{n}{2}\tau = \int_M P_{\tau_1,\tau}\left[-2\tau\Delta (\tau\ln \rho_\tau) - |\nabla (\tau\ln \rho_{\tau})|^2 + \tau^2S_\tau - \frac{n}{2}\tau\right]\,d\mu_{\tau_1}
\end{equation}
We are set up to apply \eqref{eq:GEL-} to $\tau\ln\rho_\tau$, and we then proceed as before:
\begin{align}
\cdots &\leq \int_M \left[-2\tau_1\Delta P_{\tau_1,\tau}[\tau\ln \rho_\tau] - |\nabla P_{\tau_1,\tau}[\tau\ln \rho_\tau]|^2 + \tau_1^2S_{\tau_1} - \frac{n}{2}\tau_1\right]\,d\mu_{\tau_1} \\
&= \int_M \left[ - |\nabla P_{\tau_1,\tau}[\tau\ln \rho_\tau]|^2 + \tau_1^2S_{\tau_1} - \frac{n}{2}\tau_1\right]\,d\mu_{\tau_1} + 2\int_M \left\La \nabla P_{\tau_1,\tau}[\tau\ln \rho_{\tau}], \nabla (\tau_1\ln\rho_{\tau_1})\right\Ra\,d\mu_{\tau_1} \\
&\leq \int_M \left[  |\nabla (\tau_1\ln \rho_{\tau_1})|^2 + \tau_1^2S_{\tau_1} - \frac{n}{2}\tau_1\right]\,d\mu_{\tau_1} = \tau_1^2\cF(\mu_{\tau_1},g_{\tau_1}, S_{\tau_1}) - \frac{n}{2}\tau_1\,.
\end{align}
\end{enumerate}
We conclude that $\tau \mapsto \tau^2\cF(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau,S_\tau) -(n/2)\tau$ is non-increasing. To see that $\tau \mapsto \cW(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau,S_\tau,\tau)$ is also non-increasing, we use the just-concluded monotonicity and note (or rather Topping notes, see \cite[Sec.~1.2]{Top09}) that for any sufficiently smooth family of Riemannian manifolds, that need not (sub)solve any equation, 
\begin{equation}
\partial_\tau \cW(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau,S_\tau,\tau) = \frac{1}{\tau}\partial_\tau\left(\tau^2\cF(\hat{P}_{\tau_1,\tau}[\mu_{\tau_1}], g_\tau, S_\tau) -\frac{n}{2}\tau\right)\,.
\end{equation}
\end{proof}

\begin{rmk}
    With the same proof as in the $L_-$ case, we also have that under the $L_+$ gradient estimate \eqref{eq:GEL+} we recover the montonicity of the $\mathcal W_+$ entropy, which was first considered in \cite{Feldman-Ilmanen-Ni}.
\end{rmk}

\section{Dimensional inequalities for the \texorpdfstring{$L_0$}{L0} distance}\label{s:dimL0}
In this section we prove the following theorem, which characterizes flows satisfying $\cD\geq0$ and with an upper bound on the dimension. It is formulated in terms of backwards time, but this is simply a matter of preference.

\begin{thm}\label{thm:dimL0charact}
Given $(M,g_\tau)_{\tau \in I}$ a smooth, closed, time-dependent Riemannian manifold of arbitrary dimension, a real number $N \in [0,\infty)$, and $t \in \tilde I$ a choice of forward time variable, the following are equivalent:

\begin{enumerate}
\item $\cD \geq 0$ and $\dim M \leq N$;
\item Any one of conditions 2.-6. of both Theorem \ref{thm:L-charact} and Theorem \ref{thm:L+charact} holds for the shifted flows $(M,g_{\tau - T_0})_{\tau \in (I + T_0) \cap (0,\infty)}$ resp. $(M,g_{t - T_0})_{t \in (\tilde I + T_0) \cap (0,\infty)}$ for all $T_0 \in \R{}$, with dimensional parameter $n := N$; 
\item Bochner inequality: for every $v:M\to\mathbb{\R{}}$ smooth, for every $[\sigma,\tau] \subseteq I$,
\begin{align} \label{eq:BochnerdimL0}
    (-\partial_\sigma - \Delta) \left(|\nabla P_{\sigma,\tau}v|_\sigma^2 + 2\Delta_\sigma P_{\sigma,\tau}v  -S_\sigma\right) \leq -\frac{2}{N}(S_\sigma - \Delta_\sigma P_{\sigma,\tau}v)^2\,;\tag{B\({}_{L_0,N}\)}
\end{align}
\item Gradient estimate: for every $v: M \to \R{}$ smooth, for every $[\sigma,\tau] \subseteq I$,
\begin{align} 
    |\nabla P_{\sigma,\tau}v|_\sigma^2 + 2\Delta_\sigma P_{\sigma,\tau}v - S_\sigma \leq P_{\sigma,\tau}(|\nabla v|_\tau^2 + 2\Delta_\tau v - S_\tau) - \frac{2}{N}\int_\sigma^\tau (|P_{\sigma,\eta}S_\eta - P_{\sigma,\eta}\Delta_\eta P_{\eta,\tau}v|^2)\,d\eta\,;\\\label{eq:GEdimL0}\tag{GE\({}_{L_0,N}\)}
\end{align}
\item Wasserstein contraction: for any probability measures $\mu,\nu \in \cP(M)$, for all times $\sigma,\tau,S,T \in I$ with $\sigma < \tau$, $S < T$, $\tau < T$, and $\sigma< S$, \noeqref{eq:WCdimL0}
\begin{align} \label{eq:WCdimL0}
    W_{\tilde L_0^{S,T}}(\hat{P}_{\sigma,S}\mu,\hat{P}_{\tau,T}\nu) \leq W_{\tilde L_0^{\sigma,\tau}}(\mu,\nu) + \frac{N}{4}\ln\left(\frac{T - \tau}{S - \sigma}\right)\big((T - S) - (\tau - \sigma)\big)\,, \tag{WC\({}_{L_0,N}\)}
\end{align}
where $W_{\tilde L_0^{\sigma,\tau}}$ is the Wasserstein distance with respect to the cost induced by $(\tau - \sigma)\mathcal{L}_0$. 
\end{enumerate}
\end{thm}

In view of Theorems \ref{thm:L0charact} and \ref{thm:L-charact}, there is a conspicuous absence of entropy convexity and $\mathrm{EVI}$-type conditions in Theorem \ref{thm:dimL0charact}. We partially fill this void with Theorem \ref{thm:dimL0EC/EVI}, which at least shows that the corresponding characterizations of Theorem \ref{thm:L-charact} have analogues phrased only in terms of the $L_0$ distance. However the question remains unanswered:

\begin{qu}
    What are (reasonable) time-shifting invariant entropy convexity and $\mathrm{EVI}$ statements that are equivalent to $\cD \geq 0$ and $\dim M \leq N$? Possibly one should make use of the R\'enyi entropy.
\end{qu}

\begin{thm}\label{thm:dimL0EC/EVI}
Given $(M^n,g_\tau)_{\tau\in I}$ smooth time-dependent Riemannian manifold of dimension $\dim M = n$ and $I \subseteq (0,\infty)$, the following are equivalent:
\begin{enumerate}
\item $L_-$ characterizations: Any of the (equivalent) conditions of Theorem \ref{thm:L-charact}.
\item Dimensional $L_0$ entropy convexity: for every $\mu_\sigma,\mu_\tau \in \cP(M)$, $[\sigma,\tau]\subseteq I$, there is a $W_{L_0^{\sigma,\tau}}$ geodesic $(\mu_\eta)_{\eta\in[\sigma,\tau]}$ (equivalently, for all such curves) such that \noeqref{eq:ECdimL0}
\begin{align}
    \eta \mapsto \cE(\nu_\eta) - \cE(\nu_{\sigma}) + W_{L_0^{\sigma,\eta}}(\nu_{\sigma},\nu_\eta) + \frac{n}{8}(\ln(\eta/\sigma))^2 &- \int_{\sigma}^\eta \frac{1}{\tilde\eta}W_{L_0^{\sigma,\tilde\eta}}(\nu_{\sigma},\nu_{\tilde\eta})\,d\tilde\eta\\
    &\text{is convex in the variable $\ln\eta$;}\label{eq:ECdimL0}\tag{EC\({}_{L_0,n}\)}
\end{align}

\item Dimensional $L_0$ $\mathrm{EVI}$: for every $\mu,\nu \in \cP(M)$ and times $[\sigma,\tau] \subseteq I$, the heat flow $\hat P_{\sigma,\tau}\mu$ satisfies the EVIs: \noeqref{eq:EVIdimL0}
\begin{align}
 \eta\cdot\partial_{\eta^+}^+ W_{L_0^{\eta,\tau}}(\hat{P}_{\sigma,\eta}[\nu], \mu) &\leq \frac{1}{\ln(\tau/\eta)} \left[\cE(\mu) -\cE(\hat{P}_{ \sigma,\eta}[\nu]) +W_{L_0^{\eta,\tau}}(\hat{P}_{\sigma,\eta}[\nu], d\mu) -\int_{\eta}^{\tau} \frac{1}{\tilde\tau}  W_{L_0^{\eta,\tilde\tau}}(\hat{P}_{\sigma,\eta}[\nu],\tilde{\nu}_{\tilde\tau})\,d\tilde\tau\right]\\
&\qquad + \frac{n\ln(\tau/\eta)}{8}\,,\qquad \forall\eta \in [\sigma,\tau)\,,\\
\varsigma\cdot \partial_{\varsigma^+}^+ W_{L_0^{\sigma,\varsigma}}(\nu,\hat{P}_{\tau,\varsigma}[\mu]) &\leq \frac{1}{\ln(\varsigma/\sigma)} \left[\cE(\nu) - \cE(\hat{P}_{\tau,\varsigma}[\mu]) - W_{L_0^{\sigma,\varsigma}}(\nu,\hat{P}_{\tau,\varsigma}[\mu]) -\int_{\sigma}^{\varsigma} \frac{1}{\tilde\tau}  W_{L_0^{\tilde{\tau},\varsigma}}(\tilde{\mu}_{\tilde\tau}, \hat{P}_{\tau,\varsigma}[\mu])\,d\tilde\tau\right]\\
&\qquad + \frac{n\ln(\varsigma/\sigma)}{8}\,,\qquad\forall\varsigma \in [\tau,\sup I)\,,\label{eq:EVIdimL0}\tag{EVI\({}_{L_0,n}\)}\\
\end{align}
where $(\tilde{\nu}_{\tau})_{\tau \in [\eta,\tau]}$ is any $W_{L_0^{\eta,\tau}}$-geodesic with endpoints $\hat{P}_{\sigma,\eta}[\nu]$ and $\mu$, while $(\tilde{\mu}_{\tau})_{\tau \in [\sigma,\varsigma]}$ is any $W_{L_0^{\sigma,\varsigma}}$-geodesic with endpoints $\nu$ and $\hat P_{\tau,\varsigma}[\mu]$.
\end{enumerate}
\end{thm}

\begin{rmk}
A similar addendum could be made to the $L_+$ characterizations of Theorem \ref{thm:L+charact}. However, since it is not even clear how useful the characterizations of Theorem \ref{thm:dimL0EC/EVI} are themselves--see Remark \ref{rmk:no-L0-reduced-vol}--we have not written it out.
\end{rmk}

For the remainder of the section, we assume that we have fixed $(M,g_\tau)_{\tau \in I}$ a smooth, closed, time-dependent Riemannian manifold (of arbitrary dimension, unless an assumption on the dimension is explicitly stated) and a choice of forward time variable $t: = T - \tau \in T - I =: \tilde I$.

\subsection{Dimensional \texorpdfstring{$L_0$}{L0} Bochner and dimensional \texorpdfstring{$L_0$}{L0} gradient estimate}\label{ss:nL0Bochner}
The following is a consequence of the Bochner identity of Proposition \ref{prop:DcondiffBochner}.
\begin{prop}
     The condition $\left\{\text{$\mathcal{D}\geq 0$ and $\dim M\leq N$}\right\}$ is equivalent to \noeqref{eq:BochnerdimL0-id-to-ineq}
    \begin{align}
        -(\partial_\tau + \Delta)(|\nabla v|^2 + 2\Delta v - S) \leq -\frac{2}{N}(S-\Delta v)^2 \,. \label{eq:BochnerdimL0-id-to-ineq}\tag{B\({}_{L_0,N}\)}
    \end{align}
    for any time $\tau\in I$, $v$ smooth solution of the heat flow at $\tau$.
\end{prop}
\begin{proof}
    The forward direction follows directly from \ref{prop:DcondiffBochner} and the Cauchy-Schwarz inequality for matrices. Vice versa, assume the above Bochner inequality holds, then using the Bochner identity from Proposition \ref{prop:DcondiffBochner} we get
    \begin{align}
        2|\mathcal{S}-\Hess v|^2 + \cD(-\nabla v) \geq \frac{2}{N}|S-\Delta v|^2.
    \end{align}
    Fix $(\sigma,p,V)\in I\times TM$, choose $v$ with $\nabla v(\sigma,p)=-V$, $(\Hess v -\cS)(\sigma,p) =\lambda g_\sigma$, then at $(\sigma,p)$ we have
    \begin{align}
        2(\dim M)\lambda^2 + \cD(V) \geq \frac{2(\dim M)^2}{N}\lambda^2.
    \end{align}
    For $\lambda=0$ we recover $\cD\geq0$, while for $\lambda\to\infty$ we get $(\dim M)/N\leq 1$.
\end{proof}

\begin{prop}
    The dimensional Bochner inequality for any $\tau \in I$, any smooth solutions $v$ to the heat equation at $\tau$
    \begin{align}
        -(\partial_\tau + \Delta)(|\nabla v|^2 + 2\Delta v - S) \leq -\frac{2}{N}(S-\Delta v)^2 \label{eq:BEL0N2} \tag{B\({}_{L_0,N}\)}
    \end{align}
    is equivalent to the dimensional gradient estimate
    \begin{align} 
    |\nabla P_{\sigma,\tau}v|_\sigma^2 + 2\Delta_\sigma P_{\sigma,\tau}v - S_\sigma \leq P_{\sigma,\tau}(|\nabla v|_\tau^2 + 2\Delta_\tau v - S_\tau) - \frac{2}{N}\int_\sigma^\tau (|P_{\sigma,\eta}S_\eta - P_{\sigma,\eta}\Delta_\eta P_{\eta,\tau}v|^2)\,d\eta\, \\ \label{eq:GEL0N2}\tag{GE\({}_{L_0,N}\)}
\end{align}
    for any smooth $v:M\to\R{}$.
\end{prop}
\begin{proof}
    $\implies$) Following the proof of Prop \ref{prop:L0gradestimate}, $\phi_\eta := |\nabla P_{\eta,\tau}v|_\eta^2 + 2\Delta_\eta P_{\eta,\tau}v - S_\eta$, we get
    \begin{align}
        \partial_\eta P_{\sigma,\eta}(\phi_\eta) = P_{\sigma,\eta}((\partial_\eta+\Delta)\phi_\eta) \geq \frac{2}{N}P_{\sigma,\eta}((S_\eta-\Delta P_{\eta,\tau}v)^2).
    \end{align}
    Integrating in $\eta\in[\sigma,\tau]$, and then using Jensen's inequality (with respect to the heat kernel measure)
    \begin{align} 
    P_{\sigma,\tau}(|\nabla v|_\tau^2 + 2\Delta_\tau v - S_\tau) 
    &\geq |\nabla P_{\sigma,\tau}v|_\sigma^2 + 2\Delta_\sigma P_{\sigma,\tau}v - S_\sigma + \frac{2}{N}\int_\sigma^\tau P_{\sigma,\eta}((S_\eta-\Delta P_{\eta,\tau}v)^2)\,d\eta \\
    &\geq |\nabla P_{\sigma,\tau}v|_\sigma^2 + 2\Delta_\sigma P_{\sigma,\tau}v - S_\sigma + \frac{2}{N}\int_\sigma^\tau (|P_{\sigma,\eta}S_\eta - P_{\sigma,\eta}\Delta_\eta P_{\eta,\tau}v|^2)\,d\eta \,.
    \end{align}

    $\impliedby$) Again, differentiating \eqref{eq:GEL0N2} at $\tau=\sigma$ we get back \eqref{eq:BEL0N2}.
\end{proof}


\subsection{Equivalence of dimensional Bochner inequalities}\label{ss:dimBochnerandL_}

We now show that \eqref{eq:BochnerdimL0-equiv-of-Bochners} is equivalent to the validity of \eqref{eq:BochnerL-} and \eqref{eq:BochnerL+} for all shifted flows $(M,g_{\tau - T_0})_{\tau \in (I + T_0) \cap (0,\infty)}$ resp. $(M,g_{t - T_0})_{t \in (\tilde I + T_0) \cap (0,\infty)}$. This is a consequence of the algebraic properties of these inequalities only, showing that all distinct dimensionally sensitive Bochner inequalities we might consider are actually equivalent, without any additional geometric/analytic assumptions. It also says that, if we consider all shifts, the $L_-$ Bochner inequality improves to a ``dimensionally improved'' $L_-$ $N$-Bochner inequality.

\begin{prop}\label{prop:updated-dim-Bochner-equiv}
    The following are equivalent:

\begin{enumerate}
    \item \label{item:dim-Boch-1} For any time $\tau_0 \in I$ and smooth solution to the heat equation $v$ at $\tau_0$, the $L_0$ $N$-Bochner inequality holds:
    \begin{equation}
        \left.(-\ptau - \Delta)\right|_{\tau = \tau_0}\Big(|\nabla v|^2 - 2\Delta v - S\Big) \leq -\frac{2}{N}(S + \Delta v)^2. \label{eq:BochnerdimL0-equiv-of-Bochners}\tag{B\({}_{L_0,N}\)}
        \end{equation}
    \item \label{item:dim-Boch-2} For any time $\tau_0 = T - t_0 \in I$, smooth solution to the heat equation $v$ at $\tau_0$, and shift $-T_- < \tau_0$, we have the $L_-$ Bochner inequality
    \begin{equation}
    \left.(-\ptau - \Delta)\right|_{\tau = \tau_0}\left(|\nabla v|^2 - 2(T_-+\tau)\Delta v - (T_-+\tau)^2 S + \frac{N}{2}(T_-+\tau)\right) \leq 0\,,
    \end{equation}
    and for any shift $T_+> - t_0$, the $L_+$ Bochner inequality
    \begin{equation}
    \left.(\partial_t - \Delta)\right|_{t = t_0} \left(|\nabla v|^2 - 2(T_+ + t)\Delta v - (T_+ +t)^2 S - \frac{N}{2}(T_+ + t)\right) \leq 0\,.
    \end{equation}
    \item \label{item:dim-Boch-3} For any time $\tau_0 = T - t_0 \in I$, smooth solution to the heat equation $v$ at $\tau_0$, and shift $-T_- < \tau_0$, we have the $L_-$ $N$-Bochner inequality
    \begin{equation}
    \left.(-\ptau - \Delta)\right|_{\tau = \tau_0}\left(|\nabla v|^2 - 2(T_-+\tau)\Delta v - (T_-+\tau)^2 S + \frac{N}{2}(T_-+\tau)\right) \leq -\frac{2}{N} \left( (T_-+\tau)S + \Delta v - \frac{N}{2} \right)^2\,,
    \end{equation}
    and for any shift $T_+ >  - t_0$, the $L_+$ $N$-Bochner inequality
    \begin{equation}
    \left.(\partial_t - \Delta)\right|_{t = t_0} \left(|\nabla v|^2 - 2(T_++t)\Delta v - (T_++t)^2 S - \frac{N}{2}(T_++t)\right) \leq -\frac{2}{N} \left( (T_++t)S + \Delta v + \frac{N}{2} \right)^2\,.
    \end{equation}
\end{enumerate}
\end{prop}

\begin{rmk}
In Proposition \ref{prop:updated-dim-Bochner-equiv}, $T_-,T_+$ are not required to satisfy any additional constraints with respect to $I$ resp. $\tilde I$. They correspond to a choice of time origin $\tau = -T_-$ resp. $t = -T_+$ which serves as the center for parabolic rescaling, but there is no need for the family $(M,g_\tau)$ to actually be defined there. 

In the manipulations below, one can also obtain the inequalities (\ref{item:dim-Boch-2},\ref{item:dim-Boch-3}) from \eqref{item:dim-Boch-1} when $t + T_+<0$ (resp. $\tau + T_-<0$), but theses cases are not needed to recover \eqref{item:dim-Boch-1}. Note also that $t + T_+ > 0$ (resp. $\tau + T_->0$) correspond to comparison with expanding (resp. shrinking) solitons within their intervals of definition and hence are the more geometrically relevant cases. Relatedly, $\cL_+$, $\cL_-$ are only well-defined in the cases of positive (shifted, forward resp. backwards) times.
\end{rmk}

\begin{proof}
\fbox{(\ref{item:dim-Boch-1}) $\implies$ (\ref{item:dim-Boch-3})}: We prove the $L_-$ $N$-Bochner inequality, the $L_+$ is analogous. For any $-T_- < \tau_0\in I$ we have

\begin{align}
    &(-\ptau-\Delta)|_{\tau=\tau_0} \left(|\nabla v|^2 - 2(T_-+\tau)\Delta v - (T_-+\tau)^2 S + \frac{N}{2}(T_-+\tau)\right) \\
    &= (-\ptau-\Delta)|_{\tau=\tau_0} \left(|\nabla v|^2 - 2(T_-+\tau_0)\Delta v - (T_-+\tau_0)^2 S \right) + \left(2\Delta v_{\tau_0} + 2(T_-+\tau_0) S_{\tau_0}\right) - \frac{N}{2} \\
    &= (-\ptau-\Delta)|_{\tau=\tau_0} \left(\left|\nabla \frac{v}{T_-+\tau_0}\right|^2 - 2\Delta \frac{v}{T_-+\tau_0} - S \right)(T_-+\tau_0)^2 + \left(2\Delta v_{\tau_0} + 2(T_-+\tau_0) S_{\tau_0}\right) - \frac{N}{2} \\
    &\leq -\frac{2}{N}\left( S_{\tau_0}+\Delta \frac{v_{\tau_0}}{T_-+\tau_0} \right)^2(T_-+\tau_0)^2 + 2\left(\Delta v_{\tau_0} + (T_-+\tau_0) S_{\tau_0}\right) - \frac{N}{2} \\ 
    &= -\frac{2}{N}\left( (T_-+\tau_0)S_{\tau_0}+\Delta v_{\tau_0} -\frac{N}{2} \right)^2
\end{align}
where we used the $L_0$ $N$-Bochner inequality applied to $\frac{v}{T_-+\tau_0}$. Since $-T_- < \tau_0$ were arbitrary we get it for any $-T_- < \tau_0\in I$.

\fbox{(\ref{item:dim-Boch-2}) $\implies$ (\ref{item:dim-Boch-1})}: Now, using the shifted $L_-$ Bochner:

\begin{align}
    &(-\ptau - \Delta)|_{\tau = \tau_0}\left(|\nabla v|^2 - 2\Delta v - S\right) \\
    &= \frac{1}{(T_-+\tau_0)^2}(-\ptau - \Delta)|_{\tau = \tau_0}\left(|\nabla v(T_-+\tau_0)|^2 - 2(T_-+\tau_0)\Delta \big((T_-+\tau_0)v\big) - (T_-+\tau_0)^2S\right) \\
    &= \frac{1}{(T_-+\tau_0)^2}(-\ptau - \Delta)|_{\tau = \tau_0}\left(|\nabla v(T_-+\tau_0)|^2 - 2(T_-+\tau)\Delta \big((T_-+\tau_0)v\big) - (T_-+\tau)^2S +\frac{N}{2}(T_-+\tau)\right) \\
    &\qquad -\frac{1}{(T_-+\tau_0)^2} \left( 2\Delta \big((T_-+\tau_0)v_{\tau_0}\big) + 2(T_-+\tau_0)S_{\tau_0} \right) + \frac{N}{2(T_-+\tau_0)^2} \\
    &\leq -\frac{2}{T_-+\tau_0} \left( \Delta v_{\tau_0} + S_{\tau_0} \right) + \frac{N}{2(T_-+\tau_0)^2} \\
    &= -\frac{2}{N} \left( \Delta v_{\tau_0} + S_{\tau_0}\right)^2 + \frac{2}{N}\left( \Delta v_{\tau_0} + S_{\tau_0} - \frac{N}{2(T_-+\tau_0)} \right)^2.
\end{align}
We get the $L_0$ $N$-Bochner inequality but with an additional error given by the (nonnegative) second addendum in the last line. In the case $\Delta v_{\tau_0} + S_{\tau_0}>0$, we can choose $T_- > -\tau_0$ such that the term vanishes and we recover the estimate.


Analogously, using the shifted $L_+$ Bochner inequality we get
\begin{align}
    (-\partial_\tau - \Delta)|_{\tau = \tau_0}\left(|\nabla v|^2 - 2\Delta v - S\right)&=(\partial_t - \Delta)|_{t = t_0}\left(|\nabla v|^2 - 2\Delta v - S\right) \\
    &\leq -\frac{2}{N} \left( \Delta v_{t_0} + S_{t_0}\right)^2 + \frac{2}{N}\left( \Delta v_{t_0} + S_{t_0} + \frac{N}{2(T_++t_0)} \right)^2.
\end{align}
Now we are able to get rid of the extra term when $\Delta v_{\tau_0} + S_{\tau_0} = \Delta v_{t_0} + S_{t_0}<0$. Finally, for the case $\Delta v_{\tau_0} + S_{\tau_0}=0$ we can use either of the two estimates and send $T_{\pm}\to\infty$. 
\end{proof}

\subsection{Duality of shifted gradient estimates and \texorpdfstring{$L_0$}{L0}-Wasserstein contraction for unrelated times}\label{ss:GEWCdualitydimL0}

Recall that \eqref{eq:WCL0} relates pairs of times $s < t$ and $s + h < t + h$ for $h > 0$, and was shown to be equivalent to \eqref{eq:GEL0} in Subsection \ref{ss:GEWCdualityL0}. In this subsection we again consider a Wasserstein contraction statement with respect to the $L_0$ cost, but now for pairs of times $(\sigma,\tau)$, $(S,T)$ that need not be additively related. While it would be natural to consider \eqref{eq:GEdimL0} as the gradient estimate dual to \eqref{eq:WCdimL0-GE-to-WC}, it will turn out to be more convenient to use (shifted) \eqref{eq:GEL-} and \eqref{eq:GEL+}. In view of Proposition \ref{prop:updated-dim-Bochner-equiv}, this choice has no logical impact. Let us give a name to the affine map relating the pairs of times: 

\begin{equation}
\xi:[\sigma,\tau] \to [S,T]\,,\qquad \xi(\eta) = \frac{\tau - \eta}{\tau - \sigma}S + \frac{\eta - \sigma}{\tau - \sigma}T\,.
\end{equation}

Here we will work with the normalized Lagrangian $\tilde{L}_0$ from \eqref{eq:L0action}. Computing the Hamiltonian, by Proposition \ref{prop:HLsemigroup}, for any Lipschitz $\phi: M \to \R{}$ we have
\begin{align}
    \partial_\eta Q^{S,\xi(\eta)}\phi 
    &= -\xi'(\eta) \widetilde{H}^{S,\xi(\eta)}(d Q^{S,\xi(\eta)}\phi,Q^{S,\xi(\eta)}\phi,\xi(\eta)) \\
    &= -\xi'\cdot\left(\frac{1}{2(T - S)}|\nabla Q^{S,\xi(\eta)} \phi|^2 - \frac{T - S}{2}S_{\xi(\eta)} \right)\,.
\end{align}

\begin{prop}\label{prop:WL0dim-contraction}
Suppose that the gradient estimates \eqref{eq:GEL-} and \eqref{eq:GEL+} with dimensional parameter $n := N$ hold for all shifts $(M,g_{\tau- T_0})_{\tau \in (I + T_0)\cap(0,\infty)}$ resp. $(M,g_{t- T_0})_{t \in (\tilde I + T_0)\cap(0,\infty)}$. Then for any times $\sigma,\tau,S,T \in I$ with $\sigma < \tau$, $S < T$, $\sigma < S$, and $\tau < T$, the following (dimensional) $W_{L_0}$ contraction along the adjoint heat flow for $\mu,\nu \in \cP(M)$ holds
    \begin{align}\label{eq:WCdimL0-GE-to-WC}\tag{WC\({}_{L_0,N}\)}
         W_{\tilde L_0^{S,T}}(\hat{P}_{\sigma,S}\mu,\hat{P}_{\tau,T}\nu) \leq W_{\tilde L_0^{\sigma,\tau}}(\mu,\nu) + \frac{N}{4}\ln\left(\frac{T - \tau}{S - \sigma}\right)\big((T - S) - (\tau - \sigma)\big)\,.
    \end{align}
\end{prop}

\begin{rmk}
    In the case of $S=\alpha\sigma$, $T=\alpha\tau$, $\alpha\geq1$, the statement says that
    \begin{align}\label{eq:WCdimL0-mult}
        \alpha\mapsto W_{\tilde L_0^{\alpha \sigma,\alpha \tau}}(\hat P_{\sigma,\alpha\sigma}\mu, \hat{P}_{\tau,\alpha\tau}\nu) - \frac{N}{4}\ln\left(\frac{\alpha\tau}{\alpha\sigma}\right)(\alpha\tau - \alpha \sigma) \ \ \ \text{is monotone non-increasing,}
    \end{align}
    which is reminiscent of \eqref{eq:WCL-}. Moreover, if we send $\sigma,\tau\to \infty$ keeping $\tau-\sigma$ and $S - \sigma = (\alpha - 1) \cdot \sigma$ fixed, the dimensional term vanishes. This may be thought of as \eqref{eq:WCL0} being a limiting version of \eqref{eq:WCdimL0-mult} when the (backward) time-origin gets sent to $\pm\infty$.
\end{rmk}


\begin{proof}
We will divide the argument based on a trichotomy for the four times under consideration. If $\tau - \sigma = T - S$, then we are in the case of additively related times, and one first obtains \eqref{eq:GEL0} by applying Proposition \ref{prop:updated-dim-Bochner-equiv} to the assumed gradient estimates, then recalls Proposition \ref{prop:GEtoWCL0}. We now consider the case $\tau - \sigma < T - S$, i.e. $\xi' = (T - S)/(\tau - \sigma) > 1$. By the assumed shifted \eqref{eq:GEL-} gradient estimates and the fact that $0 < (\xi')^{-1}(\xi(\eta)/\eta) < \xi(\eta) /\eta$, we may apply Corollary \ref{cor:L_GradEst_param} with parameter $\lambda := (\xi')^{-1}(\xi(\eta)/\eta)$ to obtain

\begin{align}\label{eq:etaGE}
&(|\nabla P_{\eta,\xi(\eta)}[v]|^2 - 2(\xi(\eta)/\xi')\Delta P_{\eta,\xi(\eta)}[v] - (\xi(\eta)/\xi')^2S_{\eta}) \\
&- (P_{\eta,\xi(\eta)}[|\nabla v|^2] - 2\xi(\eta)P_{\eta,\xi(\eta)}[\Delta v] - \xi^2(\eta)P_{\eta,\xi(\eta)}[S_{\xi(\eta)}
]) \leq \frac{N}{2}\frac{\xi^2(\eta)(1 - (\xi')^{-1})^2}{\xi(\eta) - \eta}\,.
\end{align}

As usual, it is enough to prove the statement for delta measures. Let $\gamma:[\sigma,\tau]\to M$ be the $L_0^{\sigma,\tau}$-geodesic from $x$ to $y$. In the spirit of the proof of Proposition \ref{prop:WL-contraction} we have
{\allowdisplaybreaks
\begin{align}
    W_{\tilde L_0^{S,T}}(\hat P_{\sigma,S}\delta_x, \hat P_{\tau,T}\delta_y) 
    &= \sup_\phi P_{\tau,T}Q^{S,T}\phi(\gamma_{\tau})-P_{\sigma,S}\phi(\gamma_{\sigma}) \\
    &=\sup_\phi \int_{\sigma}^{\tau}\partial_\eta P_{\eta,\xi(\eta)}Q^{S,\xi(\eta)}\phi(\gamma_\eta) d\eta \\
    &= \sup_\phi \int_{\sigma} ^{\tau} -\Delta P_{\eta,\xi(\eta)}Q^{S,\xi(\eta)} \phi(\gamma_\eta) + \xi' P_{\eta,\xi(\eta)}\Delta Q^{S,\xi(\eta)}\phi(\gamma_\eta) \\
    & \hspace{1cm}+ P_{\eta,\xi(\eta)}(\partial_\eta Q^{S,\xi(\eta)}\phi)(\gamma_\eta) + \left\langle \nabla P_{\eta,\xi(\eta)}Q^{S,\xi(\eta)}\phi(\gamma_\eta),\dot\gamma_\eta
    \right\rangle d\eta \\
    &\leq \sup_\phi \int_{\sigma} ^{\tau} -\Delta P_{\eta,\xi(\eta)}Q^{S,\xi(\eta)} \phi(\gamma_\eta) + \xi' P_{\eta,\xi(\eta)}\Delta Q^{S,\xi(\eta)}\phi(\gamma_\eta) \\
    & \hspace{1cm}+ \xi'P_{\eta,\xi(\eta)}\left(-\frac{1}{2(T - S)}|\nabla Q^{S,\xi(\eta)}\phi(\gamma_\eta)|^2 + \frac{T - S}{2}S_{\xi(\eta)}\right) \\
    & \hspace{1cm} + \frac{1}{2(\tau - \sigma)}|\nabla P_{\eta,\xi(\eta)}Q^{S,\xi(\eta)}\phi(\gamma_\eta)|^2 + \frac{\tau - \sigma}{2}|\dot\gamma_\eta|^2 d\eta \\
    &=\sup_\phi \int_{\sigma} ^{\tau} \frac{(T - S)\xi'}{\xi^2(\eta)}\Bigg[-(\xi(\eta)/\xi')\Delta P_{\eta,\xi(\eta)}\left(\frac{\xi(\eta)Q^{S,\xi(\eta)} \phi(\gamma_\eta)}{T - S}\right) \\
    & \hspace{1cm}+  \xi(\eta) P_{\eta,\xi(\eta)}\Delta \left(\frac{\xi(\eta)Q^{S,\xi( \eta)}\phi(\gamma_\eta)}{T-S}\right) \\
    & \hspace{1cm}+ P_{\eta,\xi(\eta)}\left(-\frac{1}{2}\left|\frac{\nabla \xi(\eta)Q^{S,\xi(\eta)}\phi(\gamma_\eta)}{T -S}\right|^2 + \frac{\xi^2(\eta)}{2}S_{\xi(\eta)}\right) \\
    & \hspace{1cm} + \frac{1}{2}\left|\frac{\nabla\xi(\eta) P_{\eta,\alpha \eta}Q^{S,\xi(\eta)}\phi(\gamma_\eta)}{T - S}\right|^2 \Bigg] + \frac{\tau - \sigma}{2}|\dot\gamma_\eta|^2 d\eta \\
    & \overset{\eqref{eq:etaGE}}{\leq} \sup_\phi \int_{\sigma}^{\tau}  \frac{(T - S)\xi'}{\xi^2(\eta)} \Bigg[ \frac{(\xi(\eta)/\xi')^2}{2}S_\eta + \frac{N}{4}\frac{\xi^2(\eta)(1 - (\xi')^{-1})^2}{\xi(\eta) - \eta} \Bigg] + \frac{\tau - \sigma}{2}|\dot\gamma_\eta|^2 d\eta \\
    &= (\tau - \sigma) \int_{\sigma}^{\tau} \frac{1}{2}|\dot\gamma_\eta|^2 + \frac{1}{2}S_\eta + (\tau -\sigma) \frac{N}{4}\frac{(\xi' - 1)^2}{\xi(\eta) - \eta} \,d\eta  \\
    & = \tilde{L}_-^{\sigma,\tau}(x,y) +  \frac{N}{4}((T - S) - (\tau - \sigma))\int_{\sigma}^{\tau}\frac{\xi' - 1}{\xi(\eta) - \eta}\,d\eta.
    \end{align}
}

Note that we occasionally made use of the identity $\xi' \equiv (T - S)/(\tau - \sigma)$ in the above computations. It now remains to rewrite the dimensional error term on the RHS of the above inequality in the desired form. Indeed, since $\eta\mapsto\xi(\eta) - \eta$ is affine and $\xi(\sigma) = S$, $\xi(\tau) = T$, we have

\begin{equation}
\int_{\sigma}^{\tau}\frac{\xi' - 1}{\xi(\eta) - \eta}\,d\eta =  \ln\left(\frac{\xi(\tau) - \tau}{\xi(\sigma) - \sigma}\right) = \ln\left(\frac{T - \tau}{S - \sigma}\right)\,.
\end{equation}

This gives \eqref{eq:WCdimL0-GE-to-WC} in the case where $T - S > \tau - \sigma$. The third case, where the strict inequality is flipped, follows from an analogous argument, but using instead an appropriately shifted \eqref{eq:GEL+}.
\end{proof}

We now turn to the reverse implication: that the dimensional Wasserstein contraction \eqref{eq:WCdimL0-GE-to-WC} implies any of the (equivalent by Proposition \ref{prop:updated-dim-Bochner-equiv}) shifted gradient estimates \eqref{eq:GEL-} and \eqref{eq:GEL+}. This essentially follows the pattern of the non-dimensional version (Proposition \ref{prop:L0-contraction-to-GE}), but using now \eqref{eq:WCdimL0-GE-to-WC} for multiplicatively related times.

\begin{prop}\label{prop:WCdimL0-implies-shifted-GE}
    Suppose that for every $\mu,\nu \in \cP(M)$ and times $\sigma,\tau,S,T \in I$ with $\sigma < \tau$, $S < T$, $\sigma < S$, and $\tau < T$, the Wasserstein contraction \eqref{eq:WCdimL0-GE-to-WC} holds. Then we have the shifted $L_-$-type gradient estimate for times $[\sigma,\tau] \subseteq I$ with $-T_-< \sigma$,
        \begin{align}
            |\nabla P_{\sigma,\tau}v|^2_\sigma-2(\sigma + T_-)\Delta_\sigma P_{\sigma,\tau}v-(\sigma + T_-)^2S_{\sigma} \leq P_{\sigma,\tau}\left(|\nabla v|^2_\tau-2(\tau + T_-)\Delta_\tau v - (\tau + T_-)^2S_{\tau}\right) + \frac{N}{2}(\tau-\sigma)\,,
        \end{align}
    and the shifted $L_+$-type gradient estimate for times $[s,t] \in \tilde I$ with $- T_+ < s$,
        \begin{align}
            |\nabla P_{t,s}v|^2_t -2(t + T_+)\Delta_t P_{t,s}v - (t + T_+)^2S_t \leq P_{t,s}\left(|\nabla v|^2_s-2(s + T_+)\Delta_s v-(s + T_+)^2 S_s\right) + \frac{N}{2}(t-s)\,,
        \end{align}
        for any Lipschitz function $v: M \to \R{}$.
\end{prop}

\begin{proof}
    We show that the shifted $L_-$-type gradient estimates follow from the hypothesis; the shifted $L_+$-type gradient estimates follow in the same way (up to minor changes in notation and a few flipped signs). 

    We first notice that the assumed $W_{\tilde{L}_0}$ contraction is invariant under shifting the family $(M,g_{\tau - T_-})_{\tau \in I +T_-}$, so there is no loss in generality in assuming that $T_- = 0$. For any given $x,y \in M$, $[\bar{\sigma}, \bar{\tau}] \subseteq I$, $\alpha > 1$, let $\bar\gamma:[\bar{\sigma},\bar{\tau}]\to M$ be a curve from $x$ to $y$, and define $[\bar{\sigma},\bar{\tau}]\ni \varsigma \mapsto \hat{P}_{\varsigma,\alpha \varsigma}\delta_{\bar\gamma_\varsigma} =: \mu_\varsigma$ which is a curve of probability measures from $\hat{P}_{\bar{\sigma},\alpha \bar{\sigma}}\delta_{\bar\gamma_{\bar{\sigma}}}$ to $\hat{P}_{\bar{\tau},\alpha\bar{\tau}}\delta_{\bar\gamma_{\bar{\tau}}}$. 
    Using Lemma \ref{lem:dynamiclifting} we can find $\eta \in \mathcal{P}(C([\alpha\bar{\sigma},\alpha\bar{\tau}]\to M))$ with $(e_\varsigma)_\#\eta = \mu_\varsigma$ and
    \begin{align}\label{eq:liftingwithsameKE-again}
        \frac{1}{2}\int_{C([\alpha\bar{\sigma},\alpha\bar{\tau}]\to M)} |\dot{\gamma}_\varsigma|_{\varsigma}^2 + S_{\varsigma}(\gamma_\varsigma) d\eta(\gamma) = (\dot{\mu}_\varsigma)_{L_0^{\varsigma}}.
    \end{align}
    Hence
    {\allowdisplaybreaks
    \begin{align}
        P_{\bar{\tau}, \alpha\bar{\tau}}f(y)-P_{\bar{\sigma}, \alpha \bar{\sigma}}f(x) &= 
        \int f d\hat{P}_{\bar{\tau},\varsigma\bar{\tau}}\delta_{\bar\gamma_{\bar{\tau}}} - \int f d\hat{P}_{\bar{\sigma},\alpha\bar{\sigma}}\delta_{\bar\gamma_{\bar{\sigma}}} \\
        &= \int_{C([\alpha\bar{\sigma},\alpha\bar{\tau}]\to M)} \int_{\alpha\bar{\sigma}}^{\alpha\bar{\tau}} \langle df(\gamma_\varsigma), \dot{\gamma}_\varsigma\rangle d\varsigma d\eta(\gamma) \\
        & \leq \int_{C([\alpha\bar{\sigma},\alpha\bar{\tau}]\to M)} \int_{\alpha\bar{\sigma}}^{\alpha\bar{\tau}} \left(\frac{1}{2\alpha} |\nabla f(\gamma_\varsigma)|_{\varsigma}^2 + \frac{\alpha}{2}|\dot{\gamma}_\varsigma|_{\varsigma}^2\right) d\varsigma d\eta(\gamma) \\
        &= \frac{1}{2\alpha} \int_{C} \int_{\alpha\bar{\sigma}}^{\alpha\bar{\tau}} |\nabla f(\gamma_\varsigma)|_{\varsigma}^2 d\varsigma d\eta(\gamma) + \frac{\alpha}{2}\int_C\int_{\alpha\bar{\sigma}}^{\alpha\bar{\tau}}|\dot{\gamma}_\varsigma|_{\varsigma}^2 d\varsigma d\eta(\gamma) \\
        &= \frac{1}{2\alpha} \int_{\alpha\bar{\sigma}}^{\alpha\bar{\tau}} \int_M |\nabla f|_{\varsigma}^2 d\mu_\varsigma d\varsigma + \frac{\alpha}{2}\int_C\int_{\alpha\bar{\sigma}}^{\alpha\bar{\tau}}\left(|\dot{\gamma}_\varsigma|_{\varsigma}^2 + S_{\varsigma}(\gamma_\varsigma)\right) d\varsigma d\eta(\gamma) \\
        & \ \ \ \ - \frac{\alpha}{2}\int_{\alpha\bar{\sigma}}^{\alpha\bar{\tau}}\int_M S_{\varsigma}d\mu_\varsigma d\varsigma \\
        &= \frac{1}{2}\int_{\bar{\sigma}}^{\bar{\tau}} P_{\varsigma,\alpha\varsigma}[|\nabla f|_{\alpha\varsigma}^2](\bar\gamma_\varsigma) d\varsigma + \alpha^2\int_{\bar{\sigma}}^{\bar{\tau}}(\dot{\mu}_{\alpha\varsigma})_{L_0^{\alpha\varsigma}} d\varsigma \\
        & \ \ \ \ - \frac{\alpha^2}{2}\int_{\bar{\sigma}}^{\bar{\tau}}P_{\varsigma,\alpha\varsigma}[S_{\alpha\varsigma}](\bar\gamma_\varsigma)d\varsigma.
    \end{align}}
    We used Young's inequality, repeatedly the fact that $\mu_\varsigma =(e_\varsigma)_\#\eta$, and \eqref{eq:liftingwithsameKE-again} in the last equality.

    Now, taking $\lim_{\vartheta \to \varsigma}\frac{1}{(\vartheta - \varsigma)^2}$ of \eqref{eq:WCdimL0-GE-to-WC} for times $\varsigma, \vartheta,\alpha\varsigma, \alpha\vartheta$ gives
    \begin{align}
        \alpha^2(\dot{\mu}_{\alpha\varsigma})_{L_0^{\alpha\varsigma}} \leq (\dot{\delta}_{\bar\gamma_{\varsigma}})_{L_0^{\varsigma}} + \frac{N}{4\varsigma}(\alpha - 1) = \frac{1}{2}\left(|\dot{\bar\gamma}_{\varsigma}|_{\varsigma}^2 + S_{\varsigma}(\bar\gamma_{\varsigma}) \right)+ \frac{N}{4\varsigma}(\alpha - 1)\,.
    \end{align}
    Substituting in the previous estimate,
    \begin{align}
        P_{\bar{\tau},\alpha\bar{\tau}}f(y)-P_{\bar{\sigma},\alpha\bar{\sigma}}f(x)
        &\leq \frac{1}{2}\int_{\bar{\sigma}}^{\bar{\tau}} P_{\varsigma,\alpha\varsigma}(|\nabla f|_{\alpha\varsigma}^2)(\bar\gamma_\varsigma) d\varsigma + \frac{1}{2}\int_{\bar{\sigma}}^{\bar{\tau}}\left(|\dot{\bar\gamma}_\varsigma|_{\varsigma}^2 + S_{\varsigma}(\bar\gamma_\varsigma)\right) d\varsigma \\
        & \ \ \ \ - \frac{\alpha^2}{2}\int_{\bar{\sigma}}^{\bar{\tau}}P_{\varsigma,\alpha\varsigma}S_{\alpha\varsigma}(\bar\gamma_\varsigma) d\varsigma + \frac{N}{4}(\alpha - 1)\int_{\bar{\sigma}}^{\bar{\tau}}\frac{1}{\varsigma}\,d\varsigma\,.
    \end{align}
    In the estimate we have the freedom to choose $y$ and $\bar\gamma$ accordingly, and hence we pick $\bar\gamma$ to have $\dot{\bar\gamma}_{\bar{\sigma}}=\nabla P_{\bar{\sigma},\alpha\bar{\sigma}} [f](x)$. We now divide everything by $(\bar{\tau} - \bar{\sigma})$ and take the limit as $\bar{\tau}\downarrow \bar{\sigma}$. The left-hand side becomes 
    \begin{align}
        \partial_\varsigma|_{\varsigma=\bar{\sigma}} P_{\varsigma,\alpha\varsigma}[f](\bar\gamma_\varsigma) &= -\Delta P_{\bar{\sigma},\alpha\bar{\sigma}}[f](x) + \alpha P_{\bar{\sigma},\alpha\bar{\sigma}}[\Delta f](x) + \langle \nabla P_{\bar{\sigma},\alpha\bar{\sigma}}f(x),\dot{\bar\gamma}(\bar{\sigma}) \rangle \\
        &= -\Delta P_{\bar{\sigma},\alpha\bar{\sigma}}[f](x) + \alpha P_{\bar{\sigma},\alpha\bar{\sigma}}[\Delta f](x) + |\nabla P_{\bar{\sigma},\alpha \bar{\sigma}} f|^2_{\bar{\sigma}}(x)\,.
    \end{align}
    And comparing this with the right-hand side gives
    \begin{align}
        &\phantom{\leq}-\Delta P_{\bar{\sigma},\alpha\bar{\sigma}}[f](x) + \alpha P_{\bar{\sigma},\alpha\bar{\sigma}}[\Delta f](x) + |\nabla P_{\bar{\sigma},\alpha \bar{\sigma}} f|^2_{\bar{\sigma}}(x) \\ &\leq 
        \frac{1}{2} P_{\bar{\sigma},\alpha\bar{\sigma}}[|\nabla f|_{\alpha\bar{\sigma}}^2](x) + \frac{1}{2}\left(|\nabla P_{\bar{\sigma},\alpha\bar{\sigma}} [f]|_{\bar{\sigma}}^2(x) + S_{\bar{\sigma}}(x)\right) - \frac{\alpha^2}{2}P_{\bar{\sigma},\alpha\bar{\sigma}}[S_{\alpha\bar{\sigma}}](x)  + \frac{N(\alpha - 1)}{4\bar{\sigma}}\,.
    \end{align}
    We conclude
    \begin{equation}
        -\Delta P_{\bar{\sigma},\alpha\bar{\sigma}}[f] +\alpha P_{\bar{\sigma},\alpha\bar{\sigma}}[\Delta f] + \frac{1}{2} |\nabla P_{\bar{\sigma},\alpha\bar{\sigma}} [f]|^2_{\bar{\sigma}} \leq 
        \frac{1}{2} P_{\bar{\sigma},\alpha\bar{\sigma}}[|\nabla f|_{\alpha\bar{\sigma}}^2] + \frac{1}{2}S_{\bar{\sigma}} - \frac{\alpha^2}{2}P_{\bar{\sigma},\alpha\bar{\sigma}}[S_{\alpha\bar{\sigma}}]+ \frac{N(\alpha - 1)}{4\bar{\sigma}}\,.
    \end{equation}

    Picking now $\bar{\sigma} := \sigma$, $f := v/\sigma$, $\alpha := \tau/\sigma$, and multiplying the above line by $2\sigma^2$, we obtain the desired inequality.
\end{proof}

\subsection{Entropy \texorpdfstring{$\ln\tau$}{lnt}-convexity and \texorpdfstring{$\mathrm{EVI}$}{EVI}}\label{ss:nL0EC/EVI}

This subsection houses the proof of Theorem \ref{thm:dimL0EC/EVI}, showing that \eqref{eq:ECdimL0-EC-to-WC} and \eqref{eq:EVIdimL0-GE-to-EVI} are equivalent to \eqref{eq:GEL--GE-to-dimL0EVI}. Many features of this subsection have already been encountered in the $L_0$ and $L_\pm$ cases, so outside of Lemma and Proposition statements we provide details only when they differ from these previous cases. 

\begin{prop}\label{prop:dim-L0-convexity-implies-contraction}
Assume that $\dim M = n$ and $I \subseteq (0,\infty)$, and pick times $[\sigma,\tau] \subseteq I$. Suppose that for any measures $\mu_{\sigma},\,\mu_{\tau}\in \cP(M)$, there exists a $W_{L_0}$ geodesic $(\mu_{\eta})_{\eta \in [\sigma,\tau]}$ between $\mu_{\sigma},\mu_{\tau}$ such that

\begin{equation}\label{eq:ECdimL0-EC-to-WC}\tag{EC\({}_{L_0,n}\)}
\cE(\mu_\eta) - \cE(\mu_{\sigma}) + W_{L_0^{\sigma,\eta}}(\mu_{\sigma},\mu_\eta) + \frac{n}{8}(\ln(\eta/\sigma))^2 - \int_{\sigma}^\eta \frac{1}{\tilde\eta}W_{L_0^{\sigma,\tilde\eta}}(\mu_{\sigma},\mu_{\tilde\eta})\,d\tilde\eta
\end{equation}

is convex in the variable $\ln\eta$. Then for any $\mu_{\sigma}, \mu_{\tau} \in \cP(M)$ and $1 < \alpha < \sup I/\tau$, it holds that

\begin{align}\label{eq:WCdimL0-mult-times}
 \alpha W_{L_0^{\alpha\sigma, \alpha\tau}}(\hat{P}_{\alpha\sigma,\sigma}[\mu_{\sigma}], \hat{P}_{\alpha\tau,\tau}[\mu_{\tau}]) - \frac{n}{4}\alpha\ln\left(\frac{\tau}{\sigma}\right) \leq W_{L_0^{\sigma,\tau}}(\mu_{\sigma}, \mu_{\tau}) - \frac{n}{4}\ln\left(\frac{\tau}{\sigma}\right)\,.
\end{align}
\end{prop}


\begin{rmk}
The above Wasserstein contraction estimate \eqref{eq:WCdimL0-mult-times}, which is \eqref{eq:WCdimL0-GE-to-WC} in the special case of multiplicatively related times, implies \eqref{eq:GEL--GE-to-dimL0EVI}. This is precisely the content of the proof of Proposition \ref{prop:WCdimL0-implies-shifted-GE}.
\end{rmk}

\begin{proof}
The technical details--in particular the smoothing of the measures by flowing for some small time $\eps > 0$--are identical to those of the proof of Proposition \ref{prop:L0-cvxty-implies-contr/EVI}. We therefore restrict our attention to the formal computations, which all hold rigorously for endpoint measures that are smooth with full support.

Writing $d/d(\ln\eta) = \eta d/d\eta$ and letting $(\phi_\sigma,\phi_\tau)$ be Kantorovich potentials with respect to $L_0$ from $\mu_\sigma$ to $\mu_\tau$, by the convexity assumption we have
\begin{align}
-\frac{n}{4}\ln(\tau/\sigma)&\leq \left. \eta\frac{d}{d\eta}\left[\cE(\mu_\eta) + \int_M \phi_\eta \,d\mu_\eta\right]\right|_{\sigma^+}^{\tau^{-}} - W_{L_0^{\sigma,\tau}}(\mu_{\sigma}, \mu_{\tau}) \\
&= \left. \eta\frac{d}{d\eta}\left[\cE(\mu_\eta) + \int_M \phi_\eta \,d\mu_\eta\right]\right|_{\sigma^+}^{\tau^{-}} - \int_M\phi_{\tau}\,d\mu_{\tau} + \int_M \phi_{\sigma}\,d\mu_{\sigma}\,\,.
\end{align}

Note that the existence of these one-sided derivatives is provided by Lemma \ref{lem:Top-1-sided-est} and Proposition \ref{prop:Lisini-for-geodesics}, which as in Proposition \ref{prop:L0-cvxty-implies-contr/EVI} yields the further inequality (with $\mu_\eta=\rho_\eta dV_\eta$ for $\eta = \sigma,\tau$)
\begin{align}
\cdots &\leq  \left[-\eta\int_M \phi_\eta\Delta\rho_\eta \,dV_\eta -\int_{M}\phi_\eta\,d\mu_{\eta} - \eta\int_M \left(-\frac{|\nabla \phi_\eta|^2}{2} + \frac{S_\eta}{2}\right)\, d\mu_\eta\right]_{\sigma}^{\tau}\,.
\end{align}

Since $\phi_\eta$ (extended past $\tau$ using the Hopf-Lax semigroup) is Lipschitz and solves the Hamilton-Jacobi equation \eqref{eq:L0-HJ} a.e. in $M$ for $\eta = \sigma,\tau$, one computes

\begin{equation}
\cdots =-\left.\frac{d}{d\alpha}\right|_{\alpha = 1^+} \alpha\cdot\left[\int_{M} \phi_{\alpha\tau} d\hat{P}_{\alpha\tau,\tau}[\mu_{\tau}] - \int_{M} \phi_{\alpha\sigma} d\hat{P}_{\alpha\sigma,\sigma}[\mu_{\sigma}]\right]\,.
\end{equation}

Now, as in Proposition \ref{prop:L0-cvxty-implies-contr/EVI}, and modulo the technical details therein, this shows that 

\begin{equation}
\left.\partial^+\right|_{\alpha = 1^+} \left[\alpha\cdot W_{L_0^{\alpha\sigma, \alpha\tau}}(\hat{P}_{\alpha\sigma,\sigma}[\mu_{\sigma}], \hat{P}_{\alpha\tau,\tau}[\mu_{\tau}]) - \frac{n}{4}\ln(\tau/\sigma)\alpha\right] \leq 0\,,
\end{equation}
and thus that the quantity $\alpha\cdot W_{L_0^{\alpha\sigma, \alpha\tau}}(\hat{P}_{\alpha\sigma,\sigma}[\mu_{\sigma}], \hat{P}_{\alpha\tau,\tau}[\mu_{\tau}]) - (n/4)\alpha\ln(\tau/\sigma)$ is non-increasing in $\alpha > 1$.
\end{proof}

To pass now from gradient estimates \eqref{eq:GEL--GE-to-dimL0EVI} to the entropy convexity statement \eqref{eq:ECdimL0-EC-to-WC}, we also proceed as in the $L_0$ and $L_{-}$ cases.

\begin{lem}\label{lem:dim-L0-action-entropy-est}
Assume that $\dim M = n$ and $I\subseteq (0,\infty)$, and let $(\nu_\eta)_{\eta \in [\sigma,\tau]} = (\rho_\eta dV_\eta)_{\eta \in [\sigma,\tau]}$, $\rho \in C^\infty\big([\sigma,\tau]\times M; (0,\infty)\big)$, $[\sigma,\tau] \subseteq I$, be a curve of smooth measures with positive densities. For $\sup I/\tau,\tau/\sigma > \alpha > 1$, write $\lambda_I := \ln (\alpha)/\ln(\alpha\tau/\sigma)$, $\lambda_{II} := \ln(\alpha)/\ln\big(\tau/(\alpha\sigma)\big)$. Then if the $L_-$-type gradient estimate \eqref{eq:GEL--GE-to-dimL0EVI} holds, we have the action-entropy estimates
\begin{align}
\lambda_I\cE(\hat{P}_{\tau, \alpha\tau}[\nu_{\tau}]) + W_{L_0^{\sigma,\alpha\tau}}(\nu_{\sigma},\hat{P}_{\tau, \alpha\tau}[\nu_{\tau}]) &\leq \lambda_I\cE(\nu_{\sigma}) + (1 - \lambda_I) \int_{\sigma}^{\tau}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta \\
&\qquad -\lambda_I\int_{\sigma}^{\tau}\frac{1}{\eta}\left(\int_{\eta}^{\tau}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right)\,d\eta\\
&\qquad +\lambda_I\frac{n}{8}\big(\ln(\tau/\sigma)\big)^2  + O((\ln\alpha)^2)\,,\label{eq:dim-L0-preEVI-I}
\end{align}
and
\begin{align}
-\lambda_{II} \cE(\nu_{\tau}) + W_{L_0^{\alpha\sigma,\tau}}(\hat{P}_{\sigma,\alpha\sigma}[\nu_{\sigma}],\nu_{\tau}) &\leq -\lambda_{II} \cE(\hat{P}_{\sigma,\alpha\sigma}[\nu_{\sigma}]) + (1 + \lambda_{II})\int_{\sigma}^{\tau}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta \\
&\qquad - \lambda_{II}\int_{\sigma}^{\tau}\frac{1}{\eta}\left(\int_{\sigma}^{\eta}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde \eta}}\,d\tilde\eta\right)\,d\eta \\
&\qquad -\lambda_{II}\frac{n}{8}\big(\ln(\tau/\sigma)\big)^2 + O((\ln\alpha)^2)\,. \label{eq:dim-L0-preEVI-II}
\end{align}
The constant implicit in the $O((\ln\alpha)^2)$ error term depends on quantities that are independent of the curve $(\nu_\eta)_{\eta \in [\sigma,\tau]}$ (namely $\text{diam}_{L_0}((M,g_\eta)_{\eta \in [\sigma,\tau]}) $, $-\inf_{(\eta,x)\in I \times M} \min(0, S_\eta(x))$, $n$, $\tau$, $\sigma$), and on a uniform bound on the actions $\sup_{[\tilde\sigma,\tilde{\tau}]\subseteq [\sigma,\tau]} \left|\int_{\tilde\sigma}^{\tilde\tau}(\dot\nu_{\eta})_{L_0^\eta}\,d\eta\right|$.
\end{lem}
\begin{proof}
We proceed as in the proof of Lemma \ref{lem:L-minus-action-entropy-est}, but with even fewer details when the two proofs align. In this case, we consider the $\ln$-linear, bijective map of intervals $\xi_\alpha: [\sigma,\alpha\tau] \to [\sigma,\tau]$ given by

\begin{equation}
\xi_\alpha:\begin{cases}\xi_\alpha(\sigma) = \sigma\,,\,\xi_\alpha(\alpha\tau) = \tau\,,& \\ \ln(\xi_\alpha(\eta)) = (1 - \lambda) \cdot\ln(\eta) + b&\end{cases}\, \implies \lambda = \frac{\ln \alpha}{\ln(\alpha\tau/\sigma)}\,,\qquad b= \frac{\ln\sigma\cdot \ln\alpha}{\ln(\alpha\tau/\sigma)}\,.
\end{equation}

The two properties of $\xi_\alpha$ that will interest us are its values at the boundary of the interval, along with the ODE $\xi_\alpha'(\eta) = (1 - \lambda)\cdot \xi_\alpha(\eta)/\eta$ it solves. As in Lemma \ref{lem:L0-action-entropy-est}, we now define the ``diagonal'' curve of measures $\rho_{\eta,\alpha}\,dV_\eta := \nu_{\eta,\alpha} := \hat{P}_{\xi_{\alpha}(\eta),\eta}[\nu_{\xi_\alpha(\eta)}]$ for $\eta \in [\sigma,\alpha\tau]$, along with a family of Kantorovich potentials $(\phi_\eta)_{\eta \in [\sigma,\alpha\tau]}: M \to \R{}$ from Corollary \ref{cor:dynamic-potentials}, which are Lipschitz and solve the Hamilton-Jacobi equation \eqref{eq:L0-HJ} for every $\eta \in [\sigma,\alpha\tau]$ and a.e. $x \in M$. We compute

\begin{align}
\eta^{2}\partial_\eta \cE(\nu_{\eta,\alpha}) &= (1 - \lambda)\int_M P_{\xi_\alpha(\eta),\eta}[\eta\Delta_\eta \big(\eta\ln \rho_{\eta,\alpha}\big) - \frac{\lambda}{1 - \lambda} |\nabla\big(\eta\ln \rho_{\eta,\alpha}\big)|^2] \,d\nu_{\xi_\alpha(\eta)} \\
&\qquad - (1 - \lambda) \int_M \Big(\xi_\alpha(\eta)\Delta_{\xi_\alpha(\eta)}P_{\xi_\alpha(\eta),\eta}[\eta\ln \rho_{\eta,\alpha}]\Big)\,d\nu_{\xi_\alpha(\eta)} - \eta^{2}\int_M S_\eta\,d\nu_{\eta,\alpha}\\
&\qquad + (1 - \lambda)\int_M \xi_\alpha(\eta) P_{\xi_\alpha(\eta),\eta}[\eta\big(1 + \ln \rho_{\eta,\alpha}\big)]\left.\partial_\upsilon\right|_{\upsilon = \xi_\alpha(\eta)} \,d\nu_\upsilon\,,
\end{align}

and

\begin{align}
\eta^{2}\partial_\eta \int_M \phi_\eta \,d\nu_{\eta,\alpha} &= (1 - \lambda)\int_M P_{\xi_\alpha(\eta),\eta}[\eta\Delta_\eta (\eta\phi_\eta) - \frac{\lambda}{1 - \lambda}\La\nabla (\eta\phi_\eta), \nabla (\eta\ln \rho_{\eta,\alpha})\Ra +\frac{\eta^{2}}{2} S_{\eta} -\frac{1}{2}|\nabla (\eta\phi_\eta)|^2]\,d\nu_{\xi_\alpha(\eta)} \\
&\qquad - (1 - \lambda)\int_M\left(\xi_\alpha(\eta)\Delta_{\xi_\alpha(\eta)} P_{ \xi_\alpha(\eta),\eta}[\eta\phi_\eta] \right)\,d\nu_{\xi_\alpha(\eta)} + \lambda\int_M \frac{\eta^2}{2}S_\eta - \frac{1}{2}|\eta\nabla \phi_\eta|^2\,d\nu_{\eta,\alpha} \\
&\qquad + (1 - \lambda) \int_M \xi_\alpha(\eta)P_{\xi_\alpha(\eta),\eta}[\eta\phi_\eta]\left.\partial_\upsilon\right|_{\upsilon = \xi_\alpha(\eta)}\,d\nu_\upsilon\,.
\end{align}

We now verify the remaining steps from the proof of Lemma \ref{lem:L0-action-entropy-est}. In particular, we consider the linear combination $\eta^2\partial_\eta(\int_M \phi_\eta\,d\nu_{\eta,\alpha} + [\lambda/(1 -\lambda)]\cE(\nu_{\eta,\alpha}))$ of the LHS's above and attempt to estimate the terms of the resulting RHS. As in the dimensionless case, we define the auxiliary quantity $f_\eta: = \phi_\eta + \lambda\ln(\rho_{\eta,\alpha})/(1 - \lambda)$. 

First, similarly to the proof of Lemma \ref{lem:L0-action-entropy-est} we estimate

\begin{align}
&\phantom{\leq}(1 - \lambda)\int_M \xi_\alpha(\eta)P_{\xi_\alpha(\eta),\eta}[\eta f_\eta]\,\left.\partial_\upsilon\right|_{\upsilon = \xi_\alpha(\eta)}d\nu_\upsilon \\
&\leq \frac{1 - \lambda}{2}\int_M \Big(|\nabla P_{\xi_\alpha(\eta),\eta}[\eta f_\eta]|^2 - \xi_\alpha^2(\eta) S_{\xi_\alpha(\eta)}\Big)\,d\nu_{\xi_\alpha(\eta)} + \xi_\alpha(\eta)\eta\xi_\alpha'(\eta)(\dot{\nu}_{\xi_\alpha(\eta)})_{L_0^{\xi_\alpha(\eta)}}\,. 
\end{align}

Second, we apply the gradient estimate \eqref{eq:GEL--GE-to-dimL0EVI} with initial data $\eta f_\eta$ between the times $\xi_\alpha(\eta) < \eta$ to bound


\begin{align}
&(1 - \lambda)\int_M P_{\xi_\alpha(\eta),\eta}[\eta\Delta_\eta (\eta f_\eta) - \frac{1}{2}|\nabla (\eta f_\eta)|^2 + \frac{\eta^2}{2}S_\eta]\,d\nu_{\xi_\alpha(\eta)} \\
&\qquad - (1 - \lambda)\int_M\left(\xi_\alpha(\eta)\Delta_{\xi_\alpha(\eta)} P_{\xi_\alpha(\eta),\eta}[\eta f_\eta] -\frac{1}{2} |\nabla P_{\xi_\alpha(\eta),\eta}[\eta f_\eta]|^2 + \frac{\xi_\alpha^2(\eta)}{2}S_{\xi_\alpha(\eta)} \right)\,d\nu_{\xi_\alpha(\eta)} \\
&\leq \frac{n}{4}(1 - \lambda)( \eta - \xi_\alpha(\eta))\,.
\end{align}

We now assemble these two estimates as in Lemma \ref{lem:L0-action-entropy-est}, divide by $\eta^2$, and then integrate between $\sigma$ and $\alpha\tau$ to obtain

\begin{align}
(1 + \lambda)\int_M \phi_\eta \,d\nu_{\eta,\alpha} + \left.\frac{\lambda}{1 - \lambda}\cE(\nu_{\eta,\alpha}) \right|_{\sigma}^{\alpha\tau} &\leq \int_{\sigma}^{\alpha\tau}\frac{\xi_\alpha(\eta)}{\eta}(\dot{\nu}_{\xi_\alpha(\eta)})_{L_0^{\xi_\alpha(\eta)}}\xi_\alpha'(\eta)\,d\eta \\
&\qquad - \frac{\lambda^2}{1 - \lambda}\int_{\sigma}^{\alpha\tau}\int_M S_\eta \,d\nu_{\eta,\alpha}d\eta \\
&\qquad +\frac{n}{4}(1 - \lambda)\int_{\sigma}^{\alpha\tau}\left(\frac{1}{\eta} - \frac{\xi_\alpha(\eta)}{\eta^2}\right)\,d\eta \,.
\end{align}

Up to $O((\ln \alpha)^2)$ error, it remains to compute the first and third integrals of the RHS above. For the first, we integrate by parts to make the action of $\nu_\eta$ appear:

\begin{align}
\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\alpha\tau)}\frac{\bar\eta}{\xi_\alpha^{\circ - 1}(\bar\eta)}(\dot{\nu}_{\bar\eta})_{L_0^{\bar \eta}}\,d\bar \eta &= \frac{\xi_\alpha(\alpha\tau)}{\alpha\tau} \int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\alpha\tau)}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta+\frac{\lambda}{1 - \lambda}\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\alpha \tau)}\frac{1}{\xi_\alpha^{\circ-1}(\bar\eta)}\left(\int_{\xi_\alpha(\sigma)}^{\bar\eta}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right)\,d\bar\eta \\
&= \frac{1}{\alpha} \int_{\sigma}^{\tau}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta+\lambda\int_{\sigma}^{\alpha\tau}\frac{\xi_\alpha(\eta)}{\eta^2}\left(\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\eta)}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right)\,d\eta\,.\\
&=  \int_{\sigma}^{\tau}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta +\frac{1 - \alpha}{\alpha\ln(\tau/\sigma)}\int_{\sigma}^{\tau}\frac{1}{\eta}\left(\int_{\sigma}^{\tau}(\dot\nu_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right) d\eta \\
&\qquad +\lambda\int_{\sigma} ^{\alpha\tau}\frac{\xi_\alpha(\eta)}{\eta^2}\left(\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\eta)}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right)\,d\eta\,.\\
\end{align}
The final two terms of the RHS above can be combined, up to allowable error, to form the desired weighted action integral:
\begin{align}
&\phantom{=}\frac{1 - \alpha}{\alpha\ln(\tau/\sigma)}\int_{\sigma}^{\tau}\frac{1}{\eta}\left(\int_{\sigma}^{\tau}(\dot\nu_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right) d\eta +\lambda\int_{\sigma}^{\alpha\tau}\frac{\xi_\alpha(\eta)}{\eta^2}\left(\int_{\xi_\alpha(\sigma)}^{\xi_\alpha(\eta)}(\dot{\nu}_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right)\,d\eta \\
&= \frac{\ln \alpha}{\ln(\tau/\sigma)}\int_{\sigma}^{\tau}\frac{1}{\eta}\left(-\int_{\sigma}^{\tau}(\dot\nu_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta + \int_{\sigma}^{\eta}(\dot\nu_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right)\,d\eta+ O((\ln\alpha)^2) \\
&= -\frac{\ln \alpha}{\ln(\tau/\sigma)}\int_{\sigma}^{\tau}\frac{1}{\eta}\left(\int_{\eta}^{\tau}(\dot\nu_{\tilde\eta})_{L_0^{\tilde\eta}}\,d\tilde\eta\right)\,d\eta+ O((\ln\alpha)^2)\,.
\end{align}

Finally, we compute the $O(\ln\alpha)$ dimensional integral, whose $\ln\alpha$ coefficient is

\begin{align}
\lim_{\alpha \to 1^+}\frac{1}{\ln\alpha}\left(\frac{n}{4}(1 - \lambda)\int_{\sigma}^{\alpha\tau}\left(\frac{1}{\eta} - \frac{\xi_\alpha(\eta)}{\eta^2}\right)\,d\eta\right) &= \lim_{\alpha \to 1^+}\frac{n}{4}(1 - \lambda)\int_{\sigma}^{\tau}\frac{\alpha - 1}{\eta^2\ln\alpha}\frac{\eta - \xi_\alpha(\eta)}{\alpha - 1}\,d\eta \\
&= \frac{n}{4}\int_{\sigma}^{\tau}\frac{-\left.\partial_\alpha\right|_{\alpha = 1^+}\xi_\alpha(\eta)}{\eta^2}\,d\eta \\
&= \frac{n}{8}\ln(\tau/\sigma)\,,
\end{align}
since
\begin{equation}
\left.\partial_\alpha\right|_{\alpha = 1^+} \xi_\alpha(\eta) = \left.\partial_\alpha\right|_{\alpha = 1^+}\exp\left(\frac{\ln(\tau/\sigma)}{\ln(\alpha\tau/\sigma)}\ln \eta + \frac{\ln\sigma\cdot \ln \alpha}{\ln(\alpha\tau/\sigma)}\right) = \frac{\eta\ln(\sigma/\eta)}{\ln(\tau/\sigma)}\,.
\end{equation}

After multiplying through by $(1 - \lambda)$, this gives \eqref{eq:dim-L0-preEVI-I}. \eqref{eq:dim-L0-preEVI-II} follows from running the same argument (but with fewer steps for the action term) with $\nu_\eta^\alpha := \hat{P}_{\tilde{\xi}_\alpha(\eta),\eta}[\nu_{\tilde{\xi}_\alpha(\eta)}]$ for the range of times $[\alpha\sigma,\tau]$, where $\tilde{\xi}_\alpha: [\alpha\sigma,\tau] \to [\sigma,\tau]$ solves

\begin{equation}
\tilde{\xi}_\alpha(\tau): \begin{cases}\tilde{\xi}_\alpha(\alpha\sigma) = \sigma\,,\,\tilde{\xi}_\alpha(\tau) = \tau\,,&\\
\ln(\tilde{\xi}_\alpha(\eta)) = (1 + \tilde{\lambda})\cdot \ln\eta + \tilde{b}\end{cases}\,\implies \tilde{\lambda} = \frac{\ln \alpha}{\ln(\tau/(\alpha\sigma))}\,,\qquad \tilde b = -\frac{\ln\tau\cdot\ln \alpha}{\ln(\tau/(\alpha\sigma))}\,.
\end{equation}
\end{proof}

As with the dimensionless $L_0$ and $L_{\pm}$ cases, we can take a normalized sum of inequalities \eqref{eq:dim-L0-preEVI-I} and \eqref{eq:dim-L0-preEVI-II} applied along a $W_{L_0}$ geodesic, then send $\alpha \to 1^+$.

\begin{prop}\label{prop:dimL0GE-to-EVI}
Assume that $\dim M = n$, $I \subseteq (0,\infty)$, and that for any Lipschitz $v$, any $[\sigma,\tau] \subseteq I$ the gradient estimate

\begin{equation}
 |\nabla P_{\sigma,\tau}v|_\sigma^2-2\sigma \Delta_\sigma P_{\sigma,\tau}v-\sigma^2S_{\sigma} \leq P_{\sigma,\tau}\left(|\nabla v|_\tau ^2 - 2\tau\Delta_\tau v - \tau ^2S_{\tau}\right) + \frac{n}{2}(\tau-\sigma)\,.\label{eq:GEL--GE-to-dimL0EVI}\tag{GE\({}_{L_-}\)}
\end{equation}
holds. Then, for any Borel probability measures $\mu,\nu \in \cP(M)$ and times $[\sigma,\tau] \subseteq I$, the backward heat flow $\hat P$ satisfies the following $\mathrm{EVI}$s

\begin{align}
 \eta\cdot\partial_{\eta^+}^+ W_{L_0^{\eta,\tau}}(\hat{P}_{\sigma,\eta}[\nu], \mu) &\leq \frac{1}{\ln(\tau/\eta)} \left[\cE(\mu) -\cE(\hat{P}_{ \sigma,\eta}[\nu]) +W_{L_0^{\eta,\tau}}(\hat{P}_{\sigma,\eta}[\nu], d\mu) -\int_{\eta}^{\tau} \frac{1}{\tilde\tau}  W_{L_0^{\eta,\tilde\tau}}(\hat{P}_{\sigma,\eta}[\nu],\tilde{\nu}_{\tilde\tau})\,d\tilde\tau\right]\\
&\qquad + \frac{n\ln(\tau/\eta)}{8}\,,\qquad \forall\eta \in [\sigma,\tau)\,.\label{eq:EVIdimL0(1)}\\
\varsigma\cdot \partial_{\varsigma^+}^+ W_{L_0^{\sigma,\varsigma}}(\nu,\hat{P}_{\tau,\varsigma}[\mu]) &\leq \frac{1}{\ln(\varsigma/\sigma)} \left[\cE(\nu) - \cE(\hat{P}_{\tau,\varsigma}[\mu]) - W_{L_0^{\sigma,\varsigma}}(\nu,\hat{P}_{\tau,\varsigma}[\mu]) -\int_{\sigma}^{\varsigma} \frac{1}{\tilde\tau}  W_{L_0^{\tilde{\tau},\varsigma}}(\tilde{\mu}_{\tilde\tau}, \hat{P}_{\tau,\varsigma}[\mu])\,d\tilde\tau\right]\\
&\qquad + \frac{n\ln(\varsigma/\sigma)}{8}\,,\qquad\forall\varsigma \in [\tau,\sup I)\,.\label{eq:EVIdimL0-GE-to-EVI}\tag{EVI\({}_{L_0,n}\)}
\end{align}

Here, $(\tilde{\nu}_{\tau})_{\tau \in [\eta,\tau]}$ is any $W_{L_0^{\eta,\tau}}$-geodesic with endpoints $\hat{P}_{\sigma,\eta}[\nu]$ and $\mu$, while $(\tilde{\mu}_{\tau})_{\tau \in [\sigma,\varsigma]}$ is any $W_{L_0^{\sigma,\varsigma}}$-geodesic with endpoints $\nu$ and $\hat P_{\tau,\varsigma}[\mu]$.
\end{prop}

With Lemma \ref{lem:dim-L0-action-entropy-est}, the proof of Proposition \ref{prop:dimL0GE-to-EVI} proceeds very similarly to the $L_0$ case of Proposition \ref{prop:L0GE-to-EVI} and the $L_-$ case of Proposition \ref{prop:L-GE-to-EVI}, so we omit it. Similarly, the same method used to prove Propositions \ref{prop:L0-entropy-cvx} and \ref{prop:L-minus-entropy-cvx} in the $L_0$ resp. $L_-$ cases gives a corresponding dimensionally sensitive $L_0$ version.

\begin{prop}\label{prop:dim-L0-entropy-cvx}
Assume that $ \dim M = n$, $I \subseteq (0,\infty)$, and suppose that for any Borel probability measures $\mu,\nu \in \cP(M)$ and times $[\sigma,\tau] \subseteq I$, the backward heat flow $\hat P$ satisfies the $\mathrm{EVI}$s \eqref{eq:EVIdimL0-GE-to-EVI}. Then for times $ \sigma \leq \bar\eta \leq \tau$ with $[\sigma,\tau] \subseteq I$ and a $W_{L_0}$ geodesic $(\mu_{\eta})_{\eta \in [\sigma,\tau]}\subseteq \cP(M)$, the following entropy convexity statement holds:

\begin{align}\label{eq:dim-L0-entropy-convexity}
&\frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)}(\cE(\mu_{\sigma}) + (n/8)(\ln\sigma)^2) + \frac{ \ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}(\cE(\mu_{\tau}) + (n/8)(\ln\tau)^2) - (\cE(\mu_{\bar\eta }) + (n/8)(\ln\bar\eta)^2) \\
&\qquad - \frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)}W_{L_0^{\sigma,\bar\eta}}(\mu_{\sigma}, \mu_{\bar\eta}) + \frac{ \ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}W_{L_0^{\bar\eta,\tau}}(\mu_{\bar\eta}, \mu_{\tau}) \\
&\geq \frac{\ln (\bar\eta/\sigma)}{\ln(\tau/\sigma)}\int_{\bar\eta}^{\tau}\frac{W_{L_0^{\sigma,\eta}}(\mu_{\sigma},\mu_{\eta})}{\eta} \,d\eta +\frac{\ln (\tau/\bar\eta)}{\ln(\tau/\sigma)}\int_{\sigma}^{\bar\eta}\frac{W_{L_0^{\sigma,\eta}}(\mu_{\sigma},\mu_{\eta})}{\eta} \,d\eta\,,
\end{align}
and we recover \eqref{eq:ECdimL0}.
\end{prop}

\begin{rmk}\label{rmk:no-L0-reduced-vol}
    This convexity statement seems to be new even for Ricci flows. One might hope that by following the strategy of \cite[Cor.~8]{Lot09}, Theorem \ref{prop:dim-L0-entropy-cvx} would give rise to a new version of reduced volume monotonicity but now for the $L_0$ cost. However, the cited argument does not work here, as the convex quantity in Theorem \ref{thm:dimL0EC/EVI} does not tend to a constant as $\ln \eta \to -\infty$. This can be seen by noticing that all terms apart from $(n/8)(\ln\bar\eta)^2$ are $O(\ln \eta)$ as $\eta \to 0$. This consideration also shows that one cannot obtain the desired convergence as $\eta\to 0$ by simply adding an $\ln\eta$-convex function of $\eta$.
\end{rmk}

\begin{proof}
    Given a geodesic $(\mu_\eta)_{\eta\in[\sigma,\tau]}$, applying both \eqref{eq:EVIdimL0-GE-to-EVI}s and using the triangle inequality as in the proof of Proposition \ref{prop:L0-entropy-cvx} gives
    \begin{align}
        &\frac{1}{\ln(\tau/\bar\eta)}\left[ \cE(\mu_\tau)-\cE(\mu_{\bar\eta})+W_{L_0^{\bar\eta,\tau}}(\mu_{\bar\eta},\mu_\tau) - \int_{\bar\eta}^\tau \frac{1}{\eta}W_{L_0^{\bar\eta,\eta}}(\mu_{\bar\eta},\mu_\eta)d\eta \right] +\frac{n}{8}\ln(\tau/\bar\eta) \\
        &+ \frac{1}{\ln(\bar\eta/\sigma)}\left[  \cE(\mu_\sigma)-\cE(\mu_{\bar\eta})-W_{L_0^{\sigma,\bar\eta}}(\mu_\sigma,\mu_{\bar\eta}) - \int_\sigma^{\bar\eta} \frac{1}{\eta}W_{L_0^{\eta,\bar\eta}}(\mu_\eta,\mu_{\bar\eta})d\eta \right] + \frac{n}{8}\ln(\bar{\eta}/\sigma) \geq 0.
    \end{align}
    Multiplying by $\frac{\ln(\tau/\bar\eta)\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}>0$, and using the relation
    \begin{align}
        &\frac{\ln(\tau/\bar\eta)\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}\frac{n}{8}\left(\ln(\tau/\bar\eta)+\ln(\bar\eta/\sigma)\right) = \frac{n}{8\ln(\tau/\sigma)}\left( \ln^2\tau\ln(\bar\eta/\sigma)+\ln^2\sigma\ln(\tau/\bar\eta)-\ln^2\bar\eta\ln(\tau/\sigma) \right) \,,
    \end{align}
    yields
    \begin{align}
        &\frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)}(\cE(\mu_\sigma)+\frac{n}{8}\ln^2(\sigma)) + \frac{\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}(\cE(\mu_\tau)+\frac{n}{8}\ln^2(\tau)+W_{L_0^{\sigma,\tau}}(\mu_\sigma,\mu_\tau)) - (\cE(\mu_{\bar\eta})+\frac{n}{8}\ln^2(\bar\eta)+W_{L_0^{\sigma,\bar\eta}}(\mu_\sigma,\mu_{\bar\eta})) \\
        &\geq \frac{\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}\int_{\bar\eta} ^\tau \frac{1}{\eta}W_{L_0^{\bar\eta,\eta}}(\mu_{\bar\eta},\mu_\eta)d\eta + \frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)} \int_\sigma^{\bar\eta} \frac{1}{\eta}W_{L_0^{\eta,\bar\eta}}(\mu_\eta,\mu_{\bar\eta})d\eta
    \end{align}
    which is the claimed inequality. Now we note that for any $\sigma_0 \leq \sigma$ within the maximal interval of definition for $\mu_\eta$, we can rewrite the RHS as

\begin{align}
    &\phantom{=} \frac{\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}\int_{\bar\eta}^{\tau}\frac{1}{\eta}W_{L_0^{\bar\eta,\eta}}(\mu_{\bar\eta},\mu_\eta)\,d\eta + \frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)}\int_{\sigma}^{\bar\eta}\frac{1}{\eta}W_{L_0^{\eta,\bar\eta}}(\mu_\eta,\mu_{\bar\eta})\,d\eta +(1 - 1)\frac{\ln(\bar\eta/\sigma)\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)}W_{L_0^{\sigma_0,\bar\eta}}(\mu_{\sigma_0},\mu_{\bar\eta}) \\
    &= \frac{\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}\int_{\bar\eta}^{\tau}\frac{1}{\eta}W_{L_0^{\sigma_0,\eta}}(\mu_{\sigma_0},\mu_\eta)\,d\eta - \frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)}\int_{\sigma}^{\bar\eta}\frac{1}{\eta}W_{L_0^{\sigma_0,\eta}}(\mu_{\sigma_0},\mu_{\eta})\,d\eta \\
    &\qquad+ \left(\frac{\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)} + \frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)} - 1\right)\int_{\sigma_0}^{\bar\eta}\frac{1}{\eta}W_{L_0^{\sigma_0,\eta}}(\mu_{\sigma_0},\mu_\eta)\,d\eta \\
    &= \frac{\ln(\bar\eta/\sigma)}{\ln(\tau/\sigma)}\int_{\sigma_0}^{\tau}\frac{1}{\eta}W_{L_0^{\sigma_0,\eta}}(\mu_{\sigma_0},\mu_\eta)\,d\eta + \frac{\ln(\tau/\bar\eta)}{\ln(\tau/\sigma)}\int_{\sigma_0}^\sigma \frac{1}{\eta}W_{L_0^{\sigma_0,\eta}}(\mu_{\sigma_0},\mu_\eta)\,d\eta - \int_{\sigma_0}^{\bar\eta}\frac{1}{\eta}W_{L_0^{\sigma_0,\eta}}(\mu_{\sigma_0},\mu_\eta)\,d\eta\,.
\end{align}

Applying the resulting convex combination inequality for any triple of times in $[\sigma,\tau]$ with $\sigma_0 := \sigma$ shows that the function $\cE(\nu_\eta) - \cE(\nu_{\sigma}) + W_{L_0^{\sigma,\eta}}(\nu_{\sigma},\nu_\eta) + \frac{n}{8}(\ln\eta)^2 - \int_{\sigma}^\eta \frac{1}{\tilde\eta}W_{L_0^{\sigma,\tilde\eta}}(\nu_{\sigma},\nu_{\tilde\eta})\,d\tilde\eta$ is convex in $\ln\eta$, and thus so is the function in \eqref{eq:ECdimL0}, as they differ just by the term $-\frac{n}{4}\ln\eta\ln\sigma + \frac{n}{8}\ln^2\sigma$, which is $(\ln\eta)$-affine.

\end{proof}

\section{Extensions to smooth metric flows with a weight}\label{s:weight}

A natural generalization of a smooth metric flow $(M^m,g_t)_{t \in I}$ (i.e. a time-dependent Riemannian manifold) is a smooth metric-{\it measure} flow, where one additionally includes the data of a time-dependent weight $e^{-U_t}$ for a smooth family of smooth functions $U_t : M \to \R{}$. In this Section we write down a (``dimensionless'') $\cD_{U,\infty}$ condition adapted to this new setting, along with a ``dimensional'' $\cD_{U,N}$ condition. The latter includes a parameter $N \in [m,\infty]$, which may be thought of as the effective dimension of $(M^m,g_t, e^{-U_t}\,dV_t)_{t \in I}$--see Remark \ref{rmk:weighted-warped-prod-equiv} for a possible precise interpretation of this last statement. In terms of $(\cD \geq 0)$-type conditions, the quantities $\cD_{U,\infty}$ and $\cD_{U,N}$ are the time-dependent analogs of the Bakry-\'Emery-Ricci tensors $\Ric_{U} = \Ric_{U,\infty}$ resp. $\Ric_{U,N}$ in the static setting (see \cite[pg.~395]{Vil09}). We note here that a comparable extension to smooth metric-measure spaces was treated by Lott \cite[Sec.~8]{Lot09} in the setting of solutions to the Ricci flow.

In the remainder of the section, we assume that we have in hand a smooth time-dependent weighted Riemannian manifold $(M^m,g_t,\mathfrak{m}_t = e^{-U_t}\,dV_t)_{t \in I}$ with topological dimension $\dim M = m$. We also assume that we have picked a $T \in \R{}$ and made the corresponding choice of backwards time variable $\tau := T - t$ for $\tau \in T - I =: \tilde I$.

\subsection{The dimensionless case \texorpdfstring{$\cD_{U,\infty} \geq 0$}{DU0}.}\label{subsec:infinity-weighted}

As before, we write $\partial_tg_t=-2\mathcal{S}_t$, but now introduce $\partial_t \mathfrak{m}_t=-S_U\mathfrak{m}_t$, i.e. $S_U=\Tr_g{\mathcal{S}}+\partial_tU$. Let $\Delta_U=\Delta_g-\langle\nabla U,\nabla\cdot\rangle_g$ be the weighted Laplacian, $P_{t,s}^U$ the semigroup induced by it, with $ (P_{t,s}^U)^*$ its adjoint and $\hat{P}_{t,s}^U$ the backward semigroup for measures (see Subsection \ref{subsec:t-dep-mflds} for details in the unweighted case). In particular,
\begin{align}
    \partial_tP_{t,s}^Uv_t=\Delta_{U} P_{t,s}^Uv_s\,, \\
    \partial_sP_{t,s}^Uv_t = -P_{t,s}\Delta_{U}v_s\,.
\end{align}

As in the unweighted case, $\cD_{U,\infty}$ appears as the ambiguously signed term in Bochner formula for the (forward) heat equation associated to $\Delta_U$:

\begin{prop}\label{prop:weighted-BE-equiv}
    For any time $t \in I$ and smooth solution to the weighted heat flow $v_t=P_{t,s}^U v_s$ at $t$ we have the Bochner formula
    \begin{align}\label{eq:BochnerWeighted}
        (\partial_t-\Delta_U)(|\nabla v|^2 - 2\Delta_Uv - S_U)=-2|\Hess v+\mathcal{S}|^2  - \cD_{U,\infty}(\nabla v)\,,
    \end{align}
    where
    \begin{align}
        \cD_{U,\infty}(X)&:=2(\Ric_U-\mathcal{S})(X,X)+2\left\langle 2\div_U\mathcal{S} - \nabla S_U,X \right\rangle + \partial_t S_U- \Delta_U S_U-2|\mathcal{S}|^2 \,,\\
        \Ric_U&=\Ric+\Hess U\,,\qquad \div_U T :=\div T - T(\nabla U)\,.
    \end{align}
\end{prop}

\begin{rmk} Let us take a moment to record some basic considerations of the condition $\cD_{U,\infty} \geq 0$:
\begin{itemize}
    \item If the space is static, we recover the notion of nonnegative weighted Ricci curvature, i.e. $\Ric_{U} \geq 0$.
    \item If $d\mu_t \equiv d\mu_0$, then $S_U\equiv0$ and choosing $X=0$, the $\cD_{U,\infty}$ condition implies $\mathcal{S}=0$, hence the space must be static.
    \item If $U_t\equiv U_0$, one can replace $S_U=\Tr\mathcal{S}$ in the $\cD_{U,\infty}$ condition.
    \item If $g_t\equiv g_0$, it becomes
    \begin{align}
        \Ric_U(X,X)-\nabla_X\partial_tU + \frac{1}{2}(\partial_t - \Delta_U)\partial_tU \geq 0\,.
    \end{align}
    In particular, it must have nonnegative weighted Ricci curvature at every time and $\partial_t U$ must be a supersolution of the weighted heat flow. 
    \item Consider a new flow defined by $g_t =: (\Phi_t^{V})^*\tilde{g}_t$, where $\Phi_t^V$ is the time-dependent family of diffeomorphisms generated by $V := -\nabla U_t$. The diffeomorphism invariance of $\Ric$ allows us to rewrite the homogeneity $2$ term of $\cD_{U,\infty}$ as $\Ric_U - \cS = (\Phi_t^V)^*\big(\Ric_{\tilde{g}_t} - \tilde{\cS}\big)$, with the functorial notation $\tilde{\cS} = -\frac{1}{2}\partial_t \tilde{g}_t$. We note however that this absorption trick does not hold for the homogeneity $0$ and $1$ terms, therefore the $\cD_{U,\infty}$ condition for $g$ need not imply the (unweighted) $\cD$ condition for $\tilde{g}$. This is in contrast with the weighted Ricci flow setting--see \cite[Sec.~8]{Lot09}
\end{itemize}
\end{rmk}

Also as in the unweighted case, the $\cD_{U,\infty} \geq 0$ condition admits a familiar list of equivalent formulations. 

\begin{thm}
    For $(M,g_t,\mathfrak{m}_{t} = e^{-U_t}\,dV_t)_{t \in I}$ a smooth family of weighted Riemannian manifolds, the following conditions are equivalent:
    \begin{enumerate}
        \item $\cD_{U,\infty}\geq0$;    
        \item Bochner inequality: for every $v: M\to \R{}$ smooth, every $[s,t] \subseteq I$,
        \begin{align}
        (\partial_t-\Delta_{U,t})(|\nabla P_{t,s}^U v|^2_t - 2\Delta_{U,t} P_{t,s}^U v -S_{U,t}) \leq 0\,;
        \end{align}    
        \item Gradient estimate: For every $v: M \to \R{}$ smooth, every $[s, t] \subseteq I$,
        \begin{align}
               |\nabla P_{t,s}^Uv|_t^2 - 2\Delta_{U,t} P_{t,s}^Uv - S_{U,t}\leq P_{t,s}^U( |\nabla v|^2_s - 2\Delta_{U,s} v - S_{U,s})\,;
        \end{align}
        \item Wasserstein contraction: for every probability measure $\mu,\nu \in \cP(M)$, times $[s,t] \subseteq I$, and flow time $0 < h < \sup I - t$,
        \[W_{L_{U,0}^{s + h,t + h}}(\hat{P}_{s+h,s}^U\mu,\hat{P}_{t+h,t}^U\nu) \leq W_{L_{U,0}^{s,t}}(\mu,\nu).\]
        where $L_{U,0}^{a,b}$ is the cost induced by the Lagrangian $L_{U,0}(v,x,t):=(|v|_{g_t}^2+S_{U,t})(x)$ for $(v,x) \in TM$;
         \item Entropy convexity: for every $\mu_s,\mu_t\in P(M)$, $[s,t] \subseteq I$, there is a $W_{L_{U,0}^{s,t}}$-geodesic $(\mu_r)_{r\in[s,t]}$ (equivalently, for all such curves) s.t.
        \begin{align}
            r\mapsto \mathcal{E}(\mu_r\mid\mathfrak{m}_r) - \mathcal{E} (\mu_s\mid \mathfrak{m}_s) - W_{L_{U,0}^{s,r}}(\mu_s,\mu_r) \ \ \text{is convex,}
        \end{align}
        where $\cE(\mu\mid \mathfrak{m})$ is the relative entropy, i.e. $\cE(\mu\mid \mathfrak{m}) := \int_M \ln(d\mu/d\mathfrak{m})\,d\mu$ if $\mu \ll \mathfrak{m}$ and $+\infty$ otherwise;
        \item $\mathrm{EVI}$ characterization: for every $\mu,\nu \in \cP(M)$ and times $[s,t]\subseteq I$, the heat flow $\hat P_{t,s}^U\mu$ satisfies the $\mathrm{EVI}$s:
        \begin{align}
            -\partial_{a^-}^- W_{L_{U,0}^{s,a}}(\mu,\hat{P}_{t,a}^U\nu) & \leq \frac{1}{a-s}\left(\cE(\mu\mid\mathfrak m_s) - \cE(\hat{P}_{t,a}^U\nu\mid \mathfrak m_a) + W_{L_{U,0}^{s,a}}(\mu, \hat{P}_{t,a}^U\nu)\right) \,, \qquad \forall a \in (s, t]\,.\\
            -\partial_{b^-}^-W_{L_{U,0}^{b,t}}( \hat{P}_{s,b}^U\mu, \nu) & \leq \frac{1}{t - b}\left(\cE(\nu\mid\mathfrak m_t) - \cE(\hat{P}_{s,b}^U\mu \mid \mathfrak m_b) - W_{L_{U,0}^{b, t}}( \hat{P}_{s,b}^U\mu, \nu)\right) \,, \qquad\forall b \in (\inf I,s]\,.
        \end{align}
    \end{enumerate}
\end{thm}

With Proposition \ref{prop:weighted-BE-equiv} in hand, the proof of the above is, up to $U$ sub/superscripts, identical to that of the unweighted $L_0$ version Theorem \ref{thm:L0charact}. We therefore omit it.

\subsection{The dimensional case \texorpdfstring{$\cD_{U,N} \geq 0$}{DUN0}.}\label{subsec:N-weighted}

Here consider a version of Subsection \ref{subsec:infinity-weighted} that incorporates a dimensional parameter $N \in [m, \infty]$ (recall $m:= \dim M$). We first show the equivalence of a dimensional variant of the $\cD_{U,\infty}$ condition with a Bochner inequality for the (forward) $\Delta_U$ heat equation with dimensional improvement, which will be the analogue of \eqref{eq:BochnerdimL0-equiv-of-Bochners}, but now for weighted spaces. 

\begin{prop}\label{prop:weighted-n-BE-equiv}
The following conditions are equivalent:
\begin{enumerate}
\item For any $X \in T_pM$, it holds
\begin{equation}
\cD_{U,N}(X) := \cD_{U,\infty}(X) - \frac{2}{N - m}(\La\nabla U ,X\Ra - \partial_t U)^2 \geq 0\,.
\end{equation}
\item For any times $[s,t] \subseteq I$, one has the Bochner inequality
\begin{equation}
(\partial_t - \Delta_U)(|\nabla P_{t,s}^U v|^2 - 2\Delta_U P_{t,s}^U v - S_U) \leq - \frac{2}{N} (S_U + \Delta_U P_{t,s}^U v)^2\,.
\end{equation}
\end{enumerate}
\end{prop}

\begin{proof}
$(\underline{\implies})$: Letting $v_t=P_{t,s}^U v$, by Proposition \ref{prop:weighted-BE-equiv} and the assumption, we have the Bochner formula, then inequality
\begin{align}
(\partial_t - \Delta_U)(|\nabla v_t|^2 - 2\Delta_U  v_t - S_U) &= -2|\Hess v_t + \cS|^2 - \cD_{U,\infty}(\nabla v_t)\\
&\leq -2|\Hess v_t + \cS|^2  - \frac{2}{N - m}(\La\nabla U , \nabla v_t\Ra - \partial_t U)^2\,.
\end{align}
We estimate the desired RHS applying the Peter-Paul inequality
\begin{align}
\frac{2}{N}(S_U + \Delta_U v_t)^2 &= \frac{2}{N}(\Tr \cS + \partial_t U + \Delta v_t - \La \nabla U,\nabla v_t\Ra)^2\\
&= \frac{2}{N}\left[(\Tr \cS + \Delta v_t)^2 - 2(\Tr \cS + \Delta v_t)(\La \nabla U,\nabla v_t\Ra - \partial_t U) + (\La \nabla U,\nabla v_t\Ra - \partial_t U)^2\right] \\
&\leq \frac{2}{N}\left[(\Tr \cS + \Delta v_t)^2 + \frac{N - m}{m}(\Tr \cS + \Delta v_t)^2 + \frac{m}{N - m}(\La \nabla U,\nabla v_t\Ra - \partial_t U)^2 + (\La \nabla U,\nabla v_t\Ra - \partial_t U)^2\right] \\
&= \frac{2}{N}\left[\frac{N}{m}(\Tr \cS + \Delta v_t)^2 + \frac{N}{N - m}(\La \nabla U,\nabla v_t\Ra - \partial_t U)^2\right] \\
&= \frac{2}{m}(\Tr \cS + \Delta v_t)^2 + \frac{2}{N - m}(\La \nabla U,\nabla v_t\Ra - \partial_t U)^2 \\
&\leq 2|\cS + \Hess v_t|^2 + \frac{2}{N - m}(\La \nabla U,\nabla v_t\Ra - \partial_t U)^2
\end{align}
This, appended to the previous intermediate Bochner inequality, gives the desired result. \vspace{0.5cm}

$(\underline{\impliedby})$: For the point $(p,t) \in M\times I$ and a tangent vector $X \in T_pM$ of interest, select a function $v: M \to \R{}$ such that 
\begin{align}
(\Hess v)_p +\cS_p = \frac{ \partial_t U(p)-\La (\nabla U)_p, X\Ra}{N - m}g\,, \qquad(\nabla u)_p = X \,.
\end{align}
The assumption then implies

\begin{align}
-(\cD_{U,\infty})_p(\nabla v) - 2|\Hess v + \cS|^2(p) &=  \left.(\partial_t - \Delta_U)\right|_{t = s}(|\nabla P_{t,s}^Uv|^2 - 2\Delta_U P_{t,s}v - S_U)(p) \\
&\leq - \frac{2}{N} (S_U + \Delta_U v)^2(p) \\
&= -\frac{2}{N}(\Tr(\cS +  \Hess v) + \partial_t U - \La\nabla U,\nabla v\Ra )^2(p)\,.
\end{align}
Now rearranging and then remembering our choice of $v$, we obtain
\begin{align}
-(\cD_{U,\infty})_p(X) &\leq  2|\Hess v + \cS|^2(p) -\frac{2}{N}(\Tr(\cS + \Hess v) + \partial_t U - \La\nabla U,\nabla v\Ra )^2(p) \\
&= \left(2\frac{m}{(N - m)^2} - \frac{2}{N}\left(\frac{m}{N -m} + 1\right)^2\right)\left(\La (\nabla U)_p, X\Ra - \partial_t U(p)\right)^2 \\
&= -\frac{2}{N - m}(\La (\nabla U)_p, X\Ra - \partial_t U(p))^2\,.
\end{align}
\end{proof}

\begin{rmk}\label{rmk:weighted-warped-prod-equiv}
In the static setting the $(n+k)$ weighted Ricci tensor can be interpreted in terms of a warped product with a given $k$ manifold \cite{LottBakryEmery}, and a similar approach was used to define Ricci flow of weighted manifolds \cite{Lot09}. Here we study $\cD_{U,N}$ from this point of view. Fix a compact time-independent $k$-dimensional ``fiber'' manifold $(F^{k}, h)$, and consider the time-dependent warped product
\begin{equation}
(P, \tilde{g}_t) := (M,g_t) \times_{f_t} (F,h) = (M\times F, g_t + f_t^2\cdot h)\,,\qquad f_t := e^{-\frac{U_t}{k}}\,.  
\end{equation}
One can see that there is a bijection between $F$-invariant solutions to the heat equation on $(P,\tilde{g}_t)_{t \in I}$ and solutions to the weighted heat flow $(\partial_t - \Delta_U) u = 0$ on $(M, g_t, d\mu_t)_{t \in I}$, and in particular
    \begin{equation}
        \cD_{\tilde{g}}(X) =\cD_{g,U,m + k}(X) \qquad \text{for $X\in T_pM$}
    \end{equation} 
i.e. for horizontal tangent vectors $X \in T_pM \leq T_p M + T_q F \cong T_{(p,q)}P$. Indeed the $N$-dimensional $L_0$ Bochner inequality of Proposition \ref{prop:updated-dim-Bochner-equiv} for $F$-invariant functions on $(P,\tilde{g}_t)$ corresponds to the $(U,N)$-Bochner inequality of Proposition \ref{prop:weighted-n-BE-equiv} for $(M, g_t, d\mu_t)$.

Moreover, we have 
    \begin{equation}
        \cD_{\tilde{g}}(Z) \geq 0 \ \ \ \text{for all $Z \in T_{(p,q)}P$} \ \ \ \iff \ \ \ \begin{cases}
            \cD_{\tilde{g}}(X)=\cD_{g,U,m + k}(X)\geq0 \ \ \ &\text{for all $X\in T_pM$} \\
            \cD_{\tilde{g}}(Y) \geq 0 &\text{for all $Y\in T_qF$} \,.
        \end{cases}
    \end{equation} 
This follows from the fact that $\Ric_{\tilde{g}} - \cS_{\tilde{g}}$ splits orthogonally in the fiber and base directions and that $2\div_{\tilde g}(\cS_{\tilde g}) - \nabla^{\tilde g} S_{\tilde g}$ is everywhere tangent to $M$ (in fact this is true for both terms individually). Finally we compute

\begin{align}
\cD_{\tilde{g}}(Y) &= 2(\Ric_{\tilde{g}} - \cS_{\tilde{g}})(Y, Y) + (\partial_t S_{\tilde g} - \Delta_{\tilde g} S_{\tilde g} - 2|\cS_{\tilde g}|^2)\\
&= 2\left(\frac{\Ric_h(Y,Y)}{e^{-2U/k}} - \frac{1}{k}\left((\partial_t - \Delta_g) U + |\nabla^g U|^2\right)|Y|^2_{\tilde{g}}\right) \\
&\qquad + \left((\partial_t - \Delta_U)(\Tr_g\cS_g + \partial_t U) - 2|\cS_g|_g^2 - \frac{2}{k}|\partial_t U|^2\right)\,, \qquad Y\in T_qF\,.
\end{align}
Since there is no homogeneity $1$ term, $\cD_{\tilde{g}}(Y) \geq 0$ is seen to be equivalent to the non-negativity of the final two lines above. The non-negativity of the second term is already required for the $\cD_{\tilde{g}}$ condition in the horizontal direction, while the non-negativity of the first term requires $U$ to be a subsolution to a semilinear parabolic PDE on $(M,g_t)_{t \in I}$. The latter is guaranteed for example if $\Ric_h \geq \lambda > 0$, by replacing $U$ with $U + C$ for some constant $C = C(\lambda,k, \|U\|_{C^{2,1}}) \gg 1$.
\end{rmk}


The Bochner inequality of Proposition \ref{prop:weighted-n-BE-equiv} is the same (up to $U$ super/subscript notation) as the dimensional $L_0$ Bochner inequality \eqref{eq:BochnerdimL0}. Correspondingly, all statements equivalent to \eqref{eq:BochnerdimL0} by Theorem \ref{thm:dimL0charact} have weighted analogs that are equivalent to the conditions in Proposition \ref{prop:weighted-n-BE-equiv}. We write down this list of equivalent statements but omit the proof since it may be obtained directly from the proof of Theorem \ref{thm:dimL0charact}, which essentially spans multiple sections of this paper, by simply adding $U$ super/subscripts where appropriate. We also simply reference the relevant unweighted conditions and indicate the required modifications instead of rewriting all the conditions with the weighted quantities substituted, since the resulting statement would span multiple pages. 

\begin{thm}
Let $(M,g_t,\mathfrak m_t = e^{-U_t}\,dV_t)_{t\in I}$ be a smooth time-dependent weighted Riemannian manifold, and $N \in [\dim M, \infty]$ a real number. Fix a backward time variable $\tau := T - t \in T - I =: \tilde I$. Then the following conditions are equivalent.

\begin{enumerate}
\item $\cD_{U,N} \geq 0$.
\item Bochner inequality: The Bochner inequality $\eqref{eq:BochnerdimL0}$ holds, or equivalently the Bochner inequalities $\eqref{eq:BochnerL-}$ and $\eqref{eq:BochnerL+}$ hold on $(M,g_{\tau - T_0})_{\tau \in (\tilde I + T_0) \cap (0,\infty)}$ resp. $(M,g_{t - T_0})_{t \in (I + T_0) \cap (0,\infty)}$ for all shifts $T_0 \in \R{}$. 
\item Gradient estimate: The gradient estimate \eqref{eq:GEdimL0} holds, or equivalently the gradient estimates \eqref{eq:GEL-} and \eqref{eq:GEL+} hold on $(M,g_{\tau - T_0})_{\tau \in (\tilde I + T_0) \cap (0,\infty)}$ resp. $(M,g_{t - T_0})_{t \in (I + T_0) \cap (0,\infty)}$ for all shifts $T_0 \in \R{}$. 
\item Wasserstein contraction:  The Wasserstein contraction \eqref{eq:WCL0} holds, or equivalently the Wasserstein contractions \eqref{eq:WCL-} and \eqref{eq:WCL+} hold on $(M,g_{\tau - T_0})_{\tau \in (\tilde I + T_0) \cap (0,\infty)}$ resp. $(M,g_{t - T_0})_{t \in (I + T_0) \cap (0,\infty)}$ for all shifts $T_0 \in \R{}$. 
\item Entropy Convexity: The convexity of entropies \eqref{eq:ECL-} and \eqref{eq:ECL+} hold on $(M,g_{\tau - T_0})_{\tau \in (\tilde I + T_0) \cap (0,\infty)}$ resp. $(M,g_{t - T_0})_{t \in (I + T_0) \cap (0,\infty)}$ for all shifts $T_0 \in \R{}$. 
\item $\mathrm{EVI}$ characterization: The (pairs of) $\mathrm{EVI}$s \eqref{eq:EVIL-} and \eqref{eq:EVIL+} hold on $(M,g_{\tau - T_0})_{\tau \in (\tilde I + T_0) \cap (0,\infty)}$ resp. $(M,g_{t - T_0})_{t \in (I + T_0) \cap (0,\infty)}$ for all shifts $T_0 \in \R{}$.
\end{enumerate}

In all conditions referenced above, one must interpret $n := N$, $S := S_U$, $\Delta := \Delta_U$, $P := P^U$, $\hat P := \hat P^U$, $W_{L_0} := W_{L_{U,0}}$, $\cE_\tau(\mu) := \cE(\mu\mid \mathfrak{m}_\tau)$, $W_{L_-} := W_{L_{U,-}}$ with $L_{U,-}$ the cost induced by the Lagrangian $L_{U,-}(v,x,\tau) := \sqrt{\tau}(|v|^2_{g_\tau} + S_{U,\tau})(x)$, and $W_{L_+} := W_{L_{U,+}}$ with $L_{U,+}$ the cost induced by the Lagrangian $L_{U,+}(v,x,t) := \sqrt{t}(|v|^2_{g_t} + S_{U,t})(x)$.
\end{thm}

\begin{appendices}
\section{Properties of \texorpdfstring{$L^{s,t}$}{Lst}}\label{Appe:Lagrangian}

In this appendix, we always assume that we are working on a smooth, closed manifold $M$ equipped with a time dependent Lagrangian $L: TM \times [s,t]\to \R{}$ satisfying the assumptions of Section \ref{subsec:LagrangianProperties}.

\begin{lem}\label{lem:Eofgeod}
    Given $(x,s)$, $(y,t)$ there always exists (at least) a $C^1$ length minimizing curve $\gamma$ with $\cL(\gamma)=L^{s,t}(x,y)$.
    \end{lem}
\begin{proof}
    The existence of a minimizer can be proved by the direct method, see \cite[Thm.~6.1.2]{CanSin04}. A refined argument implies that $\dot\gamma_t$ is bounded and that $\gamma_t\in C^1$, \cite[Thm.~6.2.5]{CanSin04}.
\end{proof}

\begin{rmk}
    Note that in the case $L=L_m$, $m=0,-,+$, $L_m\in C^\infty(TM\times I)$, $\nabla_{v,v}L_m>0$, hence by \cite[Thm.~6.2.8]{CanSin04}, any minimizer is in fact smooth.
\end{rmk}

\begin{lem}\label{lem:costfromlagrangian}
    As $t\to s$, $L^{s,t}(x,\cdot)$ converges to $+\infty$ uniformly on any $B_r(x)^c$, $r>0$, and $L^{s,t}(x,x)$ converges to $0$.
\end{lem}

\begin{proof}
    Fix $r>0$, $d(x,y)>r$, let $\gamma$ be the minimizer for $L^{s,t}(x,y)$. By a change of variables $r(u)=u(t-s)+s$ and for $\tilde\gamma_u=\gamma_{r(u)}$, we have
    \begin{align}
        L^{s,t}(x,y) &= \int_s^tL(\dot\gamma_r,\gamma_r,r)dr \\
        &=\int_0^1 L(\dot\gamma_{r(u)},\gamma_{r(u)},r(u))(t-s)du \\
        &= \int_0^1 L(\dot{\tilde \gamma}_u/(t-s),\tilde\gamma_u,r(u))(t-s)du \\
        &\geq \int_0^1 \tilde\theta(|\dot{\tilde \gamma}_u|/(t-s))(t-s)du \\
        &\geq \int_0^1 \tilde\theta(|\dot{\eta}_u|/(t-s))(t-s)du \,.
    \end{align}
    In the first inequality we are used that there exists $\tilde\theta$ convex and superlinear, with $L(v,x,t)\geq \theta(|v|)-c_0\geq \tilde\theta(|v|)$. Convexity is used in the line below to apply Jensen's inequality, and $\eta$ is the constant speed reparametrization of $\tilde\gamma$. By superlinearity of $\tilde\theta$, the integral diverges as $(t-s)\to0$.

    For the case of $x=y$, we can choose the constant curve $\gamma\equiv x$ as competitor, and using continuity of $L$ in the second two variables
    \begin{align}
        L^{s,t}(x,x)\leq \int_s^t L(0,x,r)dr \leq \int_s^t C \to 0.
    \end{align}
    On the other hand, superlinearity also implies a lower bound on $L$
    \begin{align}
        L^{s,t}(x,x)=\inf_\gamma \int_s^t L(\dot\gamma_r,\gamma_r,r)dr \geq \inf_\gamma \int_s^t -C \to 0.
    \end{align}
\end{proof}

\begin{lem}\label{lem:cost-is-Lip}
    The induced cost $(t,x,y)\mapsto L^{s,t}(x,y)$ is locally Lipschitz in the space-time $(s,b]\times M\times M$ with respect to the background distance $d=d_g$ and the Euclidean distance in time. More precisely, for any compact interval $[s+\delta,b]$, there is $C>0$ such that for any $s+\delta \leq t_1\leq t_2\leq b$, $x,y_1,y_2\in M$, 
\begin{align}
    |L^{s,t_2}(x,y_2)-L^{s,t_1}(x,y_1)| \leq C(|t_2-t_1| + d(y_1,y_2)) \end{align}
\end{lem}
\begin{proof}
    Note that $|L^{s,t_2}(x,y_2)-L^{s,t_1}(x,y_1)| \leq |L^{s,t_2}(x,y_2)-L^{s,t_1}(x,y_2)| + |L^{s,t_1}(x,y_2)-L^{s,t_1}(x,y_1)|$, hence it is enough to prove the local Lipschitzianity for space and time separately, uniformly.

1) We show $L^{s,t_2}(x,y) \leq L^{s,t_1}(x,y) + C|t_s-t_1|$. Let $\gamma$ be a minimizer for $L^{s,t_1}(x,y)$, consider 
\begin{align}
    \eta(r)=\begin{cases}
    \gamma_r \ \ &s\leq r \leq t_1 \\
    y \ \ & t_1\leq r\leq t_2 \,.
\end{cases}
\end{align}
Then
\begin{align}
    L^{s,t_2}(x,y) &\leq \int_s^{t_2} L(\dot\eta,\eta,r)dr \\
    &= \int_s^{t_1} L(\dot\gamma,\gamma,r)dr + \int_{t_1}^{t_2}L(0,y,r) dr \\
    &\leq L^{s,t_1(x,y)} + C|t_2-t_1|.
\end{align}

2) We show $L^{s,t_1}(x,y) \leq L^{s,t_2}(x,y) + C|t_2-t_1|$. Let $\gamma$ minimize $L^{s,t_2}(x,y)$, and consider $\eta(r)=\gamma_{\theta(r)}=\gamma(s+(r-s)\frac{(t_2-s)}{(t_1-s)})$. Then, setting $\frac{t_2-s}{t_1-s}=1+\epsilon$
\begin{align}
    L^{s,t_1}(x,y) &\leq \int_s^{t_1}L(\dot\eta,\eta,r)dr \\
    &= \int_s^{t_2} L\left((1+\epsilon)\dot\gamma _{\theta} ,\gamma_\theta, s+(\theta-s)\frac{1}{1+\epsilon}\right)\frac{1}{1+\epsilon}d\theta \\
    &\leq \int_s^{t_2} L\left(\dot\gamma _{\theta},\gamma_\theta, \theta \right)+ |d_v L(\dot\gamma _{\theta},\gamma_\theta, \theta)| |\dot\gamma_\theta|\epsilon + |\partial_r L(\dot\gamma _{\theta},\gamma_\theta, \theta)| \epsilon(\theta-s) \\
    &\qquad +|L(\dot\gamma _{\theta},\gamma_\theta, \theta)|\epsilon + o(\epsilon) \\
    &\leq L^{s,t_2}(x,y) + C\epsilon \\
    &\leq L^{s,t_2}(x,y) + \frac{C}{t_1-s}(t_2-t_1).
\end{align}
Here we used that $|\dot\gamma_\theta|$ is bounded, see \ref{lem:Eofgeod}.

3) We show $L^{s,t}(x,y_1) \leq L^{s,t}(x,y_2) + Cd(y_1,y_2)$. Let $\gamma$ be a minimizer for $L^{s,t}(x,y_2)$, set $d=d(y_1,y_2)$ and assume $d \leq (b - s)/4$. First consider the case $t \leq (s + b)/2$. Then define $\eta:[s,t + d]\to M$ by 
\begin{align}
    \eta(r)= \begin{cases}
        \gamma_r \ \ \ &s\leq r \leq t \\
        \gamma^d_{r - t} & t\leq r\leq t + d
    \end{cases}
\end{align}
where $\gamma^d:[0, d]\to M$ is a geodesic for the background distance $d$ from $y_2$ to $y_1$ of constant unit speed. Then
\begin{align}
    L^{s,t+d}(x,y_1)\leq L^{s,t}(x,y_2)+\int_t^{t+ d}L(\dot\gamma,\gamma,r)dr \leq L^{s,t}(x,y_2) + C d.
\end{align}
Moreover, by step 2) $L^{s,t}(x,y_1) \leq L^{s,t+ d}(x,y_1) + C d\leq L^{s,t}(x,y_2) + 2Cd$ and we conclude. In the case $t \geq (s + b)/2$, passing from $y_1$ to $y_2$ should happen before time $t$; let $\tilde\gamma$ be instead a minimizer for $L^{s,t -d}(x,y_2)$ (note that $t - d \geq s + (b - s)/4$ is uniformly far from $s$) and define $\tilde\eta: [s,t] \to M$ by

\begin{align}
    \tilde\eta(r) = 
        \begin{cases}
            \tilde\gamma_r \ \ \ &s \leq r \leq t - d\,, \\
            \gamma^d_{r + d - t} &t - d\leq r \leq t\,,
        \end{cases}
\end{align}

with $\gamma^d$ as before. Then, similarly to the previous case, we combine the estimate $L^{s,t - d}(x,y_2) \leq L^{s,t}(x,y_2) + Cd$ from time-Lipschitzianity with the estimate $L^{s,t}(x,y_1) \leq L^{s,t - d}(x,y_2) + Cd$ from testing the definition of $L$ with $\tilde\eta$, to obtain $L^{s,t}(x,y_1) \leq L^{s,t}(x,y_2) + 2Cd$. If $d \geq (b - s)/4$, then a Lipschitz estimate amounts to a uniform bound on $|L^{s,t}(x,z)|$, which follows from compactness and the assumptions on $L$. 

\end{proof}


\begin{rmk}
    Analogous regularity holds when varying the initial space-time point $(x,s)$, but it would not hold for the $L_\pm$ case at $s=0$ (see also Remark \ref{rmk:LmaregoodLagr}). Nevertheless, we need only regularity in $(t,y)$ in the study of the (forward) Hopf--Lax semigroup.
\end{rmk}

\section{Regularity of the Hamilton-Jacobi equation}\label{Appe:HJ}
We first prove a statement that holds for general Lagrangians satisfying the assumptions of Section \ref{subsec:LagrangianProperties}., adapting the approach of Evans \cite[Ch.~3,~Thm.~6]{EvansPDE}.
\begin{prop}\label{prop:HLsemigroup}
    For any initial $\phi\in \mathrm{Lip}(M)$, the function $Q^{s,t}\phi(x):[s,b]\times M\to \R{}$ is Lipschitz in space-time. Moreover, $Q^{s,t}\phi$ solves the Hamilton-Jacobi equation at all differentiability points of $(t,x)\mapsto Q^{s,t}\phi(x)$
    \begin{align}
        \begin{cases}
            &\partial_tQ^{s,t}\phi(x) + H(d Q^{s,t}\phi(x),x,t) = 0 \,,\\
            &Q^{s,t}\phi \to \phi\qquad  \text{uniformly},
        \end{cases}
    \end{align}
    where $H:T^*M\times [a,b]\to\mathbb{R}$ is the Hamiltonian. 

    Moreover, for all points $(t,x)$ at which $Q^{s,t}\phi(x)$ is differentiable in $x \in M$, it is automatically also differentiable from the left in $t \in (s,b]$ and has Dini derivatives satisfying the Hamilton-Jacobi inequalities 

    \begin{equation}
        \partial_{t^\pm}^+Q^{s,t}\phi(x) \leq -H(dQ^{s,t}\phi(x),x,t) \leq \partial_{t^-}^-Q^{s,t}\phi(x)\,.
    \end{equation}
\end{prop}

\begin{proof}
    Consider $t_1,t_2> s$, $x,y\in M$, and let $z\in M$ be such that $Q^{s,t_1}\phi(x)=L^{s,t_1}(z,x)+\phi(z)$ (it exists by compactness of $M$ and continuity of $L^{s,t_1}(\cdot,x)$). Then
    \begin{align}
        Q^{s,t_2}\phi(y) - Q^{s,t_1}\phi(x) \leq L^{s,t_2}(z,y)-L^{s,t_1}(z,x) \leq C(|t_2-t_1|+d(x,y)), 
    \end{align}
    where the last inequality follows from Lipschitzianity of $L$ in space-time (by Lemma \ref{lem:cost-is-Lip}). 

    In order to show $Q^{s,t}\phi\to \phi$, note first that $\limsup_{t\to s}Q^{s,t}\phi(y)\leq \phi(y)$. Moreover, for every $r>0$ small, there is $\bar t$ sufficiently close to $s$ for which (by Lemma \ref{lem:costfromlagrangian}) for all $t\in(s,\bar t)$ we have
    \begin{align}
        Q^{s,t}\phi(y)=\inf_{x\in B_{r}} L^{s,t}(x,y)+\phi(x) \geq \phi(y)-C r.
    \end{align}
    Sending $r \to 0$ we get $\liminf_{t\to s}Q^{s,t}\phi \geq \phi$.

    We now show that if $x$ is a differentiability point of $x\mapsto u_t(x) := Q^{s,t}\phi(x)$, then Hamilton-Jacobi inequalities for the Dini derivatives are satisfied. The Hamilton-Jacobi {\it equality} (for the two-sided or left-sided derivative, depending on whether $Q^{s,t}\phi(x)$ is differentiable at $(t,x)$ or not) will then hold by combining the upper bound on $\partial_{t^\pm}^+u_t(x)$ and lower bound on $\partial_{t^-}^-u_t(x)$.

    $(\leq)$ For any $v\in T_xM$, consider for some $h>0$ a smooth curve $\gamma:[t - h,t]\to M$ with $\gamma_t = x$, $\dot\gamma_t=v$. Since $Q^{s,t}\phi=Q^{t - h,t}u_{t - h}$,
    \begin{align}
       u_t(x) - u_{t-h}(\gamma_{t-h}) &= \inf_y \left\{ L^{t - h,t}(y,x) + u_{t - h}(y) \right\} - u_{t - h}(\gamma_{t - h}) \\
       &\leq L^{t - h,t}(\gamma_{t-h},x).
    \end{align}
    Dividing by $h$ and as $h\to 0$, we get
    \begin{align}
        \partial_{t^-}^+ u_t(x) + du_t(x) (v)  \leq \lim_{h\downarrow 0}\frac{1}{h}L^{t - h,t}(\gamma_{t-h}, x) \leq \lim_{h\downarrow 0}\frac{1}{h}\mathcal L(\gamma) = L(v,x,t).
    \end{align}
    Hence
    \begin{align}
        \partial_{t^-}^+ u_t(x) + \sup_v \left\{ du_t(x) (v) - L(v,x,t) \right\} \leq 0
    \end{align}
    and the second addendum is exactly $L^*(du_t(x),x,t)=H(du_t(x),x,t)$. The inequality $\partial^+_{t^+}u_t \leq -H(du_t(x),x,t)$ follows similarly, but instead considering $\tilde\gamma:[t,t + h]\to M$ with $\tilde\gamma_t = x$, $\dot{\tilde\gamma}_t = v$.

    $(\geq)$ Let $z\in M$ s.t. $u_t(x)= L^{s,t}(z,x)+u_s(z)$. Let $\gamma:[s,t]\to M$ be the minimizing geodesic from $z$ to $x$. Then
    \begin{align}
        u_t(x)-u_{t-h}(\gamma_{t-h}) \geq L^{s,t}(z,x) - L^{s,t-h}(z,\gamma_{t-h}).
    \end{align}
    Divide by $h$ and send $h\downarrow 0$ to obtain
    \begin{align}
        \partial_{t^-}^- u_t(x) + du_t(x) (\dot\gamma_t) \geq L\left(\dot\gamma_t,x,t\right).
    \end{align}
    Hence
    \begin{align}
        0 &\leq \partial_{t^-}^- u_t(x) + \left( du_t(x) (\dot\gamma_t) - L\left(\dot\gamma_t,x,t\right) \right) \\
        &\leq \partial_{t^-}^- u_t(x) + \sup_v\left( du_t(x) (v) - L(v,x,t) \right) \\
        &= \partial_{t^-}^- u_t(x) +  H(du_t(x),x,t).
    \end{align}
\end{proof}

\begin{rmk}
    Following the computations of \cite[Sec.~7.4]{rf1}, one can see that the cost induced by $L$ itself satisfies the HJ equality. For the $L_-$ case, this equation can be found in \cite[pg.~15]{perelman2002entropy}.
\end{rmk}

In the case of centered, quadratic dependence of the Lagrangian in the velocity, one can obtain without too much fuss an a.e. equation for {\it every} time-slice. The following holds in much larger generality and is probably well-known to viscosity solution practitioners, but it was difficult to find a precise reference so we state and prove what we need. It will (only) be used for the implications of type $(\mathrm{EC}) \implies (\mathrm{WC})$.

\begin{prop}\label{prop:fiber-quadratic-HJ}
Given the hypotheses of Proposition \ref{prop:HLsemigroup}, assume further that $ L(\cdot,p,t) = A_{p,t}(\cdot, \cdot) + C_{p,t}$ is $C^2$ in all variables with $A_{p,t} \in T_p^*M\cdot T_p^*M$ and $C_{p,t}\in \R{}$ for each $(t,p) \in [s,b]\times M$. Suppose also that $\phi$ is semiconcave or semiconvex with quadratic modulus (see \cite[Def.~10.10]{Vil09}). Then for all points $(t,x) \in [s,b]\times M$ at which $Q^{s,t}\phi(x)$ is differentiable in $x \in M$, it is automatically also differentiable in $t$ and solves the Hamilton-Jacobi equation. In particular, the following holds (with derivatives taken from one side at the endpoints):

\begin{equation}
\partial_tQ^{s,t}\phi(x) + H(dQ^{s,t}(x),x,t) = 0\,,\qquad \forall t \in [s,b]\,,\text{ a.e. }x\in M\,.
\end{equation}
\end{prop}

\begin{proof}
In view of Proposition \ref{prop:HLsemigroup}, it remains to provide the lower bound $\partial_{t^+}^- Q^{s,t}(x) \geq -H(dQ^{s,t}\phi(x), x,t)$ for each $t \in [s,b)$, a.e. $x \in M$. The potential difficulty is in controlling the minimizers in the definition of the Hopf-Lax semigroup for $Q^{t, t+h}(Q^{s,t}\phi)(y_h)$ with $y_h \to x$ as $h \downarrow 0$, but the additional assumptions will provide local uniqueness of the minimizer assuming that $y_h$ approaches $x$ along a geodesic and $Q^{s,t}\phi(x)$ is regular enough at $x$.

Writing $u_t:= Q^{s,t}\phi: M \to \R{}$, by \cite[Thm.~6.4.3]{CanSin04} we have that $u_t$ is semiconcave (with quadratic modulus) for $t \in (s,b]$. Using this along with the assumed semiconcavity or semiconvexity of $u_s = \phi$, we have that for any given $t\in [s,b]$, $u_t$ is differentiable and admits a Hessian in the sense of Alexandrov at almost every $x\in M$ (see \cite[Thm.~14.1]{Vil09}) and we fix such a point. In particular, we have a symmetric linear operator $S: T_xM\to T_xM$ with 

\begin{equation}
u_t(\exp^{g_t}_x(v)) = u_t(x) + \La v,\nabla^{g_t}u_t(x)\Ra_{g_t} + \frac{\La S(v), v\Ra_{g_t}}{2} + o(|v|^2_{g_t}) \qquad \text{as }v\to 0\,.
\end{equation}

This would hold true for any fixed smooth metric $g_t$ near $x$, but the most accurate choice in this setting is $(g_t)_z := 2A_{z,t}$, with $A$ as in the hypothesis of the Proposition. On the other hand, we have 

\begin{align}
h\cdot L^{t,t + h}(y,z) &= \inf_{\stackrel{\gamma: [t,t+h]\to M}{\gamma_t = y,\,\gamma_{t + h} = z}} h\int_t^{t+h}L(\dot\gamma_s, \gamma_s, s)\,ds \\
&= \inf_{\gamma} h^2\int_0^1 L(\dot\gamma_{t + hs},\gamma_{t + hs}, t+ hs)\,ds \\
&= \inf_{\stackrel{\tilde{\gamma}:[0,1]\to M}{ \tilde\gamma_0 =y,\,\tilde\gamma_1 = z}}  \int_0^1 h^2L(\dot{\tilde{\gamma}}(s)/h, \tilde{\gamma}(s),t + hs)\,ds = \inf_{\tilde \gamma}  \int_0^1 L^h(\dot{\tilde{\gamma}}(s), \tilde{\gamma}(s),s)\,ds\,,
\end{align}

where we have written $L^h(v,p,s) := h^2L(v/h, p, t + hs)$. Note that by the additional assumption on the form of $L$, $L^h$ $C^2$-converges on $TM \times [0,1]$ to $L^0(v,p,s) := (1/2)\cdot |v|^2_{g_t(p)}$, so we also have $C^2$ convergence of the cost $h\cdot L^{t,t + h}(\cdot,z) \to (1/2)\cdot d^2_{g_t}(\cdot,z)$ on $B^{g_t}_{\mathrm{injrad}_{g_t}/2}(z)$. This last statement follows in the case under consideration because for $C^2$-converging Lagrangians $L(x,v,t)$ that additionally have $C^1$ convergence of $(\nabla_{v,v}^2L)$ and uniform convexity $(\nabla_{v,v}^2L) \geq \lambda > 0$, the geodesic equation involves only $C^1$-converging quantities and the Jacobi field equation involves only uniformly bounded quantities (in any fixed local coordinate system). This allows us to transfer the convexity of $d^2_{g_t}(\cdot, z)$ near $z$ to the $O(h^{-1})$ convexity of $L^{t,t + h}(\cdot, z)$,
\begin{align}
L^{t,t + h}(\exp^{g_t}_y(v),z) &- L^{t,t + h}(y,z)  - \La v,(\nabla^{g_t}L^{t,t +h}(\cdot, z))_y \Ra_{g_t} \\
&= \frac{\big((\nabla^2 d^2_{g_t}(\cdot, z))_y/2 + \Psi(h)\big)(v,v) + o(|v|_{g_t}^2)}{2h}\geq \frac{|v|_{g_t}^2}{4h}\,,
\end{align}
for any $z,y \in M$, $v \in T_yM$, whenever $h$, $\,d_{g_t}(y,z)$, $|v|_{g_t}$ are small enough. We now let $\gamma:[t,t + h] \to M$ be a (uniquely minimizing for $h$ small enough, by adapting \cite[pg.~2631]{KleLot08} to quadratic Lagrangians) $L^{t,t+h}$-geodesic with $\gamma_t = x$, $\dot\gamma_t = \nabla^{g_t} u_t(x)$. By \cite[Thm.~10.15]{Vil09}, and then the specific form of the Lagrangians under consideration, we also have $(\nabla^{g_t}L^{t,t +h}(\cdot, \gamma_{t + h}))_{\gamma_t} = -(\nabla_v^{g_{t}} L)(\gamma_t,\dot\gamma_t, t) = -\dot\gamma_t$. In particular, $(\nabla^{g_t}L^{t,t +h}(\cdot, \gamma_{t + h}))_x = -\nabla^{g_t}u_t(x)$.

Finally we can conclude by noting that for $h$, $d_{g_t}(x,\gamma_{t + h})$, $|v|_{g_t}$, small enough and $v \neq 0$, the second-order expansions for $u_t$ and $L^{t,t + h}(\cdot, \gamma_{t + h})$ near $x$ give
\begin{equation}
\big(L^{t,t+h}(\cdot,\gamma_{t + h}) + u_t\big)(\exp_x^{g_t}(v)) - \big(L^{t,t + h}(x,\gamma_{t + h}) + u_t(x)\big)\geq \frac{\La (S + I/2h)(v),v \Ra_{g_t}}{2} + o(|v_t|^2_{g_t}) > |v|_{g_t}^2 > 0\,.
\end{equation}
In particular, $L^{t,t+h}(\cdot,\gamma_{t + h}) + u_t$ achieves a unique minimum in a neighborhood of $x$, which is at $x$. By Lemma \ref{lem:costfromlagrangian} and boundedness of $u_t$, we conclude that the minimizer in the definition of Hopf-Lax lies in this neighborhood for $h$ small enough, and thus

\begin{equation}
u_{t + h}(\gamma_{t + h}) -  u_t(x) = \inf_{y \in M} \{L^{t,t+h}(y,\gamma_{t + h}) + u_t(y)\} - u_t(x) = L^{t,t + h}(x,\gamma_{t + h})\,.
\end{equation}
Taking now $\liminf_{h\downarrow 0}\frac{1}{h}$ of the RHS, we obtain

\begin{equation}
\partial_{t^+}^-u_t(x) + du_t(x)(\dot{\gamma}_t) = L(\dot{\gamma}_t,x,t) \qquad\implies \qquad \partial_{t^+}^-u_t(x) = L(\dot{\gamma}_t,x,t) - du_t(x)(\dot{\gamma}_t) = -H(du_t(x), x,t)\,,
\end{equation}
where for the last equality, we used the choice $\dot\gamma_t := \nabla^{g_t}u_t(x)$ and that the optimizer in the fiberwise Legendre transform of $L(\cdot,x,t)$ is given by the $g_t$-dual covector. 
\end{proof}

\section{Dynamic transport plans}\label{Appe:Dynplans}
\begin{proof}[Proof of Proposition \ref{prop:Lisini-for-geodesics}]
    For the first claim and the existence of $\eta$ optimal, see \cite[Thm.~7.21]{Vil09}. Moreover we can compute the speed of the curve for $r\in[s,t]$:
    \begin{align}\label{eq:energyplan2}
        (\dot{\mu}_r)_{L^r} &= \lim_{h\to 0}\frac{W_{L^{r,r+h}}(\mu_r,\mu_{r+h})}{h} \\
        &\overset{\cite{Vil09}}{=} \lim_{h\to0} \frac{1}{h} \int_C\int_r^{r+h} L(\dot\gamma_u,\gamma_u,u)du d\eta \\
        &= \int_CL(\dot\gamma_r,\gamma_r,r) d\eta.
    \end{align}

Finally, we want to relate the velocity $\dot\gamma_r$ to $d\phi_r$. Because $\pi=(e_r,e_t)_\#\eta$ is an optimal plan between $\mu_r$ and $\mu_t$, it holds (\cite[Thm.~5.10-(ii)-(c)]{Vil09}) that
\begin{align}
    \phi_{t}(y)-\phi_{r}(x)= L^{r,t}(x,y) \ \ \ \text{for $\pi$-a.e. $(x,y)$.}
\end{align}
On the other hand
\begin{align}
    \phi_t(y)-\phi_r(x) \leq L^{r,t}(x',y)+ \phi_r(x') - \phi_r(x)
\end{align}
hence (temporarily working with a support metric $g$) in a neighborhood of $0 \in T_xM$
\begin{align}
    \phi_r(\exp_x(v))-\phi_r(x) \geq L^{r,t}(x,y)-L^{r,t}(\exp_x(v),y) \geq \langle p,v \rangle + o(|v|)
\end{align}
if $p\in T_x^*M$ is a superdifferential of $L^{r,t}(\cdot,y)$ at $x$. By \cite[Prop.~10.15-(i)]{Vil09}, we can take $p=-d_v L(x,\dot\gamma_r,r)$, where $\gamma$ is an $L^{r,t}$ geodesic from $x$ to $y$. But then if $x$ is a differentiability point of $\phi_r$ ($\mu_r$-a.e. because $\mu_s$ is assumed absolutely continuous, and hence $\mu_r$ is as well by \cite[Thm.~8.7]{Vil09}) we get
\begin{align}
    d\phi_r(x)=-d_v L(x,\dot\gamma_r,r)
\end{align}
for $\pi$-a.e. $(x,y)$.
Because $L$ is strictly convex and superlinear the Legendre transform is a homeomorphism, $d_v L(x,\dot\gamma_r,r)=(\dot\gamma_r)^*$ and hence $\dot\gamma_r=-(d\phi_r)^*$. Since the latter identity holds on the $\eta$-full measure set
\begin{align}
    e_r^{-1}(\{x\in M\mid \phi_r \text{ differentiable at }x\}) \cap(e_r,e_t)^{-1}(\{(x,y)\in M\times M\mid \phi_t(y) - \phi_r(x) = L^{r,t}(x,y)\}) \subseteq C
\end{align}
we can conclude
\begin{align}
    (\dot{\mu}_r)_{L^r} = \int_C L(-(d\phi_r(\gamma_r))^*,\gamma_r,r)d\eta = \int_M L(-(d\phi_r(x))^*,x,r)d\mu_r\,.
\end{align}
\end{proof}

Now we prove Lemma \ref{lem:dynamiclifting}. In \cite{Lisini2007} the same conclusion holds for all a.c. curves in the Wasserstein space (induced by $d^p$): while we expect something similar might still hold for the Lagrangian case, we follow the more practical approach from \cite{Lott-somecalculations}.
\begin{proof}[Proof of Lemma \ref{lem:dynamiclifting}]
    Let $\mu_r=\rho_rdV_g$, $dV_g$ being the background volume measure, then we can find a unique (up to translation) $\phi_r$ such that its gradient (taken in the metric $2A_{x,r}$) solves the continuity equation:
    \begin{align}
        \partial_r\rho_r = -\div(\rho_r\nabla\phi_r)\,.
    \end{align}
    We then consider $\Phi_r$ to be the flow generated by $(\nabla\phi_r)_{r\in[s,t]}$, let $\Phi_{[s,t]}:M\mapsto C^1([s,t],M)$, $\Phi_{[s,t]}(x)=(\Phi_r(x))_{r\in[s,t]}$. We then define $\eta=(\Phi_{[s,t]})_\#\mu_s$, by construction we have $(e_r)_\#\eta=\mu_r$.

    $\leq)$ This direction holds in fact for any $\eta$ with $(e_r)_\#\eta=\mu_r$:
    \begin{align}
        (\dot\mu_r)_{L^r} &= \lim_{h\to0} \frac{W_{L^{r,r+h}}(\mu_r,\mu_{r+h})}{h} \\
        &\leq \lim_{h\to0} \frac{1}{h}\int_{M\times M} L^{r,r+h}(x,y) d(e_r,e_{r+h})_\#\eta \\
        &= \lim_{h\to0} \frac{1}{h} \int_{C} L^{r,r+h}(\gamma_r,\gamma_{r+h}) d\eta(\gamma) \\
        &\leq \lim_{h\to0} \frac{1}{h} \int_{C} \int_r^{r+h} L(\dot \gamma_u,\gamma_u,u) dud\eta(\gamma) \\
        &= \int_{C} L(\dot \gamma_r,\gamma_r,r) d\eta(\gamma).
    \end{align}

    $\geq)$ Fix $\mu_r$, $\mu_{r+h}$. Let $(\nu_u^h)_{u\in[r,r+h]}$ be a $W_{L^{r,r+h}}$ geodesic between them: $\nu_r^h=\mu_r$, $\nu_{r+h}^h=\mu_{r+h}$, and let $\theta^h\in\cP(C)$ be the lifting of $\nu^h$. Then for any $f\in C^1$:
    \begin{align}
        \int fd\mu_r- \int fd\mu_{r+h} &=  \int_C f(\gamma_{r+h})-f(\gamma_r) d\theta^h(\gamma) \\
        &= \int_C \int_r^{r+h} \langle df(\gamma_u),\dot\gamma_u\rangle du d\theta^h(\gamma) \\
        &\leq \int_C \int_r^{r+h} H(df(\gamma_u),\gamma_u,u) du d\theta^h + \int_C\int_r^{r+h}L(\dot\gamma_u,\gamma_u,u)dud\theta^h \\
        &= \int_r^{r+h}\int_M H(df(x),x,u) d\nu_u^h du + W_{L^{r,r+h}}(\mu_r,\mu_{r+h})
    \end{align}
    On the other hand, using the continuity equation
    \begin{align}
        \int fd\mu_r- \int fd\mu_{r+h} &= \int_r^{r+h} \frac{d}{du}\int fd\mu_u du \\
        &=\int_r^{r+h} \int \langle df,\nabla\phi_u\rangle d\mu_udu\,.
    \end{align}
    Hence 
    \begin{align}
        W_{L^{r,r+h}}(\mu_r,\mu_{r+h}) \geq \int_r^{r+h} \int \langle df,\nabla\phi_u\rangle d\mu_udu - \int_r^{r+h}\int_M H(df(x),x,u) d\nu_u^h du\,.
    \end{align}

Since $H$ is continuous in all inputs and $\nabla \phi$ is smooth, we have $H(df(\cdot), \cdot,u) \to H(df(\cdot), \cdot,r)$ and $\La df,\nabla \phi_u\Ra \to \La df,\nabla \phi_r\Ra \in C^0(M)$ uniformly as $u \to r$. We also have smooth (and thus also weak) convergence $\mu_u \weak \mu_r$, and uniformly weak convergence $\nu_{u_h}^h \weak \nu_r \in \cP(M)$ as $h\to0$ for any sequence $u_h\in[r,r+h]$. This last weak convergence holds because Proposition \ref{prop:W-implies-weak-conv} can be applied, as 
\begin{align}
\lim_{h \to 0}W_{L^{r,u_h}}(\nu_r^h,\nu_{u_h}^h) &= \lim_{h \to 0}W_{L^{r,r+h}}(\nu_r^h,\nu_{r+h}^h) - W_{L^{u_h,r+h}}(\nu_{u_h}^h,\nu_{r+h}^h) \\
&\leq \lim_{h\to0} \int_r^{r+h}\int_CL(\dot\gamma_u,\gamma_u,u)d\eta du - \int_{u_h}^{r+h}\int_CL(\dot\gamma_u,\gamma_u,u)d\theta^h du \\
&\leq \lim_{h\to0} \int_r^{r+h}\int_CL(\dot\gamma_u,\gamma_u,u)d\eta du + Ch\,.
\end{align}
For the first integral we used Proposition \ref{prop:Lisini-for-geodesics} along with the fact that $(e_{r})_\#\eta=\mu_r$, $(e_{r + h})_\#\eta=\mu_{r + h}$ (hence it is admissible), while for the second integral the bound on the Lagrangian $L(v,x,r)\geq -C$.

The pairings--of a uniformly converging sequence of functions with a weakly converging sequence of probability measures--themselves converge, i.e.
\begin{equation}
\lim_{u \to r} \int \langle df,\nabla\phi_u\rangle d\mu_u =  \int \langle df,\nabla\phi_r\rangle d\mu_r\,,\qquad 
\lim_{h \to 0}\int_M H(df(x),x,u_h) d\nu_{u_h} = \int_M H(df(x),x,r) d\nu_r \ \ \ \text{uniformly in $u_h$}.
\end{equation}

Taking $\lim_{h \to 0}\frac{1}{h}$ then gives
\begin{align}
        (\dot\mu_r)_{L^r} \geq \int_M \langle df(x),\nabla\phi_r(x)\rangle d\mu_r(x) - \int_M H(df(x),x,r) d\mu_r(x)\,.
\end{align}
Because $L$ is quadratic, $L(v,x,r)=A_{x,r}(v,v)+C_{x,r}$, the optimizer in the Legendre transform is just the dual through $2A_{x,r}$, hence choosing $f=\phi_r$ we conclude
\begin{align}
        (\dot\mu_r)_{L^r} &\geq  \int_M L(\nabla \phi_r,x,r) d\mu_r \\
        &=\int_C L(\dot\gamma_r,\gamma_r,r) d\eta \,.
\end{align}
\end{proof}

\section{Curve-smoothing lemma}

The following lemma will allow us to smooth out the densities of measures along $W_{L_{0/\pm}}$ geodesics in a way that is not too violent from the point of view of $L_{0/\pm}$ action or entropy. There is no significant difference between the arguments for the costs $L_{0}$, $L_-$, and $L_+$, so we state and prove the result for all three simultaneously.

\begin{lem}\label{lem:wass-geodesic-smoothing}
Let $(M,g_\tau)_{\tau \in I}$ be a family of smooth Riemannian manifolds parametrized by backwards time $\tau = T - t$, and $(\mu_\tau)_{\tau \in [\tau_1,\tau_2]}\subseteq \cP(M)$ a $W_{L_{0/\pm}^{\tau_1,\tau_2}}$ Wasserstein geodesic with a.c. endpoints $\mu_{\tau_i} \in \cP^{ac}(M,dV_{\tau_i})$, $i = 1,2$. Choose a cost $L_m$, $m = 0,+,-$. The times $[\tau_1 ,\tau_2] \subseteq I$ are required to satisfy $\tau_2 < \sup I$, and also $0 < \tau_1$ in the case $m = -$ and $0 < T - \tau_2$ in the case $m = +$. Assume that \eqref{eq:WCL0} ($m = 0$), \eqref{eq:WCL-} ($m =  -$), or \eqref{eq:WCL+} ($m = +$) hold, and for $\eps > 0$, define the $\eps$-related time operation for all $\tau \in [\tau_1,\tau_2]$

\begin{equation}
\tau^\eps := \begin{cases}
    \tau + \eps,&m = 0\,,\qquad\eps < \sup I - \tau_2 \\
    e^\eps\tau,& m = -\,,\qquad\eps < \ln (\sup I/\tau_2) \\
    T - e^{-\eps}(T - \tau),& m = +\,,\qquad \eps < \ln\big((T - \tau_2)/(T - \sup I)\big)
\end{cases}\,.
\end{equation}

Then there are curves $(\mu_\tau^\eps)_{\tau \in [\tau_1^\eps, \tau_2^\eps]} = (\rho_\tau^\eps\,dV_\tau)_{\tau \in [\tau_1^\eps, \tau_2^\eps]}$ such that:
\begin{itemize}
\item (regularity) We have the space-time regularity of densities $\rho^\eps \in C^\infty\big(M\times [\tau_1^\eps,\tau_2^\eps] ; (0,\infty)\big)$.
\item (action convergence) For any times $\tau_1 \leq \tilde\tau_1 \leq \tilde\tau_2 \leq \tau_2$ we have the bounded convergences
\begin{align}\label{eq:curve-conv}
\int_{\tilde\tau_1}^{\tilde\tau_2} (\dot{\mu}_{\sigma})_{L_{0/\pm}^\sigma}\,d\sigma &= \lim_{\eps \to 0} \int_{\tilde\tau_1^\eps}^{\tilde\tau_2^\eps} (\dot{\mu}_{\sigma}^\eps)_{L_{0/\pm}^\sigma}\,d\sigma\,,\\
\left|\int_{\tilde\tau_1^\eps}^{\tilde\tau_2^\eps} (\dot{\mu}_{\sigma}^\eps)_{L_{0/\pm}^\sigma}\,d\sigma\right| &\leq C = C(\tau_2,\,\tau_1,\,\mu_{\tau_1},\mu_{\tau_2},\, (M,g_\tau)_{\tau \in I})\,. 
\end{align}

(For the definition and existence of the metric derivative for geodesics, see Proposition \ref{prop:Lisini-for-geodesics}).
\item (entropy convergence) We have the convergence for each time (possibly to $+\infty$)

\begin{equation}\label{eq:entropy-conv}
\lim_{\eps \to 0} \cE(\mu_{\tau^\eps}^\eps) = \cE(\mu_\tau)\,,\qquad \forall \tau \in [\tau_1,\tau_2]\,.
\end{equation}
\end{itemize}
\end{lem}

\begin{rmk}
The assumption that \eqref{eq:WCL0}, \eqref{eq:WCL-}, resp. \eqref{eq:WCL+} hold is not actually needed. It is in fact sufficient that $\cD(X) \geq -C(|X|^2 + 1) > -\infty$ for some $C \in \R{}$, which is automatic since $M$ is assumed smooth and closed. However, to carefully check this one would need to keep track of the corresponding error throughout the proof of $\cD \geq 0 \implies$ \eqref{eq:WCL0}, \eqref{eq:WCL-}, \eqref{eq:WCL+}. We therefore leave the details to the interested reader.
\end{rmk}

\begin{proof}
Let us begin by remarking that since $\mu_{\tau_1} = \rho_{\tau_1}\,dV_{\tau_1}$ and $\mu_{\tau_2} = \rho_{\tau_2}\,dV_{\tau_2}$ are assumed absolutely continuous, each measure along the geodesic $(\rho_\tau\,dV_\tau)_{\tau \in [\tau_1,\tau_2]}$ is as well by \cite[Thm.~8.7]{Vil09}.
We define $(\mu_{\tau^\eps}^\eps)_{\tau^\eps \in [\tau_1^\eps,\tau_2^\eps]}$ using the ``sliding window'' formula

\begin{equation}
\mu^\eps_{\tau^\eps} := \hat{P}_{\tau,\tau^\eps}[\mu_{\tau}]\,,\qquad\rho_{\tau^\eps}^\eps = P_{\tau,\tau^\eps}^*[\rho_{\tau}]\,,\qquad \forall \tau \in [\tau_1,\tau_2]\,. 
\end{equation}

Let us note that $\rho^\eps_{\tau^\eps}$ is nowhere $0$ for $\eps > 0$ by the strong maximum principle, and is a smooth function on $M$ for each $\tau^\eps \in [\tau_1^\eps,\tau_2^\eps]$. To see that it has the desired regularity in time, we can make use of Proposition \ref{prop:Lisini-for-geodesics} to write $\mu_\tau = (e_\tau)_\# \eta$ for some $\eta \in \cP(C([\tau_1,\tau_2],M))$ that is supported on $L_{0/\pm}$ geodesics. These curves are in particular $C^\infty$ in their parameter, so writing $p_{\sigma,\tau}^*(x,y)$ the adjoint heat kernel,

\begin{align}
\lim_{\eta \to 0}\frac{\rho_{(\tau + \eta)^\eps}^\eps(x) - \rho_{\tau^\eps}^\eps(x)}{\eta} &= \lim_{\eta \to 0} \frac{1}{\eta}\left(\int_M p_{\tau + \eta, (\tau + \eta)^\eps}^*(x,y)\,d\mu_{\tau + \eta}(y) - \int_M p_{\tau,\tau^\eps}^*(x,y)\,d\mu_{\tau}(y)\right) \\
&= \lim_{\eta \to 0} \frac{1}{\eta}\left(\int_C p_{\tau + \eta,(\tau + \eta)^\eps}^*(x,\gamma_{\tau + \eta})\,d\nu(\gamma) - \int_C p_{\tau,\tau^\eps}^*(x,\gamma_{\tau})\,d\nu(\gamma)\right) \\
&= \int_C \La d_yp_{\tau,\tau^\eps}^*(x,\gamma_{\tau}),\dot{\gamma}_{\tau}\Ra + \left.\partial_\eta\right|_{\eta = 0}(p^*_{\tau+ \eta,\tau^\eps } + p^*_{\tau,(\tau + \eta)^\eps})(x,\gamma_{\tau})\,d\nu(\gamma)\,,\qquad x \in M\,,
\end{align}
where we passed the limiting difference quotient into the integral by dominated (even bounded) convergence. The RHS is a smooth function of $x$ by similarly differentiating under the integral sign, and arbitrary derivatives in $x$ are continuous in time because $\nu$ is concentrated on uniformly $C^1$ curves. One may take arbitrarily many $\tau$ derivatives in this way, showing that $\rho^\eps_{\tau^\eps}(x)$ has all partial derivatives in the $x,\tau$ variables, which are moreover continuous. This shows that $\rho^\eps \in C^\infty\big([\tau_1^\eps,\tau_2^\eps]\times M;(0,\infty)\big)$ as desired. \vspace{0.5cm}

We now turn to the convergence of $W_{L_{0/\pm}}$ actions. The heat flow for Borel probability measures is weakly continuous up to the initial time, i.e. $\mu^\eps_{\tau_\eps} \weak \mu_\tau$ as $\eps \to 0$ for all $\tau \in [\tau_1,\tau_2]$. Applying this to the endpoints of any interval $[\tilde\tau_1, \tilde\tau_2] \subseteq [\tau_1,\tau_2]$ yields the convergence of transportation costs

\begin{equation}
W_{L_{0/\pm}^{\tilde\tau_1 ^\eps,\tilde\tau_2 ^\eps}}(\mu_{\tilde\tau_1^\eps}^\eps, \mu_{\tilde\tau_2^\eps}^\eps) \to W_{L_{0/\pm}^{\tilde\tau_1,\tilde\tau_2}}(\mu_{\tilde\tau_1},\mu_{\tilde\tau_2}) \qquad \text{as }\eps \to 0\,.
\end{equation}
as a result of \cite[Thm.~5.20]{Vil09}. Now let $(\phi_\tau^\eps)_{\tau \in [\tilde\tau_1^\eps,\tilde\tau_2^\eps]}$ be the Kantorovich potentials for the pair $(\mu_{\tilde\tau_1^\eps}^\eps, \mu_{\tilde\tau_2^\eps}^\eps)$ given by Corollary \ref{cor:dynamic-potentials}. We can use $\phi_\tau^\eps$ as a candidate for the dual problem w.r.t any other pair of measures, followed by the assumed \eqref{eq:WCL0}, \eqref{eq:WCL-}, or \eqref{eq:WCL+}, in
\begin{align}
\frac{W_{L_{0/\pm}^{\sigma_1^\eps,\sigma_2^\eps}}(\mu_{\sigma_1^\eps}^\eps,\mu_{\sigma_2^\eps}^\eps)}{\sigma_2^\eps - \sigma_1^\eps} &= \frac{1}{\sigma_2^\eps - \sigma_1^\eps}\left.\int_M \phi_{\sigma}^\eps \,d\mu_{\sigma}^\eps \right|_{ \sigma_1^\eps}^{\sigma_2^\eps} \\
&= \frac{1}{\sigma_2^\eps - \sigma_1^\eps}\left.\left(\int_M\phi_\sigma^\eps \,d\hat{P}_{\sigma,\sigma^\eps}\mu_{\sigma}\right)\right|_{ \sigma_1^\eps}^{\sigma_2^\eps} \\
&\leq \frac{W_{L_{0/\pm}^{\sigma_1^\eps, \sigma_2^\eps}}(\hat{P}_{\sigma_1,\sigma_1^\eps}\mu_{\sigma_1}, \hat{P}_{\sigma_2,\sigma_2^\eps}\mu_{\sigma_2})}{\sigma_2^\eps - \sigma_1^\eps} \\
&\leq \frac{(1 + \Psi(\eps))\cdot W_{L_{0/\pm}^{\sigma_1, \sigma_2}}(\mu_{\sigma_1}, \mu_{\sigma_2}) + \Psi(\eps)\cdot (\sigma_2 - \sigma_1)}{(1 + \Psi(\eps))\cdot (\sigma_2 - \sigma_1)}\,,\qquad \tilde\tau_1 ^\eps \leq \sigma_1^\eps < \sigma_2^\eps \leq \tilde\tau_2^\eps\,.
\end{align}
Now, we can use Propositions \ref{prop:Lisini-for-geodesics} and Lemma \ref{lem:dynamiclifting} to take the limit $\sigma_1^\eps, \sigma_2^\eps \to \sigma^\eps$ on both sides, obtaining $(\dot{\mu}_{\sigma ^\eps}^\eps)_{L_{0/\pm}^{\sigma^\eps}} \leq (1 + \Psi(\eps))\cdot (\dot{\mu}_{\sigma})_{L_{0/\pm}^{\sigma}} + \Psi(\eps)$ for any $\tilde\tau_1^\eps \leq \sigma^\eps \leq\tilde\tau_2^\eps$. Integrating in the variable $\sigma^\eps \in [\tilde\tau_1^\eps,\tilde\tau_2^\eps]$ gives
\begin{align}
W_{L_{0/\pm}^{\tilde\tau_1^\eps,\tilde\tau_2^\eps}}(\mu_{\tilde\tau_1^\eps}^\eps,\mu_{\tilde\tau_2^\eps}^\eps) \leq \int_{\tilde\tau_1^\eps}^{\tilde\tau_2^\eps}(\dot{\mu}_\sigma^\eps)_{L_{0/\pm}^{\sigma}}\,d\sigma &\leq \int_{\tilde\tau_1}^{\tilde\tau_2}\Big((1 + \Psi(\eps))\cdot(\dot{\mu}_{\sigma})_{L_{0/\pm}^{\sigma}}+ \Psi(\eps)\Big)(1 + \Psi(\eps))\,d\sigma  \\
&= (1 + \Psi(\eps))\cdot W_{L_{0/\pm}^{\tilde\tau_1,\tilde\tau_2}}(\mu_{\tilde\tau_1}, \mu_{\tilde\tau_2})+ \Psi(\eps)\,,
\end{align}
where we used the $W_{L_{0/\pm}}$ triangle inequality for the first inequality. After taking $\limsup_{\eps \to 0}$ of each expression in the above chain of inequalities, along with the previously established convergence of transportation costs applied to the LHS, implies that all quantities above converge, and to the same limit $\int_{\tilde\tau_1}^{\tilde\tau_2}(\dot\mu_\sigma)_{L_{0/\pm}^{\sigma}}\,d\sigma$. This gives \eqref{eq:curve-conv}. The same chain of inequalities, along with the uniform lower bound $L_{0/\pm}(v,x,\tau) \geq -C$ on the Lagrangians inducing the costs of $W_{L_{0/\pm}}$, gives uniform bounds on the action (with perhaps a larger $C$).
\begin{equation}
-C(\tau_2^\eps - \tau_1^\eps) \leq \int_{\tilde\tau_1 ^\eps}^{\tilde\tau_2^\eps} (\dot\mu_\sigma^\eps)_{L_{0/\pm}^\sigma}\,d\sigma \leq   C( W_{L_{0/\pm}^{\tau_1,\tau_2}}(\mu_{\tau_1},\mu_{\tau_2}) + 1 + \tau_2^\eps - \tau_1^\eps)\,.
\end{equation}

It remains to check the entropy convergence. Since $[0,\infty)\ni x\mapsto x\ln x$ is bounded from below, and $P^*_{\tau, \tau^\eps}[\rho_\tau] \to \rho_\tau$ pointwise a.e. as $\eps \to 0$ by the Lebesgue differentiation theorem, Fatou's Lemma implies that 
\begin{equation}
\cE(\mu_\tau) = \int_M \rho_\tau \ln \rho_\tau\, dV_\tau \leq \liminf_{\eps \to 0}\int_M \rho_{\tau^\eps}^\eps \ln (\rho_{\tau^\eps}^\eps)\,dV_{\tau^\eps} = \liminf_{\eps \to 0}\cE(\mu_{\tau^\eps}^\eps)\,,\qquad \forall \tau \in [\tau_1,\tau_2]\,.
\end{equation}
On the other hand, the convexity of $x \mapsto x\ln x$ along with Jensen's inequality applied in the probability space $(M_x, p^*_{\tau,\tau^\eps}(y,x)\,dV_\tau(x)/P_{\tau,\tau^\eps}^*[1](y))$ for each $y \in M$ yields
\begin{align}
\cE(\mu_{\tau^\eps}^\eps)&=\int_M(P^*_{\tau, \tau^\eps}[\rho_{\tau}])\ln(P^*_{\tau, \tau^\eps}[\rho_{\tau}])\,dV_{\tau^\eps} \\
&= \int_M (P^*_{\tau, \tau^\eps}[1])\left(\frac{P^*_{\tau, \tau^\eps}[\rho_{\tau}]}{P^*_{\tau, \tau^\eps}[1]}\right)\ln\left(\frac{P^*_{\tau, \tau^\eps}[\rho_{\tau}]}{P^*_{\tau, \tau^\eps}[1]}\right)\,dV_{\tau^\eps} + \int_M \ln (P^*_{\tau, \tau^\eps}[1])\,d\hat{P}_{\tau, \tau^\eps}[\mu_{\tau}] \\
&\leq \int_M (P^*_{\tau, \tau^\eps}[1])\frac{P^*_{\tau, \tau^\eps}[\rho_{\tau}\ln(\rho_{\tau })]}{P^*_{\tau, \tau^\eps}[1]}\,dV_{\tau^\eps} + \int_M \ln (P^*_{\tau, \tau^\eps}[1])\,d\hat{P}_{\tau, \tau^\eps}[\mu_{\tau}]\\
&=\int_M P^*_{\tau, \tau^\eps}[\rho_{\tau}\ln(\rho_{\tau })]\,dV_{\tau^\eps} + \int_M \ln (P^*_{\tau, \tau^\eps}[1])\,d\hat{P}_{\tau, \tau^\eps}[\mu_{\tau}] \\
&= \cE(\mu_{\tau}) + \int_M P_{\tau,\tau^\eps}[\ln (P_{\tau, \tau^\eps}^*[1])]\,d\mu_{\tau}\,,\qquad \forall \tau \in [\tau_1,\tau_2]\,. 
\end{align}
Note that we used that the adjoint heat flow preserves the integral over $M$ to obtain the first term in the final equality. Moreover, the integrand $P_{\tau,\tau^\eps}[\ln (P_{\tau, \tau^\eps}^*[1])]$ of the second term tends uniformly to $0$ as $\eps \to 0$. Taking $\limsup_{\eps\to 0}$ on both sides shows $\limsup_{\eps \to 0}\cE(\mu_{\tau^\eps}^\eps) \leq\cE(\mu_\tau)$. Combining the upper and lower bounds on $\cE(\mu_\tau)$ gives the desired convergence.
\end{proof}
