\section{Appendix: Proof of Theorem~1}

The proof  extends the approach proposed in~\cite{GE21} to the tracking problem.

Similarly to the results of~\cite{GE21}, it can be shown that, for any $\delta_x\in(0,\Delta_x)$, $\delta_y\in(0,\Delta_y)$, there exist an  $\varepsilon_1>0$ and an $\eta_0:(0,\infty)\to(0,\infty)$ such that, for any $\varepsilon\in(0,\varepsilon_1)$, $\eta\in(\eta_0(\varepsilon),\infty)$, and any  $(x^0,u^0)\in\overline{B_{\delta_{x}}(\ell(u^*(t)))\times B_{\delta_u}(u^*(t))}$, the solutions $(x(t),u(t))$ of system~\eqref{sys_dyn}--\eqref{cont_dyn} with initial condition $x(0)=x^0$, $u(0)=u^0$ are well-defined in $D_x\times D_u$ for all $t\ge0$. We omit this step because of the page limits and assume in the sequel that $\varepsilon\in(0,\varepsilon_0)$, $\eta\in(\eta_0(\varepsilon),\infty)$.

\vskip1em

\emph{\textbf{Step 1.} Estimating the maximal deviations between the $x$ and $u$ components of the solution of system~\eqref{sys_dyn}--\eqref{cont_dyn} with $(x^0,u^0)\in\overline{B_{\delta_{x}}(\ell(u^*(t)))\times B_{\delta_u}(u^*(t))}$.}


Using Assumptions~2--3 and H\"older's inequality, we get the following estimates:
$$
\begin{aligned}
 &\sqrt{h(t,\ell(u(t)))}\le \alpha_{12}\|u(t)-u^*(t)\|\\
& \le \alpha_{12}\left(\|u^0-u^*(0)\|+\|u^*(t)-u^*(0)\|+\|u(t)-u^0\|\right)\\
 & \le \alpha_{12}\left(\|u^0-u^*(0)\|+\nu+\int\limits_0^t\|\dot u(s)\|ds\right)\\
& \le \alpha_{12}\left(\|u^0-u^*(0)\|+\nu+\frac{\gamma c_u}{\eta\sqrt\varepsilon}\int\limits_0^t \sqrt{h(s,x(s))}ds\right),
\end{aligned}
$$
where $c_u=\gamma \sqrt{2\pi n_u(1+n_u)}$.
Thus,
$$
\begin{aligned}
&\sqrt{h(t,x(t))}\le \sqrt{h(t,\ell(u(t)))}+L_h\|x(t)-\ell(u(t))\|\\
&\le \alpha_{12}\left(\|u^0-u^*(0)\|+\nu+\frac{c_u}{\eta\sqrt\varepsilon}\int\limits_0^t \sqrt{h(s,x(s))}ds\right)\\
&+\frac{L_h}{\sigma_{11}}\sqrt{V(x(t),u(t))}.
\end{aligned}
$$
From the Gr\"onwall--Bellman inequality, this implies
\begin{equation}\label{est_h}
\begin{aligned}
&\sqrt{h(t,x(t))}\le \alpha\left(\|u^0-u^*(0)\|+\nu\right)\\
&+\frac{L_h}{\sigma_{11}}\sqrt{V(x(t),u(t))}+\frac{\alpha L_hc_u}{\sigma_{11}\eta\sqrt\varepsilon}\int\limits_0^t \sqrt{V(x(s),u(s))}ds,
\end{aligned}
\end{equation}
with $\alpha=\alpha_{12}e^{\alpha_{12}c_u\sqrt\varepsilon}$.
Furthermore, Assumption~\ref{ass_V} provides the following estimate:
$$
\begin{aligned}
\dot V&(x(t),u(t))= \frac{\partial V(x(t),u(t))}{\partial x}f(x(t),u(t))+\frac{\partial V(x(t),u(t))}{\partial u}\dot u(t)\\
&\le -\sigma_{21} V(x(t),u(t))+\sigma_{22}\sqrt{V(x(t),u(t))}\|\dot u(t)\|\\
&\le -\sigma_{21} V(x(t),u(t))+\frac{c_u\sigma_{22}}{\eta\sqrt\varepsilon}\sqrt{V(x(t),u(t))h(t,x(t))}.
\end{aligned}
$$
Given any $\sigma\in(0,\sigma_{21})$, let
$$
\eta_1(\varepsilon)=\frac{c_u L_h\sigma_{22}}{\sigma_{11}(\sigma_{21}-\sigma)\sqrt\varepsilon}.
$$
Then the last inequality together with~\eqref{est_h} implies that, for any $\varepsilon>0$, $\eta>\eta_1(\varepsilon)$,
$$
\begin{aligned}
\dot V&(x(t),u(t))\le - \sigma V(x(t),u(t))+\sqrt{V(x(t),u(t))}\varphi(t),
\end{aligned}
$$
where
$$
\begin{aligned}
\phi(t)=\frac{\alpha c_u\sigma_{22}}{\eta\sqrt\varepsilon}\Big(\|u^0&-u^*(0)\|+\nu\\
&+\frac{c_uL_h}{\sigma_{11}\eta\sqrt\varepsilon}\int\limits_0^t \sqrt{V(x(s),u(s))}ds\Big).
\end{aligned}$$
Solving the resulting comparison inequality yields the following estimate:
$$
\begin{aligned}
 &   \sqrt{V(x(t),u(t))}\le \sqrt{V(x^0,u^0)}e^{-\sigma t/2}\\
    &+\frac{1}{2}\int\limits_0^te^{-\sigma(t-s)/2}\phi(s)ds\\
    &\le\sqrt{V(x^0,u^0)}e^{-\sigma t/2}+\frac{\alpha c_u\sigma_{22}}{\sigma\eta\sqrt\varepsilon}\big(\|u^0-u^*(0)\|+2\nu \big)\\
    &+\frac{\alpha c_u^2 L_h\sigma_{22}}{2\sigma_{11}\eta^2\varepsilon}\int\limits_0^te^{-\sigma(t-s)/2}\int\limits_0^s \sqrt{V(x(p),u(p))}dpds.
\end{aligned}
$$
Applying integration by part to the last term, we continue the above estimate as
$$
\begin{aligned}
    \sqrt{V(x(t),u(t))}&\le \sqrt{V(x^0,u^0)}e^{-\sigma t/2}\\
    &+\frac{\alpha c_u\sigma_{22}}{\sigma\eta\sqrt\varepsilon}\big(\|u^0-u^*(0)\|+\nu\big)\\
    &+\frac{\alpha c_u^2 L_h\sigma_{22}}{\sigma\sigma_{11}\eta^2\varepsilon}\int\limits_0^t\sqrt{V(x(s),u(s))}ds.
\end{aligned}
$$
Using again the Gr\"onwall–Bellman inequality for $t\in[0,\eta\varepsilon]$ yields
$$
\begin{aligned}
    &\sqrt{V(x(t),u(t))}\le\frac{\alpha c_u\sigma_{22}}{\sigma\eta\sqrt\varepsilon}e^{\frac{\alpha c_u^2 L_h\sigma_{22}}{\sigma\sigma_{11}\eta}}\big(\|u^0-u^*(0)\|+\nu\big)\\
    &+\sqrt{V(x^0,u^0)}\Big(e^{-\sigma t/2}+\frac{\alpha c_u^2 L_h\sigma_{22}}{\sigma\sigma_{11}\eta^2\varepsilon}e^{\frac{\alpha c_u^2 L_h\sigma_{22}}{\sigma\sigma_{11}\eta}}\Big).
\end{aligned}
$$
Thus, for any $t\in[0,\eta\varepsilon]$,
\begin{equation}
    \label{estV1}
\begin{aligned}
   &\sqrt{V(x(t),u(t))}\le \frac{1}{\eta\sqrt\varepsilon}\Big({c_{v1}}\|u^0-u^*(0)\|+{\tilde\nu}\Big)\\
    &+\Big(e^{-\sigma t/2}+\frac{c_{v2}}{\eta^2\varepsilon}\Big)\sqrt{V(x^0,u^0)},
  \end{aligned}
\end{equation}
where $$c_{v1}=\frac{\alpha c_u\sigma_{22}}{\sigma}e^{\frac{\alpha c_u^2 L_h\sigma_{22}}{\sigma\sigma_{11}}\eta},\; c_{v2}=\frac{c_{v1}c_uL_h}{\sigma_{11}},\; \tilde \nu= c_{v1}\nu.$$
Consequently,
\begin{equation}
    \label{est_xu}
\begin{aligned}
   &\|x(t)-\ell(u(t))\|\le  \frac{1}{\alpha_{11}\eta\sqrt\varepsilon}\Big({c_{v1}}\|u^0-u^*(0)\|+{\tilde\nu}\Big)\\
    &+\frac{1}{\alpha_{11}}\Big(e^{-\sigma t/2}+\frac{c_{v2}}{\eta^2\varepsilon}\Big)\sqrt{V(x^0,u^0)},
  \end{aligned}
\end{equation}
for all $t\in[0,\eta\varepsilon]$.

\vskip1em

\emph{\textbf{Step 2.} Estimating the maximal deviations between the  $u$ component of the solution of system~\eqref{sys_dyn}--\eqref{cont_dyn} with $(x^0,u^0)\in\overline{B_{\delta_{x}}(\ell(u^*(t)))\times B_{\delta_u}(u^*(t))}$ and the solutions of the reduced system.}

As the next step, consider the auxiliary system
\begin{equation}\label{cont_dyn_au}
\dot {\bar u}_j=\frac{2\gamma}{\eta\sqrt\varepsilon}\sqrt{\pi  jh(t,\ell(\bar u))}\sin\left(\ln h(t_m,\ell(\bar u))+\frac{2\pi j t}{\eta\varepsilon}\right),
\end{equation}
with  $j=1,\dots,n_u$, $ t\in [0,\eta\varepsilon]$,   $\bar u(t^0)=u(t^0)\in D_u$.
Then
$$
\begin{aligned}
 \|&u(t)-\bar u(t)\|\le\frac{c_u L_{hx}}{\eta\sqrt\varepsilon}\int_{t_m}^{t_{m+1}}\|x(s)-\ell(\bar u(s))\|ds\\
 &\le\frac{c_u L_{hx}}{\eta\sqrt\varepsilon}\int_{t_m}^{t_{m+1}}\Big(\|x(s)-\ell( u(s))\|+L_\ell\|u(s)-\bar u(s)\|\Big)ds.\\
\end{aligned}
$$
Together with the Gr\"ownall--Bellman inequality, this implies
\begin{equation}
    \label{ubu}
\begin{aligned}
  \|u(t)-\bar u(t)\|\le \frac{c_{\tilde u 1}}{\eta}\|u^0&-u^*(0)\|\\
  &+\frac{c_{\tilde u 2}}{\eta\sqrt\varepsilon}\sqrt{V(x^0,u^0)}+\frac{c_{\tilde u 3}}{\eta}\tilde \nu
\end{aligned}
\end{equation}
for all $t\in[0,\eta\varepsilon]$,
where
$$c_{\tilde u 1}=c_{\nu1}c_{\tilde u 3} ,\; c_{\tilde u2}=\big(1+\dfrac{c_{\nu2}}{\eta}\Big)c_{\tilde u 3},\;     c_{\tilde u 3}=e^{c_u L_{hx} L_\ell \sqrt\varepsilon}\dfrac{c_u L_{hx}}{\alpha_{11}}.$$

\vskip1em

\emph{\textbf{Step 3.} Ensuring tracking properties for  the solutions of the reduced system.}

Based on the results of the paper~\cite{GE21}, we can derive the following representation of the solutions of system~\eqref{cont_dyn_au}:
$$
\bar u(\eta\varepsilon)=u^0-\varepsilon\gamma^2(u^0-u^*(0))+R_{\bar u},
$$
where $\|R_{\bar u}\|\le c_{R\bar u}\varepsilon^{3/2}$. Thus,
$$
\begin{aligned}
    \|\bar u(\eta\varepsilon)- u(\eta\varepsilon)\|\le (1&-\varepsilon\gamma^2)\|u^0-u^*(0)\|\\
    &+\|\bar u(\eta\varepsilon)-u^*(0)\|+c_{R\bar u}\varepsilon^{3/2}\\
    \le (1&-\varepsilon\gamma^2)\|u^0-u^*(0)\|+\nu+c_{R\bar u}\varepsilon^{3/2}.
\end{aligned}
$$
Given any $\rho>\nu$ and any $\varepsilon>0$, let us take any $\rho'\in(0,\rho)$, and  assume $\dfrac{\nu}{\rho'}<\varepsilon\gamma^2<1$.
Then, similarly to the approach of~\cite{GMZME18}, one can show that there exist an $\varepsilon_2>0$ and $\bar\gamma(\varepsilon)>0$ such that, for all $\varepsilon\in(0,\varepsilon_2)$, the solutions of system~\eqref{cont_dyn_au} with $\gamma=\bar\gamma(\varepsilon)$ satisfy the following properties:
\begin{itemize}
    \item if $\|u^0-u^*(0)\|\ge\rho'$, then $\|\bar u(\eta\varepsilon)-u^*(\eta\varepsilon)\|<\|u^0-u^*(0)\|$;
    \item if $\|u^0-u^*(0)\|<\rho'$, then $\|\bar u(\eta\varepsilon)-u^*(\eta\varepsilon)\|<\rho'$.
\end{itemize}
The rest of the proof is based on the estimate~\eqref{ubu} with a large  enough $\eta$ and follows the line of~\cite[Proof of Theorem~1, Step~4]{GE21}.

