\section{The total number of PBHs and the number density in a cluster}
The total number of PBHs in a cluster can be estimated using the two-point correlation function\;\cite{DeLuca:2022bjs,DeLuca:2022uvz}:
\begin{equation}
N_{\text{cl}} \approx \bar{n}_{\rm pbh} \int{\rm d}^3x\,\xi_{\rm pbh}(r) \approx \frac{4\pi}{3} \bar{n}_{\rm pbh} \xi_\alpha r_{\text{cl}}^3
\end{equation}
where $\bar{n}_{\rm pbh}$ is the average comoving number density of PBHs:
\begin{equation}
\bar{n}_{\rm pbh} 
=\frac{\Omega_{\rm dm}}{\Omega_{\rm M}}f_{\rm pbh}\frac{\rho_{\rm eq}}{m_{\rm pbh}}a_{\rm eq}^3
\approx f_{\rm pbh} \left( \frac{30{\rm\,M}_\odot}{m_{\rm pbh}} \right) \text{kpc}^{-3}\;.
\end{equation}
Here, we have used the ratio of dark matter to total matter abundance $\Omega_{\rm dm}/\Omega_{\rm M}\approx 0.85$, the PBH fraction of dark matter $f_{\rm pbh}\equiv\Omega_{\rm pbh}/\Omega_{\rm dm}$, and the matter energy density at matter-radiation equality $\rho_{\rm eq}\equiv\Omega_{\rm M}\,\rho_{\rm crit,0}/a_{\rm eq}^3$, with the scale factor $a_{\rm eq}\simeq1/3401$. The present critical density is taken to be $\rho_{\rm crit,0}\simeq1.27\times10^{-7}{\rm\,M}_\odot{\rm\,pc^{-3}}$ and $\Omega_{\rm M}\simeq0.3$.

We consider the PBH cluster to evolve as normal matter, diluting with the cosmic expansion until it decouples from the Hubble flow. This decoupling occurs when the energy density of the cluster, $\rho_{\rm cl}=m_{\rm pbh}n_{\rm cl}$, becomes comparable to the radiation energy density, $\rho_{\rm rad}$. After this point, the number density $n_{\rm cl}$ becomes constant in comoving coordinates. The cluster's energy density at decoupling, with scale factor $a_{\rm dec}$, is given by:
\begin{equation}
\rho_{\text{cl}}(a_{\text{dec}}) = \xi_\alpha \bar{\rho}_{\rm pbh}(a_{\text{dec}}) = \xi_\alpha \bar{\rho}_{\text{pbh}}(a_{\text{eq}}) \left( \frac{a_{\text{eq}}}{a_{\text{dec}}} \right)^3 = \xi_\alpha \left(0.85f_{\rm pbh} \rho_{\text{eq}}\right) \left( \frac{a_{\text{eq}}}{a_{\text{dec}}} \right)^3\,,
\end{equation}
where $\bar{\rho}_{\rm pbh}=m_{\rm pbh}\bar{n}_{\rm pbh}$. On the other hand, the radiation energy density redshifts as:
\begin{equation}
\rho_{\text{rad}}(a_{\text{dec}}) = \rho_{\text{eq}} \left( \frac{a_{\text{eq}}}{a_{\text{dec}}} \right)^4.
\end{equation}
Equating $\rho_{\text{cl}}(a_{\text{dec}})=\rho_{\text{rad}}(a_{\text{dec}})$, we find the scale factor at decoupling:
\begin{equation}
 a_{\text{dec}} = \frac{a_{\text{eq}}}{0.85f_{\rm pbh} \xi_\alpha}\,,
\end{equation}
which is valid for $0.85f_{\rm pbh} \xi_\alpha>1$. After decoupling and virialization, the cluster undergoes further contraction. We account for this by introducing the compactness parameter $C\gg1$, which enhances the final cluster number density:
\begin{equation}
n_{\text{cl}} = C(0.85f_{\rm pbh}\xi_\alpha)^4 \frac{\rho_{\text{eq}}}{m_{\rm pbh}}
\simeq2\times10^8{\rm\,pc^{-3}}\left(\frac{f_{\rm pbh}\xi_\alpha}{25}\right)^4\left(\frac{C}{20}\right)\left(\frac{30{\rm\,M}_{\odot}}{m_{\text{pbh}}}\right)\;.
\end{equation}

\section{The spin of clusters from tidal interactions}
We adopt a model in which PBH clusters are approximated as homogeneous ellipsoids with semi-axes $r_1\geq r_2\geq r_3$ during their hierarchical merging phase leading to SMBH formation.
The tidal torque yields
\begin{align}
&\tau_i=\epsilon_{ijk}Q_{jl}T_{lk}\,,
\end{align}
\begin{comment}
where 
\begin{align}
   { \small Q_{ij} = \frac{M_{cl}}{5}
\begin{bmatrix}
2a^2 - b^2 - c^2 & 0 & 0 \\
0 & 2b^2 - a^2 - c^2 & 0 \\
0 & 0 & 2c^2 - b^2 - a^2
\end{bmatrix}}
\end{align}
\end{comment}
where $Q_{ij}$ is the quadrupole moment of the cluster, $T_{ij}=GM_{\rm cl}\left(\delta_{ij}-3\hat{x}_i\hat{x}_j\right)/r^3$ the tidal tensor of a source at $(r, \theta, \phi)$ with the unit vector $\hat{x}_i=(\sin\theta \cos\phi, \sin\theta \sin\phi, \cos\theta)$. The ensemble-averaged squared tidal torque is computed by integrating over all external cluster configurations
\begin{align}
\langle\tau^2\rangle=\int^{\infty}_{r_{\rm vir}}P(r)\left(\sum_{i=1}^3 \tau_i^2\right){\rm\,d}^3x\,,
\end{align}
where $P(r)$ is the two-point spatial distribution function of PBH clusters, describing their correlation at separation $r$, and is given as follows.

We assume that all PBH clusters have the same mass and are homogeneously distributed within a maximum comoving distance $R_{\rm max}^c$, which defines the local clustering environment. The comoving mean inter-cluster distance is given by
\begin{align}
\bar{R}_{\rm cl}^c
\simeq \left(\frac{4\pi\bar{n}_{\rm pbh}}{3N_{\rm cl}}\right)^{-1/3}=\xi_{\alpha}^{1/3}r_{\rm cl}\,,
\end{align}
where $\xi_\alpha\gg1$ ensures a high clustering factor, and hence $\bar{R}_{\rm cl}^c\gg r_{\rm cl}$. We set $R_{\rm max}^c\simeq(4/3)\bar{R}_{\rm cl}^c$ using the definition of the average distance $\bar{R}_{\rm cl}^c=\int_{|\vec{r}|<R_{\rm max}^c}|\vec{r}-\vec{r}_0|{\rm\,d^3}x/\int_{|\vec{r}|<R_{\rm max}^c}{\rm d^3}x$ for a reference cluster fixed at the origin $\vec{r}_0=0$.
Evaluating the physical separation at the decoupling epoch $a_{\rm dec}\simeq a_{\rm eq}/(0.85f_{\rm pbh}\xi_\alpha)$, we find:
\begin{align}
R_{\rm max}^p(a_{\rm dec})\simeq a_{\rm dec}\bar{R}_{\rm cl}^c=a_{\rm eq}/(0.85f_{\rm pbh}\xi_\alpha)\cdot \frac{4}{3}\xi_{\alpha}^{1/3}r_{\rm cl}=\frac{4}{3}\left(C\xi_\alpha\right)^{1/3}r_{\rm vir}\,,
\end{align}
where we have used the virial radius expression:
\begin{equation}
r_{\rm vir}=\left(\frac{3M_{\rm cl}}{4\pi \rho_{\rm cl}}\right)^{1/3}
=\left(\frac{3N_{\rm cl}}{4\pi n_{\rm cl}}\right)^{1/3}
=(0.85f_{\rm pbh}\xi_\alpha)^{-1}C^{-1/3}a_{\rm eq}\,r_{\rm cl}\;.
\end{equation}
Thus, the probability distribution for finding another cluster at position $\vec{r}_0+\vec{r}$ , given a cluster at $\vec{r}_0=0$, is approximately:
\begin{align}
P(r)\simeq
\left\{ 
\begin{matrix}
\frac{3}{4\pi}(R_{\rm max}^p)^{-3}\,,&r_{\rm vir}<r\lesssim R_{\rm max}^p\\	
0\,,&{\rm otherwise}
\end{matrix}
\right.\;.
\end{align}
Consequently, the ensemble-averaged tidal torque acting on a cluster is given by:
\begin{align}
\langle\tau^2\rangle^{1/2}=\frac{27}{40\sqrt{5}}\left(\frac{GM_{\rm cl}^2}{r_{\text{vir}}}\right)\left(C\xi_\alpha\right)^{-1/2}\left(\frac{a_{\rm dec}}{a}\right)^{3/2}\left[\left(1-\frac{r_2^2}{r_1^2}\right)^2+\left(1-\frac{r_3^2}{r_1^2}\right)^2+\left(\frac{r_2^2}{r_1^2}-\frac{r_3^2}{r_1^2}\right)^2\right]^{1/2}\,,
\end{align}
where we have used $R_{\rm max}^p(a_{\rm dec})\simeq(4/3)\left(C\xi_\alpha\right)^{1/3}r_{\text{vir}}$ and identified $r_{\text{vir}}=r_1$ as the major axis of the ellipsoid. Since $\langle\tau^2\rangle^{1/2}\propto a^{-3/2}$, the tidal torque weakens with cosmic expansion, indicating that most of the spin is accumulated shortly after the clusters decouple from the Hubble flow.

The final spin of a cluster can be estimated by integrating the ensemble-averaged tidal torque over the time interval during which the cluster remains dynamically responsive to the tidal field of neighboring clusters. 
The upper limit of this interval is approximated by the typical time before the cluster fully merges into SMBH:
\begin{align}
J_{\text{cl}}=\int^{t_{\text{merg}}}_{t_{\text{dec}}}\langle\tau^2\rangle^{1/2}{\rm\,d}t
\end{align}
where $t_{\rm dec}$ is the decoupling time and $t_{\rm merg}\lesssim t_{\rm rm}$ denotes the typical merging time. After performing the time-dependent integral
\begin{align}
\int^{t_{\rm merg}}_{t_{\rm dec}}\frac{a_{\rm dec}^{3/2}}{a^{3/2}}{\rm\,d}t
=\frac{2}{\sqrt{8\pi G\rho_{\rm eq}/3}}\left(0.85f_{\rm pbh}\xi_\alpha\right)^{-3/2}\ln\left(\frac{\sqrt{1+a_{\rm merg}/a_{\rm eq}}+\sqrt{a_{\rm merg}/a_{\rm eq}}}{\sqrt{1+1/(0.85f_{\rm pbh}\xi_\alpha)}+\sqrt{1/(0.85f_{\rm pbh}\xi_\alpha)}}\right)
\end{align}
with $a_{\rm eq}\simeq1/3401$, and $a_{\rm merg}\sim1/10$ around redshift $z\sim9$, we estimate the dimensionless spin parameter $a_s\equiv cJ_{\text{cl}}/GM_{\text{cl}}^2$ of the cluster as:
\begin{align}
a_s&\simeq5.6\left(\frac{f_{\rm pbh}}{10^{-5}}\right)^{-1/2}\left(\frac{\xi_{\alpha}}{10^6}\right)^{-1}\left(\frac{C}{20}\right)^{-1/6}\left(\frac{r_{\text{cl}}}{10\,\text{kpc}}\right)^{-1}
\left[\left(1-\frac{r_2^2}{r_1^2}\right)^2+\left(1-\frac{r_3^2}{r_1^2}\right)^2+\left(\frac{r_2^2}{r_1^2}-\frac{r_3^2}{r_1^2}\right)^2\right]^{1/2}\;.
\end{align}
While clusters are also subject to tidal torques induced by background density fluctuations, we neglect these contributions as they are subdominant compared to the torques from neighboring clusters for the parameter range considered.

According to the peak theory, the non-sphericity of the long-wavelength curvature perturbation can be characterized by its ellipticity $e$ and prolateness $p$, which follow a statistical distribution determined by the power spectrum of the initial perturbations and the peak value\;\cite{Bardeen:1985tr,Sheth:1999su,DeLuca:2019buf,Escriva:2024lmm,Yoo:2024lhp}.  
We assume a monochromatic mass distribution and calculate the corresponding peak value using the two-point correlation function. The axis ratios are then given by
\begin{align}
\frac{r_2}{r_1}=\sqrt{\frac{1-3\bar{e}+\bar{p}}{1+3\bar{e}+\bar{p}}}\,,\quad{\rm and}\quad \frac{r_3}{r_1}=\sqrt{\frac{1-3\bar{e}+\bar{p}}{1-2\bar{p}}}
\end{align}
with the average values $\bar{e}\simeq0.09$ and $\bar{p}\simeq 0$ as our inputs.

