\subsection{}

Now we introduce our setup.

Throughout the paper, we let $\Gu:=\SU(n+1)$ and $\Gc:=\SL{n+1}(\C)$ and denote their Lie algebras by $\g_0:=\mathfrak{su}(n+1)$ and $\g:=\mathfrak{sl}_{n+1}(\C)$ for brevity.
We often identify the dual space $\g^{*}$ with $\g$ by the trace form $B$:
\begin{equation}
\label{e:isom_g_and_gstar}
	B(X,Y) = \trace{(X Y)} \quad (X,Y \in \g).
\end{equation}
Note that the form $B$ is negative definite on $\g_{0}=\mathfrak{su}(n+1)$.
%
Let $Q$ be a maximal parabolic subgroup of $\Gc$ given by
\[
	Q =\left\{ \begin{bmatrix} a & 0 \\ c & d \end{bmatrix} \in \Gc ; a \in \GL{n}(\C), c \in \Mat{1 \times n}(\C), d \in \C^{\times} \right\},
\]
and $\mathfrak q$ the Lie algebra of $Q$ given by
\[
	\mathfrak q = \left\{ \begin{bmatrix} a & 0 \\ c & d \end{bmatrix} \in \g ; a \in \Mat{n \times n}(\C), c \in \Mat{1 \times n}(\C), d \in \C \right\}.
%	\mathfrak q = \left\{ \begin{bmatrix} a_{11} & 0 \\ a_{21} & a_{22} \end{bmatrix} \in \g ; a_{11} \in \Mat{n \times n}(\C), a_{21} \in \Mat{1 \times n}(\C), a_{22} \in \C \right\}.
\]
Thus $\Gc/Q$ is isomprphic to the comlex projective space 
\[
	\CP^n=\big\{ [\zeta_0: \zeta_1: \dots :\zeta_n]; \tp{(\zeta_0,\zeta_1,\dots,\zeta_n)} \in \C^{n+1} \backslash \{0\} \big\}
%	\CP^n=\big\{ [\zeta_1: \zeta_2: \dots :\zeta_{n+1}]; \tp{(\zeta_1,\zeta_2,\dots,\zeta_{n+1})} \in \C^{n+1} \backslash \{0\} \big\}
\]
by $g.e_{Q} \leftrightarrow [g.e_{n}]$, where $e_{Q}$ is the origin of $\Gc/Q$ and $e_{n}=\tp{(0,\dots,0,1)}$.


Let $\lambda \in \g^{*}$ be a character (i.e.~one-dimensional representation) of $\mathfrak q$ which sends 
\( \left[\begin{smallmatrix} a & 0 \\ c & d \end{smallmatrix}\right] \) to $-s d$ 
%\( \left[\begin{smallmatrix} a_{11} & 0 \\ a_{21} & a_{22} \end{smallmatrix}\right] \) to $-s a_{22}$ 
for $s \in \C$,
and $\lambda^{\vee}$ the corresponding element of $\g$ under the identification $\g^{*} \simeq \g$ via the bilinear form $B$ given by \eqref{e:isom_g_and_gstar}:  
\[
	\lambda^{\vee} = \frac{s}{n+1} \begin{bmatrix} 1_{n} & 0 \\[2pt] 0 & - n \end{bmatrix} \in \g. 
\]
The $\Gc$-orbit ${\mathscr O}^c_{\lambda}:=\Gc \cdot \lambda$ of $\lambda$ under the coadjoint action is canonically isomorphic to $\Gc / L$, where
\begin{equation}
	L = \left\{ \begin{bmatrix} a & 0 \\ 0 & d \end{bmatrix} \in \Gc ; a \in \GL{n}(\C), d \in \C^{\times} \right\}
\end{equation}
is the Levi factor of $Q$.
Let $\mathfrak l$ be the Lie algebra of $L$, $\u^{-}$ the nilradical of $\q$, and $\u$ the opposite of $\u^{-}$.
Then we have the following decompositions:
\begin{equation}
\label{e:triangular_decomp}
	\q = \mathfrak l \oplus \u^{-}   \quad \text{and} \quad  \g = \u \oplus \mathfrak l \oplus \u^{-}.
\end{equation}
Note that $\u$ and $\u^{-}$ are abelian and isomorphic to $\C^{n}$. 
Denoting the analytic subgroups of $\u^{-}$ and $\u$ by $U^{-}$ and $U$ respectively, we see that
\begin{equation}
	Q = L U^{-} = U^{-} L,
\end{equation}
and that $\Gc$ has an open covering: % $\{ \sigma U Q \}_{\sigma \in W/W_\lambda}$:
\begin{equation}
\begin{aligned}
	\Gc &= \bigcup_{\sigma \in W/W_{\lambda}} \sigma U Q, 
\end{aligned}
\end{equation}
where $W$ is the Weyl group of $\Gc$ and $W_{\lambda}$ the isotropy subgroup of $\lambda$ in $W$. 
%
We fix a representative $\dot \sigma \in \Gu$ of each element $\sigma \in W/W_{\lambda}$ once and for all, and identify $\sigma$ with $\dot \sigma$.
In fact, as the representatives, we can take the signed permutation matrices of determinant one that correspond to cyclic permutations $(\alpha,\alpha+1,\dots,n)$,
%$\left( \begin{smallmatrix} 0 & 1 & \cdots & \alpha & \cdots & n \\ 0 & 1 & \cdots & \alpha+1 & \cdots  & \alpha \end{smallmatrix} \right)$ \draftcomment{<--? (to be verified)}, 
which we denote by $\dot \sigma_{\alpha}$ for $\alpha=0,1,\dots,n$.


We parametrize elements of $U$ and $U^-$ as
\begin{equation}
	u_z = \begin{bmatrix} 1 & z \\ 0 & 1 \end{bmatrix} \in U
	\quad	\text{and}	\quad
	u_w^- = \begin{bmatrix} 1 & 0 \\ w & 1 \end{bmatrix} \in U^-,
\end{equation}
where $z \in \C^{n}=\Mat{n \times 1}(\C)$ (column vector) and $w \in (\C^{n})^{*}=\Mat{1 \times n}(\C)$ (row vector).










\section{Twisted Cotangent Bundle}

As we mentioned earlier, the $\Gc$-orbit ${\mathscr O}^c_{\lambda}$ is holomorphically isomorphic to the twisted cotangent bundle of $\CP^n$, which is an affine bundle on $\CP^n$ and is denoted by $(T^* \CP^n)_\lambda$.
In this section, we first recall its construction (see \cite{Donaldson02_holomorphic_discs} \cite{equiv_sympl} for details), and then introduce a $G$-invariant function on $(T^* \CP^n)_\lambda$.


Let $\{ U_\alpha \}_{\alpha=0,1,\dots,n}$ be the standard open covering of $\CP^n$, i.e. 
\begin{align*}
	U_\alpha &= \big \{ [ \zeta_{0}:\zeta_{1}: \dots : \zeta_{n} ] \in \CP^n ; \zeta_{\alpha} \ne 0 \big \}  %\\
%		&= \{ (z_{\alpha}^1, z_{\alpha}^2, \dots, z_{\alpha}^{\alpha-1}, 1, z_{\alpha}^{\alpha}, \dots, z_{\alpha}^{n}); \} \simeq \C^{n}.
\end{align*}
and $\varphi_\alpha : U_\alpha \xrightarrow{\sim} \C^n$ the holomorphic local chart induced from the homeomorphism $U_\alpha \simeq \sigma_\alpha U Q/Q$.
%\[
%	\varphi_{\alpha} ( [Z_{1}: \cdots: Z_{n+1}] ) = (Z_{1}/Z_{\alpha}, \dots, Z_{\alpha-1}/Z_{\alpha},1,Z_{\alpha+1}/Z_{\alpha},\dots,Z_{n+1}/Z_{\alpha}).
%\]
Introducing holomorphic coordinates $(z_\alpha,\xi_\alpha) = (z_{\alpha, 1}, \dots, z_{\alpha, n}, \xi_{\alpha, 1}, \dots, \xi_{\alpha, n} )$ on the trivial cotangent bundle $T^* U_\alpha$,
we denote a point of $T^* U_\alpha$ by %$( z_\alpha, \xi_\alpha )$ or
\[
	\xi_\alpha\, \rmd z_\alpha := \sum_{i=1}^{n} \xi_{\alpha, i}\, \rmd z_{\alpha, i}.
\]
In our setting, it is natural to regard $z_{\alpha}$ as a column vector $\tp{(z_{\alpha,1},\dots,z_{\alpha,n})}$ and $\xi_{\alpha}$ as a row vector $(\xi_{\alpha,1},\dots,\xi_{\alpha,n})$.


Now we glue the cotangent bundles $\{ T^* U_\alpha \}_{\alpha=0,1,\dots,n}$ on the double intersection $U_\alpha \cap U_\beta$ by an equivalence relation:
\begin{equation}
	(T^* \CP^n)_\lambda := \bigsqcup_{\alpha = 0}^{n} T^* U_\alpha / \sim,
\end{equation}
where a point $\xi_\beta\, \rmd z_\beta$ in $T^* U_\beta|_{U_\alpha \cap U_\beta}$ is defined to be equivalent to 
a point $\xi_\alpha\, \rmd z_\alpha$ in $T^* U_\alpha|_{U_\alpha \cap U_\beta}$ if and only if the following two conditions hold:
\begin{align}
	z_\beta &= ( \varphi_\beta \circ \varphi_\alpha^{-1}) (z_\alpha),
		\label{e:z_alpha and z_beta}
	\\
	\xi_\beta\, \rmd z_\beta &= \xi_\alpha\,\rmd z_\alpha + \<\lambda,\rmd t_{\alpha \beta} {t_{\alpha \beta}}^{-1}\>.
		\label{e:xi_alpha and xi_beta}
\end{align}
Here $\<\cdot,\cdot\>$ denotes the pairing between $\g^*$ and $\g$, and $t_{\alpha \beta}$ is a unique element of $L$ determined by the relation  
%
\begin{equation}
\label{e:xi_alpha and xi_beta 2}
	\sigma_{\beta}\, u_{z_\beta} u^{-}_{w_\beta}. e_L = \sigma_{\alpha}\, u_{z_\alpha} u^{-}_{w_\alpha}. e_L,
%	\sigma_{\alpha} u_{z_\alpha} u^{-}_{w_\alpha} L = \sigma_{\beta} u_{z_\beta} u^{-}_{w_\beta} L 
\end{equation}
where $e_{L}$ denotes the origin of $\Gc / L$, and $w_\alpha,\, w_\beta \in (\C^n)^*$ are related to $\xi_\alpha, \, \xi_\beta \in (\C^n)^*$ by $\xi_{\alpha} = -s w_{\alpha},\,\xi_{\beta} = -s w_{\beta}$.
In fact, Eq.~\eqref{e:xi_alpha and xi_beta 2} implies a unique existence of $t_{\alpha \beta} \in L$ that satisfies 
$\sigma_{\beta} u_{z_{\beta}} u^{-}_{w_{\beta}} = \sigma_{\alpha} u_{z_{\alpha}} u^{-}_{w_{\alpha}} t_{\alpha \beta}$ under the condition \eqref{e:z_alpha and z_beta}.



We denote the canonical projection by $\pi_\lambda$:
\begin{equation}
	\pi_\lambda: (T^* \CP^n)_{\lambda} \to \CP^n.
\end{equation}
By definition, $\pi_\lambda^{-1}(U_\alpha) = T^* U_\alpha$, $\alpha=0,1,\dots, n$.


In what follows, we will denote the twisted cotangent bundle by $\ourZ$ for brevity:
\begin{equation}
\label{e:twd ctg bdle for short}
	\ourZ := (T^* \CP^n)_{\lambda}.
\end{equation}
%
Since the second term in the right-hand side of \eqref{e:xi_alpha and xi_beta} is exact, taking the exterior derivative of its both sides, one can equip $\ourZ$ with a holomorphic symplectic form $\omega_{+}$ of type $(2,0)$ given in terms of the local coordinates%
		\footnote{In what follows, we suppress the index $\alpha$ if it is clear in which coordinate patch $U_\alpha$ we are working.
		}
$(z,\xi)=(z_1,\dots,z_n,\xi_1,\dots,\xi_n)$ by
\begin{equation}
\label{e:local expression of omega_+}
	\omega_{+}|_{\pi_\lambda^{-1}(U_\alpha)} = \sum_{i=1}^{n} \rmd z_i \wedge \rmd \xi_i.
\end{equation}
Similarly, $\ourZ$ is equipped with an anti-holomorphic symplectic form $\omega_-$ on $\ourZ$ of type $(0,2)$ given by
\begin{equation}
	\omega_{-}|_{\pi_\lambda^{-1}(U_\alpha)} =\sum_{i=1}^{n} \rmd \bar z_i \wedge \rmd \bar \xi_i.
\end{equation}
%
We remark that there is a natural holomorphic $\Gc$-action $\gamma_{\!\lambda}$ on $\ourZ$ covering the left translation on $\Gc / Q \simeq \CP^n$, i.e.~the following diagram commutes for all $g \in \Gc$: 
%\begin{figure}[hb]
\begin{equation}
\begin{tikzcd}
	\ourZ= (T^* \CP^n)_{\lambda} \ar[r,"","\gamma_{\!\lambda}(g)"]	\ar[d,"\pi_\lambda"']	& \ourZ= (T^* \CP^n)_{\lambda}	\ar[d,"\pi_\lambda"] \\
	\CP^n \ar[r,"","g."]												& \CP^n.
\end{tikzcd}
\end{equation}
%\end{figure}
Note also that $\gamma_{\!\lambda}$ is Hamiltonian with respect to $\omega_+$, and that there is an anti-holomorphic Hamiltonian action with respect to $\omega_-$ as well.



Let $\mu_+$ and $\mu_-$ denote the moment maps $\ourZ \to \g^*$ with respect to $\omega_+$ and $\omega_-$ respectively.
%(Darboux coordinates) 
Then $\mu_+$ provides a holomorphic $\Gc$-equivariant symplectic isomorphism from $\ourZ$ onto ${\mathscr O}^c_{\lambda}$:
\begin{equation}
	\mu_+ : \ourZ \xrightarrow{\sim} {\mathscr O}^c_\lambda,
\end{equation}
where the symplectic structure on ${\mathscr O}^c_{\lambda}$ is given by the Kirillov-Kostant-Souriau form (\cite[Theorem 3.14]{equiv_sympl}).
Explicitly, $\mu_+$ is given on $\pi_\lambda^{-1}(U_\alpha)$ in terms of the local coordinates $(z,\xi)$ by
\begin{equation}
	\mu_+|_{\pi_\lambda^{-1}(U_{\alpha})} (z,\xi) = \Ad^*(g) \lambda \quad \text{with} \quad g = \sigma_\alpha\, u_z u^-_w,
\end{equation}
where $\xi=-s w$.


\begin{proposition}
If we denote the moment maps $\mu_+,\,\mu_-: \ourZ \to \g^*$ followed by the identification $\g^* \simeq \g$ via the trace form $B$, also by the same notations,
then we have
\begin{equation}
	\mu_- = - \mu_+^{*},
%	\mu_- = - \mu_+^{\dagger},
\end{equation}
where ${}^{*}$ denotes the transpose conjugate of matrices.
%where ${}^{\dagger}$ denotes the hermitian conjugate of a matrix.
\end{proposition}
%Proof
\begin{proof} 
The proof is straightforward, and is left to the reader.
\end{proof}
%



Now we are ready to introduce our main player.
Namely, set 
\begin{equation}
\label{e:seed}
\begin{aligned}
	\tau &:= - B(\mu_+, \mu_-) + \frac{\abs{s}^2}{n+1}
		\\
		&= B(\mu_+, \mu_+^*) + \frac{\abs{s}^2}{n+1},
\end{aligned}
\end{equation}
which is given in terms of the local coordinates $(z,\xi)$ by
\begin{equation}
\label{e:local expression of seed}
	\tau |_{\pi_\lambda^{-1}(U_\alpha)} = ( \norm{z}^2 + 1 )( \norm{\xi}^2 + \abs{s - \xi z}^2 ),
\end{equation}
where we regard $z \in \C^n$ (column vector) and $\xi \in (\C^n)^*$ (row vector), and $\norm{\,\cdot\,}^2$ denotes the norm squared, i.e.~$\norm{z}^2=z^* z, \norm{\xi}^2=\xi \xi^*$.
Note that we need the constant term in \eqref{e:seed} to factorize the local expression of $\tau$ as in \eqref{e:local expression of seed}.


\begin{remark}
By definition, $\tau$ is a $\Gu$-invariant function on $\ourZ$ with values in $\R_{\geqsl 0}$; it takes its minimum $\abs{s}^2$ on the submanifold $\ourLSmfd$, where $\ourLSmfd$ is locally given by
\begin{equation}
\label{e:Laglangian submfd}
	\ourLSmfd|_{\pi_\lambda^{-1}(U_\alpha)}=\left\{ \frac{s \, z^* \rmd z}{1+\norm{z}^2} ; z \in U_\alpha \right\} \subset T^* U_\alpha.
\end{equation}
Note that $\ourLSmfd$ provides an example of the \emph{LS-submanifold} of $\ourZ$, i.e.~it is Lagrangian with respect to $\im \omega_+$ and symplectic with respect to $\re \omega_+$ (see \cite{Donaldson02_holomorphic_discs}).
One also notes that $\ourLSmfd$ corresponds to the $\Gu$-orbit $\mathscr O_\lambda$ of $\lambda$ under the isomorphism $\mu_+: \ourZ \to {\mathscr O}^c_\lambda$.
%
%In the framework of brane quantization, $\ourZ$ correspond
%\draftcomment{ Brane quantization \cite{Gukov11,Gukovwitten09}, e.g. prequantum line bundle}
\end{remark}





\section{Ricci-flat K{\"a}hler Metric}


Henceforth, we assume that $s \ne 0$.

In this section, we find Ricci-flat K\"ahler metrics on the twisted cotangent bundle $Z$ under an Ansatz.
Namely, for an $\R$-valued function $f \in C^\infty(\R)$ in a single variable, let us consider a 1-form $\beta$ on $\ourZ$ given by
\begin{equation}
\label{e:one-form}
	\beta := \frac{1}4 f(\tau)\, \rmd^c \tau = \frac{\ai}4 f(\tau) (\antidel \tau - \del \tau)
\end{equation}
and define a 2-form $\omega_I$ by $\omega_I:=\rmd \beta$, where $\tau \in C^\infty(\ourZ)$ is the $\Gu$-invariant function given by \eqref{e:seed}.
Note then that
\begin{equation}
\label{e:omega_I}
%\begin{aligned}
	\omega_I = \frac{\ai}2 (f(\tau) \del \antidel \tau + f'(\tau) \del \tau \wedge \antidel \tau)
%\end{aligned}
\end{equation}
is of type $(1,1)$, and satisfies
\begin{equation}
\label{e:omega & I}
	\omega_I (Iv,Iw)=\omega_I (v,w)  \quad (v,w \in \mathfrak X (\ourZ)),
\end{equation} 
where $I$ denotes the canonical complex structure on $\ourZ$.
Furthermore, one can see that $g^* \omega_I = \omega_I$ for all $g \in \Gu$ since $\tau$ is $\Gu$-invariant.


In what follows, we will be concerned with such functions $f \in C^\infty(\R)$ that satisfy
\begin{equation}
\label{e:positivity omega_I}
	\omega_I(v, I v) > 0
\end{equation}
for all nonzero $v \in \mathfrak X (\ourZ)$.
Let $g$ be the metric on $\ourZ$ whose fundamental $2$-form is $\omega_I$.
Namely, 
\begin{equation}
\label{e:def of metric g}
	g(v,w):=\omega_I ( v, I w) \quad (v,w \in \mathfrak{X}(\ourZ)).
\end{equation}
Then $(\ourZ,g,I)$ is a K\"ahler manifold if the condition \eqref{e:positivity omega_I} is satisfied.
In particular, $\omega_I$ is a symplectic form on $\ourZ$ (i.e.~non-degenerate on $\ourZ$).


\begin{remark}
\label{r:ansatz on beta}
It is clear from \eqref{e:xi_alpha and xi_beta} that if $\lambda$ tends to $0$ then our twisted cotangent bundle $\ourZ=(T^*\CP^n)_\lambda$ reduces to the cotangent bundle $T^*\CP^n$.
Kapustin and Saulina showed in \cite{KapustinSaulina09} that Eguchi-Hanson metric on $T^*\CP^1$, which is not only Ricci-flat but also hyperk\"ahler, is obtained if one takes $f(\tau)$ in \eqref{e:one-form} to be $(1+\tau)^{1/2}/\tau$.
This is the reason we assume the 1-form $\beta$ to be of the form given above.
%\draftcomment{%
%The reason we seek for the $\omega_{I}$ of the form above here. Refer to \cite{KapustinSaulina09} about Eguchi-Hanson metric
%}

\end{remark}


