%%%%%%% convention about index %%%%%%%%%%%%%%%
For the sake of space, we sometimes use the following convention about indices.
Namely, for $i=1,2,\dots,n$, we regard $\xi_i$ as the $(n+i)$-th coordinate:
\begin{equation}
\label{e:convention about idx}
	z_{n+i} := \xi_i.
\end{equation}
%
Under the convention \eqref{e:convention about idx}, let $g_{i \bar j}$, $i,j=1,2,\dots,2n$, denote (twice) the components of the metric $g$ in terms of local coordinates:
\begin{equation}
\label{e:local metric}
	g|_{\pi_\lambda^{-1}(U_\alpha)} = \frac12 \sum_{i,j=1}^{2n} g_{i \bar j}\, \rmd z_i \rmd \bar z_j
%	g|_{\pi^{-1}(U_\alpha)} = \frac12 \sum_{i,j} \big(  a_{z_i \bar z_j}\, \rmd z_i \rmd \bar z_j + a_{z_i \bar \xi_j}\, \rmd z_i \rmd \bar \xi_j 
%							+ a_{\xi_i \bar z_j}\, \rmd \xi_i \rmd \bar z_j + a_{\xi_i \bar \xi_j}\, \rmd \xi_i \rmd \bar\xi_j \big),
\end{equation}
and set 
\begin{equation}
\label{e:matrix corresponding to g}
	A_\alpha := (g_{i \bar j})_{i,j=1,2,\dots,2n} \in C^\infty(\pi_\lambda^{-1}(U_\alpha),\End(\C^{2n})).
\end{equation}





Recall that the Ricci form $\rho$ on the K\"ahler manifold $(\ourZ, g, I)$ with respect to the Levi-Civita connection is locally given by
\[
	\rho|_{\pi_\lambda^{-1}(U_\alpha)} = \ai\, \antidel \del \log \det A_\alpha. 
\]
The following theorem is a key to find Ricci-flat metrics. 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
% Theorem: ODE of Ricci flat Kaehler metric
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}
\label{t:ricci-flat}
The metric $g$ satisfies $\det A_\alpha = 1$ if and only if the function $f$ satisfies that
\begin{equation}
\label{e:ricci-flat eq}
	2 f'(\tau) f(\tau)^{2n-1} \tau^n (\tau - \tau_0) + f(\tau)^{2n} \tau^{n-1} (2\tau - \tau_0) = 1,
\end{equation}
where we set $\tau_{0}=\abs{s}^2$.
%\begin{equation}
%\label{e:cicci-flat eq}
%%	2 y' y^{2n-1} u^{n} (u - u_{0}) + y^{2n} u^{n-1} (2u - u_{0}) =1,
%\end{equation}
%where $y=f(u),\, y'=(\rmd/\rmd u) f(u)$ and $u_{0}=\abs{s}^{2}$.
\end{theorem}
%
\begin{proof}
By definition, the components $g_{i \bar j}$ are given by 
\begin{equation}
	g_{i \bar j} = f(\tau) \tau_{i, \bar j} + f'(\tau) \tau_{i} \tau_{\bar j}
\end{equation}
with $\tau_i:=\pd_{z_i} \tau, \, \tau_{\bar i}:=\pd_{\bar z_i} \tau$ and $\tau_{i, \bar j}:=\pd_{z_i} \pd_{\bar z_j} \tau$ for $i,j=1,2,\dots,2n$ under the convention \eqref{e:convention about idx}.
Setting $c:=f(\tau), c_1:=f'(\tau)$ for brevity and
\begin{align}
	\vec{a}_j &:= \tp{(\tau_{1, \bar j},\dots,\tau_{2n, \bar j})} \quad (j=1,2,\dots,2n), 
		\label{e:mat g by tau_xy}
	\\
	\vec{b} &:= \tp{(\tau_1,\dots,\tau_{2n})}, 
		\label{e:mat g by tau_x}
\end{align}
we write $A_\alpha$ as
\begin{equation}
\label{e:mat 4 metric g}
	A_\alpha 	= c ( \vec{a}_1, \vec{a}_2,\dots, \vec{a}_{2n} ) + c_1 ( \tau_{\bar 1} \vec{b}, \tau_{\bar 2} \vec{b},\dots, \tau_{\overline{2n}} \vec{b} ).
\end{equation}
%with
%\begin{align}
%\label{e:mat g 2}
%	A'_\alpha 	&= ( \vec{a}_1, \vec{a}_2,\dots, \vec{a}_{2n} ),  \\
%	A''_\alpha	&= ( \tau_{\bar 1} \vec{b}, \tau_{\bar 2} \vec{b},\dots, \tau_{\overline{2n}} \vec{b} ).
%\end{align}
Therefore,
\begin{equation}
	\det A_\alpha = c^{2n} \det(\vec{a}_1,\dots,\vec{a}_{2n}) 
				+ c^{2n-1} c_1 \sum_{k=1}^{2n}  \tau_{\bar k} \det (\vec{a}_1,\dots,\vec{a}_{k-1}, \hspace{-3pt}\overset{k\text{-th}}{\vec{b}}\hspace{-3pt}, \vec{a}_{k+1},\dots,\vec{a}_{2n}).
\end{equation}
Now the theorem follows from Propositions \ref{p:det mat tau_xy} and \ref{p:det mat tau_x tau_y} below.
\end{proof}




In the proof of the propositions below, we will use the following notations: 
\begin{equation}
\begin{aligned}
\label{e:psi1 and psi2}
	\psi_1 &:= \norm{z}^2 + 1, \\
	\psi_2 &:= \norm{\xi}^2 + \abs{s_{xz}}^2, \\
	s_{xz} &:= s - \xi z
\end{aligned}
\end{equation}
with $z=\tp{(z_1,z_2,\dots,z_n)} \in \C^n,\, \xi=(\xi_1,\xi_2,\dots,\xi_n) \in (\C^n)^*$.
%
Then, it is immediate from the local expression \eqref{e:local expression of seed} of $\tau$ to show that
\begin{equation}
\label{e:tau_x}
\begin{aligned}
	& \tau_{i}  = \psi_2\, \bar z_i -\psi_1 \bar s_{xz}\, \xi_i,
		\\
	& \tau_{n+i} = \psi_1 (\bar \xi_i - \bar s_{xz}\, z_i),
\end{aligned}
\end{equation}
for $i=1,\dots,n$, and
\begin{equation}
\label{e:tau_xy}
\begin{aligned}
	& \tau_{i, \bar j}	= \psi_2\, \delta_{ij} - s_{xz}\, \bar z_i \bar \xi_j - \bar s_{xz}\, \xi_i z_j + \psi_1\, \xi_i \bar \xi_j,
		\\
	& \tau_{i, \overline{n+j}} 	= \psi_1\, \xi_i \bar z_j + \bar z_i \xi_j - s_{xz}\, \bar z_i \bar z_j,
		\\
	& \tau_{n+i,\bar j}			= \psi_1\, z_i \bar \xi_j + \bar \xi_i z_j - \bar s_{xz}\, z_i z_j,
		\\
	& \tau_{n+i, \overline{n+j}} = \psi_1 ( \delta_{ij} + z_i \bar z_j ) 
\end{aligned}
\end{equation}
for $i,j=1,\dots,n$, where $\delta_{ij}$ denotes the Kronecker delta.



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
% Proposition: determinant of the metric component matrix 1
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proposition}
\label{p:det mat tau_xy}
Let $\vec{a}_i$ $ $(i=1,2,\dots,2n$)$ be given by \eqref{e:mat g by tau_xy}.
Then one has
\begin{equation}
	\det(\vec{a}_1,\vec{a}_2,\dots,\vec{a}_{2n}) = \tau^{n-1} (2\tau - \tau_0), 
	\label{e:mat_cc}
\end{equation}
\end{proposition}
%
%
\begin{proof}
Let us write the matrix $(\vec{a}_1,\vec{a}_2,\dots,\vec{a}_{2n})$ in the block form: 
\begin{equation}
\label{e:block form tau_xy}
	(\vec{a}_1,\vec{a}_2,\dots,\vec{a}_{2n}) =: \begin{bmatrix} a_{11} & a_{12} \\ a_{21} & a_{22} \end{bmatrix}
\end{equation}
with $a_{ij} \in \Mat{n \times n}(\C)$ ($i,j=1,2$)%
	\footnote{To be precise, each block $a_{ij}$ is a $C^\infty$-function taking values in $\Mat{n \times n}(\C)$; 
				we will use this kind of abbreviation below.}%
.
Then, it follows from \eqref{e:tau_xy} that%
	\footnote{It would be more comprehensible to introduce bra- and ket-vectors and denote $\bar z\, \bar \xi$ by $|\bar z \> \<\bar \xi|$ etc.
				However, we will adopt a bit awkward notation to keep expressions simple.}
\begin{equation}
\label{e:submat cc}
\begin{aligned}
	a_{11} &= \psi_2 1_n - s_{xz}\, \bar z \, \bar \xi - \bar s_{xz} \tp{\xi} \tp{z} + \psi_1 \tp{\xi} \, \bar \xi,	\\
	a_{12} &= \psi_1 \tp{\xi} \, z^* + \bar z \, \xi - s_{xz} \, \bar z \, z^*, \\
	a_{21} &= \psi_1 z \, \bar \xi + \xi^* \tp{z} - \bar s_{xz} \, z \, \tp{z}, \\
	a_{22} &= \psi_1 (1_n + z \, z^*).
\end{aligned}
\end{equation}
Note in particular that
\begin{equation}
\label{e:hermiteness mat cc}
	{a_{11}}^*=a_{11}, \quad a_{21}={a_{12}}^* \quad \text{and} \quad {a_{22}}^*=a_{22},
\end{equation}
which also follows from the definition.%, of course.



The matrix decomposition
\begin{equation}
\label{e:mat decomp UL}
\begin{aligned}
	\begin{bmatrix} a_{11} & a_{12} \\[1.5pt] a_{21} & a_{22} \end{bmatrix} 
		&= \begin{bmatrix} 1_n & a_{12}\, {a_{22}}^{-1}  \\ 0 & 1_n \end{bmatrix} 
				\begin{bmatrix} a_{11} - a_{12}\, {a_{22}}^{-1}\, a_{21} & 0 \\ a_{21} & a_{22} \end{bmatrix}
\end{aligned}
\end{equation}
implies that 
\[
	\det (\vec{a}_1,\vec{a}_2,\dots,\vec{a}_{2n})=\det(a_{11} - a_{12}\, {a_{22}}^{-1}\, a_{21}) \det a_{22}.
\]
Now, using \eqref{e:1/(1+rank-one mat)} in Lemma \ref{l:1/(1+rank-two mat)},
one obtains
\begin{equation}
\label{e:1/a_22}
	{a_{22}}^{-1} = {\psi_1}^{-1} \big( 1_n - {\psi_1}^{-1} z z^* \big),
\end{equation}
from which and \eqref{e:submat cc}, it follows that
%\begin{equation}
\begin{align}
	a_{11} - a_{12} {a_{22}}^{-1} a_{21} 
		&= \psi_2 1_n + \tp{\xi} \bar \xi - (\psi_2 {\psi_1}^{-1} - \abs{s}^2 {\psi_1}^{-2}) \bar z \tp{z} - s {\psi_1}^{-1} \bar z \, \bar \xi - \bar s {\psi_1}^{-1} \tp{\xi} \tp{z}
			\notag	\\
		&= \psi_2 1_n + \tp{\xi} \big( \bar \xi - \bar s {\psi_1}^{-1} \tp{z} \big) + \bar z \big( m \tp{z} - s {\psi_1}^{-1} \bar \xi \big),
			\label{e:a_11 etc}
\end{align}
%\end{equation}
where we set $m:={\psi_1}^{-2} (\abs{s}^2 - \psi_1 \psi_2)$.
To apply Lemma \ref{l:det of 1+rank2mat} to \eqref{e:a_11 etc}, set
\begin{align*}
	Z_1 &= \tp{\xi}, & \tp{\,W_1} &= \bar \xi - \bar s {\psi_1}^{-1} \tp{z}, 
		\\
	Z_2 &=\bar z, 	& \tp{\,W_2} &= m \tp{z} - s {\psi_1}^{-1} \bar \xi.
\end{align*}
Then one finds that
\begin{align*}
	\< W_1,Z_1 \> &= \norm{\xi}^2 - \bar s {\psi_1}^{-1} \xi z,	& \< W_1,Z_2 \> &= \overline{\xi z} - \bar s {\psi_1}^{-1} \norm{z}^2,
		\\
	\< W_2,Z_1 \> &= m\, \xi z - s {\psi_1}^{-1} \norm{\xi}^2,	& \< W_2,Z_2 \> &= m \norm{z}^2 - s {\psi_1}^{-1} \overline{\xi z},
\end{align*}
and hence, 
\begin{align*}
	\trace \Lambda &= \norm{\xi}^2 + m \norm{z}^2 -\bar s {\psi_1}^{-1} \xi z - s {\psi_1}^{-1} \overline{\xi z},
		\\
	\det \Lambda &= {\psi_1}^{-1} \psi_2 ( \abs{\xi z}^2 - \norm{\xi}^2 \norm{z}^2 )
\end{align*}
in the notation of Lemma \ref{l:det of 1+rank2mat}, \eqref{e:2by2 mat}.
Thus, in view of \eqref{e:psi1 and psi2}, one has
\begin{align*}
	\det & (a_{11} -  a_{12}\, {a_{22}}^{-1}\, a_{21})	
			\\
		&= {\psi_2}^{n-2} \Big( {\psi_2}^2 + \psi_2 \big( \norm{\xi}^2 + m \norm{z}^2 - {\psi_1}^{-1} (\bar s\, \xi z + s\, \overline{\xi z}) \big) + \psi_2 {\psi_1}^{-1} (\abs{\xi z}^2 - \norm{\xi}^2 \norm{z}^2) \Big)
			\\
		&= {\psi_2}^{n-1} \Big( {\psi_2} + \psi_1^{-1} \big( \norm{\xi}^2 + \abs{s}^2 - (\bar s\, \xi z + s\, \overline{\xi z}) + \abs{\xi z}^2 \big) - \abs{s}^2 {\psi_1}^{-1} + m \norm{z}^2 \Big)
			\\
		&= {\psi_2}^{n-1} \bigg( \psi_2 \Big( 1 + \frac1{\psi_1}-\frac{\norm{z}^2}{\psi_1} \Big) + \frac{\abs{s}^2}{\psi_1} \Big(\frac{\norm{z}^2}{\psi_1} - 1 \Big) \bigg) 
			\\
		&= {\psi_1}^{-2} {\psi_2}^{n-1} ( 2 \psi_1 \psi_2 - \abs{s}^2 )
\end{align*}
and
\begin{equation*}
	\det a_{22} = {\psi_1}^n \det(1_n + z z^*) = {\psi_1}^{n+1}.
\end{equation*}
Therefore, one obtains that
\begin{align*}
	\det (\vec{a}_1,\vec{a}_2,\dots,\vec{a}_{2n}) &= {\psi_1}^{n-1} {\psi_2}^{n-1} ( 2 \psi_1 \psi_2 - \abs{s}^2 )
		\\
			&= \tau^{n-1} ( 2 \tau - \tau_0 ).
\end{align*}
This completes the proof.
\end{proof}



