\section{Hyperk\"ahler Metric}

%In this section, we will focus on the solution $f(\tau)$ with $a=0$ in \eqref{e:ricci-flat sol}, i.e.~the solution given by
%\begin{equation}
%\label{e:hk_sol}
%	f(\tau) = \tau^{-1/2}.
%\end{equation}

%\draftcomment{Definition of hyperk\"ahler manifold and the lemma on the integrability of $I,J,K$ by Hitchin here ?}

In this section, we pick out a hyperk\"ahler metric of the Ricci-flat metric obtained in the previous section.
First, we recall the definition of a hyperk\"ahler manifold and a lemma due to Hitchin \cite{Hitchin87_monopole}:
\begin{definition}
Let $X$ be a $4n$-dimensional manifold.
Then a \emph{hyperk\"ahler structure} of $X$ consists of a Riemannian metric $g$ and a triple of almost complex structures $I,J,K$ satisfying the following conditions:
\begin{enumerate}{}{\setlength{\leftmargin}{10pt}}
\item
The metric $g$ is Hermitian with respect to all $I,J,K$:
\begin{equation}
\label{e:hermitian}
	g(Iv, Iw) = g(Jv, Jw) = g(Kv, Kw) = g(v,w)
\end{equation}
for $v,w \in {\mathfrak X}(X)$;

\item
The triple $(I,J,K)$ satisfies the quaternion identities: 
\begin{equation}
\label{e:quaternion}
	I^2 = J^2 = K^2 = IJK = -1.
\end{equation}
Moreover, the endomorphisms $I,J,K$ are covariant constant:
\begin{equation}
\label{e:covariant constant}
	\nabla I = \nabla J = \nabla K = 0,
\end{equation}
where $\nabla$ denotes the covariant derivative of the Levi-Civita connection of $g$.
\end{enumerate}

\end{definition}

Note that the condition \eqref{e:covariant constant} ensures the integrability of $I,J,K$, which is equivalent to their closedness of the associated 2-forms by the following lemma.

\begin{lemma}[\cite{Hitchin87_monopole}]
Let $(X,g)$ be a Riemannian manifold equipped with skew-adjoint endomorphisms $I,J,K$ of the tangent bundle $TX$ satisfying \eqref{e:hermitian} and \eqref{e:quaternion}.
Then $(X,g,I,J,K)$ is hyperk\"ahler if and only if the 2-forms $\omega_I, \omega_J, \omega_K$ that are determined by \eqref{e:2-forms} below are closed:
\begin{equation}
\label{e:2-forms}
	\omega_I(v,w) := g(Iv,w), \quad \omega_J(v,w) := g(Jv,w), \quad \omega_K(v,w) := g(Kv,w)  
\end{equation}
for $v,w \in {\mathfrak X}(X)$.
\end{lemma}



Now, we return to our case.
%
Let $\omega_J$ (resp. $\omega_K$) be the real part (resp. the imaginary part) of the holomorphic symplectic form $\omega_+$ whose local expression is given by \eqref{e:local expression of omega_+}:
\begin{equation}
	\omega_{+} = \omega_J + \ai\, \omega_K.
\end{equation}
Under the convention \eqref{e:convention about idx}, they are given by
\begin{align}
	\omega_J|_{\pi^{-1}_\lambda(U_\alpha)} &= \frac12 \sum_{i=1}^n ( \rmd z_i \wedge \rmd z_{n+i} + \rmd \bar z_i \wedge \rmd \bar z_{n+i} ),	\\
	\omega_K|_{\pi^{-1}_\lambda(U_\alpha)} &= -\frac{\ai}2 \sum_{i=1}^n ( \rmd z_i \wedge \rmd z_{n+i} - \rmd \bar z_i \wedge \rmd \bar z_{n+i} )
\end{align}
in terms of local coordinates.
Similarly, $\omega_I$ is locally given by 
\begin{equation}
	\omega_I|_{\pi^{-1}_\lambda(U_\alpha)} = \frac{\ai}2 \sum_{i,j=1}^{2n} g_{i \bar j}\, \rmd z_i \wedge \rmd \bar z_j.
\end{equation}




For a non-degenerate bilinear form $\omega$ on $T_p \ourZ$, $p \in \ourZ$, let $\omega^\flat$ denote the isomorphism from $T_p \ourZ$ onto $T_p^* \ourZ$ defined by $\omega^\flat(v)=\iota_v \omega$ with $\iota$ the interior product, i.e.
\[
	\omega^\flat(v)(w) =\omega (v,w) \quad (v,w \in T_p \ourZ).
\]
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
% Definition: complex structures J & K
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{definition}
\label{d:cpx str J and K}
Let $J$ and $K$ be elements of $\Gamma(\End(T \ourZ))$ determined by $\omega_I,\,\omega_J$ and $\omega_K$ as follows:
\begin{equation}
	J = (\omega^\flat_I)^{-1} \circ \omega^\flat_K, \quad 
	K = (\omega^\flat_J)^{-1} \circ \omega^\flat_I.
\end{equation}
Furthermore, we also denote the canonical extensions of $I,J,K \in \Gamma(\End(T \ourZ))$ to $\Gamma(\End(\Tc \ourZ))$ by the same letters respectively, where $\Tc \ourZ := T \ourZ \otimes \C$.
\end{definition}




It is immediate to show that if $I^2 = J^2 = K^2 = IJK = -1$, then
\begin{equation}
\label{e:omega_J and omega_K}
	\omega_J(v,w) = g( Jv, w ), \quad \omega_K( v,w ) = g( Kv, w ),
\end{equation}
and
\begin{equation}
\label{e:hermitiancy of g wrt J and K}
	g(Jv, Jw) = g(Kv, Kw) = g(v,w)
\end{equation}
for $v,w \in {\mathfrak X}(\ourZ)$.
Needless to say, one has
\begin{equation}
\label{e:hermitiancy of g wrt I}
	g(Iv, Iw) = g(v,w) 	\quad ( v,w \in {\mathfrak X}(\ourZ) )
\end{equation}
by definition.


Under the convention \eqref{e:convention about idx}, let us introduce a basis $\Sigma$ for $\Tc \ourZ|_{\pi_\lambda^{-1}(U_\alpha)}$ given by
\[
	\Sigma = \big\{ \del_1, \dots, \del_{2n}, \antidel_{1},\dots, \antidel_{2n} \big\},
\]
where $\del_i := \del_{z_i}, \antidel_{i} := \del_{\bar z_i}$ $(i=1,\dots,2n)$.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
% Proposition: J^2 = K^2 = -1
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proposition}
\label{p:J^2 and K^2}
Let $A_\alpha=(g_{i \bar j})_{i,j=1,\dots,2n}$ given by \eqref{e:matrix corresponding to g} with $f(\tau)$ general, and $J,K \in \Gamma(\End(\Tc \ourZ))$ be as in Definition \ref{d:cpx str J and K}.
Then one has $J^2 = K^2 = -1$ if and only if 
\begin{equation}
\label{e:condition Sp2n}
	\tp{A_\alpha} S A_\alpha = S, 
\end{equation}
where $S=\Big[ \begin{smallmatrix} 0 & 1_n \\[1.8pt] -1_n & 0\end{smallmatrix} \Big]$.
\end{proposition}
%
\begin{proof}
Denote by $\mathbb J$ and $\mathbb K$ the $4n \times 4n$ matrices that correspond to $J$ and $K$ with respect to the basis $\Sigma$ for $\Tc \ourZ|_{\pi_\lambda^{-1}(U_\alpha)}$.
Then one can show that they are given by
\begin{subequations}
\label{e:matrices J and K}
%\begin{equation}
%\label{e:matrices J and K}
\begin{align}
	\mathbb J &= \begin{bmatrix} 0 & \tp{A^{-1}_\alpha} S^{-1} \\ A^{-1}_\alpha S^{-1} & 0 \end{bmatrix},
		\label{e:matrix J}
		\\
%		\quad \text{and} \quad
%	\mathbb K &= \ai \begin{bmatrix} 0 & - S A_\alpha \\ S \tp{A_\alpha} & 0 \end{bmatrix}.
	\mathbb K &= \begin{bmatrix} 0 & - \ai S A_\alpha \\ \ai S \tp{A_\alpha} & 0 \end{bmatrix},
		\label{e:matrix K}
\end{align}
%\end{equation}
\end{subequations}
from which it follows immediately that ${\mathbb J}^2={\mathbb K}^2=-1$ if and only if $\tp{A_\alpha} S A_\alpha=S$.


Now, we will prove \eqref{e:matrices J and K}.
If one wrtites $v,\,J v \in \Tc_p \ourZ$ as
{\allowdisplaybreaks
\begin{align*}
	v	&=\sum_{i=1}^{2n} \epsilon_i \, \del_i + \sum_{i=1}^{2n} \epsilon^-_i \, \antidel_i 
		= (\del_1,\dots,\del_{2n},\antidel_1,\dots, \antidel_{2n}) 
			\begin{bmatrix} \vec{\epsilon}^+ \\ \vec{\epsilon}^- \end{bmatrix},
			\\
	Jv	&=\sum_{i=1}^{2n} \eta_i \, \del_i + \sum_{i=1}^{2n} \eta^-_i \, \antidel_i 
		= (\del_1,\dots,\del_{2n},\antidel_1,\dots, \antidel_{2n}) 
			\begin{bmatrix} \vec{\eta}^+ \\ \vec{\eta}^- \end{bmatrix}
\end{align*}
with $\vec{\epsilon}^+=\tp{(\epsilon_1,\dots,\epsilon_{2n})}, \vec{\epsilon}^-=\tp{(\epsilon^-_1,\dots,\epsilon^-_{2n})},\, \vec{\eta}^+=\tp{(\eta_1,\dots,\eta_{2n})}, \vec{\eta}^-=\tp{(\eta^-_1,\dots,\eta^-_{2n})}$, 
then the definition that $J v = (\omega^\flat_I)^{-1} \circ \omega^\flat_K (v)$, i.e.~$\omega^\flat_I(J v) = \omega^\flat_K (v)$ ($v \in \Tc_p \ourZ$) reads
\begin{align*}
	\epsilon_i &= \sum_{j=1}^{2n} g_{n+i,\bar j} \, \eta^-_j, & \epsilon_{n+i} &= - \sum_{j=1}^{2n} g_{i,\bar j} \, \eta^-_j,
		\\
	\epsilon^-_i &= \sum_{j=1}^{2n} g_{j, \overline{n+i}} \, \eta_j, & \epsilon^-_{n+i} &= - \sum_{j=1}^{2n} g_{j,\bar i} \, \eta_j
\end{align*}
}
for $i=1,\dots, n$, which can be written as
\begin{equation*}
	\vec{\epsilon}^+= S A_\alpha \, \vec{\eta}^-, \quad \vec{\epsilon}^-= S \tp{A_\alpha} \, \vec{\eta}^+.
\end{equation*}
Therefore, one has
\begin{equation*}
	\vec{\eta}^+= \tp{A_\alpha}^{-1} S^{-1} \vec{\epsilon}^-, \quad \vec{\eta}^-= A_\alpha^{-1} S^{-1} \vec{\epsilon}^+.
\end{equation*}
Namely,
\begin{equation*}
	\begin{bmatrix} \vec{\eta}^+ \\ \vec{\eta}^-\end{bmatrix}
		= \begin{bmatrix} 0 & \tp{A_\alpha}^{-1} S^{-1} \\ A_\alpha^{-1} S^{-1} & 0 \end{bmatrix}
			\begin{bmatrix} \vec{\epsilon}^+ \\ \vec{\epsilon}^- \end{bmatrix}.
\end{equation*}
Hence one obtains \eqref{e:matrix J}.

Similarly, writing $K v$ as
\[
	K v=\sum_{i=1}^{2n} \eta_i \, \del_i + \sum_{i=1}^{2n} \eta^-_i \, \antidel_i 
		= (\del_1,\dots,\del_{2n},\antidel_1,\dots, \antidel_{2n}) 
			\begin{bmatrix} \vec{\eta}^+ \\ \vec{\eta}^- \end{bmatrix},
\]
%with $\vec{c}'=\tp{(\eta_1,\dots,\eta_{2n})}, \vec{c}''=\tp{(\eta^-_1,\dots,\eta^-_{2n})}$, 
one finds that $\omega^\flat_J(K v) = \omega^\flat_I (v)$ reads
\begin{align*}
	\eta_i &= -\ai \sum_{j=1}^{2n} g_{n+i,\bar j} \, \epsilon_j, & \eta_{n+i} &= \ai \sum_{j=1}^{2n} g_{i,\bar j} \, \epsilon_j,
		\\
	\eta^-_i &= \ai \sum_{j=1}^{2n} g_{j, \overline{n+i}} \, \epsilon_j, & \eta^-_{n+i} &= - \ai \sum_{j=1}^{2n} g_{j,\bar i} \, \epsilon_j
\end{align*}
for $i=1,\dots, n$, which can be written as
\begin{equation*}
	\vec{\eta}^+= -\ai S A_\alpha \, \vec{\epsilon}^-, \quad \vec{\eta}^-= \ai S\, \tp{A_\alpha} \, \vec{\epsilon}^+.
\end{equation*}
Namely,
\begin{equation*}
	\begin{bmatrix} \vec{\eta}^+ \\ \vec{\eta}^- \end{bmatrix}
		= \ai \begin{bmatrix} 0 & -S A_\alpha \\ S\, \tp{A_\alpha} & 0 \end{bmatrix}
				\begin{bmatrix} \vec{\epsilon}^+ \\ \vec{\epsilon}^- \end{bmatrix}.
\end{equation*}
Hence one obtains \eqref{e:matrix K}.
\end{proof}




\begin{remark}
\label{r:cpx str I, Sp & E-H}
%\label{r:cpx str I}
%
(i)\;
It is easy to verify that the canonical complex structure $I$ on $\ourZ$ satisfies $I = (\omega^\flat_K)^{-1} \circ \omega^\flat_J$, and that the matrix $\mathbb I$ corresponding to $I$ with respect to the basis $\Sigma$
%$(\pd_{z_1},\dots,\pd_{z_n},\pd_{\xi_1},\dots,\pd_{\xi_n},\pd_{\bar z_1},\dots,\pd_{\bar z_n},\pd_{\bar \xi_1},\dots,\pd_{\bar \xi_n})$ 
for $\Tc \ourZ|_{\pi_\lambda^{-1}(U_\alpha)}$ is given by
\begin{equation}
\label{e:matrix I}
	\mathbb I= \ai \begin{bmatrix} 1_{2n} & 0 \\  0 & -1_{2n} \end{bmatrix}.
\end{equation}
It follows from \eqref{e:matrices J and K} and \eqref{e:matrix I} that ${\mathbb I}\,{\mathbb J}\,{\mathbb K}=-1$, hence $IJK=-1$, regardless of whether $A_\alpha$ satisfies \eqref{e:condition Sp2n} or not. 
%\end{remark}
%

%\begin{remark}
%\label{r:Sp & E-H}
%
(ii)\;
Eq.~\eqref{e:condition Sp2n} is nothing but the condition that $A_\alpha \in \Sp(2n,\C)$, \emph{the complex symplectic group}, where
\begin{equation*}
\Sp(2n,\C) = \big\{ g \in \GL{2n}(\C); \tp{g} S g = S \big\}
\end{equation*}
with \( S = \left[ \begin{smallmatrix} 0 & 1_n \\[2pt] -1_n & 0 \end{smallmatrix} \right] \).
Therefore, when $n=1$, all solutions given in \eqref{e:ricci-flat sol} with $a \geqsl 0$ provide hyperk{\"a}hler metrics on $\ourZ$ outside the Lagrangian submanifold $\ourLSmfd$ given by \eqref{e:Laglangian submfd}, 
since $\Sp(2,\C)=\SL{2}(\C)$. 
Note that if $\lambda$ tends to $0$ (i.e.~$s \to 0$), then the twisted cotangent bundle $\ourZ=(T^*\CP^1)_\lambda$ reduces to the cotangent bundle $T^*\CP^1$ (as we remarked in Remark \ref{r:ansatz on beta} above),
and the corresponding metric with $a>0$ coincides with the Eguchi-Hanson metric (\cite{EguchiHanson79}; see also \cite{KapustinSaulina09} for more details). 


\end{remark}


%\draftcomment{add comment ``Not hyperk\"ahler if $a \ne 0$''}

%From now on, we consider the solution $f(\tau)$ with $a=0$ in \eqref{e:ricci-flat sol} again:
%\begin{equation}
