%\end{equation}


Recall that our symplectic form $\omega_I$ is given by $\omega_I=\rmd \beta$ with 
\(
	\beta =  \frac{1}4 f(\tau)\, \rmd^c \tau %= \frac{\ai}4 f(\tau) (\antidel \tau - \pd \tau),
\) and that the metric $g$ defined by
\begin{equation*}
	g(v,w) = \omega_I (v, I w)	\quad ( v,w \in {\mathfrak X}(\ourZ) )
\end{equation*} 
is Ricci-flat if and only if $f$ is of the form
\begin{equation}
\label{e:cicci-flat sol}
	f(\tau) = \left( \frac{\big( a + (\tau-\tau_0)^n \big)^{1/n}}{\tau (\tau - \tau_0)} \right)^{1/2}
\end{equation}
with $a$ a nonnegative constant, where $\tau_0=\abs{s}^2$.


\begin{theorem}
\label{t:hk_sol}
%Let $f(\tau)$ be a solution to the ODE \eqref{e:ricci-flat eq} given by \eqref{e:ricci-flat sol}:
%\[
%	f(\tau) = \left( \frac{\big( a + (\tau-\tau_0)^n \big)^{1/n}}{\tau (\tau - \tau_0)} \right)^{1/2},
%\]
%Let $f(\tau)=\tau^{-1/2}$ and correspondingly, set
%\begin{equation*}
%\label{e:one-form2hk}
%\end{equation*}
%and $g(v,w) = \omega_I (v, I w)$ $(v,w \in {\mathfrak X}(\ourZ))$ with $\omega_I=\rmd \beta$, as always.
The metric $g$ defined by \eqref{e:def of metric g} provides a hyperk{\"a}hler metric on $\ourZ$ if and only if $a=0$, i.e.~if and only if $f(\tau)$ is given by
\begin{equation}
\label{e:hk_sol}
	f(\tau) = \tau^{-1/2}.
\end{equation}

\end{theorem}
%
\begin{proof}
By Proposition \ref{p:J^2 and K^2} and Remark \ref{r:cpx str I, Sp & E-H} (i), it suffices to show that $\tp{A_\alpha} S A_\alpha = S$ if and only if $a=0$.
%
Let us rewrite \eqref{e:mat 4 metric g} as
\begin{equation}
	A_\alpha = c A'_\alpha + c_1 A''_\alpha
\end{equation}
with $c=f(\tau),\, c_1=f'(\tau)$, and
%with $c=f(\tau)=\tau^{-1/2},\, c_1=f'(\tau)=(-1/2)\tau^{-3/2}$, and
\begin{align*}
	A'_\alpha &= (\tau_{i,\bar j})_{i,j=1, \dots, 2n} = (\vec{a}_1, \vec{a}_2,\dots, \vec{a}_{2n}), \\
	A''_\alpha &= (\tau_i \tau_{\bar j})_{i,j=1,\dots, 2n} = ( \tau_{\bar 1} \vec{b}, \tau_{\bar 2} \vec{b}, \dots, \tau_{\overline{2n}}\, \vec{b} ),
\end{align*}
where $\vec{a}_i, \vec{b}$ are given by \eqref{e:mat g by tau_xy} and \eqref{e:mat g by tau_x} respectively.
%,\, A_\alpha^0 = (\tau_{i,\bar j})_{i,j=1, \dots, 2n}$ and $A_\alpha^1 = (\tau_i \tau_{\bar j})_{i,j=1,\dots, 2n}$.
Since $A''_\alpha=\vec{b} {\vec{b}}^*$ and $\tp{\vec{b}} S \vec{b} = 0$, one has
%noting that $A''_\alpha = \vec{b} \vec{b}^*$ and $\tp{\vec{b}} S \vec{b} = 0$,
\begin{equation}
	\tp{A''_\alpha}\, S\, A''_\alpha = 0.
\end{equation}
Therefore, one sees that 
{\allowdisplaybreaks
\begin{align}
\label{e:Sp condition}
	\tp{A_\alpha} S A_\alpha 
		&= c^2 \,\tp{A'_\alpha} S A'_\alpha + c c_1 ( \tp{A'_\alpha} S A''_\alpha + \tp{A''_\alpha} S A'_\alpha)
		\notag
		\\
		&= c^2 \,\tp{A'_\alpha} S A'_\alpha + c c_1 \Big( \tp{A'_\alpha} S A''_\alpha -\tp{ ( \tp{A''_\alpha} S A'_\alpha ) } \Big)
%		\notag
%		\\
%		&= \frac12 \tau^{-2} \Big( 2 \tau\, \tp{A'_\alpha} S A'_\alpha  - ( \tp{A'_\alpha} S A''_\alpha + \tp{A''_\alpha} S A'_\alpha) \Big).
%		\notag
%		\\
%		&= (\psi_1 \psi_2)^{-1} \, \tp{A'_\alpha} S A'_\alpha  - \frac12 (\psi_1 \psi_2)^{-2} ( \tp{A'_\alpha} S A''_\alpha + \tp{A''_\alpha} S A'_\alpha)
%		\notag 
%		\\
%		&= (\psi_1 \psi_2)^{-1} \, \tp{A'_\alpha} S A'_\alpha  - \frac12 (\psi_1 \psi_2)^{-2} \big( \tp{A'_\alpha} S A''_\alpha - \tp{(\tp{A'_\alpha} S A''_\alpha)} \big)
\end{align}
}
since $\tp{A''_\alpha} S A'_\alpha=-\tp{(\tp{A'_\alpha} S A''_\alpha)}$.
Using the notations in the proof of Propositions \ref{p:det mat tau_xy} and \ref{p:det mat tau_x tau_y}, i.e.
\begin{equation*}
	A'_\alpha=\begin{bmatrix} a_{11} & a_{12} \\ a_{21} & a_{22} \end{bmatrix},
		\qquad
	A''_\alpha=\begin{bmatrix} b_1 {b_1}^* & b_1 {b_2}^* \\[2pt] b_2 {b_1}^* & b_2 {b_2}^* \end{bmatrix}
\end{equation*}
with $a_{ij} \in \Mat{n \times n}(\C), b_i \in \C^n$ ($i,j=1,2$), 
one sees 
{\allowdisplaybreaks
\begin{align*}
	\tp{A'_\alpha} S A'_\alpha 
		&= 	\begin{bmatrix} 
				\tp{a_{11}} a_{21} - \tp{a_{21}} a_{11} & \tp{a_{11}} a_{22} - \tp{a_{21}} a_{12} \\[3pt] 
				\tp{a_{12}} a_{21} - \tp{a_{22}} a_{11} & \tp{a_{12}} a_{22} - \tp{a_{21}} a_{12} 
			\end{bmatrix},
		\\
	\tp{A'_\alpha} S A''_\alpha 
		&= 	\begin{bmatrix} 
				( \tp{a_{11}} b_{2} - \tp{a_{21}} b_1 ) {b_1}^* &  ( \tp{a_{11}} b_2 - \tp{a_{21}} b_1 ) {b_2}^* \\[3pt] 
				( \tp{a_{12}} b_{2} - \tp{a_{22}} b_1 ) {b_1}^* &  ( \tp{a_{12}} b_2 - \tp{a_{22}} b_1 ) {b_2}^* 
			\end{bmatrix}.	
\end{align*}
}
Recall from \eqref{e:submat cc} and \eqref{e:b_1 and b_2} that
{\allowdisplaybreaks
\begin{align*}
	a_{11} &= \psi_2 1_n - s_{xz}\, \bar z \, \bar \xi - \bar s_{xz} \tp{\xi} \tp{z} + \psi_1 \tp{\xi} \, \bar \xi,	
		&
	a_{12} &= \psi_1 \tp{\xi} \, z^* + \bar z \, \xi - s_{xz} \, \bar z \, z^*, \\
	a_{21} &= \psi_1 z \, \bar \xi + \xi^* \tp{z} - \bar s_{xz} \, z \, \tp{z}, 
		&
	a_{22} &= \psi_1 (1_n + z \, z^*),	\\
	b_1 &= \psi_2 \bar z - \psi_1 {\bar s}_{xz} \tp{\xi}, 
		&
	b_2 &= \psi_1 ( \xi^* - {\bar s}_{xz} z ).
\end{align*}
}
Thus, simple matrix calculations show that the $(1,1)$-, $(1,2)$-, and $(2,2)$-blocks of $\tp{A'} S A'$ are given by
\begin{subequations}
\label{e:A'SA'}
%
\renewcommand{\theequation}{\theparentequation}
%
{\allowdisplaybreaks
\begin{align}
	\tp{a_{11}} a_{21} - \tp{a_{21}} a_{11} &= (s_{xz} \overline{\xi z} - \norm{\xi}^2) (z \bar \xi - \xi^* \tp{z} ),
		\tag{\theequation$_{[1,1]}$} 
		\label{e:(1,1)-A'SA'}
		\\
	\tp{a_{11}} a_{22} - \tp{a_{21}} a_{12} &= \psi_1 \psi_2 1_n - \psi_1 s_{xz}\, \xi^* z^* + \bar s s_{xz}\, z z^* + \psi_1\, \xi^* \xi - \bar s\, z \xi,
		\tag{\theequation$_{[1,2]}$} 
		\label{e:(1,2)-A'SA'}
		\\
	\tp{a_{12}} a_{22} - \tp{a_{21}} a_{12} &= 0,
		\tag{\theequation$_{[2,2]}$} 
		\label{e:(2,2)-A'SA'}
		\\
\intertext{respectively. The $(2,1)$-block of $\tp{A'} S A'$ is equal to the negative transpose of its $(1,2)$-block:}
	\tp{a_{12}} a_{21} - \tp{a_{22}} a_{11} &= -\tp{(\tp{a_{11}} a_{22} - \tp{a_{21}} a_{12})}.
		\tag{\theequation$_{[2,1]}$} 
\end{align}
}
\end{subequations}



Similarly, one obtains that the $(1,1)$-, $(1,2)$-, $(2,1)$-, and $(2,2)$-blocks of $\tp{A'} S A''$ are given by
{\allowdisplaybreaks
\begin{subequations}
\label{e:A'SA''}
%
\renewcommand{\theequation}{\theparentequation}
%
\begin{align}
	( \tp{a_{11}} b_{2} - \tp{a_{21}} b_1 ) {b_1}^* 
		&= - s_{xz} {\psi_1}^2 (\psi_2 - s_{xz} \overline{\xi z} + \norm{\xi}^2)\,\xi^* \bar \xi - \bar s {\psi_2}^2\, z \tp{z}
			\notag \\
		& \hspace{2.65em} + \psi_1 \psi_2 (\psi_2 - s_{xz} \overline{\xi z} + \norm{\xi}^2)\, \xi^* \tp{z} + \bar s s_{xz }\psi_1 \psi_2\, z \bar \xi, 
		\tag{\theequation$_{[1,1]}$} 
			\label{e:(1,1)-A'SA''}
			\\
	( \tp{a_{11}} b_2 - \tp{a_{21}} b_1 ) {b_2}^* 
		&= \psi_1 \Big( \psi_1 (\psi_2 - s_{xz} \overline{\xi z} + \norm{\xi}^2 )\, \xi^* \xi + \bar s _{xz} \psi_2\, z z^* 
			\notag \\
		& \hspace{3.2em} - \bar s \psi_2\, z \xi - s_{xz} \psi_1 (\psi_2 - s_{xz} \overline{\xi z} + \norm{\xi}^2)\, \xi^* z^* \Big),
		\tag{\theequation$_{[1,2]}$} 
			\label{e:(1,2)-A'SA''}
			\\
	( \tp{a_{12}} b_2 - \tp{a_{22}} b_1 ) {b_1}^* 
		&= \bar s \psi_1 ( -s_{xz} \psi_1\, \tp{\xi} \bar \xi - s_{xz} \psi_2\, \bar z \tp{z} + \psi_2\, \tp{\xi} \tp{z}+ {s_{xz}}^2 \psi_1\, \bar z \bar \xi),
		\tag{\theequation$_{[2,1]}$} 
			\label{e:(2,1)-A'SA''}
			\\
	( \tp{a_{12}} b_2 - \tp{a_{22}} b_1 ) {b_2}^* 
		&= \bar s {\psi_1}^2 ( \tp{\xi} \xi + {s_{xz}}^2 \bar z z^* - s_{xz} \bar z \xi - s_{xz} \tp{\xi} z^* ),
		\tag{\theequation$_{[2,2]}$} 
			\label{e:(2,2)-A'SA''}
\end{align}
\end{subequations}
}%
respectively.
Thus, it is immediate from \eqref{e:(2,2)-A'SA'} and \eqref{e:(2,2)-A'SA''} to see that the $(2,2)$-block of \eqref{e:Sp condition} vanishes identically.



Now, let us show that the right-hand side of \eqref{e:Sp condition} equals $S=\Big[ \begin{smallmatrix} 0 & 1_n \\[2pt] -1_n & 0 \end{smallmatrix} \Big]$ blockwise if and only if $a=0$.


Assume first that $a=0$.
Then, noting that $c^2=\tau^{-1}$ and $c c_1 = -(1/2) \tau^{-2}$, one finds that the $(1,1)$-block of \eqref{e:Sp condition} equals
\begin{equation}
\label{e:(1,1)-block}
\begin{aligned}
	&\frac12 (\psi_1 \psi_2)^{-1} 
				\Big( 2 (s_{xz} \overline{\xi z} - \norm{\xi}^2) + \psi_2 - s_{xz} \overline{\xi z} + \norm{\xi}^2 - \bar s s_{xz} \Big) (z \bar \xi - \xi^* \tp{z})
	 \\
	=\,& \frac12 (\psi_1 \psi_2)^{-1} \Big( \psi_2 - \norm{\xi}^2 - \bar s s_{xz} + s_{xz} \overline{\xi z} \Big) (z \bar \xi - \xi^* \tp{z})
	 \\
	=\,& \frac12 (\psi_1 \psi_2)^{-1} \Big( \psi_2 - \norm{\xi}^2 - \abs{s_{xz}}^2 \Big) (z \bar \xi - \xi^* \tp{z}),
\end{aligned}
\end{equation}
which vanishes identically by \eqref{e:psi1 and psi2}.


Similarly, one finds that the $(1,2)$-block of \eqref{e:Sp condition} equals
\begin{align*}
	& (\psi_1 \psi_2)^{-1} \Big( \psi_1 \psi_2 1_n + \psi_1 \xi^* (\xi - s_{xz} z^*) - \bar s z (\xi - s_{xz} z^*) \Big)
	\\
	&\hspace{0.5em}  + \frac12 (\psi_1 \psi_2)^{-2} \Big( 
		  -{\psi_1}^2 ( \psi_2 - s_{xz} \overline{\xi z} + \norm{\xi}^2)\, \xi^* (\xi - s_{xz} z^*) + \bar s \psi_1 \psi_2\, z (\xi - s_{xz} z^*) 
	\\
	& \hspace{6.85em} + \bar s \psi_1 \big( -s_{xz} \psi_1\, \xi^* (\xi - s_{xz} z^*) + \psi_2\, z (\xi - s_{xz} z^*) \big)
			\Big)
	\\
	&\,= 1_n + \frac12 {\psi_2}^{-2} \big( \psi_2 - \bar s s_{xz} + s_{xz} \overline{\xi z} - \norm{\xi}^2 \big)\, \xi^* (\xi - s_{xz} z^*)
	\\
	&\,= 1_n + \frac12 {\psi_2}^{-2} \big( \psi_2 - \abs{s_{xz}}^2 - \norm{\xi}^2 \big)\, \xi^* (\xi - s_{xz} z^*)
	\\
	&\,= 1_n
\end{align*}
identically, again by \eqref{e:psi1 and psi2}.
Note that the $(2,1)$-block of the right-hand side of \eqref{e:Sp condition} is equal to the negative transpose of its $(1,2)$-block, and thus equals $-1_n$ identically.
%



Conversely, assume that $a \ne 0$ in \eqref{e:cicci-flat sol}.
Then, one can easily verify that the $(1,1)$-block of \eqref{e:Sp condition} does not vanish identically.
Hence $A_\alpha \notin \Sp(2n,\C)$.
This completes the proof.
\end{proof} 



Note that $\omega_I = \frac12 \rmd \rmd^c\, \tau^{1/2}$ if $f(\tau)=\tau^{-1/2}$.
Namely, a K{\"a}hler potential $\Phi$ for $(\ourZ,g,I)$ is given by $\Phi=\tau^{-1/2}$; its local expression is given by
\begin{equation}
	\Phi|_{\pi_\lambda^{-1}(U_\alpha)} = ( \norm{z}^2 + 1 )^{1/2} ( \norm{\xi}^{2} + \abs{s - \xi z}^{2} )^{1/2}
\end{equation}
in terms of the local coordinates $(z,\xi)$.

