\section{%Some determinant formulae for matrices of rank 2
}
\label{s:det rank2 etc}


%For $z_i=\tp{(z_{i,1},z_{i,2},\dots,z_{i,n})}, w_i=\tp{(w_{i,1},w_{i,2},\dots,w_{i,n})} \in \C^n$, ($i=1,2$), 
Throughout the appendix, let $A$ denote a matrix given by
\begin{equation}
\label{e:rank2 mat}
	A = Z_1 \tp{\,W_1} + Z_2 \tp{\,W_2} \in \Mat{n \times n}(\C)
\end{equation}
for $Z_i,W_i \in \C^n$ ($i=1,2$).
Note that the rank of $A$ is at most 2 if $n \geqsl 2$.

For the matrix $A$ given in \eqref{e:rank2 mat}, let us introduce a $2 \times 2$ matrix $\Lambda$ by
\begin{equation}
\label{e:2by2 mat}
	\Lambda = \begin{bmatrix} 
				\< W_1, Z_1 \>  & \< W_1, Z_2 \> \\[3pt] 
				\< W_2, Z_1 \>  & \< W_2, Z_2 \>
			  \end{bmatrix} \in \Mat{2 \times 2}(\C),
\end{equation}
where $\<\cdot,\cdot\>$ denotes the canonical bilinear form on $\C^n$.



\begin{lemma}
\label{l:det of 1+rank2mat}
For $u \in \C$, one has
\begin{equation}
\label{e:det of 1+rank2mat}
	\det( u 1_n + A) = u^{n-2} ( u^2 + u \trace{\Lambda} + \det \Lambda ).
\end{equation}
\end{lemma}
%
\begin{proof}
First, note that
\begin{equation*}
	\det( u 1_n + A) = u^{n-2} \big( u^2 + u \trace{A} + \tfrac12( (\trace A)^2 - \trace{(A^2)}) \big)
\end{equation*}
since $A$ has its eigenvalues $\lambda_1,\lambda_2, \lambda_3 = \lambda_4 = \dots = \lambda_n=0$.
It is immediate to show that
\begin{equation*}
\label{e:trace Lambda & det Lambda}
\begin{aligned}
	\trace{\Lambda} &= \trace{A}, \\
	\det \Lambda &= \tfrac12 \big( (\trace A)^2 - \trace{(A^2)} \big)
\end{aligned}
\end{equation*}
if one notes $Z_i \tp{\,W_j} \, Z_k \tp{\,W_l} = \<W_j,Z_k\>\, Z_i \tp{\,W_l}$.
This completes the proof.
\end{proof}


Note in particular that one obtains $\det(1_n + A) = \det(1_2 + \Lambda)$ setting $u=1$ in \eqref{e:det of 1+rank2mat}.



\begin{lemma}
\label{l:1/(1+rank-two mat)}
Let $A \in \Mat{n \times n}(\C)$ and $\Lambda \in \Mat{2 \times 2}(\C)$ be matrices given by \eqref{e:rank2 mat} and \eqref{e:2by2 mat} respectively.
Then one has
\begin{equation}
\label{e:1/(1+rank-two mat)}
	(1_n + A)^{-1} = 1_n - \frac{1}{\det(1_2 + \Lambda)}
						\Big( (1+\lambda_{22})\, Z_1 \! \tp{\,W_1} - \lambda_{12}\, Z_1 \! \tp{\,W_2} - \lambda_{21}\, Z_2 \! \tp{\,W_1} + (1+\lambda_{11})\, Z_2 \! \tp{\,W_2} \Big)
\end{equation}
if $\det(1_2 + \Lambda) \ne 0$, where we set $\lambda_{ij}:=\<W_i, Z_j \>$ ($i,j=1,2$).

In particular, setting $Z_2=0$ or $W_2=0$, one has
\begin{equation}
\label{e:1/(1+rank-one mat)}
	(1_n + Z_1 \tp{\,W_1} )^{-1} = 1_n - \frac{1}{1+\<W_1,Z_1\>}\, Z_1 \tp{\,W_1}
\end{equation}
if $1+\< W_1, Z_1 \> \ne 0$.
\end{lemma}
