\title{Characterizing asymmetric and bimodal long-term financial return distributions through quantum walks}

\author[inst1]{Stijn De Backer}
\ead{stijn.debacker@ugent.be}

\affiliation[inst1]{organization={Department of Physics and Astronomy, Ghent University},
            city={Ghent},
            country={Belgium}}

\affiliation[inst2]{organization={Department of Economics, Ghent University},
