% \end{equation*}
% which proves the lemma since \(T \geq 2.\)
\end{proof}

\begin{corollary} \label{cor lem B-C}
There exist \(0<\delta<1\) and \(C>0\) depending on \(\Gamma\) such that for $T>2$,     
    % \begin{equation}\label{trace growth}
    %     N(T) \leq C T^{2-\delta}\log(T)^{d-1}.
    % \end{equation}
     \begin{equation*}
        \cL'(T) \leq C T^{2-\delta}.
    \end{equation*}
\end{corollary}

We now prove the first main result:


\begin{theorem}\label{thm1}
 All cocompact semi-arithmetic Fuchsian groups which admit a modular embedding and have arithmetic dimension at most \(2\) have exponential growth of the mean multiplicity in the length spectrum.   
\end{theorem}
\begin{proof}
The result if already known for arithmetic groups by \cite{LuoSarnak94}, so we 
can assume that \(\Gamma\) is a non-arithmetic group as above. 
%, derived from a quaternion algebra and with invariant trace field of degree \(d\) as above.

Let \(\mathcal{N}'(\ell)\) be the number of distinct lengths bounded by \(\ell\) of closed geodesics in the orbifold \(\Gamma \backslash \Hyp.\)  Each length produces a unique positive trace of a hyperbolic element of \(\Gamma\) bounded by \(2\arcosh({\ell}/{2})\), i.e. with the notation of the previous lemma, we have 
\begin{equation}
    \mathcal{N}'(\ell) \leq \mathcal{L}'\left(2\cosh\left(\frac{\ell}{2}\right)\right).
\end{equation}
% Since \(\cosh(\nicefrac{\ell}{2})\leq e^{\nicefrac{\ell}{2}}\), by \eqref{trace growth}
Thus, by Corollary~\ref{cor lem B-C} and the well known inequality \(\cosh(\frac{\ell}{2})\leq e^{\frac{\ell}{2}}\), already used in the proof of Lemma~\ref{norm bound}, we obtain
% \begin{equation}
%      \mathcal{N}'(\ell) \leq C'e^{\ell(1-\delta')}\ell^{d-1}
% \end{equation}
\begin{equation}
     \mathcal{N}'(\ell) \leq C'e^{(1-\delta')\ell}
\end{equation}
for some constants \(C'>0\) and \(0<\delta'<\frac{1}{2}.\)
By the prime geodesic theorem, the number \(\mathcal{N}(\ell)\) of closed geodesics of \(\Gamma \backslash \Hyp\) counted with multiplicity is given by
\begin{align*} 
\mathcal{N}(\ell) \sim \dfrac{e^\ell}{\ell} & \text{ when } \ell \to \infty. \end{align*}
Thus the mean multiplicity \(\langle g(\ell) \rangle\) of closed geodesics of length at most \(\ell\) grows at least as
% \begin{align*}
%     \langle g(\ell) \rangle = \dfrac{\mathcal{N}(\ell)}{\mathcal{N}'(\ell)}\gtrsim c \dfrac{e^{\delta' \ell}}{\ell^{d}}, 
% \end{align*}
\begin{align*}
    \langle g(\ell) \rangle = \dfrac{\mathcal{N}(\ell)}{\mathcal{N}'(\ell)}\gtrsim c \dfrac{e^{\delta' \ell}}{\ell}, 
\end{align*}
where \(c>0\) and \(0<\delta'<\frac{1}{2}\) depend on  \(\Gamma\) and its arithmetic invariants.
\end{proof}


