								P(\gamma) \coloneq \Tr[\rho\proj{\rho\leq \gamma \sigma}],
								\;\;
								Q(\gamma) \coloneq \Tr[\sigma\proj{\rho\leq \gamma \sigma}],
								\;\;\gamma \in [0,\infty).
							\end{align*}
							\begin{equation*}
								D_f(\rho \Vert \sigma) = \sup_{g: [0,\infty)\to \mathds{R}}  \big\{
								\mathds{E}_{P} [g] +  \mathds{E}_{Q}[f^\star \circ g] \big\}
								\quad \text{(Thm.~\ref{theorem:f-duality})}
							\end{equation*}
						\end{samepage}


						\textbf{Noncommutative minimum}:
						For $A,B\geq 0$.
						\begin{align*}
							A \wedge B
							&\coloneq \argmax\limits_{H=H^\dagger} \left\{ \Tr{H} : H\leq A, H\leq B \right\}
							\\
							&=A \{A\leq B \} + B \{B < A  \}
							= \frac12\left[ A + B - |A-B| \right],
							\\
							\!\!\!\Tr\left[ A \wedge B \right]
							&= \inf_{0\leq T\leq \I} \!\Tr[A(\I\!-\!T)] + \Tr[B T]
							=\frac{\Tr[A \!+\! B] - \left\| A \!-\! B\right\|_1}{2}
							\\
							&\overset{\text{\cite{preparation}}}{=} \int_{0}^1 \Tr\left[ A \left\{ u A < B\right\} \right] \d u
							\geq \Tr\left[ A \cdot \mathrm{D} \log [A+B](B)] \right]
							\\
							&\geq \Tr\left[ A (A+B)^{-\frac12} B (A+B)^{-\frac12}\right].
						\end{align*}

