	With the above we can discuss properties of the derivative of the Hockey-Stick divergence. 
	\begin{lemm}\label{Lem:HS-derivative}
		Let $A$ and $B$ be Hermitian. Then, the map $\gamma \mapsto E_{\gamma}(A\Vert B)$ is piecewise analytic except for $\gamma$ such that $A-\gamma B$ is singular.
		The right and left derivatives are
		\begin{align}
			\partial_+ E_{\gamma}'(A \Vert B) =  -\Tr\left[ B \proj{\gamma B < A }\right] \\
			\partial_- E_{\gamma}'(A \Vert B) =  -\Tr\left[ B \proj{\gamma B \leq A }\right].
		\end{align}

		Moreover, if $A\geq 0$ and $B>0$, then we have the Lebesgue integral
		\begin{align}
			-\int_0^\infty \frac{\d}{\d\gamma} E_{\gamma}(A\Vert B) \, \d \gamma = \Tr[A], \quad B>0. \label{eq:integral_HS}
		\end{align}
	\end{lemm}
	\begin{proof}
		The piecewise analyticity directly follows from Lemma~\ref{lemm:differentiability_projection} and the definition $E_{\gamma}(A\Vert B) = \Tr\left[\left( A - \gamma B \right)_+ \right]$.

		For $\delta$ such that $A-\delta B$ is not singular, we have
		\begin{DispWithArrows}[displaystyle]
			\left.\frac{\d}{\d \gamma} \Tr\left[ ( A - \gamma B )_+ \right]\right|_{\gamma = \delta}
			= - \Tr\left[ B \left\{ A  > \delta B \right\} \right]
			= - \Tr\left[ B \left\{ A  \geq \delta B \right\} \right],
		\end{DispWithArrows}
		by Lemma~\ref{lemm:HP14} below with $f(x) = x_+$ and 
		\begin{align}
			f'(x) = \begin{cases} 
				1 & x>0
				\\
				0 & x< 0
			\end{cases}.
		\end{align}

		For $\delta$ such that $A-\delta B$ is not singular, 
		\begin{DispWithArrows}[displaystyle]
			\left.\frac{\d}{\d \gamma} \Tr\left[ ( A - \gamma B )_+ \right]\right|_{\gamma = \delta^+}
			&= - \Tr\left[ B \left\{ A  > \delta^+ B \right\} \right]
			\notag
			\Arrow{\textnormal{$\delta \mapsto \left\{ A  > \delta B \right\}$ is right} \\ \textnormal{continuous by Lemma~\ref{lemm:differentiability_projection}}}
			\notag
			\\
			&= - \Tr\left[ B \left\{ A  > \delta B \right\} \right],
		\end{DispWithArrows}
		and 
		\begin{DispWithArrows}[displaystyle]
			\left.\frac{\d}{\d \gamma} \Tr\left[ ( A - \gamma B )_+ \right]\right|_{\gamma = \delta^-}
			&= - \Tr\left[ B \left\{ A  \geq \delta^- B \right\} \right]
			\Arrow{\textnormal{$\delta \mapsto \left\{ A  \geq \delta B \right\}$ is left} \\ \textnormal{continuous by Lemma~\ref{lemm:differentiability_projection}}}
			\notag
			\\
			&= - \Tr\left[ B \left\{ A  \geq \delta B \right\} \right].
		\end{DispWithArrows}

		Lastly, by Theorem~\ref{theo:Dlog_formula} below, we have
		\begin{align*}
			-\int_0^\infty E_{\gamma}'(A\Vert B) \, \d \gamma
			&= \int_0^\infty \Tr\left[ B \left\{ \gamma B < A \right\} \right] \, \d \gamma
			\\
			&= \Tr\left[ B \cdot \mathrm{D} \log [B] (A) \right]
			\\
			&= \Tr\left[ \mathrm{D} \log [B] (B) \cdot A \right]
			\\
			&= \Tr[A].
		\end{align*}
	\end{proof}



	\begin{lemm}\label{lemm:monotone_in_gamma}
		For any $A, B \geq 0$, the maps
		\begin{align}
			\gamma \mapsto \Tr\left[ A \left\{ A < \gamma B \right\} \right],
			\quad
			\gamma \mapsto \Tr\left[ A \left\{ A \leq \gamma B \right\} \right]
		\end{align}
		are nondecreasing on $\gamma >0$.
	\end{lemm}
	\begin{proof}
		Since the Hockey-stick divergence $\Tr\left[ ( A - \gamma B )_+ \right]$ is convex nonincreasing in $\gamma >0$ (see Lemma~\ref{lemm:Hockey-stick_convex_nonincreasing} below), both the left and right derivatives are nondecreasing.
		Invoking Lemma~\ref{Lem:HS-derivative} and  switching the roles of $A$ and $B$, and substituting $\delta \leftarrow 1/\gamma$, the proof is concluded.
	\end{proof}

	\begin{lemm}[\hspace{-0.3pt}{\cite[Theorem 3.23]{HP14}}\footnote{Ref.~{\cite[Theorem 3.23]{HP14}} states for continuously differentiable function $f$. The same argument holds for one-sided differentiable functions as well.}] \label{lemm:HP14}
		Let $A$ and $B$ be Hermitian, and let $f$ be a continuously one-sided differentiable function defined around the eigenvalues of $A+t_0 B$.
		Then,
		\begin{align}
			\left.\frac{\d}{\d t} \Tr\left[ f(A+tB) \right]\right|_{t=t_0}
			= \Tr\left[ B \cdot  f'(A+t_0 B)\right].
		\end{align}
	\end{lemm}

	\begin{lemm}\label{lemm:Hockey-stick_convex_nonincreasing}
		Let $A,B\geq 0$.
		The Hockey-Stick divergence $E_{\gamma}(\rho\Vert\sigma)$ is convex nonincreasing in $\gamma \geq 0$.
	\end{lemm}
	\begin{proof}
		Let $0\leq \gamma \leq \gamma'$. We immediately have $A-\gamma B \geq A - \gamma' B$.
		Note that $(A-\gamma B)_+$ and $(A-\gamma' B)_+$ might not be comparable, but by the functional calculus (or the eigenvalue mapping theorem), the ordered eigenvalue are pointwise comparable, i.e.,~$\lambda^{\downarrow}_i(A-\gamma B) \geq \lambda^{\downarrow}_i(A-\gamma' B)$.
		After adding the positive eigenvalues, we have that $\gamma \mapsto E_{\gamma}(\rho\Vert\sigma)$ is nonincreasing.

		From the identity
		\begin{align}
			\Tr\left[ (A-\gamma B)_+ \right] 
			= \frac12 \left\| A - \gamma B \right\|_1 + \Tr\left[ A - \gamma B \right],
		\end{align}
		the convexity of the Hockey-stick divergence in $\gamma$ follows from the convexity of Schatten $1$-norm and the linearity of trace.
	\end{proof}

	We will need the following two theorems from the recent work~\cite{preparation}. These will crucially connect the integral representations with more traditional expressions. 
	\begin{theo}[Operator layer cake {\cite[Theorem B.1]{preparation}}] \label{theo:Dlog_formula}
		For any positive definite operator $A$ and any self-adjoint operator $B$ on a finite-dimensional Hilbert space,
		the following representation holds:
		\begin{align} \label{eq:Dlog_formula}
			\mathrm{D} \log[A](B) = \int_{0}^{\infty} \{ uA < B \} \d u\,-\,\int_{-\infty}^{0} \{ uA > B \} \d u,
		\end{align}
		where $ \mathrm{D} \log[A](B)=\frac{\d}{\d t}\log(A+tB)|_{t=0} $ is the directional derivative of the operator logarithm,
		and $ \{ uA < B \} \equiv \{ B - uA > 0 \} $ denotes the projection onto the positive part of $B-uA$.
	\end{theo}

	\begin{theo}[Operator change of variables{\cite[Theorem C.1]{preparation}}] \label{theo:change-of-variable}
		Let $A$ and $B$ be finite-dimensional positive semi-definite operators satisfying $r := \|A B^{-1} \|_{\infty} < \infty$.
		Then, for any Lebesgue-integrable function $h$ on $[0,r]$,
		\begin{align} \label{eq:change-of-variable}
			\int_0^\infty \proj{ A > \gamma B } h(\gamma) \, \d \gamma
			&= \int_0^\infty \frac{1}{B+t\I} A \frac{1}{\sqrt{B+t\I}} h\left(\frac{1}{\sqrt{B+t\I}} A \frac{1}{\sqrt{B+t\I}} \right)\frac{1}{\sqrt{B+t\I}} \, \d t
			\\
			&= \int_0^\infty \frac{1}{B+t\I} A \frac{1}{B+t\I} h\left( A \frac{1}{B+t\I} \right) \d t.
		\end{align}
	\end{theo}
	With these technical tools in hand, we can now start investigating their implications for quantum $f$-divergences in the following sections.  

