	\section{Layer cake representation of \Renyi and $f$-divergences} \label{sec:relation}

	We start by stating formal definitions of the quantum \Renyi and $f$-divergences that constitute the starting point of this work.  
	\begin{defn}[Quantum $f$-divergence]
		For convex function $f$ defined on $[0,\infty)$ satisfying $f(1) = 0$ and states $\rho$ and $\sigma$ such that $\rho\ll\sigma$,
		\begin{align}
			D^{\ast}_f(\rho\Vert\sigma) :=
			f(0) + \int_0^\infty \Tr\left[ \sigma \proj{ \rho > \gamma \sigma}\right] \, \d f(\gamma).
		\end{align}
		If $f$ is differentiable,
		\begin{align}\label{Eq:Def-1-dif}
			D^{\ast}_f(\rho\Vert\sigma) =
			f(0) + \int_0^\infty f'(\gamma) \Tr\left[ \sigma \proj{ \rho > \gamma \sigma}\right] \, \d \gamma.
		\end{align}
	\end{defn}
	We also define the corresponding \Renyi divergence. 
	\begin{defn}[Quantum \Renyi divergence]
		Let $\alpha \in (0,1)\cup(1,\infty)$.
		For states $\rho$ and $\sigma$ satisfying $\rho\ll\sigma$ unless $\alpha \in (0,1)$,
		\begin{align}
			D^{\ast}_{\alpha} (\rho\Vert\sigma)
			&:= \frac{1}{\alpha-1} \log Q^{\ast}_{\alpha}(\rho\Vert\sigma),
			\\
			Q^{\ast}_{\alpha}(\rho\Vert\sigma)
			&:= \alpha \int_0^\infty \gamma^{\alpha-1} \Tr\left[ \sigma  \proj{ \rho > \gamma \sigma }\right] \d \gamma, \quad \alpha > 0. \label{Eq:Q-layerCake}
		\end{align}
	\end{defn}
	Note that \Renyi and $f$-divergences are related via the Hellinger divergence,
	\begin{align}
		H_{\alpha}(\rho\Vert\sigma)
		:= D_{f_\alpha}(\rho\Vert\sigma),
	\end{align} 
	where $f_{\alpha}(x) = \frac{x^{\alpha}-1}{\alpha-1}$, $\alpha>0$, 
	by 
	\begin{align}\label{Eq:quasi-and-Hellinger}
		Q_{\alpha}(\rho\Vert\sigma)
		&= (\alpha-1) H_{\alpha} (\rho\Vert\sigma) + 1.
	\end{align}
	Also, by Lemma~\ref{Lem:HS-derivative}, we can write Equation~\eqref{Eq:Def-1-dif} as, 
	\begin{align}\label{Eq:Def-1-dif-HS}
		D^{\ast}_f(\rho\Vert\sigma) =
		f(0) - \int_0^\infty f'(\gamma) \frac{\d E_\gamma(\rho\|\sigma)}{\d\gamma} \, \d \gamma.
	\end{align}
	This is suggestive towards a connection to $f$-divergences based on Hockey Stick divergences. 
	In his PhD thesis~\cite{polyanskiy2010channel}, Polyanskiy gave the following integral representation for the relative entropy,
	\begin{align}
		D(P\Vert Q)
		&=1 - \int_0^\infty \log \gamma \frac{\d E_{\gamma}(P\Vert Q)}{\d \gamma} \d \gamma.
	\end{align}
	Our definition can be seen as an extension to general $f$-divergences that is well defined also in the quantum setting\footnote{The relative entropy special case follows from Equation~\eqref{Eq:Def-1-dif-HS} with $f(x)=x\log x$ and applying Equation~\eqref{Eq:shiftByC}, which is shown a bit later, with $c=1$.}. 
	Our first main result is that the above definitions are equivalent to those in Equations~\eqref{Eq:int-quasi-petz} and~\eqref{Eq:int-f-div} previously proposed in~\cite{hirche2023quantum}. 

	Let $\cF$ be the set of functions $f:(0,\infty)\rightarrow\bbR$ with $f(1)=0$ that are convex and twice differentiable. 
	\begin{theo} \label{theorem:f_divergence_layer-cake}
		For any $f\in\cF$ or $\alpha\in(0,1)\cup(1,\infty)$, we have
		\begin{align}
			D^{\ast}_f(\rho\|\sigma) &=   D_f(\rho\|\sigma)  \\
			D^{\ast}_\alpha(\rho\|\sigma) &=   D_\alpha(\rho\|\sigma)
		\end{align}
	\end{theo}
	\begin{proof}
		By the relation in~\eqref{Eq:quasi-and-Hellinger} it is sufficient to prove the first equality. Set, $\beta_2=e^{-D_{\max}(\sigma\|\rho)}$ and $\beta_1^{-1}=e^{D_{\max}(\rho\|\sigma)}$. In~\cite[Equation~(4.17)]{beigi2025some} the following expression was shown, 
		\begin{align}
			D_f(\rho\|\sigma) &=   f({\beta_2}) - f(1) - \sum_{i=0}^N \left(  \int_{a_i}^{a_{i+1}} f'(\gamma)  E'_\gamma(\rho\|\sigma) \d\gamma \right),  
		\end{align}
		where the $a_i$ are a finite number of points for which $E'_\gamma(\rho\|\sigma)$ is not continuous. Because at any such point the left and right derivatives exist and are finite, we can extend this to 
		\begin{align}
			D_f(\rho\|\sigma) &=   f({\beta_2}) - f(1) -   \int_{\beta_2}^{\beta_1^{-1}} f'(\gamma)  E'_\gamma(\rho\|\sigma) \d\gamma.  
		\end{align}
		Note that, 
		\begin{align}
			\int_{0}^{\beta_2} f'(\gamma)  E'_\gamma(\rho\|\sigma) \d\gamma = -\int_{0}^{\beta_2} f'(\gamma)   \d\gamma = f(0) - f(\beta_2). 
		\end{align}
		Hence, 
		\begin{align}
			D_f(\rho\|\sigma) &=   f(0) - f(1) -   \int_{0}^{\beta_1^{-1}} f'(\gamma)  E'_\gamma(\rho\|\sigma) \d\gamma.   
		\end{align}
		Finally, the result follows because the Hockey-Stick divergence is constant and equal to $0$ for all $\gamma\geq\beta_1^{-1}$ and by using Lemma~\ref{Lem:HS-derivative}. 
	\end{proof}

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



	Note that, 
	\begin{align}
		-\int_0^\infty \frac{\d E_{\gamma}(\rho\Vert\sigma)}{\d \gamma} \d \gamma = E_0(\rho\|\sigma) - E_\infty(\rho\|\sigma) = 1. 
	\end{align}
	Hence, we can modify the representation with arbitrary constants, 
	\begin{align}\label{Eq:shiftByC}
		D_f(\rho\|\sigma) &=   f(0) + c -   \int_{0}^{\infty} (f'(\gamma)-c)  E'_\gamma(\rho\|\sigma) \d\gamma 
	\end{align}
	For the particular case of the Hellinger divergence, we can give further integral representations. Interestingly, here we have to consider different values of $\alpha$ separately. 
	\begin{lemm} \label{lemm:alpha-representation}
		We have, for $0<\alpha<1$, 
		\begin{align}
			(\alpha-1)H_\alpha(\rho\|\sigma) &= (1-\alpha) \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho\leq\gamma\sigma\}] \d\gamma - 1 \label{eq:layer-cake_alpha<1-0}\\
			&= (1-\alpha) \int_0^\infty \gamma^{-\alpha} \tr[\rho\{\gamma\rho\leq\sigma\}] \d\gamma - 1
			\label{eq:layer-cake_alpha<1}
		\end{align}
		and, for $\alpha>1$, 
		\begin{align}
			(\alpha-1)H_\alpha(\rho\|\sigma) &= (\alpha-1) \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho>\gamma\sigma\}] \d\gamma  -1  \label{eq:layer-cake_alpha>1-0}\\
			&= (\alpha-1) \int_0^\infty \gamma^{-\alpha} \tr[\rho\{\gamma\rho>\sigma\}] \d\gamma  -1 .
		\end{align}
	\end{lemm}


	\begin{proof}[Proof of Lemma~\ref{lemm:alpha-representation}]
		Here, we use the integral representation found in~\cite{hirche2023quantum}, which can be written as, 
		\begin{align}
			H_\alpha(\rho\|\sigma) = \alpha \int_0^\infty \gamma^{\alpha-2} E_\gamma(\rho\|\sigma) \d\gamma - \alpha\int_0^1 \gamma^{\alpha-2}(1-\gamma) \d\gamma.
		\end{align}
		Recall that, 
		\begin{align}
			E_\gamma(\rho\|\sigma) = \tr(\rho-\gamma\sigma)_+ = \tr[\rho\{\rho>\gamma\sigma\}] - \gamma\tr[\sigma\{\rho>\gamma\sigma\}]. 
		\end{align}
		With, this we start by proving the case of $0<\alpha<1$, 
		\begin{align}
			H_\alpha(\rho\|\sigma) &= \alpha \int_0^\infty \gamma^{\alpha-2} \left(\tr[\rho\{\rho>\gamma\sigma\}] - \gamma\tr[\sigma\{\rho>\gamma\sigma\}] \right)\d\gamma - \alpha\int_0^1 \gamma^{\alpha-2}(1-\gamma) \d\gamma \\
			\label{Eq:Ha-step2}
			&= \alpha \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho>\gamma\sigma\}] \d\gamma  -1 -(\alpha-1) H_\alpha(\rho\|\sigma) - \alpha\int_0^1 \gamma^{\alpha-2}(1-\gamma) \d\gamma \\
			&= \alpha \int_0^\infty \gamma^{\alpha-2} \left(1-\tr[\rho\{\rho\leq\gamma\sigma\}]\right) \d\gamma  -1 -(\alpha-1) H_\alpha(\rho\|\sigma) - \alpha\int_0^1 \gamma^{\alpha-2}(1-\gamma) \d\gamma \\
			&= -\alpha \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho\leq\gamma\sigma\}] \d\gamma  -1 -(\alpha-1) H_\alpha(\rho\|\sigma) + \alpha\int_1^\infty \gamma^{\alpha-2} \d\gamma + \alpha\int_0^1 \gamma^{\alpha-1} \d\gamma \\
			&= -\alpha \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho\leq\gamma\sigma\}] \d\gamma   -(\alpha-1) H_\alpha(\rho\|\sigma) -\frac{\alpha}{\alpha-1}\\
			&= -\alpha \int_0^\infty \gamma^{-\alpha} \tr[\rho\{\gamma\rho\leq\sigma\}] \d\gamma   -(\alpha-1) H_\alpha(\rho\|\sigma) -\frac{\alpha}{\alpha-1}, 
		\end{align}
		where for the second equality we used Equation~\eqref{Eq:Q-layerCake} and the final equality is substituting $\gamma'=\gamma^{-1}$ in the integral. The claim then follows be rearranging the terms. 

		We continue by proving the claim for $\alpha>1$, starting from Equation~\eqref{Eq:Ha-step2},
		\begin{align}
			H_\alpha(\rho\|\sigma) &= \alpha \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho>\gamma\sigma\}] \d\gamma  -1 -(\alpha-1) H_\alpha(\rho\|\sigma) - \alpha\int_0^1 \gamma^{\alpha-2}(1-\gamma) \d\gamma  \\
			&= \alpha \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho>\gamma\sigma\}] \d\gamma  -1 -(\alpha-1) H_\alpha(\rho\|\sigma) - \frac{1}{\alpha-1} \\
			&= \alpha \int_0^\infty \gamma^{-\alpha} \tr[\rho\{\gamma\rho>\sigma\}] \d\gamma  -1 -(\alpha-1) H_\alpha(\rho\|\sigma) - \frac{1}{\alpha-1}.
		\end{align}
		The claim follows again after some rearranging. 
	\end{proof}    
	This new representation gives us immediately the following corollary. 
	\begin{coro}
		For $0<\alpha<1$,
		\begin{align}
			D_{\alpha}(\rho \Vert \sigma)
			= \frac{\alpha}{1-\alpha} D_{1-\alpha}(\sigma \Vert \rho).
		\end{align}
	\end{coro}
	\begin{proof}
		It is equivalent to proving 
		\begin{align}
			(\alpha-1) H_{\alpha}(\rho \Vert \sigma)
			= - \alpha H_{1-\alpha}(\sigma \Vert \rho).
		\end{align}
		We start with \eqref{eq:layer-cake_alpha<1-0}:
		\begin{DispWithArrows}[displaystyle]
			- \alpha H_{1-\alpha}(\sigma \Vert \rho) -1
			&= \alpha \int_0^\infty \gamma^{-\alpha-1} \tr[\sigma\{\sigma < \gamma\rho\}] \d\gamma 
			\Arrow{$\gamma \leftarrow \frac{1}{\gamma}$} -1
			\\
			&= \alpha \int_\infty^0 \gamma^{\alpha+1} \tr[\sigma\{\gamma \sigma < \rho\}] \left( - \frac{1}{\gamma^2} \right)\d\gamma -1
			\\
			&=\alpha \int_0^\infty \gamma^{\alpha-1} \tr[\sigma\{\gamma \sigma < \rho\}]\d\gamma -1
			\Arrow{\eqref{Eq:quasi-and-Hellinger}}
			\\
			&= (\alpha-1) H_{\alpha}(\rho \Vert \sigma).
		\end{DispWithArrows}
	\end{proof}
	We next turn our attention to implications of the new divergences. 



	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	\section{Trace representations for \(f\)-divergences}

	Earlier work in~\cite{beigi2025some} coined the term \textit{trace representations} for the expressions that resemble the most usual representations of divergences that are given by the trace of some operator function.  Of course the best known example is given by the typical expression for the Umegaki relative entropy~\cite{Ume62}, 
	\begin{align} \label{eq:defn:Umegaki}
		D(\rho\Vert\sigma) := \Tr\left[ \rho \left( \log \rho - \log \sigma \right) \right].
	\end{align}
	The relative entropy is a special case of the studied $f$-divergence for $f(x) = x \log x$.
	This observation from~\cite{hirche2023quantum} was made using an integral representation by Frenkel~\cite{frenkel2022integral}. 

	In the following, we first give an alternative proof of this statement based on the layer cake representation. 
	After that we proof a conjecture regarding a trace representation for the \Renyi divergence for $\alpha>1$ from~\cite{beigi2025some}. Finally, we briefly discuss the case of general $f$-divergences. 

	\subsection{The relative entropy (an alternative proof for Frenkel's formula)} \label{sec:alpha=1}


	In this section we provide an alternative proof of the integral formula for the relative entropy by Frenkel. We start by giving an alternative representation. 
	\begin{prop} \label{prop:algernative_proof_Frenkel}
		For any positive definite operators $A$ and $B$, we have
		\begin{align}
			\log A - \log B 
			&= \int_1^{\infty} \left\{ A > \alpha B \right\} \frac{1}{\alpha} \d \alpha - \int_1^{\infty} \left\{ B > \alpha A \right\} \frac{1}{\alpha} \d \alpha,
			\label{eq:log-difference1}
			\\
			D(A\Vert B)
			&= \int_1^\infty \frac{1}{\gamma} \Tr\left[ A \left( \left\{ A > \gamma B \right\} - \left\{ B > \gamma A \right\} \right) \right] \d \gamma.
			\label{eq:D-projection}
		\end{align}
	\end{prop}
	\begin{proof}
		Using the fundamental theorem of calculus and Theorem~\ref{theo:Dlog_formula}, we write
		\begin{align}
			\begin{split} \label{eq:FTC}
				&\log A - \log B 
				= \int_0^1 \mathrm{D} \log \left[ B + \beta (A-B) \right](A-B) \, \d \beta
				\\
				&=
				\underbrace{
					\int_0^1 \int_0^\infty \left\{ A-B > \left( B + \beta(A-B)\right)u \right\} \d u \,\d \beta
				}_{\text{(I) }}
				-
				\underbrace{
					\int_{0}^1 \int_{-\infty}^0 \left\{ A-B < \left( B + \beta(A-B)\right)u \right\} \d u \,\d \beta
				}_{\text{(II)}}.
			\end{split}
		\end{align}
		We continue by evaluating the individual terms, starting with the first.
		\begin{DispWithArrows}[displaystyle, fleqn, mathindent = 75pt]
			\text{(I)}
			&= \int_0^1 \int_0^\infty \left\{ (1-u\beta) (A-B) > u B \right\} \d u \,\d \beta
			\Arrow{for $0\leq \beta \leq 1$ and $u\beta \geq 1$,\\
				\quad $(1-u\beta) (A-B) \leq u B$ } \notag
			\\
			&= \int_0^1 \int_0^{\frac{1}{\beta}} \left\{ (1-u\beta) (A-B) > u B\right\} \d u \,\d \beta \notag
			\\
			&= \int_0^1 \int_0^{\frac{1}{\beta}} \left\{ A - B > \frac{u}{1-u\beta} B \right\} \d u\, \d\beta
			\Arrow{$\gamma = \frac{u}{1-u\beta}$, $\d u = \frac{1}{(1+\beta\gamma)^2}\d \gamma$} \notag
			\\ 
			&= \int_0^1 \int_0^{\infty} \left\{ A - B > \gamma B \right\} \frac{1}{(1+\beta \gamma)^2} \d \gamma \, \d \beta 
			\Arrow{$\because$ Fubini's theorem and \\ dominated convergence theorem}
			\notag
			\\ 
			&= \int_0^{\infty} \left\{ A - B > \gamma B \right\} \int_0^1 \frac{1}{(1+\beta \gamma)^2} \d \beta \, \d \gamma \notag
			\\
			&=\int_0^{\infty} \left\{ A - B > \gamma B \right\} \frac{1}{\gamma + 1} \d \gamma 
			\Arrow{$\alpha  = \gamma + 1$} \notag
			\\
			&= \int_1^{\infty} \left\{ A > \alpha B \right\} \frac{1}{\alpha} \, \d \alpha. 
			\label{eq:(I)}
		\end{DispWithArrows}
		For the second term we get the following.
		\begin{DispWithArrows}[displaystyle, fleqn, mathindent = 65pt] 
			\text{(II)}
			&= \int_0^1 \int_{-\infty}^0 \left\{ (1-u\beta) (A-B) < u B \right\} \d u \,\d \beta 
			\notag
			\\
			&= \int_0^1 \int_{-\infty}^0 \left\{ (1-u\beta+u) (A-B) < u A \right\} \d u \,\d \beta
			\Arrow{for $0\leq \beta \leq 1$ and $u(1-\beta)\leq -1$
				\\ \quad $(1-u\beta+ u) (A-B) \geq u A$ } \notag
			\\
			&= \int_0^1 \int_{\frac{1}{\beta-1}}^0 \left\{ A - B < \frac{u}{1-u\beta+u} A \right\} \d u \, \d \beta 
			\Arrow{$\gamma = \frac{u}{1+(1-\beta)u}$, $\d u = \frac{\d \gamma}{\left(1+(\beta-1)\gamma\right)^2}$}  \notag
			\\
			&= \int_0^1 \int_{-\infty}^0 \left\{ A - B < \gamma A \right\} \frac{1}{\left( 1 + (\beta-1)\gamma\right)^2} \d \gamma \, \d \beta 
			\Arrow{$\because$ Fubini's theorem and\\ \, dominated convergence theorem}
			\notag
			\\
			&=
			\int_{-\infty}^0 \left\{ A - B < \gamma A \right\} \int_0^1 \frac{1}{\left( 1 + (\beta-1)\gamma\right)^2} \d \beta \, \d \gamma \notag
			\\
			&= \int_{-\infty}^0 \left\{ A - B < \gamma A \right\} \frac{1}{1-\gamma} \d \gamma
			\Arrow{$\alpha = 1-\gamma$} \notag
			\\
			&= \int_1^{\infty} \left\{ B > \alpha A \right\} \frac{1}{\alpha} \d \alpha.
			\label{eq:(II)}
		\end{DispWithArrows}
		Combining \eqref{eq:FTC}, \eqref{eq:(I)}, and \eqref{eq:(II)}, we have
		\begin{align}
			\log A - \log B 
			&= \int_1^{\infty} \left\{ A > \alpha B \right\} \frac{1}{\alpha} \d \alpha - \int_1^{\infty} \left\{ B > \alpha A \right\} \frac{1}{\alpha} \d \alpha,
			\notag
			\\
			D(A\Vert B)
			&= \int_1^\infty \frac{1}{\gamma} \Tr\left[ A \left( \left\{ A > \gamma B \right\} - \left\{ B > \gamma A \right\} \right) \right] \d \gamma.
			\notag\qedhere
		\end{align}
	\end{proof}

	The following is a restatement of the result by Frenkel~\cite{frenkel2022integral}. However, we follow an alternative path by building on our previous result. 
	\begin{prop} \label{prop:algernative_proof_Frenkel2}
		For any positive definite operators $A$ and $B$, we have
		\begin{align}
			D(A\Vert B )
			&= \int_1^\infty \Big(\frac{1}{\gamma} E_\gamma(A\|B) +  \frac{1}{\gamma^2} E_\gamma(B\|A)\Big)\, \d \gamma
			+ \Tr[A - B].
		\end{align}
	\end{prop}
	\begin{proof}
		Continuing from the previous proposition,
		\begin{DispWithArrows}[displaystyle] 
			&\int_1^\infty \frac{1}{\gamma} \Tr\left[ A \left( \left\{ A > \gamma B \right\} - \left\{ B > \gamma A \right\} \right) \right] \d \gamma
			\notag
			\\
			&= \int_1^{\infty} \Tr\left[ \frac{1}{\gamma} \left( A - \gamma B \right) \left\{ A > \gamma B \right\} + \frac{1}{\gamma^2} \left( B - \gamma A \right) \left\{ B > \gamma A \right\} \right] \d \gamma \notag
			\\
			&\quad + \int_1^{\infty} \Tr\left[ B \left\{ A > \gamma B \right\} \right] \d \gamma 
			- \int_1^{\infty} \frac{1}{\gamma^2} \Tr\left[  B \left\{ B > \gamma A \right\} \right] \d \gamma \notag
			\\
			&= \int_1^\infty \Big(\frac{1}{\gamma} E_\gamma(A\|B) +  \frac{1}{\gamma^2} E_\gamma(B\|A)\Big)\, \d \gamma \notag
			\\
			&\quad + \underbrace{\int_1^{\infty} \Tr\left[ B \left\{ A > \gamma B \right\} \right] \d \gamma}_{\text{(i)}} 
			- \underbrace{\int_1^{\infty} \frac{1}{\gamma^2} \Tr\left[  B \left\{ B > \gamma A \right\} \right] \d \gamma}_{\text{(ii)}}, \label{eq:temp}
		\end{DispWithArrows}
		and
		\begin{DispWithArrows}[displaystyle] 
			\text{(i)}
			&= \int_1^{\infty} \Tr\left[ B \left\{ A > \gamma B \right\} \right] \d \gamma
			\notag
			\\
			&=  -\int_0^1 \Tr\left[ B \left\{ A > \gamma B \right\}\right] \d \gamma 
			+ \int_0^{\infty} \Tr\left[ B \left\{ A > \gamma B\right\}\right] \d \gamma \notag
			\\
			&= -\int_0^1 \Tr\left[ B \left\{ A > \gamma B \right\} \right] \d \gamma 
			+  \Tr[A],
			\label{eq:(i)}
		\end{DispWithArrows}

		\begin{DispWithArrows}[displaystyle] 
			\text{(ii)}
			&= \int_1^{\infty} \frac{1}{\gamma^2} \Tr\left[  B \left\{ B > \gamma A \right\} \right] \d \gamma
			\Arrow{$\alpha = \frac{1}{\gamma}$}
			\notag
			\\
			&= \int_0^1 \Tr\left[ B \left\{ \alpha B > A \right\} \right] \d \alpha
			\notag
			\\
			&= \int_0^1 \Tr\left[ B \left( \I - \left\{ \alpha B \leq A \right\} \right) \right] \d \alpha
			\Arrow{ $\because \{\alpha\mid\{\alpha B = A \}\neq 0\}$\\ \phantom{\,$\because$\,}\text{has measure zero}}
			% \Arrow{ $\because \{\alpha B = A \}$ \text{has measure zero}}
			\notag
			\\
			&= \int_0^1 \Tr\left[ B \left( \I - \left\{ \alpha B < A \right\} \right) \right] \d \alpha
			\notag
			\\
			&= \Tr[B] - \int_0^1 \Tr\left[ B \left\{ A > \alpha B \right\} \right] \d \alpha.
			\label{eq:(ii)}
		\end{DispWithArrows}

		By \eqref{eq:D-projection}, \eqref{eq:temp}, \eqref{eq:(i)}, and \eqref{eq:(ii)}, we obtain
		\begin{align}
			D(A\Vert B )
			&= \int_1^\infty \frac{1}{\gamma} \Tr\left[ A \left( \left\{ A > \gamma B \right\} - \left\{ B > \gamma A \right\} \right) \right] \d \gamma
			\\
			&= \int_1^\infty \Big(\frac{1}{\gamma} E_\gamma(A\|B) +  \frac{1}{\gamma^2} E_\gamma(B\|A)\Big)\, \d \gamma
			+ \Tr[A - B].
		\end{align}
	\end{proof}

	\subsection{The \Renyi divergence for \(\alpha > 1\)} \label{sec:alpha>1}

	In this section, we prove the trace expression conjectured in~\cite{beigi2025some} for the \Renyi divergence with $\alpha>1$. For now, we focus on normalized quantum states. That is because we can give a particularly simple proof using the previously derived results. Afterwards, we comment on the case of more general positive operators. 

	\begin{theo}\label{Theo:trace-renyi-QS}
		For any quantum states $\rho$, $\sigma$ and any $\alpha>1$,
		\begin{align}
			H_{\alpha}(\rho\Vert \sigma)
			&= \frac{-1}{\alpha-1} + \int_0^\infty \Tr\left[ \left( \rho \frac{1}{\sigma+t\I} \right)^{\alpha} \right] \d t .
		\end{align}
	\end{theo}
	\begin{proof}
		Recall the layer cake representation in Equation~\eqref{Eq:Def-1-dif}, which speciallised to the Hellinger divergence gives,
		\begin{align}
			H_\alpha(\rho\Vert\sigma) =
			\frac{-1}{\alpha-1} + \frac{\alpha}{\alpha-1}\int_0^\infty \gamma^{\alpha-1} \Tr\left[ \sigma \proj{ \rho > \gamma \sigma}\right] \, \d \gamma.
		\end{align}
		Using Theorem~\ref{theo:Dlog_formula} then gives, 
		\begin{align}
			H_\alpha(\rho\Vert\sigma) &=
			\frac{-1}{\alpha-1} + \frac{\alpha}{\alpha-1}\int_0^\infty \Tr\left[ \sigma \frac{1}{\sigma+t\I} \rho \frac{1}{\sigma+t\I} \left( \rho \frac{1}{\sigma+t\I} \right)^{\alpha-1} \right] \, \d t \\
			&=
			\frac{-1}{\alpha-1} + \frac{\alpha}{\alpha-1}\int_0^\infty \Tr\left[ \sigma \frac{1}{\sigma+t\I}  \left( \rho \frac{1}{\sigma+t\I} \right)^{\alpha} \right] \, \d t. \label{Eq:Almost-tr-exp}
		\end{align}
		Finally, we employ Lemma~\ref{lemm:order_above_1} below, from which the result immediately follows.
	\end{proof}
	% Note that the above proof only works for $\alpha>1$, because of the corresponding requirement in Lemma~\ref{lemm:order_above_1}. The intermediate result in Equation~\eqref{Eq:Almost-tr-exp} also holds for $0<\alpha<1$ and can be compared to the trace representation given in~\cite{beigi2025some}. 
	% \HC{I see. Didn't notice that \ref{Eq:Almost-tr-exp} also holds for $0<\alpha<1$. Here, we mainly focused on $\alpha>1$ only. Maybe there's a way or the above way can be adapted to deal with $0<\alpha<1$ as well.}

	% \smallskip

	Once we move to positive operators, we can not as much rely on the previously derived results. We here state the formal result and provide the proof in the Appendix. 
	\begin{theo}\label{Theo:trace-renyi-PO}
		For positive semidefinite operators $A, B$ and any $\alpha>1$,
		\begin{align}
			H_{\alpha}(A\Vert B)
			&= \frac{-1}{\alpha-1}\Tr[A] + \int_0^\infty \Tr\left[ \left( A \frac{1}{B+t\I} \right)^{\alpha} \right] \d t .
		\end{align}
	\end{theo}
	The proof relies again strongly on Theorem~\ref{theo:Dlog_formula} and Lemma~\ref{lemm:order_above_1}, however it takes a more direct route from the integral representation rather than using the layer cake representation. For details we refer to the Appendix~\ref{sec:appendix_proof}. 

	Theorem~\ref{Theo:trace-renyi-PO} with the observation made in \cite{beigi2025some} allow us to relate the integral quasi \Renyi divergence to the quasi sandwiched \Renyi divergence.

	\begin{prop}[Relation to quasi sandwiched \Renyi divergence] \label{prop:relation_sandwiched}
		For any quantum states $\rho,\sigma $ satisfying $\rho\ll\sigma$, and any $\alpha > 1$,
		\begin{align}
			Q_{\alpha}(A \Vert B ) \leq \Tr\left[ \left( B^{\frac{1-\alpha}{2\alpha}}A  B^{\frac{1-\alpha}{2\alpha}} \right)^{\alpha} \right].
		\end{align}
	\end{prop}
	\begin{proof}
		The claim follows from Theorem~\ref{Theo:trace-renyi-PO} and 
		\cite[Proposition~3.10]{beigi2025some}  for $\alpha >1$.
	\end{proof}

	\smallskip
	Finally, we need to prove the lemma that makes all of the results in this section possible. 
	\begin{lemm} \label{lemm:order_above_1}
		Let $A$ and $B$ be positive semi-definite operators satisfying $ \|A B^{-1} \|_{\infty} < \infty$.
		Then, 
		\begin{align}
			\int_0^\infty \Tr\left[ B \frac{1}{B+t\I} \left( A \frac{1}{B+t\I} \right)^\alpha \right] \d t
			&= \frac{\alpha-1}{\alpha} \int_0^\infty \Tr\left[ \left( A \frac{1}{B + t\I} \right)^\alpha\right] \d t, \quad \forall\, \alpha>1.
		\end{align}
	\end{lemm}
	\begin{proof}
		The claim is equivalent to proving 
		\begin{align}
			\int_0^\infty \Tr\left[ \frac{t}{B+t\I} \left( A \frac{1}{B+t\I} \right)^\alpha \right] \d t
			&= \frac{1}{\alpha} \int_0^\infty \left( A \frac{1}{B + t\I} \right)^\alpha \d t.
		\end{align}

		Let $n = \lfloor \alpha \rfloor$ and $\tilde{\alpha} = \alpha - n$.
		We first calculate,
		\begin{align}
			\frac{\d}{\d t}\left[\left( A \frac{1}{B+t\I} \right)^{\alpha} \right]
			&= \frac{\d}{\d t}\bigg[ \underbrace{ A \frac{1}{B+t\I} \cdots A \frac{1}{B+t\I} }_{\text{$n$ times}} \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}} \bigg]
			\notag
			\\
			\begin{split}
				\label{eq:order_above_1:derivative}
				&= A \frac{-1}{(B+t\I)^2} A \frac{1}{B+t\I} A \frac{1}{B+t\I} \cdots \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}
				\\
				&+A \frac{1}{B+t\I} \frac{-1}{(B+t\I)^2} A \frac{1}{B+t\I}  \cdots \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}
				\\
				&\quad\vdots
				\\
				&+ A \frac{1}{B+t\I} A \frac{1}{B+t\I} \cdots \frac{-1}{(B+t\I)^2} \cdot \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}
				\\
				&+ \left(A \frac{1}{B+t\I} \right)^n  \cdot \frac{\d}{\d t} \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}.
			\end{split}
		\end{align}
		Note that the first $n$ terms of \eqref{eq:order_above_1:derivative}
		have the same trace $\Tr\left[ \frac{-1}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha} \right]$.
		We then calculate the trace of the last term in \eqref{eq:order_above_1:derivative}.
		By using the integral representation for the power function $0<x \mapsto x^{\tilde{\alpha}}$, i.e., $X^{\tilde{\alpha}} =  \int_0^\infty  \lambda^{\tilde{\alpha}-1} X \frac{1}{X+ \lambda\I} \d \lambda \cdot \frac{ \sin \alpha \pi }{\pi}$, we have
		\begin{align*}
			\frac{\d}{\d t} \left[ \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}} \right]
			&= \frac{\d}{\d t} \int_0^\infty \lambda^{\tilde{\alpha}-1} A \frac{1}{B+t\I}  \frac{1}{A \frac{1}{B+t\I} + \lambda\I} \d \lambda \cdot \frac{ \sin \alpha \pi }{\pi}
			\\
			&= \frac{\d}{\d t} \int_0^\infty \lambda^{\tilde{\alpha}-1} A  \frac{1}{A  + \lambda (B+t\I)  } \d \lambda \cdot \frac{ \sin \alpha \pi }{\pi}
			\\
			&= \int_0^\infty \lambda^{\tilde{\alpha}-1} A  \frac{-\lambda}{\left(A  + \lambda (B+t\I) \right)^2 } \d \lambda \cdot \frac{ \sin \alpha \pi }{\pi}
			\\
			&= \int_0^\infty - \lambda^{\tilde{\alpha}} A \frac{1}{B+t\I} \frac{1}{A \frac{1}{B+t\I} + \lambda \I} \frac{1}{B+t\I} \frac{1}{A \frac{1}{B+t\I} + \lambda \I} \d \lambda \cdot \frac{ \sin \alpha \pi }{\pi}.
		\end{align*}
		Hence, the trace of the last term in \eqref{eq:order_above_1:derivative} is
		\begin{align}
			&\Tr\left[ \left( A \frac{1}{B+t\I} \right)^n \frac{\d}{\d t} \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}} \right]
			\notag
			\\
			&= \Tr\left[ \left( A \frac{1}{B+t\I} \right)^n \int_0^\infty - \lambda^{\tilde{\alpha}} A \frac{1}{B+t\I} \frac{1}{A \frac{1}{B+t\I} + \lambda \I} \frac{1}{B+t\I} \frac{1}{A \frac{1}{B+t\I} + \lambda \I} \d \lambda \right]\cdot \frac{ \sin \alpha \pi }{\pi}
			\notag
			\\
			&=\Tr\left[ \left( A \frac{1}{B+t\I} \right)^{n+1} \int_0^\infty - \lambda^{\tilde{\alpha}}  \frac{1}{A \frac{1}{B+t\I} + \lambda \I} \frac{1}{B+t\I} \frac{1}{A \frac{1}{B+t\I} + \lambda \I} \d \lambda \right]\cdot \frac{ \sin \alpha \pi }{\pi}
			\notag
			\\
			&=\Tr\left[ \left( A \frac{1}{B+t\I} \right)^{n+1} \int_0^\infty - \lambda^{\tilde{\alpha}}  \frac{1}{\left(A \frac{1}{B+t\I} + \lambda \I\right)^2}  \d \lambda \cdot \frac{ \sin \alpha \pi }{\pi} \frac{1}{B+t\I}\right]
			\notag
			\\
			&=\Tr\left[ \left( A \frac{1}{B+t\I} \right)^{n+1} \left\{ - \tilde{\alpha} \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}-1} \right\} \frac{1}{B+t\I}\right]
			\notag
			\\
			&= - \tilde{\alpha} \Tr\left[ \frac{1}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha} \right].
			\label{eq:order_above_1:derivative1}
		\end{align}

		Using \eqref{eq:order_above_1:derivative}, we now calculate
		\begin{align}
			\frac{\d}{\d t}\left[ t \left( A \frac{1}{B+t\I} \right)^{\alpha} \right]
			\notag
			&= \left( A \frac{1}{B+t\I} \right)^{\alpha}
			+ t \frac{\d}{\d t}\left[\left( A \frac{1}{B+t\I} \right)^{\alpha} \right]
			\notag
			\\
			\begin{split} \label{eq:order_above_1:derivative2}
				&= \left( A \frac{1}{B+t\I} \right)^{\alpha} + t A \frac{-1}{(B+t\I)^2} A \frac{1}{B+t\I} A \frac{1}{B+t\I} \cdots \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}
				\\
				&\qquad\qquad\qquad\quad\;\, + t A \frac{1}{B+t\I} \frac{-1}{(B+t\I)^2} A \frac{1}{B+t\I}  \cdots \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}
				\\
				&\qquad\qquad\qquad\quad\quad \vdots
				\\
				&\qquad\qquad\qquad\quad\;\, + tA \frac{1}{B+t\I} A \frac{1}{B+t\I} \cdots \frac{-1}{(B+t\I)^2} \cdot \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}
				\\
				&\qquad\qquad\qquad\quad\;\, + t\left(A \frac{1}{B+t\I} \right)^n  \cdot \frac{\d}{\d t} \left( A \frac{1}{B+t\I} \right)^{\tilde{\alpha}}.
			\end{split}
		\end{align}

		Using \eqref{eq:order_above_1:derivative1}, we take $\int_0^\infty \Tr[ \,\cdot\, ]\d t $ on \eqref{eq:order_above_1:derivative2} to obtain
		\begin{align}
			\int_0^\infty \Tr \left[ \frac{\d}{\d t} t \left( A \frac{1}{B+t\I} \right)^{\alpha} \right]
			&=
			\int_0^\infty \Tr\left[ \left( A \frac{1}{B+t\I} \right)^{\alpha} \right] \d t
			\notag
			\\
			&\quad - n \cdot \int_0^\infty \Tr\left[ \frac{t}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha} \right] - \tilde{\alpha} \cdot \int_0^\infty \Tr\left[ \frac{t}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha} \right]
			\notag
			\\
			&= \int_0^\infty \Tr\left[ \left( A \frac{1}{B+t\I} \right)^{\alpha} \right] \d t - \alpha \int_0^\infty \Tr\left[ \frac{t}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha}\right].
			\label{eq:order_above_1:derivative3}
		\end{align}

		On the other hand, for $\alpha>1$ and bounded $A$, we have
		\begin{align}
			\int_0^\infty \Tr \left[ \frac{\d}{\d t} t \left( A \frac{1}{B+t\I} \right)^{\alpha} \right]
			&=  \Tr \left[ \int_0^\infty\frac{\d}{\d t} t \left( A \frac{1}{B+t\I} \right)^{\alpha} \right]
			\notag
			\\
			&= \left. \Tr \left[  t \left( A \frac{1}{B+t\I} \right)^{\alpha} \right] \right|_{0}^\infty
			\notag
			\\
			&= 0
			\label{eq:order_above_1:derivative4}
		\end{align}
		Combining \eqref{eq:order_above_1:derivative3} and \eqref{eq:order_above_1:derivative4}, we get
		\begin{align}
			\int_0^\infty \Tr\left[ \left( A \frac{1}{B+t\I}\right)^{\alpha} \right]
			= \alpha \int_0^\infty \Tr \left[ \frac{t}{B+t\I} \left( A \frac{1}{B+t\I}\right)^{\alpha} \right], 
			\notag
		\end{align}
		concluding the proof.
	\end{proof}

	\medskip 
	By applying a change-of-measure argument (Lemma~\ref{lemm:change-of-measure}) that will be introduced later in Section~\ref{sec:RS-integral},
	Lemma~\ref{lemm:order_above_1} has a simpler proof, which we provide below.
	\begin{proof}[An alternative proof of Lemma~\ref{lemm:order_above_1}]
		Recall \eqref{eq:change-of-measure_combined} of Lemma~\ref{lemm:change-of-measure}:
		\begin{align*}
			\int_0^\infty g'(\gamma) \Tr[A\{A>\gamma B\}] \, \d \gamma=\int_0^\infty \left(g(\gamma)+\gamma g'(\gamma)\right) \Tr[A\{A>\gamma B\}] \, \d \gamma.
		\end{align*}

		Let $g(\gamma)=\gamma^{\alpha-1}$, $g'(\gamma)=(\alpha-1)\gamma^{\alpha-2}$, then
		\[
		(\alpha-1)\int_0^\infty \gamma^{\alpha-2} \Tr[A\{A>\gamma B\}] \, \d \gamma
		=\alpha \int_0^\infty \gamma^{\alpha-1} \Tr[B\{A>\gamma B\}] \, \d \gamma
		\]

		By Theorem~\ref{theo:change-of-variable},
		\begin{align}
			\int_0^\infty \Tr\left[ B\frac{1}{B+t\I}\left(A\frac{1}{B+t\I}\right)^\alpha \right]\d t 
			&=\Tr \left[ B \int_0^\infty \gamma^{\alpha-1} \{A>\gamma B\} \right] \, \d \gamma\\
			&=\frac{\alpha-1}{\alpha} \Tr \left[ A \int_0^\infty \gamma^{\alpha-2} \{A>\gamma B\} \right] \, \d \gamma\\
			&=\frac{\alpha-1}{\alpha}\int_0^\infty \Tr\left[ \left(A\frac{1}{B+t\I}\right)^\alpha \right] \, \d t,
		\end{align}
		concluding the proof.
	\end{proof}



	\subsection{General \(f\)-divergences}
	The results in the previous section raise the question whether the same holds true for more general functions $f$. In that direction, we state the following observation. 
	\begin{prop} \label{prop:genearl_f}
		For any quantum states $\rho$, $\sigma$ and any convex $f$ such that $f'(\gamma)$ is Lebesgue-integrable on $[0,\e^{D_{\max}(\rho\Vert\sigma)}]$, 
		\begin{align}
			D_f(\rho\Vert\sigma) &=
			f(0) + \int_0^\infty \Tr\left[ \sigma \frac{1}{\sigma+t\I} \rho \frac{1}{\sigma+t\I} f'\left( \rho \frac{1}{\sigma+t\I} \right) \right] \, \d t .
		\end{align}
	\end{prop}
	\begin{proof}
		Again, we start from Equation~\eqref{Eq:Def-1-dif}
		\begin{align}
			D_f(\rho\Vert\sigma) =
			f(0) + \int_0^\infty f'(\gamma) \Tr\left[ \sigma \proj{ \rho > \gamma \sigma}\right] \, \d \gamma.
		\end{align}
		Using  Theorem~\ref{theo:change-of-variable} the claim follows directly. 
	\end{proof}
	Note that in the commuting setting, it can easily be checked that this corresponds to the usual definition of the classical $f$-divergence. 

