	\section{Application to error exponents} \label{sec:exponents}

	We are interested in two quantities, the \textbf{error exponent},
	\begin{align}
		B_e(r) = \sup\{ -\limsup_{n\rightarrow\infty} \frac1n \log\alpha_n(T_n) \mid \limsup_{n\rightarrow\infty} \frac1n \log\beta_n(T_n) \leq -r \}, 
	\end{align}
	and the \textbf{strong converse exponent},
	\begin{align}
		B^*_e(r) = \sup\{ -\liminf_{n\rightarrow\infty} \frac1n \log(1-\alpha_n(T_n)) \mid \limsup_{n\rightarrow\infty} \frac1n \log\beta_n(T_n) \leq -r \}.
	\end{align}
	We denote by $S_n(a):=\{\rho^{\otimes n}-\e^{na}\sigma^{\otimes n} > 0\}$ the quantum Neyman--Pearson tests. 
	\begin{prop}[Error probabilities via quantum Neyman--Pearson tests] \label{prop:threshold_test}
		Let $n\in\mathds{N}$ to be an arbitrary integer.
		For all $\alpha\in(0,1)\cup(1,\infty)$, 
		\begin{align} \label{eq:type-II_error_upper_bound}
			\log\Tr\left[ \sigma^{\otimes n}  S_n(a) \right] 
			&\leq -n a - n(\alpha-1)\left( a - \frac1n D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})\right).
		\end{align}
		For all $\alpha>1$, 
		\begin{align} \label{eq:type-I_success_upper_bound}
			\log\tr[\rho^{\otimes n}S_n(a)] 
			&\leq  -n(\alpha-1)\left(a-\frac1n D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})\right).
		\end{align}
		For all $0<\alpha<1$,
		\begin{align} \label{eq:type-I_error_upper_bound}
			\log\left[1-\tr[\rho^{\otimes n}S_n(a)] \right]
			\leq -n(\alpha-1)\left(a - \frac1n D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})\right).
		\end{align}
	\end{prop}


	\begin{proof}
		Starting from Equation~\eqref{Eq:Q-layerCake}, we have for the \Renyi divergence,
		\begin{align}
			D_\alpha(\rho\|\sigma) = \frac{1}{\alpha-1}\log\left( \alpha \int_{0}^{\infty} \gamma^{\alpha-1}  \Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right] \d\gamma\right). 
		\end{align}
		Observe the following for $0<c<e^{D_{\max}(\rho\|\sigma)}$, 
		\begin{DispWithArrows}[displaystyle]
			e^{(\alpha-1)D_\alpha(\rho\|\sigma)} 
			&=  \alpha \int_{0}^{\infty} \gamma^{\alpha-1}  \Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right] \d\gamma \\
			&\geq \alpha \int_{0}^{c} \gamma^{\alpha-1}  \Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right] \d\gamma 
			\Arrow{\textnormal{by Lemma~\ref{lemm:monotone_in_gamma}}}   
			\\
			&\geq \alpha \int_{0}^{c} \gamma^{\alpha-1}  \Tr\left[ \sigma  \left\{  \rho > c \sigma \right\} \right] \d\gamma \\
			&= c^\alpha \Tr\left[ \sigma  \left\{  \rho > c \sigma \right\} \right].
		\end{DispWithArrows}
		Now, substitute $\rho\rightarrow\rho^{\otimes n}$, $\sigma\rightarrow\sigma^{\otimes n}$, $c=e^{n a}$, 
		\begin{align}
			\Tr\left[ \sigma^{\otimes n}  \left\{  \rho^{\otimes n} > e^{n a} \sigma^{\otimes n} \right\} \right] 
			&\leq e^{-\alpha n a} e^{(\alpha-1)D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})} \\
			&= e^{-n a -\frac{(\alpha-1)}{\alpha}\left(\alpha n a - \alpha D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})\right)}.
		\end{align}
		Similarly, for $\alpha>1$, from Equation~\eqref{eq:layer-cake_alpha>1-0}, 
		\begin{DispWithArrows}[displaystyle]
			e^{(\alpha-1)D_\alpha(\rho\|\sigma)} 
			&= (\alpha-1) \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho>\gamma\sigma\}] \d\gamma 
			\Arrow{\textnormal{by Lemma~\ref{lemm:monotone_in_gamma}}}   
			\\
			&\geq (\alpha-1) \int_0^c \gamma^{\alpha-2} \tr[\rho\{\rho>c\sigma\}] \d\gamma \\
			&= c^{\alpha-1} \tr[\rho\{\rho>c\sigma\}], 
		\end{DispWithArrows}
		implying
		\begin{align}
			\tr[\rho^{\otimes n}\{\rho^{\otimes n}>e^{na}\sigma^{\otimes n}\}] 
			&\leq e^{(1-\alpha)na}e^{(\alpha-1)D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})} \\
			&= e^{-(\alpha-1)(na-D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})}.
		\end{align}
		Finally, for $0\leq\alpha\leq1$, from Equation~\eqref{eq:layer-cake_alpha<1-0},  
		\begin{DispWithArrows}[displaystyle]
			e^{(\alpha-1)D_\alpha(\rho\|\sigma)} 
			&= (1-\alpha) \int_0^\infty \gamma^{\alpha-2} \tr[\rho\{\rho\leq\gamma\sigma\}] \d\gamma 
			\Arrow{\textnormal{by Lemma~\ref{lemm:monotone_in_gamma}}}   
			\\
			&\geq (1-\alpha) \int_c^\infty \gamma^{\alpha-2} \tr[\rho\{\rho\leq c\sigma\}] \d\gamma \\
			&= c^{\alpha-1} \tr[\rho\{\rho\leq c\sigma\}], 
		\end{DispWithArrows}
		which implies, 
		\begin{align}
			1-\tr[\rho^{\otimes n}\{\rho^{\otimes n} > e^{na}\sigma^{\otimes n}\}] = \tr[\rho^{\otimes n}\{\rho^{\otimes n}\leq e^{na}\sigma^{\otimes n}\}] &\leq e^{(1-\alpha)na + (\alpha-1)D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})} \\
			&= e^{-n(\alpha-1)\left(a - \frac1n D_\alpha(\rho^{\otimes n}\|\sigma^{\otimes n})\right)}
		\end{align}
	\end{proof}




	Now, set $\alpha=s+1$ for some $s>0$, then
	\begin{align}
		\Tr\left[ \sigma^{\otimes n}  \left\{  \rho^{\otimes n} > e^{n a} \sigma^{\otimes n} \right\} \right] \leq e^{- n a - \left(n s a - s D_{s+1}(\rho^{\otimes n}\|\sigma^{\otimes n})\right)}, 
	\end{align}
	which implies, because it holds for all $s>0$,
	\begin{align}
		\Tr\left[ \sigma^{\otimes n}  \left\{  \rho^{\otimes n} > e^{n a} \sigma^{\otimes n} \right\} \right] \leq e^{- n a - \sup_{s>0}\left(n s a - s D_{s+1}(\rho^{\otimes n}\|\sigma^{\otimes n})\right)}, 
	\end{align}
	Note that this is tighter that the inequality used in~\cite{mosonyi2015quantum}. To see that, observe, 
	\begin{align}
		\Tr\left[ \sigma^{\otimes n}  \left\{  \rho^{\otimes n} > e^{n a} \sigma^{\otimes n} \right\} \right] 
		&\leq e^{- n a - \sup_{s>0}\left(n s a - s D_{s+1}(\rho^{\otimes n}\|\sigma^{\otimes n})\right)} \\
		&\leq e^{- n a - \sup_{s>0}\left(n s a - s \widetilde D_{s+1}(\rho^{\otimes n}\|\sigma^{\otimes n})\right)}\\
		&= e^{- n a - n\sup_{s>0}\left( s a - s \widetilde D_{s+1}(\rho\|\sigma)\right)}\\
		&= e^{- n (a+\phi(a))}, 
	\end{align}
	which is~\cite[Eq.~(55)]{mosonyi2015quantum}. 



	\begin{prop}[Quantum Markov inequality]
		For some nondecreasing function $f\in \mathcal{F}$ satisfying $f(0)\geq 0$ and for all $0<c<\e^{D_{\max}(\rho \Vert \sigma)}$,
		\begin{align}
			\Tr\left[ \sigma \left\{ \rho > c \sigma \right\} \right] \leq \frac{ D_{f}(\rho \Vert \sigma )}{f(c)}.
		\end{align}
	\end{prop}
	\begin{proof}
		We start from Equation~\eqref{Eq:Def-1-dif}, 
		\begin{align}
			D_f(\rho\Vert\sigma) &=
			f(0) + \int_0^\infty f'(\gamma) \Tr\left[ \sigma \proj{ \rho > \gamma \sigma}\right] \, \d \gamma \\
			&\geq
			f(0) + \int_0^c f'(\gamma) \Tr\left[ \sigma \proj{ \rho > \gamma \sigma}\right] \, \d \gamma \\
			&\geq
			f(0) + \int_0^c f'(\gamma) \Tr\left[ \sigma \proj{ \rho > c \sigma}\right] \, \d \gamma \\
			&=
			f(0) + f(c) \Tr\left[ \sigma \proj{ \rho > c \sigma}\right] - f(0) \Tr\left[ \sigma \proj{ \rho > c \sigma}\right] \\
			&\geq f(c) \Tr\left[ \sigma \proj{ \rho > c \sigma}\right] 
		\end{align}
		where the first inequality follows because the integrand is always positive, the second because the trace function $\Tr\left[ \sigma \proj{ \rho > \gamma \sigma}\right]$ is non-increasing and the final one because its upper bounded by $1$. The claim then follows by rearranging. 
	\end{proof}

	\begin{theo}[Error exponent for asymmetric setting] \label{theorem:Hoeffding}
		Let $n\in\mathds{N}$ to be an arbitrary integer.
		For all $r>0$ and all $0<\alpha<1$,
		\begin{align} \label{eq:Hoeffding}
			\begin{dcases}
				\log \Tr\left[ 1 - \rho^{\otimes n} S_n(a) \right] \leq - n \frac{\alpha-1}{\alpha} \left( \frac{1}{n} D_{\alpha}\left(\rho^{\otimes n}\Vert \sigma^{\otimes n} \right) - r \right)
				% \leq  n \frac{\alpha-1}{\alpha} \left( \frac{1}{n} \bar{D}_{\alpha}\left(\rho^{\otimes n}\Vert \sigma^{\otimes n} \right) - r \right)
				\\
				\log \Tr\left[ \sigma^{\otimes n} S_n(a) \right] \leq - n r
			\end{dcases},
		\end{align}
		where the threshold in the quantum Neyman--Pearson test is chosen to be
		\begin{align} \label{eq:threshould_Hoeffding}
			a = \frac{r+(\alpha-1) \frac{1}{n}D_{\alpha} \left(\rho^{\otimes n}\Vert \sigma^{\otimes n}\right)}{\alpha}.
		\end{align}
	\end{theo}
	\begin{proof}
		Our claim follows by applying \eqref{eq:type-II_error_upper_bound} and \eqref{eq:type-I_error_upper_bound} in Proposition~\ref{prop:threshold_test} with \eqref{eq:threshould_Hoeffding}.
	\end{proof}

	\begin{theo}[Error exponent for symmetric setting] \label{theorem:Chernoff}
		For all $0<p<1$ and all $0<\alpha<1$,
		\begin{align}
			\begin{split} \label{eq:Chernoff}
				p \Tr\left[ \rho^{\otimes n} \left( \I - S_n(a) \right) \right]
				+ (1-p) \Tr\left[ \sigma^{\otimes n} S_n(a) \right]
				&\leq 2 p^{\alpha}(1-p)^{1-\alpha}\cdot \e^{- (1-\alpha) D_{\alpha}\left( \rho^{\otimes n} \Vert \sigma^{\otimes n} \right) },
				% \\
				% &\leq 2 p^{\alpha}(1-p)^{1-\alpha}\cdot \e^{- (1-\alpha) \bar{D}_{\alpha}\left( \rho^{\otimes n} \Vert \sigma^{\otimes n} \right) },
			\end{split}
		\end{align}
		where the threshold in the quantum Neyman--Pearson test is chosen to be
		\begin{align} \label{eq:threshould_Chernoff}
			a = \log \frac{1-p}{p}.
		\end{align}
	\end{theo}
	\begin{proof}
		The exponential term $\e^{- (1-\alpha) {D}_{\alpha}\left( \rho^{\otimes n} \Vert \sigma^{\otimes n} \right) }$ follows by applying \eqref{eq:type-II_error_upper_bound} and \eqref{eq:type-I_error_upper_bound} in Proposition~\ref{prop:threshold_test} with \eqref{eq:threshould_Chernoff}.
		We only need to calculate the prefactor as follows:
		\begin{align}
			p \e^{-(\alpha-1) a} + (1-p) \e^{-\alpha a}
			= p\left( \frac{p}{1-p} \right)^{\alpha-1}
			+ (1-p) \left( \frac{p}{1-p} \right)^{\alpha}
			= p^{\alpha} (1-p)^{1-\alpha} + p^{\alpha} (1-p)^{1-\alpha}.
		\end{align}
	\end{proof}

	\begin{remark}
		Note that both Theorems~\ref{theorem:Hoeffding} and \ref{theorem:Chernoff} hold for all $0<\alpha<1$.
		One can maximize over $0<\alpha<1$ to achieve the largest error exponents, respectively.
		Moreover, we can relax the established error exponents to the ones induced by the Petz--\Renyi divergence by the relation shown in Ref.~\cite{beigi2025some}:
		\begin{align}
			D_{\alpha} \left( \rho^{\otimes n} \Vert \sigma^{\otimes n} \right)
			\geq \bar{D}_{\alpha} \left( \rho^{\otimes n} \Vert \sigma^{\otimes n} \right)
			= n \bar{D}_{\alpha} \left( \rho \Vert \sigma \right).
		\end{align}
	\end{remark}


