	\section{Riemann–Stieltjes Integral Representations} \label{sec:RS-integral}

	In this section, we show that the quantum divergences introduced in Section~\ref{sec:relation} admit more intuitive Riemann--Stieltjes integral representations.
	As will be shown shortly in Proposition~\ref{prop:f-divergence_RS}, the conditions for the Riemann--Stieltjes integral representation of the quantum $f$-divergence only need to satisfy:
	(i) $D_{\max}(\rho\Vert\sigma) < \infty$,
	(ii) $f$ defined on $[0,\infty)$ is convex with $f(1) = 0$, and
	(iii) $f(x) < \infty$ for all $x>0$.
	Here, $f(0):= \lim_{x\searrow 0} f(x)$ could even be infinite.
	Later in Section~\ref{sec:relative_entropy_RS}, we show that the established Riemann–Stieltjes integral representations can be expressed in terms of some induced \emph{Riemann–Stieltjes distributions}.



	\begin{prop} \label{prop:f-divergence_RS}
		For quantum states $\rho$ and $\sigma$ satisfying $D_{\max}(\rho\Vert\sigma) < \infty$ and any convex function $f$ on $[0,\infty)$ such that $f(x)<\infty$ for all $x \geq 0$ and $f(1) = 0$,
		\begin{align}
			D_f(\rho\|\sigma) 
			&= -\int_{0}^{\infty} f(\gamma) \, \d\Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right]  \label{eq:f-divergence_RS_1}
			\\
			&= \int_{0}^{\infty} f(\gamma) \, \d\Tr\left[ \sigma  \left\{  \rho \leq \gamma \sigma \right\} \right]. \label{eq:f-divergence_RS_2}
		\end{align}
	\end{prop}
	\begin{proof}
		Using integration by parts,
		% \begin{DispWithArrows}[displaystyle]
			\begin{align}
				D_f(\rho\|\sigma) 
				&=   f(0) +   \int_{0}^{\infty}  \Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right] \d f(\gamma)
				\\
				&=  f(0) +  \left. f(\gamma) \Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right]
				\right|_0^\infty -\int_{0}^{\infty} f(\gamma)  \d\Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right] \d\gamma
				% \Arrow{$\left\{  \rho > \gamma \sigma \right\} = 0$ for all $\gamma > \e^{D_{\max}(\rho\Vert\sigma)}$}
				\\
				&\overset{\textnormal{(a)}}{=} f(0) - f(0) -\int_{0}^{\infty} f(\gamma)  \d\Tr\left[ \sigma  \left\{  \rho > \gamma \sigma \right\} \right] \d\gamma
				\\
				&= -\int_{0}^{\infty} f(\gamma)  \d\Tr\left[ \sigma  \left( \I - \left\{  \rho \leq \gamma \sigma \right\} \right) \right] \d\gamma
				\\
				&= \int_{0}^{\infty} f(\gamma)  \d\Tr\left[ \sigma \left\{  \rho \leq \gamma \sigma \right\} \right] \d\gamma,
			\end{align}
			% \end{DispWithArrows}
		where (a) is because $\left\{  \rho > \gamma \sigma \right\} = 0$ for all $\gamma > \e^{D_{\max}(\rho\Vert\sigma)}$ and $f(\gamma) < \infty$ for all finite $\gamma$.
	\end{proof}

	To see why the Riemann--Stieltjes integral representation given in Proposition~\ref{prop:f-divergence_RS} is a more intuitive expression even in the classical case (for a discrete probablity space), let us elaborate on \eqref{eq:f-divergence_RS_2} in the commuting case.

	Denote the spectral decompositions for the commuting states $\rho$ and $\sigma$, $\rho\ll\sigma$, as
	\begin{align*}
		\rho = \sum\nolimits_i \lambda_i \Pi_i,
		\quad
		\sigma = \sum\nolimits_i \mu_i \Pi_i,
	\end{align*}
	where $(\lambda_i)_i$ and $(\mu_i)_i$ are eigenvalues, and $(\Pi_i)_i$ are eigen-projections.
	We write the projection as
	\begin{align*}
		\proj{ \rho \leq \gamma \sigma}
		= \sum\nolimits_i \proj{ \nicefrac{\lambda_i}{\mu_i} \leq \gamma } \Pi_i.
	\end{align*}
	Note that for each $i$, the indicator function $\proj{ \nicefrac{\lambda_i}{\mu_i} \leq \gamma }$ is a
	right-continuous monotone increasing cumulative distribution function in $\gamma \geq 0$.
	Then,
	\begin{align*}
		\int_0^\infty f(\gamma) \, \d \proj{ \rho \leq \gamma \sigma}
		&= \sum\nolimits_i \int_0^\infty f(\gamma) \, \d \proj{ \nicefrac{\lambda_i}{\mu_i} \leq \gamma } \Pi_i
		\\
		&= \sum\nolimits_i \int_0^\infty f(\gamma) \delta\left( \nicefrac{\lambda_i}{\mu_i} - \gamma \right) \Pi_i \, \d \gamma
		\\
		&= \sum\nolimits_i f\left( \nicefrac{\lambda_i}{\mu_i} \right) \Pi_i,
	\end{align*}
	where we have used the Dirac delta function $\delta$ for simplicity.
	Taking $\Tr\left[ \sigma (\,\cdot\,)\right]$ on both sides (i.e., taking the expectation under the state $\sigma$), we recover the classical $f$-divergence between the eigenvalues $(\lambda_i)_i$ and $(\sigma_i)_i$:
	\begin{align}
		\int_0^\infty f(\gamma) \, \d \Tr[\sigma \proj{ \rho \leq \gamma \sigma}]
		=  
		\sum\nolimits_i \mu_i f\left( \nicefrac{\lambda_i}{\mu_i} \right)
		= D_f\left( (\lambda_i)_i \Vert (\mu_i)_i \right).
	\end{align}

	\medskip
	Returning to the general setting, Proposition~\ref{prop:f-divergence_RS} then also provides the Riemann--Stieltjes integral representations for the quasi \Renyi divergence as well, i.e.,
	\begin{tcolorbox}[size = small, colback=orange!1.5!white, colframe=orange,  boxrule=0.5pt, width = \linewidth]
		\begin{align}
			Q_{\alpha} (\rho\Vert\sigma)
			= - \int_{0}^\infty \gamma^{\alpha} \, \d \Tr\left[ \sigma \proj{ \rho > \gamma \sigma} \right]
			= \int_{0}^\infty \gamma^{\alpha} \, \d \Tr\left[ \sigma \proj{ \rho \leq \gamma \sigma} \right], \quad \alpha > 0
		\end{align}
	\end{tcolorbox}
	\noindent which we consider one of the most intuitive expressions for the quasi \Renyi divergence with $\rho\ll\sigma$.
