	\subsection{The relative entropy} \label{sec:relative_entropy_RS}

	Recall that for probability distributions $P$ and $Q$ with $P\ll Q$, there are two ways of expressing the Kullback--Leibler divergence:
	\begin{align}
		D(P\Vert Q)
		= \mathds{E}_{Q} \left[ \frac{\d P}{\d Q} \log \frac{\d P}{\d Q} \right]
		= \mathds{E}_{P} \left[ \log \frac{\d P}{\d Q} \right],
	\end{align}
	which can be considered as a change-of-measure argument (so as for the \Renyi divergence $D_{\alpha}(P\Vert Q)$, $\alpha > 1$).

	Using the Riemann--Stieltjes integral representation in Proposition~\ref{prop:f-divergence_RS}, we will show that the quantum relative entropy also inherits a similar flavor.
	For quantum states $\rho$ and $\sigma $ satisfying $\rho\ll\sigma$, we define the following induced functions:
	\begin{tcolorbox}[size = small, colback=orange!1.5!white, colframe=orange,  boxrule=0.5pt, width = \linewidth]
		\begin{align} \label{eq:RS-distribution}
			P_{\rho,\sigma}^{\texttt{RS}}(\gamma) := \Tr[\rho\{\rho\leq\gamma\sigma\}],
			\quad
			Q_{\rho,\sigma}^{\texttt{RS}}(\gamma) := \Tr[\sigma\{\rho\leq\gamma\sigma\}], \quad \gamma \geq 0.
		\end{align}
	\end{tcolorbox}
	\noindent 
	Note that by Lemma~\ref{lemm:differentiability_projection}, $P_{\rho,\sigma}^{\texttt{RS}}(\gamma)$
	and 
	$Q_{\rho,\sigma}^{\texttt{RS}}(\gamma)$
	are right-continuous, monotone increasing functions from $0$ to $1$ (see e.g., Figures~\ref{figure:RS-integral_quantum} and \ref{figure:RS-integral_quantum_increasing}).
	Hence, we call them \emph{Riemann--Stieltjes distributions} (as opposed to the Nussbaum--Szko{\l}a distributions \cite{NS09}) for states $(\rho,\sigma)$.
	We may use them to express the quantum relative entropy as follows (so as for the quantum $f$-divergence in Proposition~\ref{prop:f-divergence_RS}).
	We refer the readers to Figures~\ref{figure:decreasing} and \ref{figure:increasing} for illustrations of the commuting case.


	\begin{prop}[Riemann--Stieltjes integral representations for Umegaki's relative entropy] \label{prop:relative_entropy_formula2}
		For quantum states $\rho$ and $\sigma$ satisfying $D_{\max}(\rho \Vert \sigma) < \infty $, 
		\begin{align}
			\log A - \log B
			&= - \int_{0}^{\infty} \log \gamma \, \d \proj{A> \gamma B}, \quad A,B>0,
			\\
			D(\rho\Vert\sigma) 
			&= 
			- \int_0^\infty  \log \gamma \, \d \tr\left[\rho\{\rho>\gamma\sigma\}\right]
			= \int_0^\infty  \log \gamma \, \d P_{\rho,\sigma}^{\textnormal{\texttt{RS}}}(\gamma)
			\label{eq:first-row}
			\\
			&= 
			- \int_0^\infty  \gamma \log \gamma \, \d \tr\left[\sigma\{\rho>\gamma\sigma\}\right]
			= \int_0^\infty  \gamma \log \gamma \, \d Q_{\rho,\sigma}^{\textnormal{\texttt{RS}}}(\gamma).
			\label{eq:second-row}
		\end{align}
	\end{prop}
	\begin{proof}
		The equalities in the second row \eqref{eq:second-row} directly follow from Proposition~\ref{prop:f-divergence_RS} with $f(x) = x \log x$, and then the first row \eqref{eq:first-row} follows from a change-of-measure argument in Lemma~\ref{lemm:change-of-measure} below.
		In the following, we provide an alternative proof to show the first row \eqref{eq:first-row} directly, and then recover the second row \eqref{eq:second-row}.

		We first recall \eqref{eq:log-difference1} to obtain
		% \begin{DispWithArrows}[displaystyle]
			\begin{align*}
				\log A - \log B
				&= \int_1^\infty \frac{1}{\gamma} \proj{A>\gamma B} \d \alpha
				- \int_1^\infty \frac{1}{\alpha} \proj{B > \alpha A} \d \alpha
				% \Arrow{$\alpha \colon$ $\{\alpha A = B\}$ \\ \textnormal{is measure} $0$}
				\notag
				\\
				&\overset{\textnormal{(a)}}{=} \int_1^\infty \frac{1}{\gamma} \proj{A>\gamma B} \d \gamma
				- \int_1^\infty \frac{1}{\alpha} \proj{B \geq \alpha A} \d \alpha
				\\
				&\overset{\textnormal{(b)}}{=} 
				\int_1^\infty \frac{1}{\gamma} \proj{A>\gamma B} \d \gamma
				- \int_0^1 \frac{1}{\gamma} \proj{A \leq \gamma B} \d \gamma
				\\
				&= \int_1^\infty \frac{1}{\gamma} \proj{A>\gamma B} \d \gamma
				- \lim_{\epsilon \searrow 0} \left\{
				\int_{\epsilon}^1 \frac{1}{\gamma } \I \, \d \gamma - \int_{\epsilon}^1 \frac{1}{\gamma} \proj{A>\gamma B} \, \d \gamma 
				\right\}
				\\
				&= \lim_{\epsilon \searrow 0} \left\{
				\int_{\epsilon}^\infty \frac{1}{\gamma} \proj{A>\gamma B} \, \d \gamma + \log \epsilon \cdot \I 
				\right\}
				\\
				&\overset{\textnormal{(c)}}{=}
				\lim_{\epsilon\searrow 0} \left\{
				\log \gamma \proj{A>\gamma B} \big\vert_{\epsilon}^\infty - \int_{\epsilon}^\infty \log \gamma \, \d\proj{A>\gamma B}
				+ \log \epsilon \cdot \I
				\right\}
				\\
				&\overset{\textnormal{(d)}}{=}
				\lim_{\epsilon\searrow 0} \left\{
				0 - \log \epsilon \cdot \proj{A>\epsilon B} + \log \epsilon \cdot \I - \int_{\epsilon}^{\infty} \log \gamma \, \d \proj{A> \gamma B}
				\right\}
				\\
				&= \lim_{\epsilon\searrow 0} \left\{
				\log \epsilon \cdot \proj{A\leq \epsilon B} - \int_{\epsilon}^{\infty} \log \gamma \, \d \proj{A> \gamma B}
				\right\}
				\\
				&\overset{\textnormal{(e)}}{=}
				\lim_{\epsilon\searrow 0} \left\{
				- \int_{\epsilon}^{\infty} \log \gamma \, \d \proj{A> \gamma B}
				\right\}
				\\
				&=
				- \int_{0}^{\infty} \log \gamma \, \d \proj{A> \gamma B}.
			\end{align*}
			% \end{DispWithArrows}
		In (a), the set $\{ \alpha : \proj{B=\alpha A} \neq 0\}$ is measure zero.
		In (b), we change variable $\gamma \leftarrow \nicefrac{1}{\alpha}$ in the second term.
		In (c), we use integration by parts.
		In (d), we have $\proj{A>\gamma B} = 0$ for all $\gamma > \left\| B^{-\nicefrac{1}{2}} A B^{-\nicefrac{1}{2}} \right\|_{\infty}$.
		In (e), we have $\proj{A\leq \epsilon B} = 0$ for all $\epsilon$ strictly less than the smallest eigenvalue of $B^{-\nicefrac{1}{2}} A B^{-\nicefrac{1}{2}}$.

		Finally, take $\Tr[A(\cdot)]$ on both sides,
		substitute $B \leftarrow \sigma $ and $A \leftarrow \rho + \epsilon \I$. 
		By the continuity of the quantum relative entropy in its first argument and and letting $\epsilon \to 0$, we conclude the proof.
	\end{proof}




	\begin{lemm}[Change of measure] \label{lemm:change-of-measure}
		For all $A\geq 0$, $B>0$, and measurable functions $g$,
		\begin{align}
			\int_0^\infty g(\gamma) \, \d \Tr\left[ A \proj{ A > \gamma B } \right]
			&= \int_0^\infty \gamma g(\gamma) \, \d \Tr\left[ B \proj{ A > \gamma B } \right],
			\label{eq:change-of-measure1}
			\\
			\int_0^\infty g(\gamma) \, \d \Tr\left[ A \proj{ A \leq \gamma B  } \right]
			&= \int_0^\infty \gamma g(\gamma) \, \d \Tr\left[ B \proj{A \leq \gamma B } \right].
		\end{align}

		Moreover, for differentiable function $g$, such that $g(0)=0$, we have
		\begin{align} \label{eq:change-of-measure_combined}
			\int_0^\infty g'(\gamma) \Tr[A\{A>\gamma B\}] \, \d \gamma=\int_0^\infty \left(g(\gamma)+\gamma g'(\gamma)\right) \Tr[A\{A>\gamma B\}] \, \d \gamma.
		\end{align}
	\end{lemm}

	\begin{proof}
		We denote the spectrum $\spec\left\{B^{-1/2} A B^{-1/2} \right\}$ by $\mathcal{S}$.
		Recall that the map $\gamma \mapsto \proj{A > \gamma B}$ is piecewise analytical except on $\mathcal{S}$ (Lemma~\ref{lemm:differentiability_projection}).
		For $\gamma \not\in \mathcal{S}$, we calculate 
		% \begin{align}
			%     \frac{\d}{\d \gamma} \proj{A - \gamma B}
			%     &= \frac{\d}{\d \gamma} \left( \proj{A - \gamma B} \proj{A - \gamma B} \right)
			%     \\
			%     &= \frac{\d}{\d \gamma} \left( \proj{A - \gamma B}  \right) \proj{A - \gamma B} + \proj{A - \gamma B} \frac{\d}{\d \gamma} \left( \proj{A - \gamma B} \right).
			% \end{align}
		\begin{align}
			\frac{\d}{\d \gamma} \Tr\left[ \left( A - \gamma B \right)_+ \right] 
			&= \Tr\left[ \frac{\d}{\d \gamma} (A - \gamma B ) \cdot \{ A > \gamma B \} \right] + \Tr\left[ (A - \gamma B) \frac{\d}{\d \gamma } \{ A > \gamma B \}  \right]
			\\
			&= -\Tr\left[ B \{ A > \gamma B \} \right] + \Tr\left[ (A - \gamma B) \frac{\d}{\d \gamma } \{ A > \gamma B \}  \right].
		\end{align}
		On the other hand, Lemma~\ref{lemm:HP14} shows that
		\begin{align}
			\frac{\d}{\d \gamma} \Tr\left[ (A - \gamma B)_+ \right]
			= - \Tr[B \{ A > \gamma B \} ].
		\end{align}
		This gives
		\begin{align}
			\Tr\left[ (A - \gamma B ) \frac{\d}{\d \gamma} \{A > \gamma B \} \right] = 0,
		\end{align}
		or equivalently,
		\begin{align}
			\frac{\d}{\d \gamma} \Tr\left[ A \{ A > \gamma B\} \right]
			&= \gamma \frac{\d}{\d \gamma} \Tr\left[ B \{ A > \gamma B \right].
		\end{align}
		Then,
		\begin{align}
			\int_{\gamma \not\in \mathcal{S}} g(\gamma) \, \d \Tr\left[ A \{ A > \gamma B \} \right]
			&= \int_{\gamma \not\in \mathcal{S}} g(\gamma) \frac{\d}{\d \gamma} \Tr\left[ A \{ A > \gamma B \} \right]  \d \gamma
			\\
			&= \int_{\gamma \not\in \mathcal{S}} \gamma g(\gamma) \frac{\d}{\d \gamma} \Tr\left[ B \{ A > \gamma B \} \right]  \d \gamma
			\\
			&= \int_{\gamma \not\in \mathcal{S}} \gamma g(\gamma) \, \d \Tr\left[ B \{ A > \gamma B \}\right] \label{eq:change-of-measure1}
		\end{align}
		by noting that both the maps $\gamma \mapsto \Tr\left[ A \{ A > \gamma B \}\right]$ and $\gamma \mapsto \Tr\left[ B \{ A > \gamma B \} \right]$ are absolutely continuous on $[0,\infty)\backslash \mathcal{S}$ as they are differentiable with uniformly bounded right derivatives on $[0,\infty)\backslash \mathcal{S}$.

		Next, we move on to the case of $\gamma \in \mathcal{S}$.
		For a map $\gamma \mapsto h(\gamma)$, we denote the jump at $\gamma$ by
		\begin{align}
			\delta(h(\gamma))
			:= h(\gamma^+) - h(\gamma^-).
		\end{align}
		for notational simplicity.
		We claim that
		\begin{align}
			\Tr\left[ (A - \gamma B) \cdot \delta\left( \Tr[A\{A>\gamma B\}] \right) \right],
		\end{align}
		which is equivalent to
		\begin{align} \label{eq:change-of-measure-jump}
			\Tr\left[ A \cdot \delta\left( \Tr[A\{A>\gamma B\}] \right) \right]
			= \gamma \Tr\left[ B \cdot \delta\left( \Tr[A\{A>\gamma B\}] \right) \right].
		\end{align}
		Indeed,
		\begin{DispWithArrows}[displaystyle]
			\delta\left( \Tr[A\{A>\gamma B\}] \right)
			&= \Tr\left[ A \left( \{A>\gamma^+ B \} - \{A > \gamma^- B \} \right) \right]
			\Arrow{\textnormal{by Lemma~\ref{lemm:differentiability_projection}}}
			\\
			&= \Tr\left[ A \left( \{A>\gamma B \} - \{A \geq \gamma B \} \right) \right]
			\\
			&= -\Tr\left[ A \{A - \gamma B = 0\} \right]
			\\ 
			&= -\gamma \Tr\left[ B \{A - \gamma B = 0\} \right]
			\\
			&= \gamma \left( \Tr\left[ B \left( \{A>\gamma B \} - \{A \geq \gamma B \} \right) \right] \right)
			\Arrow{\textnormal{by Lemma~\ref{lemm:differentiability_projection}}}
			\\
			&= \gamma \left( \Tr\left[ B \left( \{A>\gamma^+ B \} - \{A \geq \gamma^- B \} \right) \right] \right)
			\\
			&= \gamma \cdot \delta \left( \Tr[B\{A>\gamma B\}] \right),
		\end{DispWithArrows}
		which proves \eqref{eq:change-of-measure-jump}.

		To show the claim of the lemma, we let
		\begin{align}
			h_1(\gamma) &:= \Tr\left[ A \{A>\gamma B \} \right],
			\\
			h_2(\gamma) &:= \Tr\left[ B \{A>\gamma B \} \right],
		\end{align}
		and let $\bar{h}_1(\gamma)$ be a simple function (i.e., a linear combination of linear functions) such that $h_1 - \bar{h}_1$ is continuous.
		In other words,
		\begin{align} \label{eq:change_jump}
			\delta(h_1(\gamma) ) = \delta (\bar{h}_1(\gamma)), \quad \forall \gamma \in \mathcal{S}.
		\end{align}
		We define $\bar{h}_2$ similarly.
		Finally, we have
		\begin{DispWithArrows}[displaystyle]
			\int_0^\infty g(\gamma) \, \d h_1(\gamma) 
			&= \int_0^\infty g(\gamma) \, \d \bar{h}_1(\gamma)  + \int_0^\infty g(\gamma) \, \d \left( h_1(\gamma) - \bar{h}_1(\gamma)\right)
			\notag
			\\
			&= \sum_{\gamma \in \mathcal{S}} g(\gamma) \delta(\bar{h}_1(\gamma)) + \int_0^\infty g(\gamma) \frac{\d \left( h_1(\gamma) - \bar{h}_1(\gamma)\right) }{\d \gamma} \, \d \gamma
			\Arrow{\textnormal{by} \eqref{eq:change_jump}}
			\notag
			\\
			&= \sum_{\gamma \in \mathcal{S}} g(\gamma) \delta({h}_1(\gamma)) + \int_{0}^\infty g(\gamma) \frac{\d \left( h_1(\gamma) - \bar{h}_1(\gamma)\right) }{\d \gamma} \, \d \gamma
			\Arrow{\textnormal{by ignoring} $\gamma \in \mathcal{S}$}
			\notag
			\\
			&= \sum_{\gamma \in \mathcal{S}} g(\gamma) \delta({h}_1(\gamma)) + \int_{\gamma \not\in \mathcal{S}} g(\gamma) \frac{\d h_1(\gamma)  }{\d \gamma} \, \d \gamma
			\Arrow{\textnormal{by} \eqref{eq:change-of-measure1}}
			\notag
			\\
			&= \sum_{\gamma \in \mathcal{S}} g(\gamma) \delta({h}_1(\gamma)) + \int_{\gamma \not\in \mathcal{S}} \gamma g(\gamma) \frac{\d h_2(\gamma)  }{\d \gamma} \, \d \gamma
			\Arrow{\textnormal{by ignoring} $\gamma \in \mathcal{S}$}
			\notag
			\\
			&= \sum_{\gamma \in \mathcal{S}} g(\gamma) \delta({h}_1(\gamma)) + \int_{0}^\infty \gamma g(\gamma) \frac{\d \left( h_2(\gamma) - \bar{h}_2(\gamma) \right) }{\d \gamma} \, \d \gamma
			\Arrow{\textnormal{by} \eqref{eq:change-of-measure-jump}}
			\notag
			\\
			&= \sum_{\gamma \in \mathcal{S}} \gamma g(\gamma) \delta({h}_2(\gamma)) + \int_{0}^\infty \gamma g(\gamma) \frac{\d \left( h_2(\gamma) - \bar{h}_2(\gamma) \right)  }{\d \gamma} \, \d \gamma
			\notag
			\\
			&= \int_0^\infty \gamma g(\gamma) \, \d h_2(\gamma)
			\notag
		\end{DispWithArrows}
		proving our first claim.

		Note that 
		\begin{align}
			\d \Tr\left[ A \proj{ A > \gamma B } \right]
			&= - \d \Tr\left[ A \proj{ A \leq \gamma B } \right],
			\\
			\d \Tr\left[ B \proj{ A > \gamma B } \right]
			&= - \d \Tr\left[ B \proj{ A \leq \gamma B } \right].
		\end{align}
		The second claim follows.

		For the last claim,
		we apply integration by parts on both sides of \eqref{eq:change-of-measure1}
		to obtain
		\begin{align}
			&g(\gamma)\Tr[A\{A>\gamma B\}]\biggr\vert_0^\infty -\int_0^\infty g'(\gamma) \Tr[A\{A>\gamma B\}] \, \d \gamma\\
			&=\gamma g(\gamma)\Tr[A\{A>\gamma B\}]\biggr\vert_0^\infty -\int_0^\infty \left(g(\gamma)+\gamma g'(\gamma)\right) \Tr[A\{A>\gamma B\}] \, \d \gamma,
		\end{align}
		or
		\begin{align}
			\int_0^\infty g'(\gamma) \Tr[A\{A>\gamma B\}] \, \d \gamma=\int_0^\infty \left(g(\gamma)+\gamma g'(\gamma)\right) \Tr[A\{A>\gamma B\}] \, \d \gamma,
		\end{align}
		which concludes the proof.
	\end{proof}




