	\section{Quantum \(f\)-divergence duality} \label{sec:f-duality}

	The classical $f$-divergence $D_f(P \Vert Q) = \mathds{E}_{Q}\left[ f\left(\frac{\d P}{\d Q}\right) \right]$ admits a variational formula via convex duality (see e.g.~\cite[\S 7.14]{Polyanskiy_book2024}):
	\begin{align}
		D_f(P \Vert Q ) 
		% &= \sup_{g: \mathcal{X}\to \mathds{R}} \left\{  \int_{\mathcal{X}} g(x) \, \d P(x) - \int_{\mathcal{X}} f^\star \circ g(x) \, \d Q(x) \right\}
		% \\
		&= \sup_{g: \mathcal{X}\to \mathds{R}} \left\{  \mathds{E}_{P}[g(X)] - \mathds{E}_{Q}\left[ f^\star ( g(X) ) \right] \right\}, \label{eq:convex_conjugate}
	\end{align}
	where the real-valued function $f^\star$ is the \emph{convex conjugate} (or \emph{Legendre--Fenchel transform}) of the convex function $f$ defined as
	\begin{align}
		f^\star(y) := \sup_{x \in \texttt{dom}(f)} \left\{ y x - f(x) \right\}.
	\end{align}
	It is well known that $f^\star$ is convex and continuous on its domain, and a biconjugation relation holds if $f$ is convex, i.e.,~$(f^\star)^\star = f$.
	Note that if $f$ is continuous and convex, then for fixed $y$ the optimizer is $x={f'}^{-1}(y)$.


	Via the Riemann--Stieltjes integral representation in Section~\ref{sec:relative_entropy_RS}, we show below that the quantum $f$-divergence naturally inherits such a variational representation
	via the Riemann--Stieltjes integral formula given in Proposition~\ref{prop:f-divergence_RS}.

	\begin{theo}[Quantum $f$-divergence duality] \label{theorem:f-duality}
		For any convex differentiable function $f$ on $[0,\infty)$,
		\begin{align}
			D_f(\rho \Vert \sigma)
			&= \sup_{g: [0,\infty)\to \mathds{R}}  \left\{
			\int_0^\infty g(\gamma) \, \d \Tr[\rho\{\rho\leq\gamma \sigma] - \int_0^\infty f^\star(g(\gamma)) \, \d \Tr[\sigma \{\rho\leq\gamma\sigma\}] \right\}. 
		\end{align}
	\end{theo}
	\begin{proof}
		Using the biconjugation $(f^\star)^\star = f$, the Riemann--Stieltjes integral representation given in \eqref{eq:f-divergence_RS_1} implies that
		\begin{align}
			D_f(\rho \Vert \sigma)
			&=   \int_{0}^{\infty} f(\gamma)\,  \d\Tr\left[ \sigma  \left\{  \rho \leq \gamma \sigma \right\} \right] 
			\\
			&= \int_{0}^{\infty} \sup_{y\in \texttt{dom}(f^\star)} \left\{ y \gamma - f^\star(y) \right\}  \d\Tr\left[ \sigma  \left\{  \rho \leq \gamma \sigma \right\} \right] 
			\\
			&\geq \int_{0}^{\infty}  g(\gamma) \gamma - f^\star(g(\gamma))\, \d\Tr\left[ \sigma  \left\{  \rho \leq \gamma \sigma \right\} \right] 
		\end{align}
		for all measurable functions $g: [0,\infty)\to \mathds{R}$. 
		Here, the inequality ``$\geq$'' because the map $\gamma \mapsto \Tr\left[ \sigma  \left\{  \rho \leq \gamma \sigma \right\} \right]$ is nondecreasing by Lemma~\ref{lemm:monotone_in_gamma}. 

		By a change of measure in Lemma~\ref{lemm:change-of-measure}, i.e.,
		\begin{align}
			\int_0^\infty g(\gamma) \gamma \d\Tr\left[ \sigma  \left\{  \rho \leq \gamma \sigma \right\} \right] 
			= \int_0^\infty g(\gamma) \d\Tr\left[ \rho  \left\{  \rho \leq \gamma \sigma \right\} \right],
		\end{align}
		and taking the supremum over all measurable functions $g: [0,\infty)\to \mathds{R}$, we prove one direction.

		Note that a convex conjugate in \eqref{eq:convex_conjugate} can be achieved by the derivative of $f$, i.e.,~$y = f'(x)$.
		Hence, the lower bound is achieved by $g(\gamma) = f'(\gamma)$.
	\end{proof}


	It is well known that the convex conjugate of $f(x) = x\log x$ is $f^\star(y) = \e^{y-1}$.
	Theorem~\ref{theorem:f-duality} implies the following variational formula.
	\begin{coro}[Variational representation for Umegaki's relative entropy via the Riemann--Stieltjes integral]
		For finite-dimensional quantum states $\rho$ and $\sigma$ satisfying $D_{\max}(\rho \Vert \sigma) < \infty $, 
		\begin{align} \label{eq:variational-RS}
			D(\rho\Vert\sigma)
			&=  \sup_{g: [0,\infty)\to \mathds{R}}  \left\{
			\int_0^\infty g(\gamma) \, \d \Tr[\rho\{\rho\leq\gamma \sigma] - \int_0^\infty \e^{g(\gamma)-1} \, \d \Tr[\sigma \{\rho \leq \gamma\sigma\}] \right\}.
		\end{align}
	\end{coro}

	\begin{remark}
		The variational formula in \eqref{eq:variational-RS} is not the same as the Donsker--Varadhan expression \cite{Pet88}:
		\begin{align}
			D(\rho\Vert\sigma)
			= \sup_{\omega >0} \left\{  \Tr[ \rho \log \omega ] - \log \Tr\left[ \e^{\log \sigma + \log \omega }\right] \right\}.
		\end{align}
		(which is also mentioned even in the classical case \cite[Example 7.6]{Polyanskiy_book2024}),
		in the sense that the former is formed by the scalar inner product while the latter is formed by the Hilbert--Schmidt inner product.
	\end{remark}

	The convex conjugate of $f(x)=\frac12 |x-1|$ is $f^\star(y) = y$ for $|y|\leq \frac12$ and $f^\star(y) = \infty$, otherwise.
	\begin{coro}
		\begin{align}
			\frac{1}{2}\left\| \rho - \sigma \right\|_1
			&= \sup_{ \|g\|_\infty \leq 1} \frac12 \int_0^\infty g(\gamma) \, \d \Tr[(\sigma-\rho) \{\rho\leq\gamma\sigma\}]. 
			% - \d \Tr[\rho\{\rho>\gamma\sigma\}].
		\end{align}
	\end{coro}


	The convex conjugate of $f(x) = (x-1)^2$ is $f^\star(y) = y + \frac{y^2}{4}$.
	\begin{coro}
		\begin{align}
			\chi^2(\rho\Vert\sigma)
			&= \sup_{g:[0,\infty)\to\mathds{R}} \left\{ \int_0^\infty g(\gamma) \, \d\Tr[\rho\proj{\rho\leq\gamma \sigma}]
			-  \int_0^\infty \left( g(\gamma) + \frac{g(\gamma)^2}{4} \right) \, \d \Tr[\sigma \proj{\rho\leq\gamma \sigma}]
			\right\} \\
			&= \sup_{g:[0,\infty)\to\mathds{R}} \left\{  \int_0^\infty g(\gamma) \, \d\Tr[\rho\proj{\rho\leq\gamma \sigma}]
			-  \int_0^\infty \left( 1 + \frac{g(\gamma)^2}{4} \right) \, \d \Tr[\sigma \proj{\rho\leq\gamma \sigma}]
			\right\}.
		\end{align}
	\end{coro}
	\begin{proof}
		Here, the second line follows either from $f(x)=x^2-1$ with $f^\star(y) = 1 + \frac{y^2}{4}$, or from the first line by substituting $g\rightarrow g-2$. 
	\end{proof}
	Further examples can be derived, e.g. for the Hellinger divergence we have $f^\star(y)=(\frac{\alpha-1}{\alpha}y)^{\frac{\alpha}{\alpha-1}}+\frac{1}{\alpha-1}$, which generalizes the result above for the $\chi^2$ divergence. 


