	\section{Proof of Theorem~\ref{Theo:trace-renyi-PO}} \label{sec:appendix_proof}
	\begin{proof}
		Let $A$ and $B$ be positive semi-definite operators.
		Recall,  
		\begin{align}
			H_{\alpha}(A\Vert B)
			&:= \Tr[A-B] + \alpha \int_1^\infty \gamma^{\alpha-2} E_{\gamma}(A\Vert B) + \gamma^{-\alpha -1} E_{\gamma}(B\Vert A) \d \gamma,
		\end{align}
		where $E_{\gamma}(A\Vert B) := \Tr\left[ (A-B)_+\right]$.

		We first simplify the expression for $H_{\alpha}(A\Vert B)$ as follows
		\begin{align}
			H_{\alpha}(A\Vert B) - \Tr[A-B]
			&= \alpha \int_1^\infty \Tr\left[ \gamma^{\alpha-2} (A - \gamma B) \proj{ A > \gamma B} \d \gamma \right] + \gamma^{-\alpha-1} \Tr\left[ (B - \gamma A) \proj{B> \gamma A} \right] \d \gamma.
			\notag
			\\
			\begin{split} \label{eq:order_above_1_H4}
				&= \alpha \int_1^\infty \gamma^{\alpha-2} \Tr\left[ A \proj{A > \gamma B } \right] \d \gamma  - \alpha \int_1^\infty \gamma^{\alpha-1} \Tr\left[ B \proj{A > \gamma B} \right] \d \gamma
				\\ 
				&+ \alpha \int_1^\infty \gamma^{-\alpha-1} \Tr\left[ B \proj{B>\gamma A} \right] \d \gamma - \alpha \int_1^\infty \gamma^{-\alpha} \Tr\left[ A \proj{B>\gamma A} \right] \d \gamma.
			\end{split}
		\end{align}

		We simplify the last two terms of \eqref{eq:order_above_1_H4} as follows
		\begin{align}
			\alpha \int_1^\infty \gamma^{-\alpha-1} \Tr\left[ B \proj{B>\gamma A} \right] \d \gamma 
			&=\alpha \int_0^1 \gamma^{\alpha-1} \Tr\left[ B \proj{ \gamma B> A} \right] \d \gamma
			&& ( \gamma \leftarrow \gamma^{-1} )
			\notag
			\\
			&= 
			\alpha \int_0^1 \gamma^{\alpha-1} \Tr[B] \d \gamma
			- \alpha \int_0^1 \gamma^{\alpha-1} \Tr\left[ B \proj{ \gamma B \leq A} \right] \d \gamma
			\notag
			\\
			&=\Tr[B]
			- \alpha \int_0^1 \gamma^{\alpha-1} \Tr\left[ B \proj{ \gamma B < A} \right] \d \gamma
			\label{eq:order_above_1_H4-(3)}
		\end{align}
		and
		\begin{align}
			\alpha \int_1^\infty \gamma^{-\alpha} \Tr\left[ A \proj{B>\gamma A} \right] \d \gamma 
			&=\alpha \int_0^1 \gamma^{\alpha-2} \Tr\left[ A \proj{ \gamma B> A} \right] \d \gamma
			&& ( \gamma \leftarrow \gamma^{-1} )
			\notag
			\\
			&= 
			\alpha \int_0^1 \gamma^{\alpha-2} \Tr[A] \d \gamma
			- \alpha \int_0^1 \gamma^{\alpha-2} \Tr\left[ A \proj{ \gamma B \leq A} \right] \d \gamma
			\notag
			\\
			&=
			\frac{\alpha}{\alpha-1} \Tr[A] - \alpha \int_0^1 \gamma^{\alpha-2} \Tr\left[ A \proj{ \gamma B < A} \right] \d \gamma,
			\label{eq:order_above_1_H4-(4)}
		\end{align}

		Substituting \eqref{eq:order_above_1_H4-(3)} and \eqref{eq:order_above_1_H4-(4)} into \eqref{eq:order_above_1_H4}, we obtain
		\begin{align}
			H_{\alpha}(A\Vert B)
			&= \frac{-1}{\alpha-1}\Tr[A]
			+ \alpha \int_0^\infty \gamma^{\alpha-2} \Tr\left[ A \proj{A > \gamma B } \right] \d \gamma  - \alpha \int_0^\infty \gamma^{\alpha-1} \Tr\left[ B \proj{A > \gamma B} \right] \d \gamma.
			\label{eq:order_above_1_H_formula}
		\end{align}
		We rewrite the last two terms as follows.
		Applying operator change of variables (Theorem~\ref{theo:change-of-variable}), we get
		\begin{align}
			\int_0^\infty \Tr\left[ A \proj{ A > \gamma B} \right] \gamma^{\alpha-2} \d \gamma
			&= \int_0^\infty \Tr\left[ A \frac{1}{B+t\I} A \frac{1}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha-2} 
			\right] \d t
			\notag
			\\
			&= \int_0^\infty \Tr\left[\left( A \frac{1}{B+t\I} \right)^{\alpha} 
			\right] \d t,
			\label{eq:order_above_1_H4-(1)}
		\end{align}
		and
		\begin{align}
			\int_0^\infty \Tr\left[ B \proj{ A > \gamma B} \right] \gamma^{\alpha-1} \d \gamma
			&= \int_0^\infty \Tr\left[ B \frac{1}{B+t\I} A \frac{1}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha-1} 
			\right] \d t
			\notag
			\\
			&= \int_0^\infty \Tr\left[ B \frac{1}{B+t\I} \left( A \frac{1}{B+t\I} \right)^{\alpha} 
			\right] \d t
			\notag
			\\
			&= \frac{\alpha-1}{\alpha} \int_0^\infty \left( A \frac{1}{B + t\I} \right)^\alpha \d t,
			\label{eq:order_above_1_H4-(2)}
		\end{align}
		where the last line follows from Lemma~\ref{lemm:order_above_1}.

		Combining \eqref{eq:order_above_1_H4-(1)} and \eqref{eq:order_above_1_H4-(2)}, we obtain
		\begin{align}
			H_{\alpha}(A\Vert B)
			&= \frac{-1}{\alpha-1}\Tr[A]
			+ \alpha \int_0^\infty \left( A \frac{1}{B + t\I} \right)^\alpha \d t
			- (\alpha-1) \int_0^\infty \left( A \frac{1}{B + t\I} \right)^\alpha \d t
			\notag
			\\
			&= \frac{-1}{\alpha-1}\Tr[A]
			+ \int_0^\infty \left( A \frac{1}{B + t\I} \right)^\alpha \d t.\notag
		\end{align} 
	\end{proof}





