\begin{lemma}\textnormal{\cite{feng2023}}\label{geq3}
Let $G_1^*\in U(m,n)$ be a $k$-uniform hypergraph with a unique cycle $C_{m,k}$ and $n_i$ be the number of pendant edges attached to each vertex $v_i\in V_0$. Let $G_2^*$ be a hypergraph obtained from $G_1^*$ by $v_1$-shrinking on $e_m$, and $e_0=e_m\setminus \{v_1\}$. If $m\geq 4$ and $n_3=max_{i\in [1,m]}n_i$, then $EE(G_1^*)<EE(G_2^*-e_0+(e_0\cup \{v_3\})).$\\
Note that, $G_2^*-e_0+(e_0\cup \{v_3\})$ is a $k$-uniform unicyclic hypergraph of order $n$ and the length of its unique cycle is $m-2$.
\end{lemma}
\begin{lemma}\textnormal{\cite{feng2023}}\label{C3ni}
    If $n_1\geq n_2 \geq n_3 \geq 1,$ then \[EE(C_3(n_1,n_2,n_3))<EE(C_3(n_1+n_2,n_3,0))<EE(C_3(n_1+n_2+n_3,0,0)).\]
\end{lemma}
\begin{lemma}\textnormal{\cite{Wand2020}}\label{EEuv}
    For a hypergraph $G^*$  with $u,v\in V(G^*)$ and 
    $E_0=\{e_1,e_2,\cdots,e_s\}$, where $e_i\in \mathcal{P}(V(G^*)),\, e_i\cap \{u,v\}=\phi$ for $i\in [1,s]$. Let 
    \begin{align*}
        E_u&=\{e_i'=e_i\cup\{u\}:e_i\in E_0,i\in [1,s]\},\\
         E_v&=\{e_i'=e_i\cup\{v\}:e_i\in E_0,i\in [1,s]\},
    \end{align*}
    $G^*_u=G^*-E_0+E_u$ and $G^*_v=G^*-E_0+E_v$. If for any $w\in \bigcup_{i\in[1,s]}e_i,\,(G^*,u)\prec (G^*,v)$ and $(G^*:w,u)\preceq (G^*:w,v)$, then $EE(G^*_u)<EE(G^*_v)$.
\end{lemma}
\begin{lemma}\textnormal{\cite{Wand2020}}\label{EEcolescence}
    Let $G^*_1$ and $G^*_2$ be two hypergraphs with $u,v \in V(G^*_1)$ and $w\in V(G^*_2)$. If $(G^*_1;u)\prec (G^*_1;v)$, then $EE(G^*_1(u)\cdot (w)G^*_2)< EE(G^*_1(v)\cdot (w)G^*_2)$, where $G^*_1(u)\cdot (w)G^*_2$ is the hypergraph obtained from $G^*_1$ and $G^*_2$ by identifying $u$ of $G^*_1$ with $w$ of $G^*_2$.
\end{lemma}
\begin{lemma}\textnormal{\cite{feng2023}}\label{numberofwalk}
    For a $k$-uniform unicyclic hypergraph $G^*$ with a unique cycle $C_{m,k},$ let $u \in V_0$ and $u_1$ be a pendant neighbour of $u$ in $G^*$, then $(G^*;u_1)\prec (G^*;u)$.
\end{lemma}
\begin{theorem}\textnormal{\cite{feng2023}}\label{unicyclicmax}
  Let $G^*$ be a $k$-uniform unicyclic hypergraph of order $n$, $EE(G^*)\leq EE(C_2(\frac{n}{k-1}-2,0))$ and the equality holds if and only if $G^* \cong C_2(\frac{n}{k-1}-2,0)$.
\end{theorem}

\begin{theorem}\textnormal{\cite{kurian2024}}\label{sumlamda2}
     Let $G^*$ be a $k$- uniform hypergraph with $n$ vertices and $m$ edges, and $\lambda_i,\,i\in[1,n]$ be the adjacency eigenvalues of $G^*$. Then
    \begin{equation*}
        k(k-1)m\leq\sum_{i=1}^n\lambda_i^2\leq (k-1)m\Bigl(m(k-2)+2\Bigr).
    \end{equation*}
\end{theorem}

\section{Eigenvalues of $k$-uniform hypergraph}
In this section, we study some of the interesting properties of the eigenvalues of a $k$-uniform hypergraph. 
\begin{theorem}
    Let $B$ be a symmetric matrix of order n whose largest entry is $b$ and the smallest entry is $a$. Then for every integer $t,\,2\leq t\leq n$,
    \[\tau_t \leq \dfrac{1}{2\theta+1}\left(\theta+\sqrt{\theta(t\theta +t-1)}\right)(b-a)+max\{0,a\},\]
where $\theta$ is the number of negative eigenvalues of $B$.
\end{theorem}
\begin{proof}
From Lemma \ref{sumlargestk}, to determine $\tau_t$ of symmetric matrices it is enough to consider the adjacency matrices of graphs. Therefore, from Theorem \ref{sumklargestgraph}
\[ \tau_t(M)\leq \dfrac{1}{2\theta+1}\left(\theta+\sqrt{\theta(t\theta +t-1)}\right),\,M\in M_n.\]
Let $C=B-aJ_n$. Then, $\dfrac{1}{b-a}C\in M_n$. Hence,
\begin{align*}
    \frac{1}{(b-a)n}\sum_{i=1}^t\lambda_i(C)&\leq\dfrac{1}{2\theta+1}\left(\theta+\sqrt{\theta(t\theta +t-1)}\right),\\
    \sum_{i=1}^t\lambda_i(C)&\leq\dfrac{n(b-a)}{2\theta+1}\left(\theta+\sqrt{\theta(t\theta +t-1)}\right).
\end{align*}
Since \[\sum_{i=1}^t\lambda_i(B)\leq \sum_{i=1}^t\lambda_i(C)+\sum_{i=1}^t\lambda_i(aJ_n)\] and \[\sum_{i=1}^t\lambda_i(aJ_n)=\begin{cases}
    an &if \quad  a\geq 0,\\
    0  &if \quad a<0,
\end{cases}\]  we get
\[\sum_{i=1}^t\lambda_i(B)\leq\dfrac{n(b-a)}{2\theta+1}\left(\theta+\sqrt{\theta(t\theta +t-1)}\right)+max\{0,an\}.\]
Consequently, this establishes the result.

\end{proof}
\begin{corollary}
        Let $G^*$ be a $k$-uniform hypergraph of order $n$. Then for every integer $t,\,t\in[2,n]$,
    \[\sum_{i=1}^t\lambda_i \leq \dfrac{n\binom{n-2}{k-2}}{2\theta+1}\left(\theta+\sqrt{\theta(t\theta +t-1)}\right),\]
where $\theta$ is the number of negative eigenvalues of $A(G^*)$.
\end{corollary}

\begin{theorem}\label{distincteig}
    Let $G^*$ be a $k$-uniform hypergraph on $n$ vertices. Then $G^*=(V(G^*),E(G^*))$ has 2 distinct eigenvalues if and only if $G^*$ is a $(n,k,\beta)$- BIBD, where every pair of vertices is contained in exactly $\beta$ edges.
\end{theorem}
% \begin{proof}
%     Suppose that $G^*$ has only two distinct eigenvalues. 
%     % Then, by Lemma \ref{diamG}, the diameter of $G^*$ must be equal to 1. Therefore, for ever $i,j\in[n]$, $a_{ij}\geq 1, i\neq j.$ 
%     By the Perron-Frobenius theorem, $\lambda_1$ and $\frac{\lambda_1}{n-1}$ are the eigenvalues of $G^*$ with multiplicity 1 and $(n-1)$, respectively. Since $A(G^*)$ is diagonalizable, then the minimal polynomial is 
%    \(
%         \lambda^2-\frac{(n-2)\lambda_1}{n-1}\lambda-\frac{\lambda_1^2}{n-1}=0.
%  \)
%     Then, the matrix $A(G^*)$ must satisfy the following conditions
%     \begin{align*}
%         (A^2)_{ii}&=\frac{\lambda_1^2}{n-1},\\
%         (A^2)_{ij}&=\frac{(n-2)\lambda_1}{n-1}a_{ij}.
%     \end{align*}
%     Hence, $A(G^*)=\frac{\lambda_1}{n-1}(J-I)=\beta(J-I)$. Thus, every two vertices is contained in exactly $\beta$ edges. Hence, $G^*$ is an $(n,k,\beta)$-BIBD.
% \end{proof}
\begin{proof}
    Suppose that $G^*$ has only two distinct eigenvalues. By the Perron-Frobenius theorem, $\lambda_1$ and $-\dfrac{\lambda_1}{n-1}$ are the eigenvalues of $G^*$ with multiplicity 1 and $(n-1)$, respectively. Therefore,
    \[\text{Rank}\left(A(G^*)+\frac{\lambda_1}{n-1}I_n\right)=1.\]
     Since every rank-one matrix can be represented as the outer product of two column vectors, there exist two vectors  \(\mathbf{v} = \begin{bmatrix} v_1 & v_2 & v_3 & \cdots & v_n \end{bmatrix}^T\) 
and  
\(
\mathbf{w} = \begin{bmatrix} w_1 & w_2 & w_3 & \cdots & w_n \end{bmatrix}^T
\)such that  
\[
A(G^*)+\frac{\lambda_1}{n-1}I_n = \mathbf{v w}^T =  
\begin{bmatrix}  
    v_1w_1 & v_1w_2 & v_1w_3 & \cdots & v_1w_n \\  
    v_2w_1 & v_2w_2 & v_2w_3 & \cdots & v_2w_n \\  
    \vdots & \vdots & \vdots & \ddots & \vdots \\  
    v_nw_1 & v_nw_2 & v_nw_3 & \cdots & v_nw_n  
\end{bmatrix}.
\]
Also, since $A(G^*)$ is symmetric and its diagonal entries are all zero, the following conditions must be satisfied:
\begin{itemize}
    \item $v_iw_i=\dfrac{\lambda_1}{n-1},i\in[1,n] $,
    \item $v_iw_j=v_jw_i,\,i\neq j,\,i,j\in[1,n].$
\end{itemize}
On solving these equations, we get $A(G^*)=\frac{\lambda_1}{n-1}(J_n-I_n)=\beta(J_n-I_n)$. Thus, every two vertices is contained in exactly $\beta$ edges. Hence, $G^*$ is an $(n,k,\beta)$-BIBD. The converse holds trivially. 
\end{proof}
The following corollary is an immediate consequence of Theorems \ref{BIBDdegree} and \ref{distincteig}.
\begin{corollary}
    Let $G^*$ be a $k$-uniform hypergraph of order $n$ with exactly two distinct eigenvalues. Then $G^*$ is regular with
    \begin{equation*}
        d(v_i)=\frac{\beta(n-1)}{k-1}, i\in[1,n],
    \end{equation*}
    where every pair of vertices is contained in exactly $\beta$ edges.
\end{corollary}

\section{Estrada index of a $k$-uniform hypergraph}
In \cite{Rodriguez2021}, the authors establish a lower bound for the Estrada index of graphs. Applying similar arguments, we establish that for a hypergraph $G^*$ of order $n$, a lower bound for its Estrada index is given by 
\[EE(G^*)\geq e^{\lambda_1}+(n-1)-\lambda_1.\]
 Now, let $f(x)=e^x+n-1-x$ be a function on $x\geq 0$. Since $f(x)$ increases, any lower bound for $\lambda_1$ provides another lower bound for the Estrada index of $G^*$. The following theorem establishes a lower bound for the Estrada index in terms of order, number of edges, and uniformity of the hypergraph.
\begin{theorem}
    Let $G^*$ be a $k$-uniform hypergraph with $n$ vertices and $m$ edges. Then \[EE(G^*)\geq \sqrt{n^2+\dfrac{4k(k-1)m}{2}}.\]
     The equality holds if and only if $G^*=\overline{K}_n^k$.
\end{theorem}
\begin{proof}
    Note that
    \begin{equation}\label{eqn1}
        (EE(G^*))^2=\sum_{i=1}^n e^{2\lambda_i}+2\sum_{i<j}e^{\lambda_i}e^{\lambda_j}.
    \end{equation}
    Using AM-GM inequality, we get
    \begin{align}\label{eqn2}
        \dfrac{2\sum_{i<j}e^{\lambda_i}e^{\lambda_j}}{n(n-1)}&\geq \left(\prod_{i<j}e^{\lambda_i}e^{\lambda_j}\right)^{\frac{2}{n(n-1)}},\nonumber\\
        2\sum_{i<j}e^{\lambda_i}e^{\lambda_j}&\geq n(n-1)\left(\prod_{i=1}^ne^{\lambda_i}\right)^{\frac{2}{n}}=n(n-1).
    \end{align}
Using power series expansion and spectral moments, we have
\begin{align*}
    \sum_{i=1}^ne^{2\lambda_i}&=\sum_{i=1}^n\sum_{s\geq 0} \dfrac{(2\lambda_i)^s}{s!}=n+2\sum_{i=1}^n\lambda_i^2+\sum_{i=1}^n\sum_{s\geq3}\dfrac{(2\lambda_i)^s}{s!}.
\end{align*}
Applying Theorem \ref{sumlamda2},
\[\sum_{i=1}^ne^{2\lambda_i}\geq n+2k(k-1)m+\sum_{i=1}^n\sum_{s\geq3}\dfrac{(2\lambda_i)^s}{s!}.\]
Aiming at a lower bound we replace $\sum_{s\geq3}\dfrac{(2\lambda_i)^s}{s!}$ by $8\sum_{s\geq3}\dfrac{(\lambda_i)^s}{s!}$. Therefore, 
\begin{align}\label{eqn3}
    \sum_{i=1}^ne^{2\lambda_i}&\geq n+2k(k-1)m+\gamma \sum_{i=1}^n\sum_{s\geq 3}\dfrac{(\lambda_i)^s}{s!}\nonumber\\
    &\geq n+2k(k-1)m-\gamma n-\gamma (k-1)m\frac{(m(k-2)+2)}{2}+\gamma \sum_{i=1}^n\sum_{s\geq 0} \dfrac{(\lambda_i)^s}{s!}\nonumber\\
    &=(1-\gamma)n+(2k-\dfrac{\gamma(m(k-2)+2)}{2})(k-1)m+\gamma EE(G^*), \,\qquad\gamma\in[0,8].
\end{align}
From (\ref{eqn1}),(\ref{eqn2}) and (\ref{eqn3}), we have
\[(EE(G^*))^2-\gamma EE(G^*)-n(n-\gamma)+(4k-\gamma(m(k-2)+2))\frac{(k-1)m}{2}\geq 0.\]
On solving, we get
\[EE(G^*)\geq \dfrac{\gamma}{2}+\sqrt{\left(\dfrac{\gamma}{2}-n\right)^2+(4k-\gamma(m(k-2)+2))\dfrac{(k-1)m}{2}}.\]
Now, consider the function
\[f(x)= \dfrac{x}{2}+\sqrt{\left(\dfrac{x}{2}-n\right)^2+(4k-x(m(k-2)+2))\dfrac{(k-1)m}{2}}\]
which is monotonically decreasing in [0,8]. Therefore, the best lower bound is at $\gamma=0$. Hence
\[EE(G^*)\geq \sqrt{n^2+\dfrac{4k(k-1)m}{2}}.\]
Clearly, equality holds if and only if the adjacency matrix of $G^*$ has no non-zero eigenvalue.  That is $G^*$ is an edgeless hypergraph $\overline{K}_n^k$.
\end{proof}
\begin{theorem}\label{thm4.2}
 Let $G^*$ be a $k$-uniform hypergraph with $n$ vertices and $m$ edges. Then \[EE(G^*)\leq n-1+e^{\sqrt{(k-1)m(m(k-2)+2)}}. \]   
  The equality holds if and only if $G^*=\overline{K}_n^k$.
\end{theorem}
\begin{proof}
    From the definition of Estrada index and Theorem \ref{sumlamda2}, we have
    \begin{align*}
        EE(G^*)&=n+\sum_{i=1}^n\sum_{s\geq 1}\dfrac{(\lambda_i)^s}{s!}\\
        &\leq n+\sum_{i=1}^n\sum_{s\geq 1}\dfrac{|\lambda_i|^s}{s!} \leq n+\sum_{s\geq 1}\dfrac{1}{s!}\left(\sum_{i=1}^n(\lambda_i^2)\right)^\frac{s}{2}\\
        &\leq n+\sum_{s\geq 1}\dfrac{(\sqrt{
        (k-1)m(m(k-2)+2)})^s}{s!}=n-1+e^{\sqrt{(k-1)m(m(k-2)+2)}}.
    \end{align*}
    The equality holds if and only if the adjacency matrix of $G^*$ has no non-zero eigenvalue.  That is, $G^*=\overline{K}_n^k$.
\end{proof}
The energy of a hypergraph $G^*$is defined as $E(G^*)=\sum_{i=1}^n \mid \lambda_i \mid.$
In the following theorem, we obtain a lower bound of the Estrada index of the $k$-uniform hypergraph in terms of its energy.  
\begin{theorem}
    Let $G^*$ be a $k$-uniform hypergraph with $n$ vertices and $m$ edges, and let $E(G^*)$ be its energy. Then
    \[EE(G^*)\leq n+E(G^*)-1-\sqrt{(k-1)m\left(m(k-2)+2\right)}+e^{\sqrt{(k-1)m\left(m(k-2)+2\right)}}.\]
    The equality holds if and only if $G^*=\overline{K}_n^k$.

\end{theorem}
\begin{proof}
    Using similar arguments from the proof of the Theorem \ref{thm4.2}, we get
    \begin{align*}
        EE(G^*)&\leq n+E(G^*)+\sum_{s\geq2}\frac{1}{s!}\left(\sqrt{(k-1)m\left(m(k-2)+2\right)}\right)^s\\
        &=n+E(G^*)-1-\sqrt{(k-1)m\left(m(k-2)+2\right)}+e^{\sqrt{(k-1)m\left(m(k-2)+2\right)}}.
    \end{align*}
\end{proof}
\begin{remark}
    From the definition of the Estrada index of hypergraph $G^*$ of order $n$, we have
    \begin{align*}
        EE(G^*)\leq n+\sum_{i=1}^n\sum_{s\geq1}\frac{\mid\lambda_i\mid^s}{s!}=n+\sum_{s\geq1}\frac{(E(G^*))^s}{s!}.
    \end{align*}
    Therefore, \[EE(G^*)\leq n-1+e^{E(G^*)}.\]
    and the equality holds if and only if $G^*=\overline{K}_n^k.$
\end{remark}

Next, we provide the Nordhaus–Gaddum-type bounds for the Estrada index of a $k$-uniform hypergraph.
\begin{theorem}
    Let $G^*$ be a $k$-uniform hypergraph of order $n$ and $\overline{G^*}$  be its complement. Then 
    \[EE(G^*)+EE(\overline{G^*})\geq 2 e^{\frac{n-1}{2}}+2(n-1)e^{-\frac{1}{2}}.\]
    Equality holds if and only if $G^*$ is a $k$-uniform hypergraph satisfying $(n,k,\beta)$-BIBD.
\end{theorem}
\begin{proof}
    Applying the AM-GM inequality, we get
    \begin{align*}
        EE(G^*)&
        &\geq e^{\lambda_1}+(n-1)e^{-\frac{\lambda_1}{(n-1)}}.
    \end{align*}
    Let $f(x)=e^x+(n-1)e^{-\frac{x}{(n-1)}}$.
    This function is increasing for all $x\geq 0$. Let $\lambda_i$ be the eigenvalues of $G^*$, and $\overline{\lambda}_i$ be the eigenvalues of $\overline{G^*}$ arranged in the decreasing order $\overline{\lambda}_1\geq \overline{\lambda}_2\geq \overline{\lambda}_3\ldots,\overline{\lambda}_n$. Then
    \begin{align*}
        EE(G^*)+EE(\overline{G^*})&\geq e^{\lambda_1}+e^{\overline{\lambda}_1}+(n-1)\left( e^{-\frac{\lambda_1}{(n-1)}}+e^{-\frac{\overline{\lambda}_1}{(n-1)}} \right)\\
        &\geq 2e^{\frac{\lambda_1+\overline{\lambda}_1}{2}}+2(n-1)e^{-\frac{\lambda_1+\overline{\lambda}_1}{n-1}}.
    \end{align*}
    Since $\lambda_1+\overline{\lambda}_1\geq n-1$, we have
    \[  EE(G^*)+EE(\overline{G^*})\geq 2 e^{\frac{n-1}{2}}+2(n-1)e^{-\frac{1}{2}}.\]
   Equality holds if and only if $G^*$ is a $k$-uniform hypergraph with two distinct eigenvalues, say $\lambda_1$ and $-\frac{\lambda_1}{n-1}$. Hence, by Theorem \ref{distincteig} $ G^*$ is a $k$-uniform hypergraph that satisfies $(n,k,\beta)$-BIBD.
\end{proof}

From (\ref{eqn1a}), it is evident that for any hypergraph $G^*$ of order $n$, adding an edge $e'$ contributes to an increase in the number of closed walks. Consequently, this leads to an increase in the Estrada index of the hypergraph. Therefore,
\[EE(G^*)<EE(G^*+e').\]
Also, it is evident that for a $k$- uniform hypergraph of order $n$,
\[EE(\overline{K}_n^k)<EE(G^*)<EE(K_n^k).\]
