\begin{theorem}\label{secmaxEEG}
    Let $G^{*}_0$ in $U(n) \setminus \{X_n\},\, n>3(k-1)$ be the $k$-uniform hypergraph with maximum Estrada index. Then $G^{*}_0\in U(m,n)\setminus\{X_n\}.$
\end{theorem}
\begin{proof}
Assume that $G^*_0$ in $U(n) \setminus \{X_n\},\, n>3(k-1)$ is the $k$-uniform hypergraph with the maximum Estrada index such that $G^*_0\notin U(m,n)\setminus\{X_n\}.$ \\
    \textbf{Case I.} When $m\geq 3$. Since $G^*_0\notin U(m,n)\setminus\{X_n\}$, there exists at least one vertex $v_t\in V_0$ with a non-pendant neighbour $u_t$ outside $C_{m,k}$ or in $V(C_{m,k})\setminus V_0$. Let 
    \begin{align*}
        E_0&=\{\Tilde{e}_i=e_i \setminus \{u_t\}:e_i \text{ is incident to } u_t \text{ and }  v_t\notin e_i\},\\
        &=\{\Tilde{e}_1,\Tilde{e}_2,\cdots,\Tilde{e}_{d(u_t)-1}\},\\
        E_{v_t}&=\{ \Tilde{e}_i\cup \{v_t\}:\Tilde{e}_i\in E_0,i\in[1,d(u_t)-1]\},\\
        E_{u_t}&=\{ \Tilde{e}_i\cup \{u_t\}:\Tilde{e}_i\in E_0,i\in[1,d(u_t)-1]\}.
    \end{align*}
In $G^*_0-E_{u_t}$, we have the following
\begin{itemize}
    \item $d(u_t)=1$ and $d(v_t)\geq 2$, then by Lemma \ref{numberofwalk} $(G^*_0-E_{u_t};u_t)\prec (G^*_0-E_{u_t};v_t)$.
    \item For any $w\in E_0,\,M_k(G^*_0-E_{u_t};w,u_t)=M_k(G^*_0-E_{u_t};w,v_t)=0$.
\end{itemize}
By Lemma \ref{EEuv}, we get $EE(G^*_0)<EE(G^*_0-E_{u_t}+E_{v_t})$. This is a contradiction of our assumption. Hence $G^*_0\in U(m,n)\setminus\{X_n\}.$ \\
\textbf{Case II.}When $m=2$. Since $G^*_0\notin U(m,n)\setminus\{X_n\}$ and $n > 3(k-1)$,  $G^*_0$ must satisfy one of the following conditions:
\begin{itemize}
    \item[i.] Both vertices in $V_0$ are incident to an edge outside  $C_{2,k}$, or one vertex in  $V_0$ and one in $V(C_{2,k})\setminus V_0$  are incident to an edge outside  $C_{2,k}$.
    \item[ii.] Exactly one vertex in $V_0$ is adjacent to a non-pendant vertex either outside $C_{2,k}$ or in $V(C_{2,k})\setminus V_0$, and at least one such non-pendant vertex is adjacent to another non-pendant vertex distinct from vertices of $V_0$ 
    \item[iii.] Exactly one vertex in $V_0$ is adjacent to a non-pendant vertex outside $C_{2,k}$ and the neighbours of this non-pendant vertex are all pendant vertices except for the vertex in $V_0$.
\end{itemize}
  The conditions i. and ii. contradict our assumption by following the same arguments as in Case I. Now we only need to prove for $G^*_0$ satisfying condition iii. Without loss of generality, $v_2$ is adjacent to a non-pendant vertex $u_t$ outside $C_{2,k}$ and $v_1$ does not have any neighbour outside $C_{2,k}$.
 Let $\bar{E}_0=\{e: e\in E(G^*_0)$ be an incident edge to $u_t$, $v_2\notin e\}.$ The edges of $\bar{E}_0$ form a k-uniform hyperstar $S^k_*$. Take $G^*_1=G^*_0-V(S^k_*)\setminus\{u_t\}.$ Clearly, we have $(G^*_1,u_t)\prec(G^*_1,v_1)$. By Lemma \ref{EEcolescence}, We get 
