				\cos a=1-2\left(\frac{\sqrt{5}-1}{4\cos{\frac{4\pi}f}}\right)^2,\,\,\,\, 
				\cos b=2 \left(\frac{(3-\sqrt5)\cos^2{\frac{4\pi}f}+\sqrt5-2}{\cos{\frac{4\pi}f}}\right)^2 -1,
