\begin{Lemma} Assume that $p>3$. We have ${\rm Ext}^i_{\La}(Y^{\la p\ra},  X)=0$ for $1\leq i\leq t-2$ and $\Ext_\Lambda^{t-1}(Y^{\la p\ra},  X)\neq 0$, where $t=2(p-1)$. \label{lemma4dot3}
\end{Lemma}
\begin{proof}

	By Theorem \ref{thm2dot2dot1}, $$\Ext_\Lambda^i(Y^{\la p\ra}, X)\cong \Ext_\Lambda^i(S^{\la 2, 1\ra}, Y^{\la p\ra})\cong \Ext^i(\Cs(\la 2, 1\ra), I(\la p\ra))=0$$ for $i=1, 2$. Now, assume that $i\geq 3$. Recall that the terms $R_r$ in (\ref{eq3}) are in $\add D(Q_\Lambda)$ and $Y^{\la p\ra }$ does not occur for $r\leq t-1$.

	By Lemma \ref{lemma4dot2}, applying $\Hom_\Lambda(-, X)$ to (\ref{eq3}) we obtain $\Ext_\Lambda^i(Z_{j-1}, X)\cong \Ext_\Lambda^{i+1}(Z_j, X)$ for all $i\geq 1$ and $2\leq j\leq t$. Hence,  dimension shifting yields $$\Ext_\Lambda^i(Y^{\la p\ra}, X)\cong \Ext_\Lambda^1(Z_{t-i+1}, X).$$
	Since $t-1\geq i\geq 3$, the module $Z_{t-i+1}$ is constructed in Proposition \ref{prop3dot4dot3}. For $t-1\geq i\geq 3$ consider the exact sequence $0\rightarrow Z_{t-i}\rightarrow R_{t-i}\rightarrow Z_{t-i+1}\rightarrow 0$ and apply $\Hom_\Lambda(-, X)$. Hence, by Lemma \ref{lemma4dot2}, we obtain an exact sequence
\begin{align}
	\Hom_\Lambda(R_{t-i}, X)\rightarrow \Hom_\Lambda(Z_{t-i}, X)\rightarrow \Ext_\Lambda^1(Z_{t-i+1}, X)\rightarrow 0. \label{eq16}
\end{align} By Lemma \ref{lemma4dotonedot3}, $\Hom_\Lambda(Z_{t-i}, X)=0$ for $3\leq i\leq t-2$. For $i=t-1$, the exact sequence (\ref{eq16}) becomes
$$\Hom_\Lambda(R_1, X)\rightarrow \Hom_\Lambda(Z_1, X)\cong k\rightarrow \Ext_\Lambda^1(Z_2, X)\rightarrow 0.$$ By Example \ref{example3dot4dot1}, $R_1=P^{\la 4, 2\ra}\bigoplus P^{\la 5, 3\ra}$. So, $\Hom_\Lambda(R_1, X)=0$ and thus $\Ext^{t-1}(Y^{\la p\ra}, X)\cong \Ext_\Lambda^1(Z_2, X)\cong k$.
\end{proof}

	\begin{Theorem}\label{maintheoremone}
		Let $k$ be an algebraically closed field with characteristic $p\geq 5$. Then  $$V^{\otimes 2p}\domdim_{S_k(p, 2p)} S_k(p, 2p)= 4(p-1).$$ In particular, $\Ext_{\Lambda_k(p, 2p)}^l(V^{\otimes 2p}, V^{\otimes 2p})=\Ext_{\Lambda_0}^l(Q_{\Lambda_0}, Q_{\Lambda_0})=0$ for $1\leq l\leq 4(p-1)-2$. 
	\end{Theorem}
	\begin{proof} Let $T$ be the characteristic tilting module of $S_k(p, 2p)$.  Then $\add T=\add V^{\otimes 2p}\oplus T(2^p)$. 
	By Theorem 3.1 of \cite{CE24}, we have $V^{\otimes 2p}\domdim_{S_k(p, 2p)} S_k(p, 2p)=2V^{\otimes 2p}\codomdim_{S_k(p, 2p)} T$.

		By Theorem 8.1.2 of \cite{Cr2}, $V^{\otimes 2p}\codomdim_{S_k(p, 2p)} T\geq 2$ (see also \citep[Remark 8.1.1]{Cr2}). Recall that $S_k(p, 2p)=A_0\oplus A_1$, where $A_0$ is the principal block of $S_k(p, 2p)$. So, by Corollary 3.1.9 of \cite{Cr2}, we obtain $Q\codomdim_{A_0} T_0\geq V^{\otimes  2p}\codomdim_{S_k(p, 2p)} T\geq 2$ and $\add T_0=\add Q\oplus T(2^p)$. Moreover, the maximal direct summand of $V^{\otimes 2p}$ which is an $A_1$-module is a characteristic tilting module. Write $\Lambda:= \Lambda_k(p, 2p)$. 
		Since $D(Q_\Lambda)$ is self-dual we have the following isomorphisms $$\Ext_\Lambda^i(D(Q_\Lambda), X)=\Ext_\Lambda^i(D(Q_\Lambda), {}^\natural S^{\langle 2, 1\rangle })\cong \Ext_\Lambda^i(S^{\langle 2, 1\rangle }, D(Q_\Lambda))\cong \Ext_\Lambda^i(Q_\Lambda, DS^{\langle 2, 1\rangle }).$$

		By Lemmas \ref{lemma4dot2},  \ref{lemma4dot3} and \ref{lemma2dot1dot2}, \begin{align*}
			D\Tor_i^\Lambda(Q_\Lambda, \Hom_{A_0}(Q, T(2^p)))\cong \Ext_\Lambda^i(Q_\Lambda, D\Hom_{A_0}(Q, T(2^p)))\cong\Ext_\Lambda^i(Q_\Lambda, DS^{\langle 2, 1\rangle })=0
		\end{align*} for $1\leq i \leq 2(p-1)-2$. Also, $\Ext_\Lambda^{2(p-1)-1}(Q_\Lambda, X)\neq 0$. By Theorem 3.1.4 of \cite{Cr2} and Lemma \ref{lemma2dot1dot2},  we have $Q\codomdim_{A_0} T(2^p)=2(p-1)$. By Theorem 3.1 of \cite{CE24}, $Q\domdim_{A_0} A_0=4(p-1)$ and thus $Q\domdim_{S_k(p, 2p)} S_k(p, 2p)=4(p-1)$. This means that $V^{\otimes 2p}\domdim_{S_k(p, 2p)} S_k(p, 2p)=4(p-1)$ (see \citep[Corollary 3.1.9]{Cr2}). The last claim follows now by \citep[Theorem 3.1.4(ii)]{Cr2} and Lemma \ref{lemma2dot1dot2}.
	\end{proof}







	\subsection{A tilting module built from Young modules} \label{tiltingmodulebuiltfromYoungmodules}
	Recall that a module $X$ over a finite-dimensional algebra $A$ is \emph{tilting} if $X$ is self-orthogonal, it has finite projective dimension and there exists an exact sequence $0\rightarrow A\rightarrow X_0\rightarrow\cdots\rightarrow X_t\rightarrow 0$ for some $t$.

	From Proposition \ref{5dotonedotone} it follows that $\Lambda_0$ is coresolved with a finite number of terms by direct sums of direct summands of $\bigoplus_{\lambda\neq \la p \ra} Y^\lambda$. Moreover, the proof of Proposition \ref{5dotonedotone} also gives that $\bigoplus_{\lambda\neq \la p \ra} Y^\lambda$ has projective dimension $p-2$. So, to show that $\bigoplus_{\lambda\neq \la p \ra} Y^\lambda$ is a tilting module, it remains to verify that $\Ext_{\Lambda_0}^i(\bigoplus_{\lambda\neq \la p \ra} Y^\lambda, \bigoplus_{\lambda\neq \la p \ra} Y^\lambda)=0$ for all $i>0$. 
	We show that ${\rm Ext}^i_{\La}(Y^{\lambda}, Y^{\mu})=0$ where
	$Y^{\lambda}$ and $Y^{\mu}$ are  non-projective
	Young modules in $\Lambda_0$, except the case $\lambda =\mu = \la p\ra$. 
	We may assume $\lambda \neq \la p\ra$ since we have by duality
	$${\rm Ext}^i_{\La} (Y^{\mu}, Y^{\lambda}) \cong {\rm Ext}^i_{\La}({}^\natural Y^{\lambda}, {}^\natural Y^{\mu})\cong \Ext_{\La}^i(Y^\lambda, Y^\mu).$$

	\begin{Lemma}Let $p>3$. Let $\lambda\neq \la p\ra$ and $\mu$ be two partitions of $2p$ in at most $p$ parts with $p$-weight two. Then,
		$\Ext_{\Lambda}^i(Y^\lambda, Y^\mu)=0$ for all $i>0$.\label{lema4dot2dot1}
	\end{Lemma}
	\begin{proof} 

				Assume that $i>p-2$. Then $\Ext^i_{\Lambda}(Y^\lambda, Y^\mu)=0$ because the projective dimension of $Y^\lambda$ is $p-2$ (see Subsection \ref{reducing the non injective}).



		Assume that $0<i\leq p-2$. By Theorem \ref{maintheoremone}, we obtain
		\begin{align*}
			\Ext^i_{\Lambda}(Y^\lambda, Y^\mu)\subset \Ext_\Lambda^i(Q, Q)=0.
		\end{align*}
	\end{proof}


	\begin{Theorem}\label{tiltingtheorem}
		$Q_\Lambda/Y^{\la p\ra}=\bigoplus_{\lambda\neq \la p \ra} Y^\lambda$ is a tilting $\Lambda_0$-module. Moreover, $V^{\otimes 2p}/(Y^{\la p\ra})^t$ is a tilting $\Lambda_k(p, 2p)$-module, where $t$ is the number of isomorphic copies of $Y^{\la p\ra}$ in $V^{\otimes 2p}$.
	\end{Theorem}
\begin{proof}
	By Lemma \ref{lema4dot2dot1} and Proposition \ref{5dotonedotone}, $Q$ is a tilting $\Lambda_0$-module. Since the direct summands of $V^{\otimes 2p}$ corresponding to a non-principal block of $S_k(p, 2p)$ are characteristic tilting modules in the respective block, the direct summands of $V^{\otimes 2p}$  corresponding to a non-principal block of $\Lambda$ are full tilting modules. Thus, $V^{\otimes 2p}/(Y^{\la p\ra})^t$ is a tilting $\Lambda_k(p, 2p)$-module.
\end{proof}




	\subsection{The principal block of $S_k(3, 6)$ and $\Lambda_k(3, 6)$ in characteristic three}\label{sec4dot3}

In this subsection, our aim is to show that Theorem \ref{maintheoremone} and Theorem \ref{tiltingtheorem} are also valid in characteristic three.

	The appendix of \cite{zbMATH07389875} is also valid for $p=3$, that is, we get the description of Specht modules and indecomposable projective modules.
	The only difference occurs in \citep[Corollary B.6]{zbMATH07389875}, in the notation for the Specht module $S^{\la 2, 1\ra}$. In the case $p\geq 5$  the composition factors of $S^{\la 2, 1\ra}$
	are $D^{\la 3, 1\ra}$ and $D^{\la 4, 3\ra}$ but when $p=3$ the second composition factor of $S^{\la 2, 1\ra}$ is $D^{\la 3\ra}$. To write down the quiver, we take the right hand side upper corner of the general quiver, replace the vertices $\la 4, a\ra$ just by $\la a\ra$
	for $1\leq a\leq 3$. So, the Gabriel quiver of the principal block of $\Lambda_k(3, 6)$ is 
		\begin{equation*}
		\begin{tikzcd}
		 \langle 3\rangle \arrow[d, leftrightarrow] \arrow[drr, leftrightarrow]& &  \langle 3, 2\rangle \arrow[d, leftrightarrow]  \\
			 \langle 2\rangle \arrow[dr, leftrightarrow] \arrow[urr, leftrightarrow]& & \langle 3, 1\rangle \\
			  & \langle  1\rangle \arrow[ur, leftrightarrow] \\
		\end{tikzcd}.
	\end{equation*} The quiver and its relations of this algebra was obtained in \citep[Theorem 7.1]{zbMATH00646847} based on \cite{zbMATH04125660}.
Then  for the quotient $\Lambda_k(3, 6)\cong k\cS_6/I_3$ we have, as before, projective resolutions of non-projective and non-simple Young modules ending with 
the projective modules for the quotient which are not injective:
\begin{align}
	0\to P_{\Lambda_0}^{\la 3,2\ra} \to P^{\la 2\ra} \to Y^{\la 1\ra} \to 0 \label{equation18} \\
	0\to P_{\Lambda_0}^{\la 3,1\ra} \to P^{\la 3\ra} \to Y^{\la 2\ra} \to 0 \label{equation19} \\
	0\to P_{\Lambda_0}^{\la 1 \ra} \to P^{\la 2\ra} \to Y^{\la 3,2 \ra} \to 0. \label{equation20}
\end{align}


	To summarise, the projective and Young modules are the following:

	\begin{enumerate}[(1)]
		\item $P^{\la 3\ra} = Y^{\la 2, 1\ra}$ and $P^{\la 2\ra} = Y^{\la 3, 1\ra}$ and they are both projective and injective.
		\item $P_{\Lambda_0}^{\la 3, 2\ra} = U{\la 3,2\ra\choose \la 3, 1\ra}$, it is Brauer induced and it is isomorphic to  $\Omega Y^{\la 1\ra}$.
		\item $P_{\Lambda_0}^{\la 3,1\ra}  = U{\la 3,1\ra \choose \la 2, 1\ra}$, it is Brauer induced and it is isomorphic to $\Omega Y^{\la 2\ra}$. 
		\item $P_{\Lambda_0}^{\la 1\ra} = U{\la 1\ra \choose \la 3, 1\ra}$ and this is Brauer induced and is isomorphic to $\Omega Y^{\la 3, 2\ra}$.
		\item $Y^{\la 3 \ra}= S^{\la 3 \ra}\cong k$.
		\item The modules $Y^{\la 1\ra}$ and $Y^{\la 2\ra}$ and $Y^{\la 3, 2\ra}$ are the Young modules which are neither projective nor simple, and with respect to their Specht filtration, they are given as follows:
		$$Y^{\la 1 \ra}\cong \begin{matrix}  S^{\la 2\ra}  \cr 
			S^{\la 1\ra}  \end{matrix}, \quad Y^{\la 2\ra}\cong  \begin{matrix}  S^{\la 3\ra}  \cr 
			S^{\la 2\ra}  \end{matrix}, \quad Y^{\la 3, 2\ra}\cong  \begin{matrix}  S^{\la 2\ra}  \cr 
			S^{\la 3, 2\ra}  \end{matrix}. $$
	\end{enumerate}

	In particular, we have exactly the same exact sequences for $p=3$ as described in Proposition \ref{5dotonedotone}. It follows that the non-projective Young modules $Y^\lambda$ with $\lambda\neq \la 3\ra$ have projective dimension equal to one. We also have that $S^{\la 2, 1\ra}$  has length two, with top isomorphic to $D^{\la 3, 1\ra}$ and socle isomorphic to $D^{\la 3\ra}$.



	\begin{Lemma} Assume $p=3$ and let $X$ be the dual Specht module ${}^\natural S^{\la 2, 1 \ra}$. Then 
		\begin{enumerate}[(a)]
			\item If $\lambda \neq \la 3\ra$, then ${\rm Ext}^i_\Lambda(Y^{\lambda}, X)=0$ for all $i\geq 1$.
			\item We have ${\rm Ext}_\Lambda^i(Y^{\la 3\ra}, X)=0$ for $1\leq i \leq  2$ and ${\rm Ext}_\Lambda^3(Y^{\la 3\ra}, X)\neq 0$. 
		\end{enumerate}\label{4dot3dot1}
	\end{Lemma}




	\begin{proof} \  We can assume that   $Y^{\lambda}$ is not projective.  Recall that $X$ has length two, with top isomorphic to $D^{\la 3\ra}$ and socle
		$D^{\la 3, 1\ra}$. To prove (a), assume that $\lambda \neq \la 3\ra$. Then 
		 $Y^{\lambda}$ has projective dimension $1=p-2$ and we only need the case $i=1$. 
		We apply the functor ${\rm Hom}_{\La}(-, X)$ to the minimal projective resolution of
		$Y^{\lambda}$.  If $\lambda = \la 1\ra$ or $\la 3,2\ra$ then this gives the sequence which is identically zero and hence ${\rm Ext}^1_\Lambda(Y^{\lambda}, X)$ is zero.  This leaves
		$$0\to {\rm Hom}_\Lambda(Y^{\la 2\ra}, X)\to {\rm Hom}_\Lambda(P^{\la 3\ra}, X) \to {\rm Hom}_\Lambda(P^{\la 3,1\ra}_{\Lambda_0}, X) \to  {\rm Ext}_\Lambda^1(Y^{\la 2 \ra}, X) \to 0.$$
		The second and third termsare isomorphic to $k$ and the first term is zero, hence the Ext space is zero. So (a) holds.

		For (b), we can now use part (a).
 We apply ${\rm Hom}_\Lambda(-, X)$ to the exact sequece 
		$$0\to S^{\la 2\ra}\to Y^{\la 2\ra} \to Y^{\la 3\ra} \to 0.$$
		In the resulting long exact sequence, all Hom spaces are zero and hence ${\rm Ext}_\Lambda^1(Y^{\la 3\ra}, X)=0$. Moreover,
		\begin{align}
			{\rm Ext}^i_\La(Y^{\la 3\ra}, X)\cong {\rm Ext}^{i-1}_\La(S^{\la 2\ra}, X) \label{e17}
		\end{align}
		for $i=2, 3$. 
		Now we apply ${\rm Hom}_\La(-, X)$ to the exact sequence
		$$0\to S^{\la 1\ra}\to Y^{\la 1\ra} \to S^{\la 2\ra}\to 0.$$
		In the resulting long exact sequence, the Hom spaces are zero and thus ${\rm Ext}_\Lambda^1(S^{\la 2\ra}, X)=0$. Moreover,
		\begin{align}
			{\rm Ext}_\La^2(S^{\la 2\ra}, X) \cong {\rm Ext}_\La^1(S^{\la 1\ra}, X). \label{eq18}
		\end{align}
		Applying ${\rm Hom}_\La(-, X)$ to the exact sequece
		$0\to S^{\la 3, 1\ra} \to P_{\La}^{\la 1\ra} \to S^{\la 1\ra}\to 0$
		gives
		$$0 = {\rm Hom}_\La(P_{\La}^{\la 1\ra}, X ) \to {\rm Hom}_\La(S^{\la 3, 1\ra}, X) = k \to {\rm Ext}_\La^1(S^{\la 1\ra}, X) \to 0$$
		and ${\rm Ext}^1_\La(S^{\la 1\ra}, X)=k$. By (\ref{e17}) and (\ref{eq18}), we obtain that $\Ext_\Lambda^2(Y^{\la 3\ra}, X)\cong \Ext_\La^1(S^{\la 2\ra}, X)=0$ and $\Ext_\Lambda^3(Y^{\la 3\ra}, X)\cong \Ext_\La^1(S^{\la 1\ra}, X)\cong k$.
	\end{proof}

	\begin{Cor}\label{4dot3dot2}
			Let $k$ be an algebraically closed field with characteristic $3$. Write $\Lambda=\End_{S_k(3, 6)}(V^{\otimes 6})^{op}$. Then, the following assertions hold.
			\begin{enumerate}[(a)]
				\item $V^{\otimes 6}\domdim_{S_k(3, 6)} S_k(3, 6)= 8$. In particular, $\Ext_\Lambda^l(V^{\otimes 6}, V^{\otimes 6})=\Ext_{\Lambda_0}^l(Q, Q)=0$ for $1\leq l\leq 6$. 
				\item Let $\lambda\neq \la p\ra$ and $\mu$ be two partitions of $6$ in at most $3$ parts with $3$-weight two. Then,
				$\Ext_{\Lambda}^i(Y^\lambda, Y^\mu)=0$ for all $i>0$.
				\item $Q/Y^{\la 3\ra}=\bigoplus_{\lambda\neq \la 3 \ra} Y^\lambda$ is a tilting $\Lambda_0$-module. Moreover, $V^{\otimes 6}/(Y^{\la 3\ra})^t$ is a tilting $\Lambda$-module, where $t$ is the number of copies of $Y^{\la 3\ra}$ that appear in $V^{\otimes 6}$.
			\end{enumerate} 
	\end{Cor}
\begin{proof}
	The exact same arguments employed in Theorem \ref{maintheoremone}, Theorem \ref{tiltingtheorem} and Lemma \ref{lema4dot2dot1} hold now for characteristic three by replacing the use of Lemma \ref{lemma4dot2} by Lemma \ref{4dot3dot1}(a) and Lemma \ref{lemma4dot3} by Lemma \ref{4dot3dot1}(b).
\end{proof}

\subsection{The relative dominant dimension over arbitrary fields}

As illustrated in \cite{Cr2}, relative dominant dimension is a homological invariant that is preserved under base change to an algebraically closed field. Recall that both the Schur algebra and the tensor power admit base change properties:
$\overline{k}\otimes_k (k^n)^{\otimes d}\cong \left( \overline{k}^n\right) ^{\otimes d}$ and $\overline{k}\otimes_k S_k(n, d)\cong S_{\overline{k}}(n, d)$
for every field $k$, where $\overline{k}$ denotes the algebraic closure of $k$ (see for example \citep[2.5]{Gr}.)

Thus, the results of this section on relative dominant dimension can be summarised as follows:

\begin{Theorem} \label{maintheoremarbitraryfield}
	Let $k$ be an arbitrary field with positive characteristic $p$.  Then $$V^{\otimes 2p}\domdim_{S_k(p, 2p)} S_k(p, 2p)=4(p-1).$$
\end{Theorem}
\begin{proof}
	For $p=2$, this is contained in \citep[Theorem 5.8]{CE24}. For $p=3$, the result follows by  \citep[Lemma 3.2.3]{Cr2} and Corollary \ref{4dot3dot2}. For $p>3$, the result follows by \citep[Lemma 3.2.3]{Cr2} and Theorem \ref{maintheoremone}.
\end{proof}


		\section{Homological properties of $S_k(p, 2p)$ and $\Lambda_k(p, 2p)$}\label{homologicalpropertiesofschuralgebras}

	In this section, our goal is to better understand the homological structure of Schur algebras of the form $S_k(p, 2p)$. More precisely, we will determine 
	\begin{itemize}
		\item the global dimension of $S_k(p, 2p)$;
		\item the Hemmer-Nakano dimension of $\mathcal{F}(\St_{R_k(n, d)})$ of the quasi-hereditary cover of $\Lambda_k(p, 2p)$, the centraliser of ${}_{S_k(p, 2p)} V^{\otimes 2p}$, which is formed by the Ringel dual of $S_k(p, 2p)$;
		\item a quasi-precluster tilting module of $\Lambda_k(p, 2p)$ in the sense of \citep{CP2}.
	\end{itemize}
	The latter is done by showing that the Schur algebras $S_k(p, 2p)$ fit into a non-trivial relative Auslander pair.

	\subsection{The quasi-hereditary cover of $\Lambda_k(p, 2p)$} Recall the notation introduced in Subsection \ref{sec2dot3}.
	As constructed in \cite{Cr2} and recalled in Theorem \ref{thm2dot2dot1} the pair $$(R_k(n, d), \Hom_{S_k(p, 2p)}(T, V^{\otimes 2p}))$$ is a quasi-hereditary cover of $\Lambda$. But, up until now, only a lower bound for the  Hemmer-Nakano dimension of $\mathcal{F}(\St_{R_k(n, d)})$  was known (see Theorem \ref{thm2dot2dot1}). 
	We apply now our computation of the relative dominant dimension $V^{\otimes 2p}\domdim S_k(p, 2p)$ to this cover.

	\begin{Theorem}\label{quasihereditarycover}
	Let $k$ be a field of characteristic $p>0$. Let $R_k(n, d)$ be the Ringel dual of $S_k(p, 2p)$. 
	%
	Then $(R_k(n, d), V^{\otimes 2p})$ is a $2(p-2)$-$\mathcal{F}(\St_{R_k(n, d)})$ quasi-hereditary cover of $\Lambda_k(p, 2p)$.
	More precisely, the Schur functor $F_{p, 2p}$ induces isomorphisms $$\Ext_{R_k(n, d)}^i(M, N)\cong \Ext_{ \Lambda_k(p, 2p)}^i(F_{p, 2p}M, F_{p, 2p}N)$$ for every $M, N\in \mathcal{F}(\St_{R_k(n, d)})$ and $0\leq i \leq 2(p-2)$; the isomorphism fails in general for $i=2(p-2)+1.$
\end{Theorem}
\begin{proof}
	For $p=2$, this is contained in  \citep[Corollary 6.8]{CE24}. Assume now that $p>2$. Then, the result follows from Theorem \ref{maintheoremarbitraryfield}, \citep[Theorem 5.3.1]{Cr2} and \citep[Theorem 3.1]{CE24}.
\end{proof}

This means that the Hemmer-Nakano dimension of $\mathcal{F}(\St_{R_k(n, d)})$ (with respect to $F_{p, 2p}$) is exactly $2(p-2)$.

As an application of this fact, we obtain the following.

	\begin{Cor}
	The Young  $\Lambda_0$-module $Y^{\la p \ra}$ has infinite projective dimension. \label{simpleYoungmoduledimension}
\end{Cor}
\begin{proof}
	Consider $\lambda$ so that $Y^\lambda$ has finite projective dimension. By Corollary \ref{finitisticlamdbazero}, \linebreak\mbox{$\pdim_{\Lambda_0} Y^\lambda\leq 2p-4$.} In particular, the projective dimension of $Y^\lambda$ is the maximum natural number $n$ satisfying $\Ext^n_{\Lambda_0}(Y^\lambda, \Lambda_0)\neq0$. By Theorem \ref{quasihereditarycover}, $\Ext^i_{\Lambda_0}(Y^\lambda, \Lambda_0)\cong \Ext^i_{A_0}(I(\lambda), Q)$ for every $i=0, \ldots, 2p-4$ and this isomorphism is induced by the functor $\Hom_{A_0}(Q, -)$. Moreover, by projectivisation, $\Hom_{A_0}(Q, -)$ identifies the modules in $\add Q$ with the projective  $\Lambda_0$-modules.  Thus, if $\pdim_{\Lambda_0} Y^\lambda=i\leq 2p-4$ then there exists an $\add Q_\Lambda$-resolution of $I(\lambda)$ of length $i$. Since $Q$ is self-orthogonal, this means that $Q\codomdim_{A_0} I(\lambda)=+\infty$.  By the proof of Proposition \ref{5dotonedotone}, all Young modules $Y^\lambda$ with $\lambda\neq \la p\ra$ have finite projective dimension. So, if $Y^{\la p\ra}$ has also finite projective dimension, then we would have $Q\codomdim_{A_0} I(\lambda)=+\infty$ for every partition $\lambda$ in $\Lambda_0$. But then, $Q\domdim_{A_0} A_0=Q\codomdim_{A_0} DA_0=+\infty$ which would contradict Theorem \ref{maintheoremone}. Thus, $Y^{\la p\ra}$ has infinite projective dimension.
\end{proof}


	\subsection{A quasi-precluster tilting module over $\Lambda_0$} \label{quasipreclustertiltingmodule}

	In this subsection, we present the underlying reason and the phenomenon that explains why the relative dominant dimension \linebreak $V^{\otimes 2p}\domdim_{S_k(p, 2p)} S_k(p, 2p)$ is precisely $4(p-1)$ and what does means for both the structure of $\Lambda_0$ and the principal block of $S_k(p, 2p)$. As we will show in the next result, these algebras fit in the setup presented in \cite{CP1} and \cite{CP2}.

		\begin{Theorem} \label{maintheorempair}Let $k$ be an algebraically closed field of characteristic $p\geq 3$.
		Let $A_0$ be the principal block of $S_k(p, 2p)$ and $Q$ the direct summand of $V^{\otimes 2p}$ corresponding to the principal block. Then $(A_0, Q)$ is a relative $4(p-1)$-Auslander pair and $\pdim_{A_0} Q=p-2$. In particular, $\gldim A_0=4(p-1)$.
	\end{Theorem}
\begin{proof} $Q$ is a direct summand of a characteristic tilting module, therefore it is a self-orthogonal $A_0$-module. 
	For the first claim, we need to show that $\gldim A_0\leq 4(p-1)\leq Q\domdim_{A_0} A_0$. The second inequality holds by Theorem \ref{maintheoremone} and Corollary \ref{4dot3dot2}. So, we determine now $\gldim A_0$. To do this, it is actually enough to show that $\gldim A_0\leq 4(p-1)$. Indeed,  since $Q\domdim_{A_0} A_0$ is a finite number (in particular $Q$ is not a characteristic tilting module) we have $\gldim A_0\geq Q\domdim_{A_0} A_0=4(p-1)$.




Assume that $p=3$. Then the global dimension of $S_k(3, 6)$ is $4(3-1)=8$ (see \cite{P}). Since $A_0$ is a block component of $S_k(3, 6)$, then  $\gldim A_0\leq \gldim S_3(3, 6)=8$.

Assume now that $p\geq 5$. Our strategy in this case is to use the quasi-hereditary structure of $S_k(p, 2p)$ and determine an upper bound for the injective dimension of the characteristic tilting module of $A_0$. Fix $\Lambda:=\Lambda_k(p, 2p)$.
Let $T_0$ be the characteristic tilting module of $A_0$, that is, $T_0=Q\oplus T(2^p)$.  As discussed in the proof of Theorem \ref{maintheoremone}, $Q\codomdim_{A_0} T_0\geq 2$. Lemma 2.8(i) of \cite{CP2} shows that $\injdim_{A_0} T_0=\dim_{\add Q_\Lambda} D\Hom_{A_0}(Q, T_0)$. By Lemma \ref{4dot1dot1}, $$D\Hom_{A_0}(Q, T_0)\cong D\Hom_{A_0}(Q, Q)\oplus D\Hom_{A_0}(Q, T(2^p))\cong D\Lambda_0\oplus DS^{\la 2, 1 \ra}$$ as right $\Lambda_0$-modules.



Since $\Ext_\Lambda^i(D(Q_\La), D(Q_\La))=0=\Ext_\Lambda^i(Q_\La, Q_\La)=0$ for $1\leq i\leq 4(p-1)-2$ and $R_{2(p-1)}=Y^{\langle p\rangle}\in \add DQ$ we obtain that (\ref{eq3}) is exact under $\Hom_\Lambda(-, D(Q_\La))$. Write $\delta$ to denote the exact sequence (\ref{eq3}). Then $D\delta$ is exact and it remains exact under $\Hom_\Lambda(Q_\La, -)$ and this means that $\dim_{\add Q_\Lambda} DS^{\la 2, 1\ra}\leq 2(p-1)$. Denote by $\gamma$ the direct sum of all the exact sequences (1)-(5) appearing in the proof of Proposition \ref{5dotonedotone}. This is an $\add D(Q_\La)$-coresolution of the direct sum of the projective $\Lambda_0$-modules which are not Young modules. Since the size of this coresolution is $p-2$ and $\Ext_{\Lambda_0}^i(Q, Q)=0$ for $1\leq i\leq p\leq  4(p-1)-2$, $\gamma$ remains exact under $\Hom_{\Lambda_0}(-, DQ)$. Thus, $D\gamma$ is exact and it remains exact under $\Hom_{\Lambda_0}(Q, -)$. So, $\dim_{\add Q_\Lambda} D\Lambda_0\leq p-2\leq 2(p-1)$ and it follows that $\injdim_{A_0} T_0\leq 2(p-1)$. The simple preserving duality on $A_0$ imposes then that $\gldim A_0\leq 4(p-1)$ (see \cite{zbMATH02105773}).

	Observe that $\dim_{\add Q} D\Lambda$ cannot be smaller than $p-2$ since the coresolutions constructed in the proof of Proposition \ref{5dotonedotone} are sent under $\Hom_\Lambda(-, D(Q_\La))$ to projective resolutions of direct summands of $D(Q_\La)$ whose middle terms are indecomposable modules. Hence, such projective resolutions are minimal and thus $\pdim_{A_0} Q=p-2$.


	For $p=3$, the resolutions in Subsection \ref{sec4dot3} have length one, and since $Q_\Lambda$ is self-orthogonal up to degree $4(p-1)-2$, those resolutions remain exact under $\Hom_\Lambda(-, DQ)$ as well. So, $\dim_{\add Q} D\Lambda=1$ in characteristic three and so $\pdim_{A_0} Q=1=3-2$ using the equality established in Lemma 2.8(i) of \cite{CP2}.
\end{proof}

	So according to \citep[Theorem 3.3]{MTcorrespondence}, Proposition \ref{5dotonedotone} can be reformulated into saying that $Q_\La$ is an $(p-2)$-quasi-cogenerator over $\Lambda$ and its self-duality implies that it is also an $(p-2)$-quasi-generator over $\Lambda$.

From the above theorem it follows that $$\gldim A_0=4(p-1)\geq 2(p-1)=2p-2=(p-2)+(p-2)+2=\pdim_{A_0} Q+\injdim_{A_0} Q+2.$$ This means that these pairs fit into the higher dimensional Auslander-Iyama-Solberg correspondence established in \cite{CP2}. Further, $Q_\La$ is a $(4(p-1), p-2, p-2)$-quasi-precluster tilting $\Lambda$-module in the sense of \cite{CP2}. In particular, the module $\tau\Omega^{3p-4}Q_\La\cong \tau\Omega^{3p-4}Y^{\la p\ra}$ fits into an $\add Q_\La$-resolution of length $p-2$ and 
$$\add Q_\Lambda={}^{\perp_{p-2}} Q_\Lambda\cap Q_\Lambda^{\perp_{3p-4}}={}^{\perp_{3p-4}} Q_\Lambda\cap Q_\Lambda^{\perp_{p-2}}.$$





	\subsection{Global dimension of $S_k(p, 2p)$} \label{globaldimensionofSp2p} For $p\in \{2, 3\}$ the global dimension of $S_k(p, 2p)$ was determined in \cite{P}. For $p>3$, this homological invariant was, as far as we know, unknown until now.
		As we have shown, the global dimension of the principal block of $S_k(p, 2p)$ is $4(p-1)$, so we just need to check the global dimension of the non-principal blocks of $S_k(p, 2p)$. 

		\subsubsection{Blocks of $S(n, d)$} 

	Since $(k^n)^{\otimes d}$ affords a double centraliser property between $S_k(n, d)$ and $\Lambda_k(n, d)$ the blocks of $S_k(n, d)$ are in one to one correspondence with the blocks of $\Lambda_k(n, d)$ in the sense that if $\mathcal{B}$ is a block of $\Lambda_k(n, d)$, then $\Hom_{S_k(n, d)}((k^n)^{\otimes d}, -)$ sends the injective modules of the respective block ${S_k(n, d)}_\mathcal{B}$ to the Young modules living in the block $\mathcal{B}$ (for example, this follows a similar argument as in \citep[Corollary 5.38]{zbMATH01361790} together with Equation (\ref{eqone})). Moreover, if $X$ is the maximal multiplicity-free direct summand of $(k^n)^{\otimes d}$ living in the block $\mathcal{B}$, then the block component of the Schur algebra corresponding to the block $\cB$ is Morita equivalent to $\End_{\mathcal{B}}(X)$. Further, $\mathcal{B}$ can be written as a quotient of a block component of $k\cS_d$, say $\mathcal{K}$, and $\End_{\mathcal{B}}(X)\cong \End_{\mathcal{K}}(X)$. So the block component ${S_k(n, d)}_\mathcal{B}$ is also completely determined by the block $\mathcal{K}$.

	We recall the description of the blocks of finite representation-type of $S_k(n, d)$ described in \cite{E2}.

	%Blocks of finite type
		\begin{Lemma} Let $k$ be an algebraically closed field of characteristic $p$, and let $\cB$ be a block of finite representation-type in the group algebra $k\cS_d$. Assume that $n \leq d$.  \label{lemma5dot3dot1}
			\begin{enumerate}
				\item The  partitions in $\cB$ are linearly ordered by the dominance order, say $\mu_1>\mu_2>\ldots > \mu_{p}$.
				\item Assume  that $m$ is largest natural number such that $\mu_m$ has  at most $n$ parts. Then the partitions
				$\mu_1, \ldots, \mu_{m}$  have at most $d$ parts and $\mu_k$ has more than $n $ parts for $k>m$.
				\item Let $S_k(n,d)_{\cB}$ be the component of the Schur algebra corresponding to the block $\cB$. Then 
				$S_k(n,d)_{\cB}$ is Morita equivalent to the algebra $\cA_m$ as defined in \cite{E2}.  In particular, it has finite representation-type and $m$ is smaller than or equal to the number of simple modules in $\cB$.
			\end{enumerate}
	\end{Lemma}
\begin{proof}
	For (a) and (b) see \citep[4.1]{E2}.

	The Young modules in $\cB$ are as follows: 
	We have $Y^{\mu_1} = S^{\mu_1}$ which is simple, and  for \mbox{$2\leq i\leq p-1$,} the Young module $Y^{\mu_i}$ is the indecomposable projective module %$P_{i-1}$
	 with Specht quotients
	$S^{\mu_{i-1}}$ and $S^{\mu_i}$. 
The block component $S(n,d)_{\cB}$ is Morita equivalent to the endomorphism algebra of $\oplus_{i=1}^m Y^{\mu_i}$. 
	Then part (c) follows directly from \citep[Proposition 3.2]{E2}, noting that the Young modules have the appropriate submodule structure.
\end{proof}




	\subsubsection{Non-principal blocks of $S(p, 2p)$}
	To understand the form of the non-principal blocks of $S_k(p, 2p)$, we will analyse the size of the blocks of $\Lambda_k(p, 2p)$. In turn, they arise as quotients of blocks of $k\cS_{2p}$. By \emph{Nakayama's conjecture on the blocks of the symmetric group} and \cite{zbMATH00023610}, the blocks of $k\cS_{2p}$ are determined up to Morita equivalence by their $p$-core and $p$-weight (see also \cite{zbMATH03519005}). The Specht modules in $\Lambda$ are labelled by partitions of $2p$ in at most $p$ parts. The (combinatorial) weight of a block is the number of $p$-hooks removed to reach the $p$-core. So, for partitions $\lambda\in \L^+(p, 2p)$ the weight is either one or two or zero. If the weight is zero, then the block is semisimple, and thus it can be ignored. If the weight is two, then the $p$-core is empty and in such a case we would get the principal block $\Lambda_0$. So, every non-principal (non-semisimple) block component of $\Lambda$ is the quotient of a block of $k\cS_{2p}$, say $\mathcal{K}$, with $p$-weight  equal to one. Since $p$ is larger than the weight of $\mathcal{K}$, the defect of the block $\mathcal{K}$ is equal to the $p$-weight, hence in this case it is one (see for instance \cite{MR644144}). 
	By \citep[Example 1]{zbMATH00023610}, the block $\mathcal{K}$ is Morita equivalent to the principal block of $k\cS_p$, and in particular it has finite representation-type. So, the number of simple modules in $\mathcal{K}$ is $p-1$ (see for instance \cite{E2}).
	By Lemma \ref{lemma5dot3dot1}, the block component of the Schur algebra $S_k(p, 2p)$ corresponding to the block $\mathcal{K}$ is Morita equivalent to $\mathcal{A}_m$ for some $m\leq p-1$. 




By direct computation, making use of the quiver and relations of $\mathcal{A}_m$, it is not difficult to see that the global dimension of $\mathcal{A}_m$ is precisely $2(m-1)$, and that the dominant dimension of $\mathcal{A}_m$ is also $2(m-1)$ (compare with \citep[Theorem 1.1]{zbMATH07463798} when the $p$-weight is one). Hence, it is actually a higher Auslander algebra of global dimension $2(m-1)$. Thus,  any block component of $S_k(p, 2p)$ distinct from the principal block has global dimension smaller than or equal to $2(p-2)\leq 4(p-1).$



	Combining this discussion with Theorem \ref{maintheorempair}, we showed the following.

	\begin{Theorem}\label{thm5dotone}
		The global dimension of $S_k(p, 2p)$ is equal to $4(p-1)$.
	\end{Theorem}
\begin{proof}
	The global dimension of $S_k(p, 2p)$ is the supremum of the global dimensions of all its block components. So by  Theorem \ref{maintheorempair} and the discussion above, the claim follows.
\end{proof}
	In the example below, we illustrate that the number of simple modules in a block of $\Lambda$ can be smaller than $p-1$, and thus the global dimension of the respective block component of $S_k(p, 2p)$ can be strictly smaller than $2(p-2)$.

		\begin{Example} Let $p=5$, then there are two $5$-cores of size $5$ (with $5$-weight one), they are $(3, 2)$ and $(2^2, 1)$.  We can use an abacus to display the partitions in the block $B_{(3,2)}$ that contains $(3, 2)$.

		Take an abacus $\Gamma = \la 1,1,2,1,2\ra$ (ie it has one bead on runners $1,2,4$ and two beads on runners $3$ and $5$. 
		Then we label the partitions exactly as we have done before. Then they are in dominance order by
		$$\la 5\ra > \la 3\ra > \la 4\ra > \la 2\ra > \la 1\ra.$$
		In terms of partitions, 
		$$(8, 2) > (6, 4) > (3^3, 1)  > (3, 2^2, 1^3) > (3, 2, 1^5).
		$$
		The last two have more than $5$ parts. The quotient has then three simple modules.
	\end{Example}

\subsubsection{The projective dimension of the tensor power}

\begin{Cor}
	The pair $(S_k(p, 2p), V^{\otimes 2p})$ is a relative $4(p-1)$-Auslander pair and $$\pdim_{S_k(p, 2p)} V^{\otimes 2p}=\injdim_{S_k(p, 2p)} V^{\otimes 2p}=\begin{cases}
		p-2, &\text{ if } p>2\\
		1, &\text{ if } p=2
	\end{cases}.$$
\end{Cor}
\begin{proof} For $p=2$ we refer the reader to \cite{CE24} and \citep[Example 4.1]{CP2}. Assume now that $p>2$.
	Since $\la 2, 1\ra=(2^p)$ is the only non $p$-regular partition of $2p$ in at most $p$ parts, the direct summands of $V^{\otimes 2p}$ in the non-principal block components are characteristic tilting modules. Let $\mathcal{B}$ be a non-principal block of $S_k(p, 2p)$ and $V_\mathcal{B}$ the maximal multiplicity-free direct summand of $V^{\otimes 2p}$ in the block component $\mathcal{B}$. Since $V_\mathcal{B}$ is a full tilting module, $V_\mathcal{B} \domdim \mathcal{B}=+\infty$. By Theorem \ref{maintheoremone}, it follows that $V^{\otimes 2p}\domdim S_k(p, 2p)=4(p-1)$ (see also \citep[Corollary 3.1.9]{Cr2}). By Theorem \ref{thm5dotone}, the first claim follows. 

	By Theorem \ref{maintheorempair}, $\pdim_{A_0} Q=p-2$. By the discussion above, $\gldim \mathcal{B}\leq 2(p-2)$. Since $V_\mathcal{B}$ is a characteristic tilting module, we obtain by \citep[Corollary 1]{zbMATH02105773} that $\pdim V_\mathcal{B}\leq p-2$. It follows that $\pdim_{S_k(p, 2p)} V^{\otimes 2p}=p-2$. Since it is self-dual, the same statement holds for the injective dimension.
\end{proof}

\subsubsection{Global dimension of Schur algebras $S(t, 2p)$}


In \cite{zbMATH00966941}, Totaro proved that $S_k(2p, 2p)$ has global dimension equal to $2(2p-2)=4(p-1)$ when $k$ has characteristic $p>2$ and $\gldim S_k(4, 4)=2(4-1)=6$ when $k$ has characteristic two. So far, our approach unravelled the value of $\gldim S_k(p, 2p)$ among other insights into the homological properties of $S_k(p, 2p)$ like the projective dimension of the tensor space. Now, we provide an alternative approach  to assert that $\gldim S_k(p, 2p)=4(p-1)=\gldim S_k(2p, 2p)$ when $p>2$ combining Totaro's result with our results on relative dominant dimensions making use of Schur functors and the simple preserving duality. As a by-product, we obtain the value of all intermediate Schur algebras between $S_k(p, 2p)$ and $S_k(2p, 2p)$.



\begin{Cor}\label{cor5dot3dot5}
	Let $k$ be an algebraically closed field with characteristic $p>0$. Then, $\gldim S_k(t, 2p)=4(p-1)$ for every $t=p, \ldots, 2p-1$.
\end{Cor}
\begin{proof}
	By \cite{Gr}, there exists an idempotent $e$ of $S_k(t, 2p)$ such that $S_k(p, 2p)\cong eS_k(t, 2p)e$.  This idempotent satisfies 1.5 and 1.6 of \cite{E1}. Let $T_t$ be the multiplicity-free characteristic tilting module of $S_k(t, 2p)$ and $\Cs_t$ be the direct sum of all indecomposable costandard modules of $S_k(t, 2p)$ for $t=p, \ldots, 2p-1$  By 1.6 of \cite{E1}, by multiplying an $\add T_t$ resolution of costandard modules with the idempotent $e$, the resolution remains exact and the middle terms are sent to $\add T_p$ (potentially some of the middle terms of the resolution become zero). This means that $\dim_{\add T_p} \Cs_p\leq \dim_{\add T_t} \Cs_t$.
	By Lemma 2 of \cite{zbMATH02105773}, we obtain
	$$\pdim_{S_k(p, 2p)} T_p=\dim_{\add T_p} \Cs_p\leq \dim_{\add T_t} \Cs_t=\pdim_{S_k(t, 2p)}=\pdim_{S_k(t, 2p)} T_t.$$

	By the main result of \cite{zbMATH02105773}, we then obtain that $\gldim S_k(p, 2p)\leq \gldim S_k(t, 2p)$. With this, Theorem \ref{thm5dotone} gives $\gldim S_k(t, 2p)\geq 4(p-1)$ \footnote{this bound can also be deduced from  Theorem \ref{maintheoremone} (and from \citep[Theorem B]{CE24} for characteristic two) since in this case the inequality $\gldim S_k(p, 2p)\geq V^{\otimes 2p}\domdim_{S_k(p, 2p)} S_k(p, 2p)$ holds.}. By Theorem 3 of \cite{zbMATH00966941},
	we obtain that $$ 4(p-1)\leq\gldim S_k(t, 2p)\leq 2(2p-\left\lceil \frac{p^1}{t} \right\rceil -\left\lceil \frac{p^1}{t} \right\rceil )=2(2p-2)=4(p-1).$$
So, $\gldim S_k(t, 2p)=4(p-1)$. 
\end{proof}

This result highlights another homological distinction between the case $p=2$ and larger primes. Specifically, for $p>2$, we have $\gldim S_k(2p, 2p)=\gldim S_k(p, 2p)$, whereas for $p=2$ $\gldim S_k(4, 4)=6\neq \gldim S_k(2, 4)=4$.

\subsubsection{Global dimension of Schur algebras $S(t, 2p)$ over arbitrary fields} \label{globaldimensionoverarbitraryfields}

Schur algebras are quasi-hereditary over any field (see for example \citep[Section 5]{cellularqhalgebras} and the references therein), hence they have finite global dimension. So, the global dimension of $S_k(t, 2p)$ coincides with the projective dimension of $DS_k(t, 2p)$. Since the latter has a base change property, this means that the global dimension of Schur algebras over a field is preserved under base change to an algebraically closed field. To make this precise, we use the following folklore lemma, widely known though rarely stated explicitly.

\begin{Lemma}
	Let $k$ be an arbitrary field and $A$ a finite-dimensional $k$-algebra. Then,  $$\injdim \overline{k}\otimes_k A=\injdim A,$$ where $\overline{k}$ denotes the algebraic closure of $k$. \label{lemmainvarianceofinjectivedimension}
\end{Lemma}
\begin{proof}
	To distinguish the different standard dualities, we write $D_k$ to denote $\Hom_k(-, k)$. Observe that  $\injdim \overline{k}\otimes_k A=\injdim A$ is equivalent to $\pdim_{\overline{k}\otimes_k A} D_{\overline{k}}(\overline{k}\otimes_k A)=\pdim_A D_kA$. Moreover, $D_{\overline{k}}(\overline{k}\otimes_k A)\cong \overline{k}\otimes_k D_kA$ since $\overline{k}$ is free as $k$-module.

	Assume that $\pdim_A D_k A$ is finite. Then since $\overline{k}\otimes_k -$ is an exact functor and sends projective modules to projective modules, we obtain that it preserves projective resolutions, and so $\pdim_{\overline{k}\otimes_k A} \overline{k}\otimes_k D_kA\leq \pdim_A D_k A$. If $\pdim_{\overline{k}\otimes_k A} \overline{k}\otimes_k D_kA$ is infinite, then there is nothing more to prove. So, assume that $\pdim_{\overline{k}\otimes_k A} \overline{k}\otimes_k D_kA=n$ for some $n\in \mathbb{N}$. Then for every $N\in A\m$, 
	$$\overline{k}\otimes_k \Ext_A^{n+1}(D_kA, N)\cong \Ext_{\overline{k}\otimes_k A}^{n+1}(\overline{k}\otimes_k D_k A, \overline{k}\otimes_k N)=0. $$ Since $\overline{k}\otimes_k -$ preserves any basis over $k$, we get that $\Ext_A^{n+1}(D_kA, N)=0$ for every $N\in A\m$, that is, $\pdim_A D_kA\leq n$.
\end{proof}


We can also make use of this lemma  to generalise Theorem \ref{thm3:3:2} and the previous results in this section to arbitrary fields.

\begin{Theorem}\label{maintheoremA}
	Let $k$ be an arbitrary field with positive characteristic $p$. Then, the following holds.
\begin{enumerate}
	\item $\gldim S_k(t, 2p)=4(p-1)$ for every $t=p, \ldots, 2p-1$.
	\item $(S_k(p, 2p), V^{\otimes 2p})$ is a relative $4(p-1)$-Auslander pair.
	\item $\Lambda_k(p, 2p)$ is Iwanaga-Gorenstein, and $\findim \Lambda_k(p, 2p)=2p-4$ when $p>2$.
\end{enumerate}
\end{Theorem}
\begin{proof} Let $\overline{k}$ be the algebraic closure of $k$.
	Since Schur algebras (over a field) have finite global dimension, we have $\gldim S_k(t, 2p)=\injdim S_k(t, 2p)$. By Lemma \ref{lemmainvarianceofinjectivedimension} and Corollary \ref{cor5dot3dot5},
	$\injdim S_k(t, 2p)=\injdim \overline{k}\otimes_k S_k(t, 2p)=\injdim S_{\overline{k}}(t, 2p)=4(p-1).$ 

	Part (2) follows from part (1) together with Theorem \ref{maintheoremarbitraryfield}.

	For part (3), recall from Theorem \ref{thm3:3:2} and Corollary \ref{finitisticlamdbazero} that $\L_{\overline{k}}(p, 2p)$ is Iwanaga-Gorenstein and $\findim \L_{\overline{k}}(p, 2p)=2p-4$ when $p>3$. Using the same arguments and the resolutions in Equations (\ref{equation18}), (\ref{equation19}) and (\ref{equation20}) we obtain that $\La_{\overline{k}}(3, 6)$ has injective dimension two (both as left and right module) when $p=3$. 

	 Observe that 
	 \begin{align}
	 	\overline{k}\otimes_k\La_k(p, 2p)&\cong \overline{k}\otimes_k \End_{S_k(p, 2p)}((k^p)^{\otimes 2p})^{op}\cong \End_{\overline{k}\otimes_k S_k(p, 2p)}(\overline{k}\otimes_k(k^p)^{\otimes 2p})^{op} \\&\cong \End_{S_{\overline{k}}(p, 2p)}(({\overline{k}}^p)^{\otimes 2p})^{op}=\La_{\overline{k}}(p, 2p).
	 \end{align} Assume that $p>2$. Since $\Lambda_{\overline{k}}(p, 2p)$ has finite injective dimension (as a left and as a right module), it follows by Lemma \ref{lemmainvarianceofinjectivedimension} that  $\Lambda_k(p, 2p)$ is Iwanaga-Gorenstein and $\findim \La_k(p, 2p)=\injdim \La_k(p, 2p)=\injdim \La_{\overline{k}}(p, 2p)=2p-4$.
\end{proof}

