\section{Basic properties of dipoles and potentials}\label{sec:basic}

The {\bf Green kernel} $\G_\o(x,y)$ of the random walk $\{X_n\}_{n \geq 0}$ killed at $\o$ is defined by
$$ \G_\o(x,y) := \sum_{n=0}^\infty \P_x( X_n = y, \,\, \tau_\o > n) \, ,$$
where $\tau_\o = \min\{ n \geq 0 : X_n = \o\}$. The corresponding {\bf Green density},  
\be \label{eq:greend}
{\sf g}_\o (x,y) = \frac{\G_\o(x,y)}{c_y} \, ,
\ee
is symmetric by reversibility. A {\bf dipole} from $\o$ to another vertex $y$ in a network $(G,c)$ is a function $f:V\to [0,\infty)$, for which $f(\o)=0$ and 
$$\forall v \in V \qquad \Delta f (v) = {\bf 1}_\o(v)  - {\bf 1}_y(v) \, .$$
%In a recurrent network, the Green density $g_o(\cdot,y)$ is the unique dipole from $\o$ to $y$, see \cref{claim:GreenIsDipole}. 

\begin{claim}\label{claim:GreenIsDipole} In a recurrent network, the Green density $g_\o(\cdot,y)$ for the killed random walk is the unique dipole from $\o$ to $y$. Moreover,  $\sup_y g_\o(x,y)<\infty$ for each $x \in V$.   
\end{claim}
\begin{proof}
First observe that $g_\o(\cdot,y)$ is harmonic off $\{\o,y\}$ and satisfies $\g_\o(\o, y)=0$. Second, $\Delta \g_\o(\cdot,y) (y) =-1$, since
\begin{equation} \label{eq:laplace-y}
     \sum_{x \sim y} c_{xy} (\g_\o(y,y)-\g_\o(x,y)) = \G_\o(y,y) - \sum_{x \sim y} {c_{xy} \over c_y} \G_\o(x,y) = 1 \, .
    \end{equation}
Also,
\be \label{eq:dipole11}  \Delta \g_\o(\cdot,y)(\o) = \sum_{x\sim \o}   c_{\o x} g_\o(x,y)= \sum_{x\sim \o} \G_o(y,x) \frac{c_{\o x}}{c_x} =1 \,,
\ee
where the last equality is obtained by summing, over  $n \ge 0$, the identity
$$
\sum_{x\sim \o}  \P_y( X_{n} = x  , \,\, \tau_\o > n)\frac{c_{\o x}}{c_x} =  \P_y( X_{n+1} = \o, \,\, \tau_\o > n)  = \P_y(   \tau_\o =n+1)  \, 
$$
and using recurrence. Thus, $g_\o(\cdot,y)$ is a dipole. 

Next, we verify uniqueness. For any dipole $f$ from $\o$ to $y$,  the difference
$f-g_\o(\cdot,y)$ is a harmonic function on $V$ that vanishes at $\o$ and is bounded below by $-\g_\o(y,y)$; therefore, it vanishes on $V$. 
%Thus the dipole from $\o$ to $y$ in a recurrent network is unique.

Lastly, the identity \eqref{eq:dipole11}  implies that $\g_\o(x,y) \le c_{ox}^{-1}$ for every $x \sim \o$. More generally, since $\g_\o(\cdot,y)$ is superharmonic off $\o$, for any $x \ne \o$ we have $\g_\o(x,y) \le \prod_{i=1}^\ell c_{x_{i-1}x_i}^{-1}$, where $x_0,\dots,x_\ell$ is a simple path from $\o$ to $x$. 
\end{proof}

\begin{claim}\label{claim:compact} The space of potentials on a recurrent rooted $(G,c,\o)$ is a nonempty, compact, convex subset of $\R^V$. Moreover, if there is a unique potential $h$, then $\g_\o(\cdot, y_n )$ converges to $h$ pointwise as $y_n\to \infty$.
\end{claim}
\begin{proof} 
By \cref{claim:GreenIsDipole}, for any sequence of vertices $y_n\to \infty$, Cantor diagonalization yields a subsequential pointwise limit of $\g_\o(\cdot, y_n )$, and any such limit is a potential.  Next, for any potential $h$ we have $h(x)\leq \prod_{i=1}^\ell c_{x_{i-1}x_i}^{-1}$, where $x_0,\dots,x_\ell$ is a simple path from $\o$ to $x$, by the argument in the proof of \cref{claim:GreenIsDipole}, so the set of potentials is a closed subset of a compact product set.
Finally, convexity and the last statement are obvious. 
\end{proof}



%We can infer the identity 
%\begin{equation} \label{dipolalt} g_y(\o,\o)-g_y(x,\o)=g_o(x,y)\,,
%\end{equation}
%since the left hand side is easily checked to also define a dipole from $\o$ to $y$.
\begin{remark} Conversely, if   $\g_\o(\cdot, y_n )$ converges pointwise as $y_n\to \infty$, then there is a unique potential; this follows from \cref{cor:PotentialsMixtureDipoles} below.
\end{remark}

Dipoles can be used to show that the uniqueness of the potential does not depend on the choice of  root in the network. 

\begin{claim}\label{claim:uniquenessDoesNotDependOnRoot} Let $(G,c)$ be a recurrent network. Fix two vertices $\o,\tilde{\o}$ and a function $h:V\to [0,\infty)$. Then $h$ is a potential for the network $(G,c,\o)$, if and only if the function
$$ \tilde{h}(\cdot) = h(\cdot) + \g_{\tilde{\o}}(\cdot,\o) - h(\tilde{\o}) \, ,$$
is a potential for $(G,c,\tilde{\o})$.
\end{claim}
\begin{proof} Assume that $h$ is a potential for $(G,c,\o)$. It is clear that $\tilde{h}(\tilde{\o})=0$ and
$$ \Delta \tilde{h}(\cdot) = {\bf 1}_\o(\cdot)+ {\bf 1}_{\tilde{\o}}(\cdot) -{\bf 1}_\o(\cdot)= {\bf 1}_{\tilde{\o}}(\cdot) \, .$$
Therefore $\tilde{h}(X_{\tau_v \wedge t})$ is a martingale bounded below by $-h(\tilde{\o})$. For each $x\in V$, by Fatou's lemma and recurrence
$$ \tilde{h}(x) = \lim_{t\to \infty} \E_x [ \tilde{h}(X_{\tau_{\tilde{\o}} \wedge t})] \geq  \E_x [\liminf _{t\to \infty} \tilde{h}(X_{\tau_{\tilde{\o}} \wedge t}) ] = \tilde{h}(\tilde{\o})=0 \, .$$
The other direction follows similarly.% using uniqueness of dipoles.
\end{proof}


\subsection{Basic properties of the $h$-process} \label{sec:basic-h}
Let $h:V\to [0,\infty)$ be a potential. Write $\P^h_\mu$ for the distribution of the $h$-process with initial distribution $\mu$ and $\E^h_\mu$ for the corresponding expectation. Next, we relate the Green kernels of the $h$-process and the network random walk killed at $\o$.  For any finite sequence $\gamma=(v_0,v_1,\ldots,v_k)$   in $V$, we write 
$\P_{v_0}(\gamma):=\prod_{i=1}^k p(v_{i-1},v_i) \,.$
If $\gamma$ is contained in $S_h$, we define 
$\P^h_{v_0}(\gamma)$  similarly using $p^h(v_{i-1},v_i)$. We have the telescoping product
\be \label{eq:hprocessvsSRWSimple} \P^h_{v_0}(\gamma) = \P_{v_0}(\gamma) h(v_k) /h(v_0) \, .\ee
We will use the initial distribution $\mu_h$ defined in \eqref{def:mu}. 
%$$ \mu_h(v) = c_{\o v} h(v) \, .$$
We have
\be \label{eq:hprocessvsSRW} \P^h_{\mu_h} (\gamma) = c_{\o v_0} h(v_0) \P^h_{v_0}(\gamma) =  c_{\o v_0} \P_{v_0}(\gamma) h(v_k) = c_\o \P_\o(\o\gamma) h(v_k)  \, .\ee


\begin{remark}\label{rmk:Sh} By harmonicity of $h$ in $V\setminus \{o\}$, the set $S_h$ is a union of connected components of $V\setminus \{\o\}$ in $G$.    
\end{remark}


\begin{claim} \label{claim:GhMu} Let $h$ be a potential on a recurrent rooted network $(G,c,\o)$. Then the $h$-process   $\{Y_n\}_{n \geq 0}$ is transient. Moreover,  its Green kernel $\G^h(x,y)=\sum_{k \geq 0} \P^h_x( Y_k = y) $, defined for $x,y\in S_h$, satisfies
\be\label{eq:XvsY} \G^h(x,y) = \G_\o(x,y) \frac{h(y)}{h(x)} \, ,\ee
and for all $v\in S_h$
\be\label{eq:Gh} \G^h({\mu_h},v) = h(v) c_v \, ,\ee
where $\G^h({\mu},v):=\sum_x \mu(x) \G^h(x,v)$.


\end{claim}
\begin{proof} Transience will follow    once we show $G^h(x,y)<\infty$. To prove \eqref{eq:XvsY}, we sum \eqref{eq:hprocessvsSRWSimple}  over all paths from $x$ to $y$ that avoid $\o$. Note that by \cref{rmk:Sh}, any such path is contained in $S_h$. Next, \eqref{eq:Gh} follows from \eqref{eq:XvsY} by
$$ \G^h({\mu_h},y) =\sum_v c_{\o v} h(v) \G^h(v,y) = h(y) \sum_v c_{\o v} \G_\o(v,y) = h(y) c_y \, ,$$ using \eqref{eq:dipole11} and the symmetry of $\g_\o(\cdot,\cdot)$ in the last step.
\end{proof}

\begin{claim}\label{lem:hProcessInfty} Let $h$ be a potential for a  recurrent rooted network $(G,c,\o)$ and consider the $h$-process $\{Y_n\}$ started at $v \in S_h$. Then for every $M >0$, 
$$ \P^h_v \big( h(Y_\ell) >M \bigr) \to 1 \quad \text{as} \quad \ell \to \infty \, .$$
\end{claim}
This was also observed in \cite[Lemma 5]{EngelHutch}. 
\begin{proof}
   Recall that $\{X_n\}$ is the network random walk. By \eqref{eq:hprocessvsSRWSimple}, we have 
   $$\P_v^h\big( h(Y_\ell) \le M \bigr)=\E_v\Bigl[\frac{h(X_\ell)}{h(v)} \, {\bf 1}_{\{h(X_\ell) \le M \; \, \text{and} \; \,\tau_\o  \ge \ell\}}  \Bigr] \le \frac{M}{h(v)} \, \P_v( \tau_\o  \ge \ell) \,,$$  
   which tends to $0$ as $\ell \to \infty$ by  recurrence. 
\end{proof}


% By \eqref{eq:hprocessvsSRWSimple},  for every  $x,y \in S_h$ we have
% \be\label{eq:XvsY} \P^h_x(Y_k=y) = \P_x(X_k = y, \tau_\o > k) \frac{h(y)}{h(x)}\, , \quad \textrm{whence}  \quad \G^h(x,y) = \G_\o(x,y) \frac{h(y)}{h(x)} \, .\ee


Every potential $h$ on a recurrent network is unbounded; indeed, if $\{X_n\}$ is the network random walk, then $\{h(X_n)\}$ is a submartingale that does not converge. However, the gradient of a  potential on each edge is bounded by the edge resistance, as the next lemma shows. 

% the difference on each edge 

% every potential has bounded  difference  is bounded by the edge resistance. %See [***] for an improvement.
\begin{lemma}\label{lem:lipschitz1} Every potential $h$ on a recurrent rooted network $(G,c,\o)$,  satisfies
$$ |h(x)-h(y)|\leq r_{xy} \, ,$$
for every edge $\{x,y\}\in E$, where $r_{xy}={1 \over c_{xy}}$ are edge resistances.
\end{lemma}
\begin{remark} We will prove a stronger statement in \cref{cor:PotentialLipschitz}, but we find the proof of \cref{lem:lipschitz1} too enjoyable to omit.
\end{remark}
\begin{proof} 
% By summing \eqref{eq:hprocessvsSRW} over all paths $\gamma$ from $\o$ to $v$ that do not return to $\o$ we obtain
% \be\label{eq:hVisitV} \P^h(X_k = v) = \P(X_k = v, \tau_{\o}>k) h(v) c_\o \, .\ee
% In any recurrent Markov chain, the function 
% $$ \pi(v) = \sum_k \E_\o[ X_k =v, \tau_\o>k] \, ,$$
% is a stationary measure with $\pi(\o)=1$. Since the network  is connected (i.e., the Markov chain is irreducible) the stationary measure is unique up to multiplying by a constant. Therefore the aforementioned $\pi(v)$ equals $c_v/c_\o$. Hence by summing over $k$ in \eqref{eq:hVisitV} we get that 
% $$ \G^h({\mu_h},v) = h(v) c_v \, .$$
By \cref{claim:GhMu}, for any $v,w\in S_h$ with $\{v,w\}\in E$, we have
$$ \G^h({\mu_h},v) p^h(v,w) = h(v) c_v {h(w) c_{v w} \over h(v) c_v } = h(w) c_{vw} \, .$$
The left hand side of the equality above is the expected number of crossings $N(v,w)$ of the directed edge $(v,w)$ by $\{Y_n\}$. Hence the expected   \emph{net} number of  crossings of the directed edge $(v,w)$ (that is, $N(v,w)-N(w,v)$) equals $c_{vw}(h(w)-h(v))$. 

Next we observe that in a transient network, the expected net  number of  crossings of a directed edge by the network random walk equals the expected net  number of crossings of the same edge by the loop-erased random walk (started at the same initial distribution) because each cycle of the simple random walk has equal probability of being traversed forward or backward.  Since the net number of   crossings of any edge by the loop erased random walk is $-1$, $0$ or $1$, we conclude that $c_{vw}|h(v)-h(w)|\leq 1$. \end{proof}


\subsection{Obtaining potentials from exhaustions}
Another way to generate potentials uses an {\bf exhaustion} of $G$, that is, a sequence of finite sets $\{D_n\}$ such that $o\in D_n$ and $D_n \subset D_{n+1}$, that satisfy $\cup_n D_n = V$. For each $n$, let 
$$\G_n(x,y)=  \sum_{k\geq 0} \P_x(X_k=y, \tau_{D_n^c} > k) \, $$ be the Green kernel of the random walk killed upon exiting the set $D_n$, and write $\g_{n}(x,y)=c_y^{-1} \G_n(x,y)$. The function
\be\label{def:hn} h_n(x) = \g_{n}(\o,\o) - \g_n(x,\o)=\P_x(\tau_{D_n^c} <\tau_\o)\, \g_{n}(\o,\o) \, ,\ee
is harmonic in $D_n \setminus \{\o\}$. It takes the value  $0$ at $\o$, and the value $\g_n(\o,\o)$ at any $x\in V\setminus D_n$. Furthermore, 
$$ \Delta h_n(\o)=\sum_{x \sim \o} c_{\o x} h_n(x) = \sum_{x \sim \o} p(\o,x) [\G_n(\o,\o) - \G_n(x,\o)] = \G_n(\o,\o) - \E_\o \G_n(X_1,\o) = 1\, .$$
Hence, any subsequential point-wise limit of $\{h_n\}$ is a potential. Next we prove a converse for networks with bounded edge resistances. %show that for networks with bounded 






%, to each associate the unit current flow $i_n$ from $o$ to $\partial G_n$, then take a subsequential limit $i_{n_k}$ which converges on every edge $e$ (the latter step is possible since $i_n$ is $1$-Lipschitz). It turns out that any potential can be obtained this way as we now show.

%To any finite connected set $A$ which contains $\o$ we write $h_A:V\to \RR$ for the unique function which is harmonic on $A\setminus\{o\}$ and takes the values $h(o)=0$ and $h(\partial A)=\Reff(o\lr \partial A)$, where $\partial A$ is the set of vertices in $V\setminus A$ which have a neighbor in $A$.

\begin{lemma}\label{lem:exhaustion} Let $(G,c,\o)$ be a recurrent     rooted network. Assume that the edge resistances are bounded,
$R:=\sup_{e\in E}  r_e <\infty$, and let $h$ be a potential. Then there exists an exhaustion $\{D_n\}$ of $G$ such that 
$$ \forall  v\in V, \quad h(v) = \lim_{n\to \infty} h_{n}(v) \, ,$$
where $h_n$ are defined in \eqref{def:hn}.
\end{lemma}
\begin{proof} By recurrence, for each $n$ we can choose a ball $B_n$ centered at $\o$ of large enough radius, such that  
$$\P_\o( \tau_{B_n^c} < \tau_\o^+) \leq  \frac{1}{c_\o n^2}   \, .$$
Define
$$ D_n := \{ v \in B_n : h(v) \leq n\} \quad \text{and} \quad  \tau := \tau_\o^+ \wedge \tau_{D_n^c} \,.$$
 Start the network random walk at  $X_0=\o$, and consider the martingale
$M_t:=c_\o h(X_{\tau \wedge t })+{\bf 1}_{\{t=0\}}$ which is bounded by \cref{lem:lipschitz1}. Optional stopping yields
$$1=M_0=\E_\o M_{\tau} \ge  \P_\o\big(h(X_\tau) > n\big)c_\o n   \, ,$$
and by  \cref{lem:lipschitz1},
$$1=M_0=\E_\o M_{\tau} \le \P_\o(X_\tau \in D_n^c) c_\o (n+R)\,. $$

Thus,
$$\frac{1}{c_\o(n+R)} \le \P_\o(X_\tau \in D_n^c) \le \P_\o\big(h(X_\tau) > n\big) + \P_\o( X_\tau \in B_n^c) \le  \frac{1}{c_\o n}+\frac{1}{c_\o n^2}=\frac{n+1}  {c_\o n^2} \,.$$
Since the number of visits to $o$ by the random walk is a geometric random variable,
\be\label{eq:gnooBound} 
n+R \geq g_n(\o,\o)=\big(c_\o \P_\o(X_\tau \in D_n^c)\big)^{-1}  \ge \frac{n^2}{n+1} \ge n-1\,. \ \ee

Fix $v \in V$ of graph distance $\ell$ from $\o$, so that $p^\ell(\o,v) >0$. Suppose that $n$ is large enough so  that  $D_n$ contains the shortest path from $\o$ to $v$.  
Observe that
\be \label{eq:vbnd} {1 \over c_\o n^2} \geq \P_\o(X_\tau \in B_n^c) \geq p^\ell(\o,v) \P_v(X_\tau \in B_n^c)\, . 
\ee
Applying optional stopping 
to the bounded martingale $h(X_{t \wedge \tau})$
%where we take $X_0=v$, 
gives
\be \label{eq:simpopt} h(v)= \E_v(h(X_\tau)) \ge n \P_v(h(X_\tau) > n)   \,. 
\ee
Finally, consider  the bounded martingale
$$\Gamma_t:=h(X_{t \wedge \tau})-h_n(X_{t \wedge \tau}) \,,$$
where we take $X_0=v$. Observe that for $x \in V \setminus D_n$ that has a neighbor in $D_n$,  we have that $h(x) \le n+R$ by \cref{lem:lipschitz1}, and  $h_n(x) =\g_n(\o,\o) \in [n-1,n+R]$ by \eqref{def:hn} and \eqref{eq:gnooBound}. Therefore,
\begin{eqnarray*} |h(v)-h_n(v)|=|\Gamma_0|=|\E_v(\Gamma_\tau)| &\le& (R+1)\,\P_v(h(X_\tau) > n)+(n+R)\, \P_v(X_\tau \in B_n^c) \\[1ex]  &\le& \frac{(R+1) h(v)}{n} +\frac{(n+R) } {p^\ell(\o,v) c_\o n^2} \, ,\end{eqnarray*}
using  \eqref{eq:vbnd} and \eqref{eq:simpopt} in the last step. This concludes the proof.
