\end{proof}

\begin{cor} \label{cor:exhaustion} In the setting of \cref{lem:exhaustion}, the network random walks started at $v_1\in S_h$ conditioned to exit $D_n$ before reaching $\o$, converge weakly to the $h$-process as $n\to \infty$.
\end{cor}
\begin{proof} Let $\gamma=(\gamma_1,\dots,\gamma_\ell)$ be a path in $S_h$ with $\gamma_1=v_1$. 
Then
$$ \P_{v_1}(\gamma \mid \tau_{D_n^c} < \tau_{\o}) = \P_{v_1}(\gamma) {h_n(\gamma_\ell) \over h_n(\gamma_1)} \to \P^h(\gamma) \, ,$$
as required.    
\end{proof}


Next we improve \cref{lem:lipschitz1}, replacing edge resistances by \emph{effective resistances}. For background on effective resistance see \cite[Chapter 2]{TheBook}. In recurrent networks, one can define the effective resistance $\Reff(x \lr y)$ between two vertices $x\neq y$ as
$$ \Reff(x \lr y) = \g_x(y,y) = \bigl(c_y P_y(\tau_x <\tau_y^+)\bigr)^{-1} \, .$$
%The symmetry of $\Reff(x \lr y)$ then follows from the RHS of the above via path reversal. 

\begin{lemma}\label{lem:1LipschitzReff} Let $(G,c,\o)$ be a rooted network (not necessarily recurrent). Assume that $D\subset V$ satisfies $\o\in D$ and $\P_\o(\exists n \, \, X_n \not \in D)=1$. Then the Green density $\g_{D^c}(\cdot,\o)$ of the random walk killed upon exiting $D$ is $1$-Lipschitz with respect to the effective resistance metric, that is, %for any $x,y\in D$
$$ \forall \, x,y\in D \qquad |\g_{D^c}(x,\o) - \g_{D^c}(y,\o)| \leq \Reff(x \lr y) \, .$$
\end{lemma}
\begin{proof} For the random walk $\{X_n\}$ started at $x$, we have
$$ \sum_{t=0}^{\tau_{D^c}} {\bf 1}_{\{X_t = \o\}} \leq \sum_{t=0}^{\tau_{y}} {\bf 1}_{\{X_t = \o\}} + \sum_{t=\tau_y}^{\tau_{y} \vee \tau_{D^c}} {\bf 1}_{\{X_t = \o\}} \, .$$
Taking expectations and using the strong Markov property gives
$$ \G_{D^c}(x,\o) \leq \G_y(x,\o) + \G_{D^c}(y,\o) \, ,$$
which dividing by $c_\o$ yields
$$ \g_{D^c}(x,\o) \leq \g_y(x,\o)+ \g_{D^c}(y,\o) \, .$$
Hence
$$ \g_{D^c}(x,\o) - \g_{D^c}(y,\o) \leq \g_y(x,\o) = \g_y(\o,x) \leq \g_y(x,x) = \Reff(x \lr y) \, ,$$
giving the desired result by interchanging the roles of $x$ and $y$.
\end{proof}

\begin{cor}\label{cor:PotentialLipschitz} Let $(G,c,\o)$ be recurrent rooted network and let $h:V\to [0,\infty)$ be a potential. Then
$$ \forall \, x,y\in D \qquad |h(x)-h(y)| \leq \Reff(x \lr y) \, .$$
\end{cor}
\begin{proof} If the edge resistances are bounded, then this follows directly from Lemmas \ref{lem:exhaustion} and \ref{lem:1LipschitzReff}. Otherwise, we consider the enhanced network $(G^*, c^*) = (V^*, E^*, c^*)$ where $V\subset V^*$ and every edge $e\in E$ with $r_e>1$ is split into $\lceil r_e \rceil$ edges of resistance $r_e/\lceil r_e \rceil$. Observe that for every $x,y\in V$, the effective resistance $\Reff(x \lr y)$ in $(G^*, c^*)$ equals the effective resistance in $(G, c)$. The potential $h$ has a unique extension to a potential $h^*$ on $(G^*, c^*)$ and the result follows from the case of bounded edge resistances.
\end{proof}
\begin{remark}
In the proof above, we could replace \cref{lem:exhaustion}  by     
\cref{cor:PotentialsMixtureDipoles} below.
\end{remark}

\begin{remark} \cref{cor:PotentialLipschitz} can also be obtained from \cite[Proposition 3.6]{BereEngel} together with \cite[Proposition 3.2 (ii)]{BereEngel}.
\end{remark}


\subsection{Preliminaries on transient chains}\label{sec:transient} Since the $h$-process is transient (\cref{claim:GhMu}), we present, following Dynkin \cite{Dynkin69}, a general property of transient chains.   Consider a transient Markov chain on a countable state space $S$ with transition probabilities $\q(x,y)$, and denote by $\G(x,y)$ the Green kernel
$$ \G(x,y) = \sum_{n=0}^\infty \q^n(x,y) \, .$$
Let $\mu$ be a finitely supported probability measure on $S$ representing the starting state for the chain. We write 
$$ \G(\mu,y) = \sum_{x \in S} \mu(x) \G(x,y)$$
and assume that $\mu$ satisfies
\be\label{def:standardMeasure} \G(\mu,y)>0  \hbox{  for all  } y\in S \, .\ee
The {\bf Martin kernel} $M(x,y)$ is now defined as 
\be\label{eq:MartinDef} M(x,y) := \frac{\G(x,y)}{\G(\mu, y)} \, .\ee
%Note that $M(\cdot, y)$ is harmonic off $y$. 
The strong Markov property implies that $\G(\mu,y)\geq \P_\mu(\tau_x < \infty) \G(x,y)$, hence
\be \label{eq:Minequality} M(x,y)  \leq \frac{1}{\P_\mu(\tau_x < \infty)} = \frac{\G(x,x)}{\G(\mu,x)} \, .\ee

 Let $D \subset V$ be a finite set and let $L_D$ be the last visit to $D$, that is,
$$ L_D := \sup \{\, n \geq 0 :  Y_n \in D\,  \} \, ,$$
with $L_D:=-\infty$ when this set is empty. Clearly, $\P_x(L_D < \infty)=1$ for any $x\in S$. 

\begin{lemma}\label{lem:ExpectationEq1}  Let $x\in S$ and let $D \subset S$ be a finite set with $x \in D$ and $\mu(D)=1$. Then writing $L=L_D$ we have
$$ \E_\mu [ M(x, Y_{L})] = 1 \, .$$
\end{lemma}
\begin{proof} For any $y\in D$ and $k\geq 0$, we have
$$ \P_x(Y_L = y, L=k) = q^k(x,y) \P_y(L=0) \, .$$
Therefore
$$ \P_x(Y_L=y) = \G(x,y) \P_y(L=0) \, ,$$
whence
\be\label{eq:exit2}
\P_\mu(Y_L=y) = \G(\mu,y) \P_y(L=0) \, .\ee
Thus 
$$ M(x,y) = \frac{\P_x(Y_L=y)}{\P_\mu(Y_L=y)} \, ,$$
provided that $\P_\mu(Y_L=y)>0$. We conclude that 
$$ \E_\mu [M(x,Y_L)] = \sum_{y\in D} \P_\mu(Y_L=y) M(x,y) = \sum_y \P_x(Y_L=y) = 1 \, .$$
\end{proof}



\subsection{Representing potentials as mixture of dipoles}

The next theorem shows that every potential, when restricted to a finite set of vertices $D$ containing the neighbors of $\o$, is a mixture of dipoles $\g_\o(\cdot,v)$ with $v\in D$. 

\begin{thm}\label{cor:PotentialsMixtureDipoles} Let $h$ be a potential for a  recurrent rooted network $(G,c,\o)$. Let $\{Y_n\}_{n \ge 0}$ be the corresponding $h$-process with initial distribution $\mu_h$ defined in \eqref{def:mu}. Let $D\subset V$ be a finite set containing $\o$ such that $\mu_h(D)=1$.  Then for all $x\in D$, we have
\be\label{eq:PotMixture} h(x) = \E_{\mu_h} \g_o(x, Y_L) \, ,\ee
where $L=L_D := \sup \{\, n \geq 0 :  Y_n \in D\, \}$.
\end{thm}


\begin{proof}[Proof of \cref{cor:PotentialsMixtureDipoles}.]
If $x\not\in S_h$, then both sides of \eqref{eq:PotMixture} vanish by \cref{rmk:Sh}. Therefore we may assume that $x\in D \cap S_h$. For all $y \in S_h$ we get from 
  \eqref{eq:XvsY} that $\g^h(x,y)=\g_\o(x,y)h(y)/h(x)$,  and  \cref{claim:GhMu} yields $\g^h(\mu_h,y)=h(y)$.
Thus  \cref{lem:ExpectationEq1}, applied to $D\cap S_h$ (instead of $D$),   implies that
$$1=\E_{\mu_h} \left [ {\g^h(x, Y_{L})\over \g^h(\mu_h,Y_{L})} \right ] = \E_{\mu_h}\left [ {\g_\o(x, Y_{L}) \over h(x)} \right ]\, .$$
\end{proof}

In the next claim, we show that the time reversal of an $h$-process,  run until it exits a finite set, is a network random walk stopped at $o$. This has an application to harmonic measure from infinity (\cref{cor:ExitMeasureHarmonicMeasure}) and to uniform spanning trees, see \cref{lem:Not1Ended}.
\begin{claim}\label{claim:HUntilExit} In the setup of \cref{cor:PotentialsMixtureDipoles}, let $\nu_D$ be the law of $Y_{L}$. Then $(Y_L,\ldots,Y_0,\o)$ has the law of the network random walk with initial distribution $\nu_D$, stopped at $\o$. 
\end{claim}

\begin{proof} We have to show that for any finite path $(v_0, v_1,\ldots,v_\ell)$ in $S_h$, 
\be \label{eq:leftright} \P_{\mu_h}^h\Big ((Y_0,\ldots,Y_L)=(v_0,\ldots,v_\ell)\Big ) = \P_{\nu_D}\Big ((X_0,\ldots,X_{\tau_\o})=(v_\ell,\ldots,v_0,\o)\Big ) \, .
\ee
We write the left hand side using \eqref{eq:hprocessvsSRW} as
$$ c_\o p(v_\o,\o) \Big [ \prod_{i=1}^{\ell} p(v_{i-1},v_i)\Big ]h(v_\ell) \P^h_{v_\ell}(L=0) \, .$$
On the other hand, using \eqref{eq:exit2} from the proof of \cref{lem:ExpectationEq1} and \cref{claim:GhMu}, we deduce that the right hand side of \eqref{eq:leftright} equals
$$ h(v_\ell)c_{v_\ell}\P^h_{v_\ell}(L=0) \prod_{i=0}^{\ell-1} p(v_{\ell-i},v_{\ell-i-1}) p(v_\o,\o) \, .$$
Thus the two sides of \eqref{eq:leftright} are equal by reversibility.    
\end{proof}


