\section{Harmonic measures from infinity}\label{sec:Harmonic}

Given a recurrent network $(G,c)$, a finite set $A\subset V$ and a vertex $v$, the {\bf harmonic measure} from $v$ on $A$ is 
$$ \omega_v^A(z) := P_v(X_{\tau_A} =z) \, ,$$
for any $z\in A$. We say that $A$ admits {\bf harmonic measure from infinity} if the limit $\omega_\infty^A(z) = \lim _{v \to \infty} \omega_v^A(z)$ exists for all $z\in A$. 
If this holds for all finite $A \subset V$, then we say that the network $(G,c)$ admits {\bf harmonic measures from infinity}. The following criterion is often useful.

\begin{claim} \label{clm:HarmCriterion}
A recurrent network $(G,c)$ admits harmonic measures from infinity, if and only if there exists a vertex $\o \in V$ and an exhaustion $\{D_n\}$ of $G$ with $o \in D_n$ for all $n$ such that 
%for each $n$ and every two vertices $v_1,v_2 \in \partial B_G(\o,r_{n+1})$, 
 the harmonic measures satisfy
$$q:=\sup_n \max_{v_1,v_2 \in  \partial D_{n+1}} \|\omega_{v_1}^{\partial D_n}-\omega_{v_2}^{\partial D_n}\|_{{\rm TV}}<1 \, .$$

% $$q:=\sup_n \max_{v_1,v_2 \in  \partial B_G(\o,r_{n+1})} \|\omega_{v_1}^{B_G(\o,r_n)}-\omega_{v_2}^{B_G(\o,r_n)}\|_{{\rm TV}}<1 \, .$$
\end{claim}
\begin{proof} 
Given a finite set $A \subset V$,
find $k$ such that $A \subset D_k$ and observe inductively that for each $n\geq 1$ and $v_1, v_2 \notin D_{n+k}$, we have  $$\|\omega_{v_1}^{\partial D_k}-\omega_{v_2}^{\partial D_k}\|_{{\rm TV}} \le q^n \,, \quad \text{whence} \quad
 \|\omega_{v_1}^{A}-\omega_{v_2}^{A}\|_{{\rm TV}} \le q^n \,. $$ 
\end{proof}


\begin{thm} \label{thm:PotentialHarmonicMeasure} A recurrent network $(G,c,\o)$ has a unique potential  if and only if every finite set $A\subset V$ admits harmonic measure from infinity. In this case, the unique potential $h$ and the collection of harmonic measures from infinity  on finite sets can be computed from each other as follows.
\begin{itemize} 
\item[{\rm (a)}] For all $z\in V\setminus\{\o\}$, we have $h(z) = \omega_\infty^{\{\o,z\}}(z) \g_\o(z,z)$. \vspace{2ex}

\item[{\rm (b)}]  If  $\o \in A$ and $z \in A \setminus\{\o\}$, then
$\displaystyle \omega_\infty^A(z) = \frac{\det(M^{h,z})}{\det(M)}$, where $M$ is the invertible matrix 
$M = \big ( \g_\o(x,y) \big )_{x,y \in A \setminus \{\o\}}$,
 and for every $z\in A\setminus\{\o\}$, the matrix
$M^{h,z}$ is  obtained from $M$ by replacing the  $z$-column   with the vector $(h(x))_{x\in A \setminus \{\o\}}$.

\item[{\rm (c)}]  If  $\o \notin A$, choose $\tilde{o} \in A$ and let $\tilde h$ be the unique potential for the rooted network
$(G,c, \tilde o)$, as in \cref{claim:uniquenessDoesNotDependOnRoot}.
To compute $\omega_\infty^A(\cdot)$, use (b) with $\tilde h$ instead of $h$. 
\end{itemize}
\end{thm}

\begin{remark} If $z$ is a vertex of $G$ such that there exists a network automorphism switching between $z$ and $\o$, then $\omega_\infty^{\{\o,z\}}(z)={1/2}$. For any such vertex $z$ we deduce from part (a) of the theorem above that $h(z) = \g_\o(z,z)/2$. In the particular case of $\mathbb{Z}^2$ this is contained in Proposition 4.4.1 of \cite{LawlerLimic}.
\end{remark}
\begin{remark}
Part (b) of the theorem above follows  \cite[Chapters 11 and 14]{Spitzer}.
\end{remark}


To prove this theorem, we first relate  harmonic measure  from a vertex to dipoles.

\begin{lemma}\label{lem:HarmonicMeasureDipoles}Let $(G,c,\o)$ be a recurrent rooted network and let $A \subset V$ be a finite set containing $\o$ with $|A|\geq 2$. Denote by $M$ the square matrix 
$$ M = \big ( \g_\o(x,y) \big )_{x,y \in A \setminus \{\o\}} \, .$$
Then $M$ is invertible. Moreover, for every $v\neq \o$ and $y\in A$,
$$ \omega_v^A(y) = \frac{\det(M^{v,y})}{\det(M)}\, ,$$
where $M^{v,y}$ is the matrix 
obtained from $M$ by replacing the $y$-th column with the vector $(\g_\o(x,v))_{x\in A \setminus \{\o\}}$.
\end{lemma}
\begin{proof} First entrance decomposition gives that for every $y\in A\setminus \{o\}$, 
$$ \g_\o(v,y) = \sum_{x \in A \setminus \{\o\}} 
\omega_v^A(x) \g_\o(x,y) \, .$$
We first show that $M$ is invertible. Indeed, suppose that the coefficients $\lambda_x$ satisfy $\sum_{x \in A \setminus \{o\}} \lambda_x \g_\o(x,y) = 0$ for all $y\in A \setminus \{\o\}$. Define $\psi:V \to \RR$ by
$$ \psi(y) := \sum_{x \in A \setminus \{o\}} \lambda_x \g_\o(x,y) \, .$$
Then $\psi$ is bounded, harmonic off $A$ and vanishes on $A$. Hence by recurrence $\psi \equiv 0$. On the other hand, for all $y\in A \setminus \{\o\}$ we have
$$ \Delta \psi (y) = -\sum_{x \in A \setminus \{o\}} \lambda_x {\bf 1}_x(y) = -\lambda_y \, ,$$
hence $\lambda_y=0$. The result now follows from Cramer's rule.
\end{proof}

\begin{remark} In particular, when $A=\{\o,y\}$, we get
\begin{equation} \label{eq:2PtsA}
    \omega_v^A(y) = \frac{\g_\o(v,y)}{\g_\o(y,y)} \, ,
\end{equation} 
which is also easy to verify directly. 
\end{remark}



\begin{proof}[Proof of \cref{thm:PotentialHarmonicMeasure}] Assume first that there exists a unique potential $h$. Then $h(x) = \lim_{v\to \infty} \g_\o(x,v)$, hence (b) follows from \cref{lem:HarmonicMeasureDipoles} and in particular it shows that every finite set admits harmonic measure from infinity. Furthermore, (a) follows from \eqref{eq:2PtsA}. 

Conversely, assume that every finite set admits harmonic measure from infinity. By \eqref{eq:2PtsA} we deduce that $\g_\o(v,y)=\g_\o(y,v)$ converges as $v\to \infty$ for any $y \in V$. By taking an exhaustion by finite sets $\{D_n\}_{n \geq 1}$, \cref{cor:PotentialsMixtureDipoles} implies there is a unique potential given in (a). \end{proof}

Combining the preceding theorem with the path reversal claim (\cref{claim:HUntilExit}) yields the following folklore corollary.

\begin{cor}\label{cor:ExitMeasureHarmonicMeasure} Let $(G,c,\o)$ be a recurrent network with a unique potential $h$ and $A\subset V$ a finite set so that $\mu_h(A)=1$. Then the last exit distribution $\nu_A$ of the $h$-process on $A$ equals the harmonic measure from infinity on $A$. 
\end{cor} 
\begin{proof} Let $\{Y_n\}$ be the $h$-process started, as usual, from the initial distribution $\mu_h$ and let $D$ be any set containing $A$. By \cref{claim:HUntilExit}, the reversed path $(Y_{L_D},\ldots,Y_0,\o)$ is distributed as network random walk starting from $\nu_D$ and stopped at $\o$. The first vertex in $A$ on this reversed path is $Y_{L_A}$ which has law $\nu_A$.  
%the harmonic measure from $\nu_{D}$ on $A$ equals $\nu_A$. 
Taking $D$ to be a ball of radius $R$ tending to infinity, it follows that harmonic measure from infinity on $A$ also equals $\nu_A$.
\end{proof}

% \begin{remark}\label{rmrk:cool1} 
%  \cref{cor:ExitMeasureHarmonicMeasure} implies that when the potential $h$ in a rooted network is unique, the last exit distribution $\nu_A$ of a set $A \subset V$ does not depend on the choice of root, as long as the potential $h$ is adjusted according to \cref{claim:uniquenessDoesNotDependOnRoot} and all neighbors of the root are in $A$.
% \end{remark}

\begin{remark}\label{rmrk:cool2} Let $\{Y_n\}$ be the $h$-process in a recurrent rooted network with a unique potential $h$. Motivated by the preceding corollary, we define the {\bf random walk from infinity to $\o$} in this network to be the process
$\{\widetilde{Y}_{k}\}_{k=-\infty}^0$, where $\widetilde{Y}_{k}:=Y_{-k}$ for $k < 0$. \cref{cor:ExitMeasureHarmonicMeasure} implies that for every finite set $A \subset V$ that contains all neighbors of $\o$,
  harmonic measure from infinity on $A$ is the law of $\widetilde{Y}_{\tau}$, where $\tau :=\min\big\{k<0: \widetilde{Y}_{k} \in A\big\}$.
\end{remark}


In a rooted network that admits a unique potential $h$, we can give a short proof that $h$ tends to infinity, using \cref{cor:ExitMeasureHarmonicMeasure} and \cref{thm:PotentialHarmonicMeasure}. Berestycki and van Engelenburg \cite[Proposition 5.1]{BereEngel} proved this in the special case of unimodular random graphs and asked whether \cref{thm:unique} holds. 

\begin{cor}\label{thm:unique} Let $(G,c,\o)$ be an infinite, connected, locally finite recurrent rooted network that has a unique potential $h$. Then $h$ tends to infinity, i.e., for every $b>0$, the set $\{v \in V : h(v) \leq b\}$ is finite.
\end{cor}

\begin{remark}
    This result is generalized in the next section. 
\end{remark}

\begin{proof}[Proof of \cref{thm:unique}.]
 We will assume that for some $b>0$, there is a sequence $v_n\to \infty$   such that $h(v_n) \leq b$ and obtain a contradiction. By \cref{lem:hProcessInfty}, if $A$ is a large enough ball around $\o$, then the last exit distribution $\nu_A$ of the $h$-process from $A$ satisfies 
\be\label{eq:nuA} \nu_A\Big ( \{ y \in A : h(y) \geq 4b \} \Big ) \geq 1/2 \, .\ee
Optional stopping for the positive martingale $h(X_{t \wedge \tau_A})$, where   $X_0=v_n$, gives 
$$b \ge h(v_n) \ge \E[h(X_{ \tau_A})] \ge 4b\P(h(X_{ \tau_A}\ge 4b))\,,$$
so
\be\label{eq:omega} \omega_{v_n}^A(\{ y \in A : h(y) \geq 4b \}) \leq 1/4 \, .\ee

By \cref{thm:PotentialHarmonicMeasure} the set $A$ admits harmonic measure from infinity, and by \cref{cor:ExitMeasureHarmonicMeasure} this measure equals $\nu_A$, so the measures
$\omega_{v_n}^A$ tend  to $\nu_A$ as $n \to \infty$. Comparing \eqref{eq:nuA} to \eqref{eq:omega} yields the desired contradiction. 
\end{proof}




\section{Existence of potentials tending to infinity} 
\label{sec:MainProof}

In 1936, G.C.~Evans \cite{Evans36} showed that every compact polar set $K$ in $\R^d$ supports a probability measure $\mu$ such that its Newtonian potential $h_\mu$ is infinite on $K$, see also \cite{Tsuji59}. Thus $h_\mu$ is a  harmonic function on $\R^d \setminus K$ that tends to infinity on every sequence converging to $K$. Using Evans' approach, Nakai \cite{Nakai62} proved that every parabolic noncompact Riemann surface $S$ admits a function $h: S \to [0, \infty)$ which is harmonic off a compact set and tends to infinity (i.e., its level sets $\{x \in S: h(x) \le M\}$ are compact). In Nakai's proof, the set $K$ is replaced by the Stone-\v Cech boundary of $S$. The discrete analog of these results is
\cref{conj:main}, which can also be found in our recent note~\cite{NP2025}.

We say that a function $h:V\to [0,\infty)$ {\bf tends to infinity} %and write  $h\to \infty$, 
if for all $M>0$, the set $\{ v \in V : h(v) \leq M \}$ is finite. Observe that on $\Z$, the potentials $h_1(n)=\max(n,0)$ for $n\in \Z$ and $h_2(n)=\max(-n, 0)$ do \emph{not} tend to infinity, but any non-trivial convex combination of them does. On $\Z^2$, on the other hand, it is  well known, see \cite[Sections 12 and 31]{Spitzer}, that there is a unique potential $h$ with $h(v) = \Theta(\log |v|)$ as $v \to \infty$. 

\begin{thm}\label{conj:main} On every recurrent rooted network $(G,c,\o)$, there exists a potential tending to infinity.
% has countably many extreme points $\{\psi_i\}_{i=1}^k$, then their average $\psi={1\over k}\sum_{i=1}^k\psi_i$ is a potential tending to $\infty$.
\end{thm}

\begin{remark}
The argument used by Nakai \cite{Nakai62} in the setting of Riemann surfaces can be adapted to prove \cref{conj:main}, but this argument is non-constructive.  Here we present a more constructive probabilistic approach, using the Von Neumann minimax theorem for finite zero sum games. In \cite{NP2025}, the Sion minimax theorem was used instead. 
\end{remark}

% \begin{thm}\label{conj:main} On any infinite, connected, recurrent rooted network, there exists a potential  which tends to infinity.
% \end{thm}


For any integer $R>0$, we set
$ \partial B(\o,R) = \{ w : d(\o,w)=R\} \, ,$
where $d(\cdot,\cdot)$ is the graph distance in $G$.

\begin{lemma}\label{lem:reduction1} Let $(G,c,\o)$ be a recurrent rooted network. Assume that for every $M>0$ there exists an integer $R>0$ and a potential $\psi=\psi_{M,R}$ such that $\psi(v) \geq M$ for any $v\in \partial B(\o,R)$.
Then there exists a potential $h$ that tends to infinity.
\end{lemma}
\begin{proof} First observe that for every $R$ and $M$, if $v \not \in B(\o,R)$, then $\psi(v)=\psi_{M,R}(v) \geq M$. Indeed, let $\{X_t\}$ be the network random walk started at $v$ and let $\tau_R$ be the hitting time of $\partial B(\o,R)$. Then $\psi(X_{t\wedge \tau_R})$ is a positive martingale, so by recurrence and optional stopping,
$$ \psi(v) \geq \E [ \psi(X_{\tau_R})] \geq M \, .$$
For $n\geq 1$, let $R_n$ and $\psi_n$ denote the radii and potentials corresponding to $M=n 2^n$ in the hypothesis of the lemma. By \cref{claim:compact},
$$ h := \sum_{n=1}^\infty 2^{-n} \psi_n$$
is a potential. Next, if $v\notin B(\o,R_n)$, then $h(v) \geq 2^{-n} \psi_n(v) \geq n$. Thus, $\{v : h(v) < n\}$ is finite for every $n$. 
\end{proof}

\begin{remark}\label{thm:conjectureOnTrees} In the particular case where the graph $G$ is a tree $T$, a potential tending to infinity can be constructed explicitly using the preceding lemma. Indeed, let $T_\infty\subset T$ be the union of all simple infinite paths emanating from the root. Let $M> 0$ be arbitrary. Given an integer $R>0$, let $\g_R(\cdot,\cdot)$ be the green density for the network random walk killed on the complement of the ball $B_R:=\{x \in T_\infty : d(x,\o)<R\}$. By recurrence of $T_\infty$, we can choose $R$ such that $\g_R(\o,\o)\geq M$. Set 
$$ \psi(x) = \g_R(\o,\o) - \g_R(x,\o) \, ,$$
for each $x\in B_R \cup \partial B_R$. We now extend $\psi$ to $T_\infty$ as follows. For each $v\in \partial B_R$ choose an infinite simple path $v=v_0, v_1,v_2,\ldots$ such that $v_1$ is contained in $T_\infty \setminus B$. Let $v_{-1}$ be the parent of $v$ in $T_\infty$. We  set $\psi(v_n)= \psi(v)+n(\psi(v)-\psi(v_{-1}))$ for all $n \ge 1$. We have defined $\psi$ on a subtree $T_\infty ' \subset T_\infty$ and we extend by projection: for any vertex $w\in T_\infty$ set $\psi(w)=\psi(w_*)$ where $w_*$ is the closest vertex to $w$ in $T_\infty'$. Thus $\psi$ is a potential on $T_\infty$ such that its values on $T_\infty \setminus B_{T_\infty}(\o,R)$ are larger than $M$. By \cref{lem:reduction1}, there exists a potential $h$ on $T_\infty$ which tends to infinity. We extend $h$ to $T$ by projection.
\end{remark}

For integer $r\geq 1$, let $\Upsilon_r$ be the simplex of probability measures on $\partial B_r$ and define
\begin{eqnarray*} V_1(\infty, r) &:=& \max _{\psi \in \pot} \min _{\eta \in \Upsilon_r} \psi \cdot \eta = \max _{\psi \in \pot} \min _{v \in \partial B_r} \psi(v) \, ,\\ 
V_2(\infty,r) &:=& \min _{\eta \in \Upsilon_r} \max_{\psi\in \pot} \psi \cdot \eta \, .\end{eqnarray*}
These can be interpreted as the values for players $1$ and $2$ of the zero-sum game where player $1$ selects $\psi\in \pot$, player $2$ selects $v\in \partial B_r$ and the payoff is $\psi(v)$. 

\begin{lemma} \label{lem:minimax} For each integer $r\geq 1$ 
$$ V_1(\infty,r) = V_2(\infty,r) \, .$$
\end{lemma}
As observed in \cite{NP2025}, this follows directly from Sion's minimax Theorem, but here we will derive it using approximation by finite games where the values can be calculated via linear programming. 



\begin{proof}[Proof of \cref{lem:minimax}] The inequality 
$V_1(\infty,r) \leq V_2(\infty,r)$ clearly holds. Fix $r\geq 1$. For each integer $R>r$, consider the game where player $1$ chooses $w\in \partial B_R$, player $2$ chooses $v \in \partial B_r$ and the payoff is $\g_\o(w,v)$. By von Neumann's minimax Theorem, the values 
\begin{eqnarray*} V_1(R, r) &:=& \max _{\zeta \in \Upsilon_R} \min _{v \in \partial B_r} \g_\o(v, \zeta) \quad \text{and}\\ 
V_2(R,r) &:=& \min _{\eta \in \Upsilon_r} \max_{w \in \partial B_R} \g_\o(\eta, w) \, \end{eqnarray*}
are equal. By \cref{cor:PotentialsMixtureDipoles}, for each potential $\psi$ and each $v\in \partial B_r$, we have 
$$ \psi(v) = \E _{\mu_\psi} \g_\o(v,Y_{L_R})  \, ,$$
where $L_R$ is the last exit time of the $\psi$-process $\{Y_n\}$ from $B_R \cup \partial B_R$. Thus, for any $\eta \in \Upsilon_r$ and $\psi \in \pot$, we have $\psi \cdot \eta \leq \max_{w \in \partial B_R} \g_\o(\eta,w)$. Hence by definition 
$$ V_2(\infty,r) \leq \max_{\psi} \psi \cdot \eta \leq \max_{w \in \partial B_R} \g_\o(\eta,w) \, ,$$
for any $\eta \in \Upsilon_r$. Minimizing over $\eta$ gives $V_2(\infty,r) \leq V_2(R,r)$. On the other hand, for each $R>r$ there exists $\zeta_R \in \Upsilon_R$ such that
$V_1(R,r) = \min_{v \in \partial B_r} \g_\o(v, \zeta_R)$. Pick a sequence of integer $R_n\to \infty$ such that  $\g_\o(\cdot,\zeta_{R_n})$ converge to a potential $h$, so $\lim_n V_1(R_n,r) = \min_{v\in \partial B_r} h(v)$. Hence
$$ V_2(\infty,r) \leq \lim_n V_2(R_n,r) = \lim_n V_1(R_n,r) = \min_{v\in \partial B_r} h(v) \leq V_1(\infty, r) \, .$$

\end{proof}

\subsection{Two lemmas from \cite{NP2025} on the $h$-process}
The first lemma shows that if a sequence of 
dipoles $g_\o(\cdot,v_n)$ converges pointwise to a potential $h$ as $v_n \to \infty$, then the network random walk from $\o$, conditioned to reach $v_n$ before returning to $\o$, converges weakly to the $h$-process. We prove this more generally, for mixtures of dipoles.
\begin{lemma} \label{lem:PathsConverge} Let $(G,c,\o)$ be a recurrent rooted network. Let $R_n\to \infty$ be sequence of integers and for each $n$ let $\eta_{R_n}$ be a probability measure supported on $\partial B(\o,R_n)$. Assume that the sequence $\g_\o(\cdot,\eta_{R_n})$ converges pointwise to a potential $h$ as $n\to \infty$. Then for any finite path $\gamma$ in $S_h$ starting at a neighbor of $\o$, we have
\be\label{eq:pathsConverge} \sum_{v} \eta_{R_n}(v) \P_\o( \o \gamma \mid \tau_{v} < \tau_\o^+) \longrightarrow \P_{\mu_h}^h(\gamma) \quad \text{as}    \quad n \to \infty \,.\ee


\end{lemma}
\begin{proof}
First note that for $v,w$ different from $\o$, we have
$\g_\o(w,v)=\P_w(\tau_v <\tau_\o)\g_\o(v,v)$ and  by path reversal,
$$ c_\o\P_\o(\tau_v <\tau_\o^+)= 
c_v \P_v(\tau_\o <\tau_v^+)= c_v \G_\o(v,v)^{-1} =\g_\o(v,v)^{-1}\,.$$
 Therefore, if $\gamma=(\gamma_1,\dots,\gamma_\ell)$   does not contain the vertex $v$, then  
 \be \label{dipoledoob}
\P_\o( \o \gamma \mid \tau_{v} < \tau_\o^+)=\P_\o( \o \gamma) \frac{ \P_{\gamma_\ell}(   \tau_{v} < \tau_\o) }{\P_{\o}(   \tau_{v} < \tau_\o^+)}=
c_\o \P_\o( \o \gamma)  \g_\o(\gamma_\ell,v) \,.
 \ee
Integrating this with respect $\eta_{R_n}$ gives
$$ \sum_v \eta_{R_n}(v)\P_\o( \o \gamma \mid \tau_{v} < \tau_\o^+) = c_\o \P_\o( \o \gamma)  \g_\o(\gamma_\ell,\eta_{R_n}) \to 
c_\o \P_\o( \o \gamma)  h(\gamma_\ell) \, ,$$
as $n \to \infty$ by our hypothesis. This yields the desired result by  \eqref{eq:hprocessvsSRW}. 
\end{proof}

Our second lemma is a simple combination of optional stopping and path reversal.  



\begin{lemma}\label{lem:dipolePotential}
Let $h$ be a potential for a  recurrent rooted network $(G,c,\o)$ and let $v\neq \o$ be a vertex. Then the network random walk $\{X_t\}$ satisfies 
$$ \P_\o( h(X_j) \geq M \mid \tau_v < \tau_\o^+) \leq {h(v) \over M} \, ,$$
for all $M>0$ and integer $0<j< d(\o,v)$.
\end{lemma}
\begin{proof} We may assume that $h(v)< M$. We have
\be\label{eq:beforeReversing}  \P_\o(h(X_j) \geq M \mid \tau_{v} < \tau_\o^+) \leq  \P_\o(T_{M} < \tau_{v} \mid \tau_{v} < \tau_\o^+) \, ,\ee
where $T_M = \inf \{t > 0: h(X_t) \geq M\}$. Recall that $c_\o\P_\o(\tau_{v} < \tau_\o^+) = {c_{v}}\P_{v}(\tau_\o < \tau_{v}^+)$ by path reversal. Similarly, 
$$c_\o \P_\o(T_{M} < \tau_{v} < \tau_\o^+) = c_v \P_{v}(T_{M} < \tau_{\o} < \tau_{v}^+) \, ,$$
so
$$\P_\o(T_{M} < \tau_{v} \mid \tau_{v} < \tau_\o^+) = \P_{v}(T_{M} < \tau_{\o} \mid \tau_{\o} < \tau_{v}^+) \, .$$
Consider the random walk started at $v$ and write $L = \max\{t < \tau_\o : X_t = v\}$. Then $X_{L},\ldots, X_{\tau_\o}$ is distributed as a random walk started at $v$, conditioned on $\tau_\o < \tau_{v}^+$, and stopped at $\o$. Hence
\be\label{eq:DPstep2} \P_{v}(T_M < \tau_{\o} \mid \tau_{\o} < \tau_{v}^+) = \P_{v}(\exists s\in (L,\tau_\o) : h(X_s)\geq M ) \leq \P_{v}(T_M < \tau_o) \, .\ee
To bound the last probability we note that $S_t=h(X_{t \wedge \tau_o})$ is a non-negative martingale, so by optional stopping
$$ h(v) =  \E_v S_0 \geq \E_v S_{T_M \wedge \tau_\o} \geq M \P_{v}(T_M < \tau_\o) \, .$$ 
Combining this with \eqref{eq:beforeReversing} and \eqref{eq:DPstep2} concludes the proof. \end{proof}

