\section{Convergence of dipoles along the $h$-process} \label{sec:convergence}


Given a sequence of vertices $y_n \to \infty$ in a recurrent rooted network $(G,c, \o)$, every subsequential pointwise limit of the dipoles $\g_\o(\cdot, y_n)$ is a potential. However, not every potential is a limit of dipoles; consider the potential $x \mapsto |x|/2$ on $(\mathbb Z, {\bf 1}, \o)$. It is well known that every potential is a limit of convex combinations of dipoles; see, e.g., \cref{cor:PotentialsMixtureDipoles}. 
Our next theorem provides a significant strengthening of this fact.


\begin{thm}\label{thm:convergence} Let $h$ be a potential on a recurrent rooted network $(G,c, \o)$, and let $\{\Y_n\}_{n \geq 0}$ be the $h$-process above with initial distribution 
\be\label{def:mu}\mu_h(v) = c_{\o v} h(v) \quad \text{for all} \; \; v \sim \o  \, .\ee Then almost surely, the dipoles $\g_\o(\cdot, \Y_n)$ converge pointwise to a random potential $H$,
$$ \g_\o(\cdot, \Y_n) \longrightarrow H(\cdot) \, ,$$
and $\E H(x) = h(x)$ for every $x\in V$. If $h$ is an extremal\footnote{$h$ is extremal if it cannot be represented as a non-trivial convex combination of potentials.} potential, then  $H=h$ almost surely.
\end{thm}

The following corollary shows the power of the almost sure convergence in the preceding theorem; convergence along a subsequence would not suffice.

\begin{cor}\label{cor:FiniteIntersection} Let $h_1$ and $ h_2$ be two distinct extremal potentials on a recurrent network $(G,c,\o)$ and let $\{Y_n\}_{n \geq 0}$ and $\{Z_n\}_{n \geq 0}$ be the $h_1$-process and $h_2$-process, respectively (no independence is assumed). Then their trajectories intersect finitely often a.s., that is, the set $\{ (m,n) : Y_m = Z_n \}$ is almost surely finite.
\end{cor}

\begin{proof} Let $x\in V$ be such that $h_1(x) \neq h_2(x)$.  By \cref{thm:convergence}, we almost surely have
$$ \g_\o(x, Y_n) \to h_1(x) \quad \text{and} \quad \g_\o(x, Z_n) \to h_2(x) \, .$$
Since  $\{Y_n\}$ and $\{Z_n\}$ are transient, the desired statement follows.
\end{proof}

The key to the proof of \cref{thm:convergence} is the following theorem on transient chains which is due to Doob \cite{Doob59} and Hunt \cite{Hunt60}. For completeness we provide its proof below, following the exposition by Dynkin~\cite{Dynkin69}. Another exposition can be found in Kemeny and Snell \cite{KemenySnell}. 
Recall the definition of the Martin kernel in \eqref{eq:MartinDef} from \cref{sec:transient}.

\begin{thm} \label{thm:dynkin} Let $\Y_n$ be a transient Markov chain governed by transition probabilities $\q$ and initial distribution $\mu$ satisfying \eqref{def:standardMeasure}. Then for every $x\in S$, the sequence $M(x, Y_n)$ converges almost surely as $n \to \infty$. Furthermore, $\E M(x,Y_n) \to 1$.
\end{thm}

\begin{remark} \cref{thm:dynkin} does not assume reversibility. 
\end{remark}





For the proof of \cref{thm:dynkin} it will be convenient to add a state $*$ to our state space and set  $M(x,*):=0$ for any $x\in S$. Furthermore, let $Y_{-k}:=*$ for $k>0$. Lastly, for a finite set $D\subset S$ with $\mu(D)=1$, we write $L=L_D$ for the last exit time from $D$ (recall that $L=-\infty$ if the chain never visits $D$).


\begin{lemma} \label{lem:independent} Let $D \subset S$ be a finite set with $\mu(D)=1$. Then the process $\{Y_{L-n}\}_{n\geq 0}$ has the Markov property with respect to the filtration 
\be \label{filter} 
\F_n = \sigma(Y_L, \ldots, Y_{L-n}) \, ,
\ee
that is,  %Then conditioned on $Y_{L-n}$ the random variables $Y_$
$$ \P_{\mu}(Y_{L-(n+1)}= z_{n+1} \mid \F_n) = \P_{\mu}(Y_{L-(n+1)}= z_{n+1} \mid Y_{L-n}) \, ,$$
for all $n\geq 0$ and $z_{n+1} \in S \cup \{*\}$.
\end{lemma}
\begin{proof} For any $z_0,\ldots, z_n\in S$ we have
\begin{eqnarray}\label{eq:long} \P_{\mu}(Y_{L-n}=z_n, \ldots, Y_L=z_0) &=& \sum_{\ell \geq n} \P_{\mu}(L=\ell,  Y_{\ell-n}=z_n, \ldots, Y_\ell=z_0)
\nonumber \\ &=& \sum_{\ell \geq n} q^{\ell-n}(\mu,z_n) q(z_n,z_{n-1})\cdots q(z_1,z_0) \P_{z_0}(L=0)\nonumber \\ &=& \G(\mu,z_n)  q(z_n,z_{n-1})\cdots q(z_1,z_0) \P_{z_0}(L=0) \, .
\end{eqnarray} Note that if $z_0\not\in D$, then both sides of the above vanish. When the right hand side of \eqref{eq:long} is non-zero, we can write the same formula  for $z_0,\ldots, z_{n+1}\in S$ and obtain that
\be\label{eq:cond1} \P_{\mu}( Y_{L-(n+1)}= z_{n+1} \mid Y_{L-n}=z_n, \ldots, Y_L=z_0 ) = \frac{\G(\mu,z_{n+1})q(z_{n+1},z_n)}{\G(\mu,z_n)} \, .\ee
If $z_0,\ldots ,z_n\in S$ and the expression in \eqref{eq:long} is nonzero but $z_{n+1}=*$, then the left hand side of \eqref{eq:cond1} equals $\mu(z_n)/\G(\mu,z_n)$. Lastly, if $z_0,\ldots, z_k\in S$ for $k<n$ but $z_{j}=*$ for $j\in [k+1,n]$, then the left hand side of \eqref{eq:cond1} equals $1$ if $z_{n+1}=*$ and $0$ otherwise.
\end{proof}

% \begin{claim}\label{claim:green}
% $$ \G(x,w) = {\bf 1}_{x=w} + \sum_z \G(x,z)q(z,w) $$
% \end{claim}
% \begin{proof} Sum over $m \geq 0$ the identity
% $$ q^{m+1}(x,w) = \sum_z q^m(x,z) q(z,w) \, .$$
