\section{Introduction} \label{sec:introduction}

\emph{Golden--Thompson trace inequality} \cite{Gol65, Tho65, FT14}, i.e., for Hermitian matrices $H,K$,
\begin{align} \label{eq:GT}
\Tr\left[ \mathrm{e}^{H+K} \right]
\leq \Tr\left[ \mathrm{e}^H \mathrm{e}^K \right],
\end{align}
% for Hermitian matrices $H$ and  $K$
% (where $\mathcal{M}_n(\mathds{C})$ be the algebra of $n\times n$ complex matrices),
and the \emph{Araki--Lieb--Thirrling inequality} \cite{LT76, Ara90}: for $A,B\geq 0$, %\in\mathcal{M}_n(\mathds{C})$,
\begin{align} \label{eq:ALT}
    \Tr\left[ \left( A^{1/2} B A^{1/2} \right)^r \right] 
    \leq \Tr\left[ A^{r/2} B^r A^{r/2} \right], \quad r\geq 1
    % \begin{cases}
    % \Tr\left[ \left( A^{1/2} B A^{1/2} \right)^r \right] 
    % \leq \Tr\left[ A^{r/2} B^r A^{r/2} \right], &r\geq 1
    % \\
    % \Tr\left[ \left( A^{1/2} B A^{1/2} \right)^r \right] 
    % \leq \Tr\left[ A^{r/2} B^r A^{r/2} \right], &r\leq 1
    % \\
    % \end{cases}
\end{align}
(the inequality reverses\footnote{In some literature, 
\eqref{eq:ALT} for $r\geq 1$ is called Lieb--Thirrling inequality \cite{LT76}, and the reversed inequality for $r\in[0,1]$ is sometimes called the Araki--Cordes inequality \cite{Ara90, Cordes87}. In this paper, we will use the term, Araki--Lieb--Thirrling inequality, referring to the inequality for all $r\geq 0$.}
for $r \in [0,1]$)
plays important roles in statistical mechanics, quantum information theory, and quantum computing.
For example, \eqref{eq:GT} implies that 
\begin{align}
D_{\alpha}(\rho\Vert\sigma):= \frac{1}{\alpha-1} \log \Tr\left[ \rho^{\alpha} \sigma^{1-\alpha} \right]
\leq
\frac{1}{\alpha-1} \log \Tr\left[ \e^{\alpha \log \rho + (1-\alpha) \log \sigma } \right] =: D_{\alpha}^{\flat}(\rho\Vert\sigma), \quad \forall \alpha \in (0,1),
\end{align}
where $D_{\alpha}(\rho\Vert\sigma)$ is the Petz--R\'enyi divergence \cite{Pet86}, $D_{\alpha}^{\flat}(\rho\Vert\sigma)$ is the log-Euclidean R\'enyi divergence, and $\rho,\sigma$ are density matrices.
On the other hand, \eqref{eq:ALT} implies that
\begin{align}
D_{\alpha}^*(\rho\Vert\sigma) := \frac{1}{\alpha-1} \log \Tr\left[ \left( \sigma^{\frac{1-\alpha}{2\alpha}} \rho \sigma^{\frac{1-\alpha}{2\alpha}} \right)^{\alpha} \right]
\leq D_{\alpha}(\rho\Vert\sigma), \quad \forall \alpha > 0,
\end{align}
where $D_{\alpha}^*(\rho\Vert\sigma)$ is the sandwiched R\'enyi divergence \cite{Mul13, WWY14}.
Essentially, Golden--Thompson inequality and Araki--Lieb--Thirrling inequality manifest the noncommutative nature of quantum mechanics and that certain inequalities instead of the equality will be induced in analytical derivations. 

Araki--Lieb--Thirrling trace inequality \eqref{eq:ALT} can be strengthened to the log-majorization relation \cite{Ara90}:
\begin{align} \label{eq:ALT_log}
\left( A^{1/2} B A^{1/2} \right)^r 
    \prec_{\log}  A^{r/2} B^r A^{r/2} , \quad r\geq 1
\end{align}
(the log-majorization relation reverses for $r\in[0,1]$).
Here, for matrices $A,B \in \mathcal{M}_n(\mathds{C})$ with nonnegative eigenvalues, the \emph{log-majorization} of $A$ by $B$, denoted by $A \prec_{\log} B$, means that
\begin{align}
\prod_{i=1}^k \lambda_i(A) \leq \prod_{i=1}^k \lambda_i(B), \quad k = 1,2\ldots, n,
\end{align}
and $\det{A} = \det{B}$, where $\lambda_i(A)$ is is $i$-th eigenvalue of $A$ arranged in non-increasing order.
Likewise, \eqref{eq:GT} can be strengthened by \eqref{eq:ALT_log} and the Lie--Trotter formula \cite{AH94}:
\begin{align}
\e^{H+K} \prec_{\log} \left( \e^{pH/2} \e^{pK} \e^{pH/2} \right)^{1/p}, \quad \forall p>0.    
\end{align}
Ando and Hiai later obtained a log-majorization via Löwner--Heinz operator inequality and the \emph{antisymmetric tensor power trick} (see e.g., \cite[Lemma 2.4]{operator_book}), which complements Golden--Thompson type:
\cite{AH94}:
\begin{align} \label{eq:AH94}
\left[ \mathrm{e}^{ pK/2 } \left( \mathrm{e}^{ -pK/2 } \mathrm{e}^{ pH} \mathrm{e}^{ -pK/2 } \right)^{\alpha} \mathrm{e}^{ pK/2 }
\right]^{1/p}
\prec_{\log}
\e^{\alpha H + (1-\alpha) K}, \quad \alpha \in[0,1], \; p>0.
\end{align}
The above then implies that
\begin{align}
D_{\alpha}^{\flat} (\rho\Vert\sigma)
% \leq \frac{1}{\alpha-1} \log \Tr\left[\sigma \left( \sigma^{-1/2} \rho \sigma^{-1/2} \right)^{\alpha} \right] =: \widehat{D}_{\alpha}(\rho\Vert \sigma), \quad \alpha \in (0,1].
\leq \frac{1}{\alpha-1} \log \Tr\left[\rho \left( \rho^{-1/2} \sigma \rho^{-1/2} \right)^{1-\alpha} \right] =: \widehat{D}_{\alpha}(\rho\Vert \sigma), \quad \alpha \in (0,1].
\end{align}
Bebiano, Lemos and Providência applied Ando and Hiai's proof technique with Furuta's operator inequality \cite{Fur87} to obtain the following log-majorization of Araki's type.
\begin{theorem_BLP}[BLP Inequality {\cite{BLP05}}] \hypertarget{theo:BLP}{} %\label{theo:BLP}
% \begin{theo}[{\cite{BLP05}}]
    For $A,B\geq 0$,
    \begin{align}
        A^{1+q} B^q \prec_{\log} A \left( A^{r/2} B^r A^{r/2} \right)^{q/r}, \quad 0<q\leq r.
    \end{align}
    Equivalently, 
    \begin{align} \label{eq:BLP}
    A^{t+s} B^s \prec_{\log} A^t \left( A^{1/2} B A^{1/2} \right)^s, \quad s\in(0,1], \; t>0.
    \end{align}
\end{theorem_BLP}
Theorem~\hyperlink{theo:BLP}{BLP} provides an alternative proof to the following trace inequality
\begin{align} \label{eq:HP93}
\Tr\left[ A\left( \log A + \log B \right) \right]
\leq \frac{1}{p} \Tr\left[ A \log \left( A^{p/2} B^p A^{p/2} \right) \right], \quad p>0
\end{align}
(see also the early paper by Hiai and Petz \cite{HP93}, the complementaion by Ando and Hiai \cite{AH94}, and the recent developments by Lieb and Carlen \cite{LCV17}).
Inequality \eqref{eq:HP93} then implies that the following relation between Umegaki's quantum relative entropy $D(\rho\Vert\sigma)$ \cite{Ume56} and Belavkin--Staszewski's relative entropy $\widehat{D}(\rho\Vert \sigma)$ \cite{BS82}, i.e.,
\begin{align}
    D(\rho\Vert\sigma) := \Tr\left[ \rho (\log \rho - \log \sigma ) \right]
    \leq 
    \Tr\left[ \rho \log \left( \rho^{1/2} \sigma^{-1} \rho^{1/2} \right) \right] =:
    \widehat{D}(\rho\Vert \sigma).
\end{align}

With efforts to develop the reversed BLP inequalities \cite{MNF08, Fur12, LS18}, the above log-majorizations can be unified as the following generalized BLP (GBLP) inequalities.\footnote{
Some literature studied different generalizations of the BLP inequality, \eqref{eq:BLP}, and used the term generalized BLP \cite{FNT07, MF09, Fur07, FMN22}.
In this paper, we call the inequalities and the reversed versions with the possible range of parameters as in Theorem~\hyperlink{theo:GBLP}{GBLP} as the GBLP inequality.
}
\begin{theorem_GBLP}[GBLP Inequality {\cite{BLP05, MNF08, Fur12, LS18}}] \hypertarget{theo:GBLP}{}
For $A,B\geq 0$,
\begin{align} \label{eq:GBLP}
A^{r+q} B^q \prec_{\log} A^r \left( A^{p/2} B^p A^{p/2} \right)^{q/p}, \quad  0< q \leq p, \; r\geq 0.
\end{align}
If either $0\leq r\leq p \leq q$ and $p>0$, or 
$0\leq q < p$ and $-r \geq q$, then \eqref{eq:GBLP} holds with reversed log-majorization.
\end{theorem_GBLP}

Theorem~\hyperlink{theo:GBLP}{GBLP} and together with a result by Matharu and Aujla (obtained similarly from the Furuta inequality) \cite{MA12} show the following  relations:
