The relations given in \eqref{eq:MA12} is intriguing in the following sense.
Considering $s\in [0,1]$, then Araki--Lieb--Thirrling inequality shows that $\left( A^{-1/2} B A^{-1/2} \right)^{s} \succeq_{\log} A^{-s } B^{s}$.
However, when multiplying both sides by $A$, distributing the power $s$ yields a reversed log-majorization $A\left( A^{-1/2} B A^{-1/2} \right)^{s} \preceq_{\log} A^{1-s } B^{s}$.
Hence, the goal of this paper is to identify which function $f$ such that the following trace inequality holds,
\begin{align} \label{eq:goal}
\Tr\left[ f(A) A^s B^s \right]
\leq 
\Tr\left[ f(A) \left(A^{1/2} B A^{1/2}\right)^s \right], \quad \forall \, s\in[0,1],
\end{align}
or when the trace inequality reverses.
Obviously, the BLP inequality \eqref{eq:BLP} already provides an answer to \eqref{eq:goal} for $f(A) = A^t$, $t>0$.
However, whenever $f$ is not a power function, the core idea of proving Theorems~\hyperlink{theo:BLP}{BLP} and \hyperlink{theo:GBLP}{GBLP}, i.e., the antisymmetric tensor power trick with the Furuta inequality, is not applicable.

Our main result is to show that any nonnegative and nondecreasing function $f$ satisfies \eqref{eq:goal} (see Theorem~\ref{theo:main_direct}), 
and, for any $s\in [0,1]$ and any function $g$ such that $x\mapsto x^s g(x)$ is nonnegative and nonincreasing, \eqref{eq:goal} is reversed (see Proposition~\ref{prop:main_converse}).

We provide our main results and the proofs in Section~\ref{sec:proof}.
In Section~\ref{sec:conjecture}, we discuss the scneario for $s>1$.



\section{An Araki-type trace inequality} \label{sec:proof}

We first show that \eqref{eq:goal} holds if $f(A)$ is a kind of orthogonal projection matrices.
\begin{prop} \label{prop:order}
	Let $A = \sum_{i=1}^n \lambda_i P_i$ be the spectral decomposition of positive semi-definite $A$
    with $\lambda_1 \geq \lambda_2 \geq \cdots \geq \lambda_{n} \geq 0$, and let $\Pi_k := \sum_{i=1}^k P_i$.
	Then, for all $B\geq 0$,% and integer $k = 1,2,\ldots ,d$,
	\[
	\Tr\left[ \Pi_k A^s B^s \right]
	\leq 
	\Tr\left[ \Pi_k \left(A^{1/2} B A^{1/2} \right)^s \right] , \quad \forall \, s\in[0,1],\, 1\leq k\leq n.
	\]	
	% If $s>1$, the inequality reverses(not proven yet).
\end{prop}

\begin{remark}
The proposition~\ref{prop:order} holds for $\Pi_k$ being a projection onto the eigenspace associated with the $k$-th largest eigenvalues.
The trace inequality may not be true once replacing $\Pi_k$ by an arbitrary eigenprojection $P_i$. 
To see a counter-example, let $s=1/2$ and
\begin{align}
A = \begin{bmatrix} 2 & 0 \\ 0 & 1\end{bmatrix}, \,
B = \begin{bmatrix} 1 & 1 \\ 1 & 1\end{bmatrix}, \,
P_2 = \begin{bmatrix} 0 & 0 \\ 0 & 1\end{bmatrix}.
\end{align}
Then, $\Tr[ P_2 A^s B^s ] = 1/\sqrt{2} \not\leq \Tr[P_2(A^{1/2} B A^{1/2})^s ] \approx 0.5774$.
\end{remark}

In the following proofs and lemmas, we suppose $A>0$, and the case $A\geq 0$ then follows by taking the limit.
To prove Proposition~\ref{prop:order}, we need the following two lemmas.

\begin{lemm} \label{lemm:1}
    Following the notation in Proposition~\ref{prop:order}, 
    we denote $I - \Pi_k$ by $\Pi_k^\text{c}$, and let
    $\tilde{A}_k=\Pi_k A+\lambda_k \Pi_k^\textnormal{c} =  \sum_{i=1}^n \max\{\lambda_i,\lambda_k\} P_i$.
    Then, we have
    \[
    \Tr\left[ \Pi_k \left(\tilde{A}_k^{1/2} B \tilde{A}_k^{1/2}\right)^s \right]
	\leq 
	\Tr\left[ \Pi_k \left(A^{1/2} B A^{1/2} \right)^s \right], \quad \forall\, s \in [0,1].
    \]
 %    \[
 %    \Tr\left[ \Pi_k (\tilde{A}_k B)^s \right]
	% \leq 
	% \Tr\left[ \Pi_k (A B)^s \right].
 %    \]
    The inequality reverses for all $s\in[1,2]$.
\end{lemm}

\begin{proof}
    First, note that $A$ and each $\tilde{A}_k$ commute.
    Let $R=(A\tilde{A}_k^{-1})^{1/2}$ be a Hermitian contraction, i.e.,~$R^2\leq I$. 
    Since $x\mapsto x^s$ is operator concave for $s\in[0,1]$, the operator Jensen's inequality \cite{HP82} implies that
\[
\left(A\tilde{A}_k^{-1}\right)^{1/2}\left(\tilde{A}_k^{1/2}B\tilde{A}_k^{1/2}\right)^s \left(A\tilde{A}_k^{-1}\right)^{1/2}
= R\left(\tilde{A}_k^{1/2} B \tilde{A}_k^{1/2}\right)^s R
\leq \left(R\tilde{A}_k^{1/2} B \tilde{A}_k^{1/2} R\right)^s
= \left( A^{1/2} B A^{1/2}\right)^s.
\]
Hence, we obtain
\begin{align}
    \Tr\left[ \Pi_k \left(\tilde{A}_k^{1/2} B \tilde{A}_k^{1/2}\right)^s \right]
    &=\Tr\left[ \Pi_k \left(A\tilde{A}_k^{-1}\right)^{1/2}\left(\tilde{A}_k^{1/2}B\tilde{A}_k^{1/2}\right)^s \left(A\tilde{A}_k^{-1}\right)^{1/2} \right]\\
    &\leq 
    \Tr\left[ \Pi_k \left(A^{1/2} B A^{1/2}\right)^s \right],
    % =\Tr\left[ \Pi_k (AB)^s \right]
\end{align}
with the fact that $\Pi_k(A\tilde{A}_k^{-1})^{1/2} = (A\tilde{A}_k^{-1})^{1/2}\Pi_k = \Pi_k$.

The case of $s\in[1,2]$ follows similarly by the operator convexity of $x\mapsto x^s$, $s\in[1,2]$.
\end{proof}

Note that the BLP inequality implies that, for $A,B\geq 0$,
\begin{align} \label{eq:BLP_trace}
    \Tr\left[ A^t A^s B^s \right]
	\leq 
	\Tr\left[ A^t \left(A^{1/2} B A^{1/2}\right)^s \right] , \quad \forall \, s\in[0,1],\, t\geq 0.
\end{align}
    We have another lemma.
\begin{lemm} \label{lemm:2}
    For $A>0$ and $B\geq 0$,
    \[
	\Tr\left[ A^t \left(A^{1/2} B A^{1/2}\right)^s \right]
	\leq 
	\Tr\left[ A^t A^s B^s \right] , \quad \forall \, s\in[0,1],\, t\leq -s.
	\]	
\end{lemm}

\begin{proof}
    Substitute $B$ by $A^{-1/2}BA^{-1/2}$ to \eqref{eq:BLP_trace}.
    Then
    \[
    \Tr\left[ A^t A^s \left(A^{-1/2} B A^{-1/2}\right)^s \right]
	\leq 
	\Tr\left[ A^t B^s \right], \quad \forall \, s\in[0,1],\, t\geq 0.
    \]
    Next, substitute $A$ by $A^{-1}$, then
    \[
    \Tr\left[ A^{-t-s} \left(A^{1/2} B A^{1/2}\right)^s \right]
	\leq 
	\Tr\left[ A^{-t} B^s \right], \quad \forall \, s\in[0,1],\; t\geq 0.
    \]
    Or, 
    \[
	\Tr\left[ A^t \left(A^{1/2} B A^{1/2}\right)^s \right]
	\leq 
	\Tr\left[ A^t A^s B^s \right] , \quad \forall \, s\in[0,1],\; t\leq -s.
	\]
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:order}]
Combining the two different conditions regarding $t$ in \eqref{eq:BLP_trace} and Lemma~\ref{lemm:2}, we conclude that 
for $f(x)=x^t$, $t\geq 0$ or $f(x)=-x^t$, $t\leq-s$, we have
\begin{align} \label{eq:main_proof1}
    \Tr\left[ f(A) A^s B^s \right]
	\leq 
	\Tr\left[ f(A) \left(A^{1/2} B A^{1/2}\right)^s \right], \quad \forall \, s\in[0,1].
\end{align}

Notice that $\Tr[\Pi_kA^s B^s]=\Tr[\Pi_k\tilde{A}_k^s B^s]$ for $\Pi_k$ introduced in Lemma~\ref{lemm:1}.
Hence, to complete the proof of Proposition~\ref{prop:order}, by Lemma~\ref{lemm:1} we only need to show that
\begin{align} \label{eq:main_proof2}
	\Tr\left[ \Pi_k \tilde{A}_k^s B^s \right]
	\leq 
	\Tr\left[ \Pi_k \left(\tilde{A}_k^{1/2} B \tilde{A}_k^{1/2}\right)^s \right] , \quad \forall \, s\in[0,1].
\end{align}
To show this, we first introduce $\tilde{A}_{k,\varepsilon}=\Pi_k A+(\lambda_k -\varepsilon)\Pi_k^{\mathrm{c}} $ as an approximation of $\tilde{A}_k$, for $\varepsilon\in (0,\lambda_k)$, where $\lambda_k$ is $k$-th largest eigenvalue of $A$.

Define 
\[
g_t(x)=1-\left(\frac{x}{\lambda_k -\varepsilon}\right)^t,  \quad \forall  \, t\leq -s,
\]
then, \eqref{eq:main_proof1} implies that
\[
\Tr\left[ g_t(\Tilde{A}_{k,\varepsilon}) \Tilde{A}_{k,\varepsilon}^s B^s \right]
	\leq 
	\Tr\left[ g_t(\Tilde{A}_{k,\varepsilon}) \left(\tilde{A}_{k,\varepsilon}^{1/2} B \tilde{A}_{k,\varepsilon}^{1/2} \right)^s \right] , \quad \forall \, s\in[0,1],\, t\leq -s,
\]
with noticing that the constant function $1$ is just $f(x)=x^t$ at $t=0$.

Let $t\to -\infty$, then $g_t(\tilde{A}_{k,\varepsilon})\to \Pi_k$, and hence \[
\Tr\left[ \Pi_k \tilde{A}_{k,\varepsilon}^s B^s \right]
	\leq 
	\Tr\left[ \Pi_k \left(\tilde{A}_{k,\varepsilon}^{1/2} B \tilde{A}_{k,\varepsilon}^{1/2}\right)^s \right] , \quad \forall \, s\in[0,1].
\]
Finally, by letting $\varepsilon\to 0$, we obtain
\[
\Tr\left[ \Pi_k \Tilde{A}_{k}^s B^s \right]
	\leq 
	\Tr\left[ \Pi_k \left(\tilde{A}_{k}^{1/2} B \tilde{A}_{k}^{1/2} \right)^s \right] , \quad \forall \, s\in[0,1].
\]

In conclusion, for all $s\in [0,1]$, we have
\[
\Tr\left[ \Pi_k A^s B^s \right]
=
\Tr\left[ \Pi_k \tilde{A}_{k}^s B^s \right]
\leq 
\Tr\left[ \Pi_k \left(\tilde{A}_{k}^{1/2} B \tilde{A}_{k}^{1/2}\right)^s \right] 
\leq
\Tr\left[ \Pi_k \left(A^{1/2} B A^{1/2} \right)^s \right],
\]
which completes the proof of Proposition~\ref{prop:order}.
\end{proof}

Now we are in a position to prove our main results.

\begin{theo} \label{theo:main_direct}
    Let $A,B\geq 0$.
    For any nonnegative and nondecreasing function $f$ on an interval $\mathcal{J}$, where $\spec(A)\subseteq \mathcal{J}$, we have 
\[
\Tr\left[ f(A) A^s B^s \right]
\leq 
\Tr\left[ f(A) \left(A^{1/2} B A^{1/2} \right)^s \right], \quad \forall \, s\in[0,1].
\]
\end{theo}
\begin{proof}
    Since $f$ is nonnegative and nondecreasing, we can choose some appropriate nonnegative coefficients $c_k$ for each $k=1,\cdots,n$, such that $f(A)=\sum_{k=1}^n c_k\Pi_k$. Then, the claim follows from Proposition~\ref{prop:order}.
\end{proof}


As above, we may also apply substitutions to obtain another direction of the same inequality, but with a different condition.
\begin{prop} \label{prop:main_converse}
    Let $A,B\geq 0$.
    For any $s\in[0,1]$ and any function $g$ on an interval $\mathcal{J}$, where $\spec(A)\subseteq \mathcal{J}$, such that $x\mapsto x^sg(x)$ is nonnegative and nonincreasing, then 
\begin{align*}
\Tr\left[ g(A) \left(A^{1/2} B A^{1/2} \right)^s \right]
\leq 
\Tr\left[ g(A) A^s B^s \right].
\end{align*}
\end{prop}

\begin{proof}
    Again, we assume $A>0$, and extend to $A\geq 0$ via a limit.
    Set $f(x)=x^{-s}g(x^{-1})$, which is nonnegative and nondecreasing. Since the domain of $f$ includes the spectrum of $A^{-1}$, by Theorem~\ref{theo:main_direct},
\begin{align}
\Tr\left[g(A)\left(A^{{1}/{2}}BA^{{1}/{2}}\right)^s\right]
&=
\Tr\left[ f\left(A^{-1}\right) \left(A^{-1}\right)^s \left(A^{{1}/{2}}BA^{{1}/{2}}\right)^s \right]
\\
&\leq 
\Tr\left[ f\left(A^{-1}\right) \left(A^{-1/2} \cdot A^{{1}/{2}}BA^{{1}/{2}}\cdot A^{-1/2}\right)^s \right]
\\
&=\Tr\left[g(A)A^sB^s\right].
\end{align}
\end{proof}

\section{A Conjecture for \(s > 1\)} \label{sec:conjecture}

Theorem~\ref{theo:main_direct} shows the trace inequality for all $s\in[0,1]$.
Inspired by the reverse BLP inequality \cite{MNF08, FNT07, MF09}, we conjecture the following reverse direction.

\begin{conj} \label{conj:s>1}
    For any nonnegative and nondecreasing function $f$ on an interval $\mathcal{J}$, where $\spec(A)\subseteq \mathcal{J}$, we have 
\[
\Tr\left[ f(A) A^s B^s \right]
\geq 
\Tr\left[ f(A) \left(A^{1/2} B A^{1/2} \right)^s \right], \quad \forall \, s > 1.
\]
\end{conj}

Note that $x\mapsto x^s$ is operator convex for $s\in[1,2]$, we may adapt the previous technique to prove Conjecture~\ref{conj:s>1} for $s\in[1,2]$, provided that the condition $0\leq r\leq p \leq q$ in the reverse direction of Theorem~\hyperlink{theo:GBLP}{GBLP} can be relaxed to $0\leq p \leq q$.
Thereby, we conjecture the following reverse log-majorization, which complements \eqref{eq:GBLP}.
\begin{conj} \label{conj:GBLP_reverse}
For $A,B\geq 0$,
\begin{align}
\Tr\left[ A^{r+q} B^q \right] \geq \Tr\left[ A^r \left( A^{p/2} B^p A^{p/2} \right)^{q/p} \right], \quad  0 \leq p \leq q, \; r\geq 0.
\end{align}
\end{conj}
\noindent (To show Conjecture~\ref{conj:s>1} for $s\in[1,2]$, the trace inequality version of Conjecture~\ref{conj:GBLP_reverse} would be sufficient.)

\medskip 

In fact, we can directly prove Conjecture~\ref{conj:s>1} for a special case of $s=2$ without resorting to Conjecture~\ref{conj:GBLP_reverse}.
\begin{prop} \label{prop:main_s=2}
    For any nonnegative and nondecreasing function $f$ on an interval $\mathcal{J}$, where $\spec(A)\subseteq \mathcal{J}$, we have 
\[
\Tr\left[ f(A) A^s B^s \right]
\geq 
\Tr\left[ f(A) \left(A^{1/2} B A^{1/2} \right)^s \right], \quad s = 2.
\]
\end{prop}

\begin{proof}
Our claim is based on Lemma~\ref{lemm:1} and the reverse direction to \eqref{eq:main_proof2}, which is presented in the following Lemma~\ref{lemm:order_s=2}.
\end{proof}

% The proof of Proposition~\ref{prop:main_s=2} follows from the previous reasoning, operator convexity for $x\mapsto x^2$, and the following lemma (which does not rely on Conjecture~\ref{conj:GBLP_reverse}).
\begin{lemm} \label{lemm:order_s=2}
	% Following the notation in Proposition~\ref{prop:order}.
    Let $A = \sum_{i=1}^n \lambda_i P_i$ be the spectral decomposition of positive semi-definite $A$ with $\lambda_1 \geq \lambda_2 \geq \cdots \geq \lambda_{d} \geq 0$,
	$\Pi_k := \sum_{i=1}^k P_i$,
	$\Pi_k^{\textnormal{c}} := I - \Pi_k$,
	and $\tilde{A}_k := \Pi_k A + \lambda_k \Pi_k^{\textnormal{c}}$.
	Then,
	\begin{align}
		\Tr\left[ \Pi_k \left(\tilde{A}_k^{1/2} B \tilde{A}_k^{1/2}\right)^s \right]
		\leq \Tr\left[ \Pi_k \tilde{A}_k^s B^s \right], \quad s = 2.
	\end{align}
\end{lemm}
\begin{proof}
Using the fact that $\lambda_k \Pi_k \leq \Pi_k \tilde{A}_k \Pi_k$ by construction and the Araki--Lieb--Thirrling trace inequality \eqref{eq:ALT}, we calculate
\begin{align}
	\Tr\left[ \Pi_k \left(\tilde{A}_k^{1/2} B \tilde{A}_k^{1/2}\right)^2 \right]
    &= \Tr\left[ \Pi_k \tilde{A}_k \Pi_k  B { \tilde{A}_k} B \right]
	\\
	&= \Tr\left[ \Pi_k \tilde{A}_k \Pi_k  B {  \left(\Pi_k \tilde{A}_k \Pi_k + \lambda_k \Pi_k^{\text{c}} \right) } B \right]
	\\
	&= \Tr\left[ \Pi_k \tilde{A}_k \Pi_k  B { \Pi_k \tilde{A}_k \Pi_k} B \right]
	+ \Tr\left[ \Pi_k \tilde{A}_k \Pi_k  B { (\lambda_k \Pi_k^{\text{c}})} B \right]
	\\
	&= \Tr\left[ (\Pi_k \tilde{A}_k \Pi_k  \Pi_k B \Pi_k )^2 \right]
	+ \Tr\left[ \Pi_k \tilde{A}_k \Pi_k  B { (\lambda_k \Pi_k^{\text{c}})} B \right]
	\\
	&= \Tr\left[ (\Pi_k \tilde{A}_k \Pi_k  \Pi_k B \Pi_k )^2 \right]
	+ \Tr\left[ \Pi_k \tilde{A}_k \Pi_k  { \lambda_k \Pi_k }  B  {  \Pi_k^{\text{c}}} B \right]
	\\
	&\leq\Tr\left[ (\Pi_k \tilde{A}_k \Pi_k  \Pi_k B \Pi_k )^2 \right]
	+ \Tr\left[ \Pi_k \tilde{A}_k \Pi_k  {  \Pi_k \tilde{A}_k \Pi_k }  B  {  \Pi_k^{\text{c}}} B \right]
	\\
	&= \Tr\left[ (\Pi_k \tilde{A}_k \Pi_k  \Pi_k B \Pi_k )^2 \right]
	+ \Tr\left[ \Pi_k \tilde{A}_k^2 \Pi_k  B  {  \Pi_k^{\text{c}}} B \right]
	\\
	&\overset{\eqref{eq:ALT}}{\leq} \Tr\left[ (\Pi_k \tilde{A}_k \Pi_k )^2 (\Pi_k B \Pi_k )^2 \right]
	+ \Tr\left[ \Pi_k \tilde{A}_k^2 \Pi_k  B  {  \Pi_k^{\text{c}}} B \right]
	\\
	&= \Tr\left[ \Pi_k \tilde{A}_k^2 \Pi_k B \Pi_k B \right]
	+ \Tr\left[ \Pi_k \tilde{A}_k^2 \Pi_k  B  {  \Pi_k^{\text{c}}} B \right]
	\\
	&= \Tr\left[ \Pi_k \tilde{A}_k^2 \Pi_k  B  (\Pi_k + {  \Pi_k^{\text{c}}}) B \right]
	\\
	&= \Tr\left[ \Pi_k \tilde{A}_k^2 B^2 \right].
\end{align}
\end{proof}
% We also conjecture that Lemma~\ref{lemm:order_s=2} holds for all $s\geq 1$, which can also be used to prove Conjecture~\ref{conj:s>1} for $s\in[1,2]$.

\section{Conclusions} \label{sec:conclusions}
In this paper, we derived some Araki-type trace inequalities that involve monotone functions other than powers.
Although usual Araki-type inequalities and the BLP inequalities are expressed in a stronger form of log-majorization, however, the antisymmetric tensor power trick may not be applicable for functions beyond powers.
On the other hand, trace inequalities find more and immediate applications in other fields such as quantum information science and mathematical physics, which motivates us to further Araki-type trace inequalities to a broader form.

Numerical experiments suggest that Conjecture~\ref{conj:s>1} for $s> 1$ and a slightly general reverse BLP inequality in Conjecture~\ref{conj:GBLP_reverse} could be true, which is left for future work.

