\section{Velocity field}
\label{Sec_v}
We consider here the case of a free ($f=0$) RT particle with constant tumbling rate $\alpha$ and a space-dependent speed $v(x)$ \cite{AngGar2019,Sandev_2025}.
The typical application we have in mind is the case of photokinetic bacteria whose velocity can be controlled using arbitrary light patterns \cite{Elife2018,pellicciotta2023colloidal}. Since $v(x)$ is tunable as an external parameter and $P(x)$ can be computed from experimental data, it is an ideal set-up for measuring $\pi(x)$ without estimating the Kulback-Leibler divergence between a trajectory and its time reversal.\\
The equation for the stationary PDF reads
\begin{equation}
\label{SPDFeq_v}
\px \left[ 
v(x)P(x)  -D^2 \px \left( \frac{\px P(x)}{v(x)}\right) \right]
+ \frac{\alpha D}{v(x)} \px P(x) =0 \ ,
\end{equation}
as can be see by putting $f=0$ in the equation (\ref{SPDFeq}) valid for null net stationary current $J=0$.
For purely active particles, i.e., in the absence of thermal noise $D=0$, we have that $\partial_x (vP)=0$ and 
then we obtain the well known $1/v$ dependence of the stationary PDF
$$P(x) \propto  \frac{1}{v(x)} , \qquad (D=0).$$
The local EPR can be expressed in terms of $P$ and its derivatives.
By using (\ref{pi_1}) we have
\begin{align}
\label{pi_v0}
\pi(x) &= \frac{P(x)}{D} \frac{\Delta^2(x)}{P^2(x)-Q^2(x)} + \frac{\alpha}{2}Q(x) \log \frac{P(x)+Q(x)}{P(x)-Q(x)} , \\ 
    Q(x) &= D\frac{\px P(x)}{v(x)}     \ , \\
    \Delta(x) & = v(x)P(x) - D^2 \px\left( \frac{\px P(x)}{v(x)}\right) \ .
\end{align}
Alternatively, thorugh the relation (\ref{LEPR_P}), $\pi=\phi$,  and  using  (\ref{LEPR_delta}) and (\ref{LEPR_chi}) 
we can write
\begin{align}
\label{pi_v}
\pi(x) &=  \sigma(x) - \partial_x \chi(x) , \\ 
    \sigma(x) &= \frac{v^2(x)}{D} P(x) - D \px^2 P(x) + D (\px P(x)) (\px \log v(x))    \ , \\
    \chi(x) & = \frac{D\sigma(x)}{2v(x)} \ \log \frac{v(x)P(x)+D\partial_x P(x)}{v(x) P(x)-D\partial_x P(x)} \ .
\end{align}


\paragraph*{Perturbative expansion.}
\label{Pertex}
Exact solutions of (\ref{SPDFeq_v}) are not always possible, and it is often useful to follow a perturbative approach 
%It is often useful to obtain solutions 
for small values of diffusivity.
In many real cases and practical realization of active systems 
(e.g, motile cells or syntetic catalytic particles) 
the thermal diffusivity is some order of magnitude lower than the active one.
We introduce the dimensionless quantity 
\begin{equation}
%    \text{Pe} = \frac{v_0^2}{\alpha D} \ ,
    D_* = \frac{\alpha D}{v_0^2} \ ,
\end{equation}
which is the ratio $D/D_A$ between thermal ($D$) and active diffusion ($D_A=v_0^2/\alpha$),
where $v_0$ sets the scale of velocity,  $v(x) = v_0 w(x)$, with
$w(x)$ a dimensionless field. The quantity $D_*$ is the inverse of the Peclet number
$Pe=v_0^2/(\alpha D)$.
We look for the expressions of PDFs and EPRs in the limit
$D_* \ll 1$ (large Peclet number $Pe\gg 1$).
The differential equation (\ref{SPDFeq_v}) for $P$ can be rewritten in the form 
\begin{equation}
\label{FP_Pst}
    \partial_x \left[
w(x) P(x) - \frac{v_0^2}{\alpha^2} D_*^{2} \partial_x \left( \frac{\partial_x P(x)}{w(x)} \right)
    \right]
    + \frac{D_*}{w(x)} \partial_x P(x) = 0 \ .
\end{equation}
By assuming that  $P$ is an analytic function of $D_*$ we can write the series expansion
\begin{equation}
\label{Pser}
    P(x) = \sum_{n=0}^\infty P_n(x) \ D_*^{n} \ ,
\end{equation}
where the $P_n(x)$ are functions that do not depend on $D_*$ and can take negative values (except $P_0$ which is non-negative defined).
The normalization condition implies that
\begin{equation}
\label{norm}
    \int dx \ P_n(x) = \delta_{n0} ,
\end{equation}
where $\delta_{nk}$ is the Kronecker delta function ($1$ for $n=k$ and $0$ otherwise).
%We note that the quantities $P_n$ ($n>0$) are not PDFs, as they can take negative values.
The differential equations for $P_n$ are obtained by considering (\ref{FP_Pst}) 
at different orders of $D_*$
\begin{align}
     &\partial_x(w(x) P_0(x)) = 0 \ ,   &(n=0) \\
     &\partial_x(w(x) P_1(x)) + \frac{1}{w(x)} \partial_x P_0(x) = 0 \ ,   & (n=1) \\
     &\partial_x \left[ w(x) P_n(x) - \frac{v_0^2}{\alpha^2} 
    \partial_x \left( \frac{\partial_x P_{n-2}(x)}{w(x)}\right)   \right]
    + \frac{1}{w(x)} \partial_x P_{n-1}(x) = 0  ,    &(n\geq 2) 
\end{align}
By solving up to the second order we have
\begin{eqnarray}
\label{Pper_0}
P_0(x) &=& \frac{c_0}{w(x)} \ , \\
\label{Pper_1}
P_1(x) &=& \frac{c_1}{w(x)} - \frac{c_0}{2 w^3(x)} \ , \\
P_2(x) &=& \frac{c_2}{w(x)} - \frac{c_1}{2 w^3(x)} + \frac{3 c_0}{8 w^5(x)} 
- \frac{c_0 v_0^2}{\alpha^2 w(x)} 
\partial_x \left( \frac{\partial_x w(x)}{w^3(x)}\right) \ .
\label{Pper_2}
\end{eqnarray}
The constants $c_n$ are determined by the normalization conditions (\ref{norm})
(we assume that the motion occurs in a finite domain of size $L$ with periodic boundary conditions)
\begin{eqnarray}
c_0 &=& \frac{1}{L} \langle w^{-1}(x) \rangle^{-1} \ , \nonumber \\
c_1 &=& \frac{1}{2L} \frac{\langle w^{-3}(x) \rangle}{\langle w^{-1}(x) \rangle^2}\ , \nonumber \\
c_2 &=& \frac{1}{L} \frac{1}{\langle w^{-1}(x) \rangle^2} \left[ 
\frac14 \frac{\langle w^{-3}(x) \rangle^2}{\langle w^{-1}(x) \rangle} -
\frac38 \langle w^{-5}(x) \rangle +
\frac{v_0^2}{\alpha^2} \langle (\partial_x w(x))^2 w^{-5}(x) \rangle 
\right] \ ,
\label{cn}
\end{eqnarray}
where 
\begin{equation}
    \langle f(x) \rangle = \frac{1}{L} \int dx \ f(x)\ .
\end{equation}


We now analyze the entropy production in the small diffusion regime.
We can express the EPR as a Laurent series in $D_*$
\begin{equation}
    \pi(x) = \sum_{n=-1}^\infty \pi_n(x) \ D_*^n ,
\end{equation}
where the term $n=-1$ represents the singular part.
By using the expansion of $P$ (\ref{Pser}) inserted in (\ref{pi_v}) we obtain, 
%the quantities $\pi_n$ can be written in terms of $P_n$
%\begin{eqnarray}
%    \pi_{-1}(x) &=& \alpha w^2(x) P_0(x) \ ,  \\
%    \pi_{0}(x) &=& \alpha w^2(x) P_1(x) \ , \\
%    \pi_{n}(x) &=& \alpha w^2(x) P_{n+1}(x) -
%    \frac{v_0^2}{\alpha} \left(\partial_x^2 \log w(x)\right) P_{n-1}(x) \ , \quad \quad (n\geq1) \ .
%\end{eqnarray}
up to the first order in $D_*$
\begin{equation}
\label{EPRd}
    \pi(x) =\frac{\pi_{-1}(x)}{D_*} + \pi_0(x) + \pi_1(x)\ D_* + O(D_*^2) \ ,
\end{equation}
where
\begin{eqnarray}
\label{EPRd_0}
    \pi_{-1}(x) &=& \alpha c_0  w(x) \ ,  \\
 \label{EPRd_1}
   \pi_{0}(x) &=& \alpha \left[ c_1 w(x) - \frac{c_0}{2 w(x)} \right]\ , \\
%    \pi_{1}(x) &=& \alpha \left[ c_2 w(x) - \frac{c_1}{2 w(x)} +\frac{3c_0}{8 w^3(x)} \right] -
%    \frac{2c_0v_0^2}{\alpha} \partial_x \left( \frac{\partial_x w(x)}{w^2(x)}\right) \ ,
 \label{EPRd_2}
   \pi_{1}(x) &=& \alpha \left[ c_2 w(x) - \frac{c_1}{2 w(x)} +\frac{3c_0}{8 w^3(x)} \right] 
    + \frac{c_0v_0^2}{\alpha} \partial_x \left( \frac{\partial_x w(x)}{w^2(x)}\right)  \ ,
\end{eqnarray}
with the constants $c_n$ given in (\ref{cn}).
The total EPR is obtained by integrating the EPR density (\ref{EPRd}) over space, giving
\begin{equation}
   \Pi = \frac{\Pi_{-1}}{D_*} + \Pi_0 + \Pi_1 \ D_* + O(D_*^{-2}) \ ,    
\end{equation}
with
\begin{eqnarray}
    \Pi_{-1} &=& \alpha \frac{\langle w(x) \rangle}{\langle w^{-1}(x) \rangle} \ ,  \\
    \Pi_{0} &=& \frac{\alpha}{2} \left[ 
    \frac{\langle w(x) \rangle \langle w^{-3}(x) \rangle }{\langle w^{-1}(x) \rangle^2} - 1
    \right] \ , \\
    \Pi_1 &=& \alpha L c_2 \langle w(x) \rangle + \frac{\alpha}{8} 
    \frac{\langle w^{-3}(x) \rangle}{\langle w^{-1}(x)\rangle} \ ,
\end{eqnarray}
where the constant $c_2$ in the last expression is given in (\ref{cn}).


\subsection{Piecewise constant velocity}
We analyze here the case of a gas of RT particles immersed in a piecewise constant speed field
\begin{equation}
v(x)= \begin{cases}
v_1  & \qquad \text{if $0<x<\lambda$}\\
v_2 & \qquad \text{if $\lambda<x<L$}
\end{cases}
\end{equation}
moving in a box of size $L$ with periodic boundary conditions. %(see Figure ...).
In this case the problem admits of an exact solution.
To find the stationary PDF we have to solve equation (\ref{SPDFeq_v}) in the two zones
$0<x<\lambda$ ($1$) and $\lambda<x<L$ ($2$), imposing the appropriate boundary conditions.
Within the two zones the speed is constant, $v(x)=v_i$ ($i=1,2$), and the equations for the PDF read
$$
\px \left[ \left(v_i^2-D^2\px^2 \right) P_i(x)\right] + \alpha D \px P_i(x) = 0 , \qquad (i=1,2) ,
$$
whose solutions are
\begin{equation}
\label{P_i}
    P_i(x) = A_i e^{k_i x} + B_i e^{-k_i x} + C_i ,
\end{equation}
with
\begin{equation}
\label{k_i}
    D^2 k_i^2 = v_i^2 +\alpha D .
\end{equation}
The six unknown constants $\{A_i,B_i,C_i\}\  (i=1,2)$
are determined by imposing suitable conditions on the solution (see Appendix \ref{App_Speed}).\\
Once we know the expression of $P(x)$ we can calculate the local EPR through  
(\ref{pi_v0}) or (\ref{pi_v}) considered, separately, in the two zones of constant speed.
By noting that the quantities $P$, $Q$ and $\Delta$ are continuous at the points where 
the speed jumps, $x=0$ and $x=\lambda$ (see Appendix \ref{App_Speed}), also $\pi$ is. Fig. (\ref{fig:rt_step}) reports the comparison between numerical simulations (see Appendix \ref{App_Sim}) and analytical solutions for both $P(x)$ and $\pi(x)$. As one can see, entropy production decreases with increasing local density.

