\section{Force field}
\label{Sec_f}
To understand the effect of forces on local EPR we focus on simple situations with external fields so that we still are dealing with a gas of RT particles.
We consider here the case of a RT particle with constant tumbling rate $\alpha$ and speed $v$ 
in the presence of a force field $f(x)$.
The equation for the steady state PDF takes the form -- see (\ref{SPDFeq}) with constant $v$ 
\begin{equation}
\label{eq_st}
    \px \left[ \left( v^2 - (D\px - \mu f(x))^2 \right) P(x) \right] +
    \alpha (D\px -\mu f(x)) P(x) =0 \ .
\end{equation}
It is interesting to analyze the two opposite limits of purely Brownian particles and purely
active particles in the stationary regime.
%%%%%%%%%%%
\\
\paragraph*{Brownian limit.}
In the absence of active motion ($v=0$) the PDF $P_B$ of the Brownian particle obeys the equation
\begin{equation}
\label{eq_PB}
    (D \px -\mu f(x)) P_B(x) = 0 \ ,
\end{equation}
as simply obtained from (\ref{Jdef})  and considering null flux $J=0$.
By introducing the potential $V$, $f(x)=-\px V(x)$, 
the solution is 
\begin{equation}
    P_B(x) = C_B \ e^{-\frac{\mu}{D} V(x)} \ ,
\end{equation}
where $C_B$ is the normalization constant
\begin{equation}
    C_B = \left[ \int dx \ e^{-\frac{\mu}{D}V(x)}\right]^{-1} \ .
\end{equation}
\\
%%%%%%%%%%
\paragraph*{Active limit.}
In the opposite limit of purely active motion ($D=0$) the stationary equation 
for the PDF $P_A$ reads
\begin{equation}
\label{eq_PA}
  \px \left[ (v^2 -\mu^2 f^2(x)) P_A(x) \right] - \alpha \mu f(x) P_A(x) = 0 \ ,
\end{equation}
whose solution can be written for $v>\mu f(x)$
\begin{equation}
    P_A(x) = \frac{C_A}{v^2-\mu^2 f^2(x)} \ 
    \exp \left[\alpha \mu  \int^x dy \ \frac{f(y)}{v^2-\mu^2 f^2(y)} \right]\ ,
\end{equation}
where $C_A$ is a normalization constant \cite{Dhar2019,Sevilla_2019}.\\

%%%%%%%
The local EPR can be expressed in terms of $P$ and its derivatives -- see (\ref{LEPR_P}) with constant $v$
\begin{equation}
\label{EPRl}
    \pi(x) = \frac{1}{D} \left[ v^2 - \left( D \px -\mu f(x)\right)^2\right] P(x)    
    - \px \chi(x) \ ,
\end{equation}
where 
\begin{equation}
    \chi(x) = \frac{1}{2v} 
    \left[ \log \frac{(v-\mu f(x) +D\px)P(x)}{(v+\mu f(x)-D\px)P(x)} \right] 
    \left[v^2 - \left( D\px-\mu f(x)\right)^2 \right] P(x) \ .
\end{equation}
It is noteworthy to point out that we were able to express the local EPR $\pi(x)$
as a function of the stationary PDF $P(x)$, Eq. (\ref{EPRl}), allowing us to obtain 
explicit expressions of it whenever we know the stationary solution of the problem.  
However, it should be added that it is not always possible to obtain explicit expressions 
of the stationary distributions, except in a limited number of cases, such as the case of confined motions in a box~\cite{razin2020entropy} and the case of harmonic and piecewise linear potentials, 
that we discuss in the following Sections.


%%%%%%%%%%%%%%%%%%%%%%%%%%5%%%%%%%%
\subsection{Harmonic potential}
\label{HarPot}
The case of harmonic potential is of particular interest because of its physical relevance and 
analytical tractability.
The potential $V(x)$ and the force $f(x)=-\px V(x)$ are given by
\begin{align}
V(x) &= \frac{k}{2} x^2  \ , \\
f(x) &= - k x \ .
\end{align}
\\
\paragraph*{Stationary solution.}
In this case, it is possible to write the solution of (\ref{eq_st}) as a convolution of
Brownian and active PDFs
\begin{equation}
\label{P_harm}
    P(x) = \int_{-\ell}^{+\ell} dy \ P_A(y) \ P_B(x-y) \ ,
\end{equation}
where $\ell = v/\mu k$ \cite{Frydel2022}.
In the above expression, the Brownian PDF is
\begin{equation}
\label{P_B}
    P_B(x) = \sqrt{\frac{\mu k}{2\pi D}} \ e^{-\frac{\mu k}{2 D}x^2}
\end{equation}
and the active one is given by
\begin{equation}
\label{P_A}
    P_A(x) = C \left(v^2 - \mu^2 k^2 x^2 \right)^{\frac{\alpha}{2\mu k}-1} \ ,
\end{equation}
where the constant $C$ is
\begin{equation}
\label{P_AA}
    C = \frac{\mu k \Gamma\left(\frac{\alpha}{2\mu k}+\frac12\right)}{\sqrt{\pi}\Gamma\left(\frac{\alpha}{2\mu k}\right)} \ v^{1-\frac{\alpha}{\mu k}}
\end{equation}
with $\Gamma(z)$ the Euler gamma function.
The proof of (\ref{P_harm}) is given in the Appendix \ref{App_Harm}.\\
Some limiting cases are listed below.\\

\paragraph{Diffusive Limit of the Active Motion.} For $\alpha,v \to \infty$ with finite $D_A=v^2/\alpha$ (active diffusivity)
the active PDF (\ref{P_A}) tends to a Gaussian
\begin{equation}
    P_A(x) = \sqrt{\frac{\mu k }{2 \pi D_A}}\ e^{-\frac{\mu k}{2D_A} x^2} ,
\end{equation}
and then (\ref{P_harm}) is a convolution of two Gaussian distributions ($\ell = v/ \mu k \to \infty$) 
resulting in a Gaussian with effective variance $\sigma^2$
\begin{equation}
    P(x) =  \frac{1}{\sqrt{2 \pi \sigma^2}}\ e^{-\frac{x^2}{2\sigma^2}} ,
\end{equation}
with
$$
\sigma^2 = \frac{1}{\mu k} \frac{D D_A }{D+D_A} . 
$$
\paragraph{Ballistic Limit.} For $\alpha\to 0$ the active PDF has two delta peaks
\begin{equation}
    P_A(x) = \frac12 \left[ \delta \Big(x-\frac{v}{\mu k} \Big) + \delta \Big(x+\frac{v}{\mu k}\Big)  \right]
\end{equation}
and the total PDF is the sum of two Gaussian distributions
\begin{equation}
    P(x) = \frac12 \sqrt{\frac{\mu k}{2\pi D}} \left(     
    e^{-\frac{\mu k }{2D}(x-v/\mu k)^2} +
    e^{-\frac{\mu k }{2D}(x+v/\mu k)^2} 
    \right).
\end{equation}

