\paragraph*{Entropy production rate.}
In the harmonic case the local EPR (\ref{EPRl}) becomes 
\begin{equation}
\label{pi1_harm}
    \pi(x) = \frac{1}{D} \left[ v^2 - \left( D \px +\mu k x\right)^2\right] P(x)    
    - \px \chi(x) \ ,
\end{equation}
where 
\begin{equation}
    \chi(x) = \frac{1}{2v} 
    \left[ \log \frac{(v+\mu k x +D\px)P(x)}{(v-\mu k x-D\px)P(x)} \right] 
    \left[v^2 - \left( D\px+\mu k x\right)^2 \right] P(x) \ .
\end{equation}
We first note that, by integrating over space (\ref{pi1_harm}), we obtain the known expression 
of the global entropy production rate of active particles in harmonic potential 
\cite{paoluzzi2024entropy,Fry2022,GMP2021}.
Indeed, we have
\begin{align}
\Pi &= \int_{-\infty}^{+\infty} dx  \ \pi(x) = \frac{1}{D}\int_{-\infty}^{+\infty} dx \ \left[ v^2-(D\px+\mu k x)^2 \right] P(x) \ \nn \\
&= \frac{1}{D} \int_{-\infty}^{+\infty} dx \int_{-\ell}^{+\ell} dy \ P_A(y) (v^2 - \mu^2 k^2 y^2) P_B(x-y) \nn \\
&= \frac{1}{D} \int_{-\ell}^{+\ell} dy \ P_A(y) (v^2 - \mu^2 k^2 y^2) \nn \\
&= \frac{C}{D} \int_{-\ell}^{+\ell} dy \ (v^2-\mu^2 k^2 y^2)^{\frac{\alpha}{2\mu k}}
= \frac{v^2}{D} \frac{\alpha}{\alpha +\mu k} \ , 
\end{align}
where 
%the integral over $x$ spans the entire space and that over $y$ goes from  $-\ell$ to $\ell$, with 
$\ell=v/\mu k$.
In  deriving the above result we
have considered vanishing distributions at boundaries and used
(\ref{P_harm}), (\ref{P_A}), (\ref{P_AA}),  the normalization condition for $P_B$, 
the explicit integral  \cite{gradshteyn2014table}
\begin{equation}
    \int_0^1 dx \ (1-x^2)^\nu = \frac{\sqrt{\pi}}{2} \frac{\Gamma(\nu+1)}{\Gamma(\nu+\frac32)} \ , 
    \qquad \nu>-1, 
\end{equation}
and the property of the Gamma function $\Gamma(z+1)=z \Gamma(z)$.

\noindent
Now, we give a more explicit expression of the local EPR.
By using the convolution expression (\ref{P_harm}), together with ({\ref{P_B}}) and (\ref{P_A}), 
we can write the local EPR (\ref{pi1_harm}) as 
\begin{equation} \label{eprharmexpl}
    \pi(x) = \frac{1}{D} \left[ 
    M_1(x) +\frac{\mu k}{2v} \left(
    M_2(x) \log \frac{Y_+(x)}{Y_-(x)} +
    %I_1
    M_1(x)
    \left(
    \frac{H_+(x)}{Y_+(x)}-\frac{H_-(x)}{Y_-(x)}
    \right)
    \right)
    \right]
\end{equation}
where the different space-dependent quantities are given by
\begin{align}
    M_1(x) &= v^2 I_0(x)- \mu^2 k^2 I_2(x)\ , \\
    M_2(x) &= x M_1(x) - v^2 I_1(x) + \mu^2 k^2 I_3(x)\ , \\
    Y_\pm(x) &= v I_0(x) \pm \mu k I_1(x)\ , \\
    H_\pm(x) &= x Y_\pm(x)  - v I_1(x)\mp \mu k I_2(x)\ ,
%    M_1(x) &= I[v^2-\mu^2k^2y^2] = v^2 - \mu^2 k^2 I[y^2]\ , \\
%    M_2(x) &= x I[v^2-\mu^2k^2y^2] -  I[y(v^2-\mu^2k^2y^2)] = 
%    x I_1 - v^2 I[y] + \mu^2 k^2 I[y^3]\ , \\
%    Y_\pm(x) &= I[v\pm\mu k y] = v \pm \mu k I[y] \ , \\
%    H_\pm(x) &= x I[v\pm\mu k y]  - I[y(v\pm \mu k y)] = x Y_\pm  - v I[y] \mp \mu k I[y^2]\ ,
\end{align}
where we have defined
\begin{equation}
I_n(x) = I[y^n](x)
\end{equation}
and $I$ is the linear integral operator
\begin{equation}
\label{Idef}
    I[f](x) := \int_{-\ell}^{+\ell} dy \ P_A(y) P_B(x-y) f(y) \ , \qquad \ell=v/\mu k ,
\end{equation}
which, for $f=1$, reduces to the PDF (\ref{P_harm}), i.e., $I[1](x)=I_0(x)=P(x)$.
\\

We can also give an alternative expression for the local EPR, by exploiting the direct form (\ref{pid}).
We first note that the quantities defined in (\ref{Qde}-\ref{JLde}), in the harmonic case $f=-kx$, can be
expressed in terms of the quantities defined above
%\begin{align}
%    P &= I_0 , \\
%    Q &= \frac{\mu k}{v} I_1 , \\
%    \Delta &= \frac{M_1}{v} , \\
%    R &= \frac{Y_+}{2v} , \\
%    L &= \frac{Y_-}{2v} , \\
%    J_R &= \frac{M_1}{2v} , \\
%    J_L &= -\frac{M_1}{2v} .
%\end{align}
\begin{align}
    P(x) &= I_0(x) , \\ 
    Q(x) &= \frac{\mu k}{v} I_1(x) , \\
    \Delta(x) &= \frac{M_1(x)}{v} , \\ 
    R(x) &= \frac{Y_+(x)}{2v} , \\ 
    L(x) &= \frac{Y_-(x)}{2v} , \\ 
    J_R(x) &= \frac{M_1(x)}{2v} , \\ 
    J_L(x) &= -\frac{M_1(x)}{2v} .
\end{align}
Substituting in (\ref{pid}) we obtain the alternative expression of $\pi$
\begin{equation}
\label{pihp}
%    \pi (x) = \frac{I_0 M_1^2}{D Y_+ Y_-} + \frac{\alpha \mu k I_1}{2v} \log \frac{Y_+}{Y_-} .
    \pi (x) = \frac{M_1^2(x)}{2vD} \left( \frac{1}{Y_+(x)} + \frac{1}{Y_-(x)} \right) + 
    \frac{\alpha \mu k I_1(x)}{2v} \log \frac{Y_+(x)}{Y_-(x)} .
\end{equation}
The three terms correspond to contributions $\pi_R(x)$, $\pi_L(x)$ and $\pi_{RL}(x)$, see (\ref{pisum}).


We now compare the theoretical predictions with numerical simulations (in one spatial dimension) of thermal non-interacting RT particles in a harmonic trap. We start with numerical data to highlight the difference in computing $\pi(x)$ from $\Pi$ and $\Phi$. In Fig. \ref{fig:rt_harm1}a we adopt (\ref{pi_1}) that we rewrite as
\begin{align} 
    \pi(x) &= \pi_1(x) + \pi_2(x) \\ \nonumber
\pi_1(x) &\equiv \frac{\Delta^2(x)}{4 D}\left(\frac{1}{R(x)} + \frac{1}{L(x)}\right) \\ \nonumber
\pi_2(x) &\equiv \frac{\alpha Q(x)}{2} \log \frac{R(x)}{L(x)} \; .
\end{align}
In Fig. \ref{fig:rt_harm1}b, we compute $\pi(x)$ through (\ref{pi_2}). We obtain that $\chi^\prime \equiv \partial_x \chi(x)$ plays a fundamental role since it is responsible for the peaks in $\pi$ where particles remain stuck. Finally, we compare $P(x)$ from numerics with the numerical integration of the analytical formula and the corresponding $\pi(x)$, as it is shown in \ref{fig:rt_harm2}a and \ref{fig:rt_harm2}b, respectively. $\pi(x)$ shows a crossover from a triple-peaked to single-piece structure as $\alpha$ increases. This crossover mirrors the behavior of $P(x)$ that changes from double-peaked for $\alpha < \alpha_c$ to single-peaked for $\alpha > \alpha_c$, with $\alpha_c=2 \mu k$. This is because, as $\alpha$ increases, active motion becomes more Brownian-like, and thus particles tend to accumulate at the bottom of the trap instead of at distances where external force balances the self-propulsion. 

%%%%%%%%%%%%%%%%%%%%%%%%%%5%%%%%%%%
\subsection{Piecewise linear potential}
\label{LinPot}
The second case we discuss, which allows an analytical solution, is the piecewise linear potential 
\begin{align}
V(x) &= f_0 |x| \ , \\
f(x)& =\begin{cases}
    - f_0, & \text{if $x>0$} ,\\
    f_0, & \text{if $x<0$}  ,
  \end{cases}
\end{align}
where $f_0>0$ is the force strength.
This case was recently studied in \cite{singh2025}, where an analysis of steady state and relaxation dynamics is reported, along with the expression of the global entropy rate. We discuss here the local EPR in the steady state.
\\
\paragraph*{Stationary solution.}
The steady state equation (\ref{eq_st}) reads
\begin{equation}
\label{SE_lin}
\px \left[ \left(v^2-(D \px +{\text{sgn}}(x) \mu f_0 )^2\right) P(x)\right] + 
\alpha (D \px +{\text{sgn}}(x) \mu f_0 ) P(x) = 0 .
\end{equation}
The solution has the following form
\begin{equation}
\label{P_lin}
    P(x) = A_1 e^{-k_1 |x|} + A_2 e^{-k_2 |x|},
\end{equation}
where the different constants are given in the following (see Appendix \ref{App_Lin} for details).
The quantities $k_1$ and $k_2$ are the absolute values of the two negative solutions of a cubic equation, whose  solutions 
are given by
\begin{equation}
z_n = -\frac23 \frac{\mu f_0}{D} + 2 \sqrt{\frac{p}{3}} \cos{\left[
\frac13 \cos^{-1}\left(
-\frac{3q}{2p}\sqrt{\frac{3}{p}}
\right)
 + \frac23 \pi n
\right]} ,
\qquad {(n=0,1,2)}
\end{equation}
where 
\begin{align}
p &= \frac13 \left( \frac{\mu f_0}{D} \right)^2 + \left( \frac{v}{D}\right)^2 + \frac{\alpha}{D} , \\
q &= \frac{2\mu f_0}{3D} \left[ \left( \frac{v}{D}\right)^2 - \frac{\alpha}{2D} - 
\left( \frac{\mu f_0}{3D} \right)^2 \right] .
\end{align}
The coefficients $A_1$ and $A_2$ are given by
\begin{align}
\label{A1}
    \frac{1}{A_1} &= 2 \left( \frac{1}{k_1} -\frac{1}{k_2} \frac{\mu f_0 - D k_1}{\mu f_0 - D k_2}\right) , \\
    \frac{1}{A_2} &= 2 \left( \frac{1}{k_2} -\frac{1}{k_1} \frac{\mu f_0 - D k_2}{\mu f_0 - D k_1}\right) .
\label{A2}
\end{align}
The PDF (\ref{P_lin}) is shown in Fig. (\ref{fig:rt_lin})a for $\mu=v=1$, $f_0=0.5$, $D=0.1$, and varying $\alpha$.

