\section{Stationary PDF of RT particle in a thermal bath with a piecewise constant speed}
\label{App_Speed}
The PDFs in the two zones, $0<x<\lambda$, where $v(x)=v_1$, and  $\lambda<x<L$, where $v(x)=v_2$,   
have the form 
\begin{equation}
\label{P_i}
    P_i(x) = A_i e^{k_i x} + B_i e^{-k_i x} + C_i , \qquad (i=1,2)
\end{equation}
where
\begin{equation}
\label{k_i}
    D^2 k_i^2 = v_i^2 +\alpha D .
\end{equation}
The six unknown constants ($A_i,B_i,C_i$), with $i=1,2$, are determined by imposing the following conditions on $P_i(x)$
\begin{align}
& P_1(x) = P_1(\lambda -x) , \qquad &\text{for }  x\in(0,\lambda) \qquad &\text{(symmetry in zone 1)} \label{AC1}\\
& P_2(x) = P_2(L+\lambda -x) , \qquad &\text{for } x\in(\lambda,L) \qquad &\text{(symmetry in zone 2)} \label{AC2}\\
& P_1(0) =P_2(L) , & & \text{(continuity of $P$)}   \label{AC3}\\
& \left. \frac{\px P_1(x)}{v_1}\right|_{x=0} = \left. \frac{\px P_2(x)}{v_2}\right|_{x=L} , & &  \text{(continuity of $Q$)}  \label{AC4}\\
& \left[ v_1 P_1(x) - \frac{D^2}{v_1} \px^2 P_1(x)\right]_{x=0} = 
 \left[ v_2 P_2(x) - \frac{D^2}{v_2} \px^2 P_2(x)\right]_{x=L}   & &  \text{(continuity of $\Delta$)}  \label{AC5}\\
& \int_0^\lambda dx\ P_1(x) + \int_\lambda^L dx\ P_2(x) =1, & &  \text{(normalization)}  \label{AC6}
\end{align}
Continuity conditions in $x=\lambda$ are not independent from that on $x=0$, due to the symmetry conditions 
(\ref{AC1}) and (\ref{AC2}). See (\ref{QRL}) and (\ref{DeltaDef}) for the definition of $Q$ and $\Delta$ quantities.
By substituting (\ref{P_i}) in the above equations we get a set of linear equations for the unknown constants.
After some algebra we finally obtain  the expressions
\begin{align}
    A_1 &= \frac{1}{Y_1 - Y_2 - Y_3  Y_4} , \\
    A_2 &= A_1 \frac{v_2 k_1}{v_1 k_2} \frac{1-e^{k_1\lambda}}{e^{k_2L}-e^{k_2\lambda}} , \\
    B_1 &= A_1 e^{k_1\lambda} , \\
    B_2 &= A_2 e^{k_2(L+\lambda)} , \\
    C_1 &= \frac{1-A_1 (Y_3(L-\lambda)+Y_1)}{L} , \\
    C_2 &= \frac{1+A_1 (Y_3 \lambda -Y_1)}{L} ,   
\end{align}
where
\begin{align}
    Y_1 &= \frac{2}{k_1} (e^{k_1\lambda}-1) \left( 1-\frac{v_2 k_1^2}{v_1 k_2^2}\right) , \\
    Y_2 &= \frac{\alpha L D}{v_1 v_2} (1+e^{k_1 \lambda}) , \\
    Y_3 &= 1+e^{k_1 \lambda} - \frac{v_2 k_1}{v_1 k_2} \frac{(1-e^{k_1\lambda})(e^{k_2L}+e^{k_2\lambda})}{e^{k_2L}-e^{k_2\lambda}}  , \\
    Y_4 &= \lambda + \frac{L}{v_2-v_1} \left( \frac{\alpha D}{v_2}+v_1\right) .
\end{align}
In the limit of equal speeds in the two zones, $v_1=v_2$, we have that $Y_4 \to \infty$, resulting in vanishing 
$A_i$ and $B_i$, and $C_i=1/L$ for $i=1,2$. Therefore we obtain the trivial constant PDF $P(x)=1/L$.



