\section{Stationary PDF of RT particles in a thermal bath in harmonic potential}
\label{App_Harm}
We demonstrate that the PDF (\ref{P_harm}), that we report again here for convenience,
\begin{equation}
\label{PhA}
    P(x) = \int_{-\ell}^{+\ell} dy \ P_A(y) \ P_B(x-y) \ , \qquad \ell=v/\mu k \ ,
\end{equation}
with $P_B$ given in (\ref{P_B}) and solution of (\ref{eq_PB}),
$P_A$ given in (\ref{P_AA}) and solution of (\ref{eq_PA}), is solution of the stationary equation 
(\ref{eq_st}) with $f(x)=-kx$.
We first note that, using (\ref{eq_PB})
\begin{align}
    [D\px-\mu f(x)] P_B(x-y) &= \mu [f(x-y)-f(x)] P_B(x-y) 
    \nonumber \\
    &= \mu k y P_B(x-y) \ ,
\end{align}
and 
\begin{equation}
    [D\px-\mu f(x)]^2 P_B(x-y) = (\mu k y)^2 P_B(x-y) \ .
\end{equation}
Then, inserting (\ref{PhA}) in (\ref{eq_st}), we obtain 
\begin{align}
 &   \int_{-\ell}^{+\ell} dy \ P_A(y) \left[
    \px \left(
    (v^2-\mu^2 k^2 y^2) P_B(x-y) 
    \right)
    +\alpha \mu k y P_B(x-y) 
    \right] \nonumber  \\
  = &  \int_{-\ell}^{+\ell} dy \  P_A(y)  (v^2-\mu^2 k^2 y^2)\px  P_B(x-y) 
    +\alpha \mu k \int_{-\ell}^{+\ell} dy \ y P_A(y) P_B(x-y) \nonumber \\
  = & - \int_{-\ell}^{+\ell} dy \ P_A(y)  (v^2-\mu^2 k^2 y^2) \py P_B(x-y) 
    +\alpha \mu k \int_{-\ell}^{+\ell} dy \ y P_A(y) P_B(x-y) \nonumber \\
   = & P_A(y) (v^2-\mu^2 k^2 y^2)P_B(x-y)\Big{|}_{y=-\ell}^{y=\ell}
   +\int_{-\ell}^{+\ell} dy \ P_B(x-y) \py [(v^2-\mu^2 k^2 y^2) P_A(y)] \nonumber \\
   & + \alpha \mu k \int_{-\ell}^{+\ell} dy \ y P_A(y) P_B(x-y) \nonumber \\
  = & - \alpha \mu k \int_{-\ell}^{+\ell} dy \ y P_A(y) P_B(x-y)  
    +\alpha \mu k \int_{-\ell}^{+\ell} dy \ y P_A(y) P_B(x-y)  = 0 \ ,
\end{align}
where boundary terms are zero and we have used (\ref{eq_PA}).
Therefore, the PDF (\ref{PhA}) is the stationary solution of  the run-and-tumble motion
with thermal noise in the presence of harmonic potential.


