\section{Notes on different definitions of entropy}
\label{App_Entropies}
Here we explore different definitions of entropy, which generalize the Gibbs entropy used before \cite{Amigo2018}.

%%%%%%%%%%
\subsection{R\'enyi Entropy}
Given a PDF $P(x,t)$ the R\'enyi entropy $S^R_q$ is defined as follows 
\cite{Renyi1960,Ozawa_2024}
\begin{equation}
    \label{RE}
    S^R_q(t) = \frac{1}{1-q} \log \int dx\ P^q(x,t)  ,
\end{equation}
where $q$ is an index with $q\in(0,+\infty)$.
In the limit $q\to 1$ the R\'enyi entropy tends to the Gibbs entropy
\begin{equation}
    \lim_{q\to 1} S^R_q(t) = - \int dx \ P(x,t) \log P(x,t) .
\end{equation}
For the R\'enyi entropy we cannot define a local entropy 
%\textcolor{red}{[why? meaning ?]}
, but we will be able to introduce a local EPR (see below).\\

In the case of RT particles we can use the above definitions by substituting
$\int dx \to \sum \int dx$, where the sum runs over the internal states ($R$ and $L$
in our 1d case).
We obtain the following definition of R\'enyi entropy for RT particles
\begin{equation}
    S^R_q(t) = \frac{1}{1-q} \log \int dx \ \left( R^q(x,t) + L^q(x,t) \right) .
\end{equation}
The entropy production rate can be calculated using the same procedure followed in the previous sections.
We have that 
\begin{equation}
    \pt S^R_q(t) = \frac{q}{(1-q)N_q(t)} \int dx \ \left( 
    R^{q-1}(x,t)\pt R(x,t) +   L^{q-1}(x,t)\pt L(x,t) 
    \right) ,
\end{equation} 
where 
\begin{equation}
\label{Nq}
    N_q(t) = \int dx \ \left( R^q(x,t) + L^q(x,t) \right) = e^{(1-q) S^R_q(t) }.
\end{equation}
We note that $N_q$ depends only on the time variable (in the stationary regime is constant) and 
in the limit $q\to 1$ we have $N_q \to 1$, resulting in the equivalence between the R\'enyi and Gibbs 
entropy rate in this limit.
%\begin{equation}
%\label{SRTequiv}
%    \pt S^R_q = \frac{1}{N_q} \pt S^T_q , 
%\end{equation}
We can define a local entropy rate as follows
\begin{align}
    \pt s^R_q(x,t) &= \frac{q}{(1-q)N_q(t)}  \left( 
    R^{q-1}(x,t)\pt R(x,t) +   L^{q-1}(x,t)\pt L(x,t) 
    \right)  + \frac{\pt P(x,t)}{(q-1)N_q(t)} \nonumber \\
    & = 
 \frac{1}{(q-1)N_q(t)}  \left[ \left(1-qR^{q-1}(x,t)\right) \pt R(x,t)  + 
  \left( 1-qL^{q-1}(x,t)\right)\pt L(x,t) 
    \right]   , 
\label{LRER}
\end{align}
having used the freedom to add a term whose space intergral is zero (due to the normalization of $P=R+L$).
We chose this expression because it guarantees that, in the limit $q\to 1$, we recover the
correct results of the Gibbs case for local entropy rates (see below).
%I such a way we have that the equivalence (\ref{SRTequiv}) is valid for the local quantites too
%\begin{equation}
%    \pt s^R_q = \frac{1}{N_q} \pt s^T_q .
%\end{equation}
After some algebra, we finally arrive at the expression
\begin{equation}
    \pt s^R_q(x,t) =  \pi^R_q(x,t) - \phi^R_q(x,t) ,
\end{equation}
where the first term is the local R\'enyi EPR (non negative quantity) defined by
\begin{align}
\label{piR}
 \pi^R_q(x,t) &= \frac{q}{DN_q(t)} \left( J_R^2(x,t) R^{q-2}(x,t) + J_L^2(x,t) L^{q-2}(x,t)\right) \\
    &+ \frac{\alpha}{2N_q(t)} \frac{q}{q-1} (R(x,t)-L(x,t)) \left( R^{q-1}(x,t) - L^{q-1}(x,t)\right) , 
\end{align}
and the second term is the local R\'enyi entropy flux
\begin{align}
\label{phiR}
 \phi^R_q(x,t) &= \frac{qv}{DN_q(t)} \left( J_R(x,t) R^{q-1}(x,t) - J_L(x,t) L^{q-1}(x,t)\right) \\
     &+ \frac{q\mu f(x)}{DN_q(t)} \left( J_R(x,t) R^{q-1}(x,t) + J_L(x,t) L^{q-1}(x,t)\right) 
     - \frac{1}{N_q(t)}\px \chi(x,t) ,
\end{align}
where  
\begin{equation}
\label{chiT}
    \chi(x,t) = \frac{J_R(x,t) (q R^{q-1}(x,t)-1) +J_L(x,t) (q L^{q-1}(x,t)-1) }{q-1} .
\end{equation}
For $q \to 1$ the above expressions reduce to those found before, (\ref{pid}), (\ref{phid}) and (\ref{chid}),
referring to the Gibbs entropy.\\
The global EPR $\Pi^R_q$ and entropy flux $\Phi^R_q$ are obtained as space integral of the corresponding local quantities.\\
In the stationary regime we have that
\begin{equation}
 \pi^R_q(x) = \phi^R_q(x) , 
\end{equation}
and, then, we can calculate the local EPR 
through (\ref{piR}) or (\ref{phiR}),
once we know the stationary PDF $P(x)$, solution of (\ref{SPDFeq}),
and using  (\ref{Qde}-\ref{JLde}).
%\begin{align}
%\label{piR}
%    \pi^R_q = \frac{\pi^T_q}{N_q} , \\ 
%    \phi^R_q = \frac{\phi^T_q}{N_q} ,  
%\label{phiR}
%\end{align}
%with  $\chi$ given in (\ref{chiT}).
\\

We can give an explicit expression of the local R\'enyi EPR 
for the case of harmonic potential 
in terms of the quantities defined at the end of section \ref{HarPot}.
We obtain
\begin{equation}
\label{pihpR}
    \pi^R_q(x) = \frac{q}{(2v)^q N_q} \left[
 \frac{M_1^2(x)}{D} \left( Y_+^{q-2}(x) + Y_-^{q-2}(x) \right) +
 \frac{\alpha \mu k I_1(x)}{q-1} \left( Y_+^{q-1}(x) - Y_-^{q-1}(x)\right)
 \right] ,
\end{equation}
where 
\begin{equation}
    N_q = \int \frac{dx}{(2v)^q} \ \left( Y_+^q(x) + Y_-^q(x) \right) .
\end{equation}
For $q\to 1$ we recover the Gibbs expression (\ref{pihp}).

