\subsection{Tsallis Entropy}
Given a PDF $P(x,t)$ the Tsallis entropy $S^T_q$ is defined as follow \cite{Tsallis1988}
\begin{equation}
    \label{TE}
    S^T_q(t) = \frac{1}{q-1} \left( 1 - \int dx\ P^q(x,t) \right) ,
\end{equation}
where $q$ is an index with $q\in(0,+\infty)$.
The Tsallis entropy is known to be a non-additive quantity.
We can define the local ($x$-dependent) entropy as
\begin{equation}
    \label{LTE}
    s^T_q(x,t) = \frac{P(x,t) - P^q(x,t)}{q-1} .
\end{equation}
In the limit $q \to 1$ we recover the Gibbs entropy
\begin{align}
\lim_{q \to 1} s^T_q(x,t) &= - P(x,t) \log P(x,t) , \\
\lim_{q \to 1} S^T_q(t) &= - \int dx \ P(x,t) \log P(x,t) .
\end{align}
It is worth noting that the Tsallis ans R\'enyi entropies are related one each other
through  
\begin{align}
    S^T_q(t) &= \frac{e^{(1-q)S^R_q(t)}-1}{1-q}  , \\
    S^R_q(t) &= \frac{1}{1-q} \log \left( 1 + (1-q) S^T_q(t)\right) .
\end{align}


In the case of RT particles we can define local and global Tsallis entropies as follows
\begin{align}
    s^T_q(x,t) &= \frac{1}{q-1} \left( R(x,t) - R^q(x,t) + L(x,t)-L^q(x,t)  \right) , \\
    S^T_q(t) &= \frac{1}{q-1} \left( 1 - \int dx\ \left( R^q(x,t) + L^q(x,t) \right) \right) .
\end{align}
For the local entropy production rate we have that 
\begin{equation}
    \pt s^T_q(x,t) = \frac{1}{q-1} \left[ 
    (1-qR^{q-1}(x,t))\pt R(x,t) +     (1-qL^{q-1}(x,t))\pt L(x,t) 
    \right] = N_q(t) \pt s^R_q(x,t) , 
\end{equation}
i.e., it can be expressed in terms of the local R\'enyi entropy rate (\ref{LRER}).
We then obtain the following expression
\begin{equation}
    \pt s^T_q(x,t) = \pi^T_q(x,t) - \phi^T_q(x,t) , 
\end{equation}
where the local Tsallis EPR and entropy flux are expressed in terms of (\ref{piR}) and (\ref{phiR})
\begin{align}
\label{piT}
    \pi^T_q(x,t) &= N_q(t) \pi^R_q(x,t) , \\ 
    \phi^T_q(x,t) &= N_q(t) \phi^R_q(x,t) .
\label{phiT}
\end{align}
Therefore, the local Tsallis entropy rates are proportional to the corresponding R\'enyi ones 
with a proportionality (time dependent) factor $N_q(t)$, given in (\ref{Nq}).
The global EPR $\Pi^T_q$ and entropy flux $\Phi^T_q$ are obtained as space integral of the corresponding local quantities.
\\
As before, in the stationary regime we have that
\begin{equation}
 \pi^T_q(x) = \phi^T_q(x) ,
\end{equation}
and we can use one of them to calculate the EPR once we know the exact expression of the PDF $P(x)$.
\\

The explicit expression of the stationary local Tsallis EPR in the case of harmonic potential
is obtained from (\ref{piT}) and (\ref{pihpR}), resulting 
in the same expression of the R\'enyi EPR rescale by the factor $N_q$
\begin{equation}
\label{pihpT}
    \pi^T_q(x) = \frac{q}{(2v)^q} \left[
 \frac{M_1^2(x)}{D} \left( Y_+^{q-2}(x) + Y_-^{q-2}(x) \right) +
 \frac{\alpha \mu k I_1(x)}{q-1} \left( Y_+^{q-1}(x)- Y_-^{q-1}(x)\right)
 \right] .
\end{equation}


