\section{Calculation of \texorpdfstring{$\Edag$}{Edag}}
The action of a CPTP (completely positive trace-preserving) map on an initial system density matrix is
\begin{align}
    \rho_S(t)&=\Edag[\rho_S(0)] \nonumber \\
    &=\Edag\sum_{ij}\rho_{ij}\ket{i}\bra{j} =\sum_{ij}\rho_{ij}\Edag(\ket{i}\bra{j}).
\end{align}
On vectorising this equation, we obtain
\begin{align}\label{rhoStEdag}
    \ket{\rho_S(t)}\rangle=\sum_{ij}\rho_{ij}\ket{\Edag(\ket{i}\bra{j})}\rangle.
\end{align}
Here, we find a matrix $\mathcal{S}$ that represents the above map $\Edag$ in a superoperator space. To this end, we can rewrite the above equation as
\begin{align}
    \ket{\rho_S(t)}\rangle=\mathcal{S}\ket{\rho_S(0)}\rangle.
\end{align}
On decomposing the elements in the above equation, we find
\begin{align}
    \ket{\rho_S(t)}\rangle&=\mathcal{S}\ket{\rho_S(0)}\rangle \nonumber \\
    &=\mathcal{S}\bigg|\sum_{ij}\rho_{ij}\ket{i}\bra{j}\bigg\rangle\bigg\rangle =\mathcal{S}\sum_{ij}\rho_{ij}\big|\ket{i}\bra{j}\big\rangle\big\rangle \nonumber \\
    &=\mathcal{S}\sum_{ij}\rho_{ij}\ket{ij}\rangle =\sum_{ij}\rho_{ij}\mathcal{S}\ket{ij}\rangle.
\end{align}
We change the indices of the vector $\ket{ij}\rangle \to \ket{k}$ for $k = 0, 1, 2, 3$ as $i, j\in\{0, 1\}$, such that $\ket{00}\rangle\to\ket{0}, \ket{01}\rangle\to\ket{1}, \ket{10}\rangle\to\ket{2}$, and $\ket{11}\rangle\to\ket{3}$. Using this, we can rewrite the above equation as
\begin{align}
    \ket{\rho_S(t)}\rangle&=\sum_{k}\rho_{k}\mathcal{S}\ket{k} \nonumber \\
    &=\sum_{k}\rho_{k}\times(\text{$k^{th}$ column of $\mathcal{S}$}).
\end{align}
On comparing this with Eq.~\eqref{rhoStEdag}, we obtain
\begin{align}
     \big|\Edag(\ket{i}\bra{j})\big\rangle\big\rangle\equiv\text{$k^{th}$ column of $\mathcal{S}$},
\end{align}
