\section{Proof: Additional input feature cannot decrease the mutual information}\label{sec:proof-feature-mi-increase}
The mutual information between features $X$ and labels $Y$ is, in the continuous case

\begin{equation}\label{eq:def-mi}
\begin{aligned}
I\left(X;Y\right) =&
\int_{\mathcal{Y}}\int_{\mathcal{X}}P_{\left(X,Y\right)}\left(x,y\right)\cdot 
\\
&\quad \quad \log\left(\frac{P_{\left(X,Y\right)}\left(x,y\right)}{P_{X}\left(x\right)P_{Y}\left(y\right)}\right)dxdy.
\end{aligned}
\end{equation}

We explore the case for traditional spectroscopy, where the input features are solely the energy $X \equiv E$, versus generalized graph based spectroscopy, where $X \equiv \left[E, t, \dots\right]$. Therefore, the two integrals become

\begin{equation}\label{eq:mi-spectroscopy}
\begin{aligned}
I\left(E;Y\right) =& \int_{\mathcal{Y}}\int_{D\left(E\right)}P_{\left(E,Y\right)}\left(\varepsilon,y\right)\cdot 
\\
& \quad \quad \log\left(\frac{P_{\left(E,Y\right)}\left(\varepsilon,y\right)}{P_{E}\left(\varepsilon\right)P_{Y}\left(y\right)}\right)d\varepsilon dy,
\end{aligned}
\end{equation}
where $D\left(E\right)$ is the domain of all possible energies, and

\begin{equation}\label{eq:mi-graph-spectroscopy}
\begin{aligned}
I\left(\left[E, t\right];Y\right) =&  \int_{\mathcal{Y}}\int_{D\left(E\right)}\int_{D\left(t\right)}P_{\left(\left[E, t\right],Y\right)}\left(\left[\varepsilon, \tau\right],y\right)\cdot 
\\
& \log\left(\frac{P_{\left(\left[E, t\right],Y\right)}\left(\left[\varepsilon, \tau\right],y\right)}{P_{\left[E, t\right]}\left(\left[\varepsilon, \tau\right]\right)P_{Y}\left(y\right)}\right)d\tau d\varepsilon dy,
\end{aligned}
\end{equation}
where $D\left(t\right)$ is the domain of all possible times.

From the definition of marginal probability,
\begin{equation}\label{eq:pey-marginal}
P\left(E,Y\right) \equiv \int_{D\left(t\right)} P_{\left(\left[E, t\right], Y\right)}\left(\left[\varepsilon, \tau\right], y\right) d\tau,
\end{equation}
and
\begin{equation}\label{eq:pe-marginal}
P_{E}\left(\varepsilon\right) \equiv \int_{D\left(t\right)} P_{\left[E, t\right]} \left(\left[\varepsilon, \tau \right]\right)d\tau.
\end{equation}
These values are by definition independent of $\tau$, which leads to the fact that
\begin{equation}\label{eq:dpey}
    \frac{\partial P_{\left(E, Y\right)}}{\partial \tau} = 0
\end{equation} and 
\begin{equation}\label{eq:dpe}
    \frac{\partial P_{E}}{\partial \tau} = 0.
\end{equation}
We can move the term to the left of the minus sign in \cref{eq:mi-spectroscopy} inside an integral with respect to $d\tau$ by defining quantities $\tilde{P}_{\left(\left[E,t\right],Y\right)}$ and $\tilde{P}_{\left[E,t\right]}$ which satisfy \cref{eq:pey-marginal,,eq:pe-marginal,,eq:dpey,,eq:dpe}, giving
\begin{equation}\label{eq:mi-spectroscopy-expanded}
\begin{aligned}
I\left(E;Y\right) &=
\int_{\mathcal{Y}}\int_{D\left(E\right)}\int_{D\left(t\right)}\tildepety 
\\
& \log \left(\frac{\tildepety}{\tildepet \pey}\right) d\tau d\varepsilon dy,
\end{aligned}
\end{equation}

We note that both \cref{eq:mi-spectroscopy,,eq:mi-graph-spectroscopy} are of the form
\begin{equation}
    h\left(a, b, c\right) = a\log\left(\frac{a}{bc}\right),
\end{equation}
where $a$ and $b$ may be functions of $\tau$. The Hessian of $h$ with respect to $a$ and $b$ is then
\begin{equation}
    \mathbb{H}\left(h\left(a, b\right)\right) = \left[
    \begin{array}{cc}
        \frac{1}{a} & -\frac{1}{b} \\
        -\frac{1}{b} & \frac{a}{b^{2}}
    \end{array}
    \right]
\end{equation}
which is symmetric and has eigenvalues
\begin{equation}
    \lambda_{1} = 0,
\end{equation}
and
\begin{equation}
    \lambda_{2} = \frac{a^{2} + b^{2}}{ab^{2}},
\end{equation}
which are both non-negative. Therefore $f\left(a, b, c\right)$ is convex with respect to $a$ and $b$, therefore
\begin{equation}\label{eq:convexity}
    f\left(\mathbb{E}\left(a\right), \mathbb{E}\left(b\right), c\right) \geq \mathbb{E}_{a,b}\left(f\left(a, b, c\right)\right).
\end{equation}
The expectation value of $\pety$ is
\begin{equation}
\begin{aligned}
    \mathbb{E}\left(\pety\right) = \\ 
    \frac{1}{V\left(t\right)}\int_{D\left(t\right)} \pety d\tau,
\end{aligned}
\end{equation}
and the expectation value of $\pet$ is 
\begin{equation}
    \mathbb{E}\left(\pet\right) = \frac{1}{V\left(t\right)}\int_{D\left(t\right)} \pet d\tau,
\end{equation}
where $V\left(t\right)$ is the volume of the domain of $t$. Then, from \cref{eq:mi-spectroscopy-expanded},
\begin{equation}\label{eq:i-ey-expect}
\begin{aligned}
    I\left(E;Y\right) = \int_{\mathcal{Y}}\int_{D\left(E\right)} V\left(t\right)\\
    \mathbb{E}_{a,b}\left(f\left(\pety, \pet,\right.\right.\\
    \left.\left.\pey\right)\right)d\varepsilon dy,
\end{aligned}
\end{equation}
and from \cref{eq:mi-graph-spectroscopy},
\begin{equation}\label{eq:i-ety-expect}
\begin{aligned}
    I\left(\left[E, t\right];Y\right) = \int_{\mathcal{Y}}\int_{D\left(E\right)}V\left(t\right)\\
    f\left(\mathbb{E}\left(\pety\right),\mathbb{E}\left(\pet\right),\right. \\\left.\pey\right) d\varepsilon dy.
\end{aligned}
\end{equation}

The integrand in \cref{eq:i-ey-expect} is clearly bounded above by that in \cref{eq:i-ety-expect} from the property of convexity in \cref{eq:convexity}. Therefore, the overall integral in \cref{eq:i-ey-expect} is bounded above by the overall integral in \cref{eq:i-ey-expect}. This proves that the mutual information between simple spectroscopic data must always be equal or less than that in graph spectroscopic data. By defining $t$ and its domain $D\left(t\right)$ generally, this proof can be extended to additional information of any type or dimension.  


