\title[Coupled Nonlinear Schr\"odinger-Type Equations ]{Bifurcation Analysis, Modulational Instability  and Solitons Solutions for a Coupled Nonlinear Schr\"odinger-Type Equations with Variable Coefficients}
\author{José M. Escorcia }
\address{Escuela de Ciencias Aplicadas e Ingenier\'ia, Universidad EAFIT, Carrera 49 No. 7 Sur-50, Medellín 050022, Colombia.}
\email{jmescorcit@eafit.edu.co}


