\section{Explicit Solutions for the Coupled NLS System} \label{Sect3}
In the current section, the goal is to use the system's Hamiltonian structure (\ref{PlanarSystem}) to prove the existence (by the explicit construction) of Jacobi elliptic solutions. The discovery of such solutions will prove that the system has perfect intrinsic mechanisms for generating plane waves, modulated periodic waves, and solitons. 

To accomplish the aim, let us note that the system (\ref{PlanarSystem}) is equivalent to the following  Hamilton's equations 
\begin{equation}
   \frac{\partial H}{\partial P} = G^{\prime}, \quad \quad   \frac{\partial H}{\partial G} = -P^{\prime},
\end{equation}
where the Hamiltonian has the form
$$H(G,P) = \frac{1}{2}P^2 -\frac{g_0}{2}G^2 - \frac{h_0}{2}G^4.$$
Now, we consider the surface  
$$H(G,P) = \frac{1}{2}P^2 -\frac{g_0}{2}G^2 - \frac{h_0}{2}G^4 = H_0, \quad \quad (H_0 \ \mbox{is}  \ \mbox{a} \ \mbox{constant}),$$
and we will demonstrate how the various kinds of solutions rely on the values of $H_0.$ 

\begin{enumerate}
    \item[]{\textbf{Case 1: Consider $h_0 < 0$ and $g_0 > 0.$} \\
    $(a).$ Assume that $H_0 \in \left(\dfrac{g_0^2}{8h_0},0\right),$ then the Hamiltonian possesses four distinct real roots (corresponding to points on the closed orbits) and it can be expressed as: 
    \begin{equation}
        P^2 = g_0G^2 + h_0G^4 + 2H_0 =  -h_0\left(G^2 - G_{1H_0}^2\right)\left(G_{2H_0}^2 - G^2\right), \label{Hamilt2}
    \end{equation} 
    where
    \begin{equation}
        G_{1H_0}^2 = \frac{g_0 - \sqrt{g_0^2-8h_0H_0}}{-2h_0}, \quad \quad  G_{2H_0}^2 = \frac{g_0 + \sqrt{g_0^2-8h_0H_0}}{-2h_0}.
    \end{equation}
    Now, by remembering the definition of $P$, and integrating the equation (\ref{Hamilt2}),  we have
\begin{equation}
    \int_{-G_{2H_0}}^G \frac{ds}{\sqrt{\left(s^2 - G_{1H_0}^2\right)\left(G_{2H_0}^2 - s^2\right)}} = \pm \sqrt{-h_0}(\xi - \xi_0), \label{IntEllip1}
\end{equation}
    \begin{equation}
    \int_{G}^{G2H_0} \frac{ds}{\sqrt{\left(s^2 - G_{1H_0}^2\right)\left(G_{2H_0}^2 - s^2\right)}} = \mp \sqrt{-h_0}(\xi - \xi_0), 
\end{equation}
   where $\xi_0$ is a constant. The integral in (\ref{IntEllip1}) (and similarly the second integral) can be written as
   \begin{equation}
      \int_{-G_{2H_0}}^G \frac{ds}{\sqrt{\left(s^2 - G_{1H_0}^2\right)\left(G_{2H_0}^2 - s^2\right)}} = -\frac{1}{G_{2H_0}}\int_{1}^{-G/G_{2H_0}}\frac{ds}{\sqrt{(1-s^2)(s^2-\hat{l}^2)}},
   \end{equation}
   with $\hat{l}^2 = 1-l^2,$ and $l = \frac{\sqrt{G_{2H_0}^2 - G_{1H_0}^2}}{G_{2H_0}}.$ Therefore, by the definition of the \emph{delta amplitude function} $\dn(u;l)$, we obtain the explicit solutions for the coupled NLS equations
   \begin{equation}
    \psi(x,t) = \pm G_{2H_0}\dn\left( G_{2H_0}\sqrt{-h_0}(\beta(t)x + 2\gamma(t)-\xi_0); \frac{\sqrt{G_{2H_0}^2 - G_{1H_0}^2}}{G_{2H_0}}  \right)e^{i\theta(x,t)},  \label{Sol1a}
   \end{equation}
\begin{equation}
    \varphi(x,t) = \pm G_{2H_0}\dn\left( G_{2H_0}\sqrt{-h_0}(\beta(t)x + 2\gamma(t)-\xi_0); \frac{\sqrt{G_{2H_0}^2 - G_{1H_0}^2}}{G_{2H_0}}  \right)e^{-i\theta(x,t)}.  \label{Sol1b}
   \end{equation}
   $(b).$ In this case, we consider $H_0 = 0.$ Then, the roots of the Hamiltonian are $G_{1H_0}^2 = 0$ and $G_{2H_0}^2 = -g_0/h_0$ (corresponding to points on the homoclinic). Following the same reasoning of above, we find the bell-shaped solutions (using that $\dn(u,1) = \sech(u)$)
\begin{equation}
    \psi(x,t) = \pm \sqrt{-g_0/h_0}\sech\left( \sqrt{g_0}(\beta(t)x + 2\gamma(t)-\xi_0) \right)e^{i\theta(x,t)}, \label{Sol2a} 
   \end{equation}
\begin{equation}
    \varphi(x,t) = \pm \sqrt{-g_0/h_0}\sech\left( \sqrt{g_0}(\beta(t)x + 2\gamma(t)-\xi_0) \right)e^{-i\theta(x,t)}.  \label{Sol2b}
   \end{equation}
$(c).$ Consider that $H_0 = \dfrac{g_0^2}{8h_0}$. Under this condition $H(G,P)$ vanishes at the fixed points, i.e., $G_{1H_0}^2 = G_{2H_0}^2 = -g_0/2h_0.$ Therefore, the coupled NLS system (\ref{Eq1a})-(\ref{Eq1b}) admits the following plane wave solutions:
\begin{equation}
    \psi(x,t) = \pm \sqrt{-g_0/2h_0}e^{i\theta(x,t)} \label{Sol3a} 
   \end{equation}
\begin{equation}
    \varphi(x,t) = \pm \sqrt{-g_0/2h_0}e^{-i\theta(x,t)}.  \label{Sol3b}
   \end{equation}
$(d).$ Assume that $H_0>0$. In such case, we are considering the super periodic orbits of the system. Then, the Hamiltonian can be written as
\begin{equation}
        P^2 =  -h_0\left(G^2 + G_{3H_0}^2\right)\left(G_{2H_0}^2 - G^2\right), \label{Hamilt3}
    \end{equation} 
    where
    \begin{equation}
        G_{3H_0}^2 = \frac{-g_0 + \sqrt{g_0^2-8h_0H_0}}{-2h_0}.
    \end{equation}
Integrating the equation (\ref{Hamilt3}), we get
\begin{equation}
    \int_{G_{2H_0}}^G \frac{ds}{\sqrt{\left(s^2 + G_{3H_0}^2\right)\left(G_{2H_0}^2 - s^2\right)}} = \pm \sqrt{-h_0}(\xi - \xi_0). \label{IntEllip2}
\end{equation}
Note that the last integral is equivalent to
{\footnotesize
\begin{equation}
    \int_{G_{2H_0}}^G \frac{ds}{\sqrt{\left(s^2 + G_{3H_0}^2\right)\left(G_{2H_0}^2 - s^2\right)}} = \frac{1}{\sqrt{G_{2H_0}^2 + G_{3H_0}^2}} \int_{1}^{G/G_{2H_0}} \frac{ds}{\sqrt{\left(1-s^2\right)\left(\hat{l}^2 + l^2 s^2\right)}},
\end{equation}}
with $l^2 = \frac{G_{2H_0}^2}{G_{2H_0}^2 + G_{3H_0}^2}$ and $\hat{l}^2  = 1 -l^2.$ In these terms, we can construct the following Jacobian elliptic solutions
{\footnotesize
\begin{equation}
    \psi(x,t) = \pm G_{2H_0} \cn\left(\sqrt{-h_0}\sqrt{G_{2H_0}^2 + G_{3H_0}^2}(\beta(t)x + 2\gamma(t) - \xi_0); \frac{G_{2H_0}}{\sqrt{G_{2H_0}^2 + G_{3H_0}^2}}\right) e^{i\theta(x,t)}, \label{Sol4a} 
   \end{equation}
\begin{equation}
    \varphi(x,t) = \pm G_{2H_0} \cn\left(\sqrt{-h_0}\sqrt{G_{2H_0}^2 + G_{3H_0}^2}(\beta(t)x + 2\gamma(t) - \xi_0); \frac{G_{2H_0}}{\sqrt{G_{2H_0}^2 + G_{3H_0}^2}}\right) e^{-i\theta(x,t)}, \label{Sol4b}
   \end{equation}}
where $\cn(u;l)$ is the \emph{cosine amplitude function}.
}
 \item[]{\textbf{Case 2: Consider $h_0 > 0$ and $g_0 < 0.$} \\
 $(a).$ Firstly, assume that $H_0 \in \left(0,\dfrac{g_0^2}{8h_0}\right).$ Then, 
\begin{equation}
        P^2 =  h_0\left(G^2 - G_{1H_0}^2\right)\left( G^2-G_{2H_0}^2 \right), \label{Hamilt4}
    \end{equation} 
with 
\begin{equation}
        G_{1H_0}^2 = \frac{-g_0 - \sqrt{g_0^2-8h_0H_0}}{2h_0}, \quad \quad  G_{2H_0}^2 = \frac{-g_0 + \sqrt{g_0^2-8h_0H_0}}{2h_0}. 
    \end{equation}
Now, integrating the equation (\ref{Hamilt4}), we have
{\footnotesize
\begin{equation}
    \int_{0}^G \frac{ds}{\sqrt{\left(G_{1H_0}^2 -s^2\right)\left(G_{2H_0}^2 - s^2\right)}} = \frac{1}{G_{2H_0}}\int_{0}^{G/G_{1H_0}} \frac{ds}{\sqrt{\left(1-s^2\right)\left(1 - l^2 s^2\right)}} = \pm \sqrt{h_0}(\xi-\xi_0),
\end{equation}}
where $l = \frac{G_{1H_0}}{G_{2H_0}}.$ We  conclude that the system (\ref{Eq1a})-(\ref{Eq1b}) admits  solutions in terms of the \emph{sine amplitude function} $\sn(u;l)$, i.e.,
{\small
\begin{equation}
    \psi(x,t) = \pm G_{1H_0} \sn\left(\sqrt{h_0}G_{2H_0}(\beta(t)x + 2\gamma(t) - \xi_0); \frac{G_{1H_0}}{G_{2H_0}}\right) e^{i\theta(x,t)}, \label{Sol5a} 
   \end{equation}
\begin{equation}
    \varphi(x,t) = \pm G_{1H_0} \sn\left(\sqrt{h_0}G_{2H_0}(\beta(t)x + 2\gamma(t) - \xi_0); \frac{G_{1H_0}}{G_{2H_0}}\right) e^{-i\theta(x,t)}.\label{Sol5b}
   \end{equation}}
$(b).$ In this case, let us assume that $H_0 = \dfrac{g_0^2}{8h_0}.$ The roots of the Hamiltonian are $G_{1H_0}^2 = G_{2H_0}^2 = -\frac{g_0}{2h_0}$ (corresponding to points on the heteroclinic orbit). Therefore, we obtain the equality
\begin{equation}
    \int_{0}^G \frac{ds}{\sqrt{\left(\frac{g_0}{2h_0} +s^2\right)^2}} = \frac{1}{\sqrt{-g_0/2h_0}}\int_{0}^{\sqrt{-2h_0/g_0}G }\frac{ds}{\sqrt{\left(1-s^2\right)^2}} = \pm \sqrt{h_0}(\xi-\xi_0).
\end{equation}
Using the identity $\sn(u;1) = \tanh(u),$ we find the solutions
\begin{equation}
    \psi(x,t) = \pm \sqrt{-g_0/2h_0} \tanh\left(\sqrt{-g_0/2}(\beta(t)x + 2\gamma(t) - \xi_0)\right) e^{i\theta(x,t)}, \label{Sol6a} 
   \end{equation}
\begin{equation}
    \varphi(x,t) = \pm \sqrt{-g_0/2h_0} \tanh\left(\sqrt{-g_0/2}(\beta(t)x + 2\gamma(t) - \xi_0)\right) e^{-i\theta(x,t)}.\label{Sol6b}
   \end{equation}
}
\end{enumerate}
The profile of some solutions is shown in Figure \ref{Fig3}. Only $|\psi|^2$ is displayed, since the profile of the other component, $\varphi$, exhibits identical behavior. A noteworthy point, evident from the previously reported solutions, is that the amplitude and width of the solutions can be effectively controlled through the parameters $g_0$ and $h_0$. This characteristic could be particularly useful in certain physical applications, for example, where the external linear potential $g(t)$ could be used to manipulate the number of particles in a Bose-Einstein condensate.


