A $\Sigma$-\emph{theory} $\T$ is the class of all $\Sigma$-interpretations that satisfy a set of sentences $\ax(\T)$ called the axiomatization of $\T$. We call them {\em $\T$-interpretations}.
A formula satisfied by a $\T$-interpretation is said to be $\T$-\emph{satisfiable} (or simply satisfiable if $\T$ includes all $\Sigma$-interpretations), 
and if $\varphi$ is satisfied by all $\T$-interpretations it is said to be {\em $\T$-valid}, and we write $\vDash_{\T}\varphi$.
Two formulas are said to be $\T$-\emph{equivalent} if they are satisfied by precisely the same $\T$-interpretations.
A standard result that we will use is the L{\"o}wenheim--Skolem theorem.

\begin{theorem}[\cite{Monzano93}] \label{LowenheimSkolem}
    If  $\Sigma$ is countable and $\Gamma$ 
    is a satisfiable set of $\Sigma$-formulas, there is a $\Sigma$-interpretation $\B$ with $\B\vDash\Gamma$ and $|\s^{\B}|\leq \aleph_{0}$ for all $\s\in\S_{\Sigma}$.
\end{theorem}


\subsection{Theory combination properties}
In what follows, $\Sigma$ is a signature
and $\T$ is a $\Sigma$-theory.
$\T$ is \emph{decidable} if 
the set $\{\varphi\in\qf{\Sigma}\mid\varphi\text{ is } \T\text{-satisfiable}\}$ 
is decidable, where $\qf{\Sigma}$ is the set of quantifier-free formulas over $\Sigma$.
$\T$ is \emph{convex} \cite{NelsonOppen} \wrt $S$ if $\vDash_{\T}\varphi\rightarrow\bigvee_{i=1}^{n}x_{i}=y_{i}$
implies
$\vDash_{\T}\varphi\rightarrow x_{i}=y_{i}$ for some $1\leq i\leq n$, where
$\varphi$ is a conjunction of literals and $x_{i}$ and $y_{i}$ have sorts in $S$.


$\T$ is \emph{stably infinite} \cite{OppenSI} (respectively, has the \emph{finite model property}) \wrt $S\subseteq\S_{\Sigma}$ if for every $\T$-satisfiable $\varphi\in\qf{\Sigma}$,
there is a $\T$-interpretation $\A$ with $\A\vDash\varphi$ such that for every $\s\in S$, $|\s^{\A}|\geq\aleph_{0}$ 
(respectively, $|\s^{\A}|<\aleph_{0}$).
%
$\T$ is \emph{smooth} \cite{RanRinZar} \wrt $S$ if for every quantifier-free formula $\varphi$, $\T$-interpretation $\A$ with $\A\vDash\varphi$, and function $\kappa$ from $S$ to the class of all cardinals such that $\kappa(\s)\geq |\s^{\A}|$ for every $\s\in S$, there is a $\T$-interpretation $\B$ with $\B\vDash\varphi$ and $|\s^{\B}|=\kappa(\s)$ for all $\s\in S$.
If we add the assumption that $\kappa(\s)<\aleph_{0}$
for every $\s\in\S_{\Sigma}$,
the resulting property is called \emph{finite smoothness} \cite{nounicorns}.
%
$\T$ is \emph{stably finite} \cite{RanRinZar}
if for every quantifier-free formula $\varphi$ and $\T$-interpretation $\A$ with $\A\vDash\varphi$
there is a $\T$-interpretation $\B$ with $\B\vDash\varphi$, and $|\s^{\B}|<\aleph_{0}$ and $|\s^{\B}|\leq |\s^{\A}|$ for all $\s\in S$.

Take a finite set of variables $V$ and an equivalence relation $E$ on $V$ such that, if $x$ and $y$ are of different sorts, then $x{\cancel{E}}y$ (where $\cancel{E}$ is the complement of $E$). 
We define the \emph{arrangement} induced by $E$ on $V$, denoted by $\delta_{V}^{E}$ or $\delta_{V}$ if explicitly mentioning $E$ is not necessary, as the conjunction of the literals $x=y$ if $xEy$, and $\neg(x=y)$ if $x\cancel{E}y$.

$\T$ is \emph{finitely witnessable} \cite{RanRinZar} \wrt $S$ if it has a {\em witness} $\wit:\qf{\Sigma}\rightarrow\qf{\Sigma}$, which is a computable function 
such that for any quantifier-free formula $\varphi$:
$\varphi$ and $\Exists{\overarrow{x}}\wit(\varphi)$ are $\T$-equivalent, where $\overarrow{x}=\vars(\wit(\varphi))\setminus\vars(\varphi)$;
and, if $\wit(\varphi)$ is $\T$-satisfiable, there is a $\T$-interpretation $\A$ with $\A\vDash\varphi$ and $\s^{\A}=\vars_{\s}(\wit(\varphi))^{\A}$ for each $\s\in S$.
$\T$ is \emph{strongly finitely witnessable} \cite{DBLP:conf/frocos/BarrettDS02} \wrt $S$ if it has a strong witness, which is a witness that satisfies, for every quantifier-free formula $\varphi$, finite set of variables $V$ whose sorts are in $S$, and arrangement $\delta_{V}$ in $V$, if $\wit(\varphi)\wedge\delta_{V}$ is $\T$-satisfiable, then there exists a $\T$-interpretation $\A$ with $\A\vDash\wit(\varphi)\wedge\delta_{V}$ and $\s^{\A}=\vars_{\s}(\wit(\varphi)\wedge\delta_{V})^{\A}$ for each $\s\in S$.
$\T$ is \emph{polite}, respectively \emph{strongly polite}, \wrt $S$ if it is smooth and finitely witnessable \wrt $S$, respectively smooth and strongly finitely witnessable.




A \emph{minimal model function} \cite{shiny,LPAR} \wrt $S\subseteq\S_{\Sigma}$ for $\T$ is a function that takes $\varphi\in\qf{\Sigma}$ and returns a set $\minmod_{\T}(\varphi)$ of functions $\textbf{n}$ from $S$ to the class of all cardinals such that, if $\varphi$ is $\T$-satisfiable:
for every $\textbf{n}$ in $\minmod_{\T}(\varphi)$, there exists a $\T$-interpretation $\A$ with $\A\vDash\varphi$ and $\textbf{n}(\s)=|\s^{\A}|$ for all $\s\in S$;
if $\textbf{m},\textbf{n}\in\minmod_{\T}(\varphi)$ and $\textbf{m}\neq\textbf{n}$, there exists $\s\in S$ such that $\textbf{m}(\s)<\textbf{n}(\s)$;
and for every $\T$-interpretation $\A$ that satisfies $\varphi$, there exists $\textbf{n}\in\minmod_{\T}(\varphi)$ such that $\textbf{n}(\s)\leq |\s^{\A}|$ for all $\s\in S$.
$\T$ is called \emph{shiny} \wrt $S$ if it is smooth, stably finite, and has a computable minimal model function, all \wrt $S$.

$\T$ is a {\em Unicorn $1.0$ theory} \wrt $S$ if it is stably infinite,
strongly finitely witnessable but not smooth, all \wrt $S$.
It is a {\em Unicorn $2.0$ theory} \wrt $S$ if it is
strongly finitely witnessable but does not have a computable minimal model function, both  \wrt $S$ \cite{LPAR}.
It is a {\em Unicorn $3.0$ theory} \wrt $S$ if it is
polite and shiny, but is not strongly polite, all \wrt $S$ \cite{LPAR}.

We have the following theorem:
\begin{theorem}[{\cite{harrison,DBLP:journals/jar/Tinelli03}}]
\label{thm:hornconvex}
If $\ax(\T)$ consists solely of Horn 
clauses, then $\T$ is convex.
\end{theorem}



\section{Shiny theories are always decidable (and strongly polite)}
\label{sec:no-u-3}

In \cite{CasalRasga2}, it was proven that for decidable 
theories, strong politeness and shininess are equivalent:

\begin{theorem}[{\cite[Theorem~3.10]{CasalRasga2}}]
\label{thm:casalrasga}
A decidable theory is strongly polite \wrt a finite set $S$ of sorts if and only if it is shiny \wrt $S$.
\end{theorem}

In this section, we show that the right-to-left direction holds without assuming decidability.
Moreover, the reason for this is that shiny theories are in fact always decidable. 

Now, it is important to clarify that the definition
of shininess in \cite{CasalRasga2} is slightly different from ours (which comes from \cite{LPAR}):
in~\cite{CasalRasga2}, the minimal model function of a $\Sigma$-theory $\T$ is only defined 
over $\T$-satisfiable $\Sigma$-formulas. 
With this definition, we cannot ask whether the minimal model function is computable for undecidable theories, since its domain is an undecidable set. 
In \cite{LPAR}, a more general definition was found, that would apply also to undecidable theories. 
Thus, the domain of the minimal model function is all quantifier-free formulas, although the function can return anything for unsatisfiable formulas. 
This is natural: without knowing that a formula is $\T$-satisfiable, we may still be able to determine the size of its minimal model in case it is $\T$-satisfiable. However, this is not the only way one could have generalized the definition to undecidable theories; one could have instead allowed the minimal model function to be \emph{partial}, so that the algorithm computing it may not terminate for unsatisfiable formulas. That said, we follow \cite{LPAR} in requiring the minimal model function to be total, an assumption we make essential use of.

With our definition, it makes sense to ask whether an undecidable theory is shiny. We show that the answer is always no: every shiny theory is decidable. In fact, we show something stronger,
namely, that smoothness does not need to be assumed, but can be replaced by
stable infiniteness.

\begin{restatable}{theorem}{sisfcmdec} \label{thm-shiny-imp-decidable}
    If a theory $\T$ is stably infinite, stably finite, and has a computable minimal model function, all with respect to a non-empty set of sorts $S$, then $\T$ is decidable.
\end{restatable}

Note that all the assumptions of the theorem are necessary:
decidability does not follow from stable infiniteness and stable finiteness alone, and also not from either of them combined with the computability of the minimal model function.
For more details on this, see \Cref{rem:tighteq} of \Cref{sec:completepic} below, where concrete examples are given.


\Cref{thm-shiny-imp-decidable} implies that shiny theories are decidable, since smoothness is a stronger property than stable infiniteness. 
%
As a corollary, we see that shininess implies strong politeness:
\begin{corollary} \label{thm-unicorn3}
    If a theory is shiny with respect to a finite set of sorts $S$, then it is strongly polite with respect to $S$.
\end{corollary}



The fact that
shininess implies politeness solves a problem that was left open
in \cite{LPAR}.
In that paper, it was left undetermined whether there exist
Unicorn 3.0 theories, that is, theories that are polite and shiny,
but not strongly polite.
In particular, such theories, if exist, must be shiny
without being strongly polite.
But \Cref{thm-unicorn3} tells us that such theories do not exist.


\begin{corollary}
\label{cor:nounicorns3}
There are no Unicorn 3.0 theories.
\end{corollary}



\section{Some strongly polite theories are not shiny}\label{sec:uni2}

In this section, we study the following question, which is the converse
of the question from \Cref{sec:no-u-3}.

\begin{description}
    \item[$(\ast)$] Does strong politeness imply shininess?
\end{description}


By \Cref{thm:casalrasga,thm-shiny-imp-decidable}, this is equivalent to asking whether strong politeness implies decidability. Similarly to \Cref{sec:no-u-3}, this is also related to a question
left open in \cite{LPAR}:
the existence
of strongly finitely witnessable theories 
that do not have a
computable minimal model function, a.k.a.
Unicorn 2.0 theories.
If such theories do not exist,
then the answer to $(*)$ would be positive.
%
In contrast, if such theories exist, this is still not enough
to provide a negative answer:
Unicorn 2.0 theories are definitely not shiny, since they do not
have a computable minimal model function.
But, they are only required to be strongly finitely witnessable,
and not necessarily smooth.
Thus, if a Unicorn 2.0 theory is found that is not smooth,
this does not help us with determining the answer for $(*)$.
In fact, thanks to \cite[Theorem~2]{nounicorns},
we know that every strongly finitely witnessable theory
that is also stably infinite is strongly polite (over countable signatures).
Thus, a negative answer to $(\ast)$ can be obtained
by finding a Unicorn 2.0 theory that is also stably infinite.

As part of our strategy to resolve $(\ast)$,
we make a detour into the land of Unicorn 2.0 theories. One of the goals of \cite{LPAR} was
to determine the feasibility of all Boolean combinations of model-theoretic properties 
studied there. 
After \Cref{sec:no-u-3}, we are closer to the end of that project, as it determined
the feasibility of Unicorn 3.0 theories.
To fully complete that project, we need to determine the feasibility of 10 different kinds of Unicorn 2.0 theories. Two of them, over empty signatures, will be shown to be impossible in \Cref{sec:noemptyu2}. The remaining eight cases, all over non-empty signatures, are in fact possible, which we demonstrate in \Cref{sec:nonemptyunicorn2.0}. Specifically, we prove that in non-empty signatures there are Unicorn 2.0 theories
with all the possible combinations
of the following properties:
$(1)$~being defined over a one-sorted (or many-sorted signature);
$(2)$~being stably infinite (or not stably infinite); and
$(3)$~being convex (or not convex).
In total, we present $8$ Unicorn 2.0 theories. 
Since they include stably infinite ones, we obtain in \Cref{sec:backtoorig}
a positive answer to $(\ast)$.
We conclude this section by completing the picture
of strong politeness, shininess, and decidability,
by showing which combinations of these properties are possible
in \Cref{sec:completepic}.

\subsection{Unicorns $2.0$ over empty signatures}
\label{sec:noemptyu2}

We prove that there are no Unicorn 2.0 theories over empty signatures
with finitely many sorts.

We start by proving that all theories that are based on empty signatures
with finitely many sorts are decidable. 

\begin{restatable}{lemma}{empsigimpdec}\label{empsigimpDEC}
If $\Sigma$ is an empty signature with finitely many sorts and $\T$ is a $\Sigma$-theory, then $\T$ is decidable.
\end{restatable}

\begin{proof}[Proof sketch]
    Let $\{\s_{1},\ldots,\s_{n}\}$ be the sorts of $\Sigma$.
    Using a result very similar to Dickson's lemma \cite{Dickson}, which states a subset of $\mathbb{N}^{n}$ has only finitely many minimal elements, we obtain $\T$ has only finitely many  interpretations $\A$ such that $(|\s_{1}^{\A}|,\ldots,|\s_{n}^{\A}|)$ is maximal.
    Because the signature is empty, to check whether $\varphi$ is $\T$-satisfiable it is then enough to test whether $\varphi$ has an interpretation $\B$ in equational logic such that $|\s_{i}^{\B}|\leq |\s_{i}^{\A}|$ for all $1\leq i\leq n$.
\end{proof}


Now, let us go back to \Cref{thm:casalrasga}.
The proof of the left-to-right direction
assumes decidability, strong finite witnessability and smoothness,
and proves stable finiteness and the computability of the minimal model
function.
A closer look at the proof reveals that when proving computability of the minimal model function, smoothness is not used.
We can therefore obtain the following lemma, that was nevertheless
not mentioned explicitly in \cite{CasalRasga2}:

\begin{restatable}{lemma}{decandsfwimpliescmmf}\label{DECandSFWimpliesCMMF}
    If $\T$ is decidable and strongly finitely witnessable with respect to $S$, then it has a computable minimal model function with respect to $S$.
\end{restatable}

Combining these two lemmas, we obtain that there are no Unicorn $2.0$ theories over an empty signature with finitely many sorts.

\begin{corollary}
\label{thm:no2.0emp}
    If $\Sigma$ is an empty signature with finitely many sorts, and $\T$ is a $\Sigma$-theory strongly finitely witnessable with respect to $S\subseteq \S_{\Sigma}$, then it has a computable minimal model function with respect to $S$.
\end{corollary}

