\section{Extended preliminaries}
We will make use of the following well-known result (see, e.g., \cite{Monzano93}).

\begin{theorem}[\cite{Monzano93}] \label{compactness}
    Given a signature $\Sigma$ and a set $\Gamma$ of $\Sigma$-formulas, $\Gamma$ is satisfiable if, and only if, every finite $\Gamma_{0}\subseteq \Gamma$ is satisfiable.
\end{theorem}


\section{Proof of \Cref{thm-shiny-imp-decidable}}

\sisfcmdec*

\begin{proof}
    If $\T$ is inconsistent, then it is trivially decidable, so suppose $\T$ is consistent.
    Let $\s \in S$. Then, $\T$ is stably infinite, stably finite, and has a computable minimal model function, all with respect to $\{\s\}$. Indeed, if $\varphi$ is a $\T$-satisfiable quantifier-free formula, then it has an interpretation $\A$ in which $\s^\A$ is infinite, so $\T$ is stably infinite with respect to $\{\s\}$. Similarly, $\T$ is stably finite with respect to $\{\s\}$. If $\minmod_\T$ is a minimal model function with respect to $S$, then $\minmod'_\T(\varphi) = \min \{\textbf{n}(\s) \mid \textbf{n} \in \minmod_\T(\varphi)\}$ is a minimal model function with respect to $\{\s\}$.


    We describe a decision procedure for satisfiability as follows. Let $\varphi$ be a quantifier-free formula, and let $k = \minmod'_\T(\varphi)$. Since $\T$ is stably finite with respect to $\{\s\}$, we have $k \in \No$.

    If $\varphi$ is $\T$-satisfiable, then it has a model of size $k$, but no smaller models. Let $x_{1},\ldots,x_{k+1}$ be fresh variables (i.e., not occurring in $\varphi$) of sort $\s$. Then, since $\T$ is stably infinite with respect to $\{\s\}$, the formula $\neq^{\s}(x_{1},\ldots,x_{k+1})$ is $\T$-satisfiable, and its smallest model has size greater than $k$. Therefore, $$\minmod'_\T(\varphi \lor \neq^{\s}(x_{1},\ldots,x_{k+1})) = k$$ if and only if $\varphi$ is $\T$-satisfiable. Since $\minmod'_\T$ is computable, this gives a decision procedure
    for $\T$-satisfiability.
\end{proof}
\section{Proof of \Cref{empsigimpDEC}}

The following is a version of what is known as Dickson's lemma, see \cite{Dickson};
although the proof is quite standard, we still write it down for completeness' sake.

\begin{lemma}\label{dicksonlemma}
    Let $n$ be a natural number, and consider any subset $A$ of $\N^{n}$ equipped with the order such that $(p_{1},\ldots,p_{n})\leq (q_{1}, \ldots, q_{n})$ iff $p_{i}\leq q_{i}$ for all $1\leq i\leq n$:\footnote{Of course, $\aleph_{0}>n$ for all $n\in\mathbb{N}$.} 
    then $A$ possesses at most a finite number of maximal elements under this order.
\end{lemma}

\begin{proof}
    We will prove the result by induction on $n$, it being obviously true if $n=1$. 
    As induction hypothesis assume our statement is true for $n$, and we shall prove it also holds for $n+1$. 
    Notice that if we write $A$ as the union of sets $A_{k}$, then a maximal element of $A$ that is in $A_{k}$ continues to be maximal;
    so, if we find a partition of $A$ into finitely many components, and where each component has finitely many maximal elements, this will mean that $A$ has only finitely many maximal elements.
    First, consider the subsets of $A$ of the form $\{\textbf{p}=(p_{1},\ldots,p_{n+1}) : p_{i}=\aleph_{0}\}$, for some $1\leq i\leq n$;
    we can consider them as subsets of $\N^{n}$ by removing the $i$-th coordinate, meaning they have finitely many maximal elements. 
    Notice as well that there are only $n+1$ of these sets.

    Now, we only need to prove that $A\cap \mathbb{N}^{n+1}$ has finitely many maximal elements as well.
    To that end, fix a maximal element $\textbf{p}=(p_{1}, \ldots , p_{n}, p_{n+1})$ of $A\cap \mathbb{N}^{n+1}$ (if there are none, we are done). 
    If $\textbf{q}=(q_{1}, \ldots , q_{n}, q_{n+1})$ is another maximal element, we have that there must exist distinct $1\leq i,j\leq n+1$ such that $p_{i}>q_{i}$ and $p_{j}<q_{j}$ (otherwise one would have either $\textbf{p}>\textbf{q}$ or $\textbf{p}<\textbf{q}$). 
    We get $\textbf{q}$ is a maximal element of
    \[A^{i}_{q_{i}}=\{\textbf{r}=(r_{1}, \ldots , r_{n}, r_{n+1}) \in A : r_{i}=q_{i}\}\] 
    with the order induced by the order on $A$:
    indeed, were $\textbf{r}$ a maximal element of $A^{i}_{q_{i}}$ with $\textbf{r}>\textbf{q}$, we would get $\textbf{q}$ is not a maximal element of $A\cap\mathbb{N}^{n+1}$.
    We transform $A^{i}_{q_{i}}$ into a subset $B^{i}_{q_{i}}$ of $\mathbb{N}^{n}$ by removing the $i$-th coordinate of its elements, and by induction hypothesis the set of maximal elements of $B^{i}_{q_{i}}$ is finite. 
    So every maximal element of $A\cap\mathbb{N}^{n+1}$ is either $\textbf{p}$, or projects into an element of some $\max(B^{i}_{q_{i}})$, the set of maximal elements of $B^{i}_{q_{i}}$.
    There are $n+1$ possible values for $i$, $1$ through $n+1$, and $p_{i}$ values for $q_{i}$ (given $q_{i}<p_{i}$), namely $0$ through $p_{i}-1$.
    so we can bound the number of maximal elements of $A\cap\mathbb{N}^{n+1}$ by the sum 
    \[1+\sum_{i=1}^{n+1}\sum_{q_{i}=0}^{p_{i}-1}|\max(B^{i}_{q_{i}})|,\]
    which is finite. 
    The result is then true for $n+1$.
\end{proof}

\empsigimpdec*

\begin{proof}
   Let $\{\s_{1},\ldots,\s_{n}\}$ be the sorts of $\Sigma$, for simplicity.
   Consider the set 
   \[\spec{\T}=\{(|\s_{1}^{\A}|,\ldots,|\s_{n}^{\A}|)\in \N^{n} : \text{$\A$ is a $\T$-interpretation}\}.\]
   By \Cref{dicksonlemma} we have that $\spec{\T}$ has at most finitely many maximal elements;
   let them be $(m_{1}^{j},\ldots,m_{n}^{j})$ for $1\leq j\leq M$.
   Take a quantifier-free formula $\varphi$ and consider its set of variables $V_{\s_{j}}$ of sort $\s_{i}$ and their union $V$, the set $\eq{\varphi}$ of equivalence relations on $V$ that respect sorts, and the subset $\eqp{\varphi}$ of $\eq{\varphi}$ of those equivalences $E$ such that $\delta_{V}^{E}$ implies $\varphi$.
   We state $\varphi$ is $\T$-satisfiable if, and only if, there exists $E\in\eqp{\varphi}$ and an $1\leq j\leq M$ such that $(|V_{\s_{1}}/E|,\ldots,|V_{\s_{n}}/E|)\leq (m_{1}^{j},\ldots,m_{n}^{j})$;
   by hardcoding the values $m_{i}^{j}$ we get that $\T$ is decidable once we remember $\eqp{\varphi}$ can be found algorithmically as a problem of equational logic.

   Now, if $\varphi$ is $\T$-satisfiable, take a $\T$-interpretation $\A$ that satisfies $\varphi$,\footnote{By \Cref{LowenheimSkolem} we can just assume $|\s_{i}^{\A}|\leq \aleph_{0}$ for all $1\leq i\leq n$} take the equivalence relation $E$ such that $xEy$ if and only if $x^{\A}=y^{\A}$, and it is clear that $E$ is in $\eqp{\varphi}$ and $(|V_{\s_{1}}/E|,\ldots,|V_{\s_{n}}/E|)\leq(|\s_{1}^{\A}|,\ldots,|\s_{n}^{\A}|)$. By \Cref{compactness} and Zorn's lemma, there must then exist a maximal element $(m_{1}^{j},\ldots,m_{n}^{j})$ of $\spec{\T}$ such that $(|\s_{1}^{\A}|,\ldots,|\s_{n}^{\A}|)\leq (m_{1}^{j},\ldots,m_{n}^{j})$, and thus $(|V_{\s_{1}}/E|,\ldots,|V_{\s_{n}}/E|)\leq (m_{1}^{j},\ldots,m_{n}^{j})$.


   For the reciprocal, suppose $E\in\eqp{\varphi}$ and $(|V_{\s_{1}}/E|,\ldots,|V_{\s_{n}}/E|)$ is less than or equal to $(m_{1}^{j},\ldots,m_{n}^{j})$, and take a $\T$-interpretation $\A$ with $(|\s_{1}^{\A}|,\ldots,|\s_{n}^{\A}|)=(m_{1}^{j},\ldots,m_{n}^{j})$.
   This means we can find a reassignment of the variables on $\A$ such that, in the resulting $\T$-interpretation $\A^{\prime}$, $x^{\A^{\prime}}=y^{\A^{\prime}}$ if, and only if, $xEy$. 
   This means $\A^{\prime}$ satisfies $\delta_{V}^{E}$ and, since $E\in\eqp{\varphi}$, it also satisfies $\varphi$.
\end{proof}

\section{Proof of \Cref{DECandSFWimpliesCMMF}}

\decandsfwimpliescmmf*

\begin{proof}
    Suppose $\T$ has $\wit$ as a strong witness with respect to $S$, and take a quantifier-free formula $\varphi$. 
    Let $V_{\s}$ equal $\vars_{\s}(\wit(\varphi))$, and $V$ the union of these set for $\s\in S$.
    Let $\eq{\varphi}$ be the set of equivalence relations on $V$ such that $\wit(\varphi)\wedge\delta_{V}^{E}$ is $\T$-satisfiable:
    this set can be found algorithmically as $\T$ is decidable, and the set of all equivalence relations on $V$ is finite.
    Given that there are only finitely many functions $\textbf{n}_{E}:\s\in S\mapsto |V_{\s}/E|$ for $E\in\eq{\varphi}$, we can, also algorithmically, find the (maximal) subset $\eqp{\varphi}$ of $\eq{\varphi}$ such that, if $E\in\eqp{\varphi}$ and $F\in \eq{\varphi}\setminus\{E\}$, then there exists $\s\in S$ such that $|V_{\s}/E|<|V_{\s}/F|$.
    Finally, we state that the function $\minmod_{\T}$ taking $\varphi$ to $\{\textbf{n}_{E} : E\in\eqp{\varphi}\}$ is a minimal model function for $\T$, being by construction certainly computable.

    Take an $E\in\eqp{\varphi}$:
    by definition of $\eq{\varphi}$ there is a $\T$-interpretation $\B$ that satisfies $\wit(\varphi)\wedge\delta_{V}^{E}$;
    as $\wit$ is a strong witness, there exists a $\T$-interpretation $\A$ that satisfies $\wit(\varphi)\wedge\delta_{V}^{E}$ with $\s^{\A}=\vars_{\s}(\wit(\varphi)\wedge\delta_{V}^{E})^{\A}$ for each $\s\in S$.
    Given that $\A$ satisfies $\delta_{V}^{E}$ and $V_{\s}=\vars_{\s}(\wit(\varphi)\wedge\delta_{V}^{E})$, we get that $|\s^{\A}|=|V_{\s}/E|$ for each $\s\in S$, and thus we have found a $\T$-interpretation that satisfies $\varphi$\footnote{As it satisfies $\wit(\varphi)$ and therefore $\exists{\overarrow{x}}\wit(\varphi)$ for $\overarrow{x}=\vars(\wit(\varphi))\setminus\vars(\varphi)$, $\T$-equivalent to $\varphi$.} and $|\s^{\A}|=\textbf{n}_{E}(\s)$ for each $\s\in S$.
    Finally, suppose that $E$ and $F$ are (distinct elements) in $\eqp{\varphi}$:
    by definition of $\eqp{\varphi}$ there exists a $\s\in S$ such that $\textbf{n}_{E}(\s)=|V_{\s}/E|<|V_{\s}/F|=\textbf{n}_{F}(\s)$, which finishes the proof.
\end{proof}


\section{Proof of \Cref{lem:TiSFW}}

\lemtisfw*
\begin{proof}
It suffices to define a strong witness on conjunctions of flat literals
(see, e.g., \cite{JB10-LPAR}).
Hence, let $\varphi$ be a conjunction of literals of the form $f(v) = w$, $v=w$ and $v \neq w$. If $\vars(\varphi) = \emptyset$, then let $\wit(\varphi) \coloneqq \varphi \land x=x$; otherwise, let $\wit(\varphi) = \varphi$. It is clear that $\varphi$ and $\Exists{\overarrow{w}} \wit(\varphi)$ are $\T_i$-equivalent, where $\overarrow{w} = \vars(\wit(\varphi)) \setminus \vars(\varphi)$. Let $\delta$ be an arrangement on a finite set of variables $V$ such that $\wit(\varphi) \land \delta$ is $\T_i$-satisfiable, and let $\A$ be a $\T_i$-interpretation satisfying $\wit(\varphi) \land \delta$. We need to show that there is a $\T_i$-interpretation $\B$ satisfying $\wit(\varphi) \land \delta$ such that $\sun^\B = \vars(\wit(\varphi) \land \delta)^\B$.
    Without loss of generality, $\vars(\wit(\varphi)) \subseteq V$.\footnote{Even if $\wit(\varphi)$ has variables outside of $V$,
then $\B$ satisfies an arrangement over $\vars(\wit(\varphi)) \cup V$, so it suffices to consider arrangements over a set of variables including $\vars(\wit(\varphi))$.}

    Let $E$ be the equivalence relation on $V$ induced by $\delta$. Given a variable $v \in V$, let $[v] \in V/E$ be its equivalence class. Our goal is to build a $\T_i$-interpretation $\B$ of $\wit(\varphi) \land \delta$ in which the elements are $V/E$. Viewing $\A$ as a directed graph, we may identify $V/E$ with some vertices of $\A$ (namely, $[v] \in V/E$ is identified with $v^\A$). If $f(v) = w$ is a literal in $\wit(\varphi)$, then $\A$ has an edge from $[v]$ to $[w]$. Let $G$ be the induced subgraph of $\A$ on $V/E$. Let $G_1$ be the induced subgraph of $G$ on the vertices with out-degree 1, and let $G_2$ be the induced subgraph of $G$ on the remaining vertices (i.e., those with out-degree 0). To construct $\B$, we add edges to $G$ emanating from each of the vertices in $G_2$, being careful to make the resulting graph a model of $\T_i$. There are a few cases.

    \begin{enumerate}
    \item First, suppose $G_1$ contains a cycle. Then, let $\B$ be obtained from $G$ by adding an edge from every vertex in $G_2$ to some element of the cycle. Since this doesn't create any new cycles, $\B$ is a $\T_i$-interpretation.

    \item Second, suppose that $G_1$ is acyclic and $|G_2| \ge 2$. We have two subcases. If $|G_2| = 6$, then arrange the vertices of $G_2$ into two disjoint cycles of length 3; otherwise, arrange the vertices of $G_2$ into a single cycle. The resulting graph, $\B$, does not have any cycles of length 1 or 6. It may have a cycle whose length is in $S$, but in that case it does not have a cycle of length 2, since all of the elements of $S$ are at least 7. Hence, $\B$ is a $\T_i$-interpretation.

    \item Third, suppose that $G_1$ is acyclic and $|G_2| = 1$. Let $v$ be the unique element of $G_2$. We also have two subcases here. If $G_1 = \emptyset$, then we have no choice but to create an edge from $v$ to itself, which results in a valid $\T_i$-interpretation. Otherwise, if $G_1 \neq \emptyset$, then there must be some vertex $w \in G_1$ with an edge from $w$ to $v$. Create an edge from $v$ to $w$. The resulting graph, $\B$, contains a cycle of length 2 and no other cycles. Hence, $\B$ is a valid $\T_i$-interpretation.

    \item The only remaining case is when $G_2 = \emptyset$, but in that case $\B = G = G_1$ is our desired $\T_i$-interpretation. \qedhere
    \end{enumerate}
\end{proof}

\section{Proof of \Cref{lem:TiCMMF}}
\lemticmmf*
\begin{proof}
Recall that the set $S$ is undecidable.
Assume for contradiction that $T_i$ has a computable minimal model function.
Then, given $n$, we have that $n\in S$ if and only if
the formula $\cycle{n}(x)\land f^4(y)=y$,
which is $\T_i$-satisfiable,
has a minimal model of size 
$n+4$.
Indeed, if $n\in S$ then we can obtain a
 $\T_i$-interpretation of size $n + 4$ by a disjoint union of a cycle of length $n$ and a cycle of length 4.
 And if $n\notin S$, then we can obtain
 a $T_i$-interpretation of size $n+2$
 by a disjoint union of a cycle of length $n$ and a cycle of length 2.
 This gives us a procedure for determining whether a given number
 is in $S$, which contradicts its undecidability.
\end{proof}

\section{Proof of \Cref{lem:TiSinf}}
\lemtisinf*
\begin{proof}
Let $\varphi$ be a $\T_i$-satisfiable quantifier-free formula, and let $\A$ be a $\T_i$-interpretation that satisfies $\varphi$. We create an infinite $\T_i$-interpretation $\B$ of $\varphi$ by setting
    $\sigma^{\B}=\sigma^{\A}\cup C$, for some infinite set $C=\{c_1,c_2,\ldots\}$ with $C\cap\sigma^{\A}=\emptyset$,
    and $f^{\B}(a)=f^{\A}(a)$ whenever $a\in\sigma^{\A}$
    and $f^{\B}(c_i)=c_{i+1}$ for each $i\geq 1$.
    Graph-theoretically, $\graphof{\B}$ is the result of adding a ray (i.e., a one-way infinite path) to $\graphof{\A}$. Since this doesn't create any new cycles, $\B$ is a $\T_i$-interpretation.
    And since $\varphi$ is quantifier-free and $\A\models\varphi$, we have $\B\models\varphi$.
\end{proof}


\section{Proof of \Cref{lem-tnn-polite}}

\tnnnsp*

\begin{proof}
    We show that $\tnn$ is shiny, which implies that it is strongly polite by \Cref{thm-unicorn3}.

    First, we show that $\tnn$ is smooth. Let $\A$ be a $\tnn$-interpretation satisfying a quantifier-free formula $\varphi$, and let $\kappa \ge |\sigma^\A|$. Let $\B$ be the interpretation given by adjoining $\kappa - |\sigma^\A|$ new elements to $\sigma^\A$, none of which in $P^\B$. Then, $\sigma^\B$ is a $\tnn$-interpretation satisfying $\varphi$ such that $|\sigma^\B| = \kappa$.

    Second, we show that $\tnn$ is stably finite. Let $\A$ be a $\tnn$-interpretation satisfying a quantifier-free formula $\varphi$. Let $X = \vars(\varphi)^\A$, and let $Y$ be an arbitrary subset of $\sigma^\A \setminus P^\A$ such that $|Y| = |X \cap P^\A|$. Let $\B$ be the sub-interpretation of $\A$ restricted to $X \cup Y$,
    that is, $\sigma^{\B}=X\cup Y$ and
    $P^{\B}=P^{\A}\cap\sigma^{\B}$. Then, $\B$ is a finite $\tnn$-interpretation satisfying $\varphi$.

    Third, we show that $\tnn$ has a computable minimal model function. Let $\varphi$ be a quantifier-free formula. By the previous paragraph, if $\varphi$ is $\tnn$-satisfiable, then it is satisfiable by a model of size at most $2 \cdot |\vars(\varphi)|$. Given a finite $\Sp$-interpretation $\A$, we can decide whether it is a $\tnn$-interpretation and whether it satisfies $\varphi$. Also, since $\Sp$ is finite, there are finitely many $\Sp$-interpretations of size $n \in \No$. Hence, we can compute the minimal model function by enumerating models, searching the the smallest one.
\end{proof}


\section{Proof of \Cref{lem-tnn-add}}

\tnnnnadp*

\begin{proof}
    Suppose for the sake of contradiction that $\wit$ is an additive witness. Let $n = |\vars(\wit(\top))|$, and let
    \[
        \psi \coloneqq (\neq(w_{1},\ldots,w_{n+1})) \land \bigwedge_{i=1}^{n+1} P(w_i),
    \]
    where the $w_i$ are fresh variables. Since $\wit(\wit(\varphi) \land \psi)$ and $\wit(\varphi) \land \psi$ are $\tnn$-equivalent and have the same set of variables, $\wit(\varphi) \land \psi$ has a $\tnn$-interpretation of size at most $2n+1$ (as $\tnn$ is strongly finitely witnessable). Yet, the axioms of $\tnn$ imply that every such interpretation has size at least $2n+2$, a contradiction.
\end{proof}

\section{Proof of \Cref{theo:addwit}}
\thmaddwit*
\begin{proof}
It suffices to prove that over algebraic signatures, strong finite witnessability implies
additive finite witnessability.
    Let $\wit$ be a strong witness for $\T$ with respect to $S$. First, let
    $
        \wit'(\varphi) \coloneqq \varphi \land \wit(\varphi)
    $.
   Then, we claim that $\wit'$ is still a strong witness. It is clear that $\varphi$ and $\Exists{\overarrow{w}} \wit'(\varphi)$ are $\T$-equivalent, given that this property holds for $\wit$. Now, let $V$ be a finite set of variables whose sorts lie in $S$ and $\delta_{V}$ an arrangement on $V$, and suppose $\wit^{\prime}(\varphi)\wedge\delta_{V}$ is $\T$-satisfiable. Then, $\wit(\varphi)\wedge\delta_{V}$ is $\T$-satisfiable, and since $\wit$ is a strong witness, there exists a $\T$-interpretation $\A$ that satisfies $\wit(\varphi)\wedge\delta_{V}$ with $\s^{\A}=\vars_{\s}(\wit(\varphi)\wedge\delta_{V})^{\A}$ for each $\s\in S$. Since $\A$ satisfies $\varphi$, it also satisfies $\wit'(\varphi)\wedge\delta_{V}$. And since $\vars_{\s}(\wit(\varphi)\wedge\delta_{V})\subseteq\vars_{\s}(\wit^{\prime}(\varphi)\wedge\delta_{V})$, we have $\s^{\A}=\vars_{\s}(\wit^{\prime}(\varphi)\wedge\delta_{V})^{\A}$ for each $\s\in S$.

   Additionally, it is decidable whether a quantifier-free formula is in the image of $\wit'$: a quantifier-free formula $\varphi$ is in the image of $\wit'$ if and only if $\varphi$ is of the form
    $
        \psi \land \chi
    $
    for some $\psi$ and $\chi$ such that $\wit'(\psi) = \varphi$.

%\wit(\psi)=\chi.
%\wit'(\psi)=\psi\wedge\wit(\psi)=\psi\wedge\chi=\varphi

    Next, for every quantifier-free formula $\chi$, let $\wit''(\chi) = \chi$ if $\chi$ is of the form $\wit'(\varphi) \land \psi$, where $\psi$ is a conjunction of flat literals such that every term in $\psi$ is a variable whose sorts are in $S$; otherwise, let $\wit''(\chi) = \wit'(\chi)$. By the previous paragraph, we can effectively check whether $\chi$ is of the form $\wit'(\varphi) \land \psi$. Then, we claim $\wit''$ is an additive witness. It is clearly $S$-additive: $\wit''(\wit''(\varphi)\wedge\psi)$ is equal to $\wit''(\varphi)\wedge\psi$ for all $\varphi,\psi\in \qf{\Sigma}$, where $\psi$ is a conjunction of flat literals such that every term in $\psi$ is a variable whose sort is in $S$. It remains to prove that $\wit''$ is a witness. It is clear that $\chi$ and $\Exists{\overarrow{w}} \wit''(\chi)$ are $\T$-equivalent, where $\overarrow{w} = \vars(\wit(\chi)) \setminus \vars(\chi)$. Now, suppose $\wit''(\chi)$ is $\T$-satisfiable. We need to show that there is a $\T$-interpretation $\A$ satisfying $\wit''(\chi)$ such that $\s^\A = \vars_\s(\wit''(\chi))^\A$ for every $\s \in S$. If $\wit''(\chi) = \wit'(\chi)$, then we are done by the fact that $\wit'$ is a witness. Otherwise, $\wit''(\chi) = \wit'(\varphi) \land \psi$ for some $\varphi,\psi\in \qf{\Sigma}$, where $\psi$ is a conjunction of flat literals such that every term in $\psi$ is a variable whose sort is in $S$. But, since the signature is algebraic, $\psi$ is a conjunction of equalities and disequalities. Thus, there is an arrangement $\delta_V$, where $V = \vars_S(\psi)$, such that $\delta_V \rightarrow \psi$ and $\wit'(\varphi) \land \delta_V$ is $\T$-satisfiable. Since $\wit'$ is a strong witness, there is a $\T$-interpretation $\A$ satisfying $\wit'(\varphi) \land \delta_V$ (and therefore also $\wit''(\chi)$) such that $\s^\A = \vars_\s(\wit'(\varphi) \land \delta_V)^\A = \vars_\s(\wit'(\varphi) \land \psi)^\A = \vars_\s(\wit''(\chi))^\A$.
\end{proof}

\section{Proof of \Cref{thm-uncountable-unicorns}}

\begin{lemma} \label{lem-tnt-stab-fin}
    The theory $\TNT$ is stably finite.
\end{lemma}
\begin{proof}
Let $\varphi$ be a $\SNT$-formula that is
$\TNT$-satisfiable. 
Suppose for contradiction it is not satisfied by any finite 
$\TNT$-interpretation.
In particular, it is not satisfied by any $\tnt$-interpretation,
and so its negation is satisfied by all, and therefore
so is its universal closure, which means
that the latter belongs to $\ax=\ax(\TNT)$.
In particular, $\neg\varphi$ then becomes $\TNT$-valid,
which is a contradiction as $\varphi$ is $\TNT$-satisfiable.
\end{proof}

\begin{lemma} \label{lem:finsmoothtnt}
    The theory $\TNT$ is finitely smooth.
\end{lemma}
\begin{proof}
Let $\varphi$ be a quantifier-free formula satisfied by a $\TNT$-interpretation of size $n$. Then, $\varphi \land \psi^{\sun}_{=n}$ is $\TNT$-satisfiable, so it is satisfied by a $\TNT$-interpretation $\A$ with $|\sigma_1^\A|=n$. To show that $\TNT$ is finitely smooth, it suffices to construct a $\TNT$-interpretation $\B \vDash \varphi$ with $|\sigma_1^{\B}| = |\sigma_1^{\A}| + 1$. 
    %We will do so in such a way that the underlying structure $\sB$ is one of our structures constructed above. 
    We proceed by cases.

    \textbf{Case I:} $|\sigma_1^\A| = 2^k - 1 + k$ for some $k \in \mathbb{N}$. We have $N^\A = [0,k-1]$ and $T^\A = \{0,1\}^{\le k-1}$. We create a $\TNT$-structure $\sB$ with $N^\sB = [0,k]$ and $T^\sB = \{0,1\}^{\le k-1}$. Let $f_\rho^\sB(k) = f_\rho^\A(k-1)$ for all $\rho \in 2^\omega$. This completely determines $\sB$, since $f_\rho^\sB(m)$ for $m \in [0,k-1]$ is given by
    \[
        \rho(0) \rho(1) \cdots \rho(m-1) \in \{0,1\}^m.
    \]
    We expand $\sB$ to a $\TNT$-interpretation $\B$ by interpreting the variables as follows:
    \[
        x^\B = \begin{cases}
            k \qquad &\text{if} \ x^\A = k-1 \\
            x^\A \qquad &\text{otherwise}.
        \end{cases}
    \]
    We claim that $\B \vDash \varphi$. We do this by checking that every literal satisfied by $\A$ is satisfied by $\B$. We may assume that $\varphi$ has been flattened, so it suffices to consider literals of the form $\pm N(x)$, $\pm T(x)$, $\pm (x < y)$, $\pm (x = y)$, and $f_\rho(x) = y$, where $\pm$ indicates that the atomic formula may or may not be negated.
    \begin{itemize}[label=$\bullet$]
        \item $\pm N(x)$: We have $x^\A \in N^\A$ if and only if $x^\B \in N^\B$.
        \item $\pm T(x)$: We have $x^\A \in T^\A$ if and only if $x^\B \in T^\B$.
        \item $\pm (x < y)$: If $x^\A <^\A y^\A$, then $x^\A,y^\A \in N^\A = [0,k-1]$ and $x^\A < y^\A$. Hence, $x^\A < k-1$, so $x^\A = x^\B$. Also, $y^\A \le y^\B$. Thus, $x^\B < y^\B$, which implies $x^\B <^\B y^\B$.

        Conversely, if $x^\B <^\B y^\B$, then $x^\B,y^\B \in [0,k-2] \cup \{k\}$ and $x^\B < y^\B$. Hence, $x^\B \in [0,k-2]$, so $x^\B = x^\A$. If $y^\B \in [0,k-2]$, then $y^\B = y^\A$, and we have $x^\A < y^\A$. Otherwise, $y^\B = k$, in which case $y^\A = k-1$, so we still have $x^\A < y^\A$. Therefore, $x^\A <^\A y^\A$.
        \item $\pm (x = y)$: We have $x^\A = y^\A$ if and only if $x^\B= y^\B$.
        \item $f_\rho(x) = y$: Suppose $f^\A_\rho(x^\A) = y^\A$. If $x^\A \in T^\A$, then $x^\B = x^\A = y^\A = y^\B$ and $x^\B \in T^\B$. Hence, $f^\B_\rho(x^\B) = x^\B = y^\B$. Otherwise, $x^\A \in N^\A$ and $y^\A \in T^\A$, which implies $y^\A = y^\B$. If $x^\A < k-1$, then $x^\A = x^\B$ and
        \[
            f^\B_\rho(x^\B) = f^\B_\rho(x^\A) = f^\A_\rho(x^\A) = y^\A = y^\B.
        \]
        If $x^\A = k-1$, then $x^\B = k$, so
        \[
            f^\B_\rho(x^\B) = f^\B_\rho(k) = f^\A_\rho(k-1) = f^\A_\rho(x^\A) = y^\A = y^\B.
        \]
    \end{itemize}

    \textbf{Case II:} $|\sigma_1^\A| \neq 2^k - 1 + k$ for all $k \in \mathbb{N}$. In this case, for some $k \in \mathbb{N}$ we have $N^\A = [0,k-1]$ and $T^\A = \{0,1\}^{\le k-2} \cup S$ for some $S \subsetneq \{0,1\}^{k-1}$. Let $s \in \{0,1\}^{k-1} \setminus S$. We create a $\TNT$-structure $\sB$ with $N^\sB = [0,k-1]$ and $T^\sB = \{0,1\}^{\le k-2} \cup S \cup \{s\}$. Expand $\sB$ to a $\TNT$-interpretation $\B$ by interpreting the variables the same as in $\A$. Since $\A$ is a sub-interpretation of $\B$, we have $\B \vDash \varphi$. This completes the proof that $\TNT$ is finitely smooth.
\end{proof}

\begin{lemma}
\label{lem:tntnotsmooth}
    The theory $\TNT$ is not smooth.
\end{lemma}
\begin{proof}
We show that $\TNT$ is not smooth by showing that if $\sB$ is an infinite $\TNT$-structure, then $|\sB| \ge 2^{\aleph_0}$. Let $\sB$ be an infinite $\TNT$-structure. For every $k \in \mathbb{N}$, 
    we have that 
    if $|N^{\sB}| \le k$, then $|T^{\sB}| \le 2^k - 1$. Together with the fact that $\vDash_\T \Forall{x} [N(x) \lor T(x)]$, this implies that $N^\sB$ is infinite.

    It is a theorem of $\TNT$ that $N$ has a maximal element with respect to $<$, and it is also a theorem that every non-minimal element has a predecessor. So let $a$ be the penultimate element of $N^\sB$ with respect to $<^\sB$.

    We claim that $f_\rho^\sB(a) \neq f_\tau^\sB(a)$ for all $\rho, \tau \in 2^\omega$ with $\rho \neq \tau$. Note that this claim implies $|\sB| \ge 2^{\aleph_0}$, which will finish the proof. Let $\rho, \tau \in 2^\omega$ with $\rho \neq \tau$. Given $n \in \mathbb{N}$, let $P_n(x)$ be an abbreviation for the formula
    \[
        \Exists{y_1} \Exists{y_2} \cdots \Exists{y_{n-1}} \Exists{y_n} [y_1 < y_2 \land \dots \land y_{n-1} < y_n \land y_n < x],
    \]
    which asserts that $x$ has at least $n$ distinct predecessors. Let $n \in \mathbb{N}$ be such that $\rho(n-1) \neq \tau(n-1)$. Then, we have
    \[
        \vDash_\T \Forall{x} [(P_n(x) \land \Exists{y} x < y) \rightarrow f_\rho(x) \neq f_\tau(x)].
    \]
    Since $a$ has infinitely many distinct predecessors, it follows that $f_\rho^\sB(a) \neq f_\tau^\sB(a)$, as desired.
\end{proof}

