\title{\bf Impact of Tariff Wars on Global Economy}

\author{\bf N.S. Gonchar \orcidlink{0000-0003-0954-8948}, O.P. Dovzhyk\orcidlink{0000-0003-4098-1192},A.S. Zhokhin\orcidlink{0000-0002-8969-3928},\\ \bf W.H. Kozyrsky\orcidlink{0000-0002-8969-3928}, A.P. Makhort\orcidlink{0000-0003-4098-1192}\\
