		\mathrm{=}\displaystyle\sum^l_{s\mathrm{=}1}{\displaystyle\sum^l_{i\mathrm{=}1}{e^{is}}}\mathrm{=}
		\displaystyle\sum^l_{i\mathrm{=}1}{\displaystyle\sum^l_{s\mathrm{=}1}{e^{is}}}
		\mathrm{=}\displaystyle\sum^l_{i\mathrm{=}1}{b_i}.
	\end{array}
\end{equation}

The vector of demand of the $i$-th country is determined by the vector $C_i\mathrm{=}\mathrm{\{}C_k{\}}^n_{k\mathrm{=}1}$ and supply vector is defined by the vector $b_i\mathrm{=}\mathrm{\{}b_k{\}}^n_{k\mathrm{=}1}.$ The equilibrium price vector $p_0\mathrm{=}\mathrm{\{}p^0_k{\}}^n_{k\mathrm{=}1}$ under which there is clearing of the market is determined from the set of equations


\begin{equation}\label{eq_lab2_}
\begin{array}{r}
\displaystyle\sum^l_{i\mathrm{=}1}{C_{ki}}
\frac{\mathrm{\langle}b_i,p_0\mathrm{\rangle }}{\mathrm{\langle }
C_i,p_0\mathrm{\rangle }}\mathrm{=}
\displaystyle\sum^l_{i\mathrm{=}1}{b_{ki}},\qquad k\mathrm{=}\overline{1,n},
