\begin{equation}\label{eq_lab8_}
\begin{array}{r}
H_i\left(p\right)\mathrm{=}\frac{p_i\mathrm{+}\frac{\displaystyle\sum^n_{j\mathrm{=1}}{p_j}\displaystyle\sum^l_{k\mathrm{=1}}{C_{jk}}{\tau }_{ki}}{\displaystyle\sum^l_{s\mathrm{=1}}{C_{is}}}}{\mathrm{1+}\displaystyle\sum^n_{i\mathrm{=1}}{\frac{\displaystyle\sum^n_{j\mathrm{=1}}{p_j}\displaystyle\sum^l_{k\mathrm{=1}}{C_{jk}}{\tau }_{ki}}{\displaystyle\sum^l_{s\mathrm{=1}}{C_{is}}}}}\mathrm{,}\mathrm{\qquad }i\mathrm{=}\overline{\mathrm{1,}n},
\end{array}
\end{equation}

on the set $P\mathrm{=}\mathrm{\{}p\mathrm{=}\mathrm{\{}p_i{\}}^n_{i\mathrm{=}1},\ p_i\mathrm{\ge }0,i\mathrm{=}\overline{1,n},\ \displaystyle\sum^n_{i\mathrm{=}1}{p_i}\mathrm{=}1\}.$ It is continuous on $P$ and maps it into itself. Therefore, there exists a fixed point $p_0$ of the map $H\left(p\right)$ \cite{Nirenberg1974}. The last comes to the set of equations
\begin{equation} \label{eq_lab9_}
\begin{array}{r}
\frac{\displaystyle\sum^n_{j\mathrm{=1}}{p^0_j}\displaystyle\sum^l_{k\mathrm{=1}}{C_{jk}}{\tau }_{ki}}{\displaystyle\sum^l_{s\mathrm{=1}}{C_{is}}}\mathrm{=}\lambda p^0_i\mathrm{,}\mathrm{\qquad }i\mathrm{=}\overline{\mathrm{1,}n},
\end{array}
\end{equation}

where

\[\lambda \mathrm{=}\displaystyle\sum^n_{i\mathrm{=1}}{\frac{\displaystyle\sum^n_{j\mathrm{=1}}{p^0_j}\displaystyle\sum^l_{k\mathrm{=1}}{C_{jk}}{\tau }_{ki}}{\displaystyle\sum^l_{s\mathrm{=1}}{C_{is}}b^{\mathrm{1}}_s}}.\]

Let us prove that $\lambda \mathrm{>}0,$ and $p_0$ is a strictly positive vector. Let us introduce into consideration the matrix
\begin{equation} \label{eq_lab10_} 
\begin{array}{r}
F\mathrm{=|}f_{ji}|^n_{j,i\mathrm{=}1}, \end{array}
\end{equation} 
where
\[f_{ji}\mathrm{=}\frac{\displaystyle\sum^l_{k\mathrm{=1}}{C_{jk}}{\tau }_{ki}}{\displaystyle\sum^l_{s\mathrm{=1}}{C_{is}}}\mathrm{,}\mathrm{\qquad }i,j\mathrm{=}\overline{\mathrm{1,}n}.\]

The set of equations \eqref{eq_lab9_} can be written in the operator form
\[F^Tp_0\mathrm{=}\lambda p_0.\]

Since $F^T$ is non negative and indecomposable and the fact that the vector $p_0$ also solves the set of equations
\[{\left[F^T\right]}^{n\mathrm{-}1}p_0\mathrm{=}{\lambda }^{n\mathrm{-}1}p_0,\] 
we have that ${\left[F^T\right]}^{n\mathrm{-}1}p_0$ is a strictly positive vector.
From this it follows that $p_0$ is a strictly positive vector and $\lambda \mathrm{>}0.$ 
Here we introduced the denotation $F^T$ for the transposed matrix to the matrix $F.$ Prove that $\lambda \mathrm{=}1.$ Let us denote
\begin{equation} \label{eq_lab11_}
\begin{array}{r}
d_k\mathrm{=}\frac{1}{\lambda }\displaystyle\sum^n_{u\mathrm{=}1}{p^0_u}C_{uk},\qquad k\mathrm{=}\overline{1,l}.\end{array}
\end{equation}

Then, from \eqref{eq_lab9_} we obtain
\begin{equation} \label{eq_lab12_} 
\begin{array}{r}
p^0_i\mathrm{=}\frac{\displaystyle\sum^l_{k\mathrm{=}1}{d_k}{\tau }_{ki}}{\displaystyle\sum^l_{s\mathrm{=}1}{C_{is}}}.
\end{array}
\end{equation} 

Substituting \eqref{eq_lab12_} into \eqref{eq_lab11_}, we have
\begin{equation}\label{eq_lab13_}
\begin{array}{r}
d_j\mathrm{=}\frac{1}{\lambda }\displaystyle\sum^n_{u\mathrm{=}1}{\frac{\displaystyle\sum^l_{k\mathrm{=}1}{d_k}{\tau }_{ku}C_{uj}}{\displaystyle\sum^l_{s\mathrm{=}1}{C_{us}}}},\qquad j\mathrm{=}\overline{1,l}. 
\end{array}
\end{equation}

Or,
\begin{equation}\label{eq_lab14_}
\begin{array}{r}
d_j\mathrm{=}\frac{1}{\lambda }\displaystyle\sum^l_{k\mathrm{=}1}{\displaystyle\sum^n_{u\mathrm{=}1}{\frac{d_k{\tau }_{ku}C_{uj}}{\displaystyle\sum^l_{s\mathrm{=}1}{C_{us}}}}},\qquad j\mathrm{=}\overline{1,l}. \end{array}
\end{equation}

Summing up by index $j$ left and right parts of \eqref{eq_lab14_}, we obtain
\begin{equation}\label{eq_lab15_}
\begin{array}{r}
\displaystyle\sum^l_{j\mathrm{=}1}{d_j}\mathrm{=}\frac{1}{\lambda }\displaystyle\sum^l_{j\mathrm{=}1}{d_j}.
\end{array}
\end{equation} 

Since $\displaystyle\sum^l_{j\mathrm{=}1}{d^1_j}\mathrm{\neq }0,$ we have $\lambda \mathrm{=}1.$ Therefore, the system of equations \eqref{eq_lab13_} can be written in the form
\begin{equation}\label{eq_lab16_}
\begin{array}{r}
d_i\mathrm{=}\displaystyle\sum^n_{u\mathrm{=1}}{\frac{\displaystyle\sum^l_{k\mathrm{=1}}{d_k}{\tau }_{ku}C_{ui}}{\displaystyle\sum^l_{s\mathrm{=1}}{C_{us}}}}\mathrm{=}\displaystyle\sum^l_{k\mathrm{=1}}{d_k}\displaystyle\sum^n_{u\mathrm{=1}}{\frac{{\tau }_{ku}C_{ui}}{\displaystyle\sum^l_{s\mathrm{=1}}{C_{us}}}}\mathrm{,}\mathrm{\qquad }i\mathrm{=}\overline{\mathrm{1,}l}.
\end{array}
\end{equation}

Or,

\begin{equation}\label{eq_lab17_}
\begin{array}{r}
\displaystyle\sum^l_{k\mathrm{=}1}{b^1_{ki}}d_k\mathrm{=}d_i,\qquad i\mathrm{=}\overline{1,l}.
\end{array}
\end{equation}

Let us prove the solution existence of the set of equations \eqref{eq_lab2_}. Taking into account that
\begin{equation}\label{eq_lab18_}
\begin{array}{r}
d_k\mathrm{=}\displaystyle\sum^n_{u\mathrm{=}1}{p^0_u}C_{uk}\mathrm{=}\mathrm{\langle }C_k,p_0\mathrm{\rangle },\qquad k\mathrm{=}\overline{1,l}.
\end{array}
\end{equation} 

and the set of equations \eqref{eq_lab17_} we have

\begin{equation} \label{eq_lab19_} 
\begin{array}{r}
\mathrm{\langle }b_k,p_0\mathrm{\rangle }\mathrm{=}\mathrm{\langle }C_k,p_0\mathrm{\rangle },\qquad k\mathrm{=}\overline{1,l}. 
\end{array}
\end{equation}

From this it follows that the vector $p_0$ solves the set of equations \eqref{eq_lab2_}. Theorem 1 is proved. $\mathrm{\square}$

Theorem 2. \textit{Let }$l$\textit{ countries trade }$n$\textit{ types of goods, and let their trade are characterized by import and export vectors }$C_i,b_i,\ i\mathrm{=}\overline{1,l}$\textit{ where the import vector }$C_i\mathrm{=}\mathrm{\{}C_{ki}{\}}^n_{k\mathrm{=}1},i\mathrm{=}\overline{1,n},$\textit{ satisfies the conditions }$\displaystyle\sum^l_{k\mathrm{=}1}{C_{jk}}\mathrm{>}0,\ j\mathrm{=}\overline{1,n}.$\textit{ If the matrix }$\tau \mathrm{=|}{\tau }_{ki}{\mathrm{|}}^{l,n}_{k,i\mathrm{=}1}$\textit{ is such that the matrix }$t\mathrm{=|}t_{ji}{\mathrm{|}}^n_{i,j\mathrm{=}1}$\textit{ is nonnegative and indecomposable and then for the export vector }$b_i\mathrm{=}\mathrm{\{}b_{ki}{\}}^n_{k\mathrm{=}1}$\textit{ such that}
\begin{equation}\label{eq_lab20_}
\begin{array}{r}
b_{ik}\mathrm{=}\displaystyle\sum^n_{j\mathrm{=1}}{\frac{t_{ij}C_{jk}}{\displaystyle\sum^l_{r\mathrm{=1}}{C_{jr}}}}\mathrm{,}\mathrm{\qquad }i\mathrm{=}\overline{\mathrm{1,}n}\mathrm{,\ }k\mathrm{=}\overline{\mathrm{1,}l},
\end{array}
\end{equation}

\textit{the equilibrium price vector of the set of equations}

\begin{equation}\label{eq_lab21_}
\begin{array}{r}
\displaystyle\sum^l_{i\mathrm{=1}}{r_k}C_{ki}\frac{\mathrm{\langle }rb_i,p\mathrm{\rangle }}{\mathrm{\langle }rC_i,p\mathrm{\rangle }}\mathrm{=}\displaystyle\sum^l_{s\mathrm{=1}}{r_k}b_{ks}\mathrm{,}\mathrm{\qquad }k\mathrm{=}\overline{\mathrm{1,}n},
\end{array}
\end{equation}

\textit{exists and it is equal to the vector }$p\mathrm{=}\mathrm{\{}\frac{p^0_i}{r_i}{\}}^n_{i\mathrm{=}1},$\textit{ where the vector }$p_0\mathrm{=}\mathrm{\{}p^0_i{\}}^n_{i\mathrm{=}1}$\textit{ solves the set of equations}

\begin{equation}\label{eq_lab22_}
\begin{array}{r}
\displaystyle\sum^l_{i\mathrm{=1}}{C_{ki}}\frac{\mathrm{\langle }b_i,p_0\mathrm{\rangle }}{\mathrm{\langle }C_i,p_0\mathrm{\rangle }}\mathrm{=}\displaystyle\sum^l_{s\mathrm{=1}}{b_{ks}}\mathrm{,}\mathrm{\qquad }k\mathrm{=}\overline{\mathrm{1,}n}.
\end{array}
\end{equation}


Consequence 1. \textit{Tariff wars between trading countries leads to the increasing of prices in international trade if }$r_i\mathrm{<}1,\ i\mathrm{=}\overline{1,n}.$

\section{ Conclusion.}

The paper proposes an algorithm to build fair international trade. It is based on the model of international trade proposed in the article \cite{Gonchar2022}. To do this, we find the ratio between the exports and imports of trading countries, for which there is such an ideal equilibrium that the trade balance between all countries is zero. Under simple realistic assumptions about the behaviour of countries subject to tariff restrictions, it is proved that this leads to an increase in prices for goods traded between countries. In a less than ideal equilibrium, tariff restrictions can lead to a recession.

