The next section contains the proof of Theorem \ref{thm:main}. Miyamoto \cite{M09} uses the nodal structure of solutions to $- \Delta w = \mu_2 w$ near degenerate zeroes in a smart way and combines it with the Szeg\H{o}--Weinberger inequality, i.e.\ with a bound for $\mu_2$ in terms of the area of $\Omega$. In the present note we modify this approach by using a diameter-based bound on $\mu_2$ instead. More precisely, we make use of the inequality
\begin{align}\label{eq:Kroger}
 \mu_2 \leq \frac{4 j_0^2}{\diam (\Omega)^2}
\end{align}
proven by Kr\"oger \cite{K99} for any convex $\Omega \subset \R^2$.


\section{Proof of Theorem \ref{thm:main}}

In this section we prove the main result of this note, based on ideas of Miyamoto \cite{M09}. We will use a few elementary properties of some Bessel functions of the first kind.

Recall that the Bessel function $J_0$ of order zero satisfies the differential equation
\begin{align}\label{eq:Bessel0}
 x^2 \frac{\dd^2 u}{\dd x^2} + x \frac{\dd u}{\dd x} + x^2 u = 0
\end{align}
and the normalization $J_0 (0) = 1$. Furthermore, its derivative is given by $J_0' = - J_1$, the negative of the Bessel function $J_1$ of first order. In particular, $J_0' (0) = 0$ and $J_0' (x) < 0$ on $(0, j_1)$, where $j_1$ denotes the first positive zero of $J_1$.

We will also make use of the following lemma. For completeness we provide its short proof.

\begin{lemma}\label{lem:nodal}
Let $\Omega \subset \R^2$ be a bounded Lipschitz domain and let $\mu_2$ be the second eigenvalue of the Neumann Laplacian on $\Omega$. If $w \in H^1 (\Omega)$ is a non-trivial function satisfying $- \Delta w = \mu_2 w$ in the distributional sense, then $w$ does not have any interior nodal domain; that is, there is no open, non-empty set $\Omega' \subset \Omega$ such that $w |_{\Omega'}$ belongs to $H_0^1 (\Omega')$.
\end{lemma}

\begin{proof}
Assume the converse, i.e., there exists an open, non-empty set $\Omega' \subset \Omega$ such that $u := w |_{\Omega'} \in H_0^1 (\Omega')$. Clearly, $- \Delta u = \mu_2 u$ in $\Omega'$, and, due to unique continuation, $u$ is non-trivial, and, thus, an eigenfunction of the Dirichlet Laplacian on $\Omega'$ with corresponding eigenvalue $\mu_2$. Let us denote by $\lambda_1 (\Omega)$ and $\lambda_1 (\Omega')$ the first Dirichlet Laplacian eigenvalues  on $\Omega$ and $\Omega'$, respectively. Using P\'olya's classical result $\mu_2 < \lambda_1 (\Omega)$ \cite{P52} and domain monotonicity of Dirichlet Laplacian eigenvalues, we obtain
\begin{align*}
 \mu_2 < \lambda_1 (\Omega) \leq \lambda_1 (\Omega') \leq \mu_2,
\end{align*}
a contradiction.
\end{proof}

We can now proceed with the proof of the main observation of this note.

\begin{proof}[Proof of Theorem \ref{thm:main}]
Let us assume that $\mathbf{x_0} \in \Omega$ is a critical point of an eigenfunction $\psi_2$ of the Neumann Laplacian on $\Omega$ corresponding to the eigenvalue $\mu_2$. Because of the translation invariance of the Laplacian we may assume, without loss of generality, that $\mathbf{x_0} = \mathbf{0}$. 

For a contradiction, assume now that 
\begin{align}\label{eq:contradiction}
 |\mathbf{y}| = \dist (\mathbf{0}, \mathbf{y}) \leq \frac{j_1}{2 j_0} \diam (\Omega) \quad \text{for all}~\mathbf{y} \in \partial \Omega.
\end{align}
Possibly after replacing $\psi_2$ by $- \psi_2$, we have
\begin{align}\label{eq:sign}
 \psi_2 (\mathbf{0}) \geq 0.
\end{align}
Using polar coordinates $\mathbf{x} = (r \cos \theta, r \sin \theta)$, let us set 
\begin{align*}
 w (\mathbf{x}) := \psi_2 (\mathbf{0}) J_0 \left( \sqrt{\mu_2} r \right) - \psi_2 (\mathbf{x}), \quad \mathbf{x} \in \Omega.
\end{align*}
From \eqref{eq:Bessel0} we get
\begin{align}\label{eq:Laplace}
\begin{split}
 - \Delta w (\mathbf{x}) & = - \mu_2 \psi_2 (\mathbf{0}) \left( J_0'' (\sqrt{\mu_2} r) + \frac{1}{\sqrt{\mu_2} r} J_0' (\sqrt{\mu_2} r) \right) - \mu_2 \psi_2 (\mathbf{x}) \\
 & = \mu_2 \psi_2 (\mathbf{0}) J_0 (\sqrt{\mu_2} r) - \mu_2 \psi_2 (\mathbf{x}) \\
 & = \mu_2 w (\mathbf{x})
\end{split}
\end{align}
for $\mathbf{x} \in \Omega$. Moreover,
\begin{align*}
 w (\mathbf{0}) = \psi_2 (\mathbf{0}) J_0 (0) - \psi_2 (\mathbf{0}) = 0
\end{align*}
and
\begin{align*}
 \nabla w (\mathbf{0}) = \psi_2 (\mathbf{0}) \sqrt{\mu_2} J_0' (0) \frac{1}{r} \mathbf{x} |_{\mathbf{x} = \mathbf{0}} + \nabla \psi_2 (\mathbf{0}) = 0,
\end{align*}
as $\mathbf{x_0} = \mathbf{0}$ is a critical point of $\psi_2$. It is a consequence of the latter two identities together with \eqref{eq:Laplace} that $w$ is a solution to $- \Delta w = \mu_2 w$ that has a zero of order at least two at $\mathbf{x_0} = \mathbf{0}$. Hence, the nodal set $\{ \mathbf{x} \in \Omega : w (\mathbf{x}) = 0 \}$ of $w$ consists, in a neighborhood of $\mathbf{x_0} = \mathbf{0}$, of at least four branches meeting at $\mathbf{0}$; see, e.g., \cite[Proposition 2.1]{M09} for details and references. Note further that by Lemma \ref{lem:nodal} $w$ has no interior nodal domain. Combining these observations implies that $w$ has at least four distinct nodal domains whose boundary contains $\mathbf{x_0} = \mathbf{0}$ and that $w$ is positive on at least two such nodal domains, which we call $\Omega_1^+$ and $\Omega_2^+$; see Figure \ref{fig:nodal}.
\begin{figure}[h!]
\begin{tikzpicture}[scale=0.8]
% domain
 \draw[looseness=0.75,thick] (-3,0) arc (180:360:2) to[out=90,in=0] (0,2) to[out=180,in=90] (-3,0) -- cycle;
% origin
 \draw[black,fill=black] (-0.5,0) circle(0.05) node[right,black]{$\mathbf{0}$};
% nodal curves
 \draw[thick] plot[smooth] coordinates {(-2.5,-1.3) (-1.5,-0.3) (-0.5,0) (-0.3,1) (0,2) };
 \draw[thick] plot[smooth] coordinates {(-2,1.35) (-1,0.4) (-0.5,0) (0.2,-1) (0.5,-1.35) };
% subdomains
 \draw[white] (-0.2,0.7) circle(0.05) node[right,black]{$\Omega_1^+$};
