\end{tikzpicture}
\caption{Typical structure of the nodal lines of $w$ in $\Omega$; $w$ is positive on both $\Omega_1^+$ and $\Omega_2^+$.}
\label{fig:nodal}
\end{figure}

Note that for almost all $\mathbf{x} = (r \cos \theta, r \sin \theta) \in \partial \Omega$, the normal derivative $\partial_\nu w = \nabla w \cdot \nu$ satisfies
\begin{align}\label{eq:normalDerivative}
 (\partial_\nu w) (\mathbf{x}) = \psi_2 (\mathbf{0}) \sqrt{\mu_2} J_0' (\sqrt{\mu_2} r) \frac{1}{r} \mathbf{x} \cdot \nu.
\end{align}
Furthermore, using the spectral bound \eqref{eq:Kroger} and the assumption \eqref{eq:contradiction} we get for $\mathbf{x} = (r \cos \theta, r \sin \theta) \in \partial \Omega$
\begin{align*}
 \sqrt{\mu_2} r \leq \sqrt{\mu_2} \sup_{\mathbf{y} \in \partial \Omega} |\mathbf{y}| \leq \frac{2 j_0}{\diam (\Omega)} \frac{j_1}{2 j_0} \diam (\Omega) = j_1,
\end{align*}
and since $J_0' (x) < 0$ for all $x \in (0, j_1)$ it follows $J_0' (\sqrt{\mu_2} r) \leq 0$ if $\mathbf{x} \in \partial \Omega$. Moreover, the convexity of $\Omega$ implies $\mathbf{x} \cdot \nu > 0$ for all $\mathbf{x} \in \partial \Omega$. Especially, \eqref{eq:normalDerivative} gives
\begin{align*}
 (\partial_\nu w) (\mathbf{x}) \leq 0 \quad \text{for all}~\mathbf{x} \in \partial \Omega.
\end{align*}
Now, as $\varphi_j := w |_{\Omega_j^+}$ is non-negative and vanishes on $\partial \Omega_j^+ \setminus \partial \Omega$, $j = 1, 2$, we have
\begin{align}\label{eq:yeah}
 \int_{\Omega_j^+} |\nabla \varphi_j|^2 = \mu_2 \int_{\Omega_j^+} |\varphi_j|^2 + \int_{\partial \Omega_j^+} w \partial_\nu w \leq \mu_2 \int_{\Omega_j^+} |\varphi_j|^2, \quad j = 1, 2.
\end{align}
Let $\widetilde \varphi_j \in H^1 (\Omega)$ denote the extension by zero of $\varphi_j$ to all of $\Omega$, $j = 1, 2$, and let $u := \alpha_1 \widetilde \varphi_1 + \alpha_2 \widetilde \varphi_2$, where $\alpha_1, \alpha_2 \in \R$ are chosen such that $\int_\Omega u = 0$. As $u$ vanishes identically on $\Omega \setminus (\Omega_1^+ \cup \Omega_2^+)$, it is not an eigenfunction of the Neumann Laplacian on $\Omega$ and, hence,
\begin{align}\label{eq:amazing}
\begin{split}
 \mu_2 \int_\Omega |u|^2 & < \int_\Omega |\nabla u|^2 = \alpha_1^2 \int_{\Omega_1^+} |\nabla \varphi_1|^2 + \alpha_2^2 \int_{\Omega_2^+} |\nabla \varphi_2|^2 \\
 & \leq \mu_2 \left( \alpha_1^2 \int_{\Omega_1^+} |\varphi_1|^2 + \alpha_2^2 \int_{\Omega_2^+} |\varphi_2|^2 \right),
\end{split}
\end{align}
by \eqref{eq:yeah} and the fact that $\varphi_1, \varphi_2$ have disjoint supports. On the other hand, the left-hand side of \eqref{eq:amazing} equals
\begin{align*}
 \mu_2 \int_\Omega |u|^2 = \mu_2 \left( \alpha_1^2 \int_{\Omega_1^+} |\varphi_1|^2 + \alpha_2^2 \int_{\Omega_2^+} |\varphi_2|^2 \right),
\end{align*}
leading \eqref{eq:amazing} to a contradiction. This completes the proof.
\end{proof}


\begin{remark}
The essentially same proof also leads to the following result: if $\Omega \subset \R^2$ is a convex, bounded open set such that 
\begin{align}\label{eq:strongKroger}
 \mu_2 \leq \frac{j_1^2}{\diam (\Omega)^2}
\end{align}
holds, then $\psi_2$ has no critical points in $\Omega$ and, in particular, the hot spots conjecture is true for $\Omega$. The condition \eqref{eq:strongKroger} is satisfied for certain convex domains. For instance, the Payne--Weinberger inequality \cite{PW60} asserts that the sharp inequality
\begin{align*}
 \mu_2 \geq \frac{\pi^2}{\diam (\Omega)}
\end{align*}
holds for any convex domain, with equality in the limit when $\Omega$ degenerates to a one-dimensional interval. Since $\frac{j_1}{\pi} \approx 1.2197$, \eqref{eq:strongKroger} is satisfied when $\Omega$ is a convex domain sufficiently close to an interval.
\end{remark}


