\section{Introduction}

Decomposition of a complete graph into small cliques is a well-studied problem. Due to degree and size restraints, such decompositions do not always exist, in which case we often choose to study the covering of the complete graph by these cliques instead. In a graph covering, the edges that are covered more than once form the \emph{excess} of this covering. We are particularly interested in covering a complete graph with smallest possible size of excess, while minimising the number of subgraphs used in the covering. 
The motivation comes from parallel computing, when decomposing large dense matrices to several cores with no shared memory.

In \cite{Kovar2025}, we have determined the minimum $\{K_3,K_4\}$-covering of $K_v$ with minimum excess for any $v\ge 3$, with the exception of $v\in \{18,19\}$. More specifically, the minimum size of excess in a $\{K_3,K_4\}$-covering of $K_v$, denoted by $\xi_{3,4}(v)$, is given by the following result. 

\begin{proposition}[\cite{Kovar2025}]\label{prop:k3k4cover}
	In a $\{K_3,K_4\}$-covering of $K_v$, 
	\begin{align*}
		\xi_{3,4}(v)=\begin{cases}
			0,\ &\text{if}\ v\equiv 0,1\pmod{3} \ \text{and}\ v\neq 6;\\
			2,\ &\text{if}\ v\equiv 2\pmod{3};\\
			3,\ &\text{if}\ v=6.
		\end{cases}
	\end{align*}
\end{proposition}
Moreover, the minimum number of covering graphs in a $\{K_3,K_4\}$-covering of $K_v$ with minimum excess, denoted by $C^\xi(v,\{3,4\},2)$, is given by the following result.

\begin{theorem}[\cite{Kovar2025}]\label{thm:mink3k4cover}
	In a $\{K_3,K_4\}$-covering of $K_v$ with minimum excess, 
	\begin{align*}
		C^\xi(v,\{3,4\},2) = \begin{cases}
			\frac{v^2-v}{12},\ &\text{if}\ v\equiv 1,4\pmod{12};\\
			\frac{v^2-v+42}{12} = \left\lceil \frac{v^2-v}{12} \right\rceil +3,\ &\text{if}\ v\equiv 7,10\pmod{12} \ \text{and}\ v\notin\{10,19\};\\
			\frac{v^2+v}{12}, \ &\text{if}\ v\equiv 0,3\pmod{12};\\
			\frac{v^2+v+6}{12} = \left\lceil \frac{v^2+v}{12} \right\rceil, \ &\text{if}\ v\equiv 6,9\pmod{12} \ \text{and}\ v\ge 21;\\
			\frac{v^2+3v-4}{12},\ &\text{if}\ v\equiv 5,8\pmod{12};\\
			\frac{v^2+3v+2}{12} = \left\lceil\frac{v^2+3v-4}{12} \right\rceil, \ &\text{if}\ v\equiv 2,11\pmod{12}; \\
			3,\ &\text{if}\ v=6;\\
			12,\ &\text{if}\ v\in\{9,10\};\\
			33,\ &\text{if}\ v=18;\\
			35,\ &\text{if}\ v=19.
		\end{cases}
	\end{align*}
\end{theorem}

The results for $K_{18}$ and $K_{19}$ were in fact solved during previous studies (\cite{Stanton1988}, \cite{Gruettmueller2006}) on the decomposition of $K_v$ into copies of $K_2$, $K_3$ and $K_4$. In the following, we provide a different approach to these two cases, featuring a combination of graph-theoretic analysis and brute-force searches. 

Integer linear programming (ILP) is frequently used to exclude some possible designs or to find an example. All ILP searches were implemented using Gurobi Optimizer (See \cite{GurobiOptimization2023}), version 11.0.2. An example algorithm is given in Listing \ref{src:gurobi-ilp}. 

The following theorem on graph sequences is also useful. 
\begin{theorem}[\cite{Erdoes1960}]\label{thm:erdos-gallai}
	A sequence of non-negative integers $d_1\ge\cdots\ge d_n$ can be realised as the degree sequence of a simple graph of order $n$ if and only if 
	\begin{itemize}
		\item $\sum_{i=1}^n d_i\equiv 0\pmod{2}$;
		\item for any $1\le k\le n$, 
		\begin{align*}
			\sum_{i=1}^k d_i \le k(k-1) + \sum_{i=k+1}^n \min\{d_i,k\}.
		\end{align*}
	\end{itemize}
\end{theorem}

We will make use of this famous result on pairwise balanced designs (PBD) as well. 
\begin{theorem}[\cite{rees-1989}]\label{thm:pbd4}
	A PBD$(v,\{4,w^*\},1)$ with $v>w>0$ exists, if and only if $v\ge 3w+1$, and 
	\begin{itemize}
			\item $v\equiv 1,4\pmod{12}$, $w\equiv 1,4\pmod{12}$, or
			\item $v\equiv 7,10\pmod{12}$, $w\equiv 7,10\pmod{12}$.
		\end{itemize}
\end{theorem}


\section{Main results}

According to Proposition \ref{prop:k3k4cover}, the minimum excess is empty for $\{K_3,K_4\}$-coverings of $K_{18}$ and $K_{19}$. Therefore, in the following, we simply refer to the minimum covering with minimum excess as the \emph{optimal decomposition} for these two cases, and denote by $D(v,\{3,4\})$ the minimum number of subgraphs in a $\{K_3,K_4\}$-decomposition of $K_v$, where $v\in\{18,19\}$. 

\begin{theorem}
	The optimal $\{K_3,K_4\}$-decomposition of $K_{18}$ contains 15 $K_3$'s and 18 $K_4$'s, i.e. $D(18,\{3,4\})=33$.
\end{theorem}

\begin{theorem}
	The optimal $\{K_3,K_4\}$-decomposition of $K_{19}$ contains 13 $K_3$'s and 22 $K_4$'s, i.e. $D(19,\{3,4\})=35$.
\end{theorem}


\section{Proof of results}

We always denote by $\alpha$ and $\beta$ the number of $K_3$'s and $K_4$'s, respectively, in a $\{K_3,K_4\}$-decomposition of the complete graph $K_v$. In addition, we denote by $\alpha_x$ and $\beta_x$ the number of $K_3$'s and $K_4$'s, respectively, that contain a~certain vertex $x\in V(K_v)$ in such a decomposition. Counting the edges in a decomposition yields
\begin{align*}
	3\alpha + 6\beta = {v\choose 2},
\end{align*}
so 
\begin{align*}
	\alpha + \beta = \frac{1}{6}\left(\frac{v(v-1)}{2} + 3\alpha\right),
\end{align*}
from which it is obvious that in such a decomposition, minimising $\alpha+\beta$ is equivalent to minimising $\alpha$. 

The following lower bounds for covering numbers will be useful. 

\begin{lemma}[\cite{Kovar2025}, Lemma 33]\label{lem:lb-v6v9}
	When $v\equiv 6,9\pmod{12}$ and $v\neq 6$, 
	\begin{align*}
		C^\xi(v,\{3,4\},2)\ge \left\lceil \frac{v^2+v}{12}\right\rceil = \frac{v^2+v+6}{12}.
	\end{align*}
	In particular, $D(18,\{3,4\})\ge 29$, or equivalently, $\alpha\ge 7$. 
\end{lemma}

\begin{lemma}[\cite{Kovar2025}, Lemma 30]\label{lem:lb-v7v10}
	When $v\equiv 7,10\pmod{12}$, 
	\begin{align*}
		C^\xi(v,\{3,4\},2)\ge \left\lceil \frac{v^2-v}{12}\right\rceil +3 = \frac{v^2-v+42}{12}.
	\end{align*}
	In particular, $D(19,\{3,4\})\ge 32$, or equivalently, $\alpha\ge 7$. 
\end{lemma}


\subsection{Optimal decomposition of $K_{18}$}

\begin{lemma}\label{lem:alphax-k18}
	For any vertex $x$ of $K_{18}$, $\alpha_x\equiv 1\pmod{3}$.
\end{lemma}
\begin{proof}
	By counting the degree of $x$, 
	$$2\alpha_x+3\beta_x=18-1=17\equiv 2\pmod{3},$$
	so $\alpha_x\equiv 1\pmod{3}$. 
\end{proof}

We first present the upper bound. 

\begin{lemma}\label{lem:k18sol}
		$D(18,\{3,4\})\le 33$, or equivalently, $\alpha\le 15$.
\end{lemma}
