\begin{proof}
	According to Lemma \ref{lem:k18alphage9}, it suffices to show that $D(18, \{3,4\})\neq 30$, which is equivalent to $\alpha\neq 9$. 

	For contradiction, assume there is a $\{K_3,K_4\}$-decomposition of $K_{18}$ with 9 $K_3$'s (and thus 21 $K_4$'s). For any vertex $x$ of $K_{18}$, we know $\alpha_x\in \{1,4,7\}$ from Lemma \ref{lem:alphax-k18}, just as in the proof of Lemma \ref{lem:k18alphage9}. 

	If there is some vertex $u$ with $\alpha_u=7$, by counting the total number of triples as in \eqref{eq:k18counttriples}, we deduce that there must be some vertex $u'\neq u$ with $\alpha_{u'}=4$, and then any of the remaining vertices $x$ has $\alpha_x=1$. 
	\begin{itemize}
		\item If $u$ and $u'$ belong to a common triple, then the total number of vertices satisfies $v\ge 1 + 7\cdot 2 + (4-1)\cdot 2 = 21$, a contradiction!
		\item If $u$ and $u'$ do not share a common triple, then the total number of vertices satisfies $v\ge 1+7\cdot 2 + 1+4\cdot 2 = 24$, a contradiction!
	\end{itemize}
	Therefore, for any vertex $x$ in $K_{18}$, we have $\alpha_x\in \{1,4\}$. And from the total number of triples it is easy to deduce that there must be 3 vertices $u_1$, $u_2$, $u_3$ with $\alpha_{u_1}=\alpha_{u_2}=\alpha_{u_3}=4$, and any of the other vertices $x$ has $\alpha_x=1$. 
	\begin{itemize}
		\item If $\{u_1,u_2,u_3\}$ is a triple in the decomposition, then the total number of vertices satisfies $v\ge 3 + 3\cdot (4-1)\cdot 2 = 21$, a contradiction!
		\item If $\{u_1,u_2,u_3\}$ is not a triple in the decomposition, then the total number of vertices satisfies $v\ge 3 + 3 + 6\cdot 2 = 18$, and the equality holds if and only if any two of the three vertices ${u_1,u_2,u_3}$ share a triple, as illustrated in Figure \ref{fig:k18alpha9case}. After removing the 9 triangles from $K_{18}$ in Figure \ref{fig:k18alpha9case}, an ILP search shows that the remaining subgraph can not be decomposed into $K_4$'s. 
	\end{itemize}
	Therefore, $\alpha\neq 9$. 
\end{proof}

\begin{lemma}\label{lem:k18alphax1or4}
	In a $\{K_3,K_4\}$-decomposition of $K_{18}$, if $\alpha=11$, then for any element $x$, $\alpha_x\in \{1,4\}$.
\end{lemma}
\begin{proof}
	Suppose that a $\{K_3,K_4\}$-decomposition of $K_{18}$ exists with $\alpha=11$. For any vertex $x$ of $K_{18}$, we know $\alpha_x\in \{1,4,7\}$ from Lemma \ref{lem:alphax-k18}.

	If there is some vertex $u$ with $\alpha_u=7$, by counting the total number of triples as in \eqref{eq:k18counttriples}, we deduce that there are two cases.
	\begin{itemize}
		\item Two vertices $u,u'$ with $\alpha_u=\alpha_{u'}=7$, another vertex $w$ with $\alpha_w=4$ and the remaining 15 vertices are in 1 triple each. Then both $u$ and $u'$ have at least 14 neighbours that are covered by triples with $u$ and $u'$, respectively. So at least $2\cdot 14-18=10$ vertices among them overlap. However, there are only three vertices $u$, $u'$ and $w$ that are contained in more than one triple. A contradicion! 
		\item One vertex $u$ with $\alpha_u=7$, another three vertices $w_1,w_2,w_3$ with $\alpha_{w_i}=4$ for $i\in\{1,2,3\}$, and the remaining 14 vertices are in 1 triple each. Then $u$ has 14 neighbours that are covered by triples, and we denote by $x,y,z$ the three vertices in $K_{18}$ that are not contained in a common triple with $u$. 
		Suppose $\{w_1,w_2,w_3\}=\{x,y,z\}$, then the remaining $11-7=4$ triples need to be formed in the $K_3$-subgraph on the vertices $w_1,w_2,w_3$, which is impossible due to insufficient edges. Therefore, at least one of $w_1,w_2,w_3$ must be among the 14 neighbours of $u$ that share a triple with $u$. Without loss of generality, we assume $w_1$ and $u$ are contained commonly in a triple. Then there are three more triples containing $w_1$, which means $w_1$ has 6 more neighbours that share a triple with $w_1$. However, there are at most 5 candidate vertices to form a new triple, namely $w_2$, $w_3$, $x$, $y$ and $z$. A contradiction!
		%old:If $w_i\in\{x,y,z\}$ for some $i\in\{1,2,3\}$, without loss of generality we may assume $w_1=x$, then to form 4 triples containing $w_1$, 8 vertices are needed. However, the candidate vertices are only 4: $w_2,w_3,y,z$. Therefore, all of $w_1$, $w_2$ and $w_3$ must share a triple with $u$. In particular, $w_1$ is contained in 3 more triples other than the one containing $u$, for which 6 vertices are needed. However, the candidate vertices are only 5: $w_2,w_3,x,y,z$. A contradiction!
	\end{itemize}
	Therefore, for any vertex $x$, $\alpha_x\in \{1,4\}$. 
\end{proof}

\begin{lemma}\label{lem:k18w3}
	In a $\{K_3,K_4\}$-decomposition of $K_{18}$, if $\alpha=11$, then there must be a triple $\{w_1,w_2,w_3\}$ in the covering satisfying $\alpha_{w_1}=\alpha_{w_2}=\alpha_{w_3}=4$. 
\end{lemma}
\begin{proof}
	Suppose that a $\{K_3,K_4\}$-decomposition of $K_{18}$ exists with $\alpha=11$. For any vertex $x$ of $K_{18}$, we know from Lemma \ref{lem:k18alphax1or4} that $\alpha_x\in\{1,4\}$. By counting the total number of triples as in \eqref{eq:k18counttriples}, we deduce that there must be 5 vertices, denoted by $w_1$, $w_2$, $w_3$, $w_4$ and $w_5$, satisfying $\alpha_{w_i}=4$ for $i\in\{1,2,3,4,5\}$, and the remaining 13 vertices are only in 1 triple each. 

	Assume that no 3 of the 5 vertices $w_1,w_2,w_3,w_4,w_5$ share a triple, and suppose that $t$ pairs between these 5 vertices share a triple. We clearly have $0\le t\le {5\choose 2}=10$. Since each triple that contains 2 vertices among $w_1,w_2,w_3,w_4,w_5$ requires an additional vertex, and each triple containing only 1 vertex among $w_1,w_2,w_3,w_4,w_5$ requires 2 additional vertices, we have
	\begin{align*}
		5+t+2\cdot(10-t)\cdot 2\le 18,
	\end{align*}
	whence $t\ge 9$. Thus, $t\in \{9,10\}$. So there are two cases:
	\begin{itemize}
		\item each pair between the vertices $w_1,w_2,w_3,w_4,w_5$ shares a triple, and there is an independent triple $\{x,y,z\}$ with $\alpha_x=\alpha_y=\alpha_z=1$;
		\item each pair between the vertices $w_1,w_2,w_3,w_4,w_5$, except one, shares a triple, and without loss of generality we assume $w_1$ and $w_2$ do not share a triple, so there are two more triples $\{w_1,x_1,y_1\}$ and $\{w_2,x_2,y_2\}$, satisfying $\alpha_{x_i}=\alpha_{y_i}=1$ for $i\in\{1,2\}$. 
	\end{itemize}
	Both cases above are excluded by ILP search. Therefore, there must be 3 of the 5 vertices $w_1,w_2,w_3,w_4,w_5$ that share a triple, which we assume, without loss of generality, to be $\{w_1,w_2,w_3\}$. 
\end{proof}

\begin{lemma}\label{lem:k18alphage13}
	$D(18,\{3,4\})\ge 32$, or equivalently, $\alpha\ge 13$.
\end{lemma}
\begin{proof}
	By Lemma \ref{lem:k18alphage11}, it suffices to show that $D(18,\{3,4\})\neq 31$, which is equivalent to $\alpha\neq 11$. 

	For contradiction, assume there is a $\{K_3,K_4\}$-decomposition of $K_{18}$ with 11 $K_{3}$'s (and thus with 20 $K_4$'s). By the proof of Lemma \ref{lem:k18w3}, there must be 5 vertices $w_1,w_2,w_3,w_4,w_5$ satisfying $\alpha_{w_i}=4$ for $i\in\{1,2,3,4,5\}$ and the remaining 13 vertices are only in 1 triple each, and moreover there must be a triple among $w_1,w_2,w_3,w_4,w_5$. Without loss of generality, we assume that there is triple $T=\{w_1,w_2,w_3\}$. Denote by $N_i$ the subset of $V(K_{18})\setminus T$ consisting of the vertices that share a triple with $w_i$, for $i\in \{1,2,3\}$. Since each of $w_4$ and $w_5$ is in at least one triple that does not contain any vertex of $T$, and at least one neighbour of $w_4$ and $w_5$ is not in $N_1\cup N_2\cup N_3$, we have
	\begin{align*}
		|N_1\cup N_2\cup N_3|\le 18-3-1=14.
	\end{align*}
	Meanwhile, the inclusion-exclusion principle gives
	\begin{align*}
		|N_1\cup N_2\cup N_3| = 3\cdot 6 - \sum_{1\le i<j\le 3}|N_i\cap N_j| + |N_1\cap N_2\cap N_3|,
	\end{align*}
	since $|N_1|=|N_2|=|N_3|=6$. We thus deduce
	\begin{align}\label{eq:k18n3}
		|N_1\cap N_2|+|N_1\cap N_3|+|N_2\cap N_3|-|N_1\cap N_2\cap N_3|\ge 4.
	\end{align}
	Notice that for any pair $i,j$ satisfying $1\le i<j\le 3$, $N_i\cap N_j\subseteq \{w_4,w_5\}$ holds. We claim that 
	\begin{align*}
		N_1\cap N_2\cap N_3 = \{w_4,w_5\}.
	\end{align*}


	We prove the claim in four steps.
	\begin{enumerate}
		\item First suppose there is some $N_i$ that does not contain either $w_4$ or $w_5$, where $i\in\{1,2,3\}$. Without loss of generality, we may assume $i=1$, and then $N_1\cap N_2=N_1\cap N_3=N_1\cap N_2\cap N_3=\emptyset$. Then \eqref{eq:k18n3} gives $|N_2\cap N_3|\ge 4$, which is impossible. So each $N_i$ contains either $w_4$ or $w_5$.
		\item\label{item:step2}%
                  Next, suppose there is some pair $i,j$ with $1\le i<j\le 3$ such that $N_i\cap N_j=\emptyset$. Without loss of generality, let $(i,j)=(1,2)$, and from the previous step we may assume $w_4\in N_1\setminus N_2$ and $w_5\in N_2\setminus N_1$. So $N_1\cap N_2\cap N_3=\emptyset$, and $|N_1\cap N_3|\le 1$, $|N_2\cap N_3|\le 1$. Then \eqref{eq:k18n3} gives
		\begin{align*}
			4\le |N_1\cap N_3|+|N_2\cap N_3|\le 1+1=2,
		\end{align*}
		a contradiction! So each pair among $N_i$'s intersects. 
		\item Then suppose $N_1\cap N_2\cap N_3=\emptyset$. Since 
		\begin{align*}
			N_1\cap N_2\cap N_3=(N_1\cap N_2)\cap (N_1\cap N_3),
		\end{align*}
		we may assume, without loss of generality, that $N_1\cap N_2=\{w_4\}$ and $N_1\cap N_3=\{w_5\}$, for they are both non-empty. So $w_4,w_5\in N_1$, $w_4\in N_2\setminus N_3$, and $w_5\in N_3\setminus N_2$. Therefore, $N_2\cap N_3=\emptyset$, which is a contradiction as has been shown in the step (\ref{item:step2}.)! We thus get $N_1\cap N_2\cap N_3\neq \emptyset$. 
		\item Finally, suppose there is some pair $i,j$ with $1\le i<j\le 3$ such that $|N_i\cap N_j|=1$. Without loss of generality, we assume $N_1\cap N_2 = \{w_4\}$ and $w_5\notin N_1$. So $N_1\cap N_3 = \{w_4\}$, and $N_1\cap N_2\cap N_3=\{w_4\}$. Therefore, the inequality \eqref{eq:k18n3} gives $|N_2\cap N_3|\ge 3$, which is impossible. So $N_1\cap N_2=N_1\cap N_3=N_2\cap N_3=\{w_4,w_5\}$, and thus $N_1\cap N_2\cap N_3=\{w_4,w_5\}$. 
	\end{enumerate}
