\begin{lemma}\label{lem:k18alphax1or4-13}
	In a $\{K_3,K_4\}$-decomposition of $K_{18}$, if $\alpha=13$, then for any element $x$, $\alpha_x\in \{1,4\}$.
\end{lemma}
\begin{proof}
	Suppose that a $\{K_3,K_4\}$-decomposition of $K_{18}$ exists with $\alpha=13$. For any vertex $x$ of $K_{18}$, from Lemma \ref{lem:alphax-k18} we know the number $\alpha_x$ of triples containing $x$ satisfies $\alpha_x\in \{1,4,7\}$.

	If there is some vertex $u$ with $\alpha_u=7$, by counting the total number of triples as in \eqref{eq:k18counttriples}, we deduce that there are three cases.
        Each of them we show to be impossible.
	\begin{itemize}
		\item Three vertices $u_1,u_2,u_3$ with $\alpha_{u_i}=7$ for $i\in\{1,2,3\}$, another vertex $w$ with $\alpha_w=4$ and the remaining 14 vertices only in 1 triple each. In particular, both $u_1$ and $u_2$ have 14 neighbours covered by triples with $u_1$ and $u_2$, respectively, so at least $2\cdot 14-18=10$ vertices among them overlap. But there are only four vertices $u_1,u_2,u_3$ and $w$ that are contained in more than one triple. A contradiction!
		\item Two vertices $u_1, u_2$ with $\alpha_{u_1}=\alpha_{u_2}=7$, another three vertices $w_1,w_2,w_3$ with $\alpha_{w_i}=4$ for $i\in\{1,2,3\}$, and the remaining 13 vertices are only in 1 triple each. Then both $u_1$ and $u_2$ have 14 neighbours covered by triples with $u_1$ and $u_2$, respectively, so at least $2\cdot 14-18=10$ vertices among them overlap. But there are only five vertices $u_1,u_2,w_1,w_2,w_3$ that are contained in more than one triple. A contradiction!
		\item One vertex $u$ with $\alpha_u=7$, another five vertices $w_1,w_2,w_3,w_4,w_5$ with $\alpha_{w_i}=4$ for $i\in\{1,2,3,4,5\}$ and the remaining 12 vertices are only in 1 triple each. Then $\beta_u=(17-2 \alpha_u)/3=1$, and we assume the unique quadruple containing $u$ is $\{u,x,y,z\}$. If $w_i\in\{x,y,z\}$ for some $i\in\{1,2,3,4,5\}$, without loss of generality we may assume $w_1=x$, then to form 4 triples containing $w_1$, 8 vertices are needed, but only 6 are available: $w_2,w_3,w_4,w_5,y,z$. Therefore, each $w_i$ shares a triple with $u$ for $i\in\{1,2,3,4,5\}$. It is now necessary to form the remaining $13-7=6$ triples in the $K_8$-subgraph on $w_1,w_2,w_3,w_4,w_5,x,y,z$. The union of the 6 triangles should be a subgraph the $K_8$, with degree sequence $(6,6,6,6,6,2,2,2)$. The sequence is not graphic, since summing the first five numbers in the sequence, we get 
		\begin{align*}
			6+6+6+6+6 > 5(5-1)+2+2+2,
		\end{align*}
		which violates Theorem \ref{thm:erdos-gallai}!
	\end{itemize}
	Therefore, $\alpha_x\in\{1,4\}$ for each vertex $x$. 
\end{proof}

\begin{lemma}\label{lem:k18k3k4alpha13cases}
	In a $\{K_3,K_4\}$-decomposition of $K_{18}$, if $\alpha=13$, then there are 7 vertices $w_1,w_2,\cdots,w_7$ such that $\alpha_{w_i}=4$ for $i\in\{1,2,\cdots,7\}$, and there are at least two triples among the 7 vertices in the covering. 
\end{lemma}
\begin{proof}
	Suppose that a $\{K_3,K_4\}$-decomposition of $K_{18}$ exists with $\alpha=13$. By Lemma \ref{lem:k18alphax1or4-13}, each vertex is in one or four triples. By counting the total number of triples as in \eqref{eq:k18counttriples}, we deduce that there are 7 vertices $w_1,w_2,\cdots,w_7$ each in 4 triples, and the remaining 11 vertices $y_1,y_2,\cdots,y_{11}$ are only in 1 triple each. 

	Denote by $t_i$ the number of triples in the decomposition with $i$ vertices among $w_1,w_2,\cdots,w_7$ and $3-i$ vertices among $y_1,y_2,\cdots,y_{11}$, for $i\in\{0,1,2,3\}$. Clearly, the integers $t_i$ satisfy:
	\begin{align*}
		t_0+t_1+t_2+t_3&=13,\\
		3t_3+2t_2+t_1&=\sum_{i=1}^7 \alpha_{w_i} = 28,\\
		3t_0+2t_1+t_2&=\sum_{j=1}^{11} \alpha_{y_j} = 11,\\
		t_0&\le \left\lfloor \frac{11}{3}\right\rfloor = 3,\\
		t_1&\le \left\lfloor \frac{11}{2}\right\rfloor = 5,\\
		t_2&\le 11,\\
		t_3&\le D(7,3,2) = 7,\\
		t_2+3t_3&\le e(K_7) = 21,\\
		t_0,t_1,t_2,t_3&\ge 0.
	\end{align*}
	Solving the constraints above, we get 7 possible solutions:
	\begin{align*}
		(t_0,t_1,t_2,t_3)&=(0,4,3,6)\label{eq:c1} \tag{C1},\\
		(t_0,t_1,t_2,t_3)&=(1,1,6,5)\label{eq:c2} \tag{C2},\\
		(t_0,t_1,t_2,t_3)&=(0,3,5,5)\label{eq:c3} \tag{C3},\\
		(t_0,t_1,t_2,t_3)&=(1,0,8,4)\label{eq:c4} \tag{C4},\\
		(t_0,t_1,t_2,t_3)&=(0,2,7,4)\label{eq:c5} \tag{C5},\\
		(t_0,t_1,t_2,t_3)&=(0,1,9,3)\label{eq:c6} \tag{C6},\\
		(t_0,t_1,t_2,t_3)&=(0,0,11,2)\label{eq:c7} \tag{C7}.
	\end{align*}
	In particular, $t_3\ge 2$ as desired. 
\end{proof}

From now on, we consider a decomposition of $K_{18}$ into 13 $K_3$'s and 19 $K_4$'s, where 7 vertices $w_1,\cdots,w_7$ are each in 4 triples and the remaining 11 vertices $y_1,\cdots,y_{11}$ are each in 1 triple only. We shall deal with the cases \eqref{eq:c1}--\eqref{eq:c7} in the proof of Lemma \ref{lem:k18k3k4alpha13cases} one by one and show none is feasible. 

\begin{lemma}\label{lem:k18a13c1}
	In a $\{K_3,K_4\}$-decomposition of $K_{18}$, if $\alpha=13$, then the case \eqref{eq:c1} is impossible.
\end{lemma}
