\begin{proof}
For contradiction suppose the case \eqref{eq:c7} is possible. Then there are $t_3=2$ triples among $w_1,\cdots,w_7$. The two triples can either be independent or share a vertex. We then need to pick 11 edges among $w_1,\cdots,w_7$ to determine all the triples. 

	First assume that the two triples among $w_1,\cdots,w_7$ are independent, and without loss of generality let them be $T_1=\{w_1,w_2,w_3\}$ and $T_2=\{w_4, w_5, w_6\}$. Among the 11 edges to be picked, 4 are incident to $w_7$ and the remaining 7 go between vertices in~$T_1$ and $T_2$. We therefore deduce that the 4 edges incident to $w_7$ must be picked in a balanced way between $T_1$ and $T_2$. Without loss of generality, let the triples containing $w_7$ be $T_3=\{w_1,w_7, y_1\}$, $T_4=\{w_2,w_7,y_2\}$, $T_5=\{w_4,w_7,y_3\}$ and $T_6=\{w_5,w_7,y_4\}$. Now that $w_3$ and $w_6$ each needs 3 more triples, we can take five more triples: $T_7=\{w_3,w_4,y_5\}$, $T_8=\{w_3,w_5,y_6\}$, $T_9=\{w_3,w_6,y_7\}$, $T_{10}=\{w_1,w_6,y_8\}$ and $T_{11}=\{w_2,w_6,y_9\}$. Since $w_1,w_2,w_4,w_5$ each needs 1 more triple, without loss of generality, the last two triples can be taken to be $T_{12}=\{w_1,w_4,y_{10}\}$ and $T_{13}=\{w_2,w_5,y_{11}\}$. We then exclude this configuration (See Figure \ref{fig:k18alpha13-2}) by an ILP search on the remaining edges. 

	Then assume that the two triples among $w_1,\cdots,w_7$ share a vertex, and without loss of generality let them be $T_1=\{w_1,w_2,w_3\}$ and $T_2=\{w_1,w_4,w_5\}$. Clearly, the other two triples containing $w_1$ can be taken to be $T_3=\{w_1,w_6,y_1\}$ and $T_4=\{w_1,w_7,y_2\}$. We distinguish two cases depending on whether $w_6$ and $w_7$ share a triple. 
	\begin{itemize}
		\item If $w_6$ and $w_7$ share a triple, we suppose, without loss of generality, that there is a triple $T_5=\{w_6,w_7,y_3\}$. Vertices $w_6$ and $w_7$ are each in 2 more triples, and these 4 triples must be distributed in a balanced way between $T_1$ and $T_2$. There are thus two possibilities up to isomorphism.
		\begin{enumerate}
			\item Each of $w_6$ and $w_7$ shares one triple with a vertex of $T_1$ and another with a vertex of $T_2$. Without loss of generality, we assume the triples to be $\{w_2,w_6,y_4\}$, $\{w_4,w_6,y_5\}$, $\{w_3,w_7,y_6\}$ and $\{w_5,w_7,y_7\}$. Then the remaining 4 triples are uniquely determined: $\{w_2,w_4,y_8\}$, $\{w_3,w_4,y_9\}$, $\{w_2,w_5,y_{10}\}$, $\{w_3, w_5,y_{11}\}$. We then exclude this configuration (See Figure \ref{fig:k18alpha13-3} left) by an ILP search.  
			\item Each of $w_6$ and $w_7$ only shares 2 triples with a vertex from one of $T_1$ and $T_2$. Without loss of generality, we assume the triples to be $\{w_2,w_6,y_4\}$, $\{w_3,w_6,y_5\}$, $\{w_4,w_7,y_6\}$, $\{w_5,w_7,y_7\}$. Then the remaining 4 triples are uniquely determined: $\{w_2,w_4,y_8\}$, $\{w_3,w_4,y_9\}$, $\{w_2,w_5,y_{10}\}$, $\{w_3, w_5,y_{11}\}$. We then exclude this configuration (See Figure \ref{fig:k18alpha13-3} right) by an ILP search.  
		\end{enumerate}
		\item If $w_6$ and $w_7$ do not share a triple, then each of them needs 3 more triples, and without loss of generality we may take $\{w_2,w_6,y_3\}$, $\{w_3,w_6,y_4\}$, $\{w_4,w_6,y_5\}$ and $\{w_2,w_7,y_6\}$, $\{w_4,w_7,y_7\}$, $\{w_5,w_7,y_8\}$. The remaining 3 triples are uniquely determined at this point: $\{w_2,w_5,y_9\}$, $\{w_3,w_4,y_{10}\}$ and $\{w_3,w_5,y_{11}\}$. We then exclude this configuration (See Figure \ref{fig:k18alpha13-4}) by an ILP search.  
	\end{itemize}
	In conclusion, the case \eqref{eq:c7} is impossible. 
\end{proof}

\begin{lemma}
	$D(18,\{3,4\})=33$, or equivalently, $\alpha=15$.
\end{lemma}
\begin{proof}
	According to Lemma \ref{lem:k18sol} and Lemma \ref{lem:k18alphage13}, it suffices to show that $D(18,\{3,4\})\neq 32$, or equivalently $\alpha\neq 13$. We have listed all possible cases \eqref{eq:c1}--\eqref{eq:c7} in the proof of Lemma \ref{lem:k18k3k4alpha13cases}, and have excluded all of them in Lemmas \ref{lem:k18a13c1}, \ref{lem:k18alpha13c2}, \ref{lem:k18a13c3}, \ref{lem:k18alpha13c4}, \ref{lem:k18a13c5-2}, \ref{lem:k18a13c6} and \ref{lem:k18a13c7}. Therefore, $\alpha\neq 13$ has been proven. 
\end{proof}



\subsection{Optimal decomposition of $K_{19}$}

%$K_{19}$ is an exceptional small graph for the case $v\equiv 7,10\pmod{12}$ in Theorem \ref{thm:mink3k4cover}. Above all, from Theorem \ref{thm:k3k4cover}, we know that $K_{19}$ can be decomposed into $K_3$'s and $K_4$'s. By Lemma \ref{lem:v7v10-k3k4-lb}, we also know that, the number $\alpha$ of triples in a $\{K_3,K_4\}$-decomposition of $K_{19}$ must satisfy $\alpha\ge 7$ (See \eqref{eq:alpha-ge-7}) and $\alpha\equiv 1\pmod{2}$ (See \eqref{eq:alpha-odd}). 

\begin{lemma}\label{lem:alphax-k19}
	In a $\{K_3,K_4\}$-decomposition of $K_{19}$, for any vertex $x$ in $K_{19}$, $\alpha_x\equiv 0\pmod{3}$.
\end{lemma}
\begin{proof}
	Counting the degree of $x$ gives 
	$$2\alpha_x+3\beta_x=19-1=18\equiv 0\pmod{3},$$
	so $\alpha_x\equiv 0\pmod{3}$.
\end{proof}

First, we provide an upper bound. 

\begin{lemma}\label{lem:v19alphale13}
	$D(18,\{3,4\})\le 35$, or equivalently, $\alpha\le 13$.
\end{lemma}
