Now we push the lower bound up similarly as in the previous part.

\begin{lemma}\label{lem:k19alphaneq7}
	$D(19,\{3,4\})\ge 33$, or equivalently, $\alpha\ge 9$.
\end{lemma}
\begin{proof}
	By Lemma \ref{lem:lb-v7v10}, it suffices to prove $D(19,\{3,4\})\neq 32$, which is equivalent to showing $\alpha\neq 7$. 

	For contradiction, assume there is a $\{K_3,K_4\}$-decomposition of $K_{19}$ with 7 $K_3$'s (and thus 25 $K_4$'s). For any vertex $x$ of $K_{19}$, we know $\alpha_x\equiv 0\pmod{3}$ by Lemma \ref{lem:alphax-k19}. If there were some vertex $u$ with $\alpha_u\ge 6$, then there would be at least 12 neighbours of $v$ which are each in at least 3 triples, hence the total number of triples would satisfy
	\begin{align*}
		\alpha\ge \frac{1\cdot 6 + 12\cdot 3}{3}=14,
	\end{align*}
	a contradiction with our assumption! Therefore, $\alpha_x\le 3$ for each vertex $x$ of the $K_{19}$, and thus there must be 7 vertices each in 3 triples. And by counting the degree of vertices, we see that the union of the 7 $K_3$'s make a $K_7$-subgraph of the $K_{19}$. In other words, such a $\{K_3,K_4\}$-decomposition of $K_{19}$ in fact gives a PBD$(19,\{4,7^*\},1)$. But such a design is known to be non-existent by Theorem \ref{thm:pbd4}. Therefore, $D(19,\{3,4\})\neq 32$. 
\end{proof}



\begin{lemma}\label{lem:v19alphage11}
	$D(19,\{3,4\})\ge 34$, or equivalently, $\alpha\ge 11$.
\end{lemma}
\begin{proof}
	According to Lemma \ref{lem:k19alphaneq7}, it suffices to show that $D(19, \{3,4\})\neq 33$, which is equivalent to $\alpha\neq 9$. 

	For contradiction, assume there is a $\{K_3,K_4\}$-decomposition of $K_{19}$ with 9 $K_3$'s (and thus 24 $K_4$'s). For any vertex $x$ of $K_{19}$, we know $\alpha_x\equiv 0\pmod{3}$ by Lemma \ref{lem:alphax-k19}, and we can deduce that $\alpha_x\le 3$ for any vertex $x$ just as in the proof of Lemma \ref{lem:k19alphaneq7}. Therefore, there must be 9 vertices each in 3 triples, and the remaining 10 vertices in $K_{19}$ are triple-free. Let $G$ be the $K_9$-subgraph of $K_{19}$ on the vertices that are contained in triples, and let $H$ be the subgraph of $G$ formed by taking the union of the 9 triangles. Clearly, $H$ is a 6-regular subgraph of order 9 in $G$, which implies that its complement $\overline{H}$ is a 2-regular subgraph of order 9 in $G$. Therefore, we can classify the shape of $\overline{H}$ up to isomorphism: 
	\begin{align*}
		\overline{H}\in \{C_9, C_6+C_3, C_5+C_4, 3C_3\}.
	\end{align*}
	All of the four cases of $\overline{H}$ were excluded by an ILP search. 
\end{proof}

\begin{lemma}
	$D(19,\{3,4\})= 35$, or equivalently, $\alpha= 13$.
\end{lemma}
\begin{proof}
	According to Lemma \ref{lem:v19alphale13} and Lemma \ref{lem:v19alphage11}, it suffices to show that $D(19, \{3,4\})\neq 34$, which is equivalent to $\alpha\neq 11$.

	For contradiction, assume there is a $\{K_3, K_4\}$-decomposition of $K_{19}$ with 11 $K_3$'s (and thus 23 $K_4$'s). For any vertex $x$ of $K_{19}$, we know $\alpha_x\equiv 0\pmod{3}$ by Lemma \ref{lem:alphax-k19}, and we can deduce that $\alpha_x\le 3$ for any vertex $x$ just as in the proof of Lemma \ref{lem:k19alphaneq7}. Therefore, there must be 11 vertices each in 3 triples, and the remaining 8 vertices in $K_{19}$ are triple-free. Let $G$ denote the $K_{11}$-subgraph of $K_{19}$ on the vertices contained in triples, and let $H$ denote the subgraph of $G$ formed by taking the union of the 11 triangles. Clearly, $H$ is a $6$-regular graph of $G$. Based on our assumption, the complement of $H$ in $K_{19}$, denoted by $\overline{H}$, should be decomposable into $K_4$'s. 

	Using \texttt{nauty}, a programme that computes the automorphism groups of a graph based on \cite{McKay2014}, we generate all of the 266 mutually non-isomorphic $6$-regular graphs (See Listing \ref{src:nauty-11-d6}) on 11 vertices, and one of them must be $H$. For each of the 266 graphs, we search for a $K_4$-decomposition of its complement in $K_{19}$ by an ILP search. It turns out that none of the 266 graphs meets our requirements. Therefore, $\alpha\neq 11$. 
\end{proof}

