		# First compute all blocks indexed by vertex...
		blocks = []
		for length in block_sizes:
			blocks.extend(graph.list_tuples(length))

		# Get the indices of edges as a dict...
		edge_indices = {}
		for i in range(graph.size):
			edge_indices[graph.edges[i]] = i + 1

		# Rewrite each block by edge and by edge index...
		subgraphs = []  # Collects blocks indexed by edge index
		for block in blocks:
			block_by_edge = sub_tuples_of_length(block, 2)
			block_by_edge_index = [edge_indices[e] for e in block_by_edge]
			subgraphs.append(block_by_edge_index)  
		return blocks, subgraphs


	def _incidence(edges, blocks_by_edge_index):
		matrix = np.zeros((len(edges), len(blocks_by_edge_index)), int)
		for i, b in enumerate(blocks_by_edge_index):
			for e in b:
				matrix[edges.index(e), i] = 1
		return matrix


	def gurobi_linear(order, block_sizes, removed=None, excess=None):
