			subgraphs_new = [subgraphs[i] for i in range(len(subgraphs)) if i not in block_indices_to_remove]
			subgraphs = subgraphs_new

			blocks_new = [blocks[i] for i in range(len(blocks)) if i not in block_indices_to_remove]   
			blocks = blocks_new

		incidence = _incidence(edges, subgraphs)

		multiplicity = np.ones((len(edges), 1), int)

	if excess:
		print('Multiplying excess edges...')
		# Required: input edge (v1, v2) with v1 < v2
		for edge, mult in excess:
			col = kn.edges.index(edge) + 1
