	print('----------GUROBI----------')
	with gp.Env(params=options) as env, gp.Model(env=env) as m:
		x = m.addMVar((len(subgraphs), 1), lb=0, ub=1, vtype=gp.GRB.BINARY, name='subgraphs')  # switch variable type
		m.addConstr(incidence @ x == multiplicity)  # == for exact cover, otherwise >=
		matrix_ones = np.ones((1, len(subgraphs)), int)
		m.setObjective(matrix_ones @ x, gp.GRB.MINIMIZE)

		m.update()
		m.optimize()
		print('>>>Retrieving status of optimization...')
		if m.Status == 11:
			print('>>>Optimization interrupted by user.')
			solution = []
			for i in range(len(subgraphs)):
				if x[i].x >= 0.9:
					solution.append(blocks[i])
			print(solution)
			return solution
		elif m.Status == 2:
			print('>>>Optimal solution found. Printing...')
			solution = []
			for i in range(len(subgraphs)):
				if x[i].x >= 0.9:
					solution.append(blocks[i])
			print(solution)
			return solution
		elif m.Status == 3:
			print('>>>Model is infeasible.')
			return
\end{lstlisting}

